module csa_budget_acc (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [1:0] inc,
    output wire [8:0] o_total,
    output wire       o_full
);
    // accumulator kept in carry-save form: the two halves always sum to the
    // true running total, and at most 10 increments of at most 3 are consumed
    reg [7:0] sum_h;
    reg [7:0] car_h;
    reg [3:0] n;

    initial sum_h = 8'd0;
    initial car_h = 8'd0;
    initial n     = 4'd0;

    wire [7:0] x       = {6'd0, inc};
    wire [7:0] nxt_sum = sum_h ^ car_h ^ x;
    wire [7:0] maj     = (sum_h & car_h) | (sum_h & x) | (car_h & x);
    wire [7:0] nxt_car = {maj[6:0], 1'b0};

    wire budget = (n < 4'd10);

    always @(posedge clk) begin
        if (rst) begin
            sum_h <= 8'd0;
            car_h <= 8'd0;
            n     <= 4'd0;
        end else if (ce && budget) begin
            sum_h <= nxt_sum;
            car_h <= nxt_car;
            n     <= n + 4'd1;
        end
    end

    // the true total is the sum of the two carry-save halves
    wire [8:0] total = {1'b0, sum_h} + {1'b0, car_h};

    assign o_total = total;
    assign o_full  = ~budget;

    // bounded existence: the accumulated total never exceeds 30,
    // far below what the 9-bit total could hold
    assert property (total <= 9'd30);
endmodule

module trace_fifo (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] wdata,
    output wire [7:0] rdata,
    output wire       full,
    output wire       empty
);
    // depth 8 trace queue: 3 address bits + 1 wrap bit per pointer
    reg [3:0] wptr;
    reg [3:0] rptr;
    reg [3:0] count;
    reg [7:0] mem [0:7];

    integer k;
    initial begin
        wptr  = 4'd0;
        rptr  = 4'd0;
        count = 4'd0;
        for (k = 0; k < 8; k = k + 1)
            mem[k] = 8'h00;
    end

    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);
    assign rdata = mem[rptr[2:0]];

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 4'd0;
            rptr  <= 4'd0;
            count <= 4'd0;
        end else begin
            if (do_push) begin
                mem[wptr[2:0]] <= wdata;
                wptr <= wptr + 4'd1;
            end
            if (do_pop)
                rptr <= rptr + 4'd1;

            if (do_push && !do_pop)
                count <= count + 4'd1;
            else if (do_pop && !do_push)
                count <= count - 4'd1;
        end
    end

    // P: two universal pointer/occupancy agreements, checked in every state
    always @(*) begin
        assert (count != 4'd0 || wptr == rptr);
        assert (count != 4'd8 || wptr[2:0] == rptr[2:0]);
    end
endmodule

module fifo_deadline #(parameter DW = 8) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire push,
    input wire [DW-1:0] wdata,
    output wire [DW-1:0] rdata,
    output wire o_pop,
    output wire full,
    output wire empty
);
    // service deadline: an accepted entry must be drained within K steps
    localparam [2:0] K = 3'd4;

    reg [2:0] wptr  = 3'd0;
    reg [2:0] rptr  = 3'd0;
    reg [2:0] count = 3'd0;   // occupancy, 0..4
    reg [2:0] timer = 3'd0;   // countdown to forced service

    reg [DW-1:0] mem [0:3];
    integer i;
    initial begin
        for (i = 0; i < 4; i = i + 1) mem[i] = {DW{1'b0}};
    end

    // derived flags
    assign full  = (count == 3'd4);
    assign empty = (wptr == rptr);

    wire do_push = step && push && !full;
    wire do_pop  = step && !empty && (timer == 3'd1);

    assign rdata = mem[rptr[1:0]];
    assign o_pop = do_pop;

    wire [2:0] count_nxt = count + (do_push ? 3'd1 : 3'd0)
                                 - (do_pop  ? 3'd1 : 3'd0);

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 3'd0;
            timer <= 3'd0;
        end else if (step) begin
            if (do_push) begin
                mem[wptr[1:0]] <= wdata;
                wptr <= wptr + 3'd1;
            end
            if (do_pop)
                rptr <= rptr + 3'd1;

            count <= count_nxt;

            if (count_nxt == 3'd0)
                timer <= 3'd0;                 // nothing outstanding
            else if (do_pop || (count == 3'd0))
                timer <= K;                    // fresh deadline granted
            else
                timer <= timer - 3'd1;         // tick toward forced service
        end
    end

    // P: the countdown never expires while an entry is still outstanding
    always @(posedge clk)
        if (count != 3'd0)
            assert (timer != 3'd0);

endmodule

module token_bucket_shaper (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low => all state frozen
    input  wire       req,       // request a grant
    output wire       grant,
    output reg  [3:0] tokens,    // tokens available in the bucket
    output reg  [3:0] reserve,   // tokens not yet refilled (pool)
    output reg  [1:0] timer      // refill timer
);
    // burst size of the shaper: the bucket plus the pool always hold
    // exactly this many tokens between them.
    localparam [3:0] BURST = 4'd6;

    initial tokens  = BURST;
    initial reserve = 4'd0;
    initial timer   = 2'd0;

    wire tick      = (timer == 2'd3);
    wire do_refill = tick && (reserve != 4'd0);
    wire do_grant  = req  && (tokens  != 4'd0);

    assign grant = i_ce && do_grant;

    always @(posedge clk) begin
        if (rst) begin
            tokens  <= BURST;
            reserve <= 4'd0;
            timer   <= 2'd0;
        end else if (i_ce) begin
            timer <= timer + 2'd1;
            case ({do_refill, do_grant})
                2'b10: begin
                    // refill: a token migrates pool -> bucket
                    tokens  <= tokens  + 4'd1;
                    reserve <= reserve - 4'd1;
                end
                2'b01: begin
                    // drain: a token migrates bucket -> pool
                    tokens  <= tokens  - 4'd1;
                    reserve <= reserve + 4'd1;
                end
                default: begin
                    // idle, or refill and grant cancelling out
                    tokens  <= tokens;
                    reserve <= reserve;
                end
            endcase
        end
    end

    // P: neither the bucket nor the pool ever holds more than the burst
    // size, even though each register is 4 bits wide.
    always @(posedge clk) assert (tokens  <= BURST);
    always @(posedge clk) assert (reserve <= BURST);
endmodule

module pingpong_double_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wdata,
    output wire [7:0] rdata,
    output wire       wbank_full,
    output wire       rbank_empty
);
    // Two halves of an 8-entry RAM: half 0 is entries 0..3, half 1 is 4..7.
    // The writer owns half `wsel`, the reader owns half `rsel`; the two halves
    // are exchanged only when the write half is full and the read half drained.

    reg        wsel;
    reg        rsel;
    reg [2:0]  wcnt;
    reg [2:0]  rcnt;
    reg [7:0]  mem [0:7];

    initial begin
        wsel = 1'b0;
        rsel = 1'b1;
        wcnt = 3'd0;
        rcnt = 3'd4;   // reader's half starts empty (already drained)
    end

    wire wdone = (wcnt == 3'd4);
    wire rdone = (rcnt == 3'd4);
    wire swap  = wdone && rdone;

    wire [2:0] waddr = {wsel, wcnt[1:0]};
    wire [2:0] raddr = {rsel, rcnt[1:0]};

    assign wbank_full  = wdone;
    assign rbank_empty = rdone;
    assign rdata       = mem[raddr];

    always @(posedge clk) begin
        if (rst) begin
            wsel <= 1'b0;
            rsel <= 1'b1;
            wcnt <= 3'd0;
            rcnt <= 3'd4;
        end else if (swap) begin
            // hand the filled half to the reader, the drained half to the writer
            wsel <= ~wsel;
            rsel <= ~rsel;
            wcnt <= 3'd0;
            rcnt <= 3'd0;
        end else begin
            if (wr_en && !wdone) begin
                mem[waddr] <= wdata;
                wcnt <= wcnt + 3'd1;
            end
            if (rd_en && !rdone) begin
                rcnt <= rcnt + 3'd1;
            end
        end
    end

    // P: the write port and the read port never address the same RAM location.
    always @(posedge clk)
        assert (waddr != raddr);

endmodule

module pdm_cic_precedence (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_pdm,
    output wire [31:0] o_pcm
);
    localparam [31:0] DEC = 32'd64;

    reg [31:0] integ1;
    reg [31:0] integ2;
    reg [31:0] dly1;
    reg [31:0] dly2;
    reg [31:0] pcm;
    reg [31:0] phase;
    reg        seen_one;
    reg        armed;

    initial integ1   = 32'd0;
    initial integ2   = 32'd0;
    initial dly1     = 32'd0;
    initial dly2     = 32'd0;
    initial pcm      = 32'd0;
    initial phase    = 32'd0;
    initial seen_one = 1'b0;
    initial armed    = 1'b0;

    wire [31:0] integ1_n = integ1 + {31'd0, i_pdm};
    wire [31:0] integ2_n = integ2 + integ1;
    wire [31:0] comb1    = integ2 - dly1;
    wire [31:0] comb2    = comb1 - dly2;
    wire        tick     = (phase == DEC - 32'd1);

    always @(posedge clk) begin
        if (i_ce) begin
            integ1 <= integ1_n;
            integ2 <= integ2_n;
            if (i_pdm)
                seen_one <= 1'b1;
            if (tick) begin
                phase <= 32'd0;
                dly1  <= integ2;
                dly2  <= comb1;
                pcm   <= comb2;
                armed <= 1'b1;
            end else begin
                phase <= phase + 32'd1;
            end
        end
    end

    assign o_pcm = pcm;

    always @(posedge clk) assert (!armed || pcm == 32'd0 || seen_one);
endmodule

module raw_hazard_wq (
    input  wire        clk,
    input  wire        rst,
    input  wire        push,
    input  wire [63:0] wr_addr,
    input  wire [7:0]  wr_mask,
    input  wire        pop,
    input  wire        rd_valid,
    input  wire [63:0] rd_addr,
    input  wire [7:0]  rd_mask,
    output wire [31:0] o_match,
    output wire        o_fwd,
    output wire        o_stall,
    output wire        o_full,
    output wire        o_empty
);
    reg [63:0] q_addr [0:31];
    reg [7:0]  q_mask [0:31];
    reg [63:0] wptr, rptr, count;
    reg [31:0] match_vec;
    reg        fwd_r, stall_r;
    integer i;
    initial begin
        wptr = 64'd0; rptr = 64'd0; count = 64'd0;
        match_vec = 32'd0; fwd_r = 1'b0; stall_r = 1'b0;
        for (i = 0; i < 32; i = i + 1) begin
            q_addr[i] = 64'd0;
            q_mask[i] = 8'd0;
        end
    end

    wire full  = ((wptr - rptr) == 64'd32);
    wire empty = (count == 64'd0);
    wire do_push = push && !full;
    wire do_pop  = pop && !empty;

    wire [31:0] hit;
    wire [31:0] cov_ok;
    genvar g;
    generate
        for (g = 0; g < 32; g = g + 1) begin : cmp
            localparam [4:0] IDX = g;
            wire [4:0] off = IDX - rptr[4:0];
            wire pend = ({59'd0, off} < count);
            assign hit[g]    = pend && (q_addr[g] == rd_addr) && ((q_mask[g] & rd_mask) != 8'd0);
            assign cov_ok[g] = ((q_mask[g] & rd_mask) == rd_mask);
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 64'd0;
            rptr <= 64'd0;
            count <= 64'd0;
            match_vec <= 32'd0;
            fwd_r <= 1'b0;
            stall_r <= 1'b0;
        end else begin
            if (do_push) begin
                q_addr[wptr[4:0]] <= wr_addr;
                q_mask[wptr[4:0]] <= wr_mask;
                wptr <= wptr + 64'd1;
            end
            if (do_pop)
                rptr <= rptr + 64'd1;
            case ({do_push, do_pop})
                2'b10: count <= count + 64'd1;
                2'b01: count <= count - 64'd1;
                default: count <= count;
            endcase
            if (rd_valid) begin
                match_vec <= hit;
                fwd_r   <= (hit != 32'd0) && ((hit & cov_ok) == hit);
                stall_r <= (hit != 32'd0) && ((hit & cov_ok) != hit);
            end
        end
    end

    assign o_match = match_vec;
    assign o_fwd   = fwd_r;
    assign o_stall = stall_r;
    assign o_full  = full;
    assign o_empty = empty;

    assert property (!(full && empty));
endmodule

module tia_pll_seq (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire band_ok,
    input wire lock_in,
    output wire pll_pwr,
    output wire cal_active,
    output wire loop_closed,
    output wire clk_release,
    output reg [3:0] band
);
    localparam [2:0] S_OFF      = 3'd0;
    localparam [2:0] S_PWRUP    = 3'd1;
    localparam [2:0] S_BANDCAL  = 3'd2;
    localparam [2:0] S_CLOSE    = 3'd3;
    localparam [2:0] S_LOCKWAIT = 3'd4;
    localparam [2:0] S_RUN      = 3'd5;

    reg [2:0]  state;
    reg [15:0] cnt;

    initial state = S_OFF;
    initial cnt   = 16'd0;
    initial band  = 4'd0;

    assign pll_pwr     = (state != S_OFF);
    assign cal_active  = (state == S_BANDCAL);
    assign loop_closed = (state == S_CLOSE) || (state == S_LOCKWAIT) || (state == S_RUN);
    assign clk_release = (state == S_RUN);

    always @(posedge clk) begin
        if (!rst_n) begin
            state <= S_OFF;
            cnt   <= 16'd0;
            band  <= 4'd0;
        end else if (en) begin
            case (state)
                S_OFF: begin
                    state <= S_PWRUP;
                    cnt   <= 16'd0;
                end
                S_PWRUP: begin
                    if (cnt >= 16'd511) begin
                        state <= S_BANDCAL;
                        cnt   <= 16'd0;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                S_BANDCAL: begin
                    cnt <= 16'd0;
                    if (band_ok) begin
                        state <= S_CLOSE;
                    end else begin
                        band <= band + 4'd1;
                    end
                end
                S_CLOSE: begin
                    cnt <= cnt + 16'd1;
                    if (cnt >= 16'd200)
                        state <= S_LOCKWAIT;
                end
                S_LOCKWAIT: begin
                    if (!lock_in) begin
                        state <= S_BANDCAL;
                        cnt   <= 16'd0;
                    end else if (cnt >= 16'd1200) begin
                        state <= S_RUN;
                        cnt   <= 16'd0;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                S_RUN: begin
                    cnt <= 16'd0;
                    if (!lock_in)
                        state <= S_BANDCAL;
                end
                default: begin
                    state <= S_OFF;
                    cnt   <= 16'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (state == 3'd4) assert (cnt <= 16'd1200);
endmodule

module pwm_fault_trip (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       fault_in,
    input  wire       cfg_we,
    input  wire [3:0] cfg_hi,
    input  wire [3:0] cfg_lo,
    input  wire       clr_req,
    input  wire       duty_we,
    input  wire [7:0] duty_in,
    output reg  [3:0] out_hi,
    output reg  [3:0] out_lo
);
    reg [7:0] cnt;
    reg [7:0] duty;
    reg       fault_lat;
    reg [3:0] safe_hi;
    reg [3:0] safe_lo;
    reg       clr_arm;
    reg       no_clear_yet;

    initial cnt = 8'd0;
    initial duty = 8'd128;
    initial fault_lat = 1'b0;
    initial safe_hi = 4'b0000;
    initial safe_lo = 4'b1111;
    initial clr_arm = 1'b0;
    initial no_clear_yet = 1'b1;
    initial out_hi = 4'b0000;
    initial out_lo = 4'b1111;

    wire pwm_on = (cnt < duty);

    always @(posedge clk) begin
        if (rst) begin
            cnt       <= 8'd0;
            duty      <= 8'd128;
            fault_lat <= 1'b0;
            safe_hi   <= 4'b0000;
            safe_lo   <= 4'b1111;
            clr_arm   <= 1'b0;
            out_hi    <= 4'b0000;
            out_lo    <= 4'b1111;
        end else if (ce) begin
            cnt <= cnt + 8'd1;
            if (duty_we)
                duty <= duty_in;
            if (cfg_we) begin
                safe_hi <= cfg_hi;
                safe_lo <= cfg_lo & ~cfg_hi;
            end
            if (clr_req)
                clr_arm <= 1'b1;
            if (fault_in)
                fault_lat <= 1'b1;
            else if (clr_arm && fault_lat) begin
                fault_lat    <= 1'b0;
                clr_arm      <= 1'b0;
                no_clear_yet <= 1'b0;
            end
            if (fault_in || fault_lat) begin
                out_hi <= safe_hi;
                out_lo <= safe_lo;
            end else begin
                out_hi <= {4{pwm_on}};
                out_lo <= {4{~pwm_on}};
            end
        end
    end

    always @(posedge clk)
        if (no_clear_yet)
            assert ((out_hi & out_lo) == 4'd0);
endmodule

module tile_polarity_lock (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         retrain,
    input  wire [127:0] rx_data,
    output wire [127:0] data_out,
    output reg          locked
);
    localparam [7:0] TS     = 8'hBC;
    localparam [7:0] TS_INV = 8'h43;

    reg [15:0] inv_flag;
    reg [15:0] det_mask;
    reg [4:0]  det_cnt;
    reg        pre_rt;
    reg        pv;

    initial inv_flag = 16'd0;
    initial det_mask = 16'd0;
    initial det_cnt  = 5'd0;
    initial locked   = 1'b0;
    initial pre_rt   = 1'b1;
    initial pv       = 1'b0;

    reg [15:0] new_mask;
    reg [15:0] nxt_inv;
    reg [4:0]  new_cnt;
    integer i;

    always @(*) begin
        new_mask = 16'd0;
        nxt_inv  = inv_flag;
        new_cnt  = 5'd0;
        for (i = 0; i < 16; i = i + 1) begin
            if (!det_mask[i]) begin
                if (rx_data[8*i +: 8] == TS) begin
                    new_mask[i] = 1'b1;
                    nxt_inv[i]  = 1'b0;
                end else if (rx_data[8*i +: 8] == TS_INV) begin
                    new_mask[i] = 1'b1;
                    nxt_inv[i]  = 1'b1;
                end
            end
            new_cnt = new_cnt + {4'd0, new_mask[i]};
        end
    end

    wire [4:0] sum_cnt = det_cnt + new_cnt;

    genvar g;
    generate
        for (g = 0; g < 16; g = g + 1) begin : g_lane
            assign data_out[8*g +: 8] = rx_data[8*g +: 8] ^ {8{inv_flag[g]}};
        end
    endgenerate

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            inv_flag <= 16'd0;
            det_mask <= 16'd0;
            det_cnt  <= 5'd0;
            locked   <= 1'b0;
            pre_rt   <= 1'b1;
        end else if (en) begin
            if (retrain) begin
                inv_flag <= 16'd0;
                det_mask <= 16'd0;
                det_cnt  <= 5'd0;
                locked   <= 1'b0;
                pre_rt   <= 1'b0;
            end else begin
                inv_flag <= nxt_inv;
                det_mask <= det_mask | new_mask;
                det_cnt  <= sum_cnt;
                locked   <= locked | (sum_cnt == 5'd16);
            end
        end
    end

    always @(posedge clk)
        if (pv && !rst && pre_rt && $rose(locked))
            assert (&det_mask);
endmodule

module SsiFir8 (
    input  wire        clk,
    input  wire        en,
    input  wire        load_req,
    input  wire [31:0] coef_in,
    input  wire        s_valid,
    input  wire [31:0] s_data,
    input  wire        frame_end,
    output wire [31:0] y,
    output wire        y_valid
);
    reg [31:0] tap  [0:7];
    reg [31:0] coef [0:7];
    reg [31:0] fill_cnt = 32'd0;
    reg        primed   = 1'b0;
    reg        loading  = 1'b0;
    reg [31:0] load_ptr = 32'd0;
    reg        win      = 1'b0;
    reg        pv       = 1'b0;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            tap[i]  = 32'd0;
            coef[i] = 32'd0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (load_req) begin
                loading  <= 1'b1;
                load_ptr <= 32'd0;
                fill_cnt <= 32'd0;
                primed   <= 1'b0;
            end else begin
                primed <= (fill_cnt >= 32'd8);
                if (loading) begin
                    coef[load_ptr[2:0]] <= coef_in;
                    if (load_ptr == 32'd7) begin
                        loading  <= 1'b0;
                        load_ptr <= 32'd0;
                    end else begin
                        load_ptr <= load_ptr + 32'd1;
                    end
                end else if (s_valid) begin
                    for (i = 7; i > 0; i = i - 1)
                        tap[i] <= tap[i-1];
                    tap[0]   <= s_data;
                    fill_cnt <= (fill_cnt < 32'd8) ? (fill_cnt + 32'd1) : 32'd8;
                end
            end
            if (load_req)
                win <= 1'b1;
            else if (frame_end)
                win <= 1'b0;
        end
    end

    assign y = tap[0]*coef[0] + tap[1]*coef[1] + tap[2]*coef[2] + tap[3]*coef[3]
             + tap[4]*coef[4] + tap[5]*coef[5] + tap[6]*coef[6] + tap[7]*coef[7];
    assign y_valid = primed;

    always @(posedge clk)
        if (pv && $past(win))
            assert (!($past(primed) && $past(loading)));
endmodule

module trivium_core (
    input  wire        clk,
    input  wire        ce,
    input  wire        load,
    input  wire        zeroize,
    input  wire [79:0] key,
    input  wire [79:0] iv,
    output wire        ks_bit,
    output wire        ks_valid,
    output reg         ready
);
    reg [287:0] s = 288'd0;
    reg [63:0]  wcnt = 64'd0;
    reg         busy = 1'b0;
    reg         seen_load = 1'b0;
    reg         armed = 1'b1;
    reg         pv = 1'b0;
    initial ready = 1'b0;

    wire t1a = s[65]  ^ s[92];
    wire t2a = s[161] ^ s[176];
    wire t3a = s[242] ^ s[287];
    wire z   = t1a ^ t2a ^ t3a;
    wire t1  = t1a ^ (s[90]  & s[91])  ^ s[170];
    wire t2  = t2a ^ (s[174] & s[175]) ^ s[263];
    wire t3  = t3a ^ (s[285] & s[286]) ^ s[68];

    wire [287:0] nxt  = {s[286:177], t2, s[175:93], t1, s[91:0], t3};
    wire [287:0] init = {3'b111, 108'd0, 4'd0, iv, 13'd0, key};

    assign ks_bit   = z;
    assign ks_valid = ready && ce && !load && !zeroize;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (zeroize) begin
            s         <= 288'd0;
            wcnt      <= 64'd0;
            busy      <= 1'b0;
            ready     <= 1'b0;
            seen_load <= 1'b0;
            armed     <= 1'b0;
        end else if (ce) begin
            if (load) begin
                s         <= init;
                wcnt      <= 64'd0;
                busy      <= 1'b1;
                ready     <= 1'b0;
                seen_load <= 1'b1;
            end else if (busy) begin
                s <= nxt;
                if (wcnt == 64'd1151) begin
                    busy  <= 1'b0;
                    ready <= 1'b1;
                    wcnt  <= 64'd0;
                end else begin
                    wcnt <= wcnt + 64'd1;
                end
            end else if (ready) begin
                s <= nxt;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $rose(ready))
            assert (seen_load);
endmodule

module tlb32_ice40 (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [51:0] lookup_vpn,
    input wire [7:0] lookup_asid,
    input wire fill,
    input wire [51:0] fill_vpn,
    input wire [7:0] fill_asid,
    input wire [51:0] fill_ppn,
    input wire [2:0] fill_perm,
    input wire flush_all,
    input wire flush_asid,
    input wire [7:0] asid_sel,
    output reg hit,
    output reg [51:0] ppn_out,
    output reg [2:0] perm_out
);
    reg [31:0] valid = 32'd0;
    reg [63:0] occ = 64'd0;
    reg [63:0] hits = 64'd0;
    reg [4:0] victim = 5'd0;

    reg [51:0] tag_vpn [0:31];
    reg [7:0] tag_asid [0:31];
    reg [51:0] data_ppn [0:31];
    reg [2:0] data_perm [0:31];

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            tag_vpn[i] = 52'd0;
            tag_asid[i] = 8'd0;
            data_ppn[i] = 52'd0;
            data_perm[i] = 3'd0;
        end
    end

    function [6:0] popcount32;
        input [31:0] v;
        integer k;
        begin
            popcount32 = 7'd0;
            for (k = 0; k < 32; k = k + 1)
                popcount32 = popcount32 + {6'd0, v[k]};
        end
    endfunction

    reg [31:0] asid_match;
    reg [4:0] free_idx;
    reg has_free;
    integer j;

    always @(*) begin
        asid_match = 32'd0;
        hit = 1'b0;
        ppn_out = 52'd0;
        perm_out = 3'd0;
        has_free = 1'b0;
        free_idx = 5'd0;
        for (j = 31; j >= 0; j = j - 1) begin
            if (!valid[j]) begin
                has_free = 1'b1;
                free_idx = j;
            end
        end
        for (j = 0; j < 32; j = j + 1) begin
            if (valid[j] && (tag_asid[j] == asid_sel))
                asid_match[j] = 1'b1;
            if (valid[j] && !hit && (tag_vpn[j] == lookup_vpn) && (tag_asid[j] == lookup_asid)) begin
                hit = 1'b1;
                ppn_out = data_ppn[j];
                perm_out = data_perm[j];
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            valid <= 32'd0;
            occ <= 64'd0;
            hits <= 64'd0;
            victim <= 5'd0;
        end else if (en) begin
            if (flush_all) begin
                valid <= 32'd0;
                occ <= 64'd0;
            end else if (flush_asid) begin
                valid <= valid & ~asid_match;
                occ <= occ - {57'd0, popcount32(asid_match)};
            end else if (fill) begin
                if (has_free) begin
                    tag_vpn[free_idx] <= fill_vpn;
                    tag_asid[free_idx] <= fill_asid;
                    data_ppn[free_idx] <= fill_ppn;
                    data_perm[free_idx] <= fill_perm;
                    valid <= valid | (32'd1 << free_idx);
                    occ <= occ + 64'd1;
                end else begin
                    tag_vpn[victim] <= fill_vpn;
                    tag_asid[victim] <= fill_asid;
                    data_ppn[victim] <= fill_ppn;
                    data_perm[victim] <= fill_perm;
                    victim <= victim + 5'd1;
                end
            end
            if (hit)
                hits <= hits + 64'd1;
        end
    end

    assert property (occ <= 64'd32);
endmodule

module conv_enc_win (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire din,
    input wire start,
    input wire stop,
    output reg c0,
    output reg c1,
    output reg win,
    output reg [15:0] nbits
);
    // constraint-length-4 shift register of past input bits (4 entries)
    reg [3:0] sr;
    initial sr = 4'b0000;
    initial c0 = 1'b0;
    initial c1 = 1'b0;
    initial win = 1'b0;
    initial nbits = 16'd0;

    wire [3:0] sr_n = {sr[2:0], din};

    // G0 = 1111 computed incrementally as a sliding-window parity,
    // G1 = 1011 computed directly from the next shift-register contents
    always @(posedge clk) begin
        if (rst) begin
            sr    <= 4'b0000;
            c0    <= 1'b0;
            c1    <= 1'b0;
            nbits <= 16'd0;
        end else if (ce) begin
            sr    <= sr_n;
            c0    <= c0 ^ din ^ sr[3];
            c1    <= sr_n[3] ^ sr_n[1] ^ sr_n[0];
            nbits <= nbits + 16'd1;
        end
    end

    // observation window: opened by start, closed by stop
    always @(posedge clk) begin
        if (rst)
            win <= 1'b0;
        else if (start)
            win <= 1'b1;
        else if (stop)
            win <= 1'b0;
    end

    reg pv = 0;
    always @(posedge clk) pv <= 1;

    // inside the window, the XOR of the two code bits equals the input bit
    // that sat in tap position 1 before the shift
    always @(posedge clk)
        if (pv && win && $past(ce) && !$past(rst))
            assert ((c0 ^ c1) == $past(sr[1]));
endmodule

module issie_dbi_lane (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr,
    input  wire [63:0] wdata,
    input  wire        q_start,
    input  wire        r_stop,
    output wire [63:0] rdata,
    output wire [63:0] beat_count
);
    reg [63:0] bus_q;
    reg [7:0]  dbi_q;
    reg [63:0] plain_q;
    reg [63:0] beat_cnt;
    reg        win;
    reg        pv;
    initial begin
        bus_q = 64'd0; dbi_q = 8'd0; plain_q = 64'd0;
        beat_cnt = 64'd0; win = 1'b0; pv = 1'b0;
    end

    function [3:0] pop8;
        input [7:0] b;
        integer k;
        begin
            pop8 = 4'd0;
            for (k = 0; k < 8; k = k + 1)
                pop8 = pop8 + {3'd0, b[k]};
        end
    endfunction

    wire [7:0]  f;
    wire [63:0] enc;
    wire [63:0] xdbi;

    genvar i;
    generate
        for (i = 0; i < 8; i = i + 1) begin : g_lane
            assign f[i] = ((4'd8 - pop8(wdata[8*i +: 8])) > 4'd4);
            assign enc[8*i +: 8]  = wdata[8*i +: 8] ^ {8{f[i]}};
            assign xdbi[8*i +: 8] = {8{dbi_q[i]}};
        end
    endgenerate

    assign rdata = bus_q ^ xdbi;
    assign beat_count = beat_cnt;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            bus_q <= 64'd0;
            dbi_q <= 8'd0;
            plain_q <= 64'd0;
            beat_cnt <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (wr) begin
                bus_q <= enc;
                dbi_q <= f;
                plain_q <= wdata;
                beat_cnt <= beat_cnt + 64'd1;
            end
            if (q_start)
                win <= 1'b1;
            else if (r_stop)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (pv && !rst && win && $past(win) && $stable(bus_q) && $stable(dbi_q))
            assert ($stable(plain_q));
endmodule

module fp8_reduce_minmax (
    input wire clk,
    input wire rst,
    input wire en,
    input wire valid,
    input wire op,
    input wire [7:0] x,
    output reg [7:0] mx,
    output reg [7:0] mn,
    output reg [7:0] res,
    output reg inv,
    output reg armed
);
    initial mx = 8'hFC;
    initial mn = 8'h7C;
    initial res = 8'h00;
    initial inv = 1'b0;
    initial armed = 1'b0;

    function isnan;
        input [7:0] a;
        isnan = (a[6:2] == 5'h1F) && (a[1:0] != 2'b00);
    endfunction

    function [7:0] key;
        input [7:0] a;
        key = a[7] ? ~a : (a | 8'h80);
    endfunction

    function [7:0] fmax;
        input [7:0] a;
        input [7:0] b;
        begin
            if (isnan(a) && isnan(b)) fmax = 8'h7E;
            else if (isnan(a)) fmax = b;
            else if (isnan(b)) fmax = a;
            else if (key(a) >= key(b)) fmax = a;
            else fmax = b;
        end
    endfunction

    function [7:0] fmin;
        input [7:0] a;
        input [7:0] b;
        begin
            if (isnan(a) && isnan(b)) fmin = 8'h7E;
            else if (isnan(a)) fmin = b;
            else if (isnan(b)) fmin = a;
            else if (key(a) <= key(b)) fmin = a;
            else fmin = b;
        end
    endfunction

    function fle;
        input [7:0] a;
        input [7:0] b;
        fle = !isnan(a) && !isnan(b) && (key(a) <= key(b));
    endfunction

    wire [7:0] nmax = fmax(mx, x);
    wire [7:0] nmin = fmin(mn, x);

    always @(posedge clk) begin
        if (rst) begin
            mx <= 8'hFC;
            mn <= 8'h7C;
            res <= 8'h00;
            inv <= 1'b0;
            armed <= 1'b0;
        end else if (en && valid) begin
            mx <= nmax;
            mn <= nmin;
            res <= op ? nmin : nmax;
            inv <= isnan(x) && !x[1];
            armed <= 1'b1;
        end
    end

    always @(posedge clk)
        if (armed)
            assert (!isnan(mx) && !isnan(mn) && (fle(mn, mx) || (mx == 8'hFC && mn == 8'h7C)));
endmodule

module mem_stream_reader (
    input  wire        clk,
    input  wire        rst,
    input  wire        start,
    input  wire [31:0] i_len,
    input  wire [31:0] i_psize,
    input  wire        ce,
    input  wire        wr_en,
    input  wire [4:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_valid,
    output wire [31:0] o_data,
    output wire        o_start,
    output wire        o_last
);
    reg [31:0] mem [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) mem[i] = 32'd0;
    end
    always @(posedge clk)
        if (wr_en) mem[wr_addr] <= wr_data;

    reg [31:0] rd_ptr    = 32'd0;
    reg [31:0] remaining = 32'd0;
    reg [31:0] pkt_size  = 32'd8;
    reg [31:0] beat      = 32'd0;
    reg        busy      = 1'b0;
    reg        in_pkt    = 1'b0;

    wire fire = busy && ce;
    assign o_valid = busy;
    assign o_data  = mem[rd_ptr[4:0]];
    assign o_start = busy && (beat == 32'd0);
    assign o_last  = busy && ((beat == pkt_size - 32'd1) || (remaining == 32'd1));

    wire [31:0] len_c = (i_len > 32'd32) ? 32'd32 : i_len;
    wire [31:0] psz_c = ((i_psize == 32'd0) || (i_psize > 32'd8)) ? 32'd8 : i_psize;

    always @(posedge clk) begin
        if (rst) begin
            rd_ptr    <= 32'd0;
            remaining <= 32'd0;
            pkt_size  <= 32'd8;
            beat      <= 32'd0;
            busy      <= 1'b0;
            in_pkt    <= 1'b0;
        end else if (start && !busy) begin
            rd_ptr    <= 32'd0;
            remaining <= len_c;
            pkt_size  <= psz_c;
            beat      <= 32'd0;
            busy      <= (len_c != 32'd0);
            in_pkt    <= 1'b0;
        end else if (fire) begin
            rd_ptr    <= rd_ptr + 32'd1;
            remaining <= remaining - 32'd1;
            busy      <= (remaining != 32'd1);
            beat      <= o_last ? 32'd0 : beat + 32'd1;
            if (o_last)
                in_pkt <= 1'b0;
            else if (o_start)
                in_pkt <= 1'b1;
        end
    end

    always @(posedge clk)
        if (in_pkt) assert (beat <= 32'd7);
endmodule

module cdc_line_edge_fifo (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [127:0] din,
    input  wire         rd_en,
    input  wire         cfg_set,
    output wire [127:0] dout,
    output reg          full,
    output reg          empty
);
    reg [127:0] prev;
    reg [127:0] mem [0:15];
    reg [3:0]   wr_ptr;
    reg [3:0]   rd_ptr;
    reg [4:0]   count;
    reg         armed;
    reg         pv;
    integer i;

    initial begin
        prev   = 128'd0;
        wr_ptr = 4'd0;
        rd_ptr = 4'd0;
        count  = 5'd0;
        full   = 1'b0;
        empty  = 1'b1;
        armed  = 1'b0;
        pv     = 1'b0;
        for (i = 0; i < 16; i = i + 1) mem[i] = 128'd0;
    end

    wire edge_seen = en && (din != prev);
    wire push = edge_seen && !full;
    wire pop  = en && rd_en && !empty;
    wire [4:0] count_next = count + {4'd0, push} - {4'd0, pop};

    assign dout = mem[rd_ptr];

    always @(posedge clk) begin
        if (!rst_n) begin
            prev   <= 128'd0;
            wr_ptr <= 4'd0;
            rd_ptr <= 4'd0;
            count  <= 5'd0;
            full   <= 1'b0;
            empty  <= 1'b1;
            armed  <= 1'b0;
        end else if (en) begin
            prev <= din;
            if (push) begin
                mem[wr_ptr] <= din;
                wr_ptr <= wr_ptr + 4'd1;
            end
            if (pop)
                rd_ptr <= rd_ptr + 4'd1;
            count <= count_next;
            full  <= (count_next == 5'd16);
            empty <= (count_next == 5'd0);
            armed <= armed | cfg_set;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && armed && $rose(edge_seen))
            assert (!(full && empty));
endmodule

module mesi_pair (
    input wire clk,
    input wire rst,
    input wire step,
    input wire who,
    input wire wr,
    output reg [1:0] st_a,
    output reg [1:0] st_b,
    output reg bus_req,
    output reg [31:0] bus_cnt,
    output reg [31:0] wb_cnt
);
    localparam [1:0] ST_I = 2'b00;
    localparam [1:0] ST_S = 2'b01;
    localparam [1:0] ST_E = 2'b10;
    localparam [1:0] ST_M = 2'b11;

    initial st_a = ST_I;
    initial st_b = ST_I;
    initial bus_req = 1'b0;
    initial bus_cnt = 32'd0;
    initial wb_cnt = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            st_a <= ST_I;
            st_b <= ST_I;
            bus_req <= 1'b0;
            bus_cnt <= 32'd0;
            wb_cnt <= 32'd0;
        end else if (step) begin
            bus_req <= 1'b0;
            if (!who) begin
                if (wr) begin
                    if (st_a == ST_E) begin
                        st_a <= ST_M;
                    end else if (st_a != ST_M) begin
                        st_a <= ST_M;
                        if (st_b == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_b <= ST_I;
                        bus_req <= 1'b1;
                        bus_cnt <= bus_cnt + 32'd1;
                    end
                end else if (st_a == ST_I) begin
                    bus_req <= 1'b1;
                    bus_cnt <= bus_cnt + 32'd1;
                    if (st_b == ST_I) begin
                        st_a <= ST_E;
                    end else begin
                        st_a <= ST_S;
                        if (st_b == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_b <= ST_S;
                    end
                end
            end else begin
                if (wr) begin
                    if (st_b == ST_E) begin
                        st_b <= ST_M;
                    end else if (st_b != ST_M) begin
                        st_b <= ST_M;
                        if (st_a == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_a <= ST_I;
                        bus_req <= 1'b1;
                        bus_cnt <= bus_cnt + 32'd1;
                    end
                end else if (st_b == ST_I) begin
                    bus_req <= 1'b1;
                    bus_cnt <= bus_cnt + 32'd1;
                    if (st_a == ST_I) begin
                        st_b <= ST_E;
                    end else begin
                        st_b <= ST_S;
                        if (st_a == ST_M) wb_cnt <= wb_cnt + 32'd1;
                        st_a <= ST_S;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        assert (!(st_a == ST_M && st_b == ST_M));
endmodule

module async_mem_bus_ctrl (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         req,
    input  wire         req_wr,
    input  wire [4:0]   req_cs,
    input  wire [63:0]  req_addr,
    input  wire [63:0]  req_wdata,
    input  wire [63:0]  i_rdata,
    input  wire         cfg_we,
    input  wire [4:0]   cfg_cs,
    input  wire [63:0]  cfg_setup,
    input  wire [63:0]  cfg_access,
    input  wire [63:0]  cfg_hold,
    output wire [31:0]  cs_n,
    output wire         oe_n,
    output wire         we_n,
    output wire [63:0]  addr,
    output wire [63:0]  wdata,
    output wire [63:0]  rdata,
    output wire         busy
);
    localparam [1:0] P_IDLE = 2'd0, P_SETUP = 2'd1, P_ACCESS = 2'd2, P_HOLD = 2'd3;

    reg [1:0]    phase     = P_IDLE;
    reg [63:0]   cnt       = 64'd0;
    reg          wr_lat    = 1'b0;
    reg [4:0]    cs_lat    = 5'd0;
    reg [63:0]   addr_lat  = 64'd0;
    reg [63:0]   wdata_lat = 64'd0;
    reg [63:0]   rdata_lat = 64'd0;
    reg          oe        = 1'b0;
    reg          we        = 1'b0;
    reg          armed     = 1'b0;

    // per-chip-select timing registers: 32 entries x 64 bits each
    reg [2047:0] tsetup_flat  = {32{64'd1}};
    reg [2047:0] taccess_flat = {32{64'd2}};
    reg [2047:0] thold_flat   = {32{64'd1}};

    wire [63:0] t_setup  = tsetup_flat[cs_lat*64 +: 64];
    wire [63:0] t_access = taccess_flat[cs_lat*64 +: 64];
    wire [63:0] t_hold   = thold_flat[cs_lat*64 +: 64];

    always @(posedge clk) begin
        if (rst) begin
            phase  <= P_IDLE;
            cnt    <= 64'd0;
            wr_lat <= 1'b0;
            oe     <= 1'b0;
            we     <= 1'b0;
        end else if (i_ce) begin
            if (cfg_we) begin
                tsetup_flat[cfg_cs*64 +: 64]  <= cfg_setup;
                taccess_flat[cfg_cs*64 +: 64] <= cfg_access;
                thold_flat[cfg_cs*64 +: 64]   <= cfg_hold;
            end
            case (phase)
                P_IDLE: begin
                    if (req) begin
                        phase     <= P_SETUP;
                        cnt       <= 64'd0;
                        wr_lat    <= req_wr;
                        cs_lat    <= req_cs;
                        addr_lat  <= req_addr;
                        wdata_lat <= req_wdata;
                        armed     <= 1'b1;
                    end
                end
                P_SETUP: begin
                    if (cnt >= t_setup) begin
                        phase <= P_ACCESS;
                        cnt   <= 64'd0;
                        if (wr_lat) we <= 1'b1;
                        else        oe <= 1'b1;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
                P_ACCESS: begin
                    if (cnt >= t_access) begin
                        phase <= P_HOLD;
                        cnt   <= 64'd0;
                        if (!wr_lat) rdata_lat <= i_rdata;
                        oe    <= 1'b0;
                        we    <= 1'b0;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
                P_HOLD: begin
                    if (cnt >= t_hold) begin
                        phase <= P_IDLE;
                        cnt   <= 64'd0;
                    end else begin
                        cnt <= cnt + 64'd1;
                    end
                end
            endcase
        end
    end

    assign cs_n  = (phase == P_IDLE) ? 32'hFFFFFFFF : ~(32'd1 << cs_lat);
    assign oe_n  = ~oe;
    assign we_n  = ~we;
    assign addr  = addr_lat;
    assign wdata = wdata_lat;
    assign rdata = rdata_lat;
    assign busy  = (phase != P_IDLE);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Absence after first accepted transaction: OE and WE strobes never both active
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(oe) && $past(we)));
endmodule

module wwdg_window (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire       stop,
    input  wire       kick,
    input  wire [7:0] cfg_reload,
    input  wire [7:0] cfg_win,
    output wire [1:0] o_fault,
    output wire       o_armed,
    output wire [7:0] o_cnt
);
    reg       pv       = 1'b0;
    reg       armed    = 1'b0;
    reg [7:0] cnt      = 8'd64;
    reg [7:0] reload   = 8'd64;
    reg [7:0] win_thr  = 8'd0;
    reg [1:0] fault    = 2'b00;
    reg       win_open = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (start) begin
            armed    <= 1'b1;
            reload   <= cfg_reload | 8'h40;
            win_thr  <= cfg_win & 8'h3F;
            cnt      <= cfg_reload | 8'h40;
            fault    <= 2'b00;
            win_open <= 1'b0;
        end else if (stop) begin
            armed <= 1'b0;
        end else if (armed && ce && fault == 2'b00) begin
            if (kick) begin
                if (cnt > win_thr)
                    fault[0] <= 1'b1;
                else begin
                    cnt      <= reload;
                    win_open <= 1'b0;
                end
            end else if (cnt == 8'd0) begin
                fault[1] <= 1'b1;
            end else begin
                cnt      <= cnt - 8'd1;
                win_open <= ((cnt - 8'd1) <= win_thr);
            end
        end
    end

    assign o_fault = fault;
    assign o_armed = armed;
    assign o_cnt   = cnt;

    always @(posedge clk)
        if (pv && armed && $rose(fault[1]))
            assert (win_open);
endmodule

module nfc_rst_escalator (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire rx_fault,
    output wire sub_rst,
    output wire chip_rst
);
    localparam [63:0] T1 = 64'd4;
    localparam [63:0] T2 = 64'd8;
    localparam [63:0] DECAY = 64'd1000;
    localparam [63:0] CNT_MAX = 64'hFFFF_FFFF_FFFF_FFFF;

    reg [63:0] fault_cnt = 64'd0;
    reg [63:0] decay_tmr = 64'd0;
    reg sub_rst_q = 1'b0;
    reg chip_rst_q = 1'b0;
    reg armed = 1'b0;

    wire [63:0] inc = fault_cnt + 64'd1;
    wire [63:0] dec = fault_cnt - 64'd1;

    always @(posedge clk) begin
        if (!rst_n) begin
            fault_cnt <= 64'd0;
            decay_tmr <= 64'd0;
            sub_rst_q <= 1'b0;
            chip_rst_q <= 1'b0;
            armed <= 1'b0;
        end else if (en) begin
            armed <= armed | sub_rst_q;
            if (rx_fault) begin
                if (fault_cnt != CNT_MAX) begin
                    fault_cnt <= inc;
                    if (inc == T1)
                        sub_rst_q <= 1'b1;
                    if (inc == T2) begin
                        chip_rst_q <= 1'b1;
                        sub_rst_q <= 1'b0;
                    end
                end
            end else begin
                if (decay_tmr == DECAY) begin
                    decay_tmr <= 64'd0;
                    if (fault_cnt != 64'd0) begin
                        fault_cnt <= dec;
                        if (dec == T2 - 64'd1) begin
                            chip_rst_q <= 1'b0;
                            sub_rst_q <= 1'b1;
                        end
                        if (dec == T1 - 64'd1)
                            sub_rst_q <= 1'b0;
                    end
                end else begin
                    decay_tmr <= decay_tmr + 64'd1;
                end
            end
        end
    end

    assign sub_rst = sub_rst_q;
    assign chip_rst = chip_rst_q;

    always @(*)
        if (armed)
            assert (!(sub_rst_q && chip_rst_q));
endmodule

module mcast_demux (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire [7:0] i_mask,
    input  wire [7:0] i_data,
    input  wire [7:0] i_ready,
    output wire [7:0] o_valid,
    output wire [7:0] o_data,
    output wire       o_done,
    output wire       o_busy
);
    localparam IDLE  = 2'd0;
    localparam ARMED = 2'd1;
    localparam SEND  = 2'd2;
    localparam FIN   = 2'd3;

    reg [1:0] phase;
    reg [7:0] mask;
    reg [7:0] delivered;
    reg [7:0] data;
    initial phase = IDLE;
    initial mask = 8'd0;
    initial delivered = 8'd0;
    initial data = 8'd0;

    assign o_valid = (phase == SEND) ? (mask & ~delivered) : 8'd0;
    assign o_data  = data;
    assign o_done  = (phase == FIN);
    assign o_busy  = (phase != IDLE);

    wire [7:0] accepted = o_valid & i_ready;
    wire [7:0] next_del = delivered | accepted;

    always @(posedge clk) begin
        if (i_reset) begin
            phase     <= IDLE;
            mask      <= 8'd0;
            delivered <= 8'd0;
            data      <= 8'd0;
        end else if (i_ce) begin
            case (phase)
                IDLE: begin
                    if (i_arm && (i_mask != 8'd0)) begin
                        mask      <= i_mask;
                        data      <= i_data;
                        delivered <= 8'd0;
                        phase     <= ARMED;
                    end
                end
                ARMED: begin
                    phase <= SEND;
                end
                SEND: begin
                    delivered <= next_del;
                    if (next_del == mask)
                        phase <= FIN;
                end
                FIN: begin
                    phase     <= IDLE;
                    mask      <= 8'd0;
                    delivered <= 8'd0;
                end
            endcase
        end
    end

    // finish implies a copy was started (at least one delivery)
    always @(*)
        if (phase == FIN) assert (delivered != 8'd0);

    // finish implies an arm with a non-empty destination mask happened
    always @(*)
        if (phase == FIN) assert (mask != 8'd0);
endmodule

module remap_unit (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_seq_go,
    input  wire        i_unlock,
    input  wire        i_cfg_we,
    input  wire        i_cfg_sel,
    input  wire        i_cfg_en,
    input  wire [63:0] i_cfg_src,
    input  wire [63:0] i_cfg_size,
    input  wire [63:0] i_cfg_tgt,
    input  wire [63:0] i_addr,
    output wire [63:0] o_addr,
    output wire        o_hit
);
    localparam [63:0] ROM_BASE  = 64'h0000_0000_2000_0000;
    localparam [63:0] ROM_SIZE  = 64'h0000_0000_0001_0000;
    localparam [63:0] DRAM_BASE = 64'h0000_0000_8000_0000;
    localparam [63:0] DRAM_SIZE = 64'h0000_0000_4000_0000;

    // scope register: high until software unlocks the remap table
    reg        boot_phase = 1'b1;
    // boot handoff sequencer: 0 alias, 1 copy, 2 drain, 3 ram at zero
    reg [63:0] seq        = 64'd0;
    // window 0: boot ROM aliased to address zero
    reg        alias_en   = 1'b1;
    reg [63:0] src0       = 64'd0;
    reg [63:0] size0      = ROM_SIZE;
    reg [63:0] tgt0       = ROM_BASE;
    // window 1: DRAM mapped at address zero
    reg        ram_en     = 1'b0;
    reg [63:0] src1       = 64'd0;
    reg [63:0] size1      = DRAM_SIZE;
    reg [63:0] tgt1       = DRAM_BASE;

    always @(posedge clk) begin
        if (i_reset) begin
            boot_phase <= 1'b1;
            seq        <= 64'd0;
            alias_en   <= 1'b1;
            src0       <= 64'd0;
            size0      <= ROM_SIZE;
            tgt0       <= ROM_BASE;
            ram_en     <= 1'b0;
            src1       <= 64'd0;
            size1      <= DRAM_SIZE;
            tgt1       <= DRAM_BASE;
        end else if (i_ce) begin
            if (i_unlock)
                boot_phase <= 1'b0;
            if (i_seq_go && (seq != 64'd3))
                seq <= seq + 64'd1;
            if (i_seq_go && (seq == 64'd1))
                alias_en <= 1'b0;
            if (i_seq_go && (seq == 64'd2))
                ram_en <= 1'b1;
            if (i_cfg_we && !boot_phase) begin
                if (i_cfg_sel) begin
                    src1   <= i_cfg_src;
                    size1  <= i_cfg_size;
                    tgt1   <= i_cfg_tgt;
                    ram_en <= i_cfg_en;
                end else begin
                    src0     <= i_cfg_src;
                    size0    <= i_cfg_size;
                    tgt0     <= i_cfg_tgt;
                    alias_en <= i_cfg_en;
                end
            end
        end
    end

    wire [63:0] off0 = i_addr - src0;
    wire [63:0] off1 = i_addr - src1;
    wire hit0 = alias_en && (i_addr >= src0) && (off0 < size0);
    wire hit1 = ram_en   && (i_addr >= src1) && (off1 < size1);

    assign o_hit  = hit0 || hit1;
    assign o_addr = hit0 ? (tgt0 + off0) : (hit1 ? (tgt1 + off1) : i_addr);

    // Absence, before unlock: address zero never has two owners
    always @(posedge clk)
        if (boot_phase)
            assert (!(alias_en && ram_en));
endmodule

module spi_snoop_filter (
    input wire clk,
    input wire en,
    input wire sclk_rise,
    input wire mosi,
    output wire [4:0] o_occ
);
    reg [15:0] sr;
    reg [3:0]  bitcnt;
    reg [15:0] pvec [0:15];
    reg [4:0]  occ_cnt;
    reg        armed;

    integer k;
    initial begin
        sr = 16'd0;
        bitcnt = 4'd0;
        occ_cnt = 5'd0;
        armed = 1'b0;
        for (k = 0; k < 16; k = k + 1)
            pvec[k] = 16'd0;
    end

    wire [15:0] w   = {sr[14:0], mosi};
    wire [1:0]  op  = w[15:14];
    wire [3:0]  idx = w[13:10];
    wire [3:0]  cid = w[9:6];
    wire [15:0] cur = pvec[idx];
    wire [15:0] cmask = 16'd1 << cid;
    wire [15:0] set_v = cur | cmask;
    wire [15:0] clr_v = cur & ~cmask;

    always @(posedge clk) begin
        if (en && sclk_rise) begin
            sr <= w;
            bitcnt <= bitcnt + 4'd1;
            if (bitcnt == 4'd15) begin
                case (op)
                    2'b01: begin
                        pvec[idx] <= set_v;
                        if (cur == 16'd0)
                            occ_cnt <= occ_cnt + 5'd1;
                    end
                    2'b10: begin
                        pvec[idx] <= clr_v;
                        if (cur != 16'd0 && clr_v == 16'd0)
                            occ_cnt <= occ_cnt - 5'd1;
                    end
                    2'b11: begin
                        pvec[idx] <= 16'd0;
                        if (cur != 16'd0) begin
                            occ_cnt <= occ_cnt - 5'd1;
                            armed <= 1'b1;
                        end
                    end
                    default: ;
                endcase
            end
        end
    end

    assign o_occ = occ_cnt;

    always @(posedge clk)
        if (armed)
            assert (occ_cnt <= 5'd16);
endmodule

// Host-side scheduler for the flow classifier. The flow table only takes a
// lookup or a rule write while it is not scanning, so both are queued here
// and handed over while no lookup is outstanding; every accepted lookup is
// given a sequence tag that comes back with its completion.
module lookup_scheduler #(
   parameter RQ_AW = 2,
   parameter WQ_AW = 2,
   parameter TAG_W = 4
) (
   input  wire             clk,
   input  wire             rst,
   input  wire             i_ce,
   input  wire             in_req,
   input  wire [63:0]      in_key,
   input  wire [15:0]      in_len,
   output wire             in_ready,
   output wire [TAG_W-1:0] in_tag,
   input  wire             in_wr,
   input  wire [6:0]       in_wr_idx,
   input  wire [63:0]      in_wr_key,
   input  wire [31:0]      in_wr_action,
   output wire             wr_ready,
   input  wire             tb_rsp_valid,
   input  wire             tb_rsp_hit,
   output wire             tb_req,
   output wire [63:0]      tb_key,
   output wire [15:0]      tb_len,
   output wire             tb_wr,
   output wire [6:0]       tb_wr_idx,
   output wire [63:0]      tb_wr_key,
   output wire [31:0]      tb_wr_action,
   output wire             done_valid,
   output wire             done_hit,
   output wire [TAG_W-1:0] done_tag,
   output wire             pend_o,
   output wire [RQ_AW:0]   rq_cnt_o,
   output wire [WQ_AW:0]   wq_cnt_o,
   output wire [RQ_AW:0]   rq_hwm_o,
   output wire [15:0]      miss_cnt_o
);
   localparam RQ_DEPTH = 1 << RQ_AW;
   localparam WQ_DEPTH = 1 << WQ_AW;
   reg [63:0]      rq_key [0:RQ_DEPTH-1];
   reg [15:0]      rq_len [0:RQ_DEPTH-1];
   reg [TAG_W-1:0] rq_tag [0:RQ_DEPTH-1];
   reg [RQ_AW-1:0] rq_wp;
   reg [RQ_AW-1:0] rq_rp;
   reg [RQ_AW:0]   rq_cnt;
   reg [RQ_AW:0]   rq_hwm;
   reg [TAG_W-1:0] tag_ctr;
   reg [6:0]       wq_idx [0:WQ_DEPTH-1];
   reg [63:0]      wq_key [0:WQ_DEPTH-1];
   reg [31:0]      wq_act [0:WQ_DEPTH-1];
   reg [WQ_AW-1:0] wq_wp;
   reg [WQ_AW-1:0] wq_rp;
   reg [WQ_AW:0]   wq_cnt;
   reg             pend;
   reg [TAG_W-1:0] cur_tag;
   reg [15:0]      miss_cnt;
   integer k;
   initial begin
       for (k = 0; k < RQ_DEPTH; k = k + 1) begin
           rq_key[k] = 64'd0;
           rq_len[k] = 16'd0;
           rq_tag[k] = {TAG_W{1'b0}};
       end
       for (k = 0; k < WQ_DEPTH; k = k + 1) begin
           wq_idx[k] = 7'd0;
           wq_key[k] = 64'd0;
           wq_act[k] = 32'd0;
       end
       rq_wp    = {RQ_AW{1'b0}};
       rq_rp    = {RQ_AW{1'b0}};
       rq_cnt   = {(RQ_AW+1){1'b0}};
       rq_hwm   = {(RQ_AW+1){1'b0}};
       tag_ctr  = {TAG_W{1'b0}};
       wq_wp    = {WQ_AW{1'b0}};
       wq_rp    = {WQ_AW{1'b0}};
       wq_cnt   = {(WQ_AW+1){1'b0}};
       pend     = 1'b0;
       cur_tag  = {TAG_W{1'b0}};
       miss_cnt = 16'd0;
   end
   wire rq_full  = (rq_cnt == RQ_DEPTH);
   wire rq_empty = (rq_cnt == 0);
   wire wq_full  = (wq_cnt == WQ_DEPTH);
   wire wq_empty = (wq_cnt == 0);
   // the table is handed work only while none of ours is outstanding
   assign tb_req = !pend && !rq_empty;
   assign tb_wr  = !pend && !wq_empty;
   wire rq_pop  = i_ce && tb_req;
   wire wq_pop  = i_ce && tb_wr;
   wire rq_push = i_ce && in_req && !rq_full;
   // a rule write to the same index as the newest queued write replaces it
   // in place, unless that entry is the one leaving for the table this cycle
   wire [WQ_AW-1:0] wq_tail = wq_wp - 1'b1;
   wire wq_tail_leaving = tb_wr && (wq_cnt == 1);
   wire wr_merge = !wq_empty && !wq_tail_leaving && (wq_idx[wq_tail] == in_wr_idx);
   wire wr_take  = i_ce && in_wr && (!wq_full || wr_merge);
   wire wr_push  = wr_take && !wr_merge;
   assign in_ready = !rq_full;
   assign in_tag   = tag_ctr;
   assign wr_ready = !wq_full || wr_merge;
   assign tb_key       = rq_key[rq_rp];
   assign tb_len       = rq_len[rq_rp];
   assign tb_wr_idx    = wq_idx[wq_rp];
   assign tb_wr_key    = wq_key[wq_rp];
   assign tb_wr_action = wq_act[wq_rp];
   wire done = tb_rsp_valid && pend;
   always @(posedge clk) begin
       if (rst) begin
           rq_wp   <= {RQ_AW{1'b0}};
           rq_rp   <= {RQ_AW{1'b0}};
           rq_cnt  <= {(RQ_AW+1){1'b0}};
           rq_hwm  <= {(RQ_AW+1){1'b0}};
           tag_ctr <= {TAG_W{1'b0}};
       end else if (i_ce) begin
           if (rq_push) begin
               rq_key[rq_wp] <= in_key;
               rq_len[rq_wp] <= in_len;
               rq_tag[rq_wp] <= tag_ctr;
               rq_wp         <= rq_wp + 1'b1;
               tag_ctr       <= tag_ctr + 1'b1;
           end
           if (rq_pop)
               rq_rp <= rq_rp + 1'b1;
           if (rq_push && !rq_pop)
               rq_cnt <= rq_cnt + 1'b1;
           else if (rq_pop && !rq_push)
               rq_cnt <= rq_cnt - 1'b1;
           if (rq_cnt > rq_hwm)
               rq_hwm <= rq_cnt;
       end
   end
   always @(posedge clk) begin
       if (rst) begin
           wq_wp  <= {WQ_AW{1'b0}};
           wq_rp  <= {WQ_AW{1'b0}};
           wq_cnt <= {(WQ_AW+1){1'b0}};
       end else if (i_ce) begin
           if (wr_take && wr_merge) begin
               wq_key[wq_tail] <= in_wr_key;
               wq_act[wq_tail] <= in_wr_action;
           end else if (wr_push) begin
               wq_idx[wq_wp] <= in_wr_idx;
               wq_key[wq_wp] <= in_wr_key;
               wq_act[wq_wp] <= in_wr_action;
               wq_wp         <= wq_wp + 1'b1;
           end
           if (wq_pop)
               wq_rp <= wq_rp + 1'b1;
           if (wr_push && !wq_pop)
               wq_cnt <= wq_cnt + 1'b1;
           else if (wq_pop && !wr_push)
               wq_cnt <= wq_cnt - 1'b1;
       end
   end
   always @(posedge clk) begin
       if (rst) begin
           pend     <= 1'b0;
           cur_tag  <= {TAG_W{1'b0}};
           miss_cnt <= 16'd0;
       end else if (i_ce) begin
           if (rq_pop) begin
               pend    <= 1'b1;
               cur_tag <= rq_tag[rq_rp];
           end else if (tb_rsp_valid) begin
               pend <= 1'b0;
           end
           if (done && !tb_rsp_hit && (miss_cnt != 16'hFFFF))
               miss_cnt <= miss_cnt + 16'd1;
       end
   end
   assign done_valid = done;
   assign done_hit   = tb_rsp_hit;
   assign done_tag   = cur_tag;
   assign pend_o     = pend;
   assign rq_cnt_o   = rq_cnt;
   assign wq_cnt_o   = wq_cnt;
   assign rq_hwm_o   = rq_hwm;
   assign miss_cnt_o = miss_cnt;
endmodule
module flow_match_table (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    output reg         rsp_valid,
    output reg         rsp_hit,
    output reg  [31:0] rsp_action,
    output reg  [6:0]  rsp_rule
,
    output wire busy_o,
    output wire [6:0] idx_o,
    output wire [7:0] timer_o
);
    reg [63:0]  key_mem  [0:127];
    reg [31:0]  act_mem  [0:127];
    reg [63:0]  pkt_cnt  [0:127];
    reg [63:0]  byte_cnt [0:127];
    reg [127:0] valid;

    reg        busy;
    reg [6:0]  idx;
    reg [7:0]  timer;
    reg [63:0] q_key;
    reg [63:0] q_len;

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            key_mem[i]  = 64'd0;
            act_mem[i]  = 32'd0;
            pkt_cnt[i]  = 64'd0;
            byte_cnt[i] = 64'd0;
        end
        valid      = 128'd0;
        busy       = 1'b0;
        idx        = 7'd0;
        timer      = 8'd0;
        q_key      = 64'd0;
        q_len      = 64'd0;
        rsp_valid  = 1'b0;
        rsp_hit    = 1'b0;
        rsp_action = 32'd0;
        rsp_rule   = 7'd0;
    end

    wire hit  = valid[idx] && (key_mem[idx] == q_key);
    wire last = (idx == 7'd127);

    always @(posedge clk) begin
        if (rst) begin
            busy      <= 1'b0;
            idx       <= 7'd0;
            timer     <= 8'd0;
            valid     <= 128'd0;
            rsp_valid <= 1'b0;
            rsp_hit   <= 1'b0;
        end else if (i_ce) begin
            rsp_valid <= 1'b0;
            if (!busy) begin
                if (wr_en) begin
                    key_mem[wr_idx]  <= wr_key;
                    act_mem[wr_idx]  <= wr_action;
                    pkt_cnt[wr_idx]  <= 64'd0;
                    byte_cnt[wr_idx] <= 64'd0;
                    valid[wr_idx]    <= 1'b1;
                end
                if (req) begin
                    busy  <= 1'b1;
                    idx   <= 7'd0;
                    timer <= 8'd128;
                    q_key <= req_key;
                    q_len <= {48'd0, req_len};
                end
            end else begin
                if (hit) begin
                    pkt_cnt[idx]  <= pkt_cnt[idx] + 64'd1;
                    byte_cnt[idx] <= byte_cnt[idx] + q_len;
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b1;
                    rsp_action    <= act_mem[idx];
                    rsp_rule      <= idx;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else if (last) begin
                    rsp_valid     <= 1'b1;
                    rsp_hit       <= 1'b0;
                    rsp_action    <= 32'd0;
                    rsp_rule      <= 7'd0;
                    busy          <= 1'b0;
                    timer         <= 8'd0;
                end else begin
                    idx   <= idx + 7'd1;
                    timer <= timer - 8'd1;
                end
            end
        end
    end

    // After a lookup is accepted (busy set) until it completes (busy cleared),
    // the completion countdown must never expire.
    always @(posedge clk)
        if (busy)
            assert (timer != 8'd0);
    assign busy_o = busy;
    assign idx_o = idx;
    assign timer_o = timer;
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module flow_mpu_top (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] req_key,
    input  wire [15:0] req_len,
    input  wire        wr_en,
    input  wire [6:0]  wr_idx,
    input  wire [63:0] wr_key,
    input  wire [31:0] wr_action,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    output wire        grant,
    output wire        fault,
    output wire [6:0]  rsp_rule,
    output wire        g_valid_o,
    output wire [15:0] g_addr_o,
   output wire        g_write_o,
   output wire        req_ready,
   output wire [3:0]  req_tag,
   output wire        wr_ready,
   output wire        lk_done,
   output wire        lk_hit,
   output wire [3:0]  lk_tag,
   output wire        sch_pend_o,
   output wire [2:0]  rq_cnt_o,
   output wire [2:0]  wq_cnt_o,
   output wire [2:0]  rq_hwm_o,
   output wire [15:0] miss_cnt_o
);
    wire        rsp_valid;
    wire        rsp_hit;
    wire [31:0] rsp_action;
    wire        busy_a;
    wire [6:0]  idx_a;
    wire [7:0]  timer_a;
    wire        hit_q;
    wire        miss_q;
   wire        s_req;
   wire [63:0] s_key;
   wire [15:0] s_len;
   wire        s_wr;
   wire [6:0]  s_wr_idx;
   wire [63:0] s_wr_key;
   wire [31:0] s_wr_action;
   wire        sch_pend;
   wire [2:0]  rq_cnt;
   wire [2:0]  wq_cnt;
   wire [2:0]  rq_hwm;

    // pending destination-buffer access handed from the classifier to the MPU
    reg        g_valid;
    reg [15:0] g_addr;
    reg        g_write;

    initial begin
        g_valid = 1'b0;
        g_addr  = 16'd0;
        g_write = 1'b0;
    end

    flow_match_table u_flow (
        .clk(clk),
        .rst(rst),
        .i_ce(i_ce),
       .req(s_req),
       .req_key(s_key),
       .req_len(s_len),
       .wr_en(s_wr),
       .wr_idx(s_wr_idx),
       .wr_key(s_wr_key),
       .wr_action(s_wr_action),
        .rsp_valid(rsp_valid),
        .rsp_hit(rsp_hit),
        .rsp_action(rsp_action),
        .rsp_rule(rsp_rule),
        .busy_o(busy_a),
        .idx_o(idx_a),
        .timer_o(timer_a)
    );

    always @(posedge clk) begin
        if (rst) begin
            g_valid <= 1'b0;
            g_addr  <= 16'd0;
            g_write <= 1'b0;
        end else if (i_ce) begin
            g_valid <= rsp_valid && rsp_hit;
            if (rsp_valid && rsp_hit) begin
                g_addr  <= rsp_action[15:0];
                g_write <= rsp_action[16];
            end
        end
    end

    mpu_region_checker u_mpu (
        .clk(clk),
        .i_ce(i_ce),
        .cfg_we(cfg_we),
        .cfg_idx(cfg_idx),
        .cfg_base(cfg_base),
        .cfg_limit(cfg_limit),
        .cfg_perm(cfg_perm),
        .lock_req(lock_req),
        .acc_valid(g_valid),
        .acc_write(g_write),
        .acc_addr(g_addr),
        .grant(grant),
        .fault(fault),
        .hit_q_o(hit_q),
        .miss_q_o(miss_q)
    );

    assign g_valid_o = g_valid;
    assign g_addr_o  = g_addr;
    assign g_write_o = g_write;
   lookup_scheduler #(
       .RQ_AW(2),
       .WQ_AW(2),
       .TAG_W(4)
   ) u_sched (
       .clk(clk),
       .rst(rst),
       .i_ce(i_ce),
       .in_req(req),
       .in_key(req_key),
       .in_len(req_len),
       .in_ready(req_ready),
       .in_tag(req_tag),
       .in_wr(wr_en),
       .in_wr_idx(wr_idx),
       .in_wr_key(wr_key),
       .in_wr_action(wr_action),
       .wr_ready(wr_ready),
       .tb_rsp_valid(rsp_valid),
       .tb_rsp_hit(rsp_hit),
       .tb_req(s_req),
       .tb_key(s_key),
       .tb_len(s_len),
       .tb_wr(s_wr),
       .tb_wr_idx(s_wr_idx),
       .tb_wr_key(s_wr_key),
       .tb_wr_action(s_wr_action),
       .done_valid(lk_done),
       .done_hit(lk_hit),
       .done_tag(lk_tag),
       .pend_o(sch_pend),
       .rq_cnt_o(rq_cnt),
       .wq_cnt_o(wq_cnt),
       .rq_hwm_o(rq_hwm),
       .miss_cnt_o(miss_cnt_o)
   );
   assign sch_pend_o = sch_pend;
   assign rq_cnt_o   = rq_cnt;
   assign wq_cnt_o   = wq_cnt;
   assign rq_hwm_o   = rq_hwm;
   // every response the flow table produces belongs to a lookup the scheduler handed it
   always @(posedge clk)
       if (rsp_valid)
           assert (sch_pend);

    // the MPU never holds two packet steering decisions in its check stage at once
    always @(posedge clk)
        if (g_valid)
            assert (!(hit_q || miss_q));
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire [63:0] o_hist_stamp,
   output wire [15:0] o_hist_sig,
   output wire [1:0] o_hist_state,
   output wire [2:0] o_hist_level,
   output wire o_hist_open,
   output wire [15:0] o_last_sig,
   output wire [7:0] o_hist_drops,
   output wire [7:0] o_abort_cnt,
   output wire [63:0] o_ret_stamp,
   output wire [15:0] o_ret_sig,
   output wire [1:0] o_ret_state,
   output wire o_ret_valid
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;
   localparam [1:0] ST_FREE = 2'd0, ST_OPEN = 2'd1, ST_DONE = 2'd2, ST_ABRT = 2'd3;
   localparam [4:0] HIST_CLR = 5'd30, HIST_ACK = 5'd31;
   localparam [2:0] HIST_DEPTH = 3'd4;
   // frame history: one record per launched frame, oldest at hist_rd_ptr
   reg [63:0] hist_mem [0:3];
   reg [15:0] hist_sum [0:3];
   reg [1:0]  hist_st  [0:3];
   reg [1:0]  hist_wr_ptr;
   reg [1:0]  hist_rd_ptr;
   reg [2:0]  hist_cnt;
   reg [7:0]  hist_drop;
   reg [7:0]  abort_cnt;
   reg [15:0] frame_sig;
   // last record retired through HIST_ACK
   reg [63:0] ret_stamp;
   reg [15:0] ret_sum;
   reg [1:0]  ret_st;
   reg        ret_vld;
   integer j;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;
   initial begin
       for (j = 0; j < 4; j = j + 1) begin
           hist_mem[j] = 64'd0;
           hist_sum[j] = 16'd0;
           hist_st[j] = ST_FREE;
       end
   end
   initial hist_wr_ptr = 2'd0;
   initial hist_rd_ptr = 2'd0;
   initial hist_cnt = 3'd0;
   initial hist_drop = 8'd0;
   initial abort_cnt = 8'd0;
   initial frame_sig = 16'd0;
   initial ret_stamp = 64'd0;
   initial ret_sum = 16'd0;
   initial ret_st = ST_FREE;
   initial ret_vld = 1'b0;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire [1:0]  hist_last  = hist_wr_ptr - 2'd1;
   wire        hist_empty = (hist_cnt == 3'd0);
   wire        hist_full  = (hist_cnt == HIST_DEPTH);
   // a new record is opened whenever a frame is launched
   wire        hist_push  = !abort_req && (phase == ARMED) && start_req;
   // the record of the frame on screen (running or just finished) may not be acked away
   wire        hist_pin   = (hist_cnt == 3'd1) && ((phase == RUN) || done);
   wire        hist_ack   = wr_en && (wr_addr == HIST_ACK) && !hist_empty && !hist_push && !hist_pin;
   wire        hist_clr   = wr_en && (wr_addr == HIST_CLR) && (phase != RUN) && !done && !hist_push;
   wire        frame_end  = !abort_req && (phase == RUN) && last_col && last_row;
   wire        frame_kill = abort_req && (phase == RUN);
   wire [7:0]  next_pix   = font_row(cur_char, row_cnt[2:0]);
   wire [15:0] next_sig   = {frame_sig[14:0], frame_sig[15] ^ frame_sig[12]} ^ {frame_sig[3:0], 4'h0, next_pix};

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
           for (j = 0; j < 4; j = j + 1) begin
               hist_mem[j] <= 64'd0;
               hist_sum[j] <= 16'd0;
               hist_st[j] <= ST_FREE;
           end
           hist_wr_ptr <= 2'd0;
           hist_rd_ptr <= 2'd0;
           hist_cnt <= 3'd0;
           hist_drop <= 8'd0;
           abort_cnt <= 8'd0;
           frame_sig <= 16'd0;
           ret_stamp <= 64'd0;
           ret_sum <= 16'd0;
           ret_st <= ST_FREE;
           ret_vld <= 1'b0;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
           // ---- frame history ----
           if (hist_push)
               frame_sig <= 16'd0;
           else if (!abort_req && (phase == RUN))
               frame_sig <= next_sig;
           if (hist_push) begin
               hist_mem[hist_wr_ptr] <= frame_cnt + 64'd1;
               hist_sum[hist_wr_ptr] <= 16'd0;
               hist_st[hist_wr_ptr] <= ST_OPEN;
               hist_wr_ptr <= hist_wr_ptr + 2'd1;
               if (hist_full) begin
                   // overwrite the oldest record and account for the loss
                   hist_rd_ptr <= hist_rd_ptr + 2'd1;
                   if (hist_drop != 8'hFF)
                       hist_drop <= hist_drop + 8'd1;
               end else begin
                   hist_cnt <= hist_cnt + 3'd1;
               end
           end else if (hist_ack) begin
               ret_stamp <= hist_mem[hist_rd_ptr];
               ret_sum <= hist_sum[hist_rd_ptr];
               ret_st <= hist_st[hist_rd_ptr];
               ret_vld <= 1'b1;
               hist_st[hist_rd_ptr] <= ST_FREE;
               hist_rd_ptr <= hist_rd_ptr + 2'd1;
               hist_cnt <= hist_cnt - 3'd1;
           end else if (hist_clr) begin
               for (j = 0; j < 4; j = j + 1)
                   hist_st[j] <= ST_FREE;
               hist_rd_ptr <= hist_wr_ptr;
               hist_cnt <= 3'd0;
               ret_vld <= 1'b0;
           end
           if (frame_kill) begin
               hist_st[hist_last] <= ST_ABRT;
               hist_sum[hist_last] <= frame_sig;
               if (abort_cnt != 8'hFF)
                   abort_cnt <= abort_cnt + 8'd1;
           end
           if (frame_end) begin
               hist_st[hist_last] <= ST_DONE;
               hist_sum[hist_last] <= next_sig;
           end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_hist_stamp = hist_empty ? 64'd0 : hist_mem[hist_rd_ptr];
   assign o_hist_sig = hist_empty ? 16'd0 : hist_sum[hist_rd_ptr];
   assign o_hist_state = hist_empty ? ST_FREE : hist_st[hist_rd_ptr];
   assign o_hist_level = hist_cnt;
   assign o_hist_open = !hist_empty && (hist_st[hist_last] == ST_OPEN);
   assign o_last_sig = hist_empty ? 16'd0 : hist_sum[hist_last];
   assign o_hist_drops = hist_drop;
   assign o_abort_cnt = abort_cnt;
   assign o_ret_stamp = ret_stamp;
   assign o_ret_sig = ret_sum;
   assign o_ret_state = ret_st;
   assign o_ret_valid = ret_vld;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);

   always @(posedge clk)
       if (done)
           assert (hist_cnt != 3'd0 && hist_st[hist_last] == ST_DONE && hist_mem[hist_last] == frame_cnt);
endmodule

module axi_cdc_bridge #(
    parameter DEPTH = 24,
    parameter PW = 5
) (
    input  wire        clk,
    input  wire        s_ce,
    input  wire        m_ce,
    input  wire        i_load,
    input  wire [15:0] i_lim,
    input  wire        s_aw_valid,
    input  wire [15:0] s_aw_addr,
    output wire        s_aw_ready,
    output wire        m_aw_valid,
    output wire [15:0] m_aw_addr,
    input  wire        m_aw_ready,
    input  wire        s_w_valid,
    input  wire [15:0] s_w_data,
    output wire        s_w_ready,
    output wire        m_w_valid,
    output wire [15:0] m_w_data,
    input  wire        m_w_ready,
    input  wire        m_b_valid,
    input  wire [15:0] m_b_resp,
    output wire        m_b_ready,
    output wire        s_b_valid,
    output wire [15:0] s_b_resp,
    input  wire        s_b_ready,
    input  wire        s_ar_valid,
    input  wire [15:0] s_ar_addr,
    output wire        s_ar_ready,
    output wire        m_ar_valid,
    output wire [15:0] m_ar_addr,
    input  wire        m_ar_ready,
    input  wire        m_r_valid,
    input  wire [15:0] m_r_data,
    output wire        m_r_ready,
    output wire        s_r_valid,
    output wire [15:0] s_r_data,
    input  wire        s_r_ready
,
    output wire [15:0] lim_o,
    output wire [15:0] occ_w_o,
    output wire [15:0] rc_w_o,
    output wire [PW-1:0] rp_w_o,
    output wire [15:0] wc_w_o,
    output wire [PW-1:0] wp_w_o
);
    localparam [15:0]   DEPTH16 = DEPTH;
    localparam [PW-1:0] LAST    = DEPTH - 1;

    reg [15:0] lim = DEPTH16;

    reg [15:0] mem_aw [0:DEPTH-1];
    reg [15:0] mem_w  [0:DEPTH-1];
    reg [15:0] mem_b  [0:DEPTH-1];
    reg [15:0] mem_ar [0:DEPTH-1];
    reg [15:0] mem_r  [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem_aw[i] = 16'd0;
            mem_w[i]  = 16'd0;
            mem_b[i]  = 16'd0;
            mem_ar[i] = 16'd0;
            mem_r[i]  = 16'd0;
        end
    end

    reg [PW-1:0] wp_aw = 0, rp_aw = 0, wp_w = 0, rp_w = 0, wp_b = 0, rp_b = 0;
    reg [PW-1:0] wp_ar = 0, rp_ar = 0, wp_r = 0, rp_r = 0;
    reg [15:0] wc_aw = 0, rc_aw = 0, occ_aw = 0;
    reg [15:0] wc_w  = 0, rc_w  = 0, occ_w  = 0;
    reg [15:0] wc_b  = 0, rc_b  = 0, occ_b  = 0;
    reg [15:0] wc_ar = 0, rc_ar = 0, occ_ar = 0;
    reg [15:0] wc_r  = 0, rc_r  = 0, occ_r  = 0;

    wire full_aw  = (occ_aw >= lim);
    wire empty_aw = (wc_aw == rc_aw);
    wire full_w   = (occ_w >= lim);
    wire empty_w  = (wc_w == rc_w);
    wire full_b   = (occ_b >= lim);
    wire empty_b  = (wc_b == rc_b);
    wire full_ar  = (occ_ar >= lim);
    wire empty_ar = (wc_ar == rc_ar);
    wire full_r   = (occ_r >= lim);
    wire empty_r  = (wc_r == rc_r);

    wire push_aw = s_ce && s_aw_valid && !full_aw;
    wire pop_aw  = m_ce && m_aw_ready && !empty_aw;
    wire push_w  = s_ce && s_w_valid  && !full_w;
    wire pop_w   = m_ce && m_w_ready  && !empty_w;
    wire push_b  = m_ce && m_b_valid  && !full_b;
    wire pop_b   = s_ce && s_b_ready  && !empty_b;
    wire push_ar = s_ce && s_ar_valid && !full_ar;
    wire pop_ar  = m_ce && m_ar_ready && !empty_ar;
    wire push_r  = m_ce && m_r_valid  && !full_r;
    wire pop_r   = s_ce && s_r_ready  && !empty_r;

    assign s_aw_ready = !full_aw;
    assign m_aw_valid = !empty_aw;
    assign m_aw_addr  = mem_aw[rp_aw];
    assign s_w_ready  = !full_w;
    assign m_w_valid  = !empty_w;
    assign m_w_data   = mem_w[rp_w];
    assign m_b_ready  = !full_b;
    assign s_b_valid  = !empty_b;
    assign s_b_resp   = mem_b[rp_b];
    assign s_ar_ready = !full_ar;
    assign m_ar_valid = !empty_ar;
    assign m_ar_addr  = mem_ar[rp_ar];
    assign m_r_ready  = !full_r;
    assign s_r_valid  = !empty_r;
    assign s_r_data   = mem_r[rp_r];

    wire quiet = (occ_aw == 16'd0) && (occ_w == 16'd0) && (occ_b == 16'd0) && (occ_ar == 16'd0) && (occ_r == 16'd0);

    always @(posedge clk)
        if (i_load && quiet)
            lim <= ((i_lim == 16'd0) || (i_lim > DEPTH16)) ? DEPTH16 : i_lim;

    always @(posedge clk) begin
        if (push_aw) begin
            mem_aw[wp_aw] <= s_aw_addr;
            wp_aw <= (wp_aw == LAST) ? {PW{1'b0}} : wp_aw + 1'b1;
            wc_aw <= wc_aw + 16'd1;
        end
        if (pop_aw) begin
            rp_aw <= (rp_aw == LAST) ? {PW{1'b0}} : rp_aw + 1'b1;
            rc_aw <= rc_aw + 16'd1;
        end
        occ_aw <= occ_aw + {15'd0, push_aw} - {15'd0, pop_aw};
    end

    always @(posedge clk) begin
        if (push_w) begin
            mem_w[wp_w] <= s_w_data;
            wp_w <= (wp_w == LAST) ? {PW{1'b0}} : wp_w + 1'b1;
            wc_w <= wc_w + 16'd1;
        end
        if (pop_w) begin
            rp_w <= (rp_w == LAST) ? {PW{1'b0}} : rp_w + 1'b1;
            rc_w <= rc_w + 16'd1;
        end
        occ_w <= occ_w + {15'd0, push_w} - {15'd0, pop_w};
    end

    always @(posedge clk) begin
        if (push_b) begin
            mem_b[wp_b] <= m_b_resp;
            wp_b <= (wp_b == LAST) ? {PW{1'b0}} : wp_b + 1'b1;
            wc_b <= wc_b + 16'd1;
        end
        if (pop_b) begin
            rp_b <= (rp_b == LAST) ? {PW{1'b0}} : rp_b + 1'b1;
            rc_b <= rc_b + 16'd1;
        end
        occ_b <= occ_b + {15'd0, push_b} - {15'd0, pop_b};
    end

    always @(posedge clk) begin
        if (push_ar) begin
            mem_ar[wp_ar] <= s_ar_addr;
            wp_ar <= (wp_ar == LAST) ? {PW{1'b0}} : wp_ar + 1'b1;
            wc_ar <= wc_ar + 16'd1;
        end
        if (pop_ar) begin
            rp_ar <= (rp_ar == LAST) ? {PW{1'b0}} : rp_ar + 1'b1;
            rc_ar <= rc_ar + 16'd1;
        end
        occ_ar <= occ_ar + {15'd0, push_ar} - {15'd0, pop_ar};
    end

    always @(posedge clk) begin
        if (push_r) begin
            mem_r[wp_r] <= m_r_data;
            wp_r <= (wp_r == LAST) ? {PW{1'b0}} : wp_r + 1'b1;
            wc_r <= wc_r + 16'd1;
        end
        if (pop_r) begin
            rp_r <= (rp_r == LAST) ? {PW{1'b0}} : rp_r + 1'b1;
            rc_r <= rc_r + 16'd1;
        end
        occ_r <= occ_r + {15'd0, push_r} - {15'd0, pop_r};
    end

    reg armed = 1'b0;
    always @(posedge clk)
        if (push_w)
            armed <= 1'b1;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(full_w) && $past(empty_w)));
    assign lim_o = lim;
    assign occ_w_o = occ_w;
    assign rc_w_o = rc_w;
    assign rp_w_o = rp_w;
    assign wc_w_o = wc_w;
    assign wp_w_o = wp_w;
endmodule

module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
,
    output wire [31:0] bitcnt_o,
    output wire busy_o,
    output wire in_frame_o,
    output wire [FRAME_W-1:0] shreg_o
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign in_frame_o = in_frame;
    assign shreg_o = shreg;
endmodule

module axi_uart_tx (
    input wire clk,
    input wire rst_n,
    input wire s_ce, m_ce,
    input wire i_load,
    input wire [15:0] i_lim,
    input wire baud_tick,
    input wire s_aw_valid,
    input wire [15:0] s_aw_addr,
    output wire s_aw_ready,
    input wire s_w_valid,
    input wire [15:0] s_w_data,
    output wire s_w_ready,
    output wire s_b_valid,
    output wire [15:0] s_b_resp,
    input wire s_b_ready,
    input wire s_ar_valid,
    input wire [15:0] s_ar_addr,
    output wire s_ar_ready,
    output wire s_r_valid,
    output wire [15:0] s_r_data,
    input wire s_r_ready,
    output wire txd,
    output wire [15:0] a_lim, a_occ_w, a_rc_w, a_wc_w,
    output wire [4:0] a_rp_w, a_wp_w,
    output wire [31:0] uart_bitcnt,
    output wire uart_busy, uart_in_frame,
    output wire [10:0] uart_shreg,
    output wire [15:0] address_o,
    output wire address_pending_o, tx_wait_o,
    output wire response_pending_o, response_error_o,
    output wire uart_online_o
);
    localparam [15:0] TX_ADDR = 16'h0000;
    localparam [15:0] COUNT_ADDR = 16'h0004;

    wire a_aw_valid, a_aw_ready, a_w_valid, a_w_ready;
    wire [15:0] a_aw_addr, a_w_data;
    wire a_b_valid, a_b_ready;
    wire [15:0] a_b_resp;
    wire a_ar_valid, a_ar_ready, a_r_valid, a_r_ready;
    wire [15:0] a_ar_addr, a_r_data;
    wire uart_valid, uart_ready;

    reg [15:0] address_hold = 16'd0;
    reg address_pending = 1'b0;
    reg tx_wait = 1'b0;
    reg response_pending = 1'b0;
    reg response_error = 1'b0;
    reg uart_online = 1'b0;

    assign address_o = address_hold;
    assign address_pending_o = address_pending;
    assign tx_wait_o = tx_wait;
    assign response_pending_o = response_pending;
    assign response_error_o = response_error;
    assign uart_online_o = uart_online;

    wire address_is_tx = (address_hold == TX_ADDR);
    assign a_aw_ready = uart_online && !address_pending;
    assign a_w_ready = uart_online && address_pending && !tx_wait &&
                       !response_pending && (!address_is_tx || uart_ready);
    assign uart_valid = m_ce && uart_online && address_pending &&
                        !tx_wait && !response_pending && address_is_tx && a_w_valid;
    wire address_take = m_ce && a_aw_valid && a_aw_ready;
    wire write_take = m_ce && a_w_valid && a_w_ready;
    wire uart_take = uart_valid && uart_ready;
    wire write_reject = write_take && !address_is_tx;

    assign a_b_valid = response_pending;
    assign a_b_resp = response_error ? 16'd3 : 16'd0;
    wire response_take = m_ce && a_b_valid && a_b_ready;

    // The read port reports status without disturbing a pending write.
    assign a_r_valid = uart_online && a_ar_valid;
    assign a_ar_ready = uart_online && a_r_ready;
    assign a_r_data = (a_ar_addr == TX_ADDR) ? {15'd0, uart_busy} :
                      (a_ar_addr == COUNT_ADDR) ? uart_bitcnt[15:0] : 16'hffff;

    axi_cdc_bridge bridge (
        .clk(clk), .s_ce(s_ce), .m_ce(m_ce),
        .i_load(i_load), .i_lim(i_lim),
        .s_aw_valid(s_aw_valid), .s_aw_addr(s_aw_addr),
        .s_aw_ready(s_aw_ready),
        .m_aw_valid(a_aw_valid), .m_aw_addr(a_aw_addr),
        .m_aw_ready(a_aw_ready),
        .s_w_valid(s_w_valid), .s_w_data(s_w_data),
        .s_w_ready(s_w_ready),
        .m_w_valid(a_w_valid), .m_w_data(a_w_data),
        .m_w_ready(a_w_ready),
        .m_b_valid(a_b_valid), .m_b_resp(a_b_resp),
        .m_b_ready(a_b_ready),
        .s_b_valid(s_b_valid), .s_b_resp(s_b_resp),
        .s_b_ready(s_b_ready),
        .s_ar_valid(s_ar_valid), .s_ar_addr(s_ar_addr),
        .s_ar_ready(s_ar_ready),
        .m_ar_valid(a_ar_valid), .m_ar_addr(a_ar_addr),
        .m_ar_ready(a_ar_ready),
        .m_r_valid(a_r_valid), .m_r_data(a_r_data),
        .m_r_ready(a_r_ready),
        .s_r_valid(s_r_valid), .s_r_data(s_r_data),
        .s_r_ready(s_r_ready),
        .lim_o(a_lim), .occ_w_o(a_occ_w),
        .rc_w_o(a_rc_w), .rp_w_o(a_rp_w),
        .wc_w_o(a_wc_w), .wp_w_o(a_wp_w)
    );

    uart_tx_word #(.DATA_W(8)) uart (
        .clk(clk), .rst_n(rst_n), .baud_tick(baud_tick),
        .s_valid(uart_valid), .s_ready(uart_ready),
        .s_data(a_w_data[7:0]), .txd(txd), .o_busy(),
        .bitcnt_o(uart_bitcnt), .busy_o(uart_busy),
        .in_frame_o(uart_in_frame), .shreg_o(uart_shreg)
    );

    // Allow the UART and the bus-side join to leave reset together.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            uart_online <= 1'b0;
        else
            uart_online <= 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            address_hold <= 16'd0;
            address_pending <= 1'b0;
            tx_wait <= 1'b0;
            response_pending <= 1'b0;
            response_error <= 1'b0;
        end else if (m_ce) begin
            // AW may run ahead while a previous character is shifting.
            if (address_take) begin
                address_hold <= a_aw_addr;
                address_pending <= 1'b1;
            end
            if (write_take)
                address_pending <= 1'b0;
            if (uart_take) begin
                tx_wait <= 1'b1;
                response_error <= 1'b0;
            end
            if (write_reject) begin
                response_pending <= 1'b1;
                response_error <= 1'b1;
            end
            // Completion is retained until the response FIFO has space.
            if (tx_wait && !uart_busy) begin
                tx_wait <= 1'b0;
                response_pending <= 1'b1;
                response_error <= 1'b0;
            end
            if (response_take)
                response_pending <= 1'b0;
        end
    end

    always @(posedge clk)
        if (response_pending_o && !response_error_o)
            assert (!uart_busy && uart_bitcnt == 32'd11);
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_in_mag,
    input  wire         peer_in_sign,
    output wire         out_peer,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PCW = $clog2(PEER_DEPTH + 1);
    reg [W-1:0] peer_mag [0:PEER_DEPTH-1];
    reg peer_sign [0:PEER_DEPTH-1];
    reg [PCW-1:0] peer_count;
    reg [$clog2(CHANNELS+1)-1:0] grant;
    reg [W-1:0] peer_min1, peer_min2, peer_idx;
    reg peer_parity;
    integer p, j;
    initial begin
        peer_count = 0; grant = 0;
        for (j = 0; j < PEER_DEPTH; j = j + 1) begin peer_mag[j] = {W{1'b1}}; peer_sign[j] = 0; end
    end
    always @(*) begin
        peer_min1 = {W{1'b1}}; peer_min2 = {W{1'b1}}; peer_idx = 0; peer_parity = 0;
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin
            peer_parity = peer_parity ^ peer_sign[p];
            if (peer_mag[p] < peer_min1) begin peer_min2 = peer_min1; peer_min1 = peer_mag[p]; peer_idx = p; end
            else if (peer_mag[p] < peer_min2) peer_min2 = peer_mag[p];
        end
    end

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (grant != 0) || (state == S_DONE) || (peer_count == PEER_DEPTH);
    assign out_peer = (grant == 2'd2) || ((grant == 0) && (state != S_DONE) && (peer_count == PEER_DEPTH));
    assign peer_ready = (peer_count < PEER_DEPTH);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready && !out_peer;
    wire peer_rel = out_valid && out_ready && out_peer;
    always @(posedge clk) begin
        if (peer_valid && peer_ready) begin
            peer_mag[peer_count] <= peer_in_mag; peer_sign[peer_count] <= peer_in_sign;
            peer_count <= peer_count + 1'b1;
        end else if (peer_rel) peer_count <= 0;
        if (out_valid && !out_ready && (grant == 0)) grant <= out_peer ? 2'd2 : 2'd1;
        else if (out_ready) grant <= 0;
    end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = out_peer ? peer_min1 : min1;
    assign out_min2 = out_peer ? peer_min2 : min2;
    assign out_idx  = out_peer ? peer_idx : min_idx;
    assign out_sign = out_peer ? peer_parity : sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
    always @(posedge clk) if (pv && out_valid && out_ready) assert (out_peer ? (peer_count == PEER_DEPTH) : (state == S_DONE));
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
endmodule

module ntt_butterfly #(
    parameter W = 16,
    parameter [15:0] Q = 16'd3329,
    parameter NCOEF = 24,
    parameter STAGES = 5,
    parameter DEPTH = 4
) (
    input  wire         clk,
    input  wire         ce,
    input  wire         load_cfg,
    input  wire [W-1:0] cfg_lat,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_a,
    input  wire [W-1:0] in_b,
    input  wire [W-1:0] in_w,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] out_a,
    output reg  [W-1:0] out_b,
    output wire [$clog2(DEPTH):0] queued,
    output wire         head_cached
);
    localparam NBF = NCOEF / 2;
    localparam ADDR_W = $clog2(DEPTH);
    localparam PTR_W = ADDR_W + 1;
    localparam [ADDR_W-1:0] LAST_SLOT = DEPTH - 1;

    reg [W-1:0] lat_cfg = 16'd4;
    reg [W-1:0] lat_q   = 16'd4;
    reg [W-1:0] cd      = 16'd0;
    reg [W-1:0] phase   = 16'd0;
    reg         busy    = 1'b0;
    reg         armed   = 1'b0;
    reg [W-1:0] a_r     = 16'd0;
    reg [W-1:0] b_r     = 16'd0;
    reg [W-1:0] w_r     = 16'd0;
    reg [W-1:0] bf_idx  = 16'd0;
    reg [W-1:0] stage   = 16'd0;
    reg         pv      = 1'b0;
    reg [W-1:0] q_a [0:DEPTH-1];
    reg [W-1:0] q_b [0:DEPTH-1];
    reg [W-1:0] q_w [0:DEPTH-1];
    reg [W-1:0] q_lat [0:DEPTH-1];
    reg [PTR_W-1:0] q_wr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] q_rd = {PTR_W{1'b0}};
    reg head_valid = 1'b0;
    integer init_slot;
    wire [ADDR_W-1:0] head_slot = q_rd[ADDR_W-1:0];
    wire q_empty = (q_wr == q_rd);
    wire q_full = (q_wr[ADDR_W] != q_rd[ADDR_W]) &&
                  (q_wr[ADDR_W-1:0] == q_rd[ADDR_W-1:0]);
    initial begin
        for (init_slot = 0; init_slot < DEPTH; init_slot = init_slot + 1) begin
            q_a[init_slot] = 16'd0;
            q_b[init_slot] = 16'd0;
            q_w[init_slot] = 16'd0;
            q_lat[init_slot] = 16'd0;
        end
    end
    initial begin out_valid = 1'b0; out_a = 16'd0; out_b = 16'd0; end
    assign queued = (q_wr[ADDR_W] == q_rd[ADDR_W]) ?
        ({1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]}) :
        (DEPTH + {1'b0, q_wr[ADDR_W-1:0]} - {1'b0, q_rd[ADDR_W-1:0]});
    assign head_cached = head_valid;

    assign in_ready = !q_full;
    wire accept = in_valid && in_ready;
    wire [W-1:0] lat_eff = (lat_cfg == 16'd0) ? 16'd1 : lat_cfg;
    wire last = (phase == lat_q - 16'd1);
    wire cache_read = ce && !head_valid && !q_empty;
    wire bypass_head = ce && accept && q_empty;
    wire start = ce && head_valid && !busy && !out_valid;
    wire retire = busy && ce && last;

    wire [31:0] prod = w_r * b_r;
    wire [W-1:0] t = prod % Q;
    wire [16:0] sum = {1'b0, a_r} + {1'b0, t};
    wire [16:0] dif = {1'b0, a_r} + {1'b0, Q} - {1'b0, t};
    wire [W-1:0] sum_mod = (sum >= {1'b0, Q}) ? (sum - {1'b0, Q}) : sum[W-1:0];
    wire [W-1:0] dif_mod = (dif >= {1'b0, Q}) ? (dif - {1'b0, Q}) : dif[W-1:0];
    always @(posedge clk) begin
        if (accept) begin
            q_a[q_wr[ADDR_W-1:0]] <= in_a;
            q_b[q_wr[ADDR_W-1:0]] <= in_b;
            q_w[q_wr[ADDR_W-1:0]] <= in_w;
            q_lat[q_wr[ADDR_W-1:0]] <= lat_eff;
            if (q_wr[ADDR_W-1:0] == LAST_SLOT)
                q_wr <= {!q_wr[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_wr <= q_wr + 1'b1;
        end
        if (retire) begin
            if (q_rd[ADDR_W-1:0] == LAST_SLOT)
                q_rd <= {!q_rd[ADDR_W], {ADDR_W{1'b0}}};
            else
                q_rd <= q_rd + 1'b1;
        end
    end
    always @(posedge clk) begin
        if (cache_read) begin
            a_r <= q_a[head_slot];
            b_r <= q_b[head_slot];
            w_r <= q_w[head_slot];
            lat_q <= q_lat[head_slot];
            head_valid <= 1'b1;
        end else if (bypass_head) begin
            a_r <= in_a;
            b_r <= in_b;
            w_r <= in_w;
            lat_q <= lat_eff;
            head_valid <= 1'b1;
        end else if (retire) begin
            head_valid <= 1'b0;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load_cfg) lat_cfg <= cfg_lat;
        if (start) begin
            cd    <= lat_q;
            phase <= 16'd0;
            busy  <= 1'b1;
            armed <= 1'b1;
        end else if (busy && ce) begin
            if (last) begin
                busy      <= 1'b0;
                cd        <= 16'd0;
                phase     <= 16'd0;
                out_valid <= 1'b1;
                out_a     <= sum_mod;
                out_b     <= dif_mod;
                if (bf_idx == NBF - 1) begin
                    bf_idx <= 16'd0;
                    stage  <= (stage == STAGES - 1) ? 16'd0 : stage + 16'd1;
                end else begin
                    bf_idx <= bf_idx + 16'd1;
                end
            end else begin
                cd    <= cd - 16'd1;
                phase <= phase + 16'd1;
            end
        end
        if (out_valid && out_ready) out_valid <= 1'b0;
    end

    always @(posedge clk) begin
        if (armed && busy)
            assert (cd != 16'd0);
        if (pv && armed && $fell(busy))
            assert ($past(cd) == 16'd1);
    end
endmodule

module rgb_ingress_fifo #(
    parameter W = 32,
    parameter DEPTH = 4
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    output wire s_ready,
    input  wire [7:0] s_r, s_g, s_b,
    input  wire s_first, s_last,
    output wire m_valid,
    input  wire m_ready,
    output wire [7:0] m_r, m_g, m_b,
    output wire m_first, m_last,
    output reg [$clog2(DEPTH+1)-1:0] level,
    output reg [W-1:0] accepted
);
    localparam PTR_W = $clog2(DEPTH);
    reg [7:0] red [0:DEPTH-1];
    reg [7:0] green [0:DEPTH-1];
    reg [7:0] blue [0:DEPTH-1];
    reg [DEPTH-1:0] first_bits = {DEPTH{1'b0}};
    reg [DEPTH-1:0] last_bits = {DEPTH{1'b0}};
    reg [PTR_W-1:0] rd_ptr = {PTR_W{1'b0}};
    reg [PTR_W-1:0] wr_ptr = {PTR_W{1'b0}};
    integer k;
    wire pop = m_valid && m_ready;
    wire push = s_valid && s_ready;
    assign m_valid = level != 0;
    assign s_ready = (level < DEPTH) || pop;
    assign m_r = red[rd_ptr];
    assign m_g = green[rd_ptr];
    assign m_b = blue[rd_ptr];
    assign m_first = first_bits[rd_ptr];
    assign m_last = last_bits[rd_ptr];
    initial begin
        level = 0; accepted = {W{1'b0}};
        for (k = 0; k < DEPTH; k = k + 1) begin
            red[k] = 8'd0; green[k] = 8'd0; blue[k] = 8'd0;
        end
    end
    always @(posedge clk) begin
        if (rst) begin
            level <= 0; accepted <= {W{1'b0}};
            rd_ptr <= {PTR_W{1'b0}}; wr_ptr <= {PTR_W{1'b0}};
            first_bits <= {DEPTH{1'b0}}; last_bits <= {DEPTH{1'b0}};
            for (k = 0; k < DEPTH; k = k + 1) begin
                red[k] <= 8'd0; green[k] <= 8'd0; blue[k] <= 8'd0;
            end
        end else begin
            case ({push, pop})
                2'b10: level <= level + 1'b1;
                2'b01: level <= level - 1'b1;
                default: ;
            endcase
            if (push) begin
                red[wr_ptr] <= s_r;
                green[wr_ptr] <= s_g;
                blue[wr_ptr] <= s_b;
                first_bits[wr_ptr] <= s_first;
                last_bits[wr_ptr] <= s_last;
                accepted <= accepted + 1'b1;
                wr_ptr <= (wr_ptr == DEPTH-1) ? {PTR_W{1'b0}} : wr_ptr + 1'b1;
            end
            if (pop)
                rd_ptr <= (rd_ptr == DEPTH-1) ? {PTR_W{1'b0}} : rd_ptr + 1'b1;
        end
    end
endmodule

module csc_rgb2ycc #(
    parameter W    = 32,
    parameter FRAC = 16,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         cfg_we,
    input  wire [3:0]   cfg_addr,
    input  wire [W-1:0] cfg_data,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [7:0]   i_r,
    input  wire [7:0]   i_g,
    input  wire [7:0]   i_b,
    input  wire         i_first,
    input  wire         i_last,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [7:0]   o_y,
    output reg  [7:0]   o_cb,
    output reg  [7:0]   o_cr,
    output reg          o_last,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] ingress_level,
    output wire [W-1:0] ingress_accepted,
    output reg [31:0] debug_status
);
    localparam signed [W-1:0] OFF_Y = 32'sd32768;
    localparam signed [W-1:0] OFF_C = 32'sd8421376;

    reg signed [W-1:0] c_yr  = 32'sd19595;
    reg signed [W-1:0] c_yg  = 32'sd38470;
    reg signed [W-1:0] c_yb  = 32'sd7471;
    reg signed [W-1:0] c_cbr = -32'sd11056;
    reg signed [W-1:0] c_cbg = -32'sd21712;
    reg signed [W-1:0] c_cbb = 32'sd32768;
    reg signed [W-1:0] c_crr = 32'sd32768;
    reg signed [W-1:0] c_crg = -32'sd27440;
    reg signed [W-1:0] c_crb = -32'sd5328;

    reg [W-1:0] in_cnt  = {W{1'b0}};
    reg [W-1:0] out_cnt = {W{1'b0}};
    reg         armed   = 1'b0;

    initial begin
        o_valid = 1'b0;
        o_y = 8'd0; o_cb = 8'd0; o_cr = 8'd0;
        o_last = 1'b0;
    end
    wire [7:0] ingress_r, ingress_g, ingress_b;
    wire ingress_valid, ingress_first, ingress_last;
    wire converter_ready = !o_valid || o_ready;
    rgb_ingress_fifo #(.W(W), .DEPTH(INGRESS_DEPTH)) ingress_fifo (
        .clk(clk), .rst(rst),
        .s_valid(i_valid), .s_ready(i_ready),
        .s_r(i_r), .s_g(i_g), .s_b(i_b),
        .s_first(i_first), .s_last(i_last),
        .m_valid(ingress_valid), .m_ready(converter_ready),
        .m_r(ingress_r), .m_g(ingress_g), .m_b(ingress_b),
        .m_first(ingress_first), .m_last(ingress_last),
        .level(ingress_level), .accepted(ingress_accepted)
    );

    wire signed [W-1:0] r_s = {{(W-8){1'b0}}, ingress_r};
    wire signed [W-1:0] g_s = {{(W-8){1'b0}}, ingress_g};
    wire signed [W-1:0] b_s = {{(W-8){1'b0}}, ingress_b};

    wire signed [W-1:0] acc_y  = c_yr  * r_s + c_yg  * g_s + c_yb  * b_s + OFF_Y;
    wire signed [W-1:0] acc_cb = c_cbr * r_s + c_cbg * g_s + c_cbb * b_s + OFF_C;
    wire signed [W-1:0] acc_cr = c_crr * r_s + c_crg * g_s + c_crb * b_s + OFF_C;

    function [7:0] sat8;
        input signed [W-1:0] v;
        reg signed [W-1:0] s;
        begin
            s = v >>> FRAC;
            if (s < 0)        sat8 = 8'd0;
            else if (s > 255) sat8 = 8'd255;
            else              sat8 = s[7:0];
        end
    endfunction

    wire in_fire  = ingress_valid && converter_ready;
    wire out_fire = o_valid && o_ready;
    reg [31:0] dbg_cycles, dbg_input_stalls, dbg_output_stalls;
    reg [31:0] dbg_frames, dbg_cfg_writes;
    reg [15:0] dbg_stall_run, dbg_stall_max, dbg_idle_age;
    reg [7:0] dbg_high_water;
    reg [3:0] dbg_flags;
    reg dbg_enable;
    wire dbg_input_blocked = i_valid && !i_ready;
    wire dbg_output_blocked = o_valid && !o_ready;
    wire dbg_clear = cfg_we && (cfg_addr == 4'd15) && cfg_data[0];
    initial begin
        dbg_cycles = 32'd0;
        dbg_input_stalls = 32'd0;
        dbg_output_stalls = 32'd0;
        dbg_frames = 32'd0;
        dbg_cfg_writes = 32'd0;
        dbg_stall_run = 16'd0;
        dbg_stall_max = 16'd0;
        dbg_idle_age = 16'd0;
        dbg_high_water = 8'd0;
        dbg_flags = 4'd0;
        dbg_enable = 1'b1;
        debug_status = 32'd0;
    end
    always @(posedge clk) begin
        if (rst) begin
            dbg_cycles <= 32'd0;
            dbg_input_stalls <= 32'd0;
            dbg_output_stalls <= 32'd0;
            dbg_frames <= 32'd0;
            dbg_cfg_writes <= 32'd0;
            dbg_stall_run <= 16'd0;
            dbg_stall_max <= 16'd0;
            dbg_idle_age <= 16'd0;
            dbg_high_water <= 8'd0;
            dbg_flags <= 4'd0;
            dbg_enable <= 1'b1;
            debug_status <= 32'd0;
        end else begin
            if (cfg_we && cfg_addr == 4'd9)
                dbg_enable <= cfg_data[0];
            if (dbg_clear) begin
                dbg_cycles <= 32'd0;
                dbg_input_stalls <= 32'd0;
                dbg_output_stalls <= 32'd0;
                dbg_frames <= 32'd0;
                dbg_cfg_writes <= 32'd0;
                dbg_stall_run <= 16'd0;
                dbg_stall_max <= 16'd0;
                dbg_idle_age <= 16'd0;
                dbg_high_water <= 8'd0;
                dbg_flags <= 4'd0;
            end else if (dbg_enable) begin
                if (!(&dbg_cycles))
                    dbg_cycles <= dbg_cycles + 32'd1;
                if (dbg_input_blocked && !(&dbg_input_stalls))
                    dbg_input_stalls <= dbg_input_stalls + 32'd1;
                if (dbg_output_blocked && !(&dbg_output_stalls))
                    dbg_output_stalls <= dbg_output_stalls + 32'd1;
                if (out_fire && o_last && !(&dbg_frames))
                    dbg_frames <= dbg_frames + 32'd1;
                if (cfg_we && cfg_addr <= 4'd8 && !(&dbg_cfg_writes))
                    dbg_cfg_writes <= dbg_cfg_writes + 32'd1;
                if (ingress_level > dbg_high_water)
                    dbg_high_water <= (ingress_level > 255) ? 8'hff : ingress_level;
                if (dbg_output_blocked) begin
                    if (!(&dbg_stall_run))
                        dbg_stall_run <= dbg_stall_run + 16'd1;
                    if (dbg_stall_run >= dbg_stall_max && !(&dbg_stall_run))
                        dbg_stall_max <= dbg_stall_run + 16'd1;
                end else
                    dbg_stall_run <= 16'd0;
                if ((ingress_valid || o_valid) && !out_fire) begin
                    if (!(&dbg_idle_age))
                        dbg_idle_age <= dbg_idle_age + 16'd1;
                    if (&dbg_idle_age)
                        dbg_flags[2] <= 1'b1;
                end else
                    dbg_idle_age <= 16'd0;
                if (dbg_input_blocked)
                    dbg_flags[0] <= 1'b1;
                if (dbg_output_blocked)
                    dbg_flags[1] <= 1'b1;
                if (cfg_we && armed)
                    dbg_flags[3] <= 1'b1;
            end
            case (cfg_addr)
                4'd9: debug_status <= {31'd0, dbg_enable};
                4'd10: debug_status <= dbg_cycles;
                4'd11: debug_status <= dbg_input_stalls;
                4'd12: debug_status <= dbg_output_stalls;
                4'd13: debug_status <= dbg_frames;
                4'd14: debug_status <= {dbg_stall_max, dbg_stall_run};
                4'd15: debug_status <= {dbg_high_water, dbg_flags, 4'd0, dbg_idle_age};
                default: debug_status <= dbg_cfg_writes;
            endcase
        end
    end

    always @(posedge clk) begin
        if (cfg_we) begin
            case (cfg_addr)
                4'd0: c_yr  <= cfg_data;
                4'd1: c_yg  <= cfg_data;
                4'd2: c_yb  <= cfg_data;
                4'd3: c_cbr <= cfg_data;
                4'd4: c_cbg <= cfg_data;
                4'd5: c_cbb <= cfg_data;
                4'd6: c_crr <= cfg_data;
                4'd7: c_crg <= cfg_data;
                4'd8: c_crb <= cfg_data;
                default: ;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0;
            in_cnt  <= {W{1'b0}};
            out_cnt <= {W{1'b0}};
            armed   <= 1'b0;
            o_last  <= 1'b0;
        end else begin
            if (in_fire) begin
                in_cnt <= in_cnt + 32'd1;
                o_y    <= sat8(acc_y);
                o_cb   <= sat8(acc_cb);
                o_cr   <= sat8(acc_cr);
                o_last <= ingress_last;
            end
            if (out_fire)
                out_cnt <= out_cnt + 32'd1;
            if (in_fire)
                o_valid <= 1'b1;
            else if (out_fire)
                o_valid <= 1'b0;
            if (in_fire && ingress_first)
                armed <= 1'b1;
            else if (out_fire && o_last)
                armed <= 1'b0;
        end
    end

    wire [W-1:0] occ = in_cnt - out_cnt;

    always @(posedge clk) assert (!armed || occ <= 32'd1);
    wire [W-1:0] ingress_pending = ingress_accepted - out_cnt;
    always @(posedge clk) assert (!armed || ingress_pending <= INGRESS_DEPTH + 1);
endmodule

module uart_word_formatter #(
   parameter WORD_W = 16,
   parameter WORDS = (WORD_W / 4) + 4,
   parameter IW = $clog2(WORDS),
   parameter CW = $clog2(WORDS + 1)
) (
   input  wire                    clk,
   input  wire                    rst_n,
   input  wire                    ce,
   input  wire                    in_valid,
   output wire                    in_ready,
   input  wire [WORD_W-1:0]       in_word,
   input  wire                    in_packet,
   output wire                    byte_valid,
   input  wire                    byte_ready,
   output wire [WORD_W-1:0]       byte_data,
   input  wire                    tx_busy,
   output wire                    done,
   input  wire                    done_ready,
   output wire [1:0]              state_o,
   output wire [IW-1:0]           pos_o,
   output wire [CW-1:0]           span_o,
   output reg  [WORD_W*WORDS-1:0] words_o
);
   localparam DIGITS = WORD_W / 4;
   localparam [1:0] IDLE = 2'd0;
   localparam [1:0] SEND = 2'd1;
   localparam [1:0] WAIT_BYTE = 2'd2;
   localparam [1:0] DONE = 2'd3;
   localparam [CW-1:0] FULL_SPAN = WORDS;

   reg [1:0] state = IDLE;
   reg [IW-1:0] pos = 0;
   reg [CW-1:0] span = 1;
   reg [WORD_W-1:0] frame [0:WORDS-1];
   reg [WORD_W-1:0] encoded [0:WORDS-1];
   integer init_idx;
   integer build_idx;
   integer seq_idx;

   initial begin
       for (init_idx = 0; init_idx < WORDS; init_idx = init_idx + 1)
           frame[init_idx] = 0;
   end

   function [WORD_W-1:0] hex_symbol;
       input [3:0] nibble;
       begin
           if (nibble < 4'd10)
               hex_symbol = 16'h0030 + nibble;
           else
               hex_symbol = 16'h0041 + nibble - 16'd10;
       end
   endfunction

   // CRC-8/ATM, most significant payload bit first.
   function [7:0] crc_word;
       input [WORD_W-1:0] word;
       reg [7:0] residue;
       reg feedback;
       integer bit_idx;
       begin
           residue = 8'd0;
           feedback = 1'b0;
           for (bit_idx = WORD_W - 1; bit_idx >= 0; bit_idx = bit_idx - 1) begin
               feedback = residue[7] ^ word[bit_idx];
               residue = {residue[6:0], 1'b0};
               if (feedback)
                   residue = residue ^ 8'h07;
           end
           crc_word = residue;
       end
   endfunction

   wire [7:0] input_crc = crc_word(in_word);
   wire input_take = in_valid && in_ready;
   wire byte_take = byte_valid && byte_ready;

   assign in_ready = (state == IDLE);
   assign byte_valid = (state == SEND);
   assign byte_data = frame[pos];
   assign done = (state == DONE);
   assign state_o = state;
   assign pos_o = pos;
   assign span_o = span;

   // A packet carries the complete word and its checksum as printable text.
   // Raw writes use the same completion machinery, but only one symbol.
   always @(*) begin
       for (build_idx = 0; build_idx < WORDS; build_idx = build_idx + 1) begin
           encoded[build_idx] = 0;
           words_o[build_idx*WORD_W +: WORD_W] = frame[build_idx];
       end
       encoded[0] = 16'h003a;
       for (build_idx = 0; build_idx < DIGITS; build_idx = build_idx + 1)
           encoded[build_idx + 1] =
               hex_symbol(in_word[(DIGITS-1-build_idx)*4 +: 4]);
       encoded[DIGITS + 1] = hex_symbol(input_crc[7:4]);
       encoded[DIGITS + 2] = hex_symbol(input_crc[3:0]);
       encoded[WORDS - 1] = 16'h000a;
       if (!in_packet) begin
           for (build_idx = 0; build_idx < WORDS; build_idx = build_idx + 1)
               encoded[build_idx] = 0;
           encoded[0] = {8'd0, in_word[7:0]};
       end
   end

   always @(posedge clk or negedge rst_n) begin
       if (!rst_n) begin
           state <= IDLE;
           pos <= 0;
           span <= 1;
           for (seq_idx = 0; seq_idx < WORDS; seq_idx = seq_idx + 1)
               frame[seq_idx] <= 0;
       end else if (ce) begin
           case (state)
               IDLE: begin
                   if (input_take) begin
                       for (seq_idx = 0; seq_idx < WORDS; seq_idx = seq_idx + 1)
                           frame[seq_idx] <= encoded[seq_idx];
                       pos <= 0;
                       span <= in_packet ? FULL_SPAN : 1;
                       state <= SEND;
                   end
               end
               SEND: begin
                   // Acceptance is not completion: retain the frame until
                   // the UART has shifted the accepted symbol's stop bit.
                   if (byte_take)
                       state <= WAIT_BYTE;
               end
               WAIT_BYTE: begin
                   if (!tx_busy) begin
                       if (({1'b0, pos} + 1'b1) == span) begin
                           state <= DONE;
                       end else begin
                           pos <= pos + 1'b1;
                           state <= SEND;
                       end
                   end
               end
               DONE: begin
                   // Keep completion and the encoded frame until acknowledged.
                   if (done_ready)
                       state <= IDLE;
               end
           endcase
       end
   end
endmodule

module axi_cdc_bridge #(
    parameter DEPTH = 24,
    parameter PW = 5
) (
    input  wire        clk,
    input  wire        s_ce,
    input  wire        m_ce,
    input  wire        i_load,
    input  wire [15:0] i_lim,
    input  wire        s_aw_valid,
    input  wire [15:0] s_aw_addr,
    output wire        s_aw_ready,
    output wire        m_aw_valid,
    output wire [15:0] m_aw_addr,
    input  wire        m_aw_ready,
    input  wire        s_w_valid,
    input  wire [15:0] s_w_data,
    output wire        s_w_ready,
    output wire        m_w_valid,
    output wire [15:0] m_w_data,
    input  wire        m_w_ready,
    input  wire        m_b_valid,
    input  wire [15:0] m_b_resp,
    output wire        m_b_ready,
    output wire        s_b_valid,
    output wire [15:0] s_b_resp,
    input  wire        s_b_ready,
    input  wire        s_ar_valid,
    input  wire [15:0] s_ar_addr,
    output wire        s_ar_ready,
    output wire        m_ar_valid,
    output wire [15:0] m_ar_addr,
    input  wire        m_ar_ready,
    input  wire        m_r_valid,
    input  wire [15:0] m_r_data,
    output wire        m_r_ready,
    output wire        s_r_valid,
    output wire [15:0] s_r_data,
    input  wire        s_r_ready
,
    output wire [15:0] lim_o,
    output wire [15:0] occ_w_o,
    output wire [15:0] rc_w_o,
    output wire [PW-1:0] rp_w_o,
    output wire [15:0] wc_w_o,
    output wire [PW-1:0] wp_w_o
);
    localparam [15:0]   DEPTH16 = DEPTH;
    localparam [PW-1:0] LAST    = DEPTH - 1;

    reg [15:0] lim = DEPTH16;

    reg [15:0] mem_aw [0:DEPTH-1];
    reg [15:0] mem_w  [0:DEPTH-1];
    reg [15:0] mem_b  [0:DEPTH-1];
    reg [15:0] mem_ar [0:DEPTH-1];
    reg [15:0] mem_r  [0:DEPTH-1];
    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            mem_aw[i] = 16'd0;
            mem_w[i]  = 16'd0;
            mem_b[i]  = 16'd0;
            mem_ar[i] = 16'd0;
            mem_r[i]  = 16'd0;
        end
    end

    reg [PW-1:0] wp_aw = 0, rp_aw = 0, wp_w = 0, rp_w = 0, wp_b = 0, rp_b = 0;
    reg [PW-1:0] wp_ar = 0, rp_ar = 0, wp_r = 0, rp_r = 0;
    reg [15:0] wc_aw = 0, rc_aw = 0, occ_aw = 0;
    reg [15:0] wc_w  = 0, rc_w  = 0, occ_w  = 0;
    reg [15:0] wc_b  = 0, rc_b  = 0, occ_b  = 0;
    reg [15:0] wc_ar = 0, rc_ar = 0, occ_ar = 0;
    reg [15:0] wc_r  = 0, rc_r  = 0, occ_r  = 0;

    wire full_aw  = (occ_aw >= lim);
    wire empty_aw = (wc_aw == rc_aw);
    wire full_w   = (occ_w >= lim);
    wire empty_w  = (wc_w == rc_w);
    wire full_b   = (occ_b >= lim);
    wire empty_b  = (wc_b == rc_b);
    wire full_ar  = (occ_ar >= lim);
    wire empty_ar = (wc_ar == rc_ar);
    wire full_r   = (occ_r >= lim);
    wire empty_r  = (wc_r == rc_r);

    wire push_aw = s_ce && s_aw_valid && !full_aw;
    wire pop_aw  = m_ce && m_aw_ready && !empty_aw;
    wire push_w  = s_ce && s_w_valid  && !full_w;
    wire pop_w   = m_ce && m_w_ready  && !empty_w;
    wire push_b  = m_ce && m_b_valid  && !full_b;
    wire pop_b   = s_ce && s_b_ready  && !empty_b;
    wire push_ar = s_ce && s_ar_valid && !full_ar;
    wire pop_ar  = m_ce && m_ar_ready && !empty_ar;
    wire push_r  = m_ce && m_r_valid  && !full_r;
    wire pop_r   = s_ce && s_r_ready  && !empty_r;

    assign s_aw_ready = !full_aw;
    assign m_aw_valid = !empty_aw;
    assign m_aw_addr  = mem_aw[rp_aw];
    assign s_w_ready  = !full_w;
    assign m_w_valid  = !empty_w;
    assign m_w_data   = mem_w[rp_w];
    assign m_b_ready  = !full_b;
    assign s_b_valid  = !empty_b;
    assign s_b_resp   = mem_b[rp_b];
    assign s_ar_ready = !full_ar;
    assign m_ar_valid = !empty_ar;
    assign m_ar_addr  = mem_ar[rp_ar];
    assign m_r_ready  = !full_r;
    assign s_r_valid  = !empty_r;
    assign s_r_data   = mem_r[rp_r];

    wire quiet = (occ_aw == 16'd0) && (occ_w == 16'd0) && (occ_b == 16'd0) && (occ_ar == 16'd0) && (occ_r == 16'd0);

    always @(posedge clk)
        if (i_load && quiet)
            lim <= ((i_lim == 16'd0) || (i_lim > DEPTH16)) ? DEPTH16 : i_lim;

    always @(posedge clk) begin
        if (push_aw) begin
            mem_aw[wp_aw] <= s_aw_addr;
            wp_aw <= (wp_aw == LAST) ? {PW{1'b0}} : wp_aw + 1'b1;
            wc_aw <= wc_aw + 16'd1;
        end
        if (pop_aw) begin
            rp_aw <= (rp_aw == LAST) ? {PW{1'b0}} : rp_aw + 1'b1;
            rc_aw <= rc_aw + 16'd1;
        end
        occ_aw <= occ_aw + {15'd0, push_aw} - {15'd0, pop_aw};
    end

    always @(posedge clk) begin
        if (push_w) begin
            mem_w[wp_w] <= s_w_data;
            wp_w <= (wp_w == LAST) ? {PW{1'b0}} : wp_w + 1'b1;
            wc_w <= wc_w + 16'd1;
        end
        if (pop_w) begin
            rp_w <= (rp_w == LAST) ? {PW{1'b0}} : rp_w + 1'b1;
            rc_w <= rc_w + 16'd1;
        end
        occ_w <= occ_w + {15'd0, push_w} - {15'd0, pop_w};
    end

    always @(posedge clk) begin
        if (push_b) begin
            mem_b[wp_b] <= m_b_resp;
            wp_b <= (wp_b == LAST) ? {PW{1'b0}} : wp_b + 1'b1;
            wc_b <= wc_b + 16'd1;
        end
        if (pop_b) begin
            rp_b <= (rp_b == LAST) ? {PW{1'b0}} : rp_b + 1'b1;
            rc_b <= rc_b + 16'd1;
        end
        occ_b <= occ_b + {15'd0, push_b} - {15'd0, pop_b};
    end

    always @(posedge clk) begin
        if (push_ar) begin
            mem_ar[wp_ar] <= s_ar_addr;
            wp_ar <= (wp_ar == LAST) ? {PW{1'b0}} : wp_ar + 1'b1;
            wc_ar <= wc_ar + 16'd1;
        end
        if (pop_ar) begin
            rp_ar <= (rp_ar == LAST) ? {PW{1'b0}} : rp_ar + 1'b1;
            rc_ar <= rc_ar + 16'd1;
        end
        occ_ar <= occ_ar + {15'd0, push_ar} - {15'd0, pop_ar};
    end

    always @(posedge clk) begin
        if (push_r) begin
            mem_r[wp_r] <= m_r_data;
            wp_r <= (wp_r == LAST) ? {PW{1'b0}} : wp_r + 1'b1;
            wc_r <= wc_r + 16'd1;
        end
        if (pop_r) begin
            rp_r <= (rp_r == LAST) ? {PW{1'b0}} : rp_r + 1'b1;
            rc_r <= rc_r + 16'd1;
        end
        occ_r <= occ_r + {15'd0, push_r} - {15'd0, pop_r};
    end

    reg armed = 1'b0;
    always @(posedge clk)
        if (push_w)
            armed <= 1'b1;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(full_w) && $past(empty_w)));
    assign lim_o = lim;
    assign occ_w_o = occ_w;
    assign rc_w_o = rc_w;
    assign rp_w_o = rp_w;
    assign wc_w_o = wc_w;
    assign wp_w_o = wp_w;
endmodule

module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
,
    output wire [31:0] bitcnt_o,
    output wire busy_o,
    output wire in_frame_o,
    output wire [FRAME_W-1:0] shreg_o
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign in_frame_o = in_frame;
    assign shreg_o = shreg;
endmodule

module axi_uart_tx (
    input wire clk,
    input wire rst_n,
    input wire s_ce, m_ce,
    input wire i_load,
    input wire [15:0] i_lim,
    input wire baud_tick,
    input wire s_aw_valid,
    input wire [15:0] s_aw_addr,
    output wire s_aw_ready,
    input wire s_w_valid,
    input wire [15:0] s_w_data,
    output wire s_w_ready,
    output wire s_b_valid,
    output wire [15:0] s_b_resp,
    input wire s_b_ready,
    input wire s_ar_valid,
    input wire [15:0] s_ar_addr,
    output wire s_ar_ready,
    output wire s_r_valid,
    output wire [15:0] s_r_data,
    input wire s_r_ready,
    output wire txd,
    output wire [15:0] a_lim, a_occ_w, a_rc_w, a_wc_w,
    output wire [4:0] a_rp_w, a_wp_w,
    output wire [31:0] uart_bitcnt,
    output wire uart_busy, uart_in_frame,
    output wire [10:0] uart_shreg,
    output wire [15:0] address_o,
    output wire address_pending_o, tx_wait_o,
    output wire response_pending_o, response_error_o,
   output wire uart_online_o,
   output wire [1:0] format_state_o,
   output wire [FORMAT_PW-1:0] format_pos_o,
   output wire [FORMAT_CW-1:0] format_span_o,
   output wire [16*FORMAT_WORDS-1:0] format_words_o
);
    localparam [15:0] TX_ADDR = 16'h0000;
    localparam [15:0] COUNT_ADDR = 16'h0004;
   localparam [15:0] PACKET_ADDR = 16'h0008;
   localparam FORMAT_WORDS = 8;
   localparam FORMAT_PW = $clog2(FORMAT_WORDS);
   localparam FORMAT_CW = $clog2(FORMAT_WORDS + 1);

    wire a_aw_valid, a_aw_ready, a_w_valid, a_w_ready;
    wire [15:0] a_aw_addr, a_w_data;
    wire a_b_valid, a_b_ready;
    wire [15:0] a_b_resp;
    wire a_ar_valid, a_ar_ready, a_r_valid, a_r_ready;
    wire [15:0] a_ar_addr, a_r_data;
    wire uart_valid, uart_ready;
   wire format_input_valid, format_input_ready;
   wire format_output_valid, format_done;
   wire [15:0] format_output_data;

    reg [15:0] address_hold = 16'd0;
    reg address_pending = 1'b0;
    reg tx_wait = 1'b0;
    reg response_pending = 1'b0;
    reg response_error = 1'b0;
    reg uart_online = 1'b0;

    assign address_o = address_hold;
    assign address_pending_o = address_pending;
    assign tx_wait_o = tx_wait;
    assign response_pending_o = response_pending;
    assign response_error_o = response_error;
    assign uart_online_o = uart_online;

    wire address_is_tx = (address_hold == TX_ADDR);
   wire address_is_packet = (address_hold == PACKET_ADDR);
   wire address_is_serial = address_is_tx || address_is_packet;
   assign format_input_valid = uart_online && address_pending &&
                               !tx_wait && !response_pending &&
                               address_is_serial && a_w_valid;
    assign a_aw_ready = uart_online && !address_pending;
   assign a_w_ready = uart_online && address_pending && !tx_wait &&
                      !response_pending && (!address_is_serial || format_input_ready);
   assign uart_valid = m_ce && uart_online && format_output_valid;
    wire address_take = m_ce && a_aw_valid && a_aw_ready;
    wire write_take = m_ce && a_w_valid && a_w_ready;
   wire format_take = write_take && address_is_serial;
   wire write_reject = write_take && !address_is_serial;

    assign a_b_valid = response_pending;
    assign a_b_resp = response_error ? 16'd3 : 16'd0;
    wire response_take = m_ce && a_b_valid && a_b_ready;

    // The read port reports status without disturbing a pending write.
    assign a_r_valid = uart_online && a_ar_valid;
    assign a_ar_ready = uart_online && a_r_ready;
    assign a_r_data = (a_ar_addr == TX_ADDR) ? {15'd0, uart_busy} :
                      (a_ar_addr == COUNT_ADDR) ? uart_bitcnt[15:0] : 16'hffff;

    axi_cdc_bridge bridge (
        .clk(clk), .s_ce(s_ce), .m_ce(m_ce),
        .i_load(i_load), .i_lim(i_lim),
        .s_aw_valid(s_aw_valid), .s_aw_addr(s_aw_addr),
        .s_aw_ready(s_aw_ready),
        .m_aw_valid(a_aw_valid), .m_aw_addr(a_aw_addr),
        .m_aw_ready(a_aw_ready),
        .s_w_valid(s_w_valid), .s_w_data(s_w_data),
        .s_w_ready(s_w_ready),
        .m_w_valid(a_w_valid), .m_w_data(a_w_data),
        .m_w_ready(a_w_ready),
        .m_b_valid(a_b_valid), .m_b_resp(a_b_resp),
        .m_b_ready(a_b_ready),
        .s_b_valid(s_b_valid), .s_b_resp(s_b_resp),
        .s_b_ready(s_b_ready),
        .s_ar_valid(s_ar_valid), .s_ar_addr(s_ar_addr),
        .s_ar_ready(s_ar_ready),
        .m_ar_valid(a_ar_valid), .m_ar_addr(a_ar_addr),
        .m_ar_ready(a_ar_ready),
        .m_r_valid(a_r_valid), .m_r_data(a_r_data),
        .m_r_ready(a_r_ready),
        .s_r_valid(s_r_valid), .s_r_data(s_r_data),
        .s_r_ready(s_r_ready),
        .lim_o(a_lim), .occ_w_o(a_occ_w),
        .rc_w_o(a_rc_w), .rp_w_o(a_rp_w),
        .wc_w_o(a_wc_w), .wp_w_o(a_wp_w)
    );

    uart_tx_word #(.DATA_W(8)) uart (
        .clk(clk), .rst_n(rst_n), .baud_tick(baud_tick),
        .s_valid(uart_valid), .s_ready(uart_ready),
       .s_data(format_output_data[7:0]), .txd(txd), .o_busy(),
        .bitcnt_o(uart_bitcnt), .busy_o(uart_busy),
        .in_frame_o(uart_in_frame), .shreg_o(uart_shreg)
    );

   uart_word_formatter #(
       .WORD_W(16), .WORDS(FORMAT_WORDS),
       .IW(FORMAT_PW), .CW(FORMAT_CW)
   ) formatter (
       .clk(clk), .rst_n(rst_n), .ce(m_ce),
       .in_valid(format_input_valid), .in_ready(format_input_ready),
       .in_word(a_w_data), .in_packet(address_is_packet),
       .byte_valid(format_output_valid),
       .byte_ready(uart_online && uart_ready),
       .byte_data(format_output_data), .tx_busy(uart_busy),
       .done(format_done), .done_ready(tx_wait),
       .state_o(format_state_o), .pos_o(format_pos_o),
       .span_o(format_span_o), .words_o(format_words_o)
   );

    // Allow the UART and the bus-side join to leave reset together.
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            uart_online <= 1'b0;
        else
            uart_online <= 1'b1;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            address_hold <= 16'd0;
            address_pending <= 1'b0;
            tx_wait <= 1'b0;
            response_pending <= 1'b0;
            response_error <= 1'b0;
        end else if (m_ce) begin
            // AW may run ahead while a previous character is shifting.
            if (address_take) begin
                address_hold <= a_aw_addr;
                address_pending <= 1'b1;
            end
            if (write_take)
                address_pending <= 1'b0;
           if (format_take) begin
                tx_wait <= 1'b1;
                response_error <= 1'b0;
            end
            if (write_reject) begin
                response_pending <= 1'b1;
                response_error <= 1'b1;
            end
            // Completion is retained until the response FIFO has space.
           if (tx_wait && format_done) begin
                tx_wait <= 1'b0;
                response_pending <= 1'b1;
                response_error <= 1'b0;
            end
            if (response_take)
                response_pending <= 1'b0;
        end
    end

    always @(posedge clk)
        if (response_pending_o && !response_error_o)
            assert (!uart_busy && uart_bitcnt == 32'd11);
endmodule

module ldpc_edge_ingress #(
    parameter W = 32,
    parameter FRAME = 24,
    parameter DEPTH = 4,
    parameter IW = $clog2(FRAME),
    parameter CW = $clog2(DEPTH + 1)
) (
    input wire clk,
    input wire offer,
    output wire ready,
    input wire [W-1:0] mag_i,
    input wire sign_i,
    input wire take,
    output wire valid,
    output wire [W-1:0] mag_o,
    output wire sign_o,
    output wire [IW-1:0] index_o,
    output reg [CW-1:0] queued,
    output reg [IW-1:0] next_idx,
    output wire [DEPTH*IW-1:0] queued_idx
);
    reg [W-1:0] magnitude [0:DEPTH-1];
    reg polarity [0:DEPTH-1];
    reg [IW-1:0] edge_index [0:DEPTH-1];
    integer i, n;
    wire pop = valid && take;
    wire push = offer && ready;
    assign valid = (queued != 0);
    assign ready = (queued < DEPTH) || pop;
    assign mag_o = magnitude[0];
    assign sign_o = polarity[0];
    assign index_o = edge_index[0];
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin: export_tags
            assign queued_idx[g*IW +: IW] = edge_index[g];
        end
    endgenerate
    initial begin
        queued = 0;
        next_idx = 0;
        for (n = 0; n < DEPTH; n = n + 1) begin
            magnitude[n] = {W{1'b0}};
            polarity[n] = 1'b0;
            edge_index[n] = 0;
        end
    end
    always @(posedge clk) begin
        case ({push, pop})
            2'b10: queued <= queued + 1'b1;
            2'b01: queued <= queued - 1'b1;
            default: queued <= queued;
        endcase
        if (pop) begin
            for (i = 0; i < DEPTH-1; i = i + 1) begin
                magnitude[i] <= magnitude[i+1];
                polarity[i] <= polarity[i+1];
                edge_index[i] <= edge_index[i+1];
            end
        end
        if (push) begin
            magnitude[queued - pop] <= mag_i;
            polarity[queued - pop] <= sign_i;
            edge_index[queued - pop] <= next_idx;
            if (next_idx == FRAME - 1)
                next_idx <= 0;
            else
                next_idx <= next_idx + 1'b1;
        end
    end
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32,
    parameter INGRESS_DEPTH = 4
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    input  wire         peer_valid,
    output wire         peer_ready,
    input  wire [W-1:0] peer_in_mag,
    input  wire         peer_in_sign,
    output wire         out_peer,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag,
    output wire [$clog2(INGRESS_DEPTH+1)-1:0] pending_edges
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;
    localparam CHANNELS = 2, PEER_DEPTH = 4;
    localparam PCW = $clog2(PEER_DEPTH + 1);
    reg [W-1:0] peer_mag [0:PEER_DEPTH-1];
    reg peer_sign [0:PEER_DEPTH-1];
    reg [PCW-1:0] peer_count;
    reg [$clog2(CHANNELS+1)-1:0] grant;
    reg [W-1:0] peer_min1, peer_min2, peer_idx;
    reg peer_parity;
    integer p, j;
    initial begin
        peer_count = 0; grant = 0;
        for (j = 0; j < PEER_DEPTH; j = j + 1) begin peer_mag[j] = {W{1'b1}}; peer_sign[j] = 0; end
    end
    always @(*) begin
        peer_min1 = {W{1'b1}}; peer_min2 = {W{1'b1}}; peer_idx = 0; peer_parity = 0;
        for (p = 0; p < PEER_DEPTH; p = p + 1) begin
            peer_parity = peer_parity ^ peer_sign[p];
            if (peer_mag[p] < peer_min1) begin peer_min2 = peer_min1; peer_min1 = peer_mag[p]; peer_idx = p; end
            else if (peer_mag[p] < peer_min2) peer_min2 = peer_mag[p];
        end
    end

    localparam IIW = $clog2(DEG);
    wire ingress_valid, ingress_sign;
    wire [W-1:0] ingress_mag;
    wire [IIW-1:0] ingress_idx, ingress_next_idx;
    wire [INGRESS_DEPTH*IIW-1:0] ingress_tags;
    wire ingress_take = (state == S_ACCUM);
    ldpc_edge_ingress #(
        .W(W), .FRAME(DEG), .DEPTH(INGRESS_DEPTH)
    ) ingress (
        .clk(clk), .offer(in_valid), .ready(in_ready),
        .mag_i(in_mag), .sign_i(in_sign), .take(ingress_take),
        .valid(ingress_valid), .mag_o(ingress_mag),
        .sign_o(ingress_sign), .index_o(ingress_idx),
        .queued(pending_edges), .next_idx(ingress_next_idx),
        .queued_idx(ingress_tags)
    );
    assign out_valid = (grant != 0) || (state == S_DONE) || (peer_count == PEER_DEPTH);
    assign out_peer = (grant == 2'd2) || ((grant == 0) && (state != S_DONE) && (peer_count == PEER_DEPTH));
    assign peer_ready = (peer_count < PEER_DEPTH);
    wire acc = ingress_valid && ingress_take;
    wire rel = out_valid && out_ready && !out_peer;
    wire peer_rel = out_valid && out_ready && out_peer;
    always @(posedge clk) begin
        if (peer_valid && peer_ready) begin
            peer_mag[peer_count] <= peer_in_mag; peer_sign[peer_count] <= peer_in_sign;
            peer_count <= peer_count + 1'b1;
        end else if (peer_rel) peer_count <= 0;
        if (out_valid && !out_ready && (grant == 0)) grant <= out_peer ? 2'd2 : 2'd1;
        else if (out_ready) grant <= 0;
    end

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ ingress_sign;
            if (ingress_mag < min1) begin
                min2    <= min1;
                min1    <= ingress_mag;
                min_idx <= ingress_idx;
            end else if (ingress_mag < min2) begin
                min2 <= ingress_mag;
            end
            if (ingress_idx == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = out_peer ? peer_min1 : min1;
    assign out_min2 = out_peer ? peer_min2 : min2;
    assign out_idx  = out_peer ? peer_idx : min_idx;
    assign out_sign = out_peer ? peer_parity : sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
    always @(posedge clk) if (pv && out_valid && out_ready) assert (out_peer ? (peer_count == PEER_DEPTH) : (state == S_DONE));
    always @(posedge clk) if (pv && rel && ingress_valid) assert (ingress_idx == 0);
endmodule

module div3_serial_checker (
    input  wire clk,
    input  wire i_ce,
    input  wire i_arm,
    input  wire i_start,
    input  wire i_bit,
    output wire o_verdict,
    output wire o_done
);
    parameter WIDTH = 32;

    typedef enum logic [1:0] {IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3} ctl_t;
    typedef enum logic [1:0] {R0 = 2'd0, R1 = 2'd1, R2 = 2'd2} rem_t;

    ctl_t ctl = IDLE;
    rem_t rem = R0;
    reg [WIDTH-1:0] value = {WIDTH{1'b0}};
    reg [WIDTH-1:0] nbits = {WIDTH{1'b0}};
    reg armed = 1'b0;
    reg started = 1'b0;

    rem_t rem_next;
    always @(*) begin
        case (rem)
            R0: rem_next = i_bit ? R1 : R0;
            R1: rem_next = i_bit ? R0 : R2;
            R2: rem_next = i_bit ? R2 : R1;
            default: rem_next = R0;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            case (ctl)
                IDLE: begin
                    if (i_arm) begin
                        ctl   <= ARMED;
                        armed <= 1'b1;
                    end
                end
                ARMED: begin
                    if (i_start) begin
                        ctl     <= RUN;
                        started <= 1'b1;
                        value   <= {WIDTH{1'b0}};
                        nbits   <= {WIDTH{1'b0}};
                        rem     <= R0;
                    end
                end
                RUN: begin
                    value <= {value[WIDTH-2:0], i_bit};
                    nbits <= nbits + 1'b1;
                    rem   <= rem_next;
                    if (nbits == WIDTH-1)
                        ctl <= DONE;
                end
                DONE: begin
                    if (i_arm)
                        ctl <= ARMED;
                end
                default: ctl <= IDLE;
            endcase
        end
    end

    assign o_done    = (ctl == DONE);
    assign o_verdict = (ctl == DONE) && (rem == R0);

    always @(*)
        assert (!(armed && ctl == DONE && rem == R0) || (started && (value % 32'd3) == 32'd0));
endmodule

module preload_timer #(
    parameter W = 16
) (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_period,
    input  wire [W-1:0] in_cmp,
    output wire [W-1:0] o_cnt,
    output wire         o_match,
    output wire         o_wrap
);
    reg [W-1:0] cnt        = {W{1'b0}};
    reg [W-1:0] period_act = 16'd9;
    reg [W-1:0] period_sh  = 16'd9;
    reg [W-1:0] cmp_act    = 16'd4;
    reg [W-1:0] cmp_sh     = 16'd4;
    reg         pend       = 1'b0;
    reg         armed      = 1'b0;
    reg         pv         = 1'b0;

    assign in_ready = !pend;
    wire accept = in_valid && in_ready;
    wire wrap   = i_ce && (cnt >= period_act);

    assign o_cnt   = cnt;
    assign o_match = (cnt == cmp_act);
    assign o_wrap  = wrap;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (cnt >= period_act) begin
                cnt        <= {W{1'b0}};
                period_act <= period_sh;
                cmp_act    <= cmp_sh;
            end else begin
                cnt <= cnt + 1'b1;
            end
        end
        if (accept) begin
            period_sh <= in_period;
            cmp_sh    <= in_cmp;
            pend      <= 1'b1;
        end else if (wrap) begin
            pend      <= 1'b0;
        end
        if (accept)
            armed <= 1'b1;
    end

    always @(posedge clk)
        if (pv && armed && $stable(pend))
            assert ($stable(period_act));
endmodule

module ldpc_cnp #(
    parameter DEG = 24,
    parameter W = 32
) (
    input  wire         clk,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_mag,
    input  wire         in_sign,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_min1,
    output wire [W-1:0] out_min2,
    output wire [W-1:0] out_idx,
    output wire         out_sign,
    input  wire [W-1:0] q_idx,
    output wire [W-1:0] q_mag
);
    typedef enum logic [1:0] {S_ACCUM = 2'd0, S_DONE = 2'd1} state_t;
    state_t state;
    initial state = S_ACCUM;

    reg [W-1:0] min1;
    reg [W-1:0] min2;
    reg [W-1:0] min_idx;
    reg [W-1:0] count;
    reg [W-1:0] prev_min1;
    reg         sign_prod;
    initial min1 = {W{1'b1}};
    initial min2 = {W{1'b1}};
    initial min_idx = {W{1'b0}};
    initial count = {W{1'b0}};
    initial prev_min1 = {W{1'b1}};
    initial sign_prod = 1'b0;

    assign in_ready  = (state == S_ACCUM);
    assign out_valid = (state == S_DONE);
    wire acc = in_valid && in_ready;
    wire rel = out_valid && out_ready;

    always @(posedge clk) begin
        if (acc) begin
            prev_min1 <= min1;
            sign_prod <= sign_prod ^ in_sign;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= count;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            if (count == DEG - 1) begin
                count <= {W{1'b0}};
                state <= S_DONE;
            end else begin
                count <= count + 1'b1;
            end
        end else if (rel) begin
            min1      <= {W{1'b1}};
            min2      <= {W{1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
            state     <= S_ACCUM;
        end
    end

    assign out_min1 = min1;
    assign out_min2 = min2;
    assign out_idx  = min_idx;
    assign out_sign = sign_prod;
    // check-to-variable magnitude for variable q_idx (min-sum exclusion)
    assign q_mag = (q_idx == min_idx) ? min2 : min1;

    reg pv = 0;
    always @(posedge clk) pv <= 1;
    always @(posedge clk) if (pv && $past(acc)) assert (min2 >= prev_min1);
endmodule

module frac_xmul_cmp #(
    parameter W = 32
) (
    input  wire           clk,
    input  wire           rst,
    // input channel: op=0 loads two fractions a/b and c/d, op=1 takes the reciprocal of both held fractions
    input  wire           in_valid,
    output wire           in_ready,
    input  wire           in_op,
    input  wire [W-1:0]   in_a,
    input  wire [W-1:0]   in_b,
    input  wire [W-1:0]   in_c,
    input  wire [W-1:0]   in_d,
    // output channel: registered cross products and relation result
    output reg            out_valid,
    input  wire           out_ready,
    output reg [2*W-1:0]  p_ad,
    output reg [2*W-1:0]  p_cb,
    output reg            lt_q,
    output reg            gt_q,
    output wire           eq_q
);
    initial begin
        out_valid = 1'b0;
        p_ad      = {2*W{1'b0}};
        p_cb      = {2*W{1'b0}};
        lt_q      = 1'b0;
        gt_q      = 1'b0;
    end

    // cross multiply: a/b vs c/d  <=>  a*d vs c*b (no division)
    wire [2*W-1:0] m_ad = in_a * in_d;
    wire [2*W-1:0] m_cb = in_c * in_b;

    assign in_ready = !out_valid || out_ready;
    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    assign eq_q = !lt_q && !gt_q;

    always @(posedge clk) begin
        if (rst) begin
            out_valid <= 1'b0;
            p_ad      <= {2*W{1'b0}};
            p_cb      <= {2*W{1'b0}};
            lt_q      <= 1'b0;
            gt_q      <= 1'b0;
        end else if (in_fire) begin
            out_valid <= 1'b1;
            if (in_op) begin
                // reciprocal of both fractions: b/a vs d/c -> b*c vs d*a, products and relation swap
                p_ad <= p_cb;
                p_cb <= p_ad;
                lt_q <= gt_q;
                gt_q <= lt_q;
            end else begin
                p_ad <= m_ad;
                p_cb <= m_cb;
                lt_q <= (m_ad < m_cb);
                gt_q <= (m_ad > m_cb);
            end
        end else if (out_fire) begin
            out_valid <= 1'b0;
        end
    end

    // Absence: the 'greater' result flag and products that are not greater never coexist
    wire prod_le = (p_ad <= p_cb);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv)
            assert (!($past(gt_q) && $past(prod_le)));
endmodule

module eye_scan_mon #(
    parameter W  = 128,
    parameter NS = 8,
    parameter NH = 8,
    parameter NV = 4,
    parameter CW = $clog2(NS),
    parameter HW = $clog2(NH),
    parameter VW = $clog2(NV),
    parameter EW = $clog2(NS) + 1
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          s_valid,
    output wire          s_ready,
    input  wire [W-1:0]  s_data,
    input  wire [W-1:0]  s_off,
    output reg           m_valid,
    input  wire          m_ready,
    output reg  [HW-1:0] m_hoff,
    output reg  [VW-1:0] m_voff,
    output reg  [EW-1:0] m_errs
);
    reg [HW-1:0]    hoff       = {HW{1'b0}};
    reg [VW-1:0]    voff       = {VW{1'b0}};
    reg [CW-1:0]    sample_cnt = {CW{1'b0}};
    reg [EW-1:0]    err_cnt    = {EW{1'b0}};
    reg [NH*EW-1:0] emap       = {(NH*EW){1'b0}};
    reg             armed      = 1'b1;

    initial m_valid = 1'b0;
    initial m_hoff  = {HW{1'b0}};
    initial m_voff  = {VW{1'b0}};
    initial m_errs  = {EW{1'b0}};

    assign s_ready = !m_valid;

    wire          s_fire    = s_valid && s_ready;
    wire          mis       = |(s_data ^ s_off);
    wire [EW-1:0] err_next  = err_cnt + {{(EW-1){1'b0}}, mis};
    wire          last      = (sample_cnt == NS-1);
    wire          scan_done = s_fire && last && (hoff == NH-1) && (voff == NV-1);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            hoff       <= {HW{1'b0}};
            voff       <= {VW{1'b0}};
            sample_cnt <= {CW{1'b0}};
            err_cnt    <= {EW{1'b0}};
            emap       <= {(NH*EW){1'b0}};
            armed      <= 1'b1;
            m_valid    <= 1'b0;
            m_hoff     <= {HW{1'b0}};
            m_voff     <= {VW{1'b0}};
            m_errs     <= {EW{1'b0}};
        end else begin
            if (m_valid && m_ready)
                m_valid <= 1'b0;
            if (s_fire) begin
                if (last) begin
                    sample_cnt <= {CW{1'b0}};
                    err_cnt    <= {EW{1'b0}};
                    m_valid    <= 1'b1;
                    m_errs     <= err_next;
                    m_hoff     <= hoff;
                    m_voff     <= voff;
                    emap[hoff*EW +: EW] <= err_next;
                    if (hoff == NH-1) begin
                        hoff <= {HW{1'b0}};
                        voff <= voff + 1'b1;
                    end else begin
                        hoff <= hoff + 1'b1;
                    end
                end else begin
                    sample_cnt <= sample_cnt + 1'b1;
                    err_cnt    <= err_next;
                end
            end
            if (scan_done)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed) assert (err_cnt < NS);
endmodule

module an_arbiter #(
    parameter W = 64,
    parameter NPAGES = 2,
    parameter [63:0] LINK_TIME = 64'd6,
    parameter [63:0] LOCAL_ABIL = 64'h0000_0000_0000_01E0
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          page_valid,
    input  wire [W-1:0]  page_data,
    output wire          page_ready,
    input  wire          tick,
    input  wire          restart,
    output wire          link_up,
    output reg  [W-1:0]  resolved_mode
);
    localparam [1:0] ST_BASE = 2'd0;
    localparam [1:0] ST_NEXT = 2'd1;
    localparam [1:0] ST_WAIT = 2'd2;
    localparam [1:0] ST_DONE = 2'd3;

    reg [1:0]          neg_state  = ST_BASE;
    reg [W-1:0]        link_timer = {W{1'b0}};
    reg [NPAGES*W-1:0] rx_abil    = {(NPAGES*W){1'b0}};
    reg                win        = 1'b0;
    reg                pv         = 1'b0;
    initial resolved_mode = {W{1'b0}};

    assign page_ready = (neg_state == ST_BASE) || (neg_state == ST_NEXT);
    wire accept = page_valid && page_ready;
    assign link_up = (neg_state == ST_DONE);
    wire tmr_expired = (link_timer == {W{1'b0}});
    wire tmr_last    = (link_timer == {{(W-1){1'b0}}, 1'b1});

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            neg_state     <= ST_BASE;
            link_timer    <= {W{1'b0}};
            rx_abil       <= {(NPAGES*W){1'b0}};
            win           <= 1'b0;
            resolved_mode <= {W{1'b0}};
        end else begin
            if (tick && !tmr_expired)
                link_timer <= link_timer - {{(W-1){1'b0}}, 1'b1};
            case (neg_state)
                ST_BASE: if (accept) begin
                    rx_abil[W-1:0] <= page_data;
                    neg_state      <= ST_NEXT;
                end
                ST_NEXT: if (accept) begin
                    rx_abil[2*W-1:W] <= page_data;
                    neg_state        <= ST_WAIT;
                    link_timer       <= LINK_TIME;
                    win              <= 1'b1;
                end
                ST_WAIT: if (tick && tmr_last) begin
                    neg_state     <= ST_DONE;
                    win           <= 1'b0;
                    resolved_mode <= (rx_abil[W-1:0] | rx_abil[2*W-1:W]) & LOCAL_ABIL;
                end
                ST_DONE: if (restart) begin
                    neg_state <= ST_BASE;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    always @(posedge clk)
        if (pv && win) assert (!$rose(tmr_expired));
endmodule

module thr_cross_det #(
    parameter W = 32,
    parameter [W-1:0] THR_INIT = 32'h8000_0000
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_load,
    input  wire [W-1:0] i_thr,
    input  wire [W-1:0] i_sample,
    output reg          o_xflag,
    output reg          o_xdir,
    output reg  [W-1:0] o_xcnt
);
    reg [W-1:0] thr;
    reg [W-1:0] prev;
    reg         have_prev;
    reg         seen_below;

    initial begin
        thr        = THR_INIT;
        prev       = {W{1'b0}};
        have_prev  = 1'b0;
        seen_below = 1'b0;
        o_xflag    = 1'b0;
        o_xdir     = 1'b0;
        o_xcnt     = {W{1'b0}};
    end

    wire s_below = (i_sample < thr);
    wire p_below = (prev < thr);
    wire cross   = have_prev && (s_below != p_below);

    always @(posedge clk) begin
        if (rst) begin
            thr        <= THR_INIT;
            prev       <= {W{1'b0}};
            have_prev  <= 1'b0;
            seen_below <= 1'b0;
            o_xflag    <= 1'b0;
            o_xdir     <= 1'b0;
            o_xcnt     <= {W{1'b0}};
        end else if (i_load) begin
            thr        <= i_thr;
            have_prev  <= 1'b0;
            seen_below <= 1'b0;
            o_xflag    <= 1'b0;
        end else if (i_ce) begin
            prev      <= i_sample;
            have_prev <= 1'b1;
            if (s_below)
                seen_below <= 1'b1;
            o_xflag <= cross;
            if (cross) begin
                o_xdir <= p_below;
                o_xcnt <= o_xcnt + 1'b1;
            end
        end
    end

    always @(*) assert (!(o_xflag && o_xdir) || seen_below);
endmodule

module seg_rot_shifter #(
    parameter W = 32,
    parameter SEGS = 4
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              in_valid,
    output wire              in_ready,
    input  wire [W-1:0]      in_data,
    input  wire [31:0]       in_amt,
    input  wire              step,
    output reg               out_valid,
    input  wire              out_ready,
    output wire [SEGS*W-1:0] out_data
);
    reg [SEGS*W-1:0] segs;
    reg [SEGS-1:0]   spill;
    reg              par;
    reg              busy;
    reg [31:0]       cnt;

    initial segs = {SEGS*W{1'b0}};
    initial spill = {SEGS{1'b0}};
    initial par = 1'b0;
    initial busy = 1'b0;
    initial cnt = 32'd0;
    initial out_valid = 1'b0;

    assign in_ready = !busy && !out_valid;
    assign out_data = segs;

    reg [SEGS*W-1:0] seg_nxt;
    reg [SEGS-1:0]   sp_nxt;
    integer i;
    always @(*) begin
        for (i = 0; i < SEGS; i = i + 1) begin
            seg_nxt[i*W +: W] = {segs[i*W +: (W-1)], spill[(i+SEGS-1)%SEGS]};
            sp_nxt[i] = segs[i*W + W - 2];
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            segs <= {SEGS*W{1'b0}};
            spill <= {SEGS{1'b0}};
            par <= 1'b0;
            busy <= 1'b0;
            cnt <= 32'd0;
            out_valid <= 1'b0;
        end else begin
            if (in_valid && in_ready) begin
                segs <= {{((SEGS-1)*W){1'b0}}, in_data};
                spill <= {{(SEGS-1){1'b0}}, in_data[W-1]};
                par <= ^in_data;
                cnt <= in_amt;
                busy <= 1'b1;
            end else if (busy && step) begin
                if (cnt == 32'd0) begin
                    busy <= 1'b0;
                    out_valid <= 1'b1;
                end else begin
                    segs <= seg_nxt;
                    spill <= sp_nxt;
                    cnt <= cnt - 32'd1;
                end
            end
            if (out_valid && out_ready)
                out_valid <= 1'b0;
        end
    end

    always @(posedge clk)
        if (busy) assert ((^segs) == par);
endmodule

module islip_alloc #(
    parameter N = 4
) (
    input  wire           clk,
    input  wire           rst_n,
    input  wire           en,
    input  wire [N*N-1:0] req,
    input  wire [N-1:0]   release_i,
    output wire [N-1:0]   o_in_busy,
    output wire [31:0]    o_active
);
    localparam PW = (N <= 2) ? 1 : $clog2(N);

    reg [N-1:0]    in_busy    = {N{1'b0}};
    reg [N-1:0]    out_busy   = {N{1'b0}};
    reg [N*PW-1:0] g_ptr      = {(N*PW){1'b0}};
    reg [N*PW-1:0] a_ptr      = {(N*PW){1'b0}};
    reg [N*PW-1:0] conn       = {(N*PW){1'b0}};
    reg [31:0]     active_cnt = 32'd0;
    reg            armed      = 1'b0;

    reg [N*N-1:0]  ereq, gnt, acc;
    reg [N-1:0]    new_in, new_out, rel_in, rel_out;
    reg [N*PW-1:0] acc_out, acc_in;
    reg [31:0]     new_cnt, rel_cnt;
    integer i, j, k, idx;
    reg found;

    always @(*) begin
        ereq = {(N*N){1'b0}};
        for (i = 0; i < N; i = i + 1)
            for (j = 0; j < N; j = j + 1)
                ereq[i*N+j] = req[i*N+j] & ~in_busy[i] & ~out_busy[j];
        gnt = {(N*N){1'b0}};
        for (j = 0; j < N; j = j + 1) begin
            found = 1'b0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (g_ptr[j*PW +: PW] + k) % N;
                for (i = 0; i < N; i = i + 1)
                    if (!found && (i == idx) && ereq[i*N+j]) begin
                        gnt[j*N+i] = 1'b1;
                        found = 1'b1;
                    end
            end
        end
        acc = {(N*N){1'b0}};
        acc_out = {(N*PW){1'b0}};
        acc_in = {(N*PW){1'b0}};
        new_in = {N{1'b0}};
        new_out = {N{1'b0}};
        for (i = 0; i < N; i = i + 1) begin
            found = 1'b0;
            for (k = 0; k < N; k = k + 1) begin
                idx = (a_ptr[i*PW +: PW] + k) % N;
                for (j = 0; j < N; j = j + 1)
                    if (!found && (j == idx) && gnt[j*N+i]) begin
                        acc[i*N+j] = 1'b1;
                        acc_out[i*PW +: PW] = j;
                        acc_in[j*PW +: PW] = i;
                        new_in[i] = 1'b1;
                        new_out[j] = 1'b1;
                        found = 1'b1;
                    end
            end
        end
        rel_in = release_i & in_busy;
        rel_out = {N{1'b0}};
        for (i = 0; i < N; i = i + 1)
            for (j = 0; j < N; j = j + 1)
                if (rel_in[i] && (conn[i*PW +: PW] == j))
                    rel_out[j] = 1'b1;
        new_cnt = 32'd0;
        rel_cnt = 32'd0;
        for (i = 0; i < N; i = i + 1) begin
            new_cnt = new_cnt + new_in[i];
            rel_cnt = rel_cnt + rel_in[i];
        end
    end

    integer p;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            in_busy    <= {N{1'b0}};
            out_busy   <= {N{1'b0}};
            g_ptr      <= {(N*PW){1'b0}};
            a_ptr      <= {(N*PW){1'b0}};
            conn       <= {(N*PW){1'b0}};
            active_cnt <= 32'd0;
            armed      <= 1'b0;
        end else if (en) begin
            in_busy  <= (in_busy & ~rel_in) | new_in;
            out_busy <= (out_busy & ~rel_out) | new_out;
            for (p = 0; p < N; p = p + 1) begin
                if (new_in[p]) begin
                    conn[p*PW +: PW]  <= acc_out[p*PW +: PW];
                    a_ptr[p*PW +: PW] <= (acc_out[p*PW +: PW] == N-1) ? {PW{1'b0}} : acc_out[p*PW +: PW] + 1'b1;
                end
                if (new_out[p])
                    g_ptr[p*PW +: PW] <= (acc_in[p*PW +: PW] == N-1) ? {PW{1'b0}} : acc_in[p*PW +: PW] + 1'b1;
            end
            active_cnt <= active_cnt + new_cnt - rel_cnt;
            if (new_cnt != 32'd0)
                armed <= 1'b1;
        end
    end

    assign o_in_busy = in_busy;
    assign o_active  = active_cnt;

    always @(posedge clk)
        if (armed)
            assert (active_cnt <= N);
endmodule

module frame_beat_ripple #(
    parameter W = 32,
    parameter MAX_BEATS = 12
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         s_valid,
    input  wire         s_last,
    output wire         s_ready,
    output wire         m_valid,
    input  wire         m_ready,
    output wire [W-1:0] m_count
);
    typedef enum logic [1:0] {IDLE = 2'd0, COUNTING = 2'd1, DONE = 2'd2} state_t;

    localparam [W-1:0] LIMIT    = MAX_BEATS;
    localparam [W-1:0] LAST_IDX = MAX_BEATS - 1;

    state_t state;
    reg in_frame;
    reg [W-1:0] q;
    integer i;

    initial begin
        state    = IDLE;
        in_frame = 1'b0;
        q        = {W{1'b0}};
    end

    assign s_ready = (state != DONE);
    assign m_valid = (state == DONE);
    assign m_count = q;

    wire accept = s_valid && s_ready;
    wire drain  = m_valid && m_ready;

    // Ripple chain of toggle flip-flops: stage 0 toggles on each accepted
    // beat; stage g toggles when stage g-1 falls from 1 to 0 (its 'clock').
    wire [W-1:0] t;
    assign t[0] = accept;
    genvar g;
    generate
        for (g = 1; g < W; g = g + 1) begin : rip
            assign t[g] = t[g-1] & q[g-1];
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            state    <= IDLE;
            in_frame <= 1'b0;
            q        <= {W{1'b0}};
        end else begin
            if (drain)
                q <= {W{1'b0}};
            else
                for (i = 0; i < W; i = i + 1)
                    if (t[i]) q[i] <= ~q[i];

            case (state)
                IDLE: begin
                    if (accept) begin
                        in_frame <= 1'b1;
                        state    <= (s_last || q == LAST_IDX) ? DONE : COUNTING;
                    end
                end
                COUNTING: begin
                    if (accept && (s_last || q == LAST_IDX))
                        state <= DONE;
                end
                DONE: begin
                    if (drain) begin
                        state    <= IDLE;
                        in_frame <= 1'b0;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (in_frame) assert (q <= LIMIT);
endmodule

module its_xlate #(
    parameter DEV_ENTRIES = 16,
    parameter CQ_DEPTH = 16,
    parameter DW = 64,
    parameter DEVW = 4,
    parameter AW = 4
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            cmd_valid,
    output wire            cmd_ready,
    input  wire [1:0]      cmd_op,
    input  wire [DEVW-1:0] cmd_dev,
    input  wire [DW-1:0]   cmd_base,
    input  wire [DW-1:0]   cmd_coll,
    input  wire            exec_en,
    input  wire            req_valid,
    output wire            req_ready,
    input  wire [DEVW-1:0] req_dev,
    input  wire [DW-1:0]   req_event,
    output reg             out_valid,
    input  wire            out_ready,
    output reg  [DW-1:0]   out_intid,
    output reg  [DW-1:0]   out_coll,
    output reg  [DW-1:0]   xlat_count,
    output reg  [DW-1:0]   miss_count
);
    localparam [1:0] OP_MAPD = 2'd1;
    localparam [1:0] OP_UNMAPD = 2'd2;

    reg [1:0]      cq_op   [0:CQ_DEPTH-1];
    reg [DEVW-1:0] cq_dev  [0:CQ_DEPTH-1];
    reg [DW-1:0]   cq_base [0:CQ_DEPTH-1];
    reg [DW-1:0]   cq_coll [0:CQ_DEPTH-1];
    reg [AW:0]     wptr;
    reg [AW:0]     rptr;

    reg [DEV_ENTRIES-1:0] dev_valid;
    reg [DW-1:0]   dt_base [0:DEV_ENTRIES-1];
    reg [DW-1:0]   dt_coll [0:DEV_ENTRIES-1];

    reg seen_map;

    wire [AW:0] cq_count = wptr - rptr;
    assign cmd_ready = (cq_count != CQ_DEPTH);
    assign req_ready = !out_valid || out_ready;

    wire [1:0]      ex_op   = cq_op[rptr[AW-1:0]];
    wire [DEVW-1:0] ex_dev  = cq_dev[rptr[AW-1:0]];
    wire [DW-1:0]   ex_base = cq_base[rptr[AW-1:0]];
    wire [DW-1:0]   ex_coll = cq_coll[rptr[AW-1:0]];

    integer i;
    initial begin
        wptr = 0;
        rptr = 0;
        dev_valid = 0;
        seen_map = 1'b0;
        out_valid = 1'b0;
        out_intid = 0;
        out_coll = 0;
        xlat_count = 0;
        miss_count = 0;
        for (i = 0; i < CQ_DEPTH; i = i + 1) begin
            cq_op[i] = 0;
            cq_dev[i] = 0;
            cq_base[i] = 0;
            cq_coll[i] = 0;
        end
        for (i = 0; i < DEV_ENTRIES; i = i + 1) begin
            dt_base[i] = 0;
            dt_coll[i] = 0;
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            wptr <= 0;
            rptr <= 0;
            dev_valid <= 0;
            seen_map <= 1'b0;
            out_valid <= 1'b0;
            out_intid <= 0;
            out_coll <= 0;
            xlat_count <= 0;
            miss_count <= 0;
            for (i = 0; i < CQ_DEPTH; i = i + 1) begin
                cq_op[i] <= 0;
                cq_dev[i] <= 0;
                cq_base[i] <= 0;
                cq_coll[i] <= 0;
            end
            for (i = 0; i < DEV_ENTRIES; i = i + 1) begin
                dt_base[i] <= 0;
                dt_coll[i] <= 0;
            end
        end else begin
            if (cmd_valid && cmd_ready) begin
                cq_op[wptr[AW-1:0]]   <= cmd_op;
                cq_dev[wptr[AW-1:0]]  <= cmd_dev;
                cq_base[wptr[AW-1:0]] <= cmd_base;
                cq_coll[wptr[AW-1:0]] <= cmd_coll;
                wptr <= wptr + 1'b1;
            end
            if (exec_en && (cq_count != 0)) begin
                if (ex_op == OP_MAPD) begin
                    dev_valid[ex_dev] <= 1'b1;
                    dt_base[ex_dev] <= ex_base;
                    dt_coll[ex_dev] <= ex_coll;
                    seen_map <= 1'b1;
                end else if (ex_op == OP_UNMAPD) begin
                    dev_valid[ex_dev] <= 1'b0;
                end
                rptr <= rptr + 1'b1;
            end
            if (out_valid && out_ready)
                out_valid <= 1'b0;
            if (req_valid && req_ready) begin
                if (dev_valid[req_dev]) begin
                    out_valid <= 1'b1;
                    out_intid <= dt_base[req_dev] + req_event;
                    out_coll <= dt_coll[req_dev];
                    xlat_count <= xlat_count + 1'b1;
                end else begin
                    miss_count <= miss_count + 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (xlat_count != {DW{1'b0}}) assert (seen_map);
endmodule

module idle_autopd #(
    parameter DATA_W = 128,
    parameter CNT_W  = 4,
    parameter [CNT_W-1:0] DEF_THR = 4'd6
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              in_valid,
    output wire              in_ready,
    input  wire [DATA_W-1:0] in_data,
    input  wire              tick,
    input  wire              cfg_thr_we,
    input  wire [CNT_W-1:0]  cfg_thr,
    input  wire              cfg_en,
    input  wire              cfg_dis,
    output wire              pwr_down_req,
    output reg  [DATA_W-1:0] blk_data
);
    reg [CNT_W-1:0] idle_cnt = {CNT_W{1'b0}};
    reg [CNT_W-1:0] thresh   = DEF_THR;
    reg             pd_req   = 1'b0;
    reg             apd_en   = 1'b0;
    initial blk_data = {DATA_W{1'b0}};

    assign in_ready     = !pd_req;
    assign pwr_down_req = pd_req && apd_en;

    wire accept = in_valid && in_ready;

    always @(posedge clk) begin
        if (rst) begin
            idle_cnt <= {CNT_W{1'b0}};
            thresh   <= DEF_THR;
            pd_req   <= 1'b0;
        end else if (cfg_thr_we) begin
            thresh   <= (cfg_thr == {CNT_W{1'b0}}) ? {{(CNT_W-1){1'b0}}, 1'b1} : cfg_thr;
            idle_cnt <= {CNT_W{1'b0}};
            pd_req   <= 1'b0;
        end else if (in_valid) begin
            idle_cnt <= {CNT_W{1'b0}};
            pd_req   <= 1'b0;
        end else if (tick && !pd_req) begin
            idle_cnt <= idle_cnt + 1'b1;
            if (idle_cnt + 1'b1 == thresh)
                pd_req <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (!rst && accept)
            blk_data <= in_data;
    end

    always @(posedge clk) begin
        if (rst)
            apd_en <= 1'b0;
        else if (cfg_dis)
            apd_en <= 1'b0;
        else if (cfg_en)
            apd_en <= 1'b1;
    end

    always @(*) assert (!apd_en || idle_cnt <= thresh);
endmodule

module fft_twiddle_rom #(
    parameter ENTRIES = 16,
    parameter AW = 4,
    parameter W = 16,
    parameter CW = 6
) (
    input wire clk,
    input wire rst,
    input wire ce,
    output reg [W-1:0] re_q,
    output reg [W-1:0] im_q,
    output reg [AW-1:0] idx_q
);
    // butterfly sequencing counter: position and stage fields
    reg [CW-1:0] cnt;
    wire [1:0]    stage = cnt[5:4];
    wire [AW-1:0] pos   = cnt[AW-1:0];
    wire [AW-1:0] k     = pos << stage;

    // ROM contents: cos(pi*k/16) and -sin(pi*k/16) in Q15
    wire [W-1:0] cos_k =
        (k == 4'd0)  ? 16'h7FFF :
        (k == 4'd1)  ? 16'h7D89 :
        (k == 4'd2)  ? 16'h7641 :
        (k == 4'd3)  ? 16'h6A6D :
        (k == 4'd4)  ? 16'h5A82 :
        (k == 4'd5)  ? 16'h471D :
        (k == 4'd6)  ? 16'h30FC :
        (k == 4'd7)  ? 16'h18F9 :
        (k == 4'd8)  ? 16'h0000 :
        (k == 4'd9)  ? 16'hE707 :
        (k == 4'd10) ? 16'hCF04 :
        (k == 4'd11) ? 16'hB8E3 :
        (k == 4'd12) ? 16'hA57E :
        (k == 4'd13) ? 16'h9593 :
        (k == 4'd14) ? 16'h89BF :
                       16'h8277;
    wire [W-1:0] msin_k =
        (k == 4'd0)  ? 16'h0000 :
        (k == 4'd1)  ? 16'hE707 :
        (k == 4'd2)  ? 16'hCF04 :
        (k == 4'd3)  ? 16'hB8E3 :
        (k == 4'd4)  ? 16'hA57E :
        (k == 4'd5)  ? 16'h9593 :
        (k == 4'd6)  ? 16'h89BF :
        (k == 4'd7)  ? 16'h8277 :
        (k == 4'd8)  ? 16'h8001 :
        (k == 4'd9)  ? 16'h8277 :
        (k == 4'd10) ? 16'h89BF :
        (k == 4'd11) ? 16'h9593 :
        (k == 4'd12) ? 16'hA57E :
        (k == 4'd13) ? 16'hB8E3 :
        (k == 4'd14) ? 16'hCF04 :
                       16'hE707;

    // registered ROM read stage
    reg [W-1:0]  re_d;
    reg [W-1:0]  im_d;
    reg [AW-1:0] idx_d;

    initial cnt = {CW{1'b0}};
    initial re_d = 16'h7FFF;
    initial im_d = 16'h0000;
    initial idx_d = {AW{1'b0}};
    initial re_q = 16'h7FFF;
    initial im_q = 16'h0000;
    initial idx_q = {AW{1'b0}};

    always @(posedge clk) begin
        if (rst) begin
            cnt   <= {CW{1'b0}};
            re_d  <= 16'h7FFF;
            im_d  <= 16'h0000;
            idx_d <= {AW{1'b0}};
            re_q  <= 16'h7FFF;
            im_q  <= 16'h0000;
            idx_q <= {AW{1'b0}};
        end else if (ce) begin
            cnt   <= cnt + 1'b1;
            idx_d <= k;
            re_d  <= cos_k;
            im_d  <= msin_k;
            idx_q <= idx_d;
            re_q  <= re_d;
            im_q  <= im_d;
        end
    end

    // unity twiddle W^0 = 1
    always @(*) assert (idx_q != 4'd0 || (re_q == 16'h7FFF && im_q == 16'h0000));
    // quarter twiddle W^8 = -j
    always @(*) assert (idx_q != 4'd8 || (re_q == 16'h0000 && im_q == 16'h8001));
endmodule

module ecc_scrubber #(
    parameter LINES = 16,
    parameter AW = 4,
    parameter DW = 128,
    parameter SW = 7,
    parameter TW = 4,
    parameter [TW-1:0] INTERVAL = 4'd9,
    parameter CW = 8
)(
    input  wire          clk,
    input  wire          tick,
    input  wire          rd_valid,
    output wire          rd_ready,
    input  wire [DW-1:0] rd_data,
    input  wire          rd_err,
    input  wire [SW-1:0] rd_syn,
    output wire [AW-1:0] rd_addr,
    output wire          wb_valid,
    input  wire          wb_ready,
    output reg  [AW-1:0] wb_addr,
    output reg  [DW-1:0] wb_data,
    output reg  [CW-1:0] err_count,
    output reg  [AW-1:0] scrub_addr,
    output reg  [LINES-1:0] err_map
);
    localparam [1:0] S_WAIT = 2'd0;
    localparam [1:0] S_READ = 2'd1;
    localparam [1:0] S_WB   = 2'd2;

    reg [1:0]    phase;
    reg [TW-1:0] timer;
    reg          first_pass;

    initial begin
        phase      = S_WAIT;
        timer      = INTERVAL;
        wb_addr    = {AW{1'b0}};
        wb_data    = {DW{1'b0}};
        err_count  = {CW{1'b0}};
        scrub_addr = {AW{1'b0}};
        err_map    = {LINES{1'b0}};
        first_pass = 1'b1;
    end

    assign rd_ready = (phase == S_READ);
    assign wb_valid = (phase == S_WB);
    assign rd_addr  = scrub_addr;

    wire rd_fire    = rd_valid && rd_ready;
    wire done_clean = rd_fire && !rd_err;
    wire done_wb    = wb_valid && wb_ready;
    wire wrap_event = (done_clean && scrub_addr == LINES-1) ||
                      (done_wb && wb_addr == LINES-1);

    wire [DW-1:0] flip_mask = {{(DW-1){1'b0}}, 1'b1} << rd_syn;

    always @(posedge clk) begin
        case (phase)
            S_WAIT: begin
                if (tick) begin
                    if (timer == {TW{1'b0}}) begin
                        phase <= S_READ;
                        timer <= INTERVAL;
                    end else begin
                        timer <= timer - 1'b1;
                    end
                end
            end
            S_READ: begin
                if (rd_fire) begin
                    if (rd_err) begin
                        wb_data <= rd_data ^ flip_mask;
                        wb_addr <= scrub_addr;
                        phase   <= S_WB;
                    end else begin
                        scrub_addr <= scrub_addr + 1'b1;
                        phase      <= S_WAIT;
                    end
                end
            end
            S_WB: begin
                if (wb_ready) begin
                    scrub_addr       <= wb_addr + 1'b1;
                    err_map[wb_addr] <= 1'b1;
                    if (err_count != {CW{1'b1}})
                        err_count <= err_count + 1'b1;
                    phase <= S_WAIT;
                end
            end
            default: phase <= S_WAIT;
        endcase
        if (wrap_event)
            first_pass <= 1'b0;
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && first_pass && $stable(scrub_addr))
            assert ($stable(err_count));
endmodule

module irq_first_arrival #(
    parameter NCH  = 8,
    parameter IDXW = 3,
    parameter TW   = 64
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            ce,
    input  wire            clr,
    input  wire [NCH-1:0]  irq,
    output reg             captured,
    output reg [IDXW-1:0]  win_idx,
    output reg [NCH-1:0]   win_mask,
    output reg [TW-1:0]    cap_time
);
    localparam [NCH-1:0] ONE = 1;

    reg [TW-1:0] tick;

    initial begin
        captured = 1'b0;
        win_idx  = {IDXW{1'b0}};
        win_mask = {NCH{1'b0}};
        cap_time = {TW{1'b0}};
        tick     = {TW{1'b0}};
    end

    function [IDXW-1:0] first_idx;
        input [NCH-1:0] v;
        integer i;
        begin
            first_idx = {IDXW{1'b0}};
            for (i = NCH-1; i >= 0; i = i - 1)
                if (v[i]) first_idx = i;
        end
    endfunction

    wire [IDXW-1:0] enc = first_idx(irq);

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            captured <= 1'b0;
            win_idx  <= {IDXW{1'b0}};
            win_mask <= {NCH{1'b0}};
            cap_time <= {TW{1'b0}};
            tick     <= {TW{1'b0}};
        end else if (ce) begin
            tick <= tick + {{(TW-1){1'b0}}, 1'b1};
            if (!captured && (|irq)) begin
                captured <= 1'b1;
                win_idx  <= enc;
                win_mask <= ONE << enc;
                cap_time <= tick;
            end else if (captured && clr) begin
                captured <= 1'b0;
                win_mask <= win_mask & ~(ONE << win_idx);
            end
        end
    end

    always @(*) assert (captured || win_mask == {NCH{1'b0}});
endmodule

module islip_alloc #(
    parameter N  = 4,
    parameter W  = 2,
    parameter CW = 64
) (
    input  wire           clk,
    input  wire           rst,
    input  wire           step,
    input  wire [N*N-1:0] req,
    input  wire [N-1:0]   rel,
    output reg  [N-1:0]   in_busy,
    output reg  [N*W-1:0] in_dst,
    output reg  [N-1:0]   out_busy,
    output reg  [N*W-1:0] out_src,
    output reg  [CW-1:0]  match_count,
    output reg            armed
);
    reg [N*W-1:0] g_ptr;
    reg [N*W-1:0] a_ptr;

    initial begin
        in_busy     = {N{1'b0}};
        in_dst      = {(N*W){1'b0}};
        out_busy    = {N{1'b0}};
        out_src     = {(N*W){1'b0}};
        g_ptr       = {(N*W){1'b0}};
        a_ptr       = {(N*W){1'b0}};
        match_count = {CW{1'b0}};
        armed       = 1'b0;
    end

    // grant phase: each free output picks a free requesting input, round robin from g_ptr
    integer gi, go, gk;
    reg [W-1:0]   tmp_g;
    reg [N-1:0]   gnt_v;
    reg [N*W-1:0] gnt_in;
    always @(*) begin
        gnt_v  = {N{1'b0}};
        gnt_in = {(N*W){1'b0}};
        tmp_g  = {W{1'b0}};
        for (go = 0; go < N; go = go + 1)
            for (gk = N-1; gk >= 0; gk = gk - 1) begin
                tmp_g = g_ptr[go*W +: W] + gk;
                for (gi = 0; gi < N; gi = gi + 1)
                    if (tmp_g == gi && !out_busy[go] && !in_busy[gi] && req[gi*N+go]) begin
                        gnt_v[go] = 1'b1;
                        gnt_in[go*W +: W] = gi;
                    end
            end
    end

    // accept phase: each free input accepts one granting output, round robin from a_ptr
    integer ai, ao, ak;
    reg [W-1:0]   tmp_a;
    reg [N-1:0]   acc_v;
    reg [N*W-1:0] acc_out;
    always @(*) begin
        acc_v   = {N{1'b0}};
        acc_out = {(N*W){1'b0}};
        tmp_a   = {W{1'b0}};
        for (ai = 0; ai < N; ai = ai + 1)
            for (ak = N-1; ak >= 0; ak = ak - 1) begin
                tmp_a = a_ptr[ai*W +: W] + ak;
                for (ao = 0; ao < N; ao = ao + 1)
                    if (tmp_a == ao && !in_busy[ai] && gnt_v[ao] && gnt_in[ao*W +: W] == ai) begin
                        acc_v[ai] = 1'b1;
                        acc_out[ai*W +: W] = ao;
                    end
            end
    end

    // next-state: releases tear down, accepted matches connect, pointers advance only on accept
    integer ni, no;
    reg [N-1:0]   in_busy_n;
    reg [N*W-1:0] in_dst_n;
    reg [N-1:0]   out_busy_n;
    reg [N*W-1:0] out_src_n;
    reg [N*W-1:0] g_ptr_n;
    reg [N*W-1:0] a_ptr_n;
    reg [W:0]     n_acc;
    always @(*) begin
        in_busy_n  = in_busy;
        in_dst_n   = in_dst;
        out_busy_n = out_busy;
        out_src_n  = out_src;
        g_ptr_n    = g_ptr;
        a_ptr_n    = a_ptr;
        n_acc      = {(W+1){1'b0}};
        for (ni = 0; ni < N; ni = ni + 1) begin
            if (rel[ni] && in_busy[ni])
                in_busy_n[ni] = 1'b0;
            if (acc_v[ni]) begin
                in_busy_n[ni]        = 1'b1;
                in_dst_n[ni*W +: W]  = acc_out[ni*W +: W];
                a_ptr_n[ni*W +: W]   = acc_out[ni*W +: W] + 1'b1;
                n_acc                = n_acc + 1'b1;
            end
            for (no = 0; no < N; no = no + 1) begin
                if (rel[ni] && in_busy[ni] && in_dst[ni*W +: W] == no)
                    out_busy_n[no] = 1'b0;
                if (acc_v[ni] && acc_out[ni*W +: W] == no) begin
                    out_busy_n[no]       = 1'b1;
                    out_src_n[no*W +: W] = ni;
                    g_ptr_n[no*W +: W]   = ni + 1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            in_busy     <= {N{1'b0}};
            in_dst      <= {(N*W){1'b0}};
            out_busy    <= {N{1'b0}};
            out_src     <= {(N*W){1'b0}};
            g_ptr       <= {(N*W){1'b0}};
            a_ptr       <= {(N*W){1'b0}};
            match_count <= {CW{1'b0}};
        end else if (step) begin
            in_busy     <= in_busy_n;
            in_dst      <= in_dst_n;
            out_busy    <= out_busy_n;
            out_src     <= out_src_n;
            g_ptr       <= g_ptr_n;
            a_ptr       <= a_ptr_n;
            match_count <= match_count + n_acc;
            if (|acc_v)
                armed <= 1'b1;
        end
    end

    // absence: two inputs never own the same output (after the first match)
    integer pi, pj;
    reg dup;
    always @(*) begin
        dup = 1'b0;
        for (pi = 0; pi < N; pi = pi + 1)
            for (pj = pi + 1; pj < N; pj = pj + 1)
                if (in_busy[pi] && in_busy[pj] && in_dst[pi*W +: W] == in_dst[pj*W +: W])
                    dup = 1'b1;
    end

    assert property (!armed || !dup);
endmodule

module desc_own_table #(
    parameter DEPTH = 8,
    parameter AW = 3,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          ce,
    input  wire          we,
    input  wire [AW-1:0] waddr,
    input  wire [DW-1:0] wdata,
    input  wire          dma_take,
    input  wire          adv,
    input  wire          start,
    input  wire          stop,
    output wire [DW-1:0] rdata,
    output wire          cpu_own,
    output wire          dma_own
);
    // asynchronous-read distributed descriptor RAM
    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] ptr = {AW{1'b0}};
    reg armed = 1'b0;
    integer i;

    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    // combinational read of the word addressed by the DMA fetch pointer
    assign rdata   = mem[ptr];
    assign cpu_own = rdata[0];
    assign dma_own = rdata[1];

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            for (i = 0; i < DEPTH; i = i + 1)
                mem[i] <= {DW{1'b0}};
            ptr   <= {AW{1'b0}};
            armed <= 1'b0;
        end else if (ce) begin
            if (we)
                // CPU write: CPU ownership bit wins, DMA bit is cleared if CPU claims
                mem[waddr] <= {wdata[DW-1:2], wdata[1] & ~wdata[0], wdata[0]};
            else if (dma_take && !rdata[0])
                // DMA claims the fetched descriptor only if CPU does not own it
                mem[ptr] <= {rdata[DW-1:2], 2'b10};
            if (adv)
                ptr <= ptr + 1'b1;
            if (start)
                armed <= 1'b1;
            else if (stop)
                armed <= 1'b0;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n)
            pv <= 1'b0;
        else
            pv <= 1'b1;
    end

    // after start until stop: the fetched descriptor never has two owners
    always @(posedge clk)
        if (pv && $past(armed))
            assert (!($past(cpu_own) && $past(dma_own)));
endmodule

module fll_cnt_cmp #(
    parameter W = 64,
    parameter [W-1:0] WINDOW = 64'd8
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         osc_tick,
    input  wire         tgt_load,
    input  wire [W-1:0] tgt_in,
    output reg  [W-1:0] osc_code,
    output reg          locked
);
    typedef enum logic [1:0] {S_IDLE = 2'd0, S_COUNT = 2'd1, S_CMP = 2'd2, S_ADJ = 2'd3} state_t;

    state_t state = S_IDLE;
    reg [W-1:0] cyc_cnt = {W{1'b0}};
    reg [W-1:0] win_tmr = {W{1'b0}};
    reg [W-1:0] target  = {W{1'b0}};
    reg up_req = 1'b0;
    reg dn_req = 1'b0;
    reg armed  = 1'b0;

    initial osc_code = {W{1'b0}};
    initial locked   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            state   <= S_IDLE;
            cyc_cnt <= {W{1'b0}};
            win_tmr <= {W{1'b0}};
            up_req  <= 1'b0;
            dn_req  <= 1'b0;
            locked  <= 1'b0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (tgt_load) target <= tgt_in;
                    cyc_cnt <= {W{1'b0}};
                    win_tmr <= WINDOW;
                    armed   <= 1'b1;
                    state   <= S_COUNT;
                end
                S_COUNT: begin
                    if (osc_tick) cyc_cnt <= cyc_cnt + 1'b1;
                    win_tmr <= win_tmr - 1'b1;
                    if (win_tmr == 1) state <= S_CMP;
                end
                S_CMP: begin
                    up_req <= (cyc_cnt < target);
                    dn_req <= (cyc_cnt > target);
                    state  <= S_ADJ;
                end
                S_ADJ: begin
                    if (up_req)      osc_code <= osc_code + 1'b1;
                    else if (dn_req) osc_code <= osc_code - 1'b1;
                    locked <= !up_req && !dn_req;
                    up_req <= 1'b0;
                    dn_req <= 1'b0;
                    state  <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        assert (!armed || !(state == S_CMP && cyc_cnt > WINDOW));
endmodule

module morse_decoder #(
    parameter SRW = 8,
    parameter [7:0] MAXSYM = 8'd7,
    parameter [7:0] DOT_MAX = 8'd3,
    parameter [7:0] CHAR_GAP = 8'd5
) (
    input wire clk,
    input wire rst,
    input wire step,
    input wire key,
    output reg [SRW-1:0] char_code,
    output reg [7:0] char_len,
    output reg char_valid
);
    typedef enum logic [1:0] {IDLE = 2'd0, MARK = 2'd1, SPACE = 2'd2} state_t;
    state_t state;
    reg [7:0] dur;
    reg [SRW-1:0] sym_sr;
    reg [7:0] sym_cnt;
    reg armed;

    initial begin
        state = IDLE;
        dur = 8'd0;
        sym_sr = {{(SRW-1){1'b0}}, 1'b1};
        sym_cnt = 8'd0;
        armed = 1'b0;
        char_code = {SRW{1'b0}};
        char_len = 8'd0;
        char_valid = 1'b0;
    end

    wire is_dash = (dur > DOT_MAX);
    wire [7:0] dur_inc = (dur == 8'hFF) ? dur : (dur + 8'd1);

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            dur <= 8'd0;
            sym_sr <= {{(SRW-1){1'b0}}, 1'b1};
            sym_cnt <= 8'd0;
            armed <= 1'b0;
            char_code <= {SRW{1'b0}};
            char_len <= 8'd0;
            char_valid <= 1'b0;
        end else if (step) begin
            char_valid <= 1'b0;
            case (state)
                IDLE: begin
                    if (key) begin
                        state <= MARK;
                        dur <= 8'd1;
                    end
                end
                MARK: begin
                    if (key) begin
                        dur <= dur_inc;
                    end else begin
                        if (sym_cnt < MAXSYM) begin
                            sym_sr <= {sym_sr[SRW-2:0], is_dash};
                            sym_cnt <= sym_cnt + 8'd1;
                        end
                        armed <= 1'b1;
                        state <= SPACE;
                        dur <= 8'd1;
                    end
                end
                SPACE: begin
                    if (key) begin
                        state <= MARK;
                        dur <= 8'd1;
                    end else if (dur_inc >= CHAR_GAP) begin
                        char_code <= sym_sr;
                        char_len <= sym_cnt;
                        char_valid <= 1'b1;
                        sym_sr <= {{(SRW-1){1'b0}}, 1'b1};
                        sym_cnt <= 8'd0;
                        armed <= 1'b0;
                        state <= IDLE;
                        dur <= 8'd0;
                    end else begin
                        dur <= dur_inc;
                    end
                end
                default: state <= IDLE;
            endcase
        end
    end

    // Scope: after a symbol is accepted (armed set) until the character is emitted (armed cleared)
    always @(posedge clk)
        if (armed)
            assert (sym_sr != {{(SRW-1){1'b0}}, 1'b1});

    always @(posedge clk)
        if (armed && sym_cnt < MAXSYM)
            assert (sym_sr[SRW-1] == 1'b0);
endmodule

module assoc_bitserial #(
    parameter N  = 8,
    parameter W  = 32,
    parameter CW = 6,
    parameter TW = 4
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire          in_op,
    input  wire [2:0]    in_addr,
    input  wire [W-1:0]  in_data,
    input  wire [W-1:0]  in_mask,
    input  wire          i_step,
    output reg           res_valid,
    input  wire          res_ready,
    output wire [N-1:0]  res_tag,
    output wire          res_any
);
    reg [N*W-1:0] words;
    reg [W-1:0]   comparand;
    reg [W-1:0]   mask;
    reg [N-1:0]   tag;
    reg [TW-1:0]  hit_cnt;
    reg [CW-1:0]  col;
    reg           busy;

    initial begin
        words = {N*W{1'b0}};
        comparand = {W{1'b0}};
        mask = {W{1'b0}};
        tag = {N{1'b0}};
        hit_cnt = {TW{1'b0}};
        col = {CW{1'b0}};
        busy = 1'b0;
        res_valid = 1'b0;
    end

    assign in_ready = !busy && !res_valid;
    assign res_tag  = tag;
    assign res_any  = (hit_cnt != {TW{1'b0}});

    wire [4:0] bit_idx = col[4:0];
    wire cmp_bit = comparand[bit_idx];
    wire msk_bit = mask[bit_idx];

    wire [N-1:0] keep;
    genvar g;
    generate
        for (g = 0; g < N; g = g + 1) begin : g_col
            assign keep[g] = !msk_bit || (words[g*W + bit_idx] == cmp_bit);
        end
    endgenerate

    wire [N-1:0] cleared = tag & ~keep;
    reg [TW-1:0] drop;
    integer k;
    always @(*) begin
        drop = {TW{1'b0}};
        for (k = 0; k < N; k = k + 1)
            drop = drop + {{(TW-1){1'b0}}, cleared[k]};
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            words <= {N*W{1'b0}};
            comparand <= {W{1'b0}};
            mask <= {W{1'b0}};
            tag <= {N{1'b0}};
            hit_cnt <= {TW{1'b0}};
            col <= {CW{1'b0}};
            busy <= 1'b0;
            res_valid <= 1'b0;
        end else begin
            if (res_valid && res_ready)
                res_valid <= 1'b0;
            if (in_valid && in_ready) begin
                if (in_op) begin
                    comparand <= in_data;
                    mask <= in_mask;
                    tag <= {N{1'b1}};
                    hit_cnt <= N[TW-1:0];
                    col <= {CW{1'b0}};
                    busy <= 1'b1;
                end else begin
                    words[in_addr*W +: W] <= in_data;
                end
            end else if (busy && i_step) begin
                tag <= tag & keep;
                hit_cnt <= hit_cnt - drop;
                if (col == W-1) begin
                    col <= W[CW-1:0];
                    busy <= 1'b0;
                    res_valid <= 1'b1;
                end else begin
                    col <= col + 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (busy)
            assert ((hit_cnt != {TW{1'b0}}) == (tag != {N{1'b0}}));
endmodule

module ola_block_conv #(
    parameter W = 32,
    parameter BLK = 64,
    parameter TAPS = 4,
    parameter [TAPS*W-1:0] COEF = {32'd1, 32'd3, 32'd3, 32'd1}
)(
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire [W-1:0] i_sample,
    output reg  [W-1:0] o_y,
    output reg          o_valid,
    output wire         o_busy,
    output wire [31:0]  o_blocks
);
    localparam [31:0] LAST  = BLK + TAPS - 2;
    localparam [31:0] TLAST = TAPS - 2;

    reg [W-1:0] in_buf [0:BLK-1];
    reg [W-1:0] tail   [0:TAPS-2];
    reg [31:0] wr_idx   = 32'd0;
    reg [31:0] out_idx  = 32'd0;
    reg [31:0] tail_idx = 32'd0;
    reg [31:0] blk_cnt  = 32'd0;
    reg        phase    = 1'b0;

    integer i;
    initial begin
        o_y = 0;
        o_valid = 1'b0;
        for (i = 0; i < BLK; i = i + 1) in_buf[i] = 0;
        for (i = 0; i < TAPS-1; i = i + 1) tail[i] = 0;
    end

    assign o_busy   = phase;
    assign o_blocks = blk_cnt;

    reg [W-1:0] acc;
    reg [31:0]  src;
    integer j;
    always @(*) begin
        acc = 0;
        src = 0;
        for (j = 0; j < TAPS; j = j + 1) begin
            src = out_idx - j;
            if (out_idx >= j && src < BLK)
                acc = acc + COEF[j*W +: W] * in_buf[src];
        end
        if (out_idx < TAPS-1)
            acc = acc + tail[out_idx];
    end

    always @(posedge clk) begin
        if (i_reset) begin
            wr_idx   <= 32'd0;
            out_idx  <= 32'd0;
            tail_idx <= 32'd0;
            blk_cnt  <= 32'd0;
            phase    <= 1'b0;
            o_valid  <= 1'b0;
            o_y      <= 0;
        end else if (i_ce) begin
            o_valid <= 1'b0;
            if (!phase) begin
                in_buf[wr_idx] <= i_sample;
                if (wr_idx == BLK-1) begin
                    wr_idx   <= 32'd0;
                    phase    <= 1'b1;
                    out_idx  <= 32'd0;
                    tail_idx <= 32'd0;
                end else begin
                    wr_idx <= wr_idx + 32'd1;
                end
            end else begin
                if (out_idx >= BLK) begin
                    tail[tail_idx] <= acc;
                    if (tail_idx == TLAST) begin
                        phase    <= 1'b0;
                        out_idx  <= 32'd0;
                        tail_idx <= 32'd0;
                        blk_cnt  <= blk_cnt + 32'd1;
                    end else begin
                        tail_idx <= tail_idx + 32'd1;
                        out_idx  <= out_idx + 32'd1;
                    end
                end else begin
                    o_y     <= acc;
                    o_valid <= 1'b1;
                    out_idx <= out_idx + 32'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv) assert (!$past(i_ce) || out_idx <= LAST);
endmodule

module div3_serial #(
    parameter W = 16,
    parameter MAXBITS = 16
) (
    input  wire         clk,
    input  wire         arm,
    input  wire         clr,
    input  wire         load,
    input  wire [W-1:0] load_len,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire         in_bit,
    output wire         done,
    output wire         div3,
    output wire [1:0]   o_rem
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0]   phase   = S_IDLE;
    reg [1:0]   rem     = 2'd0;
    reg [W-1:0] val     = {W{1'b0}};
    reg [W-1:0] cnt     = {W{1'b0}};
    reg [W-1:0] limit   = 16'd8;
    reg         started = 1'b0;
    reg         win     = 1'b0;

    assign in_ready = (phase == S_ARM) || (phase == S_RUN);
    wire acc = in_valid && in_ready;

    function [1:0] rnext;
        input [1:0] r;
        input       b;
        begin
            case ({r, b})
                3'b000: rnext = 2'd0;
                3'b001: rnext = 2'd1;
                3'b010: rnext = 2'd2;
                3'b011: rnext = 2'd0;
                3'b100: rnext = 2'd1;
                3'b101: rnext = 2'd2;
                default: rnext = 2'd0;
            endcase
        end
    endfunction

    wire [W-1:0] load_clamped = (load_len == 16'd0) ? 16'd1 :
                                (load_len > MAXBITS) ? MAXBITS : load_len;

    always @(posedge clk) begin
        if (phase == S_IDLE) begin
            if (load) limit <= load_clamped;
            if (arm) begin
                phase   <= S_ARM;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b1;
            end
        end else if (phase == S_DONE) begin
            if (clr) begin
                phase   <= S_IDLE;
                rem     <= 2'd0;
                val     <= {W{1'b0}};
                cnt     <= {W{1'b0}};
                started <= 1'b0;
                win     <= 1'b0;
            end
        end else if (acc) begin
            rem     <= rnext(rem, in_bit);
            val     <= {val[W-2:0], in_bit};
            cnt     <= cnt + 16'd1;
            started <= 1'b1;
            if (cnt + 16'd1 == limit) phase <= S_DONE;
            else                      phase <= S_RUN;
        end
    end

    assign done  = (phase == S_DONE);
    assign div3  = (rem == 2'd0);
    assign o_rem = rem;

    always @(posedge clk)
        if (win && $rose(done))
            assert (started && (div3 == ((val % 16'd3) == 16'd0)));
endmodule

module desc_prefetch_cache #(
    parameter DEPTH = 32,
    parameter DW = 16
)(
    input  wire          clk,
    input  wire          flush,
    input  wire [DW-1:0] flush_addr,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_desc,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_desc,
    output wire [DW-1:0] out_tag,
    output wire [DW-1:0] fetch_req_addr,
    input  wire [DW-1:0] lk_addr,
    output wire          lk_hit
);
    localparam AW = $clog2(DEPTH);

    reg [DW-1:0] desc_mem [0:DEPTH-1];
    reg [DW-1:0] tag_mem  [0:DEPTH-1];
    reg [DEPTH-1:0] valid = {DEPTH{1'b0}};
    reg [AW-1:0] wr_ptr = {AW{1'b0}};
    reg [AW-1:0] rd_ptr = {AW{1'b0}};
    reg [DW-1:0] count = {DW{1'b0}};
    reg [DW-1:0] fetch_addr = {DW{1'b0}};
    reg armed = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) begin
            desc_mem[i] = {DW{1'b0}};
            tag_mem[i]  = {DW{1'b0}};
        end
    end

    assign in_ready = !flush && (count != DEPTH);
    wire in_fire = in_valid && in_ready;
    wire push = in_fire && !valid[wr_ptr];
    assign out_valid = !flush && valid[rd_ptr];
    wire pop = out_valid && out_ready;

    assign out_desc = desc_mem[rd_ptr];
    assign out_tag = tag_mem[rd_ptr];
    assign fetch_req_addr = fetch_addr;

    wire [DEPTH-1:0] set_mask = push ? ({{(DEPTH-1){1'b0}}, 1'b1} << wr_ptr) : {DEPTH{1'b0}};
    wire [DEPTH-1:0] clr_mask = pop  ? ({{(DEPTH-1){1'b0}}, 1'b1} << rd_ptr) : {DEPTH{1'b0}};

    wire [DEPTH-1:0] exp_valid;
    wire [DEPTH-1:0] hit_vec;
    genvar g;
    generate
        for (g = 0; g < DEPTH; g = g + 1) begin : g_slot
            wire [AW-1:0] off = g - rd_ptr;
            assign exp_valid[g] = ({{(DW-AW){1'b0}}, off} < count);
            assign hit_vec[g] = valid[g] && (tag_mem[g] == lk_addr);
        end
    endgenerate
    assign lk_hit = |hit_vec;

    always @(posedge clk) begin
        if (flush) begin
            valid <= {DEPTH{1'b0}};
            count <= {DW{1'b0}};
            rd_ptr <= wr_ptr;
            fetch_addr <= flush_addr;
            armed <= 1'b0;
        end else begin
            if (push) begin
                desc_mem[wr_ptr] <= in_desc;
                tag_mem[wr_ptr] <= fetch_addr;
                wr_ptr <= wr_ptr + 1'b1;
                armed <= 1'b1;
            end
            if (in_fire)
                fetch_addr <= fetch_addr + {{(DW-1){1'b0}}, 1'b1};
            if (pop)
                rd_ptr <= rd_ptr + 1'b1;
            valid <= (valid | set_mask) & ~clr_mask;
            count <= count + {{(DW-1){1'b0}}, push} - {{(DW-1){1'b0}}, pop};
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $stable(wr_ptr))
            assert ($stable(fetch_addr));
endmodule

module ddr3_cmd_queue #(
    parameter DEPTH = 12,
    parameter DW = 32
) (
    input  wire          clk,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data,
    input  wire          cfg_load,
    input  wire [31:0]   cfg_wm,
    output wire          almost_full,
    output wire [31:0]   occupancy
);
    localparam AW = $clog2(DEPTH);
    localparam [AW-1:0] LAST = DEPTH - 1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg [AW-1:0] wptr = {AW{1'b0}};
    reg [AW-1:0] rptr = {AW{1'b0}};
    reg          wr_lap = 1'b0;
    reg          rd_lap = 1'b0;
    reg [31:0]   count = 32'd0;
    reg [31:0]   wm = 32'd8;
    reg          armed = 1'b1;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1) mem[i] = {DW{1'b0}};
    end

    wire full  = (wptr == rptr) && (wr_lap != rd_lap);
    wire empty = (wptr == rptr) && (wr_lap == rd_lap);
    assign in_ready  = !full;
    assign out_valid = !empty;
    assign out_data  = mem[rptr];

    wire push = in_valid && in_ready;
    wire pop  = out_valid && out_ready;

    // T inputs of the two lap toggle flip-flops
    wire wr_t = push && (wptr == LAST);
    wire rd_t = pop  && (rptr == LAST);

    always @(posedge clk) begin
        if (push) begin
            mem[wptr] <= in_data;
            wptr <= (wptr == LAST) ? {AW{1'b0}} : wptr + 1'b1;
        end
        if (pop)
            rptr <= (rptr == LAST) ? {AW{1'b0}} : rptr + 1'b1;
        if (wr_t) wr_lap <= ~wr_lap;
        if (rd_t) rd_lap <= ~rd_lap;
        case ({push, pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
        if (cfg_load) begin
            wm    <= cfg_wm;
            armed <= 1'b0;
        end
    end

    assign almost_full = (count >= wm);
    assign occupancy   = count;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $rose(wr_lap))
            assert (count <= DEPTH);
endmodule

module rename_table #(
    parameter NARCH = 4,
    parameter NPHYS = 8,
    parameter AW = $clog2(NARCH),
    parameter TW = $clog2(NPHYS),
    parameter CW = 16
) (
    input  wire          clk,
    input  wire          i_ce,
    input  wire          i_req,
    input  wire [AW-1:0] i_dst,
    output wire [TW-1:0] o_tag,
    output wire [CW-1:0] o_cnt
);
    typedef enum logic [1:0] {S_IDLE, S_ARM, S_START, S_FINISH} state_t;

    state_t state = S_IDLE;

    // rename map: architectural register -> physical tag
    reg [NARCH-1:0][TW-1:0] map_q;
    // free-tag list as a bit vector (1 = tag free)
    reg [NPHYS-1:0] free_vec = {NPHYS{1'b1}} << NARCH;
    reg [AW-1:0]    dst       = {AW{1'b0}};
    reg [TW-1:0]    alloc_tag = {TW{1'b0}};
    reg [CW-1:0]    rename_cnt = {CW{1'b0}};
    reg             seen_q    = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < NARCH; i = i + 1)
            map_q[i] = i;
    end

    // lowest free physical tag
    reg [TW-1:0] pick;
    integer k;
    always @(*) begin
        pick = {TW{1'b0}};
        for (k = NPHYS-1; k >= 0; k = k - 1)
            if (free_vec[k]) pick = k;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        dst    <= i_dst;
                        seen_q <= 1'b1;
                        state  <= S_ARM;
                    end
                end
                S_ARM: begin
                    if (free_vec != {NPHYS{1'b0}}) begin
                        alloc_tag      <= pick;
                        free_vec[pick] <= 1'b0;
                        state          <= S_START;
                    end
                end
                S_START: begin
                    map_q[dst]           <= alloc_tag;
                    free_vec[map_q[dst]] <= 1'b1;
                    state                <= S_FINISH;
                end
                S_FINISH: begin
                    rename_cnt <= rename_cnt + 1'b1;
                    state      <= S_IDLE;
                end
            endcase
        end
    end

    assign o_tag = alloc_tag;
    assign o_cnt = rename_cnt;

    // after the first accepted rename request: a finished rename must have
    // passed through allocation (tag taken off the free list)
    always @(posedge clk)
        if (seen_q && state == S_FINISH)
            assert (!free_vec[alloc_tag]);
endmodule

module pkt_framer #(
    parameter W = 16,
    parameter DEPTH = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_start,
    input  wire [W-1:0] i_len,
    input  wire [W-1:0] i_data,
    output reg  [W-1:0] o_word,
    output reg          o_sof,
    output reg          o_eof
);
    localparam [W-1:0] MAX_LEN    = DEPTH;
    localparam [W-1:0] START_DELIM = 16'hA5A5;
    localparam [W-1:0] END_DELIM   = 16'h5A5A;
    localparam [1:0] S_IDLE = 2'd0, S_HDR = 2'd1, S_PAY = 2'd2, S_TRL = 2'd3;

    reg [1:0]   frame_state = S_IDLE;
    reg [W-1:0] byte_cnt    = {W{1'b0}};
    reg [W-1:0] len_reg     = {{(W-1){1'b0}}, 1'b1};
    reg         armed       = 1'b0;
    reg         pv          = 1'b0;
    initial o_word = {W{1'b0}};
    initial o_sof  = 1'b0;
    initial o_eof  = 1'b0;

    wire [W-1:0] len_clamped = (i_len == {W{1'b0}}) ? {{(W-1){1'b0}}, 1'b1} :
                               ((i_len > MAX_LEN) ? MAX_LEN : i_len);
    wire over_lim = (byte_cnt > MAX_LEN);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            frame_state <= S_IDLE;
            byte_cnt    <= {W{1'b0}};
            len_reg     <= {{(W-1){1'b0}}, 1'b1};
            o_word      <= {W{1'b0}};
            o_sof       <= 1'b0;
            o_eof       <= 1'b0;
        end else if (i_ce) begin
            case (frame_state)
                S_IDLE: begin
                    o_sof <= 1'b0;
                    o_eof <= 1'b0;
                    if (i_start) begin
                        len_reg     <= len_clamped;
                        o_word      <= START_DELIM;
                        o_sof       <= 1'b1;
                        armed       <= 1'b1;
                        frame_state <= S_HDR;
                    end
                end
                S_HDR: begin
                    o_sof       <= 1'b0;
                    o_word      <= len_reg;
                    byte_cnt    <= {W{1'b0}};
                    frame_state <= S_PAY;
                end
                S_PAY: begin
                    o_word <= i_data;
                    if (byte_cnt == len_reg - 1'b1) begin
                        byte_cnt    <= {W{1'b0}};
                        frame_state <= S_TRL;
                    end else begin
                        byte_cnt <= byte_cnt + 1'b1;
                    end
                end
                S_TRL: begin
                    o_word      <= END_DELIM;
                    o_eof       <= 1'b1;
                    frame_state <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && armed && $stable(frame_state))
            assert ($stable(over_lim));
endmodule

module exp_scale_unit #(
    parameter W = 32,
    parameter signed EMAX = 127,
    parameter signed EMIN = -126
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_valid,
    output wire         i_ready,
    input  wire [W-1:0] i_exp,
    input  wire [W-1:0] i_scale,
    input  wire [W-1:0] i_sig,
    output reg          o_valid,
    input  wire         o_ready,
    output reg  [W-1:0] o_exp,
    output reg  [W-1:0] o_sig,
    output reg          o_ovf,
    output reg          o_uf,
    output reg  [W-1:0] ovf_in_cnt,
    output reg  [W-1:0] ovf_out_cnt
);
    initial begin
        o_valid = 1'b0; o_exp = {W{1'b0}}; o_sig = {W{1'b0}};
        o_ovf = 1'b0; o_uf = 1'b0;
        ovf_in_cnt = {W{1'b0}}; ovf_out_cnt = {W{1'b0}};
    end

    assign i_ready = !o_valid || o_ready;
    wire accept = i_valid && i_ready;
    wire fire   = o_valid && o_ready;

    // scaleB: exponent + signed scale, computed wide to avoid wrap
    wire signed [W+1:0] sum = $signed({{2{i_exp[W-1]}}, i_exp}) + $signed({{2{i_scale[W-1]}}, i_scale});
    wire ovf_now = (sum > EMAX);
    wire uf_now  = (sum < EMIN);
    wire signed [W+1:0] ushift = EMIN - sum;
    wire flush = uf_now && (ushift >= W);
    wire [W-1:0] den_sig = flush ? {W{1'b0}} : (i_sig >> ushift[$clog2(W):0]);
    wire [W-1:0] emax_p1 = EMAX + 1;
    wire [W-1:0] emin_m1 = EMIN - 1;
    wire [W-1:0] res_exp = ovf_now ? emax_p1 : (uf_now ? emin_m1 : sum[W-1:0]);
    wire [W-1:0] res_sig = ovf_now ? {W{1'b0}} : (uf_now ? den_sig : i_sig);

    always @(posedge clk) begin
        if (rst) begin
            o_valid <= 1'b0; o_exp <= {W{1'b0}}; o_sig <= {W{1'b0}};
            o_ovf <= 1'b0; o_uf <= 1'b0;
            ovf_in_cnt <= {W{1'b0}}; ovf_out_cnt <= {W{1'b0}};
        end else begin
            if (accept) begin
                o_valid <= 1'b1;
                o_exp   <= res_exp;
                o_sig   <= res_sig;
                o_ovf   <= ovf_now;
                o_uf    <= uf_now;
            end else if (fire) begin
                o_valid <= 1'b0;
            end
            if (accept && ovf_now) ovf_in_cnt  <= ovf_in_cnt + 1'b1;
            if (fire && o_ovf)     ovf_out_cnt <= ovf_out_cnt + 1'b1;
        end
    end

    // Precedence: an overflow result delivered now must have been preceded by
    // an accepted overflowing input that has not yet been delivered.
    always @(posedge clk)
        if (o_valid && o_ready && o_ovf)
            assert (ovf_in_cnt != ovf_out_cnt);
endmodule

module burst_hold_arb #(
    parameter NREQ = 4,
    parameter LW   = 16,
    parameter OW   = 2
) (
    input  wire            clk,
    input  wire            rst_n,
    input  wire            ce,
    input  wire [NREQ-1:0] req,
    input  wire [LW-1:0]   req_len,
    output wire [NREQ-1:0] gnt,
    output wire            busy,
    output wire            last_beat
);
    localparam [1:0] S_IDLE = 2'd0;
    localparam [1:0] S_ARM  = 2'd1;
    localparam [1:0] S_XFER = 2'd2;

    reg [1:0]    phase      = S_IDLE;
    reg [OW-1:0] owner      = {OW{1'b0}};
    reg [LW-1:0] beats      = {LW{1'b0}};
    reg          seen_grant = 1'b0;
    reg          pv         = 1'b0;

    reg [OW-1:0] winner;
    integer i;
    always @(*) begin
        winner = {OW{1'b0}};
        for (i = NREQ-1; i >= 0; i = i - 1)
            if (req[i]) winner = i;
    end

    wire [LW-1:0] eff_len = (req_len == {LW{1'b0}}) ? {{(LW-1){1'b0}}, 1'b1} : req_len;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase      <= S_IDLE;
            owner      <= {OW{1'b0}};
            beats      <= {LW{1'b0}};
            seen_grant <= 1'b0;
        end else if (ce) begin
            case (phase)
                S_IDLE: begin
                    if (|req) begin
                        owner      <= winner;
                        beats      <= eff_len;
                        phase      <= S_ARM;
                        seen_grant <= 1'b1;
                    end
                end
                S_ARM: begin
                    phase <= S_XFER;
                end
                S_XFER: begin
                    beats <= beats - {{(LW-1){1'b0}}, 1'b1};
                    if (beats == {{(LW-1){1'b0}}, 1'b1})
                        phase <= S_IDLE;
                end
                default: begin
                    phase <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    assign gnt       = (phase == S_XFER) ? ({{(NREQ-1){1'b0}}, 1'b1} << owner) : {NREQ{1'b0}};
    assign busy      = (phase != S_IDLE);
    assign last_beat = (phase == S_XFER) && (beats == {{(LW-1){1'b0}}, 1'b1});

    always @(posedge clk)
        if (pv && seen_grant && $stable(beats))
            assert ($stable(owner));
endmodule

module transpose_buf #(
    parameter ROWS  = 4,
    parameter COLS  = 8,
    parameter DEPTH = ROWS * COLS,
    parameter DW    = 32
) (
    input  wire          clk,
    input  wire          rst_n,
    input  wire          in_valid,
    output wire          in_ready,
    input  wire [DW-1:0] in_data,
    output wire          out_valid,
    input  wire          out_ready,
    output wire [DW-1:0] out_data
);
    localparam AW = $clog2(DEPTH);
    localparam [1:0] C_IDLE  = 2'd0;
    localparam [1:0] C_ARM   = 2'd1;
    localparam [1:0] C_START = 2'd2;
    localparam PH_FILL  = 1'b0;
    localparam PH_DRAIN = 1'b1;

    reg [DW-1:0] mem [0:DEPTH-1];
    reg        phase    = 1'b0;
    reg [31:0] wr_row   = 32'd0;
    reg [31:0] wr_col   = 32'd0;
    reg [31:0] rd_row   = 32'd0;
    reg [31:0] rd_col   = 32'd0;
    reg [1:0]  chain    = 2'd0;
    reg        before_r = 1'b1;
    reg        pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < DEPTH; i = i + 1)
            mem[i] = {DW{1'b0}};
    end

    assign in_ready  = (phase == PH_FILL);
    assign out_valid = (phase == PH_DRAIN);

    wire wr_fire = in_valid && in_ready;
    wire rd_fire = out_valid && out_ready;
    wire wr_last = (wr_row == ROWS - 1) && (wr_col == COLS - 1);
    wire rd_last = (rd_row == ROWS - 1) && (rd_col == COLS - 1);

    wire [31:0] wr_addr = wr_row * COLS + wr_col;
    wire [31:0] rd_addr = rd_row * COLS + rd_col;

    assign out_data = mem[rd_addr[AW-1:0]];

    // row-order write into the tile
    always @(posedge clk) begin
        if (wr_fire)
            mem[wr_addr[AW-1:0]] <= in_data;
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            phase    <= PH_FILL;
            wr_row   <= 32'd0;
            wr_col   <= 32'd0;
            rd_row   <= 32'd0;
            rd_col   <= 32'd0;
            chain    <= C_IDLE;
            before_r <= 1'b1;
        end else begin
            if (wr_fire) begin
                if (wr_col == COLS - 1) begin
                    wr_col <= 32'd0;
                    if (wr_row == ROWS - 1) wr_row <= 32'd0;
                    else                    wr_row <= wr_row + 32'd1;
                end else begin
                    wr_col <= wr_col + 32'd1;
                end
                if (wr_last) begin
                    phase <= PH_DRAIN;
                    chain <= C_START;
                end else if (chain == C_IDLE) begin
                    chain <= C_ARM;
                end
            end
            // column-order read out of the tile
            if (rd_fire) begin
                if (rd_row == ROWS - 1) begin
                    rd_row <= 32'd0;
                    if (rd_col == COLS - 1) rd_col <= 32'd0;
                    else                    rd_col <= rd_col + 32'd1;
                end else begin
                    rd_row <= rd_row + 32'd1;
                end
                if (rd_last) begin
                    phase    <= PH_FILL;
                    chain    <= C_IDLE;
                    before_r <= 1'b0;
                end
            end
        end
    end

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) pv <= 1'b0;
        else        pv <= 1'b1;
    end

    // Chain precedence (arm -> start -> finish), before first tile completes:
    // while the chain FSM sits unchanged short of START, no column-order read may advance.
    always @(posedge clk) begin
        if (pv && before_r && $stable(chain) && chain != C_START)
            assert ($stable(rd_row) && $stable(rd_col));
    end
endmodule

module heap_pq #(
    parameter DEPTH = 4,
    parameter KW    = 8,
    parameter IW    = 2,
    parameter SW    = 3,
    parameter LVL   = 2
) (
    input  wire          clk,
    input  wire          i_ce,
    input  wire          in_valid,
    input  wire          in_op,
    input  wire [KW-1:0] in_key,
    output wire          in_ready,
    output reg  [KW-1:0] o_key,
    output wire [SW-1:0] o_size,
    output wire          o_busy
);
    reg [DEPTH*KW-1:0] heap = {(DEPTH*KW){1'b0}};
    reg [SW-1:0] size  = {SW{1'b0}};
    reg          busy  = 1'b0;
    reg          dir   = 1'b0;
    reg [IW-1:0] idx   = {IW{1'b0}};
    reg [1:0]    timer = 2'd0;
    reg          armed = 1'b0;
    initial o_key = {KW{1'b0}};

    assign in_ready = i_ce && !busy && (in_op ? (size != {SW{1'b0}}) : (size != DEPTH));
    wire accept = in_valid && in_ready;
    assign o_size = size;
    assign o_busy = busy;

    wire [IW-1:0] last   = size - 1'b1;
    wire [KW-1:0] k_root = heap[KW-1:0];
    wire [KW-1:0] k_last = heap[last*KW +: KW];
    wire [KW-1:0] k_idx  = heap[idx*KW +: KW];

    // sift-up
    wire [IW-1:0] up_par  = (idx - 1'b1) >> 1;
    wire [KW-1:0] k_par   = heap[up_par*KW +: KW];
    wire          up_swap = (idx != {IW{1'b0}}) && (k_idx < k_par);

    // sift-down
    wire [SW:0]   lc    = {idx, 1'b1};
    wire [SW:0]   rc    = lc + 1'b1;
    wire [IW-1:0] lci   = lc[IW-1:0];
    wire [IW-1:0] rci   = rc[IW-1:0];
    wire [KW-1:0] k_lc  = heap[lci*KW +: KW];
    wire [KW-1:0] k_rc  = heap[rci*KW +: KW];
    wire          lc_ok = lc < {1'b0, size};
    wire          rc_ok = rc < {1'b0, size};
    wire          l_lt  = lc_ok && (k_lc < k_idx);
    wire [IW-1:0] sm1   = l_lt ? lci : idx;
    wire [KW-1:0] k_sm1 = l_lt ? k_lc : k_idx;
    wire          r_lt  = rc_ok && (k_rc < k_sm1);
    wire [IW-1:0] sm    = r_lt ? rci : sm1;
    wire [KW-1:0] k_sm  = r_lt ? k_rc : k_sm1;
    wire          dn_swap = (sm != idx);
    wire [SW:0]   sm_lc = {sm, 1'b1};
    wire          dn_more = sm_lc < {1'b0, size};

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                armed <= 1'b1;
                timer <= LVL;
                if (!in_op) begin
                    heap[size[IW-1:0]*KW +: KW] <= in_key;
                    idx  <= size[IW-1:0];
                    size <= size + 1'b1;
                    busy <= (size != {SW{1'b0}});
                    dir  <= 1'b0;
                end else begin
                    o_key <= k_root;
                    heap[KW-1:0] <= k_last;
                    size  <= size - 1'b1;
                    idx   <= {IW{1'b0}};
                    busy  <= (size > 3'd2);
                    dir   <= 1'b1;
                end
            end else if (busy) begin
                if (!dir) begin
                    if (up_swap) begin
                        heap[idx*KW +: KW]    <= k_par;
                        heap[up_par*KW +: KW] <= k_idx;
                        idx   <= up_par;
                        timer <= timer - 1'b1;
                        busy  <= (up_par != {IW{1'b0}});
                        if (up_par == {IW{1'b0}}) armed <= 1'b0;
                    end else begin
                        busy  <= 1'b0;
                        armed <= 1'b0;
                    end
                end else begin
                    if (dn_swap) begin
                        heap[idx*KW +: KW] <= k_sm;
                        heap[sm*KW +: KW]  <= k_idx;
                        idx   <= sm;
                        timer <= timer - 1'b1;
                        busy  <= dn_more;
                        if (!dn_more) armed <= 1'b0;
                    end else begin
                        busy  <= 1'b0;
                        armed <= 1'b0;
                    end
                end
            end else begin
                armed <= 1'b0;
            end
        end
    end

    // bounded response: while the accepted request is still sifting, its budget never runs out
    always @(posedge clk)
        if (armed) assert (!busy || timer != 2'd0);
endmodule

module axi_w_upsizer #(
    parameter NW    = 16,
    parameter LANES = 16,
    parameter LW    = 4,
    parameter SW    = 2*LANES
) (
    input  wire              clk,
    input  wire              rst,
    input  wire              i_awvalid,
    output wire              o_awready,
    input  wire [15:0]       i_awlen,
    input  wire [2:0]        i_awsize,
    input  wire              i_wvalid,
    output wire              o_wready,
    input  wire [NW-1:0]     i_wdata,
    output wire              o_wvalid,
    input  wire              i_wready,
    output wire [NW*LANES-1:0] o_wdata,
    output wire [SW-1:0]     o_wstrb,
    output wire              o_wlast,
    output wire [2:0]        o_cap_size,
    output wire [15:0]       o_beats_left
);
    localparam [1:0] P_IDLE = 2'd0, P_ARMED = 2'd1, P_PACK = 2'd2, P_OUT = 2'd3;

    reg [1:0]          phase      = P_IDLE;
    reg                aw_seen    = 1'b0;
    reg [LW-1:0]       lane       = {LW{1'b0}};
    reg [SW-1:0]       strb       = {SW{1'b0}};
    reg [NW*LANES-1:0] pbuf       = {(NW*LANES){1'b0}};
    reg [15:0]         beats_left = 16'd0;
    reg [2:0]          cap_size   = 3'd0;
    reg                last_q     = 1'b0;

    assign o_awready    = (phase == P_IDLE);
    assign o_wready     = (phase == P_ARMED) || (phase == P_PACK);
    assign o_wvalid     = (phase == P_OUT);
    assign o_wdata      = pbuf;
    assign o_wstrb      = strb;
    assign o_wlast      = last_q;
    assign o_cap_size   = cap_size;
    assign o_beats_left = beats_left;

    wire aw_hs  = i_awvalid && o_awready;
    wire w_hs   = i_wvalid  && o_wready;
    wire out_hs = o_wvalid  && i_wready;

    wire          end_wide  = (lane == LANES-1) || (beats_left == 16'd0);
    wire [SW-1:0] lane_strb = {{(SW-2){1'b0}}, 2'b11} << {lane, 1'b0};

    always @(posedge clk) begin
        if (rst) begin
            phase      <= P_IDLE;
            aw_seen    <= 1'b0;
            lane       <= {LW{1'b0}};
            strb       <= {SW{1'b0}};
            pbuf       <= {(NW*LANES){1'b0}};
            beats_left <= 16'd0;
            cap_size   <= 3'd0;
            last_q     <= 1'b0;
        end else begin
            if (aw_hs) begin
                phase      <= P_ARMED;
                aw_seen    <= 1'b1;
                beats_left <= i_awlen;
                cap_size   <= i_awsize;
                lane       <= {LW{1'b0}};
                strb       <= {SW{1'b0}};
            end
            if (w_hs) begin
                pbuf[lane*NW +: NW] <= i_wdata;
                strb <= strb | lane_strb;
                if (end_wide) begin
                    phase  <= P_OUT;
                    last_q <= (beats_left == 16'd0);
                end else begin
                    phase <= P_PACK;
                    lane  <= lane + 1'b1;
                end
                if (beats_left != 16'd0)
                    beats_left <= beats_left - 16'd1;
            end
            if (out_hs) begin
                strb <= {SW{1'b0}};
                lane <= {LW{1'b0}};
                pbuf <= {(NW*LANES){1'b0}};
                if (last_q) begin
                    phase   <= P_IDLE;
                    aw_seen <= 1'b0;
                    last_q  <= 1'b0;
                end else begin
                    phase <= P_PACK;
                end
            end
        end
    end

    // chain precedence: a wide beat (finish) is never offered unless the
    // address was captured (arm) and the first lane was packed (start)
    assert property (!o_wvalid || (aw_seen && strb[1:0] == 2'b11));
endmodule

module sha256_msg_sched #(
    parameter WIDTH = 32,
    parameter NWIN  = 16,
    parameter NEXP  = 48
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             in_valid,
    output wire             in_ready,
    input  wire [WIDTH-1:0] in_data,
    output wire             out_valid,
    input  wire             out_ready,
    output wire [WIDTH-1:0] out_data,
    output wire             out_last
);
    typedef enum logic [1:0] {IDLE = 2'd0, LOAD = 2'd1, EXPAND = 2'd2} state_t;

    state_t state;
    initial state = IDLE;
    reg [31:0] cnt;
    initial cnt = 32'd0;
    reg armed;
    initial armed = 1'b1;
    reg [NWIN*WIDTH-1:0] win;
    initial win = {(NWIN*WIDTH){1'b0}};

    function [31:0] ssig0(input [31:0] x);
        ssig0 = {x[6:0], x[31:7]} ^ {x[17:0], x[31:18]} ^ (x >> 3);
    endfunction
    function [31:0] ssig1(input [31:0] x);
        ssig1 = {x[16:0], x[31:17]} ^ {x[18:0], x[31:19]} ^ (x >> 10);
    endfunction

    wire [WIDTH-1:0] w0  = win[0*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w1  = win[1*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w9  = win[9*WIDTH +: WIDTH];
    wire [WIDTH-1:0] w14 = win[14*WIDTH +: WIDTH];

    assign out_data  = ssig1(w14) + w9 + ssig0(w1) + w0;
    assign in_ready  = (state == IDLE) || (state == LOAD);
    assign out_valid = (state == EXPAND);
    assign out_last  = out_valid && (cnt == NEXP - 1);

    wire in_fire  = in_valid && in_ready;
    wire out_fire = out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            state <= IDLE;
            cnt   <= 32'd0;
        end else begin
            case (state)
                IDLE: begin
                    if (in_fire) begin
                        win   <= {in_data, win[NWIN*WIDTH-1:WIDTH]};
                        cnt   <= 32'd1;
                        state <= LOAD;
                    end
                end
                LOAD: begin
                    if (in_fire) begin
                        win <= {in_data, win[NWIN*WIDTH-1:WIDTH]};
                        if (cnt == NWIN - 1) begin
                            cnt   <= 32'd0;
                            state <= EXPAND;
                        end else begin
                            cnt <= cnt + 32'd1;
                        end
                    end
                end
                EXPAND: begin
                    if (out_fire) begin
                        win <= {out_data, win[NWIN*WIDTH-1:WIDTH]};
                        if (cnt == NEXP - 1) begin
                            cnt   <= 32'd0;
                            state <= IDLE;
                            armed <= 1'b0;
                        end else begin
                            cnt <= cnt + 32'd1;
                        end
                    end
                end
                default: begin
                    state <= IDLE;
                    cnt   <= 32'd0;
                end
            endcase
        end
    end

    assert property (!armed || cnt <= NEXP);
endmodule

module ldpc_cnp #(
    parameter DEG = 32,
    parameter W   = 16
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    output wire         out_valid,
    input  wire         out_ready,
    output wire [W-1:0] out_data
);
    localparam IW = $clog2(DEG);

    reg [W-1:0]   cnt       = {W{1'b0}};
    reg [W-1:0]   oidx      = {W{1'b0}};
    reg           out_phase = 1'b0;
    reg [W-2:0]   min1      = {(W-1){1'b1}};
    reg [W-2:0]   min2      = {(W-1){1'b1}};
    reg [W-1:0]   min_idx   = {W{1'b0}};
    reg           sign_prod = 1'b0;
    reg [DEG-1:0] sign_mem  = {DEG{1'b0}};
    reg           armed     = 1'b0;

    assign in_ready  = !out_phase;
    assign out_valid = out_phase;

    wire          accept = in_valid && in_ready;
    wire          emit   = out_valid && out_ready;
    wire          in_sgn = in_data[W-1];
    wire [W-2:0]  in_mag = in_data[W-2:0];

    assign out_data = { sign_prod ^ sign_mem[oidx[IW-1:0]],
                        (oidx == min_idx) ? min2 : min1 };

    always @(posedge clk) begin
        if (accept) armed <= 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            cnt       <= {W{1'b0}};
            oidx      <= {W{1'b0}};
            out_phase <= 1'b0;
            min1      <= {(W-1){1'b1}};
            min2      <= {(W-1){1'b1}};
            min_idx   <= {W{1'b0}};
            sign_prod <= 1'b0;
        end else if (accept) begin
            sign_mem[cnt[IW-1:0]] <= in_sgn;
            sign_prod <= sign_prod ^ in_sgn;
            if (in_mag < min1) begin
                min2    <= min1;
                min1    <= in_mag;
                min_idx <= cnt;
            end else if (in_mag < min2) begin
                min2 <= in_mag;
            end
            cnt <= cnt + 1'b1;
            if (cnt == DEG - 1)
                out_phase <= 1'b1;
        end else if (emit) begin
            if (oidx == DEG - 1) begin
                oidx      <= {W{1'b0}};
                cnt       <= {W{1'b0}};
                out_phase <= 1'b0;
                min1      <= {(W-1){1'b1}};
                min2      <= {(W-1){1'b1}};
                min_idx   <= {W{1'b0}};
                sign_prod <= 1'b0;
            end else begin
                oidx <= oidx + 1'b1;
            end
        end
    end

    assert property (!armed || cnt <= DEG);
endmodule

module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
   output wire [10:0] o_seq_stat
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
   wire frame_end = (phase == RUN) && last_col && last_row && !abort_req;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                       if (seq_fire)
                           phase <= RUN;
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                       if (arm_req || seq_rearm) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module tplan_px_drain (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire abort_req,
   input wire frame_act,
   input wire push,
   input wire push_eof,
   input wire [7:0] push_pix,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire ready,
   output wire drained,
   output wire eof_pend_o,
   output wire [2:0] fill_o,
   output wire [4:0] col_o,
   output wire [7:0] px_o,
   output wire px_vld_o,
   output wire px_eol_o,
   output wire hblank_o,
   output wire [7:0] sig_o,
   output wire [7:0] stall_o
);
   localparam [2:0] DEPTH = 3'd4;
   localparam [4:0] LINE_LAST = 5'd23;

   reg [7:0] fifo [0:3];
   reg [1:0] wr_ptr;
   reg [1:0] rd_ptr;
   reg [2:0] cnt;
   reg [3:0] cfg_div;
   reg [3:0] cfg_hblank;
   reg       cfg_inv;
   reg [7:0] cfg_blank;
   reg [3:0] div_cnt;
   reg [3:0] hb_cnt;
   reg [4:0] col_out;
   reg [7:0] px_q;
   reg       px_vld;
   reg       px_eol;
   reg       eof_pend;
   reg [7:0] sig_run;
   reg [7:0] sig_last;
   reg [7:0] stall_cnt;

   integer j;
   initial begin
       for (j = 0; j < 4; j = j + 1)
           fifo[j] = 8'h00;
   end
   initial wr_ptr = 2'd0;
   initial rd_ptr = 2'd0;
   initial cnt = 3'd0;
   initial cfg_div = 4'd0;
   initial cfg_hblank = 4'd0;
   initial cfg_inv = 1'b0;
   initial cfg_blank = 8'h00;
   initial div_cnt = 4'd0;
   initial hb_cnt = 4'd0;
   initial col_out = 5'd0;
   initial px_q = 8'h00;
   initial px_vld = 1'b0;
   initial px_eol = 1'b0;
   initial eof_pend = 1'b0;
   initial sig_run = 8'h00;
   initial sig_last = 8'h00;
   initial stall_cnt = 8'd0;

   function [7:0] crc8_step;
       input [7:0] c;
       input [7:0] d;
       integer b;
       reg [7:0] x;
       begin
           x = c ^ d;
           for (b = 0; b < 8; b = b + 1)
               x = x[7] ? ((x << 1) ^ 8'h07) : (x << 1);
           crc8_step = x;
       end
   endfunction

   wire full = (cnt == DEPTH);
   wire empty = (cnt == 3'd0);
   wire tick = (div_cnt == 4'd0);
   wire in_hb = (hb_cnt != 4'd0);
   wire acc = push && !full;
   wire pop = tick && !in_hb && !empty;
   wire [7:0] head_pix = fifo[rd_ptr] ^ {8{cfg_inv}};

   assign ready = !full;
   assign drained = eof_pend && empty && tick && !in_hb;
   assign eof_pend_o = eof_pend;
   assign fill_o = cnt;
   assign col_o = col_out;
   assign px_o = px_q;
   assign px_vld_o = px_vld;
   assign px_eol_o = px_eol;
   assign hblank_o = in_hb;
   assign sig_o = sig_last;
   assign stall_o = stall_cnt;

   always @(posedge clk) begin
       if (!rst_n) begin
           for (j = 0; j < 4; j = j + 1)
               fifo[j] <= 8'h00;
           wr_ptr <= 2'd0;
           rd_ptr <= 2'd0;
           cnt <= 3'd0;
           cfg_div <= 4'd0;
           cfg_hblank <= 4'd0;
           cfg_inv <= 1'b0;
           cfg_blank <= 8'h00;
           div_cnt <= 4'd0;
           hb_cnt <= 4'd0;
           col_out <= 5'd0;
           px_q <= 8'h00;
           px_vld <= 1'b0;
           px_eol <= 1'b0;
           eof_pend <= 1'b0;
           sig_run <= 8'h00;
           sig_last <= 8'h00;
           stall_cnt <= 8'd0;
       end else if (en) begin
           if (frame_act && full && !abort_req && (stall_cnt != 8'hFF))
               stall_cnt <= stall_cnt + 8'd1;
           if (csr_we) begin
               case (csr_addr)
                   3'd4: cfg_div <= csr_wdata[3:0];
                   3'd5: cfg_hblank <= csr_wdata[3:0];
                   3'd6: begin
                       cfg_inv <= csr_wdata[0];
                       if (csr_wdata[7])
                           stall_cnt <= 8'd0;
                   end
                   3'd7: cfg_blank <= csr_wdata;
               endcase
           end
           if (abort_req) begin
               wr_ptr <= 2'd0;
               rd_ptr <= 2'd0;
               cnt <= 3'd0;
               div_cnt <= 4'd0;
               hb_cnt <= 4'd0;
               col_out <= 5'd0;
               px_q <= cfg_blank;
               px_vld <= 1'b0;
               px_eol <= 1'b0;
               eof_pend <= 1'b0;
               sig_run <= 8'h00;
           end else begin
               if (acc) begin
                   fifo[wr_ptr] <= push_pix;
                   wr_ptr <= wr_ptr + 2'd1;
                   if (push_eof)
                       eof_pend <= 1'b1;
               end
               if (acc && !pop)
                   cnt <= cnt + 3'd1;
               else if (pop && !acc)
                   cnt <= cnt - 3'd1;
               if (!tick)
                   div_cnt <= div_cnt - 4'd1;
               else if (pop || in_hb)
                   div_cnt <= cfg_div;
               if (tick) begin
                   if (in_hb) begin
                       hb_cnt <= hb_cnt - 4'd1;
                       px_q <= cfg_blank;
                       px_vld <= 1'b0;
                       px_eol <= 1'b0;
                   end else if (pop) begin
                       px_q <= head_pix;
                       px_vld <= 1'b1;
                       rd_ptr <= rd_ptr + 2'd1;
                       sig_run <= crc8_step(sig_run, head_pix);
                       if (col_out == LINE_LAST) begin
                           col_out <= 5'd0;
                           hb_cnt <= cfg_hblank;
                           px_eol <= 1'b1;
                       end else begin
                           col_out <= col_out + 5'd1;
                           px_eol <= 1'b0;
                       end
                   end else begin
                       px_q <= cfg_blank;
                       px_vld <= 1'b0;
                       px_eol <= 1'b0;
                   end
               end
               if (drained) begin
                   eof_pend <= 1'b0;
                   sig_last <= sig_run;
                   sig_run <= 8'h00;
               end
           end
       end
   end
endmodule
module tplan_seq_ctrl (
   input wire clk,
   input wire rst_n,
   input wire en,
   input wire [1:0] phase_i,
   input wire start_req,
   input wire abort_req,
   input wire frame_end,
   input wire csr_we,
   input wire [2:0] csr_addr,
   input wire [7:0] csr_wdata,
   output wire start_ack,
   output wire fire,
   output wire rearm,
   output wire busy,
   output wire pend_o,
   output wire loop_pend_o,
   output wire ovr_o,
   output wire [3:0] delay_o,
   output wire [3:0] loops_o
);
   reg [3:0] cfg_preroll;
   reg [3:0] cfg_loops;
   reg       cfg_auto;
   reg       pend;
   reg [3:0] delay_cnt;
   reg       loop_pend;
   reg [3:0] loops_left;
   reg       ovr;
   initial cfg_preroll = 4'd0;
   initial cfg_loops = 4'd0;
   initial cfg_auto = 1'b0;
   initial pend = 1'b0;
   initial delay_cnt = 4'd0;
   initial loop_pend = 1'b0;
   initial loops_left = 4'd0;
   initial ovr = 1'b0;
   wire armed = (phase_i == 2'd1);
   wire fin = (phase_i == 2'd3);
   assign start_ack = armed && !pend && !abort_req && (start_req || loop_pend);
   assign fire = pend && (delay_cnt == 4'd0) && !abort_req;
   assign rearm = fin && loop_pend && !abort_req;
   assign busy = pend || loop_pend;
   assign pend_o = pend;
   assign loop_pend_o = loop_pend;
   assign ovr_o = ovr;
   assign delay_o = delay_cnt;
   assign loops_o = loops_left;
   always @(posedge clk) begin
       if (!rst_n) begin
           cfg_preroll <= 4'd0;
           cfg_loops <= 4'd0;
           cfg_auto <= 1'b0;
           pend <= 1'b0;
           delay_cnt <= 4'd0;
           loop_pend <= 1'b0;
           loops_left <= 4'd0;
           ovr <= 1'b0;
       end else if (en) begin
           if (csr_we) begin
               case (csr_addr)
                   3'd0: cfg_preroll <= csr_wdata[3:0];
                   3'd1: cfg_loops <= csr_wdata[3:0];
                   3'd2: cfg_auto <= csr_wdata[0];
                   3'd3: ovr <= 1'b0;
               endcase
           end
           if (start_req && pend && !abort_req)
               ovr <= 1'b1;
           if (abort_req) begin
               pend <= 1'b0;
               delay_cnt <= 4'd0;
               loop_pend <= 1'b0;
               loops_left <= 4'd0;
           end else begin
               if (start_ack) begin
                   pend <= 1'b1;
                   delay_cnt <= cfg_preroll;
                   if (loop_pend) begin
                       loop_pend <= 1'b0;
                       loops_left <= loops_left - 4'd1;
                   end else begin
                       loops_left <= cfg_loops;
                   end
               end else if (pend) begin
                   if (delay_cnt == 4'd0)
                       pend <= 1'b0;
                   else
                       delay_cnt <= delay_cnt - 4'd1;
               end
               if (frame_end && cfg_auto && (loops_left != 4'd0))
                   loop_pend <= 1'b1;
           end
       end
   end
endmodule
module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
   output wire o_done,
   output wire o_seq_busy,
  output wire [10:0] o_seq_stat,
  output wire [7:0] o_scan_pix,
  output wire o_scan_vld,
  output wire o_scan_eol,
  output wire o_scan_hblank,
  output wire o_scan_ready,
  output wire o_drain_busy,
  output wire [7:0] o_scan_fill_col,
  output wire [7:0] o_frame_sig,
  output wire [7:0] o_scan_stall
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);
   wire seq_start_ack, seq_fire, seq_rearm, seq_busy;
   wire seq_pend, seq_loop_pend, seq_ovr;
   wire [3:0] seq_delay;
   wire [3:0] seq_loops;
  wire dr_ready, dr_drained, dr_eof_pend;
  wire dr_px_vld, dr_px_eol, dr_hblank;
  wire [2:0] dr_fill;
  wire [4:0] dr_col;
  wire [7:0] dr_px;
  wire [7:0] dr_sig;
  wire [7:0] dr_stall;
  wire [7:0] gen_pix = font_row(cur_char, row_cnt[2:0]);
  wire px_push = (phase == RUN) && !abort_req && dr_ready;
  wire frame_end = px_push && last_col && last_row;
   wire csr_we = wr_en && (wr_addr[4:3] == 2'b11);
   tplan_seq_ctrl u_seq (
       .clk(clk),
       .rst_n(rst_n),
       .en(en),
       .phase_i(phase),
       .start_req(start_req),
       .abort_req(abort_req),
       .frame_end(frame_end),
       .csr_we(csr_we),
       .csr_addr(wr_addr[2:0]),
       .csr_wdata(wr_data[7:0]),
       .start_ack(seq_start_ack),
       .fire(seq_fire),
       .rearm(seq_rearm),
       .busy(seq_busy),
       .pend_o(seq_pend),
       .loop_pend_o(seq_loop_pend),
       .ovr_o(seq_ovr),
       .delay_o(seq_delay),
       .loops_o(seq_loops)
   );
  tplan_px_drain u_drain (
      .clk(clk),
      .rst_n(rst_n),
      .en(en),
      .abort_req(abort_req),
      .frame_act(phase == RUN),
      .push(px_push),
      .push_eof(last_col && last_row),
      .push_pix(gen_pix),
      .csr_we(csr_we),
      .csr_addr(wr_addr[2:0]),
      .csr_wdata(wr_data[7:0]),
      .ready(dr_ready),
      .drained(dr_drained),
      .eof_pend_o(dr_eof_pend),
      .fill_o(dr_fill),
      .col_o(dr_col),
      .px_o(dr_px),
      .px_vld_o(dr_px_vld),
      .px_eol_o(dr_px_eol),
      .hblank_o(dr_hblank),
      .sig_o(dr_sig),
      .stall_o(dr_stall)
  );

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                       if (seq_start_ack) begin
                           start_seen <= 1'b1;
                           col_cnt <= 64'd0;
                           row_cnt <= 64'd0;
                       end
                       if (seq_fire)
                           phase <= RUN;
                    end
                    RUN: begin
                      if (dr_ready) begin
                       pix_row <= gen_pix;
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                      end
                    end
                    FIN: begin
                      if ((arm_req || seq_rearm) && !dr_eof_pend) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
              if (dr_drained)
                  done <= 1'b1;
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;
   assign o_seq_busy = seq_busy;
   assign o_seq_stat = {seq_pend, seq_loop_pend, seq_ovr, seq_loops, seq_delay};
  assign o_scan_pix = dr_px;
  assign o_scan_vld = dr_px_vld;
  assign o_scan_eol = dr_px_eol;
  assign o_scan_hblank = dr_hblank;
  assign o_scan_ready = dr_ready;
  assign o_drain_busy = dr_eof_pend;
  assign o_scan_fill_col = {dr_fill, dr_col};
  assign o_frame_sig = dr_sig;
  assign o_scan_stall = dr_stall;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module modexp_sdr (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire [7:0] in_base,
    input  wire [7:0] in_exp,
    output wire [7:0] o_result,
    output wire       o_busy
);
    localparam [7:0] MOD = 8'd251;

    reg [7:0] base_r = 8'd0;
    reg [7:0] result = 8'd1;
    reg [7:0] exp_sr = 8'd0;
    reg [7:0] cnt    = 8'd0;
    reg       busy   = 1'b0;

    // square-and-multiply datapath (MSB first)
    wire [15:0] sq_full  = {8'd0, result} * {8'd0, result};
    wire [15:0] sq_mod   = sq_full % {8'd0, MOD};
    wire [7:0]  sq       = sq_mod[7:0];
    wire [15:0] mul_full = {8'd0, sq} * {8'd0, base_r};
    wire [15:0] mul_mod  = mul_full % {8'd0, MOD};
    wire [7:0]  mul      = mul_mod[7:0];
    wire [7:0]  next_res = exp_sr[7] ? mul : sq;

    wire [15:0] base_mod = {8'd0, in_base} % {8'd0, MOD};

    // bits of the exponent register already consumed must be zero
    wire [7:0] exp_tail = exp_sr << cnt;

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (start) begin
                    base_r <= base_mod[7:0];
                    result <= 8'd1;
                    exp_sr <= in_exp;
                    cnt    <= 8'd8;
                    busy   <= 1'b1;
                end
            end else begin
                result <= next_res;
                exp_sr <= {exp_sr[6:0], 1'b0};
                cnt    <= cnt - 8'd1;
                if (cnt == 8'd1)
                    busy <= 1'b0;
            end
        end
    end

    assign o_result = result;
    assign o_busy   = busy;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // inside the busy window: on the final exponent bit, only the MSB may remain
    always @(posedge clk)
        if (pv && $past(busy) && ($past(cnt) == 8'd1))
            assert (($past(exp_sr) & 8'h7F) == 8'h00);
endmodule

module crc8_onehot_check (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire data_bit,
    output reg [3:0] st,
    output reg [7:0] crc,
    output reg [2:0] bitcnt,
    output reg crc_busy,
    output reg crc_valid
);
    // one-hot phases: bit0 = IDLE, bit1 = SHIFT, bit2 = FINAL, bit3 = DONE
    initial st        = 4'b0001;
    initial crc       = 8'hFF;
    initial bitcnt    = 3'd0;
    initial crc_busy  = 1'b0;
    initial crc_valid = 1'b0;

    wire       fb       = crc[7] ^ data_bit;
    wire [7:0] crc_next = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);

    always @(posedge clk) begin
        if (rst) begin
            st        <= 4'b0001;
            crc       <= 8'hFF;
            bitcnt    <= 3'd0;
            crc_busy  <= 1'b0;
            crc_valid <= 1'b0;
        end else if (ce) begin
            // IDLE arm: accepting a new byte starts the shifter
            if (st[0]) begin
                if (start) begin
                    st       <= 4'b0010;
                    crc      <= 8'hFF;
                    bitcnt   <= 3'd0;
                    crc_busy <= 1'b1;
                end
            end
            // SHIFT arm: one bit of the polynomial reduction per cycle
            if (st[1]) begin
                crc    <= crc_next;
                bitcnt <= bitcnt + 3'd1;
                if (bitcnt == 3'd7) begin
                    st       <= 4'b0100;
                    crc_busy <= 1'b0;
                end
            end
            // FINAL arm: remainder settled, publish it
            if (st[2]) begin
                st        <= 4'b1000;
                crc_valid <= 1'b1;
            end
            // DONE arm: consumer has seen the result
            if (st[3]) begin
                st        <= 4'b0001;
                crc_valid <= 1'b0;
            end
        end
    end

    always @(*)
        assert (!(crc_busy && crc_valid));
endmodule

module elastic_skid_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_valid,
    output wire       o_full
);
    // two-entry elastic buffer with head/tail flags and a redundant occupancy count
    reg [7:0] mem0;
    reg [7:0] mem1;
    reg       v0;
    reg       v1;
    reg       head;
    reg       tail;
    reg [2:0] count;

    initial begin
        mem0  = 8'd0;
        mem1  = 8'd0;
        v0    = 1'b0;
        v1    = 1'b0;
        head  = 1'b0;
        tail  = 1'b0;
        count = 3'd0;
    end

    wire full  = v0 && v1;
    wire empty = !v0 && !v1;

    wire do_push = i_push && !full;
    wire do_pop  = i_pop  && !empty;

    assign o_full  = full;
    assign o_valid = !empty;
    assign o_data  = head ? mem1 : mem0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            head  <= 1'b0;
            tail  <= 1'b0;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                if (tail) begin
                    mem1 <= i_data;
                    v1   <= 1'b1;
                end else begin
                    mem0 <= i_data;
                    v0   <= 1'b1;
                end
                tail <= ~tail;
            end

            if (do_pop) begin
                if (head)
                    v1 <= 1'b0;
                else
                    v0 <= 1'b0;
                head <= ~head;
            end

            if (do_push && !do_pop)
                count <= count + 3'd1;
            else if (do_pop && !do_push)
                count <= count - 3'd1;
        end
    end

    // P: occupancy never exceeds the two-entry depth, although the counter is 3 bits wide
    always @(posedge clk)
        assert (count <= 3'd2);
endmodule

module token_chain (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // global enable: low freezes all state
    input  wire i_tick,    // refill timer tick
    input  wire i_arm,     // step 1: arm a transfer request
    input  wire i_start,   // step 2: start it (consumes a token)
    input  wire i_finish,  // step 3: transfer completes
    output wire o_grant,
    output wire o_busy,
    output wire [2:0] o_tokens
);
    localparam [2:0] BURST  = 3'd4;
    localparam [1:0] S_IDLE = 2'd0,
                     S_ARMED= 2'd1,
                     S_RUN  = 2'd2;

    // ---- state ----
    reg [1:0] state;
    reg [2:0] tokens;    // token bucket, capped at BURST
    reg       seen_arm;
    reg       seen_start;
    reg       seen_fin;

    initial state      = S_IDLE;
    initial tokens     = BURST;
    initial seen_arm   = 1'b0;
    initial seen_start = 1'b0;
    initial seen_fin   = 1'b0;

    // ---- chain events ----
    wire arm_pulse   = i_ce && !rst && (state == S_IDLE)  && i_arm;
    wire start_pulse = i_ce && !rst && (state == S_ARMED) && i_start && (tokens != 3'd0);
    wire fin_pulse   = i_ce && !rst && (state == S_RUN)   && i_finish;

    // refill on timer tick, never above the burst cap
    wire refill      = i_ce && !rst && i_tick && (tokens < BURST);

    assign o_grant  = start_pulse;
    assign o_busy   = (state == S_RUN);
    assign o_tokens = tokens;

    // ---- three-step request machine ----
    always @(posedge clk)
        if (rst)
            state <= S_IDLE;
        else if (i_ce) begin
            case (state)
                S_IDLE:  if (i_arm)                        state <= S_ARMED;
                S_ARMED: if (i_start && (tokens != 3'd0))  state <= S_RUN;
                S_RUN:   if (i_finish)                     state <= S_IDLE;
                default:                                   state <= S_IDLE;
            endcase
        end

    // ---- token bucket: drains on grant, refills on tick ----
    always @(posedge clk)
        if (rst)
            tokens <= BURST;
        else if (start_pulse && refill)
            tokens <= tokens;
        else if (start_pulse)
            tokens <= tokens - 3'd1;
        else if (refill)
            tokens <= tokens + 3'd1;

    // ---- sticky chain observation bits ----
    always @(posedge clk)
        if (rst) begin
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            seen_fin   <= 1'b0;
        end else begin
            if (arm_pulse)   seen_arm   <= 1'b1;
            if (start_pulse) seen_start <= 1'b1;
            if (fin_pulse)   seen_fin   <= 1'b1;
        end

    // ---- property: a finish is never observed unless arm and start happened ----
    always @(posedge clk)
        if (seen_fin)
            assert (seen_arm && seen_start);
endmodule

module sat_event_counter (
    input  wire clk,
    input  wire clr,
    input  wire step,
    output wire o_empty,
    output wire o_full,
    output wire [3:0] o_count
);
    localparam [3:0] MAX = 4'd12;

    // saturating up-counter: clamps at 12, well below what 4 bits admit
    reg [3:0] cnt   = 4'd0;
    reg       zero_f = 1'b1;   // "no events yet / cleared" flag
    reg       sat_f  = 1'b0;   // "counter has reached its clamp" flag

    initial begin
        cnt    = 4'd0;
        zero_f = 1'b1;
        sat_f  = 1'b0;
    end

    wire [3:0] nxt = (cnt == MAX) ? MAX : (cnt + 4'd1);

    always @(posedge clk) begin
        if (clr) begin
            cnt    <= 4'd0;
            zero_f <= 1'b1;
            sat_f  <= 1'b0;
        end else if (step) begin
            cnt <= nxt;
            // zero_f is only dropped on the step that leaves the zero point
            if (cnt == 4'd0)
                zero_f <= 1'b0;
            // sat_f tracks arrival at the clamp value
            sat_f <= (nxt == MAX);
        end
    end

    assign o_empty = zero_f;
    assign o_full  = sat_f;
    assign o_count = cnt;

    // P: while the counter is being commanded, it can never report
    //    empty and full at the same time.
    always @(posedge clk)
        if (step || clr)
            assert (!(o_empty && o_full));
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
    wire [2:0] delta = sync1 ^ sync2;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;

            if (bad_ev) begin
                stage <= S_FINISH;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                S_STARTED:
                    if (fin_ev)
                        stage <= S_FINISH;
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
    assign o_done  = (stage == S_FINISH);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
endmodule

module boot_key_debounce (
    input  wire clk,
    input  wire ce,
    input  wire raw_key,
    output wire clean_key,
    output wire menu_armed
);
    // K identical consecutive samples are required before the clean
    // boot-menu key output is allowed to follow the raw input.
    parameter [2:0] K = 3'd6;

    reg       samp;    // last registered raw sample
    reg [2:0] cnt;     // stability counter, saturates at K
    reg       at_k;    // registered decode of (cnt == K-1)
    reg       shadow;  // value captured one step before the commit
    reg       clean;   // debounced output
    reg       armed;   // sticky: set at the first commit, never cleared

    initial begin
        samp   = 1'b0;
        cnt    = 3'd0;
        at_k   = 1'b0;
        shadow = 1'b0;
        clean  = 1'b0;
        armed  = 1'b0;
    end

    wire       match    = (raw_key == samp);
    wire [2:0] next_cnt = (!match) ? 3'd0 : ((cnt < K) ? (cnt + 3'd1) : K);
    wire       commit   = at_k && match;

    always @(posedge clk) if (ce) begin
        samp <= raw_key;
        cnt  <= next_cnt;
        at_k <= (next_cnt == (K - 3'd1));

        // one step before the run completes, record the value that is
        // about to be committed to the clean output
        if (match && (cnt == (K - 3'd2)))
            shadow <= samp;

        // the run of K identical samples completes here
        if (commit) begin
            clean <= shadow;
            armed <= 1'b1;
        end
    end

    assign clean_key  = clean;
    assign menu_armed = armed;

    // Precedence, in the "after first commit" scope: whenever the counter
    // is saturated, the clean output must already carry the value that was
    // shadowed when the stable run was recognised.
    always @(posedge clk)
        if (armed && (cnt == K))
            assert (clean == shadow);
endmodule

module fetch_handshake (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,      // global enable: low => design idles
    input  wire       start,     // new cell fetch requested
    input  wire [7:0] cell_in,
    output reg        req,
    output reg        ack,
    output reg        busy,
    output reg [7:0]  cell_q,
    output reg [3:0]  rows_done
);

    // four-phase handshake sequencer
    //   0 : idle          req=0 ack=0 busy=0
    //   1 : req asserted  req=1 ack=0 busy=1
    //   2 : ack asserted  req=1 ack=1 busy=1
    //   3 : req dropped   req=0 ack=1 busy=1
    reg [1:0] phase;

    initial begin
        phase     = 2'd0;
        req       = 1'b0;
        ack       = 1'b0;
        busy      = 1'b0;
        cell_q    = 8'd0;
        rows_done = 4'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase     <= 2'd0;
            req       <= 1'b0;
            ack       <= 1'b0;
            busy      <= 1'b0;
            cell_q    <= 8'd0;
            rows_done <= 4'd0;
        end else if (step) begin
            case (phase)
                2'd0: begin
                    // requester raises req and marks itself busy
                    if (start) begin
                        phase <= 2'd1;
                        req   <= 1'b1;
                        busy  <= 1'b1;
                    end
                end
                2'd1: begin
                    // responder acknowledges and presents the cell
                    phase  <= 2'd2;
                    ack    <= 1'b1;
                    cell_q <= cell_in;
                end
                2'd2: begin
                    // req may only drop after ack has risen
                    phase <= 2'd3;
                    req   <= 1'b0;
                end
                2'd3: begin
                    // responder retires the transaction; it releases ack
                    // only once it observes req deasserted
                    phase     <= 2'd0;
                    busy      <= 1'b0;
                    rows_done <= rows_done + 4'd1;
                    if (!req) ack <= 1'b0;
                end
            endcase
        end
    end

    // P: the busy flag covers every live handshake wire, in every state
    always @(posedge clk)
        if (req) assert (busy);

    always @(posedge clk)
        if (ack) assert (busy);

endmodule

module histogram_commit_engine (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [1:0]  bin_sel,
    output reg         busy,
    output reg  [1:0]  timer,
    output wire [9:0]  samples
);
    // histogram bins, incremented one at a time
    reg [7:0] bin0, bin1, bin2, bin3;
    // total-samples register
    reg [9:0] total;
    // which bin the outstanding request targets
    reg [1:0] sel;

    initial begin
        bin0  = 8'd0;
        bin1  = 8'd0;
        bin2  = 8'd0;
        bin3  = 8'd0;
        total = 10'd0;
        sel   = 2'd0;
        busy  = 1'b0;
        timer = 2'd0;
    end

    assign samples = total;

    wire [9:0] sum = {2'b00, bin0} + {2'b00, bin1} + {2'b00, bin2} + {2'b00, bin3};

    // headroom check performed when a request is accepted
    wire bins_ok = (bin0 < 8'hf0) && (bin1 < 8'hf0) && (bin2 < 8'hf0) && (bin3 < 8'hf0);

    // bookkeeping audit: bins must account for every recorded sample
    wire consistent = (sum == total);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 8'd0;
            bin1  <= 8'd0;
            bin2  <= 8'd0;
            bin3  <= 8'd0;
            total <= 10'd0;
            sel   <= 2'd0;
            busy  <= 1'b0;
            timer <= 2'd0;
        end else if (ce) begin
            if (!busy) begin
                if (start && bins_ok) begin
                    busy  <= 1'b1;
                    timer <= 2'd3;
                    sel   <= bin_sel;
                end
            end else begin
                if (timer != 2'd0)
                    timer <= timer - 2'd1;
                // the commit fires on the last countdown tick, but only if the
                // audit passes; otherwise the request stays outstanding
                if ((timer == 2'd1) && consistent) begin
                    busy  <= 1'b0;
                    total <= total + 10'd1;
                    case (sel)
                        2'd0: bin0 <= bin0 + 8'd1;
                        2'd1: bin1 <= bin1 + 8'd1;
                        2'd2: bin2 <= bin2 + 8'd1;
                        2'd3: bin3 <= bin3 + 8'd1;
                    endcase
                end
            end
        end
    end

    // Bounded response, safety form: the countdown never expires while the
    // accepted sample request is still outstanding.
    always @(posedge clk)
        assert (!(busy && (timer == 2'd0)));
endmodule

module rr_credit_arb (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    input  wire       i_ack_valid,
    input  wire [1:0] i_ack_id,
    output wire [3:0] o_grant,
    output wire [2:0] o_occ,
    output wire       o_armed
);
    // ---------------------------------------------------------------
    // Round-robin arbiter over 4 requesters with a last-grant pointer.
    // A line that already owns an outstanding grant (ack_pend) is
    // masked out, so a grant never lands on a busy or non-requesting
    // line, and the grant vector is one-hot-or-zero by construction.
    // ---------------------------------------------------------------
    reg [3:0] ack_pend;   // outstanding (granted, not yet acked) lines
    reg [2:0] occ;        // occupancy: number of outstanding grants
    reg [1:0] last;       // last granted index (round-robin pointer)
    reg       armed;      // high until line 3 has ever been granted

    initial ack_pend = 4'b0000;
    initial occ      = 3'd0;
    initial last     = 2'd3;
    initial armed    = 1'b1;

    wire [3:0] mreq = i_req & ~ack_pend;

    wire [1:0] p1 = last + 2'd1;
    wire [1:0] p2 = last + 2'd2;
    wire [1:0] p3 = last + 2'd3;

    reg [3:0] gnt_c;
    always @(*) begin
        gnt_c = 4'b0000;
        if (mreq[p1])       gnt_c = (4'b0001 << p1);
        else if (mreq[p2])  gnt_c = (4'b0001 << p2);
        else if (mreq[p3])  gnt_c = (4'b0001 << p3);
        else if (mreq[last])gnt_c = (4'b0001 << last);
    end

    wire       gnt_any = |gnt_c;
    wire [1:0] gidx    = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    // an ack only counts if that line really has an outstanding grant
    wire       eff_ack   = i_ack_valid && ack_pend[i_ack_id];
    wire [3:0] ack_mask  = eff_ack ? (4'b0001 << i_ack_id) : 4'b0000;

    always @(posedge i_clk) begin
        if (i_reset) begin
            ack_pend <= 4'b0000;
            occ      <= 3'd0;
            last     <= 2'd3;
            armed    <= 1'b1;
        end else if (i_ce) begin
            ack_pend <= (ack_pend | gnt_c) & ~ack_mask;
            occ      <= occ + {2'b00, gnt_any} - {2'b00, eff_ack};
            if (gnt_any)
                last <= gidx;
            if (gnt_c[3])
                armed <= 1'b0;
        end
    end

    assign o_grant = i_ce ? gnt_c : 4'b0000;
    assign o_occ   = occ;
    assign o_armed = armed;

    // Property: before line 3 has ever been granted, at most three
    // grants can be outstanding at once (occ is 3 bits wide).
    always @(posedge i_clk)
        if (armed)
            assert (occ <= 3'd3);
endmodule

// Gray-coded write pointer crossing into a second domain through a
// two-flop synchronizer, with a shadow register recording the previously
// observed synchronized sample.
module gray_ptr_cdc (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle condition: low freezes all state
    input  wire       push,
    output wire [3:0] o_gray,
    output wire [3:0] o_gray_shadow
);

    // source-domain binary pointer and its gray encoding
    reg [3:0] bin;
    reg [3:0] wgray;

    // two-flop synchronizer
    reg [3:0] s1;
    reg [3:0] s2;

    // shadow: the sample observed one enabled cycle earlier
    reg [3:0] s2_prev;

    initial begin
        bin     = 4'd0;
        wgray   = 4'd0;
        s1      = 4'd0;
        s2      = 4'd0;
        s2_prev = 4'd0;
    end

    wire [3:0] nbin = bin + (push ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            bin     <= 4'd0;
            wgray   <= 4'd0;
            s1      <= 4'd0;
            s2      <= 4'd0;
            s2_prev <= 4'd0;
        end else if (i_ce) begin
            bin     <= nbin;
            wgray   <= nbin ^ (nbin >> 1);
            s1      <= wgray;
            s2      <= s1;
            s2_prev <= s2;
        end
    end

    assign o_gray        = s2;
    assign o_gray_shadow = s2_prev;

    // Hamming distance between the present sample and the shadow sample
    wire [3:0] d_a = s2 ^ s2_prev;
    wire [2:0] n_a = {2'b0, d_a[0]} + {2'b0, d_a[1]} +
                     {2'b0, d_a[2]} + {2'b0, d_a[3]};

    // Hamming distance between the first-flop sample and the shadow sample
    wire [3:0] d_b = s1 ^ s2_prev;
    wire [2:0] n_b = {2'b0, d_b[0]} + {2'b0, d_b[1]} +
                     {2'b0, d_b[2]} + {2'b0, d_b[3]};

    // P1: whatever value is observed now must have been preceded by a value
    //     at most one bit away.
    always @(posedge clk)
        assert (n_a <= 3'd1);

    // P2: the value about to be observed is at most two bits away from the
    //     value observed two enabled cycles ago.
    always @(posedge clk)
        assert (n_b <= 3'd2);

endmodule

// Stack pointer with a ratcheting high-water mark, plus a three-step
// arm -> start -> finish transaction FSM whose start step needs live data
// on the stack.
module hwm_chain_precedence (
    input  wire clk,
    input  wire ce,
    input  wire i_push,
    input  wire i_pop,
    input  wire i_arm,
    input  wire i_start,
    input  wire i_finish,
    input  wire i_clear,
    output wire o_finish,
    output wire [3:0] o_mark
);
    localparam [3:0] DEPTH = 4'd8;

    localparam [1:0] S_IDLE    = 2'd0;
    localparam [1:0] S_ARMED   = 2'd1;
    localparam [1:0] S_STARTED = 2'd2;
    localparam [1:0] S_DONE    = 2'd3;

    reg [3:0] sp;
    reg [3:0] hwm;      // high-water mark: never below sp, only ratchets up
    reg [1:0] stage;
    reg       saw_arm;
    reg       saw_start;
    reg       obs_en;    // sticky: set the first cycle a push is accepted

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial stage     = S_IDLE;
    initial saw_arm   = 1'b0;
    initial saw_start = 1'b0;
    initial obs_en    = 1'b0;

    wire do_push = ce && i_push && !i_pop && (sp <  DEPTH);
    wire do_pop  = ce && i_pop  && !i_push && (sp != 4'd0);

    wire [4:0] nxt_sp = {1'b0, sp} + 5'd1;

    // ---- stack pointer and high-water mark -------------------------------
    always @(posedge clk) begin
        if (do_push) begin
            sp     <= sp + 4'd1;
            obs_en <= 1'b1;
            if (nxt_sp > {1'b0, hwm})
                hwm <= nxt_sp[3:0];
        end else if (do_pop) begin
            sp <= sp - 4'd1;
        end
    end

    // ---- three-step chain: arm, then start, then finish ------------------
    always @(posedge clk) begin
        if (ce) begin
            case (stage)
                S_IDLE: begin
                    if (i_arm) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                end
                S_ARMED: begin
                    if (i_start && (sp != 4'd0)) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                end
                S_STARTED: begin
                    if (i_finish && (sp != 4'd0))
                        stage <= S_DONE;
                end
                default: begin
                    if (i_clear)
                        stage <= S_IDLE;
                end
            endcase
        end
    end

    assign o_finish = (stage == S_DONE);
    assign o_mark   = hwm;

    // Property: once the mark has been armed by a first push, a finish can
    // never be observed unless arm and start were both observed before it and
    // the high-water mark records that data was really on the stack.
    assert property (!obs_en || !o_finish ||
                     (saw_arm && saw_start && (hwm >= 4'd1)));
endmodule

module frame_fifo (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire       push,    // request: enqueue a frame command
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       full,
    output wire       empty,
    output wire       expired
);
    // ---- FIFO state: two pointers plus an occupancy counter -------------
    reg [2:0] wptr  = 3'd0;
    reg [2:0] rptr  = 3'd0;
    reg [2:0] count = 3'd0;   // occupancy, capacity 7 so diff is unambiguous

    // ---- bounded-response countdown for the drain engine ----------------
    reg [3:0] timer = 4'd0;

    // ---- sticky arm: set the first time a request is accepted -----------
    reg       armed = 1'b0;

    reg [7:0] mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'd0;
    end

    assign full    = (count == 3'd7);
    assign empty   = (count == 3'd0);
    assign dout    = mem[rptr];
    assign expired = (timer == 4'd0);

    // write port has priority; the drain engine pops on any idle-of-push cycle
    wire       wr = push && !full;
    wire       rd = !push && !empty;

    // next write pointer and the resulting pointer difference
    wire [2:0] nwptr = wptr + {2'b00, wr};
    wire [2:0] ndiff = nwptr - rptr;

    always @(posedge clk) begin
        if (ce) begin
            if (wr) begin
                mem[wptr] <= din;
                wptr      <= wptr + 3'd1;
                armed     <= 1'b1;
            end
            if (rd)
                rptr <= rptr + 3'd1;

            count <= count + {2'b00, wr} - {2'b00, rd};

            // a new request reloads the deadline from the pointer distance
            if (push)
                timer <= {1'b0, ndiff} + 4'd2;
            else if (timer != 4'd0)
                timer <= timer - 4'd1;
        end
    end

    // P: after the engine has been armed, the countdown must never be
    //    expired while work is still outstanding in the queue.
    always @(posedge clk)
        assert (!armed || count == 3'd0 || timer != 4'd0);
endmodule

module dma_burst_engine (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_start,
    input wire [4:0] i_len,
    input wire [11:0] i_base,
    output reg o_busy
);
    // beats-remaining counter and its bookkeeping companions
    reg [4:0]  beats_left;
    reg [4:0]  beats_done;
    reg [4:0]  burst_len;
    reg [11:0] addr;
    reg [11:0] base;

    initial begin
        o_busy     = 1'b0;
        beats_left = 5'd0;
        beats_done = 5'd0;
        burst_len  = 5'd0;
        addr       = 12'd0;
        base       = 12'd0;
    end

    // requested length is clamped to the engine's maximum burst of 16 beats
    wire [4:0] eff_len = (i_len > 5'd16) ? 5'd16 : i_len;
    wire       accept  = (!o_busy) && i_start && (i_len != 5'd0);

    // address one past the last beat of the current burst
    wire [11:0] end_addr = base + ({7'd0, burst_len} << 2);

    always @(posedge clk) begin
        if (rst) begin
            o_busy     <= 1'b0;
            beats_left <= 5'd0;
            beats_done <= 5'd0;
            burst_len  <= 5'd0;
            addr       <= 12'd0;
            base       <= 12'd0;
        end else if (i_ce) begin
            if (o_busy) begin
                // issue one beat
                beats_left <= beats_left - 5'd1;
                beats_done <= beats_done + 5'd1;
                addr       <= addr + 12'd4;
                o_busy     <= (beats_left != 5'd1);
            end else if (accept) begin
                o_busy     <= 1'b1;
                beats_left <= eff_len;
                beats_done <= 5'd0;
                burst_len  <= eff_len;
                addr       <= i_base;
                base       <= i_base;
            end
        end
        // i_ce low: engine idles, all state held
    end

    // P: while the engine is busy, the beat pointer has not yet reached the
    // end of the burst region.
    always @(posedge clk)
        if (o_busy)
            assert (addr != end_addr);
endmodule

module histo_hotbins (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [1:0] sel,
    output wire       full,
    output wire [2:0] o_hot
);
    // Sample histogram: four bins, one increment per accepted sample.
    // The bins always sum to the total-samples register, and the total
    // saturates at MAXTOT, so at most two bins can ever reach THRESH.
    localparam [3:0] MAXTOT = 4'd9;
    localparam [3:0] THRESH = 4'd4;

    reg [3:0] bin0, bin1, bin2, bin3;
    reg [3:0] total;
    reg [2:0] hot;    // number of bins that have reached THRESH
    reg       armed;  // sticky: set the first time hot reaches 2
    reg       pv;     // past-valid

    initial begin
        bin0  = 4'd0;
        bin1  = 4'd0;
        bin2  = 4'd0;
        bin3  = 4'd0;
        total = 4'd0;
        hot   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
    end

    wire accept = ce && !rst && (total < MAXTOT);

    wire [3:0] cur = (sel == 2'd0) ? bin0 :
                     (sel == 2'd1) ? bin1 :
                     (sel == 2'd2) ? bin2 : bin3;

    wire cross = accept && (cur == (THRESH - 4'd1));

    assign full  = (total == MAXTOT);
    assign o_hot = hot;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
            hot   <= 3'd0;
            armed <= 1'b0;
        end else begin
            if (accept) begin
                total <= total + 4'd1;
                case (sel)
                    2'd0:    bin0 <= bin0 + 4'd1;
                    2'd1:    bin1 <= bin1 + 4'd1;
                    2'd2:    bin2 <= bin2 + 4'd1;
                    default: bin3 <= bin3 + 4'd1;
                endcase
                if (cross)
                    hot <= hot + 3'd1;
            end
            if (hot >= 3'd2)
                armed <= 1'b1;
        end
    end

    // P: once the design has been armed (hot first reached its true
    // maximum of 2), the hot-bin occupancy can never change again --
    // i.e. it never exceeds 2, well below what the 3-bit register allows.
    always @(posedge clk)
        if (pv && armed)
            assert ($stable(hot));
endmodule

module arb_lock_green (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,
    input  wire req_a,
    input  wire req_b,
    input  wire rel,
    output wire grant_a,
    output wire grant_b,
    output wire all_red
);
    // Green phase length limit: a locked winner keeps the road for at most
    // GMAX ticks, then must hand over through an all-red interval.
    localparam [3:0] GMAX = 4'd9;

    reg       lock;   // freezes the current winner until it releases
    reg       owner;  // 0 = road A, 1 = road B
    reg [3:0] gcnt;   // green-phase tick counter
    reg [1:0] ar;     // all-red interval countdown

    initial lock  = 1'b0;
    initial owner = 1'b0;
    initial gcnt  = 4'd0;
    initial ar    = 2'd0;

    wire any_req = req_a | req_b;

    always @(posedge clk) begin
        if (rst) begin
            lock  <= 1'b0;
            owner <= 1'b0;
            gcnt  <= 4'd0;
            ar    <= 2'd0;
        end else if (i_ce) begin
            if (lock) begin
                // locked winner runs its green phase
                if (rel || gcnt == GMAX) begin
                    lock <= 1'b0;
                    gcnt <= 4'd0;
                    ar   <= 2'd2;   // enter all-red handover
                end else begin
                    gcnt <= gcnt + 4'd1;
                end
            end else if (ar != 2'd0) begin
                ar <= ar - 2'd1;
            end else if (any_req) begin
                // fixed priority: road A beats road B
                lock  <= 1'b1;
                owner <= ~req_a;
            end
        end
    end

    assign grant_a = lock && (owner == 1'b0);
    assign grant_b = lock && (owner == 1'b1);
    assign all_red = !lock;

    // P: while a road holds the locked green, its phase timer never exceeds
    // GMAX = 9, even though the register could hold up to 15.
    always @(posedge clk)
        if (lock)
            assert (gcnt <= GMAX);
endmodule

// Carry-save split accumulator with a windowed flag-exclusion check.
// The accumulator value is held as two halves (acc_s, acc_c) whose 8-bit sum
// is the true running total; `total` is the directly-accumulated shadow copy.
module cs_accum_window (
    input  wire       clk,
    input  wire       ce,       // idle when low: no state changes at all
    input  wire       clr,
    input  wire       q_start,  // opens the observation window
    input  wire       r_stop,   // closes the observation window
    input  wire [7:0] din,
    output wire [7:0] sum_out
);

    // carry-save halves
    reg [7:0] acc_s;
    reg [7:0] acc_c;
    // golden (direct) accumulator
    reg [7:0] total;

    // window register (scope): set by q_start, cleared by r_stop
    reg       win;

    // two status flags, derived from the two different representations
    reg       f_lo;   // derived from the golden total
    reg       f_hi;   // derived from the carry-save halves

    initial begin
        acc_s = 8'd0;
        acc_c = 8'd0;
        total = 8'd0;
        win   = 1'b0;
        f_lo  = 1'b1;   // total(0) < 16
        f_hi  = 1'b0;   // acc_s+acc_c(0) < 16
    end

    // carry-save incorporation of din
    wire [7:0] cs_sum  = acc_s ^ acc_c ^ din;
    wire [7:0] cs_maj  = (acc_s & acc_c) | (acc_s & din) | (acc_c & din);
    wire [7:0] cs_carry = cs_maj << 1;   // top bit drops: mod-256 arithmetic

    assign sum_out = acc_s + acc_c;

    always @(posedge clk) begin
        if (ce) begin
            if (clr) begin
                acc_s <= 8'd0;
                acc_c <= 8'd0;
                total <= 8'd0;
            end else begin
                acc_s <= cs_sum;
                acc_c <= cs_carry;
                total <= total + din;
            end

            // flags sampled from the pre-update state, each from its own copy
            f_lo <= (total < 8'd16);
            f_hi <= ((acc_s + acc_c) >= 8'd16);

            if (r_stop)       win <= 1'b0;
            else if (q_start) win <= 1'b1;
        end
    end

    // P: inside the window the two flags are never asserted together
    always @(posedge clk)
        if (win)
            assert (!(f_lo && f_hi));

endmodule

module rtos_sched (
    input  wire i_clk,
    input  wire i_ce,       // scheduler tick enable; low means the kernel is idle
    input  wire i_req,      // a thread is ready to run
    input  wire i_kernel,   // the ready thread is a kernel thread
    input  wire i_start,    // first scheduler start event (arms the property)
    output wire o_grant_kern,
    output wire o_grant_user,
    output wire o_running
);

    // binary-encoded scheduler FSM: only 5 of the 8 encodings are ever entered
    localparam [2:0] S_IDLE   = 3'd0;
    localparam [2:0] S_FETCH  = 3'd1;
    localparam [2:0] S_KERNEL = 3'd2;
    localparam [2:0] S_USER   = 3'd3;
    localparam [2:0] S_SWITCH = 3'd4;
    localparam [2:0] S_FAULT  = 3'd6;   // unreachable trap encoding

    reg [2:0] state = S_IDLE;
    reg [1:0] cnt   = 2'd0;   // time-slice quantum counter, full 2-bit range
    reg       g_kern = 1'b0;
    reg       g_user = 1'b0;
    reg       armed  = 1'b0;  // sticky: set the first time the scheduler starts

    reg [2:0] nstate;
    reg       ngk, ngu;

    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_req ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = i_kernel ? S_KERNEL : S_USER;
            S_KERNEL: nstate = (cnt == 2'd3) ? S_SWITCH : S_KERNEL;
            S_USER:   nstate = (cnt == 2'd3) ? S_SWITCH : S_USER;
            S_SWITCH: nstate = i_req ? S_FETCH : S_IDLE;
            default:  nstate = S_FAULT;   // trap encodings lock up
        endcase
    end

    // grant decode for the state being entered
    always @(*) begin
        case (nstate)
            S_IDLE, S_FETCH, S_SWITCH: begin ngk = 1'b0; ngu = 1'b0; end
            S_KERNEL:                  begin ngk = 1'b1; ngu = 1'b0; end
            S_USER:                    begin ngk = 1'b0; ngu = 1'b1; end
            default:                   begin ngk = 1'b1; ngu = 1'b1; end
        endcase
    end

    always @(posedge i_clk) begin
        if (i_ce) begin
            state  <= nstate;
            g_kern <= ngk;
            g_user <= ngu;
            if (nstate == S_KERNEL || nstate == S_USER)
                cnt <= cnt + 2'd1;
            else
                cnt <= 2'd0;
        end
    end

    // sticky arming register: never cleared once the scheduler has started
    always @(posedge i_clk)
        if (i_start)
            armed <= 1'b1;

    assign o_grant_kern = g_kern;
    assign o_grant_user = g_user;
    assign o_running    = g_kern | g_user;

    // Absence: once the scheduler has been started, a kernel grant and a user
    // grant are never asserted together.
    always @(*)
        assert (!armed || !(g_kern && g_user));

endmodule

module fetch_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
    output reg [7:0]  out_data
);
    // ---- skid buffer of a valid/ready instruction-fetch pipeline stage ----
    reg       skid_valid;
    reg [7:0] skid_data;   // only meaningful while skid_valid (stall flag) is up
    reg [2:0] occ;         // shadow occupancy counter
    reg       armed;       // sticky: set the first time back-pressure stalls us

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
    end

    assign in_ready = !skid_valid;

    wire in_fire   = in_valid  && in_ready;
    wire out_fire  = out_valid && out_ready;
    wire capture   = in_fire && out_valid && !out_ready; // stall: park word in skid
    wire drain     = !out_valid || out_ready;            // output slot becomes free

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 3'd0;
        end else begin
            if (capture) begin
                skid_valid <= 1'b1;
                skid_data  <= in_data;
            end

            if (drain) begin
                if (skid_valid) begin
                    out_valid  <= 1'b1;
                    out_data   <= skid_data;
                    skid_valid <= 1'b0;
                end else if (in_fire) begin
                    out_valid  <= 1'b1;
                    out_data   <= in_data;
                end else begin
                    out_valid  <= 1'b0;
                end
            end

            // occupancy bookkeeping
            if (in_fire && !out_fire)
                occ <= occ + 3'd1;
            else if (!in_fire && out_fire)
                occ <= occ - 3'd1;
        end
    end

    // sticky arm: first stall event, never cleared (not even by reset)
    always @(posedge clk) begin
        if (capture)
            armed <= 1'b1;
    end

    // P: once the stage has ever stalled, the tracked occupancy never exceeds
    //    the two physical slots (output register + skid buffer).
    always @(*)
        assert (!armed || (occ <= 3'd2));
endmodule

module surf_clk_div_frame (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire sync_in,
    output wire tick
);
    // Clock divider: 3-bit phase counter runs 0..4, the divided enable pulse
    // fires exactly on the phase wrap.  pcount counts divided pulses inside a
    // frame, total counts enabled cycles inside a frame; the two counters are
    // cross-reset (pcount clears on the total wrap, total clears on the fourth
    // divided pulse), so together they form a 20-cycle frame.

    reg [2:0] phase;
    reg [2:0] pcount;
    reg [4:0] total;
    reg       pre_sync;   // starts high, cleared the first time sync_in is taken

    initial phase    = 3'd0;
    initial pcount   = 3'd0;
    initial total    = 5'd0;
    initial pre_sync = 1'b1;

    assign tick = ce && (phase == 3'd4);

    wire do_sync = ce && sync_in;

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 3'd0;
            pcount   <= 3'd0;
            total    <= 5'd0;
            pre_sync <= 1'b1;
        end else if (do_sync) begin
            phase    <= 3'd0;
            pcount   <= 3'd0;
            total    <= 5'd0;
            pre_sync <= 1'b0;
        end else if (ce) begin
            phase  <= (phase == 3'd4) ? 3'd0 : (phase + 3'd1);
            pcount <= (total == 5'd19) ? 3'd0 :
                      (tick ? (pcount + 3'd1) : pcount);
            total  <= (tick && (pcount == 3'd3)) ? 5'd0 : (total + 5'd1);
        end
    end

    // Bounded existence, before the first external sync:
    // at most four divided pulses and at most twenty enabled cycles per frame.
    always @(posedge clk) begin
        if (pre_sync) assert (pcount <= 3'd3);
        if (pre_sync) assert (total  <= 5'd19);
    end
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
                stable_f <= 1'b0;
            end else if (cnt != K) begin
                cnt      <= cnt + 3'd1;
                stable_f <= (cnt == K - 3'd1);
                if (cnt == K - 3'd1)
                    o_clean <= samp;   // commit the debounced value
            end
            // cnt == K: saturated, hold cnt, stable_f and o_clean

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module call_debounce_lift (
    input  wire       clk,
    input  wire       ce,      // sample / step enable; low = whole design idles
    input  wire       btn,     // raw (bouncy) hall-call button at the top floor
    output reg  [1:0] floor,
    output reg        clean    // debounced call line
);
    localparam integer K          = 4;     // identical consecutive samples needed
    localparam [1:0]   CALL_FLOOR = 2'd3;

    reg [2:0] cnt;      // stability counter: consecutive samples differing from clean
    reg       req;      // latched pending request
    reg       moving;   // cab in motion
    reg       armed;    // starts high, cleared the first time the cab departs
    reg       pv;       // past-valid

    initial begin
        floor  = 2'd0;
        clean  = 1'b0;
        cnt    = 3'd0;
        req    = 1'b0;
        moving = 1'b0;
        armed  = 1'b1;
        pv     = 1'b0;
    end

    wire mismatch = (btn != clean);
    wire flip     = mismatch && (cnt == 3'd3);   // K-1 previous mismatches + this one
    wire go       = req && !moving;
    wire arrive   = moving && (floor == CALL_FLOOR);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            // ---- debouncer: K identical consecutive samples flip the clean output ----
            if (mismatch) begin
                if (cnt == 3'd3) cnt <= 3'd0;
                else             cnt <= cnt + 3'd1;
            end else begin
                cnt <= 3'd0;
            end

            if (flip) clean <= ~clean;

            // rising edge of the debounced line latches a hall call
            if (flip && !clean) req <= 1'b1;

            // ---- cab control: one floor of travel per step ----
            if (go) begin
                moving <= 1'b1;
                req    <= 1'b0;
                armed  <= 1'b0;      // first departure clears the scope register
            end else if (arrive) begin
                moving <= 1'b0;
            end else if (moving) begin
                floor <= floor + 2'd1;
            end
        end
    end

    // P: before the cab has ever departed, the floor register never changes
    always @(posedge clk)
        if (pv && armed)
            assert (floor == $past(floor));
endmodule

module cart_write_elastic (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_req,
    input  wire       i_two,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_valid,
    output wire       o_busy
);
    // two-entry elastic buffer for flash program bytes
    reg       v_head, v_tail;   // head/tail occupancy flags
    reg [7:0] d_head, d_tail;
    reg [1:0] count;            // occupancy counter, mirrors the flags
    reg [2:0] timer;            // completion countdown
    reg       win;              // window register: armed on accept, cleared on drain

    initial v_head = 1'b0;
    initial v_tail = 1'b0;
    initial d_head = 8'h00;
    initial d_tail = 8'h00;
    initial count  = 2'd0;
    initial timer  = 3'd0;
    initial win    = 1'b0;

    always @(posedge clk) begin
        if (i_rst) begin
            v_head <= 1'b0;
            v_tail <= 1'b0;
            d_head <= 8'h00;
            d_tail <= 8'h00;
            count  <= 2'd0;
            timer  <= 3'd0;
            win    <= 1'b0;
        end else if (i_ce) begin
            if (!win) begin
                // accept a new burst request (one or two bytes)
                if (i_req) begin
                    v_head <= 1'b1;
                    d_head <= i_data;
                    v_tail <= i_two;
                    d_tail <= i_data ^ 8'h5a;
                    count  <= i_two ? 2'd2 : 2'd1;
                    timer  <= 3'd3;
                    win    <= 1'b1;
                end
            end else begin
                // draining: one byte committed to the cart per enabled cycle
                timer <= timer - 3'd1;
                if (count == 2'd2) begin
                    d_head <= d_tail;
                    v_tail <= 1'b0;
                    count  <= 2'd1;
                end else begin
                    v_head <= 1'b0;
                    count  <= 2'd0;
                    win    <= 1'b0;
                end
            end
        end
    end

    assign o_data  = d_head;
    assign o_valid = v_head;
    assign o_busy  = win;

    // Bounded response (safety): the countdown never expires while the
    // accepted burst is still outstanding.
    always @(posedge clk)
        if (win)
            assert (timer != 3'd0);
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    input  wire       i_start,
    input  wire       i_finish,
    output reg  [3:0] o_grant,
    output reg        o_fin
);
    // phase encoding: 0 = IDLE, 1 = ARMED (grant issued), 2 = RUNNING, 3 = FINISHED
    localparam [1:0] PH_IDLE = 2'd0,
                     PH_ARM  = 2'd1,
                     PH_RUN  = 2'd2,
                     PH_FIN  = 2'd3;

    reg [1:0] last_grant;   // round-robin pointer
    reg [1:0] phase;
    reg [3:0] req_hold;     // request vector latched at grant time
    reg       r_arm_seen;   // this transaction was armed (granted)
    reg       r_start_seen; // this transaction was started
    reg       armed_q;      // sticky: an arbitration has happened at least once

    initial begin
        last_grant   = 2'd0;
        phase        = PH_IDLE;
        o_grant      = 4'b0000;
        o_fin        = 1'b0;
        req_hold     = 4'b0000;
        r_arm_seen   = 1'b0;
        r_start_seen = 1'b0;
        armed_q      = 1'b0;
    end

    // ---- round robin winner select, starting just after last_grant ----
    wire [1:0] c1 = last_grant + 2'd1;
    wire [1:0] c2 = last_grant + 2'd2;
    wire [1:0] c3 = last_grant + 2'd3;

    reg [1:0] win;
    reg       any;

    always @(*) begin
        any = 1'b1;
        if      (i_req[c1])         win = c1;
        else if (i_req[c2])         win = c2;
        else if (i_req[c3])         win = c3;
        else if (i_req[last_grant]) win = last_grant;
        else begin
            win = last_grant;
            any = 1'b0;
        end
    end

    // ---- arm / start / finish chain ----
    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                PH_IDLE: begin
                    if (any) begin
                        o_grant      <= (4'b0001 << win);
                        last_grant   <= win;
                        req_hold     <= i_req;
                        phase        <= PH_ARM;
                        r_arm_seen   <= 1'b1;
                        armed_q      <= 1'b1;
                    end
                end
                PH_ARM: begin
                    if (i_start) begin
                        phase        <= PH_RUN;
                        r_start_seen <= 1'b1;
                    end
                end
                PH_RUN: begin
                    if (i_finish) begin
                        phase        <= PH_FIN;
                        o_fin        <= 1'b1;
                    end
                end
                PH_FIN: begin
                    phase        <= PH_IDLE;
                    o_grant      <= 4'b0000;
                    o_fin        <= 1'b0;
                    req_hold     <= 4'b0000;
                    r_arm_seen   <= 1'b0;
                    r_start_seen <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence, only required once arbitration has ever occurred:
    // a completion can never be observed unless this transaction was armed
    // and then started.
    always @(posedge clk)
        if (armed_q && o_fin)
            assert (r_start_seen && r_arm_seen);

endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = v1;
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);
endmodule

module serv_inflight_tracker (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,      // idle condition: all state frozen when low
    input  wire       i_issue,   // issue a new operation into the pipeline
    output wire       o_retire,
    output wire [2:0] o_occ
);
    localparam LAT = 4;

    // fixed-latency drain shift register: one bit per pipeline stage
    reg [LAT-1:0] pipe;
    initial pipe = {LAT{1'b0}};

    // in-flight occupancy counter: issue increments, drain decrements
    reg [2:0] occ;
    initial occ = 3'd0;

    // window register (scope): armed by an issue, cleared by a retirement
    reg armed;
    initial armed = 1'b0;

    // shadow register: occupancy recorded at the arming issue
    reg [2:0] sh_occ;
    initial sh_occ = 3'd0;

    wire       drain   = pipe[LAT-1];
    wire [2:0] occ_nxt = occ + {2'b00, i_issue} - {2'b00, drain};

    always @(posedge i_clk) begin
        if (i_reset) begin
            pipe   <= {LAT{1'b0}};
            occ    <= 3'd0;
            armed  <= 1'b0;
            sh_occ <= 3'd0;
        end else if (i_ce) begin
            pipe <= {pipe[LAT-2:0], i_issue};
            occ  <= occ_nxt;
            if (i_issue) begin
                armed  <= 1'b1;
                sh_occ <= occ_nxt;
            end else if (drain) begin
                armed <= 1'b0;
            end
        end
    end

    assign o_retire = i_ce & drain;
    assign o_occ    = occ;

    // Precedence, after issue until retire: a retirement observed inside the
    // armed window must have been preceded by a recorded, still-accounted issue.
    always @(posedge i_clk)
        if (armed && i_ce && drain)
            assert (occ != 3'd0 && sh_occ != 3'd0);
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       o_ready,
    output wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_data
);
    // ---- pipeline stage registers ----
    reg       out_valid  = 1'b0;   // output register stage
    reg [7:0] out_data   = 8'h00;
    reg       skid_valid = 1'b0;   // stall flag
    reg [7:0] skid_data  = 8'h00;  // buffered word, meaningful only while skid_valid
    reg [1:0] occ        = 2'd0;   // independently maintained occupancy counter
    reg       pv         = 1'b0;   // past-valid

    assign i_ready = !skid_valid;
    assign o_valid = out_valid;
    assign o_data  = out_data;

    wire accept = ce && i_valid && !skid_valid;
    wire emit   = ce && out_valid && o_ready;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 2'd0;
        end else if (ce) begin
            if (emit) begin
                if (skid_valid) begin
                    // drain the buffered word into the output register
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
                end else begin
                    out_valid <= accept;
                    if (accept) out_data <= i_data;
                end
            end else begin
                if (accept) begin
                    if (out_valid) begin
                        // downstream stalled: park the word in the skid buffer
                        skid_data  <= i_data;
                        skid_valid <= 1'b1;
                    end else begin
                        out_data  <= i_data;
                        out_valid <= 1'b1;
                    end
                end
            end
            occ <= occ + (accept ? 2'd1 : 2'd0) - (emit ? 2'd1 : 2'd0);
        end
    end

    // P: the moment the stall flag rises, the stage must be completely full
    always @(posedge clk)
        if (pv && $rose(skid_valid))
            assert (occ == 2'd2);
endmodule

module token_bucket_chain (
    input  wire clk,
    input  wire rst,
    input  wire ce,      // global enable: low => all state frozen
    input  wire tick,    // refill timer tick
    input  wire req,     // step 1: arm
    input  wire cancel,  // drop an arm before it starts
    input  wire go,      // step 2: request a grant (needs a token)
    input  wire done,    // step 3: finish
    output wire o_start,
    output wire o_finish,
    output reg  [2:0] tokens
);
    localparam [1:0] S_IDLE = 2'd0, S_ARM = 2'd1, S_RUN = 2'd2;
    localparam [2:0] BURST  = 3'd4;

    reg [1:0] state;
    reg       armed_seen;
    reg       started_seen;

    initial begin
        state        = S_IDLE;
        tokens       = 3'd0;
        armed_seen   = 1'b0;
        started_seen = 1'b0;
    end

    // a grant may only be issued from the armed state and only if the
    // bucket holds at least one token
    wire can_start = (state == S_ARM) && go && !cancel && (tokens != 3'd0);
    wire do_refill = tick && (tokens < BURST);

    assign o_start  = ce && can_start;
    assign o_finish = ce && (state == S_RUN) && done;

    always @(posedge clk) begin
        if (rst) begin
            state        <= S_IDLE;
            tokens       <= 3'd0;
            armed_seen   <= 1'b0;
            started_seen <= 1'b0;
        end else if (ce) begin
            // token bucket: refill on tick up to the burst cap, drain on grant
            case ({do_refill, can_start})
                2'b10:   tokens <= tokens + 3'd1;
                2'b01:   tokens <= tokens - 3'd1;
                default: tokens <= tokens;
            endcase

            // arm -> start -> finish chain
            case (state)
                S_IDLE: begin
                    if (req) begin
                        state        <= S_ARM;
                        armed_seen   <= 1'b1;
                        started_seen <= 1'b0;
                    end
                end
                S_ARM: begin
                    if (cancel) begin
                        state      <= S_IDLE;
                        armed_seen <= 1'b0;
                    end else if (can_start) begin
                        state        <= S_RUN;
                        started_seen <= 1'b1;
                    end
                end
                S_RUN: begin
                    if (done) begin
                        state        <= S_IDLE;
                        armed_seen   <= 1'b0;
                        started_seen <= 1'b0;
                    end
                end
                default: begin
                    state        <= S_IDLE;
                    armed_seen   <= 1'b0;
                    started_seen <= 1'b0;
                end
            endcase
        end
    end

    // chain precedence: a finish can never be observed unless this
    // transaction was armed and then started
    always @(*)
        if (o_finish)
            assert (armed_seen && started_seen);
endmodule

module pingpong_dbuf (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire       push,
    input  wire       pop,
    output wire       wr_full,
    output wire       rd_empty,
    output wire [3:0] occupancy,
    output wire       half_swapped
);
    // ping-pong double buffer: two halves of 4 entries each.
    // wsel selects the half the writer fills, rsel the half the reader drains;
    // they are flipped together so the two agents never touch the same half.
    reg       wsel  = 1'b0;
    reg       rsel  = 1'b1;
    reg [2:0] cnt0  = 3'd0;   // entries resident in half 0
    reg [2:0] cnt1  = 3'd0;   // entries resident in half 1
    reg [3:0] total = 4'd0;   // shadow occupancy accumulator
    reg       armed = 1'b0;   // sticky: set at the first buffer swap, never cleared
    reg       pv    = 1'b0;

    wire [2:0] wcnt = wsel ? cnt1 : cnt0;
    wire [2:0] rcnt = rsel ? cnt1 : cnt0;

    assign wr_full   = (wcnt == 3'd4);
    assign rd_empty  = (rcnt == 3'd0);
    assign occupancy = total;

    wire do_swap = wr_full && rd_empty;
    wire do_push = push && !wr_full && !do_swap;
    wire do_pop  = pop  && !rd_empty && !do_swap;

    assign half_swapped = en && do_swap;

    always @(posedge clk)
        pv <= 1'b1;

    // arm register: latched on the first swap, never cleared afterwards
    always @(posedge clk)
        if (!rst && en && do_swap)
            armed <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            wsel  <= 1'b0;
            rsel  <= 1'b1;
            cnt0  <= 3'd0;
            cnt1  <= 3'd0;
            total <= 4'd0;
        end else if (en) begin
            if (do_swap) begin
                wsel <= ~wsel;
                rsel <= ~rsel;
            end else begin
                if (do_push) begin
                    if (wsel) cnt1 <= cnt1 + 3'd1;
                    else      cnt0 <= cnt0 + 3'd1;
                end
                if (do_pop) begin
                    if (rsel) cnt1 <= cnt1 - 3'd1;
                    else      cnt0 <= cnt0 - 3'd1;
                end
                total <= total + (do_push ? 4'd1 : 4'd0) - (do_pop ? 4'd1 : 4'd0);
            end
        end
    end

    // P: once the buffer has swapped at least once, every rising edge of the
    // writer-full flag must find the accumulated occupancy at or below 8,
    // even though the accumulator is 4 bits wide.
    always @(posedge clk)
        if (pv && armed && $rose(wr_full))
            assert (total <= 4'd8);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
    end

    wire [3:0] nxt      = cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module elastic_buf2 (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       full,
    output wire       empty
);
    // two-entry elastic buffer: one valid flag per slot, head/tail select bits
    reg       v0 = 1'b0;   // slot 0 occupied
    reg       v1 = 1'b0;   // slot 1 occupied
    reg       h  = 1'b0;   // head: slot read next
    reg       t  = 1'b0;   // tail: slot written next
    reg [7:0] m0 = 8'h00;
    reg [7:0] m1 = 8'h00;
    reg [2:0] count = 3'd0; // redundant occupancy counter

    assign full  = v0 & v1;
    assign empty = (~v0) & (~v1);
    assign dout  = h ? m1 : m0;

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            h     <= 1'b0;
            t     <= 1'b0;
            m0    <= 8'h00;
            m1    <= 8'h00;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                if (t == 1'b0) begin
                    v0 <= 1'b1;
                    m0 <= din;
                end else begin
                    v1 <= 1'b1;
                    m1 <= din;
                end
                t <= ~t;
            end
            if (do_pop) begin
                if (h == 1'b0)
                    v0 <= 1'b0;
                else
                    v1 <= 1'b0;
                h <= ~h;
            end
            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase
        end
    end

    // P: the buffer never holds more than two entries, although count is 3 bits wide
    always @(posedge clk)
        assert (count <= 3'd2);
endmodule

// Fixed-latency execution unit with an in-flight occupancy tracker.
// Issued operations march through a 4-deep valid shift register and retire
// from the last stage; the occupancy counter tracks how many are in flight.
module exu_inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       i_issue,   // issue a new operation this cycle
    input  wire [7:0] i_opnd,
    output wire       o_valid,
    output wire [7:0] o_res,
    output wire [2:0] o_inflight
);

    // latency shift register: one valid bit per pipeline stage
    reg [3:0] pipe;
    // payload pipeline riding alongside
    reg [7:0] d0, d1, d2, d3;
    // occupancy counter (3 bits wide: can hold up to 7)
    reg [2:0] inflight;

    initial begin
        pipe     = 4'b0000;
        d0       = 8'h00;
        d1       = 8'h00;
        d2       = 8'h00;
        d3       = 8'h00;
        inflight = 3'd0;
    end

    wire acc    = i_ce && i_issue;   // accepted issue this cycle
    wire retire = i_ce && pipe[3];   // operation leaving the last stage

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            d0       <= 8'h00;
            d1       <= 8'h00;
            d2       <= 8'h00;
            d3       <= 8'h00;
            inflight <= 3'd0;
        end else if (i_ce) begin
            pipe <= {pipe[2:0], i_issue};
            d0   <= i_opnd;
            d1   <= d0 + 8'd1;
            d2   <= d1 ^ 8'h5a;
            d3   <= d2;

            case ({acc, retire})
                2'b10:   inflight <= inflight + 3'd1;
                2'b01:   inflight <= inflight - 3'd1;
                default: inflight <= inflight;
            endcase
        end
    end

    assign o_valid    = pipe[3];
    assign o_res      = d3;
    assign o_inflight = inflight;

    // P: occupancy of a 4-stage fixed-latency unit never exceeds 4,
    //    even though the counter is 3 bits wide.
    always @(*)
        assert (inflight <= 3'd4);

endmodule

module thermo_div_guard (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] temp,
    input  wire       q_arm,
    input  wire       r_done,
    output wire       heat_o,
    output wire       tick_o
);
    localparam [7:0] T_LOW  = 8'd60;
    localparam [7:0] T_HIGH = 8'd80;
    localparam [2:0] DIVM1  = 3'd4;   // divide by 5

    // clock divider: phase counter, divided enable fires on the wrap
    reg [2:0] phase;
    // thermostat state
    reg [7:0] temp_lat;   // temperature sample taken on the divided enable
    reg       heater;     // hysteresis output
    // chatter / inconsistency detectors
    reg       bad_hi;     // heater was on while last sample was above T_HIGH
    reg       bad_lo;     // heater was off while last sample was below T_LOW
    // monitoring window
    reg       win;

    initial phase    = 3'd0;
    initial temp_lat = 8'd70;
    initial heater   = 1'b0;
    initial bad_hi   = 1'b0;
    initial bad_lo   = 1'b0;
    initial win      = 1'b0;

    wire tickw = ce && (phase == DIVM1);

    assign tick_o = tickw;
    assign heat_o = heater;

    always @(posedge clk) if (ce) begin
        phase <= (phase == DIVM1) ? 3'd0 : phase + 3'd1;

        if (tickw) begin
            // sample and apply hysteresis from the same sample
            temp_lat <= temp;
            if (temp < T_LOW)
                heater <= 1'b1;
            else if (temp > T_HIGH)
                heater <= 1'b0;

            // check the previously latched sample against the current output
            if (heater && (temp_lat > T_HIGH))
                bad_hi <= 1'b1;
            if (!heater && (temp_lat < T_LOW))
                bad_lo <= 1'b1;
        end

        // window: opened by q_arm (which also restarts the detectors),
        // closed by r_done; may be opened and closed repeatedly
        if (q_arm) begin
            win    <= 1'b1;
            bad_hi <= 1'b0;
            bad_lo <= 1'b0;
        end else if (r_done)
            win <= 1'b0;
    end

    always @(posedge clk)
        if (win) assert (!bad_hi);

    always @(posedge clk)
        if (win) assert (!bad_lo);
endmodule

module fifo_occ_flags (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_wr,
    input  wire       i_rd,
    input  wire [7:0] i_data,
    output wire [7:0] o_data,
    output wire       o_full,
    output wire       o_empty
);
    // depth-8 FIFO: 4-bit pointers (extra MSB for wrap), separate occupancy count
    reg [3:0] wptr;
    reg [3:0] rptr;
    reg [3:0] count;
    reg [7:0] mem [0:7];
    reg [7:0] dout;

    integer i;
    initial begin
        wptr  = 4'd0;
        rptr  = 4'd0;
        count = 4'd0;
        dout  = 8'd0;
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 8'd0;
    end

    // full is derived from the occupancy counter,
    // empty is derived from the pointers
    assign o_full  = (count == 4'd8);
    assign o_empty = (wptr == rptr);

    wire do_wr = i_wr && !o_full;
    wire do_rd = i_rd && !o_empty;

    assign o_data = dout;

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 4'd0;
            rptr  <= 4'd0;
            count <= 4'd0;
            dout  <= 8'd0;
        end else begin
            if (do_wr) begin
                mem[wptr[2:0]] <= i_data;
                wptr <= wptr + 4'd1;
            end
            if (do_rd) begin
                dout <= mem[rptr[2:0]];
                rptr <= rptr + 4'd1;
            end
            if (do_wr && !do_rd)
                count <= count + 4'd1;
            else if (!do_wr && do_rd)
                count <= count - 4'd1;
        end
    end

    // P: the FIFO is never reported full and empty at the same time
    always @(posedge clk)
        assert (!(o_full && o_empty));
endmodule

module onehot_pipe_gauge (
    input  wire clk,
    input  wire rst,
    input  wire step,
    input  wire start,
    output wire busy,
    output wire [2:0] o_cnt
);
    // one-hot pipeline walker: S0 -> S1 -> S2 -> S3 -> S4 -> S0
    localparam [4:0] S0 = 5'b00001,
                     S1 = 5'b00010,
                     S2 = 5'b00100,
                     S3 = 5'b01000,
                     S4 = 5'b10000;

    reg [4:0] st;
    reg [2:0] cnt;   // stage gauge: how far down the pipe we are
    reg       pv;

    initial st  = S0;
    initial cnt = 3'd0;
    initial pv  = 1'b0;

    // advance / clear terms are only mutually exclusive because st is one-hot
    wire adv = st[1] | st[2] | st[3];
    wire clr = st[0] | st[4];

    reg [4:0] nxt;
    always @(*) begin
        nxt = 5'b00000;
        if (st[0]) nxt = nxt | (start ? S1 : S0);
        if (st[1]) nxt = nxt | S2;
        if (st[2]) nxt = nxt | S3;
        if (st[3]) nxt = nxt | S4;
        if (st[4]) nxt = nxt | S0;
    end

    always @(posedge clk) begin
        if (rst) begin
            st  <= S0;
            cnt <= 3'd0;
        end else if (step) begin
            st <= nxt;
            if (adv)
                cnt <= cnt + 3'd1;
            else if (clr)
                cnt <= 3'd0;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign busy  = |st[4:1];
    assign o_cnt = cnt;

    // P: while the one-hot state does not change, the stage gauge must not
    //    change either, and it never exceeds 3 (its width allows 7).
    always @(posedge clk)
        if (pv && $stable(st))
            assert ($stable(cnt) && cnt <= 3'd3);
endmodule

module hwm_stack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_en,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_item,
    output wire [3:0] o_sp,
    output wire [3:0] o_hwm,
    output wire       o_deep
);
    // Placement stack for footprint records: pointer plus a high-water mark
    // that only ever ratchets upward, and a shadow flag recording that the
    // stack was once at least half full.

    reg [3:0] sp;         // stack pointer, 0..8
    reg [3:0] hwm;        // high-water mark, 0..8
    reg       deep_flag;  // shadow: a deep occupancy event happened earlier
    reg [7:0] mem [0:7];

    integer k;
    initial begin
        sp        = 4'd0;
        hwm       = 4'd0;
        deep_flag = 1'b0;
        for (k = 0; k < 8; k = k + 1) mem[k] = 8'd0;
    end

    wire do_push = i_en && i_push && !i_pop && (sp != 4'd8);
    wire do_pop  = i_en && i_pop  && !i_push && (sp != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            sp        <= 4'd0;
            hwm       <= 4'd0;
            deep_flag <= 1'b0;
        end else if (i_en) begin
            if (do_push) begin
                sp <= sp + 4'd1;
                if ((sp + 4'd1) > hwm)
                    hwm <= sp + 4'd1;
                mem[sp[2:0]] <= i_item;
            end else if (do_pop) begin
                sp <= sp - 4'd1;
            end
            // shadow register: remember that occupancy reached 4 or more
            deep_flag <= deep_flag || (sp >= 4'd4);
        end
    end

    assign o_sp   = sp;
    assign o_hwm  = hwm;
    assign o_deep = deep_flag;

    // Precedence: if the deep-occupancy flag is observed set now, the high
    // water mark must already record a depth of at least 4.
    always @(*)
        assert (!deep_flag || (hwm >= 4'd4));
endmodule

module tmr_cred_gate (
    input wire clk,
    input wire step,
    input wire submit,
    input wire logout,
    input wire [7:0] user,
    input wire [7:0] pass,
    output wire grant_admin,
    output wire grant_guest,
    output wire session_armed
);
    localparam [1:0] ROLE_NONE  = 2'b00;
    localparam [1:0] ROLE_GUEST = 2'b01;
    localparam [1:0] ROLE_ADMIN = 2'b10;

    // three shadow copies of the privilege register (TMR)
    reg [1:0] role_a = ROLE_NONE;
    reg [1:0] role_b = ROLE_NONE;
    reg [1:0] role_c = ROLE_NONE;

    // registered grant lines, driven from the voted privilege code
    reg out_admin = 1'b0;
    reg out_guest = 1'b0;

    // sticky arm: set the first time a credential is ever submitted
    reg armed = 1'b0;

    // bitwise 2-of-3 majority voter
    wire [1:0] vote;
    assign vote[1] = (role_a[1] & role_b[1]) | (role_a[1] & role_c[1]) | (role_b[1] & role_c[1]);
    assign vote[0] = (role_a[0] & role_b[0]) | (role_a[0] & role_c[0]) | (role_b[0] & role_c[0]);

    // scrub path: voted value is written back into all three copies
    wire [1:0] scrub = (vote == 2'b11) ? ROLE_NONE : vote;

    // default-credential table lookup
    wire [1:0] lookup = ((user == 8'hAD) && (pass == 8'h1E)) ? ROLE_ADMIN :
                        ((user == 8'h67) && (pass == 8'h00)) ? ROLE_GUEST :
                                                               ROLE_NONE;

    wire [1:0] role_next = logout ? ROLE_NONE : (submit ? lookup : scrub);

    always @(posedge clk) begin
        if (step) begin
            role_a    <= role_next;
            role_b    <= role_next;
            role_c    <= role_next;
            out_admin <= vote[1];
            out_guest <= vote[0];
            if (submit)
                armed <= 1'b1;
        end
    end

    assign grant_admin   = out_admin;
    assign grant_guest   = out_guest;
    assign session_armed = armed;

    // Absence, after Q: once a credential has been submitted, the admin grant
    // and the guest grant are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(grant_admin && grant_guest));
endmodule

module symbol_histogram (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_dec,        // 0 = tally an incoming symbol, 1 = retire one
    input wire [1:0] i_bin,  // modulation class of the symbol
    input wire i_flush,      // closes the measurement window
    output wire o_empty,
    output wire o_has_data,
    output wire o_armed
);
    // per-modulation symbol tallies
    reg [3:0] bin0, bin1, bin2, bin3;
    // total symbols currently accounted for
    reg [5:0] total;
    // window register: set by the first tally, cleared by a flush
    reg       armed;

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 6'd0;
    initial armed = 1'b0;

    wire [3:0] sel = (i_bin == 2'd0) ? bin0 :
                     (i_bin == 2'd1) ? bin1 :
                     (i_bin == 2'd2) ? bin2 : bin3;

    wire do_flush = i_ce &&  i_flush;
    wire do_inc   = i_ce && !i_flush && !i_dec && (sel != 4'hF);
    wire do_dec   = i_ce && !i_flush &&  i_dec && (sel != 4'h0);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 6'd0;
            armed <= 1'b0;
        end else if (do_flush) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 6'd0;
            armed <= 1'b0;
        end else if (do_inc) begin
            case (i_bin)
                2'd0: bin0 <= bin0 + 4'd1;
                2'd1: bin1 <= bin1 + 4'd1;
                2'd2: bin2 <= bin2 + 4'd1;
                2'd3: bin3 <= bin3 + 4'd1;
            endcase
            total <= total + 6'd1;
            armed <= 1'b1;
        end else if (do_dec) begin
            case (i_bin)
                2'd0: bin0 <= bin0 - 4'd1;
                2'd1: bin1 <= bin1 - 4'd1;
                2'd2: bin2 <= bin2 - 4'd1;
                2'd3: bin3 <= bin3 - 4'd1;
            endcase
            total <= total - 6'd1;
        end
    end

    assign o_empty    = (total == 6'd0);
    assign o_has_data = (bin0 != 4'd0) || (bin1 != 4'd0) ||
                        (bin2 != 4'd0) || (bin3 != 4'd0);
    assign o_armed    = armed;

    // Absence, after arm until flush: the window never reports empty and
    // holding data at the same time.
    assert property (!armed || !(o_empty && o_has_data));
endmodule

// Gray-coded pointer crossing a domain boundary through a two-flop
// synchronizer, with a shadow register holding the previously observed
// synchronized sample.
module gray_ptr_cdc (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       inc,     // advance the write pointer
    output wire [3:0] o_sync_gray,
    output wire [3:0] o_shadow_gray
);
    // producer side
    reg [3:0] bin;
    reg [3:0] gptr;

    // two-flop synchronizer
    reg [3:0] s1;
    reg [3:0] s2;

    // shadow register: the sample observed one enabled cycle earlier
    reg [3:0] prev_s2;

    // binary shadows of the pipeline stages (book-keeping only)
    reg [3:0] bs1, bs2, bs3;

    initial begin
        bin     = 4'b0000;
        gptr    = 4'b0000;
        s1      = 4'b0000;
        s2      = 4'b0000;
        prev_s2 = 4'b0000;
        bs1     = 4'b0000;
        bs2     = 4'b0000;
        bs3     = 4'b0000;
    end

    wire [3:0] bin_next = bin + (inc ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            bin     <= bin_next;
            gptr    <= bin_next ^ (bin_next >> 1);

            s1      <= gptr;
            s2      <= s1;
            prev_s2 <= s2;

            bs1     <= bin;
            bs2     <= bs1;
            bs3     <= bs2;
        end
    end

    assign o_sync_gray   = s2;
    assign o_shadow_gray = prev_s2;

    // difference vectors
    wire [3:0] d_shadow = s2 ^ prev_s2;
    wire [3:0] d_stage  = s1 ^ s2;

    // Precedence: whatever the synchronizer shows now must have been preceded
    // by a value at most one bit away, at both observation points.
    always @(posedge clk) begin
        assert ((d_shadow & (d_shadow - 4'd1)) == 4'd0);
        assert ((d_stage  & (d_stage  - 4'd1)) == 4'd0);
    end
endmodule

module lefdef_parse_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [1:0] tok,
    output reg  [2:0] state,
    output reg        hdr_seen,
    output reg  [3:0] macro_cnt
);
    // binary-encoded parser FSM; encodings 3'd6 and 3'd7 are never entered
    localparam S_IDLE   = 3'd0;  // waiting for a file
    localparam S_HEADER = 3'd1;  // VERSION / UNITS block
    localparam S_MACRO  = 3'd2;  // MACRO record
    localparam S_PINS   = 3'd3;  // PIN records of current macro
    localparam S_LAYER  = 3'd4;  // LAYER / PORT geometry
    localparam S_END    = 3'd5;  // END LIBRARY

    initial state     = S_IDLE;
    initial hdr_seen  = 1'b0;    // shadow register: header block was parsed
    initial macro_cnt = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            state     <= S_IDLE;
            hdr_seen  <= 1'b0;
            macro_cnt <= 4'd0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (tok == 2'd1)
                        state <= S_HEADER;
                end
                S_HEADER: begin
                    if (tok == 2'd2) begin
                        hdr_seen <= 1'b1;   // header fully consumed
                        state    <= S_MACRO;
                    end
                end
                S_MACRO: begin
                    if (tok == 2'd3)
                        state <= S_PINS;
                    else if (tok == 2'd0)
                        state <= S_END;
                end
                S_PINS: begin
                    if (tok == 2'd3)
                        state <= S_LAYER;
                end
                S_LAYER: begin
                    if (tok == 2'd0) begin
                        state     <= S_MACRO;
                        macro_cnt <= macro_cnt + 4'd1;
                    end
                end
                S_END: begin
                    if (tok == 2'd1)
                        state <= S_IDLE;
                end
                default: begin
                    // illegal encoding recovery path (never taken in practice)
                    state <= S_PINS;
                end
            endcase
        end
    end

    // Precedence: pin records can only be seen after the header was parsed.
    always @(posedge clk)
        if (state == S_PINS)
            assert (hdr_seen);
endmodule

module prio_skid (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_valid,
    input  wire [7:0] i_req,
    input  wire       o_ready,   // downstream ready
    output wire       i_ready,
    output wire       o_valid,
    output wire [2:0] o_idx,
    output wire       o_hit
);
    // ---------------- combinational priority encoder ----------------
    wire       enc_hit = |i_req;
    wire [2:0] enc_idx = i_req[7] ? 3'd7 :
                         i_req[6] ? 3'd6 :
                         i_req[5] ? 3'd5 :
                         i_req[4] ? 3'd4 :
                         i_req[3] ? 3'd3 :
                         i_req[2] ? 3'd2 :
                         i_req[1] ? 3'd1 : 3'd0;

    // ---------------- registered output stage ----------------
    reg       out_vld;
    reg [2:0] out_idx;
    reg       out_hit;
    reg [7:0] out_req;

    // ---------------- skid buffer (only meaningful while sk_full) ----
    reg       sk_full;
    reg [7:0] sk_req;
    reg [2:0] sk_idx;
    reg       sk_hit;

    // ---------------- stall history and sticky arm ----------------
    reg       stalled;   // registered copy of the stall condition
    reg       armed;     // sticky: set the first time an input word is offered

    initial begin
        out_vld = 1'b0; out_idx = 3'd0; out_hit = 1'b0; out_req = 8'h00;
        sk_full = 1'b0; sk_req  = 8'h00; sk_idx  = 3'd0; sk_hit  = 1'b0;
        stalled = 1'b0; armed   = 1'b0;
    end

    wire stall = out_vld && !o_ready;

    assign i_ready = !sk_full;
    assign o_valid = out_vld;
    assign o_idx   = out_idx;
    assign o_hit   = out_hit;

    always @(posedge clk) begin
        if (i_ce) begin
            armed   <= armed | i_valid;
            stalled <= stall;

            if (!stall) begin
                if (sk_full) begin
                    out_vld <= 1'b1;
                    out_idx <= sk_idx;
                    out_hit <= sk_hit;
                    out_req <= sk_req;
                    sk_full <= 1'b0;
                end else begin
                    out_vld <= i_valid;
                    out_idx <= enc_idx;
                    out_hit <= enc_hit;
                    out_req <= i_req;
                end
            end else begin
                // output stage blocked: park the incoming word in the skid
                if (i_valid && !sk_full) begin
                    sk_full <= 1'b1;
                    sk_req  <= i_req;
                    sk_idx  <= enc_idx;
                    sk_hit  <= enc_hit;
                end
            end
        end
    end

    // ---------------- property ----------------
    // Once an input word has ever been offered (armed), whenever the stage has
    // recorded a stall the buffered encoding must point at a set request bit.
    always @(posedge clk)
        if (armed && stalled)
            assert (!sk_hit || sk_req[sk_idx]);

endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

    // ---- redundant occupancy counter kept in parallel with the valid bits ----
    reg [1:0]  occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire do_push   = i_ce && i_valid && !hold;
    wire do_pop    = i_ce && m_valid && i_ready;
    wire load_skid = i_ce && i_valid && !hold && m_valid && !i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
                if (i_valid && !hold) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

    // ---- parallel occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
            if (do_push && !do_pop)
                occ <= occ + 2'd1;
            else if (do_pop && !do_push)
                occ <= occ - 2'd1;
        end
    end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
            g_fast <= i_valid && (occ == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
    assign o_upstream_ready = !hold;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
    output reg        armed    // sticky: set the first time a request is taken
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit

    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // accept a new request: index and one-hot come from the encoder
                vld   <= 1'b1;
                idx   <= enc;
                oh    <= iso;
                armed <= 1'b1;
            end else if (vld) begin
                // no new request: age the standing grant round-robin style
                idx <= idx + 2'd1;
                oh  <= {oh[2:0], oh[3]};
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

// saturating event counter with full/empty status flags
module sat_counter_flags (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    output wire o_full,
    output wire o_empty
);
    parameter [3:0] MAX = 4'd10;

    reg [3:0] cnt;
    reg       at_max;   // "full"  status flag
    reg       at_min;   // "empty" status flag
    reg       pv;       // past-valid

    initial cnt    = 4'd0;
    initial at_max = 1'b0;
    initial at_min = 1'b1;
    initial pv     = 1'b0;

    // saturating next value: clamps at MAX, well below 4'd15
    wire [3:0] nxt = (cnt >= MAX) ? MAX : (cnt + 4'd1);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_rst) begin
            cnt    <= 4'd0;
            at_max <= 1'b0;
            at_min <= 1'b1;
        end else if (i_ce) begin
            cnt    <= nxt;
            at_max <= (nxt == MAX);
            at_min <= (nxt == 4'd0);
        end
    end

    assign o_full  = at_max;
    assign o_empty = at_min;

    // P: the counter holding still and a status flag moving are never
    //    true at the same time
    always @(posedge clk)
        if (pv && $stable(cnt))
            assert ($stable(at_max) && $stable(at_min));

endmodule

module clock_pend_track (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,     // the running side's clock tick
    input  wire i_start,  // Q: press starts the side's clock (opens window)
    input  wire i_stop,   // R: flag falls / press stops it (closes window)
    input  wire i_req,    // a new move-timing request enters the pipeline
    output wire o_done
);
    // in-flight request pipeline plus a separate count of its set bits
    reg [7:0] pend;
    reg [3:0] cnt;
    reg       armed;   // window register: set by i_start, cleared by i_stop

    initial pend  = 8'h00;
    initial cnt   = 4'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (i_rst) begin
            pend  <= 8'h00;
            cnt   <= 4'd0;
            armed <= 1'b0;
        end else begin
            if (i_start)
                armed <= 1'b1;
            else if (i_stop)
                armed <= 1'b0;

            // state only advances while the side's clock is actually running
            if (armed && i_ce) begin
                pend <= { pend[6:0], i_req };
                cnt  <= cnt + { 3'b000, i_req } - { 3'b000, pend[7] };
            end
        end
    end

    assign o_done = armed && i_ce && pend[7];

    // P (two assertions, both inside the open window)
    always @(posedge clk)
        if (armed)
            assert (cnt != 4'd0 || pend == 8'h00);

    always @(posedge clk)
        if (armed)
            assert (cnt != 4'd8 || pend == 8'hFF);
endmodule

module boot_prio_sched (
    input  wire       clk,
    input  wire       i_ce,      // scheduler tick enable; low => full idle
    input  wire       i_flush,   // end of the boot round
    input  wire [7:0] i_req,     // dynamic requests, admitted only after flush
    output wire       o_valid,
    output wire [2:0] o_index,
    output wire [2:0] o_count
);

    // ---------------- state ----------------
    reg [7:0] pending;      // outstanding boot/thread requests
    reg [2:0] o_index_r;    // encoded index, meaningful only while valid
    reg       o_valid_r;    // registered valid flag
    reg [2:0] grant_count;  // retired grants (saturating)
    reg       pre_flush;    // arming register: high until first flush tick

    initial pending     = 8'h0F;   // four statically pinned boot threads
    initial o_index_r   = 3'd0;
    initial o_valid_r   = 1'b0;
    initial grant_count = 3'd0;
    initial pre_flush   = 1'b1;

    // ------------- priority encoder (combinational) -------------
    wire       req_any = |pending;
    reg  [2:0] enc;
    always @(*) begin
        if      (pending[0]) enc = 3'd0;
        else if (pending[1]) enc = 3'd1;
        else if (pending[2]) enc = 3'd2;
        else if (pending[3]) enc = 3'd3;
        else if (pending[4]) enc = 3'd4;
        else if (pending[5]) enc = 3'd5;
        else if (pending[6]) enc = 3'd6;
        else                 enc = 3'd7;
    end

    wire [7:0] gmask = req_any ? (8'h01 << enc) : 8'h00;
    wire [7:0] admit = (!pre_flush) ? i_req : 8'h00;

    // ------------- sequential core -------------
    always @(posedge clk) begin
        if (i_ce) begin
            if (i_flush) begin
                // open the scheduler up: all slots become requestable
                pending   <= 8'hFF;
                o_valid_r <= 1'b0;
                pre_flush <= 1'b0;
            end else begin
                pending   <= (pending & ~gmask) | admit;
                o_valid_r <= req_any;
                if (req_any)
                    o_index_r <= enc;
                if (o_valid_r)
                    grant_count <= (grant_count == 3'd7) ? 3'd7
                                                         : grant_count + 3'd1;
            end
        end
    end

    assign o_valid = o_valid_r;
    assign o_index = o_index_r;
    assign o_count = grant_count;

    // ------------- property -------------
    // Before the scheduler has ever been flushed, and while a grant is
    // actually presented, at most three grants can already have retired.
    always @(posedge clk)
        if (pre_flush && o_valid_r)
            assert (grant_count <= 3'd3);

endmodule

module parity_reg_slice (
    input  wire       clk,
    input  wire       rst,
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output wire       out_valid,
    output wire [7:0] out_data
);
    // ---- register slice protected by a parity bit ----
    reg [7:0] buf_data;
    reg       buf_par;
    reg       buf_valid;

    // sticky arm: set the first time a beat is ever accepted
    reg       armed;
    // sticky error: set if a departing word's stored parity disagrees
    reg       err_sticky;

    initial begin
        buf_data   = 8'h00;
        buf_par    = 1'b0;
        buf_valid  = 1'b0;
        armed      = 1'b0;
        err_sticky = 1'b0;
    end

    assign in_ready  = !buf_valid || out_ready;
    assign out_valid = buf_valid;
    assign out_data  = buf_data;

    wire accept = in_valid  && in_ready;
    wire pop    = buf_valid && out_ready;

    // parity check on the word that is leaving the slice
    wire par_bad = pop && (buf_par != (^buf_data));

    always @(posedge clk) begin
        if (rst) begin
            buf_data   <= 8'h00;
            buf_par    <= 1'b0;
            buf_valid  <= 1'b0;
            armed      <= 1'b0;
            err_sticky <= 1'b0;
        end else begin
            if (par_bad)
                err_sticky <= 1'b1;

            if (accept) begin
                buf_data  <= in_data;
                buf_par   <= ^in_data;   // parity written with the data
                buf_valid <= 1'b1;
                armed     <= 1'b1;       // sticky, never cleared
            end else if (pop) begin
                buf_valid <= 1'b0;
            end
        end
    end

    // Property: once the slice has ever accepted a beat, no parity fault has
    // ever been observed on a departing word.
    always @(*)
        if (armed)
            assert (err_sticky == 1'b0);
endmodule

module sorted_insert_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // enable: low freezes all sequencer state
    input  wire       i_arm,     // step 1: insertion request armed
    input  wire       i_scan,    // step 2: ordered scan started
    input  wire       i_commit,  // step 3: element spliced into the sorted list
    input  wire       i_abort,
    input  wire       i_open,    // Q: opens the observation window
    input  wire       i_close,   // R: closes it (may never arrive)
    output reg  [2:0] st,
    output reg  [2:0] size
);
    // binary-encoded FSM; encodings 1,3,4,7 are never entered
    localparam [2:0] S_IDLE   = 3'd0;
    localparam [2:0] S_ARMED  = 3'd2;
    localparam [2:0] S_SCAN   = 3'd5;
    localparam [2:0] S_COMMIT = 3'd6;

    reg did_arm;
    reg did_scan;
    reg win;

    initial begin
        st       = S_IDLE;
        size     = 3'd0;
        did_arm  = 1'b0;
        did_scan = 1'b0;
        win      = 1'b0;
    end

    // latched observation window: set by Q, cleared by R
    always @(posedge clk) begin
        if (rst)           win <= 1'b0;
        else if (i_close)  win <= 1'b0;
        else if (i_open)   win <= 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            st       <= S_IDLE;
            did_arm  <= 1'b0;
            did_scan <= 1'b0;
            size     <= 3'd0;
        end else if (i_ce) begin
            case (st)
                S_IDLE: begin
                    if (i_arm) begin
                        st      <= S_ARMED;
                        did_arm <= 1'b1;
                    end
                end
                S_ARMED: begin
                    if (i_abort) begin
                        st       <= S_IDLE;
                        did_arm  <= 1'b0;
                        did_scan <= 1'b0;
                    end else if (i_scan) begin
                        st       <= S_SCAN;
                        did_scan <= 1'b1;
                    end
                end
                S_SCAN: begin
                    if (i_abort) begin
                        st       <= S_IDLE;
                        did_arm  <= 1'b0;
                        did_scan <= 1'b0;
                    end else if (i_commit) begin
                        st <= S_COMMIT;
                    end
                end
                S_COMMIT: begin
                    st       <= S_IDLE;
                    did_arm  <= 1'b0;
                    did_scan <= 1'b0;
                    if (size != 3'd4) size <= size + 1'b1;
                end
                default: begin
                    st       <= S_IDLE;
                    did_arm  <= 1'b0;
                    did_scan <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence, after window-open until window-close:
    // a commit is never observed unless arm and scan already happened.
    always @(posedge clk)
        if (win && st == S_COMMIT)
            assert (did_arm && did_scan);
endmodule

// Instruction-fetch queue occupancy tracker with gray-coded pointers.
// Pointers are 4 bits (3 address bits + 1 wrap bit) over an 8-entry buffer.
// Each binary pointer carries a gray shadow used for the full/empty compare.
module ifq_gray_occupancy (
    input  wire        clk,
    input  wire        rst,
    input  wire        push,
    input  wire        pop,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        full,
    output wire        empty
);
    // binary pointers
    reg [3:0] wbin    = 4'd0;
    reg [3:0] rbin    = 4'd0;
    // gray shadows of the binary pointers
    reg [3:0] wgray   = 4'd0;
    reg [3:0] rgray   = 4'd0;
    // occupancy and high-water mark
    reg [3:0] occ     = 4'd0;
    reg [3:0] hiwater = 4'd0;

    reg [31:0] mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) mem[i] = 32'd0;
    end

    wire [3:0] wbin_nxt  = wbin + 4'd1;
    wire [3:0] rbin_nxt  = rbin + 4'd1;
    wire [3:0] wgray_nxt = wbin_nxt ^ (wbin_nxt >> 1);
    wire [3:0] rgray_nxt = rbin_nxt ^ (rbin_nxt >> 1);

    // classic gray-pointer full / empty decode
    assign full  = (wgray == {~rgray[3:2], rgray[1:0]});
    assign empty = (wgray == rgray);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    wire [3:0] occ_nxt = occ + (do_push ? 4'd1 : 4'd0) - (do_pop ? 4'd1 : 4'd0);

    assign dout = mem[rbin[2:0]];

    always @(posedge clk) begin
        if (rst) begin
            wbin    <= 4'd0;
            rbin    <= 4'd0;
            wgray   <= 4'd0;
            rgray   <= 4'd0;
            occ     <= 4'd0;
            hiwater <= 4'd0;
        end else begin
            if (do_push) begin
                wbin           <= wbin_nxt;
                wgray          <= wgray_nxt;
                mem[wbin[2:0]] <= din;
            end
            if (do_pop) begin
                rbin  <= rbin_nxt;
                rgray <= rgray_nxt;
            end
            occ <= occ_nxt;
            if (occ_nxt > hiwater)
                hiwater <= occ_nxt;
        end
    end

    // P (two parts): the queue never holds more than the 8 entries it has,
    // and the recorded peak occupancy never exceeds 8 either, even though the
    // 4-bit registers could represent up to 15.
    always @(posedge clk) assert (occ <= 4'd8);
    always @(posedge clk) assert (hiwater <= 4'd8);
endmodule

module fourphase_arb (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    input  wire start_a,
    input  wire start_b,
    input  wire clr_mon,
    output wire o_busy,
    output wire o_mon
);
    // Two four-phase req/ack channels sharing one resource.
    // Per channel the phase walks:
    //   idle : busy=0 req=0 ack=0   -- grant -> busy=1
    //   P1   : busy=1 req=0 ack=0   -- raise req
    //   P2   : busy=1 req=1 ack=0   -- raise ack
    //   P3   : busy=1 req=1 ack=1   -- drop req (req may not drop before ack)
    //   P4   : busy=1 req=0 ack=1   -- drop ack, release busy
    reg req_a, ack_a, busy_a;
    reg req_b, ack_b, busy_b;

    // window register: armed by the first completed handshake (Q),
    // closed only by clr_mon while the resource is free (R, may never arrive)
    reg mon;

    initial begin
        req_a  = 1'b0;
        ack_a  = 1'b0;
        busy_a = 1'b0;
        req_b  = 1'b0;
        ack_b  = 1'b0;
        busy_b = 1'b0;
        mon    = 1'b0;
    end

    // arbiter: a channel may only be granted when neither channel is busy,
    // channel A has priority
    wire grant_a = start_a && !busy_a && !busy_b;
    wire grant_b = start_b && !busy_b && !busy_a && !start_a;

    // a channel is finishing this cycle (ack about to fall, busy released)
    wire fin_a = busy_a && !req_a && ack_a;
    wire fin_b = busy_b && !req_b && ack_b;

    always @(posedge clk) begin
        if (rst) begin
            req_a  <= 1'b0;
            ack_a  <= 1'b0;
            busy_a <= 1'b0;
            req_b  <= 1'b0;
            ack_b  <= 1'b0;
            busy_b <= 1'b0;
            mon    <= 1'b0;
        end else if (ce) begin
            // ---- channel A phase walk ----
            if (!busy_a && !req_a && !ack_a) begin
                if (grant_a)
                    busy_a <= 1'b1;
            end else if (busy_a && !req_a && !ack_a) begin
                req_a <= 1'b1;
            end else if (busy_a && req_a && !ack_a) begin
                ack_a <= 1'b1;
            end else if (busy_a && req_a && ack_a) begin
                req_a <= 1'b0;
            end else if (busy_a && !req_a && ack_a) begin
                ack_a  <= 1'b0;
                busy_a <= 1'b0;
            end

            // ---- channel B phase walk ----
            if (!busy_b && !req_b && !ack_b) begin
                if (grant_b)
                    busy_b <= 1'b1;
            end else if (busy_b && !req_b && !ack_b) begin
                req_b <= 1'b1;
            end else if (busy_b && req_b && !ack_b) begin
                ack_b <= 1'b1;
            end else if (busy_b && req_b && ack_b) begin
                req_b <= 1'b0;
            end else if (busy_b && !req_b && ack_b) begin
                ack_b  <= 1'b0;
                busy_b <= 1'b0;
            end

            // ---- monitoring window ----
            if (fin_a || fin_b)
                mon <= 1'b1;
            else if (clr_mon && !busy_a && !busy_b)
                mon <= 1'b0;
        end
    end

    assign o_busy = busy_a || busy_b;
    assign o_mon  = mon;

    // P: once the monitoring window has opened, the two channels never both
    // drive a request, and never both drive an acknowledge.
    always @(posedge clk)
        if (mon)
            assert (!(req_a && req_b));

    always @(posedge clk)
        if (mon)
            assert (!(ack_a && ack_b));
endmodule

module stack_scoreboard (
    input  wire       clk,
    input  wire       issue,      // a transaction is pushed onto the shadow stack
    input  wire       retire,     // a transaction is popped / completed
    output wire [2:0] outstanding_o,
    output wire       pre_deep_o
);
    // window depth of the in-flight scoreboard
    localparam [2:0] WINDOW = 3'd4;

    // free-running census of issued and retired transactions (wrap mod 16)
    reg [3:0] issued_cnt  = 4'd0;
    reg [3:0] retired_cnt = 4'd0;

    // in-flight occupancy of the window
    reg [2:0] outstanding = 3'd0;

    // "before R" arming register: starts high, cleared the first time the
    // scoreboard occupancy ever reaches 3 (the deep-stack event)
    reg       pre_deep    = 1'b1;

    // past-valid
    reg       pv          = 1'b0;

    wire do_issue  = issue  && (outstanding != WINDOW);
    wire do_retire = retire && (outstanding != 3'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue)  issued_cnt  <= issued_cnt  + 4'd1;
        if (do_retire) retired_cnt <= retired_cnt + 4'd1;

        case ({do_issue, do_retire})
            2'b10:   outstanding <= outstanding + 3'd1;
            2'b01:   outstanding <= outstanding - 3'd1;
            default: outstanding <= outstanding;
        endcase

        if (outstanding >= 3'd3)
            pre_deep <= 1'b0;
    end

    assign outstanding_o = outstanding;
    assign pre_deep_o    = pre_deep;

    // Universality, in the scope "before the stack ever got deep":
    // while pre_deep is still set, the number issued so far can lead the
    // retire census of the PREVIOUS cycle by at most 3.
    always @(posedge clk)
        if (pv && pre_deep)
            assert (issued_cnt - $past(retired_cnt) <= 4'd3);
endmodule

module wdt_supervisor (
    input  wire       clk,
    input  wire       i_ce,      // idle condition: low freezes all state
    input  wire       kick,      // service the watchdog
    output reg        expired,   // one-cycle timeout notification
    output reg        hard_rst,  // forced reset after the strike budget is used
    output reg [2:0]  strikes    // accumulated un-serviced timeouts
);
    localparam [3:0] LIMIT = 4'd4;

    reg [3:0] cnt;
    reg       pv;

    initial begin
        cnt      = 4'd0;
        strikes  = 3'd0;
        expired  = 1'b0;
        hard_rst = 1'b0;
        pv       = 1'b0;
    end

    wire timeout = (cnt == LIMIT);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            expired  <= 1'b0;
            hard_rst <= 1'b0;
            if (kick) begin
                cnt <= 4'd0;
            end else if (timeout) begin
                cnt     <= 4'd0;
                expired <= 1'b1;
                if (strikes == 3'd2) begin
                    strikes  <= 3'd0;
                    hard_rst <= 1'b1;
                end else begin
                    strikes <= strikes + 3'd1;
                end
            end else begin
                cnt <= cnt + 4'd1;
            end
        end
    end

    // P: whenever the timeout notification rises, the strike budget of 2 has
    //    never been exceeded (3-bit register could hold up to 7).
    always @(posedge clk)
        if (pv && $rose(expired))
            assert (strikes <= 3'd2);
endmodule

module axi_burst_hist (
    input  wire       clk,
    input  wire       rst,
    input  wire       start,        // request from the AXI side
    input  wire       sample_valid, // enable: one sample per cycle
    input  wire [1:0] sel,          // which bin this sample lands in
    output wire       done
);
    // Each accepted request collects BURST samples into a 4-bin histogram.
    // The bins are incremented one at a time and always sum to `total`.
    localparam integer BURST    = 4;
    localparam [2:0]   DEADLINE = 3'd6;

    reg [3:0] bin0, bin1, bin2, bin3;
    reg [3:0] total;   // total samples collected in this burst
    reg [2:0] timer;   // bounded-response countdown
    reg       busy;    // window register: set by accept, cleared by done

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;
    initial timer = 3'd0;
    initial busy  = 1'b0;

    wire [7:0] sum = bin0 + bin1 + bin2 + bin3;

    // burst finishes when the histogram has absorbed the last sample
    assign done = busy && sample_valid && (sum == BURST - 1);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
            timer <= 3'd0;
            busy  <= 1'b0;
        end else if (!busy) begin
            if (start) begin          // Q: request accepted, window opens
                bin0  <= 4'd0;
                bin1  <= 4'd0;
                bin2  <= 4'd0;
                bin3  <= 4'd0;
                total <= 4'd0;
                timer <= DEADLINE;
                busy  <= 1'b1;
            end
        end else if (sample_valid) begin
            case (sel)
                2'd0: bin0 <= bin0 + 4'd1;
                2'd1: bin1 <= bin1 + 4'd1;
                2'd2: bin2 <= bin2 + 4'd1;
                2'd3: bin3 <= bin3 + 4'd1;
            endcase
            total <= total + 4'd1;
            timer <= timer - 3'd1;
            if (sum == BURST - 1)     // R: last sample, window closes
                busy <= 1'b0;
        end
    end

    // Bounded response (safety): inside the open window the countdown
    // must never reach zero, i.e. the burst always completes in time.
    always @(posedge clk)
        if (busy)
            assert (timer != 3'd0);
endmodule

module rot_seq_window (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire [1:0]  sym,
    input  wire [15:0] din,
    input  wire        load,
    input  wire        win_start,
    input  wire        win_stop,
    output reg  [15:0] word,
    output reg         hit
);
    // ---- sequence detector for pattern sym = 1, 2, 3 ----------------
    reg [2:0] prog;    // match progress, 0..3 (3 = full match)
    reg [3:0] onehot;  // one-hot shadow of prog, maintained structurally
    reg       armed;   // window register: opened by win_start, closed by win_stop
    reg       pv;      // past-valid

    initial begin
        prog   = 3'd0;
        onehot = 4'b0001;
        armed  = 1'b0;
        pv     = 1'b0;
        word   = 16'h0000;
        hit    = 1'b0;
    end

    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = (sym == 2'd1) ? 3'd1 : 3'd0;
            3'd1:    nprog = (sym == 2'd2) ? 3'd2 : ((sym == 2'd1) ? 3'd1 : 3'd0);
            3'd2:    nprog = (sym == 2'd3) ? 3'd3 : ((sym == 2'd1) ? 3'd1 : 3'd0);
            default: nprog = (sym == 2'd1) ? 3'd1 : 3'd0;
        endcase
    end

    wire adv = (nprog == prog + 3'd1);

    // ---- barrel rotate: amount = 4*prog, stage selects taken from onehot ----
    wire [15:0] r4 = (onehot[1] | onehot[3]) ? {word[11:0], word[15:12]} : word;
    wire [15:0] r8 = (onehot[2] | onehot[3]) ? {r4[7:0],   r4[15:8]}     : r4;

    always @(posedge clk) begin
        if (rst) begin
            prog   <= 3'd0;
            onehot <= 4'b0001;
            armed  <= 1'b0;
            word   <= 16'h0000;
            hit    <= 1'b0;
        end else if (ce) begin
            prog <= nprog;
            if (adv)                onehot <= {onehot[2:0], 1'b0};
            else if (nprog == 3'd1) onehot <= 4'b0010;
            else                    onehot <= 4'b0001;

            word <= load ? din : r8;
            hit  <= (nprog == 3'd3);

            if (win_stop)       armed <= 1'b0;
            else if (win_start) armed <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    // ---- property: inside the window, the previous one-hot shadow was live ----
    always @(posedge clk)
        if (pv && armed)
            assert ($past(onehot) != 4'd0);
endmodule

// Transaction scoreboard: arm (credit allocated) -> start (issue) -> finish (retire).
// Retired never exceeds issued, issued never exceeds armed, and each gap is
// bounded by the window WIN.
module txn_scoreboard (
    input  wire       clk,
    input  wire       ce,        // idle when low: no state changes at all
    input  wire       arm_req,
    input  wire       start_req,
    input  wire       fin_req,
    output reg  [3:0] alloc_cnt,
    output reg  [3:0] iss_cnt,
    output reg  [3:0] ret_cnt
);
    localparam [2:0] WIN = 3'd4;

    // credit registers: armed-but-not-started, started-but-not-finished
    reg [2:0] pend_iss;
    reg [2:0] outstanding;

    reg pv;

    initial begin
        alloc_cnt   = 4'd0;
        iss_cnt     = 4'd0;
        ret_cnt     = 4'd0;
        pend_iss    = 3'd0;
        outstanding = 3'd0;
        pv          = 1'b0;
    end

    // the chain is enforced purely through the credit registers
    wire do_arm   = ce && arm_req   && (pend_iss    <  WIN);
    wire do_start = ce && start_req && (pend_iss    != 3'd0) && (outstanding < WIN);
    wire do_fin   = ce && fin_req   && (outstanding != 3'd0);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_arm)   alloc_cnt <= alloc_cnt + 4'd1;
        if (do_start) iss_cnt   <= iss_cnt   + 4'd1;
        if (do_fin)   ret_cnt   <= ret_cnt   + 4'd1;

        case ({do_arm, do_start})
            2'b10:   pend_iss <= pend_iss + 3'd1;
            2'b01:   pend_iss <= pend_iss - 3'd1;
            default: pend_iss <= pend_iss;
        endcase

        case ({do_start, do_fin})
            2'b10:   outstanding <= outstanding + 3'd1;
            2'b01:   outstanding <= outstanding - 3'd1;
            default: outstanding <= outstanding;
        endcase
    end

    // P (chain precedence, no-change form): a start cannot be observed unless an
    // arm got ahead of the issue counter, and a finish cannot be observed unless
    // a start got ahead of the retire counter.
    always @(posedge clk)
        if (pv)
            assert (((($past(alloc_cnt) != $past(iss_cnt))) || $stable(iss_cnt)) &&
                    ((($past(iss_cnt)   != $past(ret_cnt))) || $stable(ret_cnt)));
endmodule

module lfsr_lockup_watch (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire       o_bit,
    output wire       o_strobe,
    output wire [3:0] o_dead
);
    // Fibonacci LFSR, x^8 + x^6 + x^5 + x^4 + 1 (maximal length, 255 states).
    // Seeded nonzero, so the all-zeros lockup state is never entered.
    reg [7:0] lfsr;
    // Watchdog: counts consecutive enabled cycles spent in the lockup word.
    reg [3:0] zcnt;
    // Pipelined "low tap field is empty" strobe.
    reg       strobe;
    reg       pv;

    initial lfsr   = 8'h01;
    initial zcnt   = 4'd0;
    initial strobe = 1'b0;
    initial pv     = 1'b0;

    wire fb   = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
    wire dead = (lfsr == 8'h00);

    always @(posedge i_clk) begin
        if (i_rst) begin
            lfsr   <= 8'h01;
            zcnt   <= 4'd0;
            strobe <= 1'b0;
        end else if (i_ce) begin
            lfsr   <= { lfsr[6:0], fb };
            zcnt   <= dead ? ((zcnt == 4'hf) ? 4'hf : (zcnt + 4'd1)) : 4'd0;
            strobe <= (lfsr[2:0] == 3'b000);
        end
    end

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_bit    = lfsr[7];
    assign o_strobe = strobe;
    assign o_dead   = zcnt;

    // P: whenever the strobe rises, the lockup watchdog must read zero.
    always @(posedge i_clk)
        if (pv && $rose(strobe))
            assert (zcnt == 4'd0);
endmodule

module lfsr_session_monitor (
    input  wire       clk,
    input  wire       ce,      // entropy-draw enable; low => all state frozen
    input  wire       start,   // Q: opens the sampling session window
    input  wire       stop,    // R: closes the sampling session window
    output reg  [7:0] lfsr,
    output reg        window,
    output reg        nz_seen,
    output reg  [2:0] count,
    output wire       done
);
    // ------------------------------------------------------------------
    // Maximal-length Fibonacci LFSR, x^8 + x^6 + x^5 + x^4 + 1.
    // Seeded nonzero, so the all-zeros lockup state is never entered.
    // ------------------------------------------------------------------
    initial lfsr    = 8'h01;
    initial window  = 1'b0;
    initial nz_seen = 1'b0;
    initial count   = 3'd0;

    wire fb = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];

    // a session is "done" once four draws have been consumed inside it
    assign done = window && (count == 3'd4);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (ce)
            lfsr <= {lfsr[6:0], fb};

    // window register: set by start, cleared by stop, may open/close repeatedly.
    // count counts draws inside the current window (saturates at 4).
    // nz_seen is the shadow register: records that a nonzero draw occurred.
    always @(posedge clk) begin
        if (start && !window) begin
            window  <= 1'b1;
            count   <= 3'd0;
            nz_seen <= 1'b0;
        end
        else if (stop && window) begin
            window  <= 1'b0;
        end
        else if (ce && window && (count != 3'd4)) begin
            count   <= count + 3'd1;
            nz_seen <= nz_seen | (lfsr != 8'h00);
        end
    end

    // Property: inside an open session, at the moment done rises, a nonzero
    // draw must already have been recorded earlier in that same session.
    always @(posedge clk)
        if (pv && window)
            assert (!$rose(done) || nz_seen);
endmodule

module wifi_inflight_chain (
    input  wire clk,
    input  wire step,      // global enable / idle when low
    input  wire push,      // a new TX request enters the pipeline
    input  wire arm_cmd,   // CCA clear: arm the chain
    input  wire q_open,    // Q: opens the observation window
    input  wire r_close,   // R: closes the observation window
    output wire busy,
    output wire tx_done
);
    // shift register of in-flight requests + separate count of set bits
    reg [3:0] inflight   = 4'd0;
    reg [2:0] cnt        = 3'd0;

    // window register (Q opens, R closes), may be opened/closed repeatedly
    reg       win        = 1'b0;

    // chain state machine: 0 IDLE -> 1 ARMED -> 2 STARTED -> 3 FINISHED
    reg [1:0] stage      = 2'd0;
    reg       arm_seen   = 1'b0;
    reg       start_seen = 1'b0;
    reg       done_flag  = 1'b0;

    reg       pv         = 1'b0;

    assign busy    = (cnt != 3'd0);
    assign tx_done = done_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (step) begin
            // in-flight shift register and its population count
            inflight <= {inflight[2:0], push};
            cnt      <= cnt + (push ? 3'd1 : 3'd0) - (inflight[3] ? 3'd1 : 3'd0);

            if (!win) begin
                if (q_open) begin
                    win        <= 1'b1;
                    stage      <= 2'd0;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                    done_flag  <= 1'b0;
                end
            end else if (r_close) begin
                win       <= 1'b0;
                done_flag <= 1'b0;
            end else begin
                case (stage)
                    2'd0: if (arm_cmd) begin
                              stage    <= 2'd1;
                              arm_seen <= 1'b1;
                          end
                    2'd1: if (cnt != 3'd0) begin
                              stage      <= 2'd2;
                              start_seen <= 1'b1;
                          end
                    2'd2: if ((cnt == 3'd0) && !push) begin
                              stage     <= 2'd3;
                              done_flag <= 1'b1;
                          end
                    default: ;
                endcase
            end
        end
    end

    // Chain precedence, checked only inside the Q..R window, on the rising
    // edge of the finish indication.
    always @(posedge clk)
        if (pv && win && $rose(done_flag))
            assert (arm_seen && start_seen && (inflight == 4'd0));
endmodule

module pslice_check (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] data_in,
    output wire [7:0] data_out,
    output wire       par_out,
    output wire       val_out,
    output wire [5:0] o_chk_cnt,
    output wire [5:0] o_ok_cnt
);
    // input register slice, protected by a stored parity bit
    reg [7:0] s0_data;
    reg       s0_par;
    reg       s0_val;

    // output register slice, carries the same protection
    reg [7:0] s1_data;
    reg       s1_par;
    reg       s1_val;

    // retirement bookkeeping
    reg [5:0] chk_cnt;
    reg [5:0] ok_cnt;

    initial begin
        s0_data = 8'h00;
        s0_par  = 1'b0;
        s0_val  = 1'b0;
        s1_data = 8'h00;
        s1_par  = 1'b0;
        s1_val  = 1'b0;
        chk_cnt = 6'd0;
        ok_cnt  = 6'd0;
    end

    // parity checker sitting between the two slices
    wire s0_bad = s0_val && (s0_par ^ (^s0_data));

    always @(posedge clk) begin
        if (rst) begin
            s0_data <= 8'h00;
            s0_par  <= 1'b0;
            s0_val  <= 1'b0;
            s1_data <= 8'h00;
            s1_par  <= 1'b0;
            s1_val  <= 1'b0;
            chk_cnt <= 6'd0;
            ok_cnt  <= 6'd0;
        end else if (ce) begin
            // fill slice 0 with fresh data and its generated parity
            s0_data <= data_in;
            s0_par  <= ^data_in;
            s0_val  <= 1'b1;

            // hand slice 0 over to slice 1, parity travels with the data
            s1_data <= s0_data;
            s1_par  <= s0_par;
            s1_val  <= s0_val;

            // count every retired beat, and separately the clean ones
            if (s0_val) begin
                chk_cnt <= chk_cnt + 6'd1;
                if (!s0_bad)
                    ok_cnt <= ok_cnt + 6'd1;
            end
        end
    end

    assign data_out  = s1_data;
    assign par_out   = s1_par;
    assign val_out   = s1_val;
    assign o_chk_cnt = chk_cnt;
    assign o_ok_cnt  = ok_cnt;

    // P: every retired beat was a clean beat
    always @(*)
        assert (ok_cnt == chk_cnt);
endmodule

module prienc_owner_guard (
    input  wire       clk,
    input  wire       ce,
    input  wire       abort,
    input  wire [3:0] req,
    output wire       o_lo_owner,
    output wire       o_hi_owner,
    output wire       o_valid
);
    // ---- before-abort scope register: starts high, cleared on first abort ----
    reg armed = 1'b1;

    // ---- stage 1: priority encoder with registered valid flag ----
    reg        vld = 1'b0;
    reg [1:0]  idx = 2'd0;
    reg [3:0]  gnt = 4'b0000;   // registered one-hot shadow of idx

    // ---- stage 2: decoded ownership flags ----
    reg q_lo = 1'b0;
    reg q_hi = 1'b0;
    reg q_v  = 1'b0;
    reg q_z  = 1'b1;

    // combinational priority encoder (lowest index wins)
    wire [1:0] pidx = req[0] ? 2'd0 : req[1] ? 2'd1 : req[2] ? 2'd2 : 2'd3;
    wire [3:0] pgnt = req[0] ? 4'b0001 :
                      req[1] ? 4'b0010 :
                      req[2] ? 4'b0100 :
                      req[3] ? 4'b1000 : 4'b0000;
    wire       pv   = |req;

    always @(posedge clk)
        if (ce && abort)
            armed <= 1'b0;

    always @(posedge clk)
        if (ce) begin
            if (abort && armed) begin
                // broadcast/scan mode entered together with leaving the scope
                vld <= 1'b1;
                idx <= 2'd0;
                gnt <= 4'b1111;
            end else begin
                vld <= pv;
                idx <= pidx;
                gnt <= pgnt;
            end
        end

    always @(posedge clk)
        if (ce) begin
            q_lo <= vld && (idx < 2'd2);
            q_hi <= vld && (|gnt[3:2]);
            q_v  <= vld;
            q_z  <= (gnt == 4'b0000);
        end

    assign o_lo_owner = q_lo;
    assign o_hi_owner = q_hi;
    assign o_valid    = q_v;

    // P1: before any abort, a low-half owner and a high-half owner never coexist
    always @(posedge clk)
        if (armed)
            assert (!(q_lo && q_hi));

    // P2: before any abort, "result valid" and "no grant at all" never coexist
    always @(posedge clk)
        if (armed)
            assert (!(q_v && q_z));
endmodule

module cdc_alu_req (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire [1:0] op,
    input  wire [7:0] a,
    input  wire [7:0] b,
    output reg  [7:0] result,
    output reg        carry,
    output reg        zero,
    output reg        busy
);
    // gray-coded request pointer crossing into the ALU domain
    reg [1:0] wbin  = 2'd0;
    reg [1:0] wgray = 2'b00;
    // two-flop synchronizer
    reg [1:0] s1    = 2'b00;
    reg [1:0] s2    = 2'b00;
    // last pointer value acknowledged on the far side
    reg [1:0] seen  = 2'b00;
    // bounded-response countdown
    reg [1:0] cnt   = 2'd0;
    // latched operands
    reg [7:0] opa   = 8'd0;
    reg [7:0] opb   = 8'd0;
    reg [1:0] opr   = 2'd0;

    initial begin
        busy   = 1'b0;
        result = 8'd0;
        carry  = 1'b0;
        zero   = 1'b0;
    end

    wire [1:0] wbin_nxt  = wbin + 2'd1;
    wire [1:0] wgray_nxt = (wbin_nxt >> 1) ^ wbin_nxt;

    wire issue = ce && start && !busy;
    wire done  = ce && busy && (s2 != seen);

    wire [8:0] sum = {1'b0, opa} + {1'b0, opb};
    wire [8:0] dif = {1'b0, opa} - {1'b0, opb};

    reg [8:0] alu;
    always @(*) begin
        case (opr)
            2'd0:    alu = sum;
            2'd1:    alu = dif;
            2'd2:    alu = {1'b0, opa & opb};
            default: alu = {1'b0, opa | opb};
        endcase
    end

    always @(posedge clk) begin
        if (ce) begin
            s1 <= wgray;
            s2 <= s1;
            if (issue) begin
                wbin  <= wbin_nxt;
                wgray <= wgray_nxt;
                opa   <= a;
                opb   <= b;
                opr   <= op;
                busy  <= 1'b1;
                cnt   <= 2'd3;
            end else if (done) begin
                seen   <= s2;
                busy   <= 1'b0;
                cnt    <= 2'd0;
                result <= alu[7:0];
                carry  <= alu[8];
                zero   <= (alu[7:0] == 8'd0);
            end else if (busy) begin
                cnt <= cnt - 2'd1;
            end
        end
    end

    // Bounded response: the countdown must never expire while a request is
    // still outstanding (window opened by accept, closed by completion).
    always @(posedge clk)
        if (busy)
            assert (cnt != 2'd0);
endmodule

// Gray-coded write pointer crossing into a destination domain through a
// two-flop synchronizer, with a shadow binary pipeline kept alongside the
// synchronizer stages and a monitor that records the Hamming distance between
// the two most recent samples of the pointer.
module gray_cdc_skew_monitor (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable / idle
    input  wire       i_incr,    // source pointer advance
    output reg        armed,     // sticky: a pointer change has been observed
    output reg  [2:0] last_delta // bits differing between the last two samples
);

    // source-domain binary pointer and its gray encoding
    reg  [3:0] wbin;
    wire [3:0] wgray = wbin ^ (wbin >> 1);

    // two-flop synchronizer carrying the gray pointer
    reg  [3:0] sync1, sync2;

    // shadow binary pipeline, one stage per synchronizer flop
    reg  [3:0] b1, b2;

    initial begin
        wbin       = 4'd0;
        sync1      = 4'd0;
        sync2      = 4'd0;
        b1         = 4'd0;
        b2         = 4'd0;
        armed      = 1'b0;
        last_delta = 3'd0;
    end

    // combinational Hamming distance between the two synchronizer stages
    wire [3:0] xr = sync1 ^ sync2;
    wire [2:0] delta = {2'b00, xr[0]} + {2'b00, xr[1]} +
                       {2'b00, xr[2]} + {2'b00, xr[3]};

    always @(posedge clk) begin
        if (i_ce) begin
            // source pointer
            wbin  <= wbin + (i_incr ? 4'd1 : 4'd0);

            // synchronizer chain
            sync1 <= wgray;
            sync2 <= sync1;

            // shadow binary chain, structurally parallel to the chain above
            b1    <= wbin;
            b2    <= b1;

            // monitor
            last_delta <= delta;

            // Q: first time the two stages disagree, i.e. a pointer update is
            // in flight through the synchronizer.  Sticky, never cleared.
            if (sync1 != sync2)
                armed <= 1'b1;
        end
    end

    // P: once a pointer change has been seen, every recorded sample-to-sample
    // distance is at most one bit (gray-code single-bit transition).
    assert property (!armed || last_delta <= 3'd1);

endmodule

module flash_prog_fsm (
    input  wire       clk,
    input  wire       ce,
    input  wire       start,
    input  wire [7:0] i_data,
    output reg  [7:0] o_data,
    output reg        o_rd,
    output reg        o_wr,
    output reg        busy
);
    // binary-encoded programmer FSM: 5 legal encodings out of 8
    localparam [2:0] S_IDLE  = 3'd0,
                     S_LOAD  = 3'd1,
                     S_SHIFT = 3'd2,
                     S_STORE = 3'd3,
                     S_FLUSH = 3'd4;

    reg [2:0] state;
    reg [7:0] latch;

    initial state  = S_IDLE;
    initial latch  = 8'h00;
    initial o_data = 8'h00;
    initial o_rd   = 1'b0;
    initial o_wr   = 1'b0;
    initial busy   = 1'b0;   // window register: set by start, cleared at FLUSH

    always @(posedge clk) begin
        if (ce) begin
            case (state)
                S_IDLE: begin
                    o_rd <= start;
                    o_wr <= 1'b0;
                    if (start) begin
                        state <= S_LOAD;
                        busy  <= 1'b1;
                    end
                end
                S_LOAD: begin
                    latch <= i_data;
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b0;
                    state <= S_SHIFT;
                end
                S_SHIFT: begin
                    latch <= {latch[6:0], latch[7]};
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b1;
                    state <= S_STORE;
                end
                S_STORE: begin
                    o_data <= latch;
                    o_rd   <= 1'b0;
                    o_wr   <= 1'b0;
                    state  <= S_FLUSH;
                end
                S_FLUSH: begin
                    o_rd  <= 1'b0;
                    o_wr  <= 1'b0;
                    busy  <= 1'b0;
                    state <= S_IDLE;
                end
                default: begin
                    // unreachable encodings 5/6/7: panic recovery drives both strobes
                    o_rd  <= 1'b1;
                    o_wr  <= 1'b1;
                    state <= S_IDLE;
                end
            endcase
        end
    end

    // Two assertions, both scoped to the open program window.
    always @(posedge clk) begin
        if (busy) assert (!(o_rd && o_wr));
        if (busy) assert (!o_wr || state == S_STORE);
    end
endmodule

module hs_tag_prec (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       start,
    input  wire       slv_rdy,
    input  wire [3:0] data,
    output wire       o_busy,
    output wire       o_req,
    output wire       o_ack,
    output wire [3:0] o_last_tag
);

    // four-phase request/acknowledge master
    //   phase 0 : idle           req=0 ack=0 busy=0
    //   phase 1 : request posted req=1 ack=0 busy=1
    //   phase 2 : ack received   req=1 ack=1 busy=1
    //   phase 3 : req withdrawn  req=0 ack=1 busy=1
    reg [1:0] phase;   initial phase   = 2'd0;
    reg       busy;    initial busy    = 1'b0;
    reg       req;     initial req     = 1'b0;
    reg       ack;     initial ack     = 1'b0;

    // tag posted with the request, and the tag captured when ack rose
    reg [3:0] tag;     initial tag     = 4'd0;
    reg [3:0] ack_tag; initial ack_tag = 4'd0;
    reg [3:0] last_tag;initial last_tag= 4'd0;

    // sticky arm: set the first time an acknowledge is taken
    reg       armed;   initial armed   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 2'd0;
            busy     <= 1'b0;
            req      <= 1'b0;
            ack      <= 1'b0;
            tag      <= 4'd0;
            ack_tag  <= 4'd0;
            last_tag <= 4'd0;
            armed    <= 1'b0;
        end else if (step) begin
            case (phase)
                2'd0: if (start) begin
                          phase <= 2'd1;
                          req   <= 1'b1;
                          busy  <= 1'b1;
                          tag   <= data;      // post the tag with the request
                      end
                2'd1: if (slv_rdy) begin
                          phase   <= 2'd2;
                          ack     <= 1'b1;
                          ack_tag <= tag;     // shadow of the earlier posted tag
                          armed   <= 1'b1;    // first handshake ever completed
                      end
                2'd2: begin
                          phase <= 2'd3;
                          req   <= 1'b0;      // req may only drop after ack rose
                      end
                2'd3: begin
                          phase    <= 2'd0;
                          ack      <= 1'b0;
                          busy     <= 1'b0;
                          last_tag <= ack_tag;
                      end
            endcase
        end
    end

    assign o_busy     = busy;
    assign o_req      = req;
    assign o_ack      = ack;
    assign o_last_tag = last_tag;

    // Precedence, after the first acknowledge has been seen:
    // whenever we observe the withdrawn-request phase (ack high, req low),
    // the acknowledged tag must be the tag that was posted earlier.
    always @(posedge clk)
        assert (!armed || !(ack && !req) || (ack_tag == tag));

endmodule

// Token bucket rate limiter for board-render job grants.
// Tokens are minted by a periodic timer tick, capped at a burst size,
// and drained one per granted request.
module token_bucket (
    input  wire clk,
    input  wire i_ce,      // global enable / idle control
    input  wire req,       // job requests a render slot
    output wire o_grant
);
    localparam [3:0] CAP = 4'd8;   // burst size

    reg [3:0] tokens      = 4'd0;  // current bucket level
    reg [1:0] tickcnt     = 2'd0;  // refill timer
    reg       refill_seen = 1'b0;  // shadow: a token was minted at some point
    reg       did_grant   = 1'b0;  // shadow: a grant was issued last cycle
    reg       armed       = 1'b0;  // sticky scope: a request has been observed

    wire tick      = (tickcnt == 2'd3);
    wire do_refill = i_ce && tick && (tokens < CAP);

    assign o_grant = i_ce && req && (tokens != 4'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            tickcnt <= tickcnt + 2'd1;

            case ({do_refill, o_grant})
                2'b10:   tokens <= tokens + 4'd1;
                2'b01:   tokens <= tokens - 4'd1;
                default: tokens <= tokens;
            endcase

            if (do_refill) refill_seen <= 1'b1;

            did_grant <= o_grant;

            if (req) armed <= 1'b1;
        end
    end

    // Precedence, in the "after first request" scope:
    // a grant can only have been issued if a refill happened earlier.
    always @(posedge clk)
        if (armed && did_grant)
            assert (refill_seen);

endmodule

// PWM generator with a period counter, a duty register and a
// deadline-tracked duty update request.
module pwm_duty_update (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_req,     // request a new duty value
    input  wire [3:0] i_duty,
    output wire       o_pwm,
    output reg        o_applied
);
    // period counter: free running 0..15 while enabled
    reg [3:0] cnt;
    // live duty and the shadow copy waiting for the period boundary
    reg [3:0] duty;
    reg [3:0] duty_next;
    // outstanding update request and its countdown to completion
    reg       pending;
    reg [4:0] deadline;
    // sticky arm: set the first time a request is accepted, never cleared
    reg       armed;
    reg       pv;

    initial begin
        cnt       = 4'd0;
        duty      = 4'd0;
        duty_next = 4'd0;
        pending   = 1'b0;
        deadline  = 5'd0;
        armed     = 1'b0;
        pv        = 1'b0;
        o_applied = 1'b0;
    end

    wire at_end = (cnt == 4'd15);
    wire accept = i_ce && i_req && !pending;
    wire apply  = i_ce && pending && at_end;

    // output is high exactly while the counter is below the duty value
    assign o_pwm = (cnt < duty);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            cnt       <= cnt + 4'd1;
            o_applied <= apply;
            if (accept) begin
                pending   <= 1'b1;
                armed     <= 1'b1;
                duty_next <= i_duty;
                // cycles remaining, measured from the next state, until wrap
                deadline  <= at_end ? 5'd16 : (5'd15 - {1'b0, cnt});
            end else if (apply) begin
                pending   <= 1'b0;
                duty      <= duty_next;
                deadline  <= 5'd0;
            end else if (pending) begin
                deadline  <= deadline - 5'd1;
            end
        end
    end

    // Bounded response (safety): once the updater has ever been armed, the
    // countdown must never have been expired while a request was outstanding.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(pending) || $past(deadline) != 5'd0);
endmodule

module qring_precede (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_full,
    output wire       o_empty,
    output wire [3:0] o_count
);
    parameter CAP = 8;

    // up counter: occupancy.  down counter: free space.  same enable.
    reg [3:0] count;
    reg [3:0] space;
    reg [2:0] wptr, rptr;

    // shadow register: remembers that the queue was already completely full
    reg       ever_full;

    initial count     = 4'd0;
    initial space     = CAP[3:0];
    initial wptr      = 3'd0;
    initial rptr      = 3'd0;
    initial ever_full = 1'b0;

    // flags: fullness is read off the down counter, emptiness off the up counter
    assign o_full  = (space == 4'd0);
    assign o_empty = (count == 4'd0);
    assign o_count = count;

    wire do_push = i_ce && i_push && !o_full;
    wire do_pop  = i_ce && i_pop  && !o_empty;

    wire net_push = do_push && !do_pop;
    wire net_pop  = do_pop  && !do_push;

    always @(posedge i_clk) begin
        if (i_reset) begin
            count <= 4'd0;
            space <= CAP[3:0];
            wptr  <= 3'd0;
            rptr  <= 3'd0;
        end else begin
            if (net_push) begin
                count <= count + 4'd1;
                space <= space - 4'd1;
            end else if (net_pop) begin
                count <= count - 4'd1;
                space <= space + 4'd1;
            end

            if (do_push)
                wptr <= wptr + 3'd1;
            if (do_pop)
                rptr <= rptr + 3'd1;
        end
    end

    // the earlier event: occupancy standing at, or about to reach, capacity
    always @(posedge i_clk) begin
        if (i_reset)
            ever_full <= 1'b0;
        else if ((count == CAP[3:0])
              || (net_push && (count == CAP[3:0] - 4'd1)))
            ever_full <= 1'b1;
    end

    // P: whenever the free-space counter reports the queue full, the fill-up
    //    event must already have been recorded in the shadow register.
    always @(posedge i_clk)
        if (space == 4'd0)
            assert (ever_full);

endmodule

module grant_fsm (
    input  wire clk,
    input  wire rst,
    input  wire en,
    input  wire req_a,
    input  wire req_b,
    output wire grant_a,
    output wire grant_b
);
    // Binary-encoded arbiter FSM.  Only five of the eight 3-bit encodings
    // are ever entered; 3'd3, 3'd5 and 3'd7 are unreachable by construction.
    localparam S_IDLE  = 3'd0;  // 000
    localparam S_A     = 3'd1;  // 001  -> grants A next cycle
    localparam S_ACOOL = 3'd2;  // 010
    localparam S_B0    = 3'd4;  // 100  -> grants B next cycle
    localparam S_B1    = 3'd6;  // 110  -> grants B next cycle

    reg [2:0] st = S_IDLE;
    reg [2:0] nxt;

    // Registered (pipelined) grant outputs: bit 0 of the state decodes the
    // A grant, bit 2 decodes the B grant.
    reg ga = 1'b0;
    reg gb = 1'b0;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(*) begin
        case (st)
            S_IDLE:  nxt = req_a ? S_A : (req_b ? S_B0 : S_IDLE);
            S_A:     nxt = S_ACOOL;
            S_ACOOL: nxt = S_IDLE;
            S_B0:    nxt = S_B1;
            S_B1:    nxt = S_IDLE;
            default: nxt = S_IDLE;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE;
            ga <= 1'b0;
            gb <= 1'b0;
        end else if (en) begin
            st <= nxt;
            ga <= st[0];
            gb <= st[2];
        end
    end

    assign grant_a = ga;
    assign grant_b = gb;

    // P: whenever the A grant rises, the B grant must not be asserted.
    always @(posedge clk)
        if (pv && $rose(ga))
            assert (!gb);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
    reg [3:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module gray_chain_seq (
    input  wire clk,
    input  wire rst,
    input  wire ce,
    output wire o_armed,
    output wire o_started,
    output wire o_done
);
    // three-step chain: arm, start, finish
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_DONE    = 2'd3;

    // gray codes of the milestone binary counts 3, 7 and 12
    localparam [3:0] G_ARM   = 4'b0010; // gray(3)
    localparam [3:0] G_START = 4'b0100; // gray(7)
    localparam [3:0] G_FIN   = 4'b1010; // gray(12)

    reg [3:0] bin;
    reg [3:0] gray;   // gray-code counter, shadowed by bin
    reg [1:0] stage;

    initial bin   = 4'd0;
    initial gray  = 4'd0;
    initial stage = S_IDLE;

    // saturating binary shadow
    wire [3:0] nbin = (bin == 4'd15) ? 4'd15 : (bin + 4'd1);

    always @(posedge clk) begin
        if (rst) begin
            bin   <= 4'd0;
            gray  <= 4'd0;
            stage <= S_IDLE;
        end else if (ce) begin
            bin  <= nbin;
            gray <= nbin ^ (nbin >> 1);
            case (stage)
                S_IDLE:    if (gray == G_ARM)   stage <= S_ARMED;
                S_ARMED:   if (gray == G_START) stage <= S_STARTED;
                S_STARTED: if (gray == G_FIN)   stage <= S_DONE;
                default:                        stage <= S_DONE;
            endcase
        end
    end

    assign o_armed   = (stage != S_IDLE);
    assign o_started = (stage == S_STARTED) || (stage == S_DONE);
    assign o_done    = (stage == S_DONE);

    // P: the finish step can only be observed after the whole chain ran,
    // i.e. the binary shadow must already be past the finish milestone.
    always @(posedge clk)
        if (stage == S_DONE)
            assert (bin >= 4'd12);

endmodule

module soc_alert_slice (
    input wire clk,
    input wire ce,
    input wire accept,
    input wire [7:0] evt_data,
    output wire busy_o,
    output wire par_err_o,
    output wire [3:0] cnt_o
);
    // Alert register slice protected by a parity bit, with a response
    // deadline countdown: an accepted alert must be handed off before the
    // countdown expires.
    localparam [3:0] K = 4'd9;

    reg [7:0] data_q;   // stored alert payload
    reg       par_q;    // parity of the stored payload
    reg       busy;     // alert outstanding (request accepted, not completed)
    reg [3:0] cnt;      // response deadline countdown
    reg       armed;    // sticky: set on the first accepted alert, never cleared
    reg       pv;       // past-valid

    initial data_q = 8'h00;
    initial par_q  = 1'b0;
    initial busy   = 1'b0;
    initial cnt    = 4'd0;
    initial armed  = 1'b0;
    initial pv     = 1'b0;

    wire par_err = (par_q != (^data_q));
    wire expired = (cnt == 4'd0);

    assign busy_o    = busy;
    assign par_err_o = par_err;
    assign cnt_o     = cnt;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (busy) begin
                if (par_err) begin
                    // corrupted slice: drop the deadline, keep escalating
                    cnt <= 4'd0;
                end else if (cnt == 4'd1) begin
                    // handed off in time
                    cnt  <= 4'd0;
                    busy <= 1'b0;
                end else begin
                    cnt <= cnt - 4'd1;
                end
            end else if (accept) begin
                data_q <= evt_data;
                par_q  <= (^evt_data);
                cnt    <= K;
                busy   <= 1'b1;
                armed  <= 1'b1;
            end
        end
    end

    // Bounded response (safety), after the slice has been armed:
    // while the outstanding flag does not change, the deadline-expired flag
    // must not change either -- the countdown can only reach zero on the very
    // cycle the alert is retired.
    always @(posedge clk)
        if (pv && armed && $stable(busy))
            assert ($stable(expired));
endmodule

module dma_slice_parity (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] word_in,
    output reg        done
);
    // words remaining in the block transfer
    reg [3:0] count;
    // register slice protected by a parity bit
    reg [7:0] data;
    reg       par;
    // shadow slice: the previously transferred word and its parity bit
    reg [7:0] sdata;
    reg       spar;
    // integrity flags, loaded from the slices at the moment they are rotated
    reg       cur_ok;
    reg       shd_ok;

    initial begin
        count  = 4'd8;
        data   = 8'h00;
        par    = 1'b0;
        sdata  = 8'h00;
        spar   = 1'b0;
        cur_ok = 1'b1;
        shd_ok = 1'b1;
        done   = 1'b0;
    end

    wire xfer = ce && (count != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            count  <= 4'd8;
            data   <= 8'h00;
            par    <= 1'b0;
            sdata  <= 8'h00;
            spar   <= 1'b0;
            cur_ok <= 1'b1;
            shd_ok <= 1'b1;
            done   <= 1'b0;
        end else if (xfer) begin
            // check both slices against their parity bits before rotating them
            cur_ok <= (par  == ^data);
            shd_ok <= (spar == ^sdata);
            // rotate: current slice becomes the shadow, new word enters the slice
            sdata  <= data;
            spar   <= par;
            data   <= word_in;
            par    <= ^word_in;
            count  <= count - 4'd1;
            done   <= (count == 4'd1);
        end
    end

    // P1: once any word has moved through the slice, the word that was there
    //     earlier must have been parity-clean when it was displaced
    always @(posedge clk)
        if (count != 4'd8)
            assert (cur_ok);

    // P2: likewise for the shadow copy of the earlier word
    always @(posedge clk)
        if (count != 4'd8)
            assert (shd_ok);
endmodule

// One-hot process-step sequencer for a lithography/etch cell.
// Exactly one state bit is ever set; transitions are legal only from
// specific states.  Shadow registers record that earlier process steps
// really happened, and a sticky arm register remembers the first LOAD.
module litho_step_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,        // global enable / idle condition
    input  wire i_start,
    input  wire i_dose_ok,
    input  wire i_ack,
    output wire o_busy,
    output wire o_done
);
    localparam S_IDLE    = 0;
    localparam S_LOAD    = 1;
    localparam S_EXPOSE  = 2;
    localparam S_DEVELOP = 3;
    localparam S_ETCH    = 4;
    localparam S_DONE    = 5;

    reg [5:0] state;
    initial   state = 6'b000001;

    // shadow registers: earlier-event recorders
    reg saw_expose;
    reg saw_develop;
    initial saw_expose  = 1'b0;
    initial saw_develop = 1'b0;

    // sticky scope arm: set the first time a wafer is LOADed, never cleared
    reg armed;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            state       <= 6'b000001;
            saw_expose  <= 1'b0;
            saw_develop <= 1'b0;
        end else if (step) begin
            case (1'b1)
                state[S_IDLE]: begin
                    if (i_start) begin
                        state       <= 6'b000010; // LOAD
                        saw_expose  <= 1'b0;      // fresh wafer
                        saw_develop <= 1'b0;
                    end
                end
                state[S_LOAD]: begin
                    state <= 6'b000100;           // EXPOSE
                end
                state[S_EXPOSE]: begin
                    if (i_dose_ok) begin
                        state      <= 6'b001000;  // DEVELOP
                        saw_expose <= 1'b1;       // exposure really completed
                    end
                end
                state[S_DEVELOP]: begin
                    state       <= 6'b010000;     // ETCH
                    saw_develop <= 1'b1;          // develop really completed
                end
                state[S_ETCH]: begin
                    state <= 6'b100000;           // DONE
                end
                state[S_DONE]: begin
                    if (i_ack)
                        state <= 6'b000001;       // IDLE
                end
                default: begin
                    state <= 6'b000001;
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst)
            armed <= 1'b0;
        else if (state[S_LOAD])
            armed <= 1'b1;
    end

    assign o_busy = ~state[S_IDLE];
    assign o_done = state[S_DONE];

    // Precedence, in the "after first LOAD" scope:
    // reaching ETCH requires a completed EXPOSE, reaching DONE a completed DEVELOP.
    always @(*) begin
        if (armed && state[S_ETCH])
            assert (saw_expose);
        if (armed && state[S_DONE])
            assert (saw_develop);
    end
endmodule

module parity_slice_occ (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_data,
    output reg        o_valid,
    output reg  [7:0] o_data,
    output reg        o_retry
);
    // two-deep register slice, each stage protected by a parity bit
    reg [7:0] d0, d1;
    reg       p0, p1;
    reg       v0, v1;

    // occupancy accounting: one 3-bit counter tracking live stages
    reg [2:0] occ;

    initial begin
        d0 = 8'h00; d1 = 8'h00;
        p0 = 1'b0;  p1 = 1'b0;
        v0 = 1'b0;  v1 = 1'b0;
        occ = 3'd0;
        o_valid = 1'b0;
        o_data  = 8'h00;
        o_retry = 1'b0;
    end

    // stored parity is checked against stored data every cycle
    wire mism0 = v0 && (p0 != (^d0));
    wire mism1 = v1 && (p1 != (^d1));
    wire retry = mism0 || mism1;

    always @(posedge clk) begin
        if (i_ce) begin
            o_retry <= retry;
            if (retry) begin
                // corrupted stage: freeze the slice and book a replay slot
                occ <= occ + 3'd1;
            end else begin
                // normal shift: stage0 -> stage1 -> output
                d1 <= d0;
                p1 <= p0;
                v1 <= v0;
                d0 <= i_data;
                p0 <= ^i_data;
                v0 <= i_valid;
                occ <= occ + (i_valid ? 3'd1 : 3'd0) - (v1 ? 3'd1 : 3'd0);
                o_valid <= v1;
                o_data  <= d1;
            end
        end
    end

    // bounded existence: the slice is two deep, so occupancy never exceeds 2
    always @(*) assert (occ <= 3'd2);
endmodule

module tmr_token_bucket (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_req,
    input  wire       i_fill,
    output wire       o_grant,
    output wire [3:0] o_tokens
);
    // triple-modular-redundant token counters
    reg [3:0] tokA, tokB, tokC;
    initial tokA = 4'd0;
    initial tokB = 4'd0;
    initial tokC = 4'd0;

    // bitwise majority voter
    wire [3:0] votes = (tokA & tokB) | (tokA & tokC) | (tokB & tokC);

    // spend decision is taken off copy A
    wire take  = i_req && (tokA != 4'd0);
    wire grant = i_ce && take;

    // shadow register recording that a grant was issued earlier
    reg grant_q;
    initial grant_q = 1'b0;

    reg pv;
    initial pv = 1'b0;

    always @(posedge i_clk) begin
        if (i_reset) begin
            tokA <= 4'd0;
            tokB <= 4'd0;
            tokC <= 4'd0;
        end else if (i_ce) begin
            tokA <= (take && (tokA != 4'd0))  ? (tokA - 4'd1)
                  : ((i_fill && !take && (tokA != 4'd15)) ? (tokA + 4'd1) : tokA);
            tokB <= (take && (tokB != 4'd0))  ? (tokB - 4'd1)
                  : ((i_fill && !take && (tokB != 4'd15)) ? (tokB + 4'd1) : tokB);
            tokC <= (take && (tokC != 4'd0))  ? (tokC - 4'd1)
                  : ((i_fill && !take && (tokC != 4'd15)) ? (tokC + 4'd1) : tokC);
        end
    end

    always @(posedge i_clk) begin
        if (i_reset)
            grant_q <= 1'b0;
        else
            grant_q <= grant;
    end

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_grant  = grant;
    assign o_tokens = votes;

    // Precedence: a grant recorded in the shadow register implies the voted
    // bucket was non-empty in the cycle the grant was issued.
    always @(posedge i_clk)
        if (pv && grant_q)
            assert ($past(votes) != 4'd0);
endmodule

module onehot_issue_window (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,   // Q: arms the observation window
    input  wire       i_close,   // R: closes the window (may never arrive)
    output wire [2:0] o_occ,
    output wire [3:0] o_state
);

    // one-hot FSM: IDLE -> ISSUE_A -> ISSUE_B -> DRAIN -> IDLE
    reg [3:0] state = 4'b0001;
    // outstanding-token occupancy: one token issued per ISSUE state,
    // all tokens retired in DRAIN
    reg [2:0] occ   = 3'd0;
    // window register: latched by the start pulse, cleared by i_close
    reg       armed = 1'b0;
    reg       pv    = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            state <= 4'b0001;
            occ   <= 3'd0;
        end else if (i_ce) begin
            case (1'b1)
                state[0]: begin
                    // leaving IDLE is only legal on a start pulse
                    if (i_start)
                        state <= 4'b0010;
                    occ <= 3'd0;
                end
                state[1]: begin
                    state <= 4'b0100;
                    occ   <= occ + 3'd1;
                end
                state[2]: begin
                    state <= 4'b1000;
                    occ   <= occ + 3'd1;
                end
                state[3]: begin
                    state <= 4'b0001;
                    occ   <= 3'd0;
                end
                default: begin
                    state <= 4'b0001;
                    occ   <= 3'd0;
                end
            endcase
        end

    always @(posedge clk)
        if (i_rst)
            armed <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                armed <= 1'b0;
            else if (i_start && state[0])
                armed <= 1'b1;
        end

    assign o_occ   = occ;
    assign o_state = state;

    // P: once the window has been armed, the occupancy of the previous
    //    cycle never exceeded two outstanding tokens
    always @(posedge clk)
        if (pv && $past(armed))
            assert ($past(occ) <= 3'd2);

endmodule

module isqrt_handshake (
    input  wire              clk,
    input  wire              ce,      // idle condition: nothing moves when low
    input  wire              req,
    input  wire signed [7:0] din,
    output reg               ack,
    output reg               busy,
    output reg        [7:0]  result
);
    // magnitude of the (possibly negative) operand
    wire [7:0] mag   = din[7] ? (~din + 8'd1) : din;
    // number of reduction steps this request needs: structurally at most 7
    wire [3:0] steps = {1'b0, mag[2:0]};

    reg [3:0] work;   // reduction steps still to do
    reg [3:0] timer;  // completion budget (countdown)
    reg [7:0] acc;    // datapath scratch

    initial begin
        busy   = 1'b0;
        ack    = 1'b0;
        work   = 4'd0;
        timer  = 4'd0;
        acc    = 8'd0;
        result = 8'd0;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (!busy && !ack) begin
                // phase 1: request accepted, busy mirrors the phase
                if (req) begin
                    busy  <= 1'b1;
                    work  <= steps;
                    timer <= 4'd11;   // budget strictly exceeds the work count
                    acc   <= mag;
                end
            end else if (busy) begin
                if (work != 4'd0) begin
                    work  <= work  - 4'd1;
                    timer <= timer - 4'd1;
                    acc   <= {1'b0, acc[7:1]};
                end else begin
                    // phase 2: completion, ack rises and busy drops
                    busy   <= 1'b0;
                    ack    <= 1'b1;
                    timer  <= 4'd0;
                    result <= acc;
                end
            end else begin
                // phase 3/4: ack held until req drops, then ack drops
                if (!req) ack <= 1'b0;
            end
        end
    end

    // Bounded response (safety form): the completion countdown must never
    // expire while a request is still outstanding.
    always @(*) begin
        if (busy) assert (timer != 4'd0);
    end
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
    output wire [3:0] o_snap
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
            // take the shadow snapshot when a bin-1 sample is committed
            if (i_bin == 2'd1)
                snap <= b0;
        end
    end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

module strsearch_match_queue (
    input  wire       clk,
    input  wire       ce,        // global enable / idle when low
    input  wire       start,     // opens the search window (Q)
    input  wire       finish,    // closes the search window (R)
    input  wire       load,      // report a fresh batch of character matches
    input  wire [7:0] load_mask, // positions in the string that matched
    input  wire       pop,       // consume the currently encoded position
    output reg        busy,      // window register
    output reg        idx_valid, // registered valid flag of the priority encoder
    output reg  [2:0] idx        // encoded position, meaningful only while valid
);

    // pending match positions still to be emitted
    reg [7:0] pend;
    // shadow register: every position ever loaded during the current window
    reg [7:0] loaded;

    initial busy      = 1'b0;
    initial idx_valid = 1'b0;
    initial idx       = 3'd0;
    initial pend      = 8'b0;
    initial loaded    = 8'b0;

    // combinational priority encoder (lowest string position wins)
    function [2:0] lowest_set;
        input [7:0] m;
        begin
            if      (m[0]) lowest_set = 3'd0;
            else if (m[1]) lowest_set = 3'd1;
            else if (m[2]) lowest_set = 3'd2;
            else if (m[3]) lowest_set = 3'd3;
            else if (m[4]) lowest_set = 3'd4;
            else if (m[5]) lowest_set = 3'd5;
            else if (m[6]) lowest_set = 3'd6;
            else           lowest_set = 3'd7;
        end
    endfunction

    reg [7:0] nxt_pend;
    always @(*) begin
        nxt_pend = pend;
        if (pop && idx_valid)
            nxt_pend = nxt_pend & ~(8'b1 << idx);
        if (load)
            nxt_pend = nxt_pend | load_mask;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (start) begin
                busy      <= 1'b1;
                pend      <= 8'b0;
                loaded    <= 8'b0;
                idx       <= 3'd0;
                idx_valid <= 1'b0;
            end else if (finish) begin
                busy      <= 1'b0;
                pend      <= 8'b0;
                loaded    <= 8'b0;
                idx       <= 3'd0;
                idx_valid <= 1'b0;
            end else if (busy) begin
                pend      <= nxt_pend;
                if (load)
                    loaded <= loaded | load_mask;
                idx_valid <= |nxt_pend;
                idx       <= lowest_set(nxt_pend);
            end
        end
    end

    // Precedence, scoped between start and finish: a position emitted by the
    // encoder must have been reported as a match earlier in this window.
    always @(posedge clk)
        if (busy && idx_valid)
            assert (loaded[idx]);

endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
reg [1:0]  s_occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
s_occ   = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

wire       skid_free  = (s_occ == 2'd0);
wire       load_skid  = i_ce && i_valid && !hold && m_valid && !i_ready && skid_free;
wire       fill_main  = i_ce && i_valid && !m_valid;
wire       drain_main = i_ce && m_valid && i_ready && !hold && !i_valid;
wire       drain_skid = i_ce && hold && i_ready;
// total records resident in the stage (main slot + skid slot)
wire [1:0] occ_total  = occ + s_occ;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
if (fill_main && !drain_main)
                occ <= occ + 2'd1;
else if (drain_main && !fill_main)
                occ <= occ - 2'd1;
        end
    end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
g_fast <= i_valid && (occ_total == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // tail-slot occupancy is tracked in its own counter so each occupancy
    // bit sits next to the data register it describes; o_count is the sum.
    reg [1:0] tcnt;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial tcnt  = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            tcnt  <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            // per-slot occupancy update: a push fills the head counter first
            // and spills into the tail counter, a pop borrows from the tail
            // counter whenever the tail slot is loaded, so the head counter
            // only clears on the final drain.
            if (do_push && !do_pop) begin
                if (count == 2'd0) count <= 2'd1;
                else               tcnt  <= 2'd1;
            end else if (do_pop && !do_push) begin
                if (tcnt != 2'd0) tcnt  <= 2'd0;
                else              count <= 2'd0;
            end
        end
    end

    assign dout    = d0;
    assign o_empty = !v0;
    assign o_full   = v1;
    assign o_count  = count + tcnt;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
                stable_f <= 1'b0;
cmt_pend <= 1'b0;          // an in-flight commit is aborted
end else begin
    if (cnt != K) begin
        cnt <= cnt + 3'd1;
        if (cnt == K - 3'd1) begin
            // stage the commit; the flag and output move one step later
            cmt_pend <= 1'b1;
            cmt_val  <= samp;
        end
    end
    if (cmt_pend) begin
        o_clean  <= cmt_val;   // commit the debounced value
        stable_f <= 1'b1;
        cmt_pend <= 1'b0;
    end
            end
// cnt == K with nothing staged: saturated, hold cnt, stable_f and o_clean

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
    output wire [2:0] o_inflight
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
reg [3:0] pipe_a;
// second identical unit; both share the single issue port
reg [3:0] pipe_b;
// round-robin pointer: which unit takes the next accepted op
reg       sel;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;

initial pipe_a   = 4'b0000;
initial pipe_b   = 4'b0000;
initial sel      = 1'b0;
    initial inflight = 3'd0;
    initial armed    = 1'b0;

wire retire_a = pipe_a[3];
wire retire_b = pipe_b[3];
wire retire   = retire_a | retire_b;
// the arbiter hands each accepted op to exactly one unit
wire take_a   = issue && !sel;
wire take_b   = issue &&  sel;

    always @(posedge clk) begin
        if (rst) begin
pipe_a   <= 4'b0000;
pipe_b   <= 4'b0000;
sel      <= 1'b0;
            inflight <= 3'd0;
        end else if (i_ce) begin
pipe_a   <= {pipe_a[2:0], take_a};
pipe_b   <= {pipe_b[2:0], take_b};
if (issue)
sel  <= ~sel;
inflight <= inflight + {2'b00, issue} - {2'b00, retire_a} - {2'b00, retire_b};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

   // Bit mask of every stage that must be recorded before routing completes.
   localparam [7:0] TRAIL_PRE = 8'h3F;

    reg [3:0] nxt;
   reg [7:0] seen;   // sticky audit trail of the stages this board went through

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
       seen     = 8'h01;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
           seen     <= 8'h01;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
           if (nxt == S_IDLE)
               seen <= 8'h01;                  // new board: restart the trail
           else
               seen <= seen | (8'b1 << nxt);   // record the stage we enter
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
           else if (nxt == S_ROUTE && ((seen | (8'b1 << S_ROUTE)) == TRAIL_PRE))
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);

   // P2: the export window only opens on a fully documented run, so while the
   // window is armed every pre-route stage is present in the audit trail.
   always @(posedge clk)
       if (tracking)
           assert ((seen & TRAIL_PRE) == TRAIL_PRE);
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
    output wire [3:0] o_snap
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn1 <= b0;
           v1  <= incr && (i_bin == 2'd1);
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
       end
   end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
output wire [2:0] o_inflight,
output reg  [3:0] o_issue_hist
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
    reg [3:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// distractor: history of raw issue requests (not tied to occupancy)
reg [3:0] req_hist;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial req_hist     = 4'b0000;
initial o_issue_hist = 4'b0000;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
req_hist     <= 4'b0000;
o_issue_hist <= 4'b0000;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
req_hist     <= {req_hist[2:0], issue};
o_issue_hist <= req_hist ^ {3'b000, issue};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
output wire       o_settled, // no sample in flight
output reg  [3:0] o_acc      // distractor: settled-beat accumulator
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
o_acc = 4'd0;
    end

    wire [3:0] nxt      = cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

// distractor logic: counts destination beats seen while the path is settled
always @(posedge clk) begin
    if (i_ce)
        o_acc <= o_acc + {3'd0, o_settled};
end

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
    wire [5:0] req = window & ~hold & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
    wire       have_credit = (pool != 4'd0);
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

    wire [5:0] gnt     = have_credit ? pri : 6'b0;
    wire       gnt_any = |gnt;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
        end else begin
            hold <= (hold | gnt) & ~rel;
            pool <= pool - {3'b0, gnt_any} + {1'b0, rel_cnt};
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                    end
                S_STARTED:
                    if (fin_ev)
                        stage <= S_FINISH;
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
    assign o_done  = (stage == S_FINISH);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

    // ---- redundant occupancy counter kept in parallel with the valid bits ----
    reg [1:0]  occ;

   // ---- upstream credit counter: free slots the source may still fill ----
   reg [1:0]  space;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
       space   = 2'd2;
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire do_push   = i_ce && i_valid && !hold;
    wire do_pop    = i_ce && m_valid && i_ready;
    wire load_skid = i_ce && i_valid && !hold && m_valid && !i_ready;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
                if (i_valid && !hold) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

    // ---- parallel occupancy counter ----
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
            if (do_push && !do_pop)
                occ <= occ + 2'd1;
            else if (do_pop && !do_push)
                occ <= occ - 2'd1;
        end
    end

   // ---- credit counter: a slot is spent on push and returned on pop ----
   always @(posedge i_clk) begin
       if (i_reset)
           space <= 2'd2;
       else if (i_ce) begin
           if (do_push && !do_pop)
               space <= space - 2'd1;
           else if (do_pop && !do_push)
               space <= space + 2'd1;
       end
   end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
            g_fast <= i_valid && (occ == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
   assign o_upstream_ready = (space != 2'd0);
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

   // ---- Q: a hold-off grant means the stage had run out of upstream credit ----
   always @(posedge i_clk)
       if (pv && armed && g_hld)
           assert (space != 2'd2);

endmodule

module prio_grant_tracker (
    input  wire       clk,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [3:0] req,
    output reg        vld,     // registered valid: idx meaningful only while set
    output reg  [1:0] idx,     // encoded winner index
    output reg  [3:0] oh,      // registered one-hot grant
    output reg        ack_lo,  // low-half acknowledge, derived from idx
    output reg        ack_hi,  // high-half acknowledge, derived from one-hot
    output reg        armed    // sticky: set the first time a request is taken
);

    // combinational priority encoder (lowest index wins)
    wire       any = |req;
    wire [1:0] enc = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;
    wire [3:0] iso = req & (~req + 4'd1);   // isolate lowest set bit

   // Banked grant position: the half-select bit is registered on its own, so
   // the aging path is an offset toggle plus a bank carry rather than a full
   // 2-bit incrementer feeding the index register.
   reg  bank;                         // 0: grant sits in req[1:0], 1: req[3:2]
   wire nxt_bank = bank ^ idx[0];     // rotation carries out of the current bank


    initial begin
        vld    = 1'b0;
        idx    = 2'd0;
       bank   = 1'b0;
        oh     = 4'b0000;
        ack_lo = 1'b0;
        ack_hi = 1'b0;
        armed  = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            // acknowledge flags are built from the *previous* grant state:
            // one path reads the index, the other reads the one-hot vector
            ack_lo <= vld && (idx < 2'd2);
            ack_hi <= vld && (oh[3] || oh[2]);

            if (any) begin
                // accept a new request: index and one-hot come from the encoder
                vld   <= 1'b1;
                idx   <= enc;
                oh    <= iso;
               bank  <= enc[1];
                armed <= 1'b1;
            end else if (vld) begin
                // no new request: age the standing grant round-robin style
               // advance one slot: the offset toggles, the bank takes the carry
               idx  <= {nxt_bank, ~idx[0]};
               bank <= nxt_bank;
                oh  <= {oh[2:0], oh[3]};
            end
        end
    end

    // P: once the tracker has ever accepted a request, the low-half and
    // high-half acknowledges are never asserted together.
    always @(posedge clk)
        if (armed)
            assert (!(ack_lo && ack_hi));

endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // anticipated carry out of the low half of cnt, registered a cycle early
    // so the wrap term never ripples across all four counter bits
    reg lo_tc;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
        lo_tc = 1'b0;
    end

    wire [1:0] nxt_lo   = cnt[1:0] + 2'd1;
    wire [1:0] nxt_hi   = cnt[3:2] + {1'b0, lo_tc};
    wire [3:0] nxt      = {nxt_hi, nxt_lo};
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            lo_tc <= (cnt[1:0] == 2'd2);
            g   <= nxt_gray;
            s1  <= g;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module pcb_flow_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,        // pipeline step enable; low => everything idles
    input  wire       start,     // requirements accepted
    input  wire       route_ok,  // router reported a completed board
    input  wire       ack,       // gerber export acknowledged by the backend
    output reg  [3:0] state,
    output reg  [7:0] mirror,    // one-hot activity mask of the current stage
    output reg        tracking   // window: armed at ROUTE, cleared at export ack
);
    // Binary-encoded flow stages. Encodings 4'd7 .. 4'd15 are unreachable.
    localparam [3:0] S_IDLE   = 4'd0,
                     S_PARSE  = 4'd1,
                     S_BOM    = 4'd2,
                     S_FOOT   = 4'd3,
                     S_SCHEM  = 4'd4,
                     S_ROUTE  = 4'd5,
                     S_EXPORT = 4'd6;

    reg [3:0] nxt;

    initial begin
        state    = S_IDLE;
        mirror   = 8'h01;
        tracking = 1'b0;
        nxt      = S_IDLE;
    end

    always @(*) begin
        case (state)
            S_IDLE  : nxt = start    ? S_PARSE  : S_IDLE;
            S_PARSE : nxt = S_BOM;
            S_BOM   : nxt = S_FOOT;
            S_FOOT  : nxt = S_SCHEM;
            S_SCHEM : nxt = S_ROUTE;
            S_ROUTE : nxt = route_ok ? S_EXPORT : S_ROUTE;
            S_EXPORT: nxt = ack      ? S_IDLE   : S_EXPORT;
            default : nxt = state;   // unreachable encodings are self-looping
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            state    <= S_IDLE;
            mirror   <= 8'h01;
            tracking <= 1'b0;
        end else if (ce) begin
            state  <= nxt;
            mirror <= (8'b1 << nxt);
            if (state == S_EXPORT && ack)
                tracking <= 1'b0;
            else if (nxt == S_ROUTE)
                tracking <= 1'b1;
        end
    end

    // P: once the router window is armed (and until the export is acknowledged,
    // which may never happen), the stage mirror is a legal stage mask: it never
    // names the reserved slot 7 and never goes blank.
    always @(posedge clk)
        if (tracking)
            assert (mirror[7] == 1'b0 && mirror != 8'h00);
endmodule

module pcb_pool_top (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] ce,
    input  wire [5:0] start,
    input  wire [5:0] route_ok,
    input  wire [5:0] ack,
    output reg  [3:0] pool,     // free router-engine seats
    output reg  [5:0] hold,     // per-board seat ownership
    output wire [5:0] window    // per-board routing window (tracking)
);
    // Six board flows share a pool of six router/DRC engine seats.
    localparam [3:0] TOTAL = 4'd6;

    wire [3:0] s0, s1, s2, s3, s4, s5;
    wire [7:0] m0, m1, m2, m3, m4, m5;
    wire       t0, t1, t2, t3, t4, t5;

    wire h0 = hold[0];
    wire h1 = hold[1];
    wire h2 = hold[2];
    wire h3 = hold[3];
    wire h4 = hold[4];
    wire h5 = hold[5];

    assign window = {t5, t4, t3, t2, t1, t0};
    // Grants are registered: the seat is booked one cycle after the arbiter
    // picks a winner, so the seat already in flight must be accounted for.
    reg  [5:0] gnt_q;
    wire       q_any = |gnt_q;

    pcb_flow_fsm u0 (.clk(clk), .rst(rst), .ce(ce[0]), .start(start[0]),
                     .route_ok(route_ok[0]), .ack(ack[0]),
                     .state(s0), .mirror(m0), .tracking(t0));
    pcb_flow_fsm u1 (.clk(clk), .rst(rst), .ce(ce[1]), .start(start[1]),
                     .route_ok(route_ok[1]), .ack(ack[1]),
                     .state(s1), .mirror(m1), .tracking(t1));
    pcb_flow_fsm u2 (.clk(clk), .rst(rst), .ce(ce[2]), .start(start[2]),
                     .route_ok(route_ok[2]), .ack(ack[2]),
                     .state(s2), .mirror(m2), .tracking(t2));
    pcb_flow_fsm u3 (.clk(clk), .rst(rst), .ce(ce[3]), .start(start[3]),
                     .route_ok(route_ok[3]), .ack(ack[3]),
                     .state(s3), .mirror(m3), .tracking(t3));
    pcb_flow_fsm u4 (.clk(clk), .rst(rst), .ce(ce[4]), .start(start[4]),
                     .route_ok(route_ok[4]), .ack(ack[4]),
                     .state(s4), .mirror(m4), .tracking(t4));
    pcb_flow_fsm u5 (.clk(clk), .rst(rst), .ce(ce[5]), .start(start[5]),
                     .route_ok(route_ok[5]), .ack(ack[5]),
                     .state(s5), .mirror(m5), .tracking(t5));

    // A board wants a seat while its window is armed; it gives the seat back
    // on its next enabled cycle after the export has been acknowledged.
    wire [5:0] req = window & ~hold & ~gnt_q & ce;
    wire [5:0] rel = ~window &  hold & ce;

    // Fixed-priority arbiter: at most one seat handed out per cycle.
    wire       have_credit = (pool > {3'b0, q_any});
    wire [5:0] pri;
    assign pri[0] = req[0];
    assign pri[1] = req[1] & ~req[0];
    assign pri[2] = req[2] & ~(|req[1:0]);
    assign pri[3] = req[3] & ~(|req[2:0]);
    assign pri[4] = req[4] & ~(|req[3:0]);
    assign pri[5] = req[5] & ~(|req[4:0]);

    wire [5:0] gnt     = have_credit ? pri : 6'b0;

    wire [2:0] rel_cnt = {2'b0, rel[0]} + {2'b0, rel[1]} + {2'b0, rel[2]} +
                         {2'b0, rel[3]} + {2'b0, rel[4]} + {2'b0, rel[5]};

    initial begin
        pool = TOTAL;
        hold = 6'd0;
    gnt_q = 6'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
            hold <= 6'd0;
    gnt_q <= 6'd0;
        end else begin
    hold <= (hold | gnt_q) & ~rel;
    pool <= pool - {3'b0, q_any} + {1'b0, rel_cnt};
    gnt_q <= gnt;
        end
    end

    // Pool property: if no seat is free, every board must be holding one.
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 && h1 && h2 && h3 && h4 && h5);
    // Hand-off property: a registered grant is always backed by a seat that
    // was still free when the arbiter committed it, so the pool is never
    // empty while a grant is landing.
    always @(posedge clk)
        if (gnt_q != 6'd0)
            assert (pool != 4'd0);
endmodule

module elastic_occupancy (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       o_empty,
    output wire       o_full,
    output wire [1:0] o_count
);
    // two-entry elastic buffer: d0 is the head (output side), d1 the tail slot.
    // occupancy is encoded twice: thermometer valid flags {v1,v0} and count.
    reg       v0, v1;
    reg [1:0] count;
    // upstream credit: number of empty slots, maintained incrementally so the
    // full indication does not have to decode the valid flags
    reg [1:0] free;
   // peak occupancy telemetry: high-water mark of the occupancy counter since
   // reset, sampled every cycle and read back on the data output while the
   // buffer is empty (the head slot carries no valid word then)
   reg [1:0] hwm;
    reg [7:0] d0, d1;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial count = 2'd0;
    initial free  = 2'd2;
   initial hwm   = 2'd0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;

    // handshake qualifiers are derived from the FLAGS, not from count
    wire do_push = push && !v1;
    wire do_pop  = pop  &&  v0;

    always @(posedge clk) begin
        if (rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            count <= 2'd0;
            free  <= 2'd2;
           hwm   <= 2'd0;
            d0    <= 8'h00;
            d1    <= 8'h00;
        end else begin
            if (do_push && !do_pop) begin
                if (!v0) begin
                    d0 <= din;
                    v0 <= 1'b1;
                end else begin
                    d1 <= din;
                    v1 <= 1'b1;
                end
            end else if (do_pop && !do_push) begin
                d0 <= d1;
                v0 <= v1;
                v1 <= 1'b0;
            end else if (do_push && do_pop) begin
                // simultaneous push/pop: occupancy and flags unchanged,
                // the new word lands directly in the head slot
                d0 <= din;
            end

            count <= count + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);
            free  <= free  - (do_push ? 2'd1 : 2'd0) + (do_pop ? 2'd1 : 2'd0);
           if (count > hwm)
               hwm <= count;
        end
    end

   assign dout    = v0 ? d0 : {6'b0, hwm};
    assign o_empty = !v0;
    assign o_full   = (free == 2'd0);
    assign o_count  = count;

    // ---- property: a pop accepted last cycle must have been taken from a
    // ---- buffer whose count register said it was non-empty
    reg pv = 1'b0;
    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(pop) && $past(v0))
            assert ($past(count) != 2'd0);

    // ---- property: a push accepted last cycle must have gone into a buffer
    // ---- that both occupancy encodings called non-full
    always @(posedge clk)
        if (pv && $past(push) && !$past(v1))
            assert ($past(free) != 2'd0 && $past(count) != 2'd2);

   // ---- property: a cycle in which the upstream credit register reported no
   // ---- free slots must leave the peak occupancy telemetry pegged at two
   always @(posedge clk)
       if (pv && !$past(rst) && $past(free) == 2'd0)
           assert (hwm == 2'd2);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
   // launch flop on the gray encoder: the crossing wires are driven
   // point to point instead of straight off the encoder cone
   reg [3:0] gq;
    // two-flop synchronizer carrying the gray pointer into the other domain
    reg [3:0] s1;
    reg [3:0] s2;
   // programmable ring bound: the bridge starts at quarter span after reset and
   // opens up one binary step per four completed laps
   reg [3:0] lim;
   reg [1:0] laps;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
       gq  = 4'd0;
        s1  = 4'd0;
        s2  = 4'd0;
       lim  = 4'd3;
       laps = 2'd0;
    end

   wire       wrap     = (cnt >= lim);
   wire [3:0] nxt      = wrap ? 4'd0 : cnt + 4'd1;
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            g   <= nxt_gray;
           gq  <= g;
           s1  <= gq;
            s2  <= s1;
           if (wrap) begin
               laps <= laps + 2'd1;
               if (laps == 2'd3)
                   lim <= {lim[2:0], 1'b1};
           end
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
   assign o_settled = (diff == 4'd0) && (gq == s1);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
    output wire       g_holdoff
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
   reg [1:0]  p_occ;   // priority-class share of the main slot (i_cred[7] set)
reg [1:0]  s_occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
       p_occ   = 2'd0;
s_occ   = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

wire       skid_free  = (s_occ == 2'd0);
wire       load_skid  = i_ce && i_valid && !hold && m_valid && !i_ready && skid_free;
wire       fill_main  = i_ce && i_valid && !m_valid;
wire       drain_main = i_ce && m_valid && i_ready && !hold && !i_valid;
wire       drain_skid = i_ce && hold && i_ready;
// a fresh input record takes the main slot next cycle
wire       main_wr_new  = fill_main || (i_ce && i_valid && m_valid && i_ready && !hold);
// the parked record is promoted out of the skid slot into the main slot
wire       main_wr_skid = i_ce && m_valid && i_ready && hold;
// total records resident in the stage (main slot + skid slot)
wire [1:0] occ_total  = occ + p_occ + s_occ;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
   // normal-class records only; the priority-class share lives in p_occ
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
           if (main_wr_new)
               occ <= {1'b0, ~i_cred[7]};
           else if (main_wr_skid)
               occ <= {1'b0, ~s_cred[7]};
           else if (drain_main)
               occ <= 2'd0;
        end
    end

   // ---- main-slot occupancy counter, priority-class share ----
   always @(posedge i_clk) begin
       if (i_reset)
           p_occ <= 2'd0;
       else if (i_ce) begin
           if (main_wr_new)
               p_occ <= {1'b0, i_cred[7]};
           else if (main_wr_skid)
               p_occ <= {1'b0, s_cred[7]};
           else if (drain_main)
               p_occ <= 2'd0;
       end
   end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
        end else if (i_ce) begin
g_fast <= i_valid && (occ_total == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam [2:0] M = 3'd3;  // samples counted by the run counter
   localparam [1:0] G = 2'd2;  // K - M: steps counted by the hold-off stage

    reg       samp     = 1'b0;  // last accepted raw sample
   reg [2:0] cnt      = 3'd0;  // stability run counter, saturates at M
   reg       stable_f = 1'b0;  // decoded "full K-sample count elapsed" flag
   reg [1:0] hold     = 2'd0;  // tail of the count: the K - M steps past cnt's top
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw != samp) begin
                // sample changed: restart the stability count
                samp     <= i_raw;
                cnt      <= 3'd0;
               hold     <= 2'd0;
                stable_f <= 1'b0;
cmt_pend <= 1'b0;          // an in-flight commit is aborted
end else begin
   if (cnt != M) begin
       cnt <= cnt + 3'd1;         // the first M identical samples
   end else if (hold != G) begin
       hold <= hold + 2'd1;       // the tail of the count runs here
       if (hold == G - 2'd1) begin
           // stage the commit; the flag and output move one step later
           cmt_pend <= 1'b1;
           cmt_val  <= samp;
       end
   end
    if (cmt_pend) begin
        o_clean  <= cmt_val;   // commit the debounced value
        stable_f <= 1'b1;
        cmt_pend <= 1'b0;
    end
            end
// cnt == M and hold == G with nothing staged: saturated, everything holds

            if (i_disarm)
                armed <= 1'b0;
            else if (i_arm)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

// Histogram accumulator: four bin counters, one sample at a time,
// plus a running total-samples register and a shadow register that
// records the bin-0 count observed at the most recent bin-1 sample.
module histo_precedence (
    input  wire       clk,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire [1:0] i_bin,     // which bin the incoming sample lands in
    output wire [5:0] o_total,
output wire [3:0] o_snap,
output reg  [3:0] o_act
);
    // bin counters
    reg [3:0] b0, b1, b2, b3;
    // total samples accumulated
    reg [5:0] total;
    // shadow register: value of bin 0 at the time of the last bin-1 sample
    reg [3:0] snap;
   // snapshot delivery pipeline: the bin-0 population read out alongside a
   // bin-1 sample only reaches the shadow register four cycles later, which
   // matches the read latency of the bin storage array.
   reg [3:0] sn1, sn2, sn3, sn4;
   reg       v1, v2, v3, v4;
reg [3:0] ce_hist;

    initial b0    = 4'd0;
    initial b1    = 4'd0;
    initial b2    = 4'd0;
    initial b3    = 4'd0;
    initial total = 6'd0;
    initial snap  = 4'd0;
   initial sn1   = 4'd0;
   initial sn2   = 4'd0;
   initial sn3   = 4'd0;
   initial sn4   = 4'd0;
   initial v1    = 1'b0;
   initial v2    = 1'b0;
   initial v3    = 1'b0;
   initial v4    = 1'b0;
initial ce_hist = 4'd0;
initial o_act   = 4'd0;

    // value currently held by the selected bin
    wire [3:0] sel_val = (i_bin == 2'd0) ? b0 :
                         (i_bin == 2'd1) ? b1 :
                         (i_bin == 2'd2) ? b2 : b3;

    // a sample is committed only if the selected bin has headroom
    wire incr = i_ce && (sel_val != 4'd15);

    always @(posedge clk) begin
        if (incr) begin
            case (i_bin)
                2'd0: b0 <= b0 + 4'd1;
                2'd1: b1 <= b1 + 4'd1;
                2'd2: b2 <= b2 + 4'd1;
                2'd3: b3 <= b3 + 4'd1;
            endcase
            total <= total + 6'd1;
        end
    end
   // Snapshot pipeline: the read data shifts on every enabled cycle and the
   // valid bit travels with it, so the shadow register is loaded four cycles
   // after the bin-1 sample that requested the snapshot.
   always @(posedge clk) begin
       if (i_ce) begin
           sn1 <= b0;
           v1  <= incr && (i_bin == 2'd1);
           sn2 <= sn1;
           v2  <= v1;
           sn3 <= sn2;
           v3  <= v2;
           sn4 <= sn3;
           v4  <= v3;
           if (v4)
               snap <= sn4;
       end
   end

  // Activity monitor: a shift register of "sample landed in bin 3" flags,
  // mixed with the current bin index for a cheap activity signature.
  always @(posedge clk) begin
      if (i_ce) begin
          ce_hist <= {ce_hist[2:0], (i_bin == 2'd3)};
          o_act   <= ce_hist ^ {2'b00, i_bin};
      end
  end

    assign o_total = total;
    assign o_snap  = snap;

    // Property (precedence): whenever a sample is being committed, the
    // bin-0 population recorded earlier in the shadow register must already
    // have been accounted for in the total-samples register.
    always @(posedge clk)
        if (incr)
            assert (total >= {2'b00, snap});
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
               steps <= steps + 3'd1;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                       steps   <= steps + 3'd1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                       steps     <= steps + 3'd1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
                       steps <= steps + 3'd1;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

module cdc_gray_sync (
    input  wire       clk,
    input  wire       i_ce,      // destination-domain clock enable: low = whole path idles
    output wire [3:0] o_bin,     // decoded pointer visible to the consumer
    output wire       o_settled  // no sample in flight
);
    // source-side binary counter and its gray-coded shadow
    reg [3:0] cnt;
    reg [3:0] g;
    // anticipated carry out of the low half of cnt, registered a cycle early
    // so the wrap term never ripples across all four counter bits
    reg lo_tc;
    // two-flop synchronizer carrying the gray pointer into the other domain
// first stage is split in two: the low pair re-samples on every enabled
// cycle, the upper pair only while armed, because the upper gray bits can
// only move on the cycle after the low half of the counter wraps, so the
// wide upper flops need not toggle their sample the rest of the time
reg [1:0] s1_lo;
reg [1:0] s1_hi;
reg       hi_arm;   // upper-pair re-sample window
wire [3:0] s1 = {s1_hi, s1_lo};
    reg [3:0] s2;

    initial begin
        cnt = 4'd0;
        g   = 4'd0;
s1_lo  = 2'd0;
s1_hi  = 2'd0;
hi_arm = 1'b0;
        s2  = 4'd0;
        lo_tc = 1'b0;
    end

    wire [1:0] nxt_lo   = cnt[1:0] + 2'd1;
    wire [1:0] nxt_hi   = cnt[3:2] + {1'b0, lo_tc};
    wire [3:0] nxt      = {nxt_hi, nxt_lo};
    wire [3:0] nxt_gray = nxt ^ (nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            cnt <= nxt;
            lo_tc <= (cnt[1:0] == 2'd2);
            g   <= nxt_gray;
s1_lo <= g[1:0];
if (hi_arm)
    s1_hi <= g[3:2];
hi_arm <= lo_tc;
            s2  <= s1;
        end
    end

    // gray -> binary decode of the settled sample
    wire [3:0] dec;
    assign dec[3] = s2[3];
    assign dec[2] = dec[3] ^ s2[2];
    assign dec[1] = dec[2] ^ s2[1];
    assign dec[0] = dec[1] ^ s2[0];
    assign o_bin  = dec;

    wire [3:0] diff = s1 ^ s2;
    assign o_settled = (diff == 4'd0);

    // P: whenever the two synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (s1 != s2)
            assert (((diff) & (diff - 4'd1)) == 4'd0);
endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable: low means the unit idles
    input  wire       issue,     // new op handed to the fixed-latency unit
    output wire       o_retire,  // op leaving the last pipe stage
output wire [2:0] o_inflight,
output reg  [3:0] o_issue_hist,
output reg  [3:0] o_act_cnt
);
    // fixed-latency (4 cycle) pipeline occupancy shift register
    reg [3:0] pipe;
    // running count of operations currently inside the pipeline
    reg [2:0] inflight;
    // sticky arm: set the first time an issue is actually accepted
    reg       armed;
// distractor: history of raw issue requests (not tied to occupancy)
reg [3:0] req_hist;
// distractor: raw retire-pulse accumulator, unrelated to occupancy
reg [3:0] ce_cnt;

    initial pipe     = 4'b0000;
    initial inflight = 3'd0;
    initial armed    = 1'b0;
initial req_hist     = 4'b0000;
initial o_issue_hist = 4'b0000;
initial ce_cnt       = 4'b0000;
initial o_act_cnt    = 4'b0000;

    wire retire = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe     <= 4'b0000;
            inflight <= 3'd0;
req_hist     <= 4'b0000;
o_issue_hist <= 4'b0000;
ce_cnt       <= 4'b0000;
o_act_cnt    <= 4'b0000;
        end else if (i_ce) begin
            pipe     <= {pipe[2:0], issue};
            inflight <= inflight + {2'b00, issue} - {2'b00, retire};
req_hist     <= {req_hist[2:0], issue};
o_issue_hist <= req_hist ^ {3'b000, issue};
ce_cnt       <= ce_cnt + {3'b000, retire};
o_act_cnt    <= ce_cnt ^ {3'b000, issue};
        end
    end

    always @(posedge clk) begin
        if (i_ce && issue)
            armed <= 1'b1;
    end

    assign o_retire   = retire;
    assign o_inflight = inflight;

    // P: once the unit has ever issued, occupancy never exceeds the 4 pipe
    // stages, even though the counter is 3 bits wide (could hold up to 7).
    assert property (!armed || inflight <= 3'd4);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       q_pend   = 1'b0;  // queued commit sitting behind the head slot
reg       q_val    = 1'b0;  // sample value waiting in the queued slot
reg       q_ch     = 1'b0;  // which channel owns the queued slot
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

// Two commit slots were budgeted (a head that retires and one queued tail);
// the channels arbitrate for a free slot, the raw-sample channel wins a tie.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
wire q_full  = cmt_pend && q_pend;
wire grant_a = !q_full && a_req;
wire grant_b = !q_full && b_req && !a_req;
wire grant   = grant_a || grant_b;
wire new_val = grant_a ? samp : samp_b;
wire new_ch  = grant_a ? CH_A : CH_B;
// a queued raw-sample commit is stale the moment the sample moves again
wire keep_q  = q_pend && !(q_ch == CH_A && a_chg);

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
// take a commit slot; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
               end
// both slots busy: hold at K-1 and retry once one frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
               end
           end

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
               if (cmt_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= cmt_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= cmt_val;
               end
// the head always retires: the queued tail shifts up and a fresh
// grant lands in whichever slot is left over
cmt_pend <= keep_q || grant;
cmt_val  <= keep_q ? q_val : new_val;
cmt_ch   <= keep_q ? q_ch  : new_ch;
q_pend   <= keep_q && grant;
q_val    <= new_val;
q_ch     <= new_ch;
           end
else begin
cmt_pend <= grant;
cmt_val  <= new_val;
cmt_ch   <= new_ch;
q_pend   <= 1'b0;
end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;
  // legs of the walk currently in flight.  steps is a status field read by
  // the host, so it is written once per handshake instead of once per leg:
  // the decoder parks intermediate legs here and the terminating leg flushes
  // the whole batch into steps in a single update.
  reg [1:0] credit;
  initial   credit = 2'd0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
           credit    <= 2'd0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
               steps  <= steps + {1'b0, credit} + 3'd1;
               credit <= 2'd0;
            end else begin
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
                       credit  <= credit + 2'd1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
                       credit    <= credit + 2'd1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
                      steps  <= steps + {1'b0, credit} + 3'd1;
                      credit <= 2'd0;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

module skid_cred_stage (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_valid,
    input  wire [7:0] i_cred,
    input  wire       i_ready,
    output wire       o_valid,
    output wire [7:0] o_cred,
    output wire       o_upstream_ready,
    output wire       g_bypass,
output wire       g_holdoff,
output reg  [3:0] o_dbg_count
);
    // ---- main pipeline register (vendor/credential record) ----
    reg        m_valid;
    reg [7:0]  m_cred;

    // ---- skid buffer: s_cred is only meaningful while the stall flag is up ----
    reg        hold;      // stall flag
    reg [7:0]  s_cred;

// ---- per-slot occupancy accounting, kept in parallel with the valid bits ----
    reg [1:0]  occ;
   reg [1:0]  p_occ;   // priority-class share of the main slot (i_cred[7] set)
reg [1:0]  s_occ;

    // ---- downstream arbitration grants ----
    reg        g_fast;    // bypass grant: record admitted into an empty stage
    reg        g_hld;     // hold-off grant: skid full, upstream must wait

    // ---- sticky arm + past-valid ----
    reg        armed;
    reg        pv;
reg  [3:0] dbg_prev;

    initial begin
        m_valid = 1'b0;
        m_cred  = 8'h00;
        hold    = 1'b0;
        s_cred  = 8'h00;
        occ     = 2'd0;
       p_occ   = 2'd0;
s_occ   = 2'd0;
        g_fast  = 1'b0;
        g_hld   = 1'b0;
        armed   = 1'b0;
        pv      = 1'b0;
o_dbg_count = 4'd0;
dbg_prev    = 4'd0;
    end

wire       skid_free  = (s_occ == 2'd0);
wire       load_skid  = i_ce && i_valid && !hold && m_valid && !i_ready && skid_free;
wire       fill_main  = i_ce && i_valid && !m_valid;
wire       drain_main = i_ce && m_valid && i_ready && !hold && !i_valid;
wire       drain_skid = i_ce && hold && i_ready;
// a fresh input record takes the main slot next cycle
wire       main_wr_new  = fill_main || (i_ce && i_valid && m_valid && i_ready && !hold);
// the parked record is promoted out of the skid slot into the main slot
wire       main_wr_skid = i_ce && m_valid && i_ready && hold;
// total records resident in the stage (main slot + skid slot)
wire [1:0] occ_total  = occ + p_occ + s_occ;

    // ---- skid-buffered valid/ready stage ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            m_valid <= 1'b0;
            m_cred  <= 8'h00;
            hold    <= 1'b0;
            s_cred  <= 8'h00;
        end else if (i_ce) begin
            if (m_valid && i_ready) begin
                if (hold) begin
                    m_cred  <= s_cred;
                    m_valid <= 1'b1;
                    hold    <= 1'b0;
                end else if (i_valid) begin
                    m_cred  <= i_cred;
                    m_valid <= 1'b1;
                end else begin
                    m_valid <= 1'b0;
                end
            end else if (!m_valid) begin
                if (i_valid) begin
                    m_valid <= 1'b1;
                    m_cred  <= i_cred;
                end
            end else begin
if (i_valid && !hold && skid_free) begin
                    hold   <= 1'b1;
                    s_cred <= i_cred;
                end
            end
        end
    end

// ---- main-slot occupancy counter ----
   // normal-class records only; the priority-class share lives in p_occ
    always @(posedge i_clk) begin
        if (i_reset)
            occ <= 2'd0;
        else if (i_ce) begin
           if (main_wr_new)
               occ <= {1'b0, ~i_cred[7]};
           else if (main_wr_skid)
               occ <= {1'b0, ~s_cred[7]};
           else if (drain_main)
               occ <= 2'd0;
        end
    end

   // ---- main-slot occupancy counter, priority-class share ----
   always @(posedge i_clk) begin
       if (i_reset)
           p_occ <= 2'd0;
       else if (i_ce) begin
           if (main_wr_new)
               p_occ <= {1'b0, i_cred[7]};
           else if (main_wr_skid)
               p_occ <= {1'b0, s_cred[7]};
           else if (drain_main)
               p_occ <= 2'd0;
       end
   end

// ---- skid-slot occupancy counter ----
always @(posedge i_clk) begin
    if (i_reset)
        s_occ <= 2'd0;
    else if (i_ce) begin
        if (load_skid)
            s_occ <= s_occ + 2'd1;
        else if (drain_skid)
            s_occ <= s_occ - 2'd1;
    end
end

    // ---- grant registers ----
    always @(posedge i_clk) begin
        if (i_reset) begin
            g_fast <= 1'b0;
            g_hld  <= 1'b0;
dbg_prev    <= 4'd0;
o_dbg_count <= 4'd0;
        end else if (i_ce) begin
g_fast <= i_valid && (occ_total == 2'd0);
            g_hld  <= i_valid && m_valid && hold;
dbg_prev    <= dbg_prev + {3'b000, (i_valid && i_ready)};
o_dbg_count <= dbg_prev ^ {3'b000, hold};
        end
    end

    // ---- sticky arm: first time a record is parked in the skid buffer ----
    always @(posedge i_clk)
        armed <= armed | load_skid;

    always @(posedge i_clk)
        pv <= 1'b1;

    assign o_valid          = m_valid;
    assign o_cred           = m_cred;
assign o_upstream_ready = !hold && skid_free;
    assign g_bypass         = g_fast;
    assign g_holdoff        = g_hld;

    // ---- P: once armed, the two grants are never asserted together ----
    always @(posedge i_clk)
        if (pv && armed && $rose(g_hld))
            assert (!g_fast);

endmodule

// Gray-coded pointer crossing a two-flop synchronizer.  The destination
// domain decodes which single bit of the sampled pointer toggled and uses
// those toggles to walk a three-step chain: arm, then start, then finish.
module cdc_gray_chain (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    output wire [1:0] o_stage,
    output wire       o_done
);
    localparam [1:0] S_IDLE    = 2'd0,
                     S_ARMED   = 2'd1,
                     S_STARTED = 2'd2,
                     S_FINISH  = 2'd3;

    // source-domain binary counter and its gray encoding
    reg [2:0] bin;
    initial   bin = 3'd0;

    // two-flop synchronizer in the destination domain
    reg [2:0] sync1;
    initial   sync1 = 3'b000;
    reg [2:0] sync2;
    initial   sync2 = 3'b000;

   // destination-side retiming pipeline: the event decoder sits far from the
   // synchronizer in the floorplan, so the sampled pointer is retimed four
   // times before it is decoded, and both decode operands are taken from
   // the last two taps of this pipeline so they share the same route delay
   reg [2:0] ret1;
   initial   ret1 = 3'b000;
   reg [2:0] ret2;
   initial   ret2 = 3'b000;
   reg [2:0] ret3;
   initial   ret3 = 3'b000;
   reg [2:0] ret4;
   initial   ret4 = 3'b000;

    // chain state machine plus its history bits
    reg [1:0] stage;
    initial   stage = S_IDLE;
    reg       saw_arm;
    initial   saw_arm = 1'b0;
    reg       saw_start;
    initial   saw_start = 1'b0;
   // number of chain transitions actually taken.  A corrupt handshake aborts
   // straight to FINISH, so the transition count is what tells a full walk
   // of the chain apart from an aborted one.
   reg [2:0] steps;
   initial   steps = 3'd0;
  // legs of the walk currently in flight.  steps is a status field read by
  // the host, so it is written once per handshake instead of once per leg:
  // the decoder parks intermediate legs here and the terminating leg flushes
  // the whole batch into steps in a single update.
  reg [1:0] credit;
  initial   credit = 2'd0;
// the leg adder is retimed one stage: a freshly decoded leg parks in leg_q
// and merges into credit on the next enabled cycle, so the terminating leg
// has to flush both halves of the pending batch into steps at once
reg       leg_q;
initial   leg_q = 1'b0;

    wire [2:0] gray  = bin ^ (bin >> 1);
   wire [2:0] delta = ret3 ^ ret4;

    // which single pointer bit moved between the two samples
    wire arm_ev   = (delta == 3'b001);
    wire start_ev = (delta == 3'b010);
    wire fin_ev   = (delta == 3'b100);

    // a sample pair that changed in more than one bit: impossible for a gray
    // pointer, treated here as a corrupt handshake that aborts to FINISH
    wire bad_ev = !((delta == 3'b000) || arm_ev || start_ev || fin_ev);

    always @(posedge i_clk) begin
        if (i_rst) begin
            bin       <= 3'd0;
            sync1     <= 3'b000;
            sync2     <= 3'b000;
           ret1      <= 3'b000;
           ret2      <= 3'b000;
           ret3      <= 3'b000;
           ret4      <= 3'b000;
            stage     <= S_IDLE;
            saw_arm   <= 1'b0;
            saw_start <= 1'b0;
           steps     <= 3'd0;
           credit    <= 2'd0;
leg_q     <= 1'b0;
        end else if (i_ce) begin
            bin   <= bin + 3'd1;
            sync1 <= gray;
            sync2 <= sync1;
           ret1  <= sync2;
           ret2  <= ret1;
           ret3  <= ret2;
           ret4  <= ret3;

            if (bad_ev) begin
                stage <= S_FINISH;
steps  <= steps + {1'b0, credit} + {2'b0, leg_q} + 3'd1;
               credit <= 2'd0;
leg_q  <= 1'b0;
            end else begin
credit <= credit + {1'b0, leg_q};
leg_q  <= 1'b0;
                case (stage)
                S_IDLE:
                    if (arm_ev) begin
                        stage   <= S_ARMED;
                        saw_arm <= 1'b1;
leg_q   <= 1'b1;
                    end
                S_ARMED:
                    if (start_ev) begin
                        stage     <= S_STARTED;
                        saw_start <= 1'b1;
leg_q     <= 1'b1;
                    end
                S_STARTED:
                   if (fin_ev) begin
                       stage <= S_FINISH;
steps  <= steps + {1'b0, credit} + {2'b0, leg_q} + 3'd1;
                      credit <= 2'd0;
leg_q  <= 1'b0;
                   end
                default: ;
                endcase
            end
        end
    end

    assign o_stage = stage;
   assign o_done  = (stage == S_FINISH) && (steps == 3'd3);

    // chain precedence: finishing is only ever observed after arm and start
    always @(posedge i_clk)
        if (stage == S_FINISH)
            assert (saw_arm && saw_start);
   // an abort reaches FINISH without walking the chain, so a FINISH that the
   // done output is allowed to honour must show all three transitions counted
   always @(posedge i_clk)
       if (stage == S_FINISH)
           assert (steps == 3'd3);
endmodule

module sample_debouncer (
    input  wire clk,
    input  wire i_ce,      // step enable: low means the debouncer idles
    input  wire i_raw,     // noisy input sample
    input  wire i_arm,     // Q: start the monitoring window
    input  wire i_disarm,  // R: close the window (may never arrive)
    output reg  o_clean
);
    // K identical consecutive samples are required before o_clean flips.
    localparam [2:0] K = 3'd5;
   localparam       CH_A = 1'b0;  // commit-stage owner encoding
   localparam       CH_B = 1'b1;

    reg       samp     = 1'b0;  // last accepted raw sample
    reg [2:0] cnt      = 3'd0;  // stability counter, saturates at K
    reg       stable_f = 1'b0;  // decoded "counter has reached K" flag
reg       cmt_pend = 1'b0;  // commit staged, retires on the next enabled step
reg       cmt_val  = 1'b0;  // sample value waiting in the commit stage
reg       cmt_ch   = 1'b0;  // which channel owns the commit stage
reg       q_pend   = 1'b0;  // queued commit sitting behind the head slot
reg       q_val    = 1'b0;  // sample value waiting in the queued slot
reg       q_ch     = 1'b0;  // which channel owns the queued slot
reg       wb_pend  = 1'b0;  // writeback slot: entry retired by the head
reg       wb_val   = 1'b0;  // sample value being applied this step
reg       wb_ch    = 1'b0;  // which channel owns the writeback slot
reg       samp_b   = 1'b0;  // last accepted arm-button sample
reg [2:0] cnt_b    = 3'd0;  // arm-button stability counter, saturates at K
reg       arm_clean = 1'b0; // debounced arm-button level
    reg       armed    = 1'b0;  // window register: set by Q, cleared by R
    reg       pv       = 1'b0;  // past-valid

// Two commit slots were budgeted (a head that retires and one queued tail);
// the channels arbitrate for a free slot, the raw-sample channel wins a tie.
   wire a_chg   = (i_raw != samp);
   wire b_chg   = (i_arm != samp_b);
   wire a_req   = !a_chg && (cnt   == K - 3'd1);
   wire b_req   = !b_chg && (cnt_b == K - 3'd1);
wire q_full  = cmt_pend && q_pend;
wire grant_a = !q_full && a_req;
wire grant_b = !q_full && b_req && !a_req;
wire grant   = grant_a || grant_b;
wire new_val = grant_a ? samp : samp_b;
wire new_ch  = grant_a ? CH_A : CH_B;
// a queued raw-sample commit is stale the moment the sample moves again
wire keep_q  = q_pend && !(q_ch == CH_A && a_chg);

    initial o_clean = 1'b0;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
           // ---- channel A: the raw sample ----
           if (a_chg) begin
               // sample changed: restart the stability count
               samp     <= i_raw;
               cnt      <= 3'd0;
               stable_f <= 1'b0;
           end else if (cnt != K) begin
               if (!a_req) begin
                   cnt <= cnt + 3'd1;
               end else if (grant_a) begin
// take a commit slot; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
               end
// both slots busy: hold at K-1 and retry once one frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
               end
           end
           // ---- writeback slot: applies the entry retired one step ago ----
           if (wb_pend) begin
               if (wb_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= wb_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= wb_val;
               end
           end
           // the head hands its entry to the writeback slot; an entry whose
           // sample moved again in the meantime is dropped instead
           wb_pend <= cmt_pend && !(cmt_ch == CH_A && a_chg)
                               && !(cmt_ch == CH_B && b_chg);
           wb_val  <= cmt_val;
           wb_ch   <= cmt_ch;

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
// the head always retires: the queued tail shifts up and a fresh
// grant lands in whichever slot is left over
cmt_pend <= keep_q || grant;
cmt_val  <= keep_q ? q_val : new_val;
cmt_ch   <= keep_q ? q_ch  : new_ch;
q_pend   <= keep_q && grant;
q_val    <= new_val;
q_ch     <= new_ch;
           end
else begin
cmt_pend <= grant;
cmt_val  <= new_val;
cmt_ch   <= new_ch;
q_pend   <= 1'b0;
end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

