// take a commit slot; the flag and output move one step later
                   cnt      <= cnt + 3'd1;
               end
// both slots busy: hold at K-1 and retry once one frees
           end

           // ---- channel B: the arm button, same filter, same stage ----
           if (b_chg) begin
               samp_b <= i_arm;
               cnt_b  <= 3'd0;
           end else if (cnt_b != K) begin
               if (!b_req) begin
                   cnt_b <= cnt_b + 3'd1;
               end else if (grant_b) begin
                   cnt_b    <= cnt_b + 3'd1;
               end
           end
// ---- writeback slot: applies the entry the retire pipe handed over ----
           if (wb_pend) begin
               if (wb_ch == CH_A) begin
                   if (!a_chg) begin
                       o_clean  <= wb_val;   // commit the debounced value
                       stable_f <= 1'b1;
                   end
               end else if (!b_chg) begin
                   arm_clean <= wb_val;
               end
           end
// the head hands its entry to the retire pipe; the apply path is
// registered four deep to keep the commit fanout off the counter
// logic, and every stage re-checks its own channel so an entry whose
// sample moved again while in flight is dropped where it stands
s1_pend <= cmt_pend && !(cmt_ch == CH_A && a_chg)
                    && !(cmt_ch == CH_B && b_chg);
s1_val  <= cmt_val;
s1_ch   <= cmt_ch;
s2_pend <= s1_pend && !(s1_ch == CH_A && a_chg)
                   && !(s1_ch == CH_B && b_chg);
s2_val  <= s1_val;
s2_ch   <= s1_ch;
s3_pend <= s2_pend && !(s2_ch == CH_A && a_chg)
                   && !(s2_ch == CH_B && b_chg);
s3_val  <= s2_val;
s3_ch   <= s2_ch;
s4_pend <= s3_pend && !(s3_ch == CH_A && a_chg)
                   && !(s3_ch == CH_B && b_chg);
s4_val  <= s3_val;
s4_ch   <= s3_ch;
wb_pend <= s4_pend && !(s4_ch == CH_A && a_chg)
                   && !(s4_ch == CH_B && b_chg);
wb_val  <= s4_val;
wb_ch   <= s4_ch;

           // ---- shared stage: retires one entry per enabled step ----
           if (cmt_pend) begin
// the head always retires: the queued tail shifts up and a fresh
// grant lands in whichever slot is left over
cmt_pend <= keep_q || grant;
cmt_val  <= keep_q ? q_val : new_val;
cmt_ch   <= keep_q ? q_ch  : new_ch;
q_pend   <= keep_q && grant;
q_val    <= new_val;
q_ch     <= new_ch;
           end
else begin
cmt_pend <= grant;
cmt_val  <= new_val;
cmt_ch   <= new_ch;
q_pend   <= 1'b0;
end

            if (i_disarm)
                armed <= 1'b0;
           else if (arm_clean)
                armed <= 1'b1;
        end
    end

    // Universality inside the armed window, stated about the previous cycle:
    // whenever the stability flag was set, the counter had already run up.
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(stable_f) || $past(cnt) >= 3'd3);
endmodule

module dfe_ss_lms (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_mu_wr,
    input  wire [63:0] i_mu,
    input  wire        i_dec,
    input  wire        i_err_sgn,
    output wire [63:0] o_tap0,
    output wire [63:0] o_tap1,
    output wire        o_done
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_ADAPT = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;
    localparam [63:0] N_UPD  = 64'd4;

    reg [63:0] coef0 = 64'd0;
    reg [63:0] coef1 = 64'd0;
    reg [63:0] mu = 64'd1;
    reg [63:0] upd_cnt = 64'd0;
    reg [1:0]  hist = 2'b00;
    reg [1:0]  hist_cnt = 2'd0;
    reg [1:0]  phase = P_IDLE;
    reg        arm_seen = 1'b0;
    reg        start_seen = 1'b0;
    reg        q_seen = 1'b0;

    // sign-sign LMS step: +mu when error sign matches decided bit sign, else -mu
    wire [63:0] d0 = (i_err_sgn ^ hist[0]) ? (~mu + 64'd1) : mu;
    wire [63:0] d1 = (i_err_sgn ^ hist[1]) ? (~mu + 64'd1) : mu;

    always @(posedge clk) begin
        if (rst) begin
            coef0 <= 64'd0;
            coef1 <= 64'd0;
            hist <= 2'b00;
            hist_cnt <= 2'd0;
            upd_cnt <= 64'd0;
            phase <= P_IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
        end else if (i_ce) begin
            if (i_mu_wr) begin
                mu <= i_mu;
                q_seen <= 1'b1;
            end
            hist <= {hist[0], i_dec};
            if (hist_cnt != 2'd2)
                hist_cnt <= hist_cnt + 2'd1;
            case (phase)
                P_IDLE: begin
                    if (hist_cnt == 2'd2) begin
                        phase <= P_ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                P_ARMED: begin
                    coef0 <= coef0 + d0;
                    coef1 <= coef1 + d1;
                    upd_cnt <= 64'd1;
                    phase <= P_ADAPT;
                    start_seen <= 1'b1;
                end
                P_ADAPT: begin
                    coef0 <= coef0 + d0;
                    coef1 <= coef1 + d1;
                    upd_cnt <= upd_cnt + 64'd1;
                    if (upd_cnt == N_UPD - 64'd1)
                        phase <= P_DONE;
                end
                default: ;
            endcase
        end
    end

    assign o_tap0 = coef0;
    assign o_tap1 = coef1;
    assign o_done = (phase == P_DONE);

    always @(posedge clk)
        if (q_seen && phase == P_DONE)
            assert (arm_seen && start_seen);
endmodule

module ws2812_encoder (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [23:0] color,
    output reg         dout,
    output wire        busy_o,
    output wire        ready
);
    localparam [31:0] T_BIT   = 32'd4;
    localparam [31:0] T_HI0   = 32'd1;
    localparam [31:0] T_HI1   = 32'd3;
    localparam [31:0] T_RESET = 32'd8;
    localparam [31:0] N_BITS  = 32'd24;
    localparam [31:0] K       = 32'd104;

    reg        busy        = 1'b0;
    reg        in_reset    = 1'b0;
    reg [31:0] shift       = 32'd0;
    reg [31:0] bit_cnt     = 32'd0;
    reg [31:0] pulse_timer = 32'd0;
    reg [31:0] gap_cnt     = 32'd0;
    reg [31:0] deadline    = 32'd0;

    assign busy_o = busy;
    assign ready  = !busy;

    always @(*) begin
        dout = busy && !in_reset && (pulse_timer < (shift[23] ? T_HI1 : T_HI0));
    end

    always @(posedge clk) begin
        if (rst) begin
            busy        <= 1'b0;
            in_reset    <= 1'b0;
            shift       <= 32'd0;
            bit_cnt     <= 32'd0;
            pulse_timer <= 32'd0;
            gap_cnt     <= 32'd0;
            deadline    <= 32'd0;
        end else if (ce) begin
            if (!busy) begin
                if (start) begin
                    busy        <= 1'b1;
                    in_reset    <= 1'b0;
                    shift       <= {8'd0, color};
                    bit_cnt     <= N_BITS;
                    pulse_timer <= 32'd0;
                    gap_cnt     <= 32'd0;
                    deadline    <= K;
                end
            end else begin
                deadline <= deadline - 32'd1;
                if (!in_reset) begin
                    if (pulse_timer == T_BIT - 32'd1) begin
                        pulse_timer <= 32'd0;
                        shift       <= shift << 1;
                        if (bit_cnt == 32'd1) begin
                            bit_cnt  <= 32'd0;
                            in_reset <= 1'b1;
                            gap_cnt  <= T_RESET;
                        end else begin
                            bit_cnt <= bit_cnt - 32'd1;
                        end
                    end else begin
                        pulse_timer <= pulse_timer + 32'd1;
                    end
                end else begin
                    if (gap_cnt == 32'd1) begin
                        gap_cnt  <= 32'd0;
                        in_reset <= 1'b0;
                        busy     <= 1'b0;
                    end else begin
                        gap_cnt <= gap_cnt - 32'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (busy)
            assert (deadline != 32'd0);
endmodule

module polar_sc_result_dec (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire abort,
    input wire wr,
    input wire [2:0] wr_addr,
    input wire [127:0] llr_in,
    output wire [7:0] o_result,
    output wire o_done
);
    localparam [7:0] FROZEN = 8'b0001_0111;
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, DECODE = 2'd2, DONE = 2'd3;

    reg [127:0] llr_mem [0:7];
    reg [7:0] ps;
    reg [7:0] dec;
    reg [2:0] leaf_idx;
    reg [1:0] phase;
    reg armed_seen;
    reg started_seen;
    reg pre_abort;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) llr_mem[i] = 128'd0;
        ps = 8'd0;
        dec = 8'd0;
        leaf_idx = 3'd0;
        phase = IDLE;
        armed_seen = 1'b0;
        started_seen = 1'b0;
        pre_abort = 1'b1;
    end

    wire [127:0] cur_word = llr_mem[leaf_idx];
    wire [7:0] la = cur_word[7:0];
    wire [7:0] lb = cur_word[15:8];
    wire [6:0] min_mag = (la[6:0] < lb[6:0]) ? la[6:0] : lb[6:0];
    wire [7:0] f_llr = {la[7] ^ lb[7], min_mag};
    wire [2:0] prev_idx = leaf_idx - 3'd1;
    wire u_prev = ps[prev_idx];
    wire [7:0] g_llr = u_prev ? (lb - la) : (lb + la);
    wire [7:0] leaf_llr = leaf_idx[0] ? g_llr : f_llr;
    wire bit_hat = FROZEN[leaf_idx] ? 1'b0 : leaf_llr[7];

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_abort <= 1'b1;
            leaf_idx <= 3'd0;
            ps <= 8'd0;
            dec <= 8'd0;
        end else if (en) begin
            if (wr && phase != DECODE)
                llr_mem[wr_addr] <= llr_in;
            if (abort) begin
                phase <= IDLE;
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm) begin
                            phase <= ARMED;
                            armed_seen <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (start) begin
                            phase <= DECODE;
                            started_seen <= 1'b1;
                            leaf_idx <= 3'd0;
                            ps <= 8'd0;
                        end
                    end
                    DECODE: begin
                        dec[leaf_idx] <= bit_hat;
                        ps[leaf_idx] <= bit_hat;
                        llr_mem[leaf_idx] <= {cur_word[127:16], f_llr, g_llr};
                        leaf_idx <= leaf_idx + 3'd1;
                        if (leaf_idx == 3'd7)
                            phase <= DONE;
                    end
                    DONE: begin
                        if (arm) begin
                            phase <= ARMED;
                            started_seen <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_result = dec;
    assign o_done = (phase == DONE);

    always @(posedge clk)
        if (pre_abort && phase == 2'd3)
            assert (started_seen && armed_seen);
endmodule

module vend_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       coin_valid,
    input  wire [7:0] coin_val,
    input  wire       select,
    input  wire       cancel,
    output wire       vend,
    output wire       change_ret,
    output wire [7:0] change_out
);
    localparam [1:0] S_IDLE    = 2'd0;
    localparam [1:0] S_COLLECT = 2'd1;
    localparam [1:0] S_VEND    = 2'd2;
    localparam [1:0] S_CHANGE  = 2'd3;
    localparam [7:0] PRICE     = 8'd75;

    reg [1:0] state;
    reg [7:0] credit;
    reg [7:0] change_amt;
    reg       vend_r;
    reg       chg_r;
    reg       pv;
    initial begin
        state = S_IDLE; credit = 8'd0; change_amt = 8'd0;
        vend_r = 1'b0; chg_r = 1'b0; pv = 1'b0;
    end

    wire [8:0] sum     = {1'b0, credit} + {1'b0, coin_val};
    wire [7:0] sat_sum = sum[8] ? 8'd255 : sum[7:0];

    assign vend       = vend_r;
    assign change_ret = chg_r;
    assign change_out = change_amt;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; credit <= 8'd0; change_amt <= 8'd0;
            vend_r <= 1'b0; chg_r <= 1'b0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (coin_valid) begin
                        credit <= sat_sum;
                        state  <= S_COLLECT;
                    end
                end
                S_COLLECT: begin
                    if (select && credit >= PRICE) begin
                        credit <= credit - PRICE;
                        state  <= S_VEND;
                        vend_r <= 1'b1;
                    end else if (cancel) begin
                        change_amt <= credit;
                        credit     <= 8'd0;
                        state      <= S_CHANGE;
                        chg_r      <= 1'b1;
                    end else if (coin_valid) begin
                        credit <= sat_sum;
                    end
                end
                S_VEND: begin
                    vend_r <= 1'b0;
                    if (credit != 8'd0) begin
                        change_amt <= credit;
                        credit     <= 8'd0;
                        state      <= S_CHANGE;
                        chg_r      <= 1'b1;
                    end else begin
                        state <= S_IDLE;
                    end
                end
                S_CHANGE: begin
                    chg_r      <= 1'b0;
                    change_amt <= 8'd0;
                    state      <= S_IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && $rose(vend_r))
            assert (!chg_r);
endmodule

module bfi_chain (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_load,
    input wire i_abort,
    input wire [63:0] i_dest,
    input wire [63:0] i_field,
    input wire [5:0] i_off,
    input wire [6:0] i_len,
    output wire [63:0] o_result,
    output wire o_done
);
    reg [1:0] phase = 2'd0;
    reg [63:0] dest = 64'd0;
    reg [63:0] field = 64'd0;
    reg [63:0] shifted = 64'd0;
    reg [63:0] mask = 64'd0;
    reg [63:0] result = 64'd0;
    reg [5:0] off = 6'd0;
    reg [6:0] len = 7'd0;
    reg armed_seen = 1'b0;
    reg start_seen = 1'b0;
    reg done_seen = 1'b0;
    reg pre_r = 1'b1;

    wire [63:0] lowmask = (len >= 7'd64) ? {64{1'b1}} : ((64'd1 << len) - 64'd1);

    always @(posedge clk) begin
        if (i_reset) begin
            phase <= 2'd0;
            armed_seen <= 1'b0;
            start_seen <= 1'b0;
            done_seen <= 1'b0;
        end else if (i_ce) begin
            if (i_abort && (phase != 2'd0)) begin
                phase <= 2'd0;
                pre_r <= 1'b0;
            end else begin
                case (phase)
                    2'd0: if (i_load) begin
                        dest <= i_dest;
                        field <= i_field;
                        off <= i_off;
                        len <= (i_len > 7'd64) ? 7'd64 : i_len;
                        phase <= 2'd1;
                        armed_seen <= 1'b1;
                    end
                    2'd1: begin
                        shifted <= field << off;
                        mask <= lowmask << off;
                        phase <= 2'd2;
                        start_seen <= 1'b1;
                    end
                    2'd2: begin
                        result <= (dest & ~mask) | (shifted & mask);
                        phase <= 2'd3;
                        done_seen <= 1'b1;
                    end
                    default: phase <= 2'd0;
                endcase
            end
        end
    end

    assign o_result = result;
    assign o_done = (phase == 2'd3);

    always @(posedge clk)
        if (pre_r) assert (!done_seen || (start_seen && armed_seen));
endmodule

module doorbell_sweep (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        ring,
    input  wire [5:0]  ring_ch,
    input  wire        ext,
    output reg         busy,
    output reg  [7:0]  svc_cnt,
    output reg  [47:0] pending
);
    reg [5:0] idx;
    reg [7:0] deadline;
    reg       armed;
    reg       pv;
    initial begin
        pending  = 48'd0;
        busy     = 1'b0;
        idx      = 6'd0;
        deadline = 8'd0;
        armed    = 1'b1;
        svc_cnt  = 8'd0;
        pv       = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (ext) armed <= 1'b0;
            if (busy) begin
                if (pending[idx]) svc_cnt <= svc_cnt + 8'd1;
                pending[idx] <= 1'b0;
                deadline <= deadline - 8'd1 + (ext ? 8'd16 : 8'd0);
                if (idx == 6'd47) begin
                    busy <= 1'b0;
                    idx  <= 6'd0;
                end else begin
                    idx <= idx + 6'd1;
                end
            end else if (pending != 48'd0) begin
                busy     <= 1'b1;
                idx      <= 6'd0;
                deadline <= 8'd48;
            end
            if (ring && (ring_ch < 6'd48)) pending[ring_ch] <= 1'b1;
        end
    end

    always @(posedge clk)
        if (armed && busy)
            assert (deadline != 8'd0);

    always @(posedge clk)
        if (pv && armed && $past(i_ce) && $past(busy) && !busy)
            assert ($past(deadline) == 8'd1);
endmodule

module mips_wb_scoreboard (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [15:0] req_vec,
    input wire q_open,
    input wire r_close,
    output wire wb_valid,
    output reg [3:0] wb_idx
);
    reg [15:0] pend = 16'd0;
    reg busy = 1'b0;
    reg [7:0] cnt = 8'd0;
    reg win = 1'b0;

    wire [15:0] low = pend & (~pend + 16'd1);
    wire [15:0] pend_next = pend & ~low;

    reg [4:0] pc;
    integer i;
    always @(*) begin
        wb_idx = 4'd0;
        for (i = 15; i >= 0; i = i - 1)
            if (pend[i]) wb_idx = i[3:0];
    end

    integer j;
    always @(*) begin
        pc = 5'd0;
        for (j = 0; j < 16; j = j + 1)
            pc = pc + {4'd0, pend[j]};
    end

    assign wb_valid = en && busy;

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                pend <= 16'd0;
                busy <= 1'b0;
                cnt <= 8'd0;
                win <= 1'b0;
            end else begin
                if (q_open)
                    win <= 1'b1;
                else if (r_close)
                    win <= 1'b0;
                if (!busy && req && req_vec != 16'd0) begin
                    pend <= req_vec;
                    busy <= 1'b1;
                    cnt <= 8'd16;
                end else if (busy) begin
                    pend <= pend_next;
                    cnt <= cnt - 8'd1;
                    if (pend_next == 16'd0)
                        busy <= 1'b0;
                end
            end
        end
    end

    always @(*) assert (!(win && busy) || cnt != 8'd0);
endmodule

module pretrig_capture (
    input  wire        clk,
    input  wire        ce,
    input  wire        rearm,
    input  wire        trig,
    input  wire [63:0] sample,
    input  wire [5:0]  rd_idx,
    output wire [63:0] rd_data,
    output wire        is_frozen,
    output wire [63:0] captured
);
    localparam [63:0] DEPTH = 64'd48;
    reg [63:0] chain [0:47];
    reg [47:0] valid;
    reg [63:0] count;
    reg        frozen;
    reg        pv;
    integer i;

    initial begin
        for (i = 0; i < 48; i = i + 1) chain[i] = 64'd0;
        valid  = 48'd0;
        count  = 64'd0;
        frozen = 1'b0;
        pv     = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rearm) begin
            frozen <= 1'b0;
            count  <= 64'd0;
            valid  <= 48'd0;
        end else if (ce && !frozen) begin
            if (trig && count == DEPTH) begin
                frozen <= 1'b1;
            end else begin
                chain[0] <= sample;
                for (i = 1; i < 48; i = i + 1) chain[i] <= chain[i-1];
                valid <= {valid[46:0], 1'b1};
                if (count != DEPTH) count <= count + 64'd1;
            end
        end
    end

    assign rd_data   = (rd_idx < 6'd48) ? chain[rd_idx] : 64'd0;
    assign is_frozen = frozen;
    assign captured  = count;

    always @(posedge clk)
        if (pv && $rose(frozen))
            assert (valid == 48'hFFFFFFFFFFFF);
endmodule

module phase_clkgen (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        cfg_we,
    input  wire [2:0]  cfg_sel,
    input  wire [15:0] cfg_div,
    input  wire [15:0] cfg_off,
    input  wire        win_open,
    input  wire        win_close,
    output wire [7:0]  clk_out,
    output wire [7:0]  align_pulse
);
    localparam [15:0] LAP = 16'd240;

    reg [15:0]  cyc        = 16'd0;
    reg [15:0]  lap        = 16'd0;
    reg [127:0] div_sh     = {8{16'd2}};
    reg [127:0] off_sh     = 128'd0;
    reg [127:0] div_act    = {8{16'd2}};
    reg [127:0] off_act    = 128'd0;
    reg [127:0] ph         = 128'd0;
    reg [15:0]  align_cnt0 = 16'd0;
    reg         win        = 1'b0;
    reg         pv         = 1'b0;

    wire        wrap = (cyc == LAP - 16'd1);
    wire [15:0] off0 = off_act[15:0];

    genvar g;
    generate
        for (g = 0; g < 8; g = g + 1) begin : outs
            assign clk_out[g]     = ph[g*16 +: 16] < (div_act[g*16 +: 16] >> 1);
            assign align_pulse[g] = ce && (cyc == off_act[g*16 +: 16]);
        end
    endgenerate

    integer i;
    always @(posedge clk) begin
        if (rst) begin
            cyc        <= 16'd0;
            lap        <= 16'd0;
            align_cnt0 <= 16'd0;
            win        <= 1'b0;
            ph         <= 128'd0;
            div_act    <= {8{16'd2}};
            off_act    <= 128'd0;
            div_sh     <= {8{16'd2}};
            off_sh     <= 128'd0;
        end else begin
            if (win_close)     win <= 1'b0;
            else if (win_open) win <= 1'b1;
            if (cfg_we) begin
                div_sh[cfg_sel*16 +: 16] <= cfg_div;
                off_sh[cfg_sel*16 +: 16] <= cfg_off;
            end
            if (ce) begin
                if (wrap) begin
                    cyc        <= 16'd0;
                    lap        <= lap + 16'd1;
                    align_cnt0 <= 16'd0;
                end else begin
                    cyc <= cyc + 16'd1;
                    if (cyc == off0) align_cnt0 <= align_cnt0 + 16'd1;
                end
                for (i = 0; i < 8; i = i + 1) begin
                    if (wrap) begin
                        div_act[i*16 +: 16] <= (div_sh[i*16 +: 16] < 16'd2) ? 16'd2 : div_sh[i*16 +: 16];
                        off_act[i*16 +: 16] <= (off_sh[i*16 +: 16] >= LAP) ? (LAP - 16'd1) : off_sh[i*16 +: 16];
                    end
                    if (cyc == off_act[i*16 +: 16])
                        ph[i*16 +: 16] <= 16'd0;
                    else if (ph[i*16 +: 16] >= div_act[i*16 +: 16] - 16'd1)
                        ph[i*16 +: 16] <= 16'd0;
                    else
                        ph[i*16 +: 16] <= ph[i*16 +: 16] + 16'd1;
                end
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(lap) && $past(align_cnt0) >= 16'd1)
            assert ($stable(align_cnt0));
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
endmodule

module qpsk_mw_cfg (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cs,
    input wire di,
    output wire dout,
    output reg do_oe
);
    localparam [2:0] IDLE = 3'd0, START = 3'd1, OPCODE = 3'd2, ADDR = 3'd3, DATA = 3'd4;

    reg [2:0]  phase;
    reg [63:0] cnt;
    reg [7:0]  oa_sr;
    reg [63:0] dat_sr;
    reg [63:0] mem [0:63];
    reg [63:0] wr_cnt;
    reg        pre_commit;
    integer i;

    initial begin
        phase = IDLE; cnt = 64'd0; oa_sr = 8'd0; dat_sr = 64'd0;
        do_oe = 1'b0; wr_cnt = 64'd0; pre_commit = 1'b1;
        for (i = 0; i < 64; i = i + 1) mem[i] = 64'd0;
    end

    wire [7:0]  oa_next  = {oa_sr[6:0], di};
    wire        is_read  = (oa_sr[7:6] == 2'b10);
    wire [63:0] dat_next = {dat_sr[62:0], di};

    assign dout = do_oe & dat_sr[63];

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; cnt <= 64'd0; oa_sr <= 8'd0; dat_sr <= 64'd0;
            do_oe <= 1'b0; wr_cnt <= 64'd0; pre_commit <= 1'b1;
        end else if (en) begin
            if (!cs) begin
                phase <= IDLE;
                do_oe <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (di) phase <= START;
                    end
                    START: begin
                        phase <= OPCODE;
                        cnt <= 64'd2;
                    end
                    OPCODE: begin
                        oa_sr <= oa_next;
                        if (cnt == 64'd1) begin
                            phase <= ADDR;
                            cnt <= 64'd6;
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    ADDR: begin
                        oa_sr <= oa_next;
                        if (cnt == 64'd1) begin
                            phase <= DATA;
                            cnt <= 64'd64;
                            do_oe <= (oa_next[7:6] == 2'b10);
                            if (oa_next[7:6] == 2'b10)
                                dat_sr <= mem[oa_next[5:0]];
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    DATA: begin
                        if (is_read)
                            dat_sr <= {dat_sr[62:0], 1'b0};
                        else
                            dat_sr <= dat_next;
                        if (cnt == 64'd1) begin
                            if (!is_read) begin
                                mem[oa_sr[5:0]] <= dat_next;
                                wr_cnt <= wr_cnt + 64'd1;
                                pre_commit <= 1'b0;
                            end
                            phase <= IDLE;
                            do_oe <= 1'b0;
                        end else begin
                            cnt <= cnt - 64'd1;
                        end
                    end
                    default: begin
                        phase <= IDLE;
                    end
                endcase
            end
        end
    end

    always @(*)
        if (pre_commit)
            assert (!(phase == 3'd3 && do_oe));
endmodule

module tag_array_precedence (
    input wire clk,
    input wire ce,
    input wire fill,
    input wire [6:0] fill_set,
    input wire [7:0] fill_tag,
    input wire flush,
    input wire lookup,
    input wire [6:0] lookup_set,
    input wire [7:0] lookup_tag,
    output wire hit
);
    localparam [6:0] NSETS = 7'd96;

    reg [7:0] tag_mem [0:95];
    reg [95:0] valid;
    reg filled_any;
    reg [7:0] fill_cnt;
    reg hit_q;
    reg armed;

    integer i;
    initial begin
        for (i = 0; i < 96; i = i + 1) tag_mem[i] = 8'd0;
        valid = 96'd0;
        filled_any = 1'b0;
        fill_cnt = 8'd0;
        hit_q = 1'b0;
        armed = 1'b0;
    end

    wire fill_ok = fill && (fill_set < NSETS);
    wire look_ok = lookup && (lookup_set < NSETS);
    wire raw_hit = look_ok && valid[lookup_set] && (tag_mem[lookup_set] == lookup_tag);

    always @(posedge clk) begin
        if (ce && !flush && fill_ok)
            tag_mem[fill_set] <= fill_tag;
    end

    always @(posedge clk) begin
        if (ce) begin
            hit_q <= !flush && raw_hit;
            if (flush) begin
                valid <= 96'd0;
                filled_any <= 1'b0;
                fill_cnt <= 8'd0;
            end else if (fill_ok) begin
                valid[fill_set] <= 1'b1;
                filled_any <= 1'b1;
                if (fill_cnt != 8'hFF) fill_cnt <= fill_cnt + 8'd1;
                armed <= 1'b1;
            end
        end
    end

    assign hit = hit_q;

    always @(posedge clk)
        if (armed && hit_q)
            assert (filled_any);

    always @(posedge clk)
        if (armed && hit_q)
            assert (fill_cnt != 8'd0);
endmodule

module simd_serial_alu (
    input wire clk,
    input wire ce,
    input wire req,
    input wire [1:0] op,
    input wire [1:0] lsz,
    input wire [63:0] a_in,
    input wire [63:0] b_in,
    output wire busy_o,
    output wire [63:0] result,
    output wire [7:0] lane_flags
);
    localparam [63:0] K = 64'd8;
    reg busy = 1'b0;
    reg [63:0] cd = 64'd0;
    reg [63:0] pos = 64'd0;
    reg [63:0] a_r = 64'd0;
    reg [63:0] b_r = 64'd0;
    reg [63:0] res = 64'd0;
    reg [7:0] flg = 8'd0;
    reg [1:0] op_r = 2'd0;
    reg [1:0] lsz_r = 2'd0;
    reg carry = 1'b0;

    wire [2:0] p = pos[2:0];
    wire lane_lo = (lsz_r == 2'd0) | ((lsz_r == 2'd1) & ~p[0]) | ((lsz_r == 2'd2) & (p[1:0] == 2'b00)) | (p == 3'd0);
    wire lane_hi = (lsz_r == 2'd0) | ((lsz_r == 2'd1) & p[0]) | ((lsz_r == 2'd2) & (p[1:0] == 2'b11)) | (p == 3'd7);
    wire [7:0] ab = a_r[{p, 3'b000} +: 8];
    wire [7:0] bb = b_r[{p, 3'b000} +: 8];
    wire sub = (op_r == 2'd1);
    wire arith = ~op_r[1];
    wire cin = lane_lo ? sub : carry;
    wire [8:0] sum = {1'b0, ab} + {1'b0, bb ^ {8{sub}}} + {8'd0, cin};
    reg [7:0] r8;
    always @(*) begin
        case (op_r)
            2'd0, 2'd1: r8 = sum[7:0];
            2'd2: r8 = ab & bb;
            default: r8 = ab ^ bb;
        endcase
    end

    always @(posedge clk) begin
        if (ce) begin
            if (busy) begin
                res[{p, 3'b000} +: 8] <= r8;
                flg[p] <= lane_hi & arith & sum[8];
                carry <= sum[8];
                cd <= cd - 64'd1;
                if (pos == 64'd7) begin
                    busy <= 1'b0;
                    pos <= 64'd0;
                end else begin
                    pos <= pos + 64'd1;
                end
            end else if (req) begin
                busy <= 1'b1;
                pos <= 64'd0;
                cd <= K;
                a_r <= a_in;
                b_r <= b_in;
                op_r <= op;
                lsz_r <= lsz;
                carry <= 1'b0;
            end
        end
    end

    assign busy_o = busy;
    assign result = res;
    assign lane_flags = flg;

    always @(*) if (busy) assert (cd != 64'd0);
    always @(*) if (!busy) assert (cd == 64'd0);
endmodule

module spi_master_face (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire start,
    input wire cfg_wr,
    input wire [1:0] cfg_mode,
    input wire [7:0] tx_data,
    input wire miso,
    output reg cs_n,
    output reg sclk,
    output wire mosi,
    output reg [7:0] rx_data,
    output reg done
);
    reg busy;
    reg [7:0] shreg;
    reg [7:0] bitcnt;
    reg cpol;
    reg cpha;
    reg phase;
    reg samp;
    reg win;
    reg [1:0] mode_sh;
    reg pv;

    initial begin
        cs_n = 1'b1; sclk = 1'b0; rx_data = 8'd0; done = 1'b0;
        busy = 1'b0; shreg = 8'd0; bitcnt = 8'd0; cpol = 1'b0; cpha = 1'b0;
        phase = 1'b0; samp = 1'b0; win = 1'b0; mode_sh = 2'b00; pv = 1'b0;
    end

    assign mosi = shreg[7];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            cs_n <= 1'b1; sclk <= 1'b0; done <= 1'b0; busy <= 1'b0;
            bitcnt <= 8'd0; cpol <= 1'b0; cpha <= 1'b0; phase <= 1'b0;
            win <= 1'b0; mode_sh <= 2'b00;
        end else if (ce) begin
            done <= 1'b0;
            if (!busy) begin
                if (cfg_wr) begin
                    cpol <= cfg_mode[1];
                    cpha <= cfg_mode[0];
                    sclk <= cfg_mode[1];
                end else if (start) begin
                    busy <= 1'b1;
                    cs_n <= 1'b0;
                    shreg <= tx_data;
                    bitcnt <= 8'd0;
                    phase <= 1'b0;
                    win <= 1'b1;
                    mode_sh <= {cpol, cpha};
                end
            end else begin
                sclk <= ~sclk;
                phase <= ~phase;
                if (!phase) begin
                    samp <= miso;
                end else begin
                    shreg <= {shreg[6:0], (cpha ? miso : samp)};
                    if (bitcnt == 8'd7) begin
                        bitcnt <= 8'd0;
                        busy <= 1'b0;
                        cs_n <= 1'b1;
                        win <= 1'b0;
                        done <= 1'b1;
                        rx_data <= {shreg[6:0], (cpha ? miso : samp)};
                    end else begin
                        bitcnt <= bitcnt + 8'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (pv && win && $stable(cs_n))
            assert ($stable({cpol, cpha}) && ({cpol, cpha} == mode_sh));
endmodule

module mtile_od_loader (
    input  wire         clk,
    input  wire         step,
    input  wire         req,
    input  wire         ext_hold,
    input  wire [127:0] din,
    input  wire [3:0]   raddr,
    output wire [127:0] rdata,
    output wire         bus_line,
    output wire         busy_o
);
    // tile register: 16 rows of 128-bit data
    reg [127:0] tile [0:15];
    reg         busy;
    reg [4:0]   cnt;    // completion countdown
    reg [3:0]   beats;  // rows loaded so far
    reg         armed;  // sticky: set at first accepted request
    reg         pv;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) tile[i] = 128'd0;
        busy  = 1'b0;
        cnt   = 5'd0;
        beats = 4'd0;
        armed = 1'b0;
        pv    = 1'b0;
    end

    // open-drain drivers on a wired-AND ready line with external pull-up:
    // each driver pulls the line low while its input is asserted, otherwise releases it
    wire [1:0] od_pull = {ext_hold, busy};
    wire [1:0] od_rel  = ~od_pull;
    assign bus_line = &od_rel;

    always @(posedge clk) begin
        if (step) begin
            if (busy) begin
                tile[beats] <= din;
                if (beats == 4'd15) begin
                    busy  <= 1'b0;
                    cnt   <= 5'd0;
                    beats <= 4'd0;
                end else begin
                    beats <= beats + 4'd1;
                    cnt   <= cnt - 5'd1;
                end
            end else if (req && bus_line) begin
                busy  <= 1'b1;
                cnt   <= 5'd16;
                beats <= 4'd0;
                armed <= 1'b1;
            end
        end
    end

    assign rdata  = tile[raddr];
    assign busy_o = busy;

    always @(posedge clk) pv <= 1'b1;

    // bounded response: countdown never expired while the load was still outstanding
    always @(posedge clk)
        if (pv && armed)
            assert (!$past(busy) || $past(cnt) != 5'd0);
endmodule

module axi_burst_to_lite (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire         i_awvalid,
    input  wire [3:0]   i_awid,
    input  wire [31:0]  i_awaddr,
    input  wire [2:0]   i_awlen,
    input  wire         i_wr_en,
    input  wire [2:0]   i_wr_idx,
    input  wire [127:0] i_wr_data,
    input  wire [1:0]   i_lite_bresp,
    input  wire         i_bready,
    output wire         o_awready,
    output wire         o_lite_valid,
    output wire [31:0]  o_lite_awaddr,
    output wire [127:0] o_lite_wdata,
    output wire         o_bvalid,
    output wire [3:0]   o_bid,
    output wire [1:0]   o_bresp
);
    reg         busy = 1'b0;
    reg         bvalid = 1'b0;
    reg         win = 1'b0;
    reg [3:0]   beats_left = 4'd0;
    reg [3:0]   deadline = 4'd0;
    reg [31:0]  addr = 32'd0;
    reg [3:0]   id = 4'd0;
    reg [1:0]   resp_acc = 2'd0;
    reg [2:0]   bidx = 3'd0;
    reg [127:0] wbuf [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            wbuf[i] = 128'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            bvalid <= 1'b0;
            win <= 1'b0;
            beats_left <= 4'd0;
            deadline <= 4'd0;
            addr <= 32'd0;
            id <= 4'd0;
            resp_acc <= 2'd0;
            bidx <= 3'd0;
        end else if (i_ce) begin
            if (!busy && !bvalid && i_awvalid) begin
                busy <= 1'b1;
                win <= 1'b1;
                id <= i_awid;
                addr <= i_awaddr;
                beats_left <= {1'b0, i_awlen} + 4'd1;
                deadline <= {1'b0, i_awlen} + 4'd1;
                resp_acc <= 2'd0;
                bidx <= 3'd0;
            end else if (busy) begin
                beats_left <= beats_left - 4'd1;
                deadline <= deadline - 4'd1;
                addr <= addr + 32'd16;
                bidx <= bidx + 3'd1;
                if (i_lite_bresp > resp_acc)
                    resp_acc <= i_lite_bresp;
                if (beats_left == 4'd1) begin
                    busy <= 1'b0;
                    bvalid <= 1'b1;
                end
            end else if (bvalid && i_bready) begin
                bvalid <= 1'b0;
                win <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (!rst && i_ce && i_wr_en)
            wbuf[i_wr_idx] <= i_wr_data;

    assign o_awready     = !busy && !bvalid;
    assign o_lite_valid  = busy;
    assign o_lite_awaddr = addr;
    assign o_lite_wdata  = wbuf[bidx];
    assign o_bvalid      = bvalid;
    assign o_bid         = id;
    assign o_bresp       = resp_acc;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(beats_left) == 4'd0 || $past(deadline) != 4'd0);
endmodule

module bus_timeout_mon (
    input  wire        clk,
    input  wire        i_clr,
    input  wire        i_ce,
    input  wire        i_arm,
    input  wire [31:0] i_thresh,
    input  wire        i_req,
    input  wire        i_resp,
    output wire        o_err_resp,
    output wire        o_timeout,
    output wire [31:0] o_txn_count
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_BUSY  = 2'd2;

    reg [1:0]  phase;
    reg [31:0] thresh;
    reg [31:0] wait_cnt;
    reg [31:0] txn_count;
    reg        to_err;
    reg        seen_arm;
    reg        seen_start;

    initial begin
        phase = P_IDLE;
        thresh = 32'd0;
        wait_cnt = 32'd0;
        txn_count = 32'd0;
        to_err = 1'b0;
        seen_arm = 1'b0;
        seen_start = 1'b0;
    end

    always @(posedge clk) begin
        if (i_clr) begin
            phase <= P_IDLE;
            thresh <= 32'd0;
            wait_cnt <= 32'd0;
            txn_count <= 32'd0;
            to_err <= 1'b0;
            seen_arm <= 1'b0;
            seen_start <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (i_arm) begin
                        thresh <= i_thresh;
                        seen_arm <= 1'b1;
                        phase <= P_ARMED;
                    end
                end
                P_ARMED: begin
                    if (i_req) begin
                        seen_start <= 1'b1;
                        wait_cnt <= 32'd0;
                        txn_count <= txn_count + 32'd1;
                        phase <= P_BUSY;
                    end
                end
                P_BUSY: begin
                    if (i_resp) begin
                        wait_cnt <= 32'd0;
                        phase <= P_ARMED;
                    end else if (wait_cnt >= thresh) begin
                        to_err <= 1'b1;
                        wait_cnt <= 32'd0;
                        phase <= P_ARMED;
                    end else begin
                        wait_cnt <= wait_cnt + 32'd1;
                    end
                end
                default: begin
                end
            endcase
        end
    end

    assign o_err_resp  = (phase == P_BUSY) && !i_resp && (wait_cnt >= thresh);
    assign o_timeout   = to_err;
    assign o_txn_count = txn_count;

    assert property (!to_err || (seen_arm && seen_start));
endmodule

module lz77_match_finder (
    input wire clk,
    input wire i_push,
    input wire [63:0] i_data,
    input wire i_start,
    input wire [63:0] i_look0,
    input wire [63:0] i_look1,
    input wire i_ce,
    input wire i_ack,
    input wire i_flush,
    output wire o_searching,
    output wire o_match_valid,
    output wire [63:0] o_best_len,
    output wire [63:0] o_best_pos,
    output wire [63:0] o_match_len
);
    localparam [63:0] WIN  = 64'd256;
    localparam [63:0] LAST = 64'd255;

    reg [63:0] hist [0:255];
    reg [63:0] wr_ptr    = 64'd0;
    reg [63:0] look0     = 64'd0;
    reg [63:0] look1     = 64'd0;
    reg [63:0] scan_idx  = 64'd0;
    reg [63:0] scan_left = 64'd0;
    reg [63:0] cand_pos  = 64'd0;
    reg [63:0] match_len = 64'd0;
    reg [63:0] best_len  = 64'd0;
    reg [63:0] best_pos  = 64'd0;
    reg searching   = 1'b0;
    reg match_valid = 1'b0;
    reg armed       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) hist[i] = 64'd0;
    end

    wire [7:0] c0 = cand_pos[7:0];
    wire [7:0] c1 = c0 + 8'd1;
    wire [63:0] cand_len = (hist[c0] == look0) ? ((hist[c1] == look1) ? 64'd2 : 64'd1) : 64'd0;

    always @(posedge clk) begin
        if (i_push && !searching) begin
            hist[wr_ptr[7:0]] <= i_data;
            wr_ptr <= wr_ptr + 64'd1;
        end
        if (!searching && i_start) begin
            searching   <= 1'b1;
            match_valid <= 1'b0;
            scan_idx    <= 64'd0;
            scan_left   <= WIN;
            cand_pos    <= wr_ptr;
            look0       <= i_look0;
            look1       <= i_look1;
            best_len    <= 64'd0;
            best_pos    <= 64'd0;
            match_len   <= 64'd0;
        end else if (searching && i_ce) begin
            match_len <= cand_len;
            if (cand_len > best_len) begin
                best_len <= cand_len;
                best_pos <= cand_pos;
            end
            cand_pos  <= cand_pos + 64'd1;
            scan_idx  <= scan_idx + 64'd1;
            scan_left <= scan_left - 64'd1;
            if (scan_left == 64'd1) searching <= 1'b0;
            if (scan_idx == LAST) match_valid <= 1'b1;
        end else if (!searching && i_ack) begin
            match_valid <= 1'b0;
        end
    end

    // scope window: opened by the first accepted search, closed by flush
    always @(posedge clk) begin
        if (i_flush) armed <= 1'b0;
        else if (!searching && i_start) armed <= 1'b1;
    end

    assign o_searching   = searching;
    assign o_match_valid = match_valid;
    assign o_best_len    = best_len;
    assign o_best_pos    = best_pos;
    assign o_match_len   = match_len;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(armed))
            assert (!($past(searching) && $past(match_valid)));
endmodule

module dvfs_ctrl (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire [31:0] i_load,
    input  wire        i_vr_ack,
    input  wire        i_win_close,
    output reg  [31:0] o_volt_mv,
    output reg  [31:0] o_freq_khz,
    output wire        o_pending,
    output wire [31:0] o_req_count
);
    localparam [31:0] HI_TH = 32'd800;
    localparam [31:0] LO_TH = 32'd200;

    reg [2:0]  cur_pt    = 3'd0;
    reg [2:0]  req_pt    = 3'd0;
    reg [2:0]  last_req  = 3'd0;
    reg        pending   = 1'b0;
    reg        win       = 1'b0;
    reg [31:0] req_count = 32'd0;

    wire       up    = (i_load > HI_TH) && (cur_pt != 3'd7);
    wire       dn    = (i_load < LO_TH) && (cur_pt != 3'd0);
    wire       issue = i_ce && !pending && (up || dn);
    wire [2:0] nxt   = up ? (cur_pt + 3'd1) : (cur_pt - 3'd1);
    wire       grant = i_ce && pending && i_vr_ack;

    always @(posedge clk) begin
        if (i_reset) begin
            cur_pt    <= 3'd0;
            req_pt    <= 3'd0;
            last_req  <= 3'd0;
            pending   <= 1'b0;
            win       <= 1'b0;
            req_count <= 32'd0;
        end else begin
            if (issue) begin
                req_pt    <= nxt;
                last_req  <= nxt;
                pending   <= 1'b1;
                req_count <= req_count + 32'd1;
            end else if (grant) begin
                cur_pt  <= req_pt;
                pending <= 1'b0;
            end
            if (issue)
                win <= 1'b1;
            else if (i_ce && i_win_close)
                win <= 1'b0;
        end
    end

    always @(*) begin
        case (cur_pt)
            3'd0: begin o_volt_mv = 32'd700;  o_freq_khz = 32'd100000;  end
            3'd1: begin o_volt_mv = 32'd750;  o_freq_khz = 32'd200000;  end
            3'd2: begin o_volt_mv = 32'd800;  o_freq_khz = 32'd400000;  end
            3'd3: begin o_volt_mv = 32'd850;  o_freq_khz = 32'd600000;  end
            3'd4: begin o_volt_mv = 32'd900;  o_freq_khz = 32'd800000;  end
            3'd5: begin o_volt_mv = 32'd950;  o_freq_khz = 32'd1000000; end
            3'd6: begin o_volt_mv = 32'd1000; o_freq_khz = 32'd1200000; end
            default: begin o_volt_mv = 32'd1100; o_freq_khz = 32'd1500000; end
        endcase
    end

    assign o_pending   = pending;
    assign o_req_count = req_count;

    always @(posedge clk)
        assert (!(win && !pending) || (cur_pt == last_req));
endmodule

module polyphase_resampler (
    input  wire         clk,
    input  wire         ce,
    input  wire         in_valid,
    input  wire [127:0] in_data,
    output reg  [127:0] out_data,
    output reg          out_valid
);
    localparam [1:0] S_IDLE   = 2'd0;
    localparam [1:0] S_PRIMED = 2'd1;
    localparam [1:0] S_RUN    = 2'd2;
    localparam [1:0] S_DONE   = 2'd3;

    reg [127:0] hist [0:23];
    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) hist[i] = 128'd0;
    end

    reg [4:0] fill        = 5'd0;
    reg [4:0] phase       = 5'd0;
    reg [3:0] out_cnt     = 4'd0;
    reg [1:0] st          = S_IDLE;
    reg       q_seen      = 1'b0;
    reg       armed_seen  = 1'b0;
    reg       start_seen  = 1'b0;
    reg       finish_seen = 1'b0;
    initial out_data  = 128'd0;
    initial out_valid = 1'b0;

    wire [5:0] phase_sum = {1'b0, phase} + 6'd7;
    wire       wrap      = (phase_sum >= 6'd24);
    wire [4:0] phase_nxt = wrap ? (phase_sum[4:0] - 5'd24) : phase_sum[4:0];
    wire [4:0] tap       = 5'd23 - phase;

    always @(posedge clk) begin
        if (ce) begin
            if (in_valid) begin
                for (i = 23; i > 0; i = i - 1) hist[i] <= hist[i-1];
                hist[0] <= in_data;
                if (fill != 5'd24) fill <= fill + 5'd1;
                q_seen <= 1'b1;
            end
            phase     <= phase_nxt;
            out_valid <= 1'b0;
            case (st)
                S_IDLE: begin
                    if (fill == 5'd24) begin
                        st         <= S_PRIMED;
                        armed_seen <= 1'b1;
                    end
                end
                S_PRIMED: begin
                    if (wrap) begin
                        st         <= S_RUN;
                        start_seen <= 1'b1;
                        out_cnt    <= 4'd0;
                    end
                end
                S_RUN: begin
                    out_data  <= hist[phase] + hist[tap];
                    out_valid <= 1'b1;
                    if (out_cnt == 4'd11) begin
                        st          <= S_DONE;
                        finish_seen <= 1'b1;
                        out_cnt     <= 4'd0;
                    end else begin
                        out_cnt <= out_cnt + 4'd1;
                    end
                end
                S_DONE: begin
                    if (wrap) st <= S_RUN;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (q_seen && finish_seen)
            assert (start_seen && armed_seen);
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
endmodule

module rms_power_meter (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_start,
    input wire [2:0] i_shift,
    input wire [31:0] i_sample,
    output wire o_busy,
    output wire o_valid,
    output wire [63:0] o_mean_sq
);
    reg busy;
    reg valid;
    reg [2:0] shift_r;
    reg [63:0] win_len, win_cnt, countdown, acc, result;
    reg pv;
    initial begin
        busy = 1'b0; valid = 1'b0; shift_r = 3'd0;
        win_len = 64'd1; win_cnt = 64'd0; countdown = 64'd0;
        acc = 64'd0; result = 64'd0; pv = 1'b0;
    end

    wire [63:0] sq = {32'd0, i_sample} * {32'd0, i_sample};
    wire [63:0] acc_nxt = acc + sq;
    wire last = (win_cnt + 64'd1 == win_len);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0; valid <= 1'b0; shift_r <= 3'd0;
            win_len <= 64'd1; win_cnt <= 64'd0; countdown <= 64'd0;
            acc <= 64'd0; result <= 64'd0;
        end else if (i_ce) begin
            valid <= 1'b0;
            if (!busy) begin
                if (i_start) begin
                    busy <= 1'b1;
                    shift_r <= i_shift;
                    win_len <= 64'd1 << i_shift;
                    countdown <= 64'd1 << i_shift;
                    win_cnt <= 64'd0;
                    acc <= 64'd0;
                end
            end else begin
                acc <= acc_nxt;
                win_cnt <= win_cnt + 64'd1;
                countdown <= countdown - 64'd1;
                if (last) begin
                    busy <= 1'b0;
                    result <= acc_nxt >> shift_r;
                    valid <= 1'b1;
                end
            end
        end
    end

    assign o_busy = busy;
    assign o_valid = valid;
    assign o_mean_sq = result;

    // after a measurement request is accepted (busy set) until the window completes:
    // the deadline countdown never expires while the request is outstanding
    always @(posedge clk)
        if (busy)
            assert (countdown != 64'd0);

    // and the window completes exactly when the countdown reaches zero
    always @(posedge clk)
        if (pv && $fell(busy))
            assert (countdown == 64'd0);
endmodule

module kv_vault (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        wr_en,
    input  wire [2:0]  wr_slot,
    input  wire [63:0] wr_key,
    input  wire        perm_set,
    input  wire [2:0]  perm_slot,
    input  wire        lock_req,
    input  wire [2:0]  lock_slot,
    input  wire        use_req,
    input  wire [2:0]  use_slot,
    output reg  [63:0] cipher_key,
    output reg         use_gnt
);
    reg [511:0] key;
    reg [7:0]   perm;
    reg [7:0]   lock;
    reg [63:0]  use_cnt;
    reg         armed;

    initial key        = 512'd0;
    initial perm       = 8'd0;
    initial lock       = 8'd0;
    initial use_cnt    = 64'd0;
    initial armed      = 1'b0;
    initial cipher_key = 64'd0;
    initial use_gnt    = 1'b0;

    wire grant = use_req && perm[use_slot] && lock[use_slot];

    always @(posedge clk) begin
        if (!rst_n) begin
            key        <= 512'd0;
            perm       <= 8'd0;
            lock       <= 8'd0;
            use_cnt    <= 64'd0;
            armed      <= 1'b0;
            cipher_key <= 64'd0;
            use_gnt    <= 1'b0;
        end else if (en) begin
            if (wr_en && !lock[wr_slot])
                key[{wr_slot, 6'd0} +: 64] <= wr_key;
            if (perm_set && !lock[perm_slot])
                perm[perm_slot] <= 1'b1;
            if (lock_req) begin
                lock[lock_slot] <= 1'b1;
                if (lock_slot == 3'd0)
                    armed <= 1'b1;
            end
            use_gnt <= grant;
            if (grant) begin
                cipher_key <= key[{use_slot, 6'd0} +: 64];
                use_cnt    <= use_cnt + 64'd1;
            end else begin
                cipher_key <= 64'd0;
            end
        end
    end

    wire [63:0] key0 = key[63:0];

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed && $past(armed) && $stable(use_cnt))
            assert ($stable(key0));
endmodule

module zkr_seed_unit (
    input wire clk,
    input wire rst,
    input wire en,
    input wire raw,
    input wire q_open,
    input wire r_close,
    output wire [7:0] o_seed,
    output wire o_win
);
    reg half = 1'b0;
    reg first_bit = 1'b0;
    reg out_valid = 1'b0;
    reg out_bit = 1'b0;
    reg [7:0] pair_cnt = 8'd0;
    reg [7:0] emit_cnt = 8'd0;
    reg [63:0] pool = 64'd0;
    reg [5:0] wr_ptr = 6'd0;
    reg win = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            half <= 1'b0;
            first_bit <= 1'b0;
            out_valid <= 1'b0;
            out_bit <= 1'b0;
            pair_cnt <= 8'd0;
            emit_cnt <= 8'd0;
            pool <= 64'd0;
            wr_ptr <= 6'd0;
            win <= 1'b0;
        end else if (en) begin
            if (!half) begin
                first_bit <= raw;
                half <= 1'b1;
                pair_cnt <= pair_cnt + 8'd1;
                if (out_valid) begin
                    pool[wr_ptr] <= out_bit;
                    wr_ptr <= wr_ptr + 6'd1;
                    out_valid <= 1'b0;
                end
            end else begin
                half <= 1'b0;
                if (raw != first_bit) begin
                    out_bit <= first_bit;
                    out_valid <= 1'b1;
                end
            end
            if (out_valid)
                emit_cnt <= emit_cnt + 8'd1;
            if (q_open)
                win <= 1'b1;
            else if (r_close)
                win <= 1'b0;
        end
    end

    assign o_seed = pool[7:0];
    assign o_win = win;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(pair_cnt))
            assert ($stable(emit_cnt));
endmodule

module huff_decoder64 (
    input wire clk,
    input wire rst,
    input wire start,
    input wire step,
    input wire wr_en,
    input wire wr_idx,
    input wire [63:0] bits_in,
    input wire [63:0] wr_code,
    input wire [63:0] wr_len,
    output wire busy,
    output wire [63:0] o_sym,
    output wire [63:0] o_nsym
);
    localparam [63:0] MAXLEN = 64'd8;

    // decode window / request outstanding
    reg win = 1'b0;
    // bit accumulator, consumed-code shift register, bit position, completion countdown
    reg [63:0] acc = 64'd0;
    reg [63:0] code_acc = 64'd0;
    reg [63:0] bitpos = 64'd0;
    reg [63:0] cnt = 64'd0;
    reg [63:0] sym = 64'd0;
    reg [63:0] nsym = 64'd0;
    // two-entry code table (code word + length)
    reg [63:0] code0 = 64'd0;
    reg [63:0] len0 = 64'd1;
    reg [63:0] code1 = 64'd2;
    reg [63:0] len1 = 64'd2;

    wire [63:0] nbits = bitpos + 64'd1;
    wire [63:0] ncode = {code_acc[62:0], acc[63]};
    wire hit0 = (nbits == len0) && (ncode == code0);
    wire hit1 = (nbits == len1) && (ncode == code1);
    wire esc  = (nbits == MAXLEN);

    always @(posedge clk) begin
        if (rst) begin
            win <= 1'b0;
            acc <= 64'd0;
            code_acc <= 64'd0;
            bitpos <= 64'd0;
            cnt <= 64'd0;
            nsym <= 64'd0;
        end else begin
            if (wr_en) begin
                if (wr_idx) begin
                    code1 <= wr_code;
                    len1 <= wr_len;
                end else begin
                    code0 <= wr_code;
                    len0 <= wr_len;
                end
            end
            if (win) begin
                if (step) begin
                    acc <= acc << 1;
                    code_acc <= ncode;
                    bitpos <= nbits;
                    cnt <= cnt - 64'd1;
                    if (hit0 || hit1 || esc) begin
                        win <= 1'b0;
                        nsym <= nsym + 64'd1;
                        sym <= hit0 ? 64'd0 : (hit1 ? 64'd1 : 64'd2);
                    end
                end
            end else if (start) begin
                win <= 1'b1;
                acc <= bits_in;
                code_acc <= 64'd0;
                bitpos <= 64'd0;
                cnt <= MAXLEN;
            end
        end
    end

    assign busy = win;
    assign o_sym = sym;
    assign o_nsym = nsym;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(cnt) != 64'd0);
endmodule

module usb_ep_buf (
    input  wire        clk,
    input  wire        ce,
    input  wire        cfg_set,
    input  wire        out_valid,
    input  wire [31:0] out_data,
    input  wire        in_ready,
    output wire [31:0] in_data,
    output wire        in_toggle,
    output wire        out_toggle,
    output wire [31:0] level_o
);
    reg [31:0] mem [0:15];
    reg [31:0] wptr     = 32'd0;
    reg [31:0] rptr     = 32'd0;
    reg [31:0] count    = 32'd0;
    reg        tog_out  = 1'b0;
    reg        tog_in   = 1'b0;
    reg        ep_cfg   = 1'b0;
    reg        armed    = 1'b0;
    reg        pkt_done = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) mem[i] = 32'd0;
    end

    wire [31:0] level   = wptr - rptr;
    wire        do_push = ce && ep_cfg && out_valid && (level != 32'd16);
    wire        do_pop  = ce && in_ready && (level != 32'd0);

    assign in_data    = mem[rptr[3:0]];
    assign in_toggle  = tog_in;
    assign out_toggle = tog_out;
    assign level_o    = count;

    always @(posedge clk) begin
        if (ce) begin
            if (cfg_set) ep_cfg <= 1'b1;
            pkt_done <= do_push;
        end
        if (do_push) begin
            mem[wptr[3:0]] <= out_data;
            wptr    <= wptr + 32'd1;
            tog_out <= ~tog_out;
            armed   <= 1'b1;
        end
        if (do_pop) begin
            rptr   <= rptr + 32'd1;
            tog_in <= ~tog_in;
        end
        case ({do_push, do_pop})
            2'b10:   count <= count + 32'd1;
            2'b01:   count <= count - 32'd1;
            default: count <= count;
        endcase
    end

    always @(posedge clk)
        if (armed && $rose(pkt_done))
            assert (count <= 32'd16);
endmodule

module wb_port_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       issue,
    input  wire [7:0] lat,
    input  wire       oreq,
    input  wire [7:0] olat,
    output wire       acc,
    output wire       oacc,
    output wire       wb_fire,
    output wire       wb_trk
);
    // result-bus reservation shift register: bit i = write port booked i steps ahead
    reg [47:0] resv = 48'd0;
    // slot booked by the tracked (watched) functional unit request
    reg [47:0] trk  = 48'd0;
    // window register: set when tracked request accepted, cleared on its writeback
    reg        pend = 1'b0;
    // bounded-response countdown
    reg [7:0]  cnt  = 8'd0;

    wire [47:0] rsh = resv >> 1;
    wire lat_ok  = (lat  < 8'd48) && ((rsh & (48'd1 << lat))  == 48'd0);
    wire olat_ok = (olat < 8'd48) && ((rsh & (48'd1 << olat)) == 48'd0);

    assign acc  = step && issue && !pend && lat_ok;
    assign oacc = step && oreq && olat_ok && !(acc && (olat == lat));
    assign wb_fire = step && resv[0];
    assign wb_trk  = step && pend && trk[0];

    always @(posedge clk) begin
        if (rst) begin
            resv <= 48'd0;
            trk  <= 48'd0;
            pend <= 1'b0;
            cnt  <= 8'd0;
        end else if (step) begin
            resv <= rsh | (acc ? (48'd1 << lat) : 48'd0) | (oacc ? (48'd1 << olat) : 48'd0);
            trk  <= (trk >> 1) | (acc ? (48'd1 << lat) : 48'd0);
            if (pend) begin
                if (trk[0]) begin
                    pend <= 1'b0;
                    cnt  <= 8'd0;
                end else begin
                    cnt  <= cnt - 8'd1;
                end
            end else if (acc) begin
                pend <= 1'b1;
                cnt  <= lat + 8'd1;
            end
        end
    end

    // after accept (pend set) until writeback (pend cleared): countdown never expires
    assert property (!pend || cnt != 8'd0);
endmodule

module orbit_mrs_unit (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        req_valid,
    input  wire [2:0]  req_idx,
    input  wire [15:0] req_data,
    input  wire        cfg_lock,
    output wire        busy,
    output reg         mrs_cmd_valid,
    output reg  [18:0] mrs_cmd
);
    reg [15:0] shadow [0:7];
    reg [7:0]  pend;
    reg [2:0]  cur_idx;
    reg [15:0] cur_data;
    reg [15:0] cnt;
    reg        win;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) shadow[i] = 16'd0;
        pend = 8'd0;
        cur_idx = 3'd0;
        cur_data = 16'd0;
        cnt = 16'd0;
        win = 1'b0;
        mrs_cmd_valid = 1'b0;
        mrs_cmd = 19'd0;
    end

    assign busy = |pend;

    wire accept   = req_valid && !busy;
    wire countdn  = busy && (cnt > 16'd1);
    wire complete = busy && (cnt == 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) shadow[i] <= 16'd0;
            pend <= 8'd0;
            cur_idx <= 3'd0;
            cur_data <= 16'd0;
            cnt <= 16'd0;
            win <= 1'b0;
            mrs_cmd_valid <= 1'b0;
            mrs_cmd <= 19'd0;
        end else if (en) begin
            mrs_cmd_valid <= 1'b0;
            if (accept) begin
                pend[req_idx] <= 1'b1;
                cur_idx <= req_idx;
                cur_data <= req_data;
                cnt <= 16'd8;
                mrs_cmd_valid <= 1'b1;
                mrs_cmd <= {req_idx, req_data};
            end else if (countdn) begin
                cnt <= cnt - 16'd1;
            end else if (complete) begin
                for (i = 0; i < 8; i = i + 1)
                    if (cur_idx == i[2:0]) shadow[i] <= cur_data;
                pend[cur_idx] <= 1'b0;
                cnt <= 16'd0;
            end
            if (accept)
                win <= 1'b1;
            else if (cfg_lock)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && busy) assert (cnt != 16'd0);
endmodule

module traffic_ctrl (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    input  wire       preempt,
    output wire       ns_green,
    output wire       ew_green,
    output wire [2:0] phase_o
);
    // phases: 0 NS_GREEN, 1 NS_YELLOW, 2 ALL_RED_A, 3 EW_GREEN, 4 EW_YELLOW, 5 ALL_RED_B
    reg [2:0]  phase     = 3'd0;
    reg [15:0] timer     = 16'd39;
    reg [15:0] green_cnt = 16'd0;
    reg        armed     = 1'b1;
    reg        pv        = 1'b0;

    assign ns_green = (phase == 3'd0);
    assign ew_green = (phase == 3'd3);
    assign phase_o  = phase;

    function [15:0] dur;
        input [2:0] p;
        begin
            case (p)
                3'd0:    dur = 16'd39;
                3'd1:    dur = 16'd4;
                3'd2:    dur = 16'd1;
                3'd3:    dur = 16'd29;
                3'd4:    dur = 16'd4;
                default: dur = 16'd1;
            endcase
        end
    endfunction

    wire [2:0] nxt = (phase >= 3'd5) ? 3'd0 : phase + 3'd1;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (rst) begin
            phase     <= 3'd0;
            timer     <= 16'd39;
            green_cnt <= 16'd0;
            armed     <= 1'b1;
        end else if (step) begin
            if (phase == 3'd0)
                green_cnt <= green_cnt + 16'd1;
            if (phase == 3'd0 && preempt) begin
                timer <= 16'd200;
                armed <= 1'b0;
            end else if (timer == 16'd0) begin
                phase <= nxt;
                timer <= dur(nxt);
                if (nxt == 3'd0)
                    green_cnt <= 16'd0;
            end else begin
                timer <= timer - 16'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && armed && $fell(ns_green))
            assert (green_cnt <= 16'd40);
endmodule

module dirty_track_ram (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_we,
    input  wire [1:0]   i_addr,
    input  wire [127:0] i_wdata,
    input  wire         i_clr,
    input  wire         i_clr_blk,
    input  wire         i_clr_all,
    output wire [127:0] o_rdata,
    output wire [1:0]   o_dirty,
    output wire [1:0]   o_dirty_cnt,
    output wire         o_any_dirty
);
    // 4 x 128-bit data array, organised as 2 blocks of 2 words
    reg [127:0] mem [0:3];
    reg [1:0]   dirty     = 2'b00;
    reg [1:0]   dirty_cnt = 2'd0;
    reg         any_dirty = 1'b0;

    initial begin
        mem[0] = 128'd0;
        mem[1] = 128'd0;
        mem[2] = 128'd0;
        mem[3] = 128'd0;
    end

    wire wblk = i_addr[1];

    reg [1:0] dirty_nx;
    reg [1:0] cnt_nx;
    always @(*) begin
        dirty_nx = dirty;
        cnt_nx   = dirty_cnt;
        if (i_we) begin
            dirty_nx[wblk] = 1'b1;
            if (!dirty[wblk])
                cnt_nx = dirty_cnt + 2'd1;
        end else if (i_clr_all) begin
            dirty_nx = 2'b00;
            cnt_nx   = 2'd0;
        end else if (i_clr) begin
            dirty_nx[i_clr_blk] = 1'b0;
            if (dirty[i_clr_blk])
                cnt_nx = dirty_cnt - 2'd1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_we)
                mem[i_addr] <= i_wdata;
            dirty     <= dirty_nx;
            dirty_cnt <= cnt_nx;
            any_dirty <= |dirty_nx;
        end
    end

    assign o_rdata     = mem[i_addr];
    assign o_dirty     = dirty;
    assign o_dirty_cnt = dirty_cnt;
    assign o_any_dirty = any_dirty;

    always @(*)
        assert (any_dirty == (dirty_cnt != 2'd0));
endmodule

module docker_cfg_shadow (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire wr,
    input wire [5:0] waddr,
    input wire [7:0] wdata,
    input wire commit,
    input wire [5:0] raddr,
    output wire [7:0] rdata
);
    reg [7:0] shadow [0:63];
    reg [7:0] active [0:63];
    reg [7:0] wr_cnt;
    reg [7:0] act_gen;
    reg armed;
    reg pre_commit;
    integer i;

    initial begin
        wr_cnt = 8'h00;
        act_gen = 8'h00;
        armed = 1'b0;
        pre_commit = 1'b1;
        for (i = 0; i < 64; i = i + 1) begin
            shadow[i] = 8'h00;
            active[i] = 8'h00;
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            wr_cnt <= 8'h00;
            act_gen <= 8'h00;
            armed <= 1'b0;
            pre_commit <= 1'b1;
            for (i = 0; i < 64; i = i + 1) begin
                shadow[i] <= 8'h00;
                active[i] <= 8'h00;
            end
        end else if (en) begin
            if (wr) begin
                shadow[waddr] <= wdata;
                wr_cnt <= wr_cnt + 8'h01;
            end
            if (armed) begin
                for (i = 0; i < 64; i = i + 1)
                    active[i] <= shadow[i];
                act_gen <= act_gen + 8'h01;
            end
            armed <= commit;
            if (commit)
                pre_commit <= 1'b0;
        end
    end

    assign rdata = active[raddr];

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && $past(rst_n) && pre_commit && $stable(wr_cnt))
            assert ($stable(act_gen));
endmodule

module cordic_rot64 (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        ack,
    input  wire [63:0] x_in,
    input  wire [63:0] y_in,
    input  wire [63:0] z_in,
    output wire [63:0] x_out,
    output wire [63:0] y_out,
    output wire [63:0] z_out,
    output wire        busy_o,
    output wire        done_o
);
    localparam [63:0] N_ITER = 64'd32;

    reg signed [63:0] x, y, z;
    reg [63:0] iter, remaining;
    reg busy, done, armed;

    initial begin
        x = 64'd0; y = 64'd0; z = 64'd0;
        iter = 64'd0; remaining = N_ITER;
        busy = 1'b0; done = 1'b0; armed = 1'b0;
    end

    // 32-entry arctangent ROM, angle in Q32 radians held in 64 bits
    function [63:0] atan_lut;
        input [4:0] i;
        begin
            case (i)
                5'd0: atan_lut = 64'h00000000C90FDAA2;
                5'd1: atan_lut = 64'h0000000076B19C16;
                5'd2: atan_lut = 64'h000000003EB6EBF2;
                5'd3: atan_lut = 64'h000000001FD5BA9B;
                5'd4: atan_lut = 64'h000000000FFAADDC;
                5'd5: atan_lut = 64'h0000000007FF556F;
                5'd6: atan_lut = 64'h0000000003FFEAAB;
                5'd7: atan_lut = 64'h0000000001FFFD55;
                default: atan_lut = 64'd1 << (6'd32 - {1'b0, i});
            endcase
        end
    endfunction

    wire [4:0] sh = iter[4:0];

    always @(posedge clk) begin
        if (rst) begin
            x <= 64'd0; y <= 64'd0; z <= 64'd0;
            iter <= 64'd0; remaining <= N_ITER;
            busy <= 1'b0; done <= 1'b0; armed <= 1'b0;
        end else if (ce) begin
            if (start && !busy) begin
                x <= x_in; y <= y_in; z <= z_in;
                iter <= 64'd0;
                remaining <= N_ITER;
                busy <= 1'b1;
                done <= 1'b0;
                armed <= 1'b1;
            end else begin
                if (ack) armed <= 1'b0;
                if (busy) begin
                    if (z[63] == 1'b0) begin
                        x <= x - (y >>> sh);
                        y <= y + (x >>> sh);
                        z <= z - atan_lut(sh);
                    end else begin
                        x <= x + (y >>> sh);
                        y <= y - (x >>> sh);
                        z <= z + atan_lut(sh);
                    end
                    iter <= iter + 64'd1;
                    remaining <= remaining - 64'd1;
                    if (iter == N_ITER - 64'd1) begin
                        busy <= 1'b0;
                        done <= 1'b1;
                    end
                end
            end
        end
    end

    assign x_out = x;
    assign y_out = y;
    assign z_out = z;
    assign busy_o = busy;
    assign done_o = done;

    // After a start (armed) until ack: never busy with the iteration budget exhausted
    always @(posedge clk)
        if (armed)
            assert (!(busy && remaining == 64'd0));
endmodule

module tapeout_i2f (
    input wire clk,
    input wire en,
    input wire arm,
    input wire start,
    input wire [7:0] din,
    input wire q_sess,
    input wire r_sess,
    output reg [7:0] fout,
    output reg fin
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, NORM = 2'd2, DONE = 2'd3;

    reg [1:0] phase;
    reg arm_f, start_f;
    reg [7:0] mant;
    reg [3:0] exp;
    reg win;

    initial begin
        phase = IDLE; arm_f = 1'b0; start_f = 1'b0;
        mant = 8'd0; exp = 4'd0; fout = 8'd0; fin = 1'b0; win = 1'b0;
    end

    wire guard_b = mant[3];
    wire sticky_b = |mant[2:0];
    wire rup = guard_b && (sticky_b || mant[4]);
    wire [2:0] mfrac = mant[6:4];
    wire [2:0] mr = (rup && mfrac != 3'b111) ? (mfrac + 3'd1) : mfrac;
    wire [7:0] rounded = (mant == 8'd0) ? 8'd0 : {1'b0, exp, mr};

    always @(posedge clk) begin
        if (en) begin
            if (q_sess) begin
                win <= 1'b1;
                arm_f <= 1'b0;
                start_f <= 1'b0;
                phase <= IDLE;
                fin <= 1'b0;
            end else begin
                if (r_sess) win <= 1'b0;
                fin <= 1'b0;
                case (phase)
                    IDLE: if (arm) begin
                        mant <= din; exp <= 4'd7; arm_f <= 1'b1; phase <= ARMED;
                    end
                    ARMED: if (start) begin
                        start_f <= 1'b1; phase <= NORM;
                    end
                    NORM: begin
                        if (mant != 8'd0 && !mant[7]) begin
                            mant <= mant << 1;
                            exp <= exp - 4'd1;
                        end else begin
                            phase <= DONE;
                            fin <= 1'b1;
                            fout <= rounded;
                        end
                    end
                    DONE: if (arm) begin
                        mant <= din; exp <= 4'd7; arm_f <= 1'b1; phase <= ARMED;
                    end
                endcase
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $past(win) && fin)
            assert ($past(arm_f) && $past(start_f));
endmodule

module mutex_arb (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire req_a,
    input wire req_b,
    input wire rel,
    input wire w_open,
    input wire w_close,
    output wire o_own_a,
    output wire o_own_b,
    output wire [31:0] o_grants
);
    localparam [1:0] IDLE = 2'd0, ARM = 2'd1, START = 2'd2, FIN = 2'd3;

    reg [1:0] phase;
    reg latch_a, latch_b;
    reg sync_a, sync_b;
    reg own_a, own_b;
    reg win;
    reg [31:0] n_grants;

    initial phase = IDLE;
    initial latch_a = 1'b0;
    initial latch_b = 1'b0;
    initial sync_a = 1'b0;
    initial sync_b = 1'b0;
    initial own_a = 1'b0;
    initial own_b = 1'b0;
    initial win = 1'b0;
    initial n_grants = 32'd0;

    // cross-coupled set terms: each side inhibited by the other, A wins ties
    wire set_a = req_a & ~latch_b;
    wire set_b = req_b & ~latch_a & ~set_a;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            latch_a <= 1'b0;
            latch_b <= 1'b0;
            sync_a <= 1'b0;
            sync_b <= 1'b0;
            own_a <= 1'b0;
            own_b <= 1'b0;
            win <= 1'b0;
            n_grants <= 32'd0;
        end else if (i_ce) begin
            if (w_open)
                win <= 1'b1;
            else if (w_close)
                win <= 1'b0;
            case (phase)
                IDLE: begin
                    if (set_a | set_b) begin
                        latch_a <= latch_a | set_a;
                        latch_b <= latch_b | set_b;
                        phase <= ARM;
                    end
                end
                ARM: begin
                    sync_a <= latch_a;
                    sync_b <= latch_b;
                    phase <= START;
                end
                START: begin
                    own_a <= sync_a;
                    own_b <= sync_b;
                    n_grants <= n_grants + 32'd1;
                    phase <= FIN;
                end
                FIN: begin
                    if (rel) begin
                        latch_a <= 1'b0;
                        latch_b <= 1'b0;
                        sync_a <= 1'b0;
                        sync_b <= 1'b0;
                        own_a <= 1'b0;
                        own_b <= 1'b0;
                        phase <= IDLE;
                    end
                end
            endcase
        end
    end

    assign o_own_a = own_a;
    assign o_own_b = own_b;
    assign o_grants = n_grants;

    // Chain precedence inside the window: ownership (finish) only with filter (start) and latch (arm)
    assert property (!win || ((!own_a || (sync_a && latch_a)) && (!own_b || (sync_b && latch_b))));
endmodule

module vtg_frame_sync #(
    parameter [31:0] H_ACTIVE = 32'd4,
    parameter [31:0] H_FP     = 32'd1,
    parameter [31:0] H_SYNC   = 32'd2,
    parameter [31:0] H_BP     = 32'd1,
    parameter [31:0] V_ACTIVE = 32'd2,
    parameter [31:0] V_FP     = 32'd1,
    parameter [31:0] V_SYNC   = 32'd2,
    parameter [31:0] V_BP     = 32'd1
) (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    output wire        hsync,
    output wire        vsync,
    output wire        hblank,
    output wire        vblank,
    output wire        active,
    output wire [31:0] o_x,
    output wire [31:0] o_y,
    output wire        o_win
);
    localparam [31:0] H_TOTAL    = H_ACTIVE + H_FP + H_SYNC + H_BP;
    localparam [31:0] HS_START   = H_ACTIVE + H_FP;
    localparam [31:0] HS_END     = H_ACTIVE + H_FP + H_SYNC;
    localparam [31:0] V_TOTAL    = V_ACTIVE + V_FP + V_SYNC + V_BP;
    localparam [31:0] VS_START   = V_ACTIVE + V_FP;
    localparam [31:0] VS_END     = V_ACTIVE + V_FP + V_SYNC;

    reg [31:0] h_cnt;
    reg [31:0] v_cnt;
    reg [31:0] lines_done;
    reg        win;
    reg        pv;
    initial begin
        h_cnt = 32'd0;
        v_cnt = 32'd0;
        lines_done = 32'd0;
        win = 1'b0;
        pv = 1'b0;
    end

    wire line_end = (h_cnt == H_TOTAL - 32'd1);
    wire last_line = (v_cnt == V_TOTAL - 32'd1);
    wire vs_close = line_end && (v_cnt == VS_END - 32'd1);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (line_end) begin
                h_cnt <= 32'd0;
                if (last_line) begin
                    v_cnt <= 32'd0;
                    lines_done <= 32'd0;
                end else begin
                    v_cnt <= v_cnt + 32'd1;
                    lines_done <= lines_done + 32'd1;
                end
            end else begin
                h_cnt <= h_cnt + 32'd1;
            end
            if (vs_close)
                win <= 1'b0;
            else if (arm)
                win <= 1'b1;
        end
    end

    assign hsync  = (h_cnt >= HS_START) && (h_cnt < HS_END);
    assign vsync  = (v_cnt >= VS_START) && (v_cnt < VS_END);
    assign hblank = (h_cnt >= H_ACTIVE);
    assign vblank = (v_cnt >= V_ACTIVE);
    assign active = !hblank && !vblank;
    assign o_x = h_cnt;
    assign o_y = v_cnt;
    assign o_win = win;

    always @(posedge clk)
        if (pv && win && $rose(vsync))
            assert (lines_done == VS_START);
endmodule

module delay_pulse_gen (
    input  wire        clk,
    input  wire        ce,
    input  wire        trig,
    input  wire        wr_cfg,
    input  wire [31:0] cfg_delay,
    input  wire [31:0] cfg_width,
    output wire        pulse,
    output wire        busy
);
    localparam [1:0] IDLE = 2'd0, DLY = 2'd1, WID = 2'd2;

    reg [31:0] delay_reg;
    reg [31:0] width_reg;
    reg [31:0] snap_delay;
    reg [31:0] snap_width;
    reg [31:0] cnt;
    reg [1:0]  phase;
    reg [33:0] since_trig;

    initial begin
        delay_reg  = 32'd0;
        width_reg  = 32'd0;
        snap_delay = 32'd0;
        snap_width = 32'd0;
        cnt        = 32'd0;
        phase      = IDLE;
        since_trig = 34'd0;
    end

    always @(posedge clk) begin
        if (ce) begin
            if (wr_cfg) begin
                delay_reg <= cfg_delay;
                width_reg <= cfg_width;
            end
            case (phase)
                IDLE: begin
                    if (trig) begin
                        phase      <= DLY;
                        cnt        <= 32'd0;
                        snap_delay <= delay_reg;
                        snap_width <= width_reg;
                        since_trig <= 34'd0;
                    end
                end
                DLY: begin
                    since_trig <= since_trig + 34'd1;
                    if (cnt == snap_delay) begin
                        phase <= WID;
                        cnt   <= 32'd0;
                    end else begin
                        cnt <= cnt + 32'd1;
                    end
                end
                WID: begin
                    since_trig <= since_trig + 34'd1;
                    if (cnt == snap_width) begin
                        phase <= IDLE;
                        cnt   <= 32'd0;
                    end else begin
                        cnt <= cnt + 32'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    cnt   <= 32'd0;
                end
            endcase
        end
    end

    assign pulse = (phase == WID);
    assign busy  = (phase != IDLE);

    // Precedence: a pulse now implies the trigger came more than 'delay' cycles earlier
    always @(posedge clk)
        if (phase == WID)
            assert (since_trig > {2'b00, snap_delay});

    // Precedence: a pulse now implies the trigger came no more than delay+width+1 cycles earlier
    always @(posedge clk)
        if (phase == WID)
            assert (since_trig <= {2'b00, snap_delay} + {2'b00, snap_width} + 34'd1);
endmodule

module ecc_dbg_mem (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        cmd_valid,
    input  wire        cmd_wr,
    input  wire [5:0]  cmd_addr,
    input  wire [31:0] cmd_wdata,
    input  wire [38:0] cmd_inject,
    input  wire        rsp_ack,
    output wire        rsp_valid,
    output reg  [31:0] rsp_rdata,
    output reg  [6:0]  rsp_syndrome,
    output reg         rsp_sbe,
    output reg         rsp_dbe
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, START = 2'd2, DONE = 2'd3;

    function [38:0] secded_enc(input [31:0] d);
        integer i, j, p, k;
        reg [38:0] c;
        reg par;
        begin
            c = 39'd0;
            j = 0;
            for (i = 1; i < 39; i = i + 1) begin
                if ((i & (i - 1)) != 0) begin
                    c[i] = d[j];
                    j = j + 1;
                end
            end
            for (p = 0; p < 6; p = p + 1) begin
                par = 1'b0;
                for (k = 1; k < 39; k = k + 1)
                    if (((k >> p) & 1) == 1) par = par ^ c[k];
                c[1 << p] = par;
            end
            c[0] = ^c[38:1];
            secded_enc = c;
        end
    endfunction

    function [5:0] secded_syn(input [38:0] c);
        integer p, k;
        reg [5:0] s;
        begin
            s = 6'd0;
            for (p = 0; p < 6; p = p + 1)
                for (k = 1; k < 39; k = k + 1)
                    if (((k >> p) & 1) == 1) s[p] = s[p] ^ c[k];
            secded_syn = s;
        end
    endfunction

    function [31:0] secded_data(input [38:0] c);
        integer i, j;
        reg [31:0] d;
        begin
            d = 32'd0;
            j = 0;
            for (i = 1; i < 39; i = i + 1) begin
                if ((i & (i - 1)) != 0) begin
                    d[j] = c[i];
                    j = j + 1;
                end
            end
            secded_data = d;
        end
    endfunction

    reg [1:0]  phase      = IDLE;
    reg        arm_seen   = 1'b0;
    reg        start_seen = 1'b0;
    reg        q_seen     = 1'b0;
    reg        wr_q       = 1'b0;
    reg [5:0]  addr_q     = 6'd0;
    reg [31:0] wdata_q    = 32'd0;
    reg [38:0] inj_q      = 39'd0;
    reg [38:0] rd_cw_q    = 39'd0;
    reg [38:0] mem [0:63];

    integer n;
    initial begin
        for (n = 0; n < 64; n = n + 1) mem[n] = 39'd0;
        rsp_rdata    = 32'd0;
        rsp_syndrome = 7'd0;
        rsp_sbe      = 1'b0;
        rsp_dbe      = 1'b0;
    end

    wire [38:0] wr_cw = secded_enc(wdata_q) ^ inj_q;
    wire [5:0]  syn   = secded_syn(rd_cw_q);
    wire        ovp   = ^rd_cw_q;
    wire        sbe   = ovp;
    wire        dbe   = !ovp && (syn != 6'd0);
    wire [38:0] fixed = sbe ? (rd_cw_q ^ (39'd1 << syn)) : rd_cw_q;

    assign rsp_valid = (phase == DONE);

    always @(posedge clk) begin
        if (rst) begin
            phase      <= IDLE;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: if (cmd_valid) begin
                    phase      <= ARMED;
                    arm_seen   <= 1'b1;
                    start_seen <= 1'b0;
                    wr_q       <= cmd_wr;
                    addr_q     <= cmd_addr;
                    wdata_q    <= cmd_wdata;
                    inj_q      <= cmd_inject;
                    if (cmd_wr) q_seen <= 1'b1;
                end
                ARMED: begin
                    if (wr_q) mem[addr_q] <= wr_cw;
                    rd_cw_q    <= wr_q ? wr_cw : mem[addr_q];
                    start_seen <= 1'b1;
                    phase      <= START;
                end
                START: begin
                    rsp_rdata    <= secded_data(fixed);
                    rsp_syndrome <= {ovp, syn};
                    rsp_sbe      <= sbe;
                    rsp_dbe      <= dbe;
                    phase        <= DONE;
                end
                DONE: if (rsp_ack) begin
                    phase      <= IDLE;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end
    end

    assert property (!q_seen || !rsp_valid || (arm_seen && start_seen));
endmodule

module chacha_qr_lockstep (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire load,
    input wire [3:0] ld_idx,
    input wire [31:0] ld_word,
    input wire start,
    input wire abort,
    output wire o_mismatch,
    output wire [31:0] o_word0,
    output wire [31:0] o_rnd
);
    // 16 x 32-bit state words, flattened: word i at bits [i*32 +: 32]
    reg [511:0] st_a;
    reg [511:0] st_b;
    reg [31:0]  rnd;
    reg         win;

    initial begin
        st_a = 512'd0;
        st_b = 512'd0;
        rnd  = 32'd0;
        win  = 1'b0;
    end

    function [511:0] qr_step;
        input [511:0] s;
        input [2:0] sel;
        reg [3:0] ia, ib, ic, id;
        reg [31:0] a, b, c, d;
        reg [511:0] r;
        begin
            case (sel)
                3'd0: begin ia = 4'd0; ib = 4'd4; ic = 4'd8;  id = 4'd12; end
                3'd1: begin ia = 4'd1; ib = 4'd5; ic = 4'd9;  id = 4'd13; end
                3'd2: begin ia = 4'd2; ib = 4'd6; ic = 4'd10; id = 4'd14; end
                3'd3: begin ia = 4'd3; ib = 4'd7; ic = 4'd11; id = 4'd15; end
                3'd4: begin ia = 4'd0; ib = 4'd5; ic = 4'd10; id = 4'd15; end
                3'd5: begin ia = 4'd1; ib = 4'd6; ic = 4'd11; id = 4'd12; end
                3'd6: begin ia = 4'd2; ib = 4'd7; ic = 4'd8;  id = 4'd13; end
                default: begin ia = 4'd3; ib = 4'd4; ic = 4'd9; id = 4'd14; end
            endcase
            a = s[{ia, 5'b0} +: 32];
            b = s[{ib, 5'b0} +: 32];
            c = s[{ic, 5'b0} +: 32];
            d = s[{id, 5'b0} +: 32];
            a = a + b; d = d ^ a; d = {d[15:0], d[31:16]};
            c = c + d; b = b ^ c; b = {b[19:0], b[31:20]};
            a = a + b; d = d ^ a; d = {d[23:0], d[31:24]};
            c = c + d; b = b ^ c; b = {b[24:0], b[31:25]};
            r = s;
            r[{ia, 5'b0} +: 32] = a;
            r[{ib, 5'b0} +: 32] = b;
            r[{ic, 5'b0} +: 32] = c;
            r[{id, 5'b0} +: 32] = d;
            qr_step = r;
        end
    endfunction

    wire [511:0] nxt_a = qr_step(st_a, rnd[2:0]);
    wire [511:0] nxt_b = qr_step(st_b, rnd[2:0]);

    always @(posedge clk) begin
        if (!rst_n) begin
            st_a <= 512'd0;
            st_b <= 512'd0;
            rnd  <= 32'd0;
            win  <= 1'b0;
        end else if (en) begin
            if (load) begin
                st_a[{ld_idx, 5'b0} +: 32] <= ld_word;
                st_b[{ld_idx, 5'b0} +: 32] <= ld_word;
                rnd <= 32'd0;
            end else begin
                st_a <= nxt_a;
                st_b <= nxt_b;
                rnd  <= rnd + 32'd1;
            end
            if (abort)
                win <= 1'b0;
            else if (start)
                win <= 1'b1;
        end
    end

    assign o_mismatch = (st_a != st_b);
    assign o_word0    = st_a[31:0];
    assign o_rnd      = rnd;

    always @(*) assert (!win || (st_a[31:0] == st_b[31:0]));
endmodule

module jls_remap_lut (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr_v,
    input wire [63:0] wdata,
    input wire new_frame,
    input wire pix_v,
    input wire [4:0] pix_idx,
    output reg [63:0] out_q
);
    localparam [63:0] DEPTH = 64'd24;
    localparam [63:0] LAST  = 64'd23;

    reg [63:0] mem [0:23];
    reg [63:0] wp;
    reg full_q, empty_q, load_own, map_own, armed;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 64'd0;
        wp = 64'd0;
        full_q = 1'b0;
        empty_q = 1'b1;
        load_own = 1'b1;
        map_own = 1'b0;
        armed = 1'b0;
        out_q = 64'd0;
    end

    wire [4:0] sidx = (pix_idx > 5'd23) ? 5'd23 : pix_idx;
    wire do_wr = wr_v && load_own && (wp < DEPTH);

    always @(posedge clk) begin
        if (rst) begin
            wp <= 64'd0;
            full_q <= 1'b0;
            empty_q <= 1'b1;
            load_own <= 1'b1;
            map_own <= 1'b0;
            armed <= 1'b0;
            out_q <= 64'd0;
        end else if (en) begin
            if (new_frame) begin
                wp <= 64'd0;
                empty_q <= 1'b1;
                full_q <= 1'b0;
                load_own <= 1'b1;
                map_own <= 1'b0;
            end else if (do_wr) begin
                mem[wp[4:0]] <= wdata;
                wp <= wp + 64'd1;
                empty_q <= empty_q && (wp != 64'd0);
                full_q <= full_q || (wp == LAST);
                load_own <= load_own && (wp != LAST);
                map_own <= map_own || (wp == LAST);
                if (wp == LAST) armed <= 1'b1;
            end
            if (pix_v && map_own)
                out_q <= mem[sidx];
        end
    end

    always @(posedge clk)
        if (armed)
            assert (!(full_q && empty_q));

    always @(posedge clk)
        if (armed)
            assert (!(load_own && map_own));
endmodule

module isp_fb_sema (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [31:0] req_id,
    input wire [5:0] cell_sel,
    input wire arm_req,
    input wire start_req,
    input wire fin_req,
    output wire [1:0] o_phase,
    output wire [47:0] o_locked,
    output wire [31:0] o_cur_owner
);
    reg [47:0] locked = 48'd0;
    reg [31:0] owner [0:47];
    reg [5:0] cur_cell = 6'd0;
    reg [1:0] phase = 2'd0;
    reg [31:0] arm_cnt = 32'd0;
    reg [31:0] start_cnt = 32'd0;
    reg [31:0] fin_cnt = 32'd0;
    integer i;
    initial begin
        for (i = 0; i < 48; i = i + 1) owner[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            locked <= 48'd0;
            cur_cell <= 6'd0;
            phase <= 2'd0;
            arm_cnt <= 32'd0;
            start_cnt <= 32'd0;
            fin_cnt <= 32'd0;
        end else if (en) begin
            case (phase)
                2'd0: begin
                    if (arm_req && (cell_sel < 6'd48) && !locked[cell_sel]) begin
                        locked[cell_sel] <= 1'b1;
                        owner[cell_sel] <= req_id;
                        cur_cell <= cell_sel;
                        phase <= 2'd1;
                        arm_cnt <= arm_cnt + 32'd1;
                    end
                end
                2'd1: begin
                    if (start_req) begin
                        phase <= 2'd2;
                        start_cnt <= start_cnt + 32'd1;
                    end
                end
                2'd2: begin
                    if (fin_req) begin
                        locked[cur_cell] <= 1'b0;
                        phase <= 2'd0;
                        fin_cnt <= fin_cnt + 32'd1;
                    end
                end
                default: begin
                end
            endcase
        end
    end

    assign o_phase = phase;
    assign o_locked = locked;
    assign o_cur_owner = owner[cur_cell];

    always @(*) assert (((arm_cnt - start_cnt) <= 32'd1) && ((start_cnt - fin_cnt) <= 32'd1));
endmodule

module frame_scrambler32 (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire [31:0] i_data,
    output wire [31:0] o_scr,
    output wire [31:0] o_desc
);
    localparam [31:0] SEED = 32'h1D2C3B4A;
    localparam [31:0] POLY = 32'hEDB88320;
    localparam [31:0] LAST = 32'd11;

    reg [31:0] lfsr_tx, lfsr_rx;
    reg [31:0] tx_cnt, rx_cnt;
    reg        armed;
    initial begin
        lfsr_tx = SEED; lfsr_rx = SEED;
        tx_cnt = 32'd0; rx_cnt = 32'd0;
        armed = 1'b0;
    end

    function [31:0] lfsr_step;
        input [31:0] s;
        begin
            lfsr_step = s[0] ? ((s >> 1) ^ POLY) : (s >> 1);
        end
    endfunction

    // scrambler (tx) and descrambler (rx) run in lockstep, reseeding every 12 words
    always @(posedge clk) begin
        if (rst) begin
            lfsr_tx <= SEED; lfsr_rx <= SEED;
            tx_cnt <= 32'd0; rx_cnt <= 32'd0;
        end else if (i_ce) begin
            if (tx_cnt == LAST) begin
                tx_cnt  <= 32'd0;
                lfsr_tx <= SEED;
            end else begin
                tx_cnt  <= tx_cnt + 32'd1;
                lfsr_tx <= lfsr_step(lfsr_tx);
            end
            if (rx_cnt == LAST) begin
                rx_cnt  <= 32'd0;
                lfsr_rx <= SEED;
            end else begin
                rx_cnt  <= rx_cnt + 32'd1;
                lfsr_rx <= lfsr_step(lfsr_rx);
            end
        end
    end

    // sticky scope register: set at the first scrambled word, never cleared
    always @(posedge clk)
        if (i_ce) armed <= 1'b1;

    assign o_scr  = i_data ^ lfsr_tx;
    assign o_desc = o_scr ^ lfsr_rx;

    wire tx_sof = (tx_cnt == 32'd0);
    wire tx_eof = (tx_cnt == LAST);
    wire rx_sof = (rx_cnt == 32'd0);
    wire rx_eof = (rx_cnt == LAST);

    always @(posedge clk) begin
        if (armed) begin
            assert (!(tx_sof && rx_eof));
            assert (!(tx_eof && rx_sof));
        end
    end
endmodule

module ifu_align_buf (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_rvalid,
    input  wire [127:0] i_rdata,
    input  wire         i_pop,
    output wire         o_req,
    output wire [31:0]  o_fetch_addr,
    output wire         o_valid,
    output wire [127:0] o_line,
    output wire [31:0]  o_pc
);
    reg [127:0] abuf [0:7];
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [3:0]  count = 4'd0;
    reg [31:0] fetch_ptr = 32'd0;
    reg [31:0] head_pc = 32'd0;
    reg        armed = 1'b0;
    reg        pv = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            abuf[i] = 128'd0;
    end

    wire [3:0] occ   = wptr - rptr;
    wire       full  = (occ == 4'd8);
    wire       empty = (occ == 4'd0);
    wire push_ok = i_ce && i_rvalid && !full;
    wire pop_ok  = i_ce && i_pop && !empty;

    always @(posedge clk) begin
        if (push_ok) begin
            abuf[wptr[2:0]] <= i_rdata;
            wptr            <= wptr + 4'd1;
            fetch_ptr       <= fetch_ptr + 32'd16;
        end
        if (pop_ok) begin
            rptr    <= rptr + 4'd1;
            head_pc <= head_pc + 32'd16;
        end
        case ({push_ok, pop_ok})
            2'b10:   count <= count + 4'd1;
            2'b01:   count <= count - 4'd1;
            default: count <= count;
        endcase
    end

    always @(posedge clk)
        if (push_ok)
            armed <= 1'b1;

    always @(posedge clk)
        pv <= 1'b1;

    assign o_req        = !full;
    assign o_fetch_addr = fetch_ptr;
    assign o_valid      = !empty;
    assign o_line       = abuf[rptr[2:0]];
    assign o_pc         = head_pc;

    always @(posedge clk)
        if (armed && pv && $stable(rptr))
            assert ($stable(head_pc) && (count <= 4'd8));
endmodule

module backoff_ctrl (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire req,
    input wire col,
    input wire [63:0] rnd,
    output wire tx_active,
    output wire busy,
    output wire [63:0] o_attempts
);
    localparam [1:0] S_IDLE = 2'd0;
    localparam [1:0] S_WAIT = 2'd1;
    localparam [1:0] S_TX   = 2'd2;
    localparam [63:0] MAXA    = 64'd3;
    localparam [63:0] BUDGET0 = 64'd18;

    reg [1:0]  state;
    reg        pending;
    reg [63:0] attempts;
    reg [63:0] slot;
    reg [63:0] budget;

    initial begin
        state = S_IDLE;
        pending = 1'b0;
        attempts = 64'd0;
        slot = 64'd0;
        budget = 64'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            pending <= 1'b0;
            attempts <= 64'd0;
            slot <= 64'd0;
            budget <= 64'd0;
        end else if (ce) begin
            case (state)
                S_IDLE: begin
                    if (req) begin
                        state <= S_TX;
                        pending <= 1'b1;
                        attempts <= 64'd0;
                        slot <= 64'd0;
                        budget <= BUDGET0;
                    end
                end
                S_WAIT: begin
                    budget <= budget - 64'd1;
                    if (slot == 64'd0)
                        state <= S_TX;
                    else
                        slot <= slot - 64'd1;
                end
                S_TX: begin
                    budget <= budget - 64'd1;
                    if (!col) begin
                        state <= S_IDLE;
                        pending <= 1'b0;
                        attempts <= 64'd0;
                    end else if (attempts >= MAXA) begin
                        state <= S_IDLE;
                        pending <= 1'b0;
                        attempts <= 64'd0;
                    end else begin
                        attempts <= attempts + 64'd1;
                        slot <= rnd & ((64'd1 << (attempts + 64'd1)) - 64'd1);
                        state <= S_WAIT;
                    end
                end
                default: begin
                    state <= S_IDLE;
                    pending <= 1'b0;
                end
            endcase
        end
    end

    assign tx_active = (state == S_TX);
    assign busy = pending;
    assign o_attempts = attempts;

    always @(posedge clk)
        if (pending)
            assert (budget != 64'd0);
endmodule

module wl_map_scan (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [4:0] lblk,
    output reg busy,
    output reg done
);
    reg [4:0]  map_mem   [0:31];
    reg [15:0] erase_cnt [0:31];
    reg [5:0]  scan_idx;
    reg [5:0]  countdown;
    reg [4:0]  best_idx;
    reg [15:0] best_cnt;
    reg [4:0]  tgt;
    integer i;

    initial busy = 1'b0;
    initial done = 1'b0;
    initial scan_idx = 6'd0;
    initial countdown = 6'd0;
    initial best_idx = 5'd0;
    initial best_cnt = 16'hFFFF;
    initial tgt = 5'd0;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            map_mem[i] = i;
            erase_cnt[i] = 16'd0;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            busy <= 1'b0;
            done <= 1'b0;
            scan_idx <= 6'd0;
            countdown <= 6'd0;
            best_idx <= 5'd0;
            best_cnt <= 16'hFFFF;
            tgt <= 5'd0;
            for (i = 0; i < 32; i = i + 1) begin
                map_mem[i] <= i;
                erase_cnt[i] <= 16'd0;
            end
        end else if (en) begin
            done <= 1'b0;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    tgt <= lblk;
                    scan_idx <= 6'd0;
                    countdown <= 6'd33;
                    best_cnt <= 16'hFFFF;
                end
            end else if (scan_idx < 6'd32) begin
                if (erase_cnt[scan_idx[4:0]] < best_cnt) begin
                    best_idx <= scan_idx[4:0];
                    best_cnt <= erase_cnt[scan_idx[4:0]];
                end
                scan_idx <= scan_idx + 6'd1;
                countdown <= countdown - 6'd1;
            end else if (scan_idx == 6'd32) begin
                map_mem[tgt] <= best_idx;
                if (erase_cnt[best_idx] != 16'hFFFF)
                    erase_cnt[best_idx] <= erase_cnt[best_idx] + 16'd1;
                busy <= 1'b0;
                countdown <= countdown - 6'd1;
                done <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (busy) assert (countdown != 6'd0);
endmodule

module scan_unload_chain (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        req,
    input  wire [31:0] scan_in,
    input  wire [31:0] func_d,
    output wire [31:0] scan_out,
    output wire        busy_o
);
    // 32-entry scan chain of 32-bit scan flip-flops
    reg [31:0] chain [0:31];
    reg        busy     = 1'b0;
    reg [31:0] shifted  = 32'd0;
    reg [31:0] deadline = 32'd0;
    integer i;
    integer k;
    initial begin
        for (k = 0; k < 32; k = k + 1) chain[k] = 32'd0;
    end

    assign scan_out = chain[31];
    assign busy_o   = busy;

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            shifted  <= 32'd0;
            deadline <= 32'd0;
        end else if (ce) begin
            if (busy) begin
                // test mode: scan mux selects the previous flop
                for (i = 31; i > 0; i = i - 1)
                    chain[i] <= chain[i-1];
                chain[0] <= scan_in;
                shifted  <= shifted + 32'd1;
                deadline <= deadline - 32'd1;
                if (shifted == 32'd31)
                    busy <= 1'b0;
            end else if (req) begin
                // accept unload request: countdown guarantees completion in 32 shifts
                busy     <= 1'b1;
                shifted  <= 32'd0;
                deadline <= 32'd32;
            end else begin
                // functional mode: scan mux selects functional data
                for (i = 0; i < 32; i = i + 1)
                    chain[i] <= chain[i] ^ func_d;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(busy))
            assert ($past(deadline) != 32'd0);
endmodule

module pix_palette_bimap (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire [1:0] op,
    input wire [7:0] din_a,
    input wire [7:0] din_b,
    output wire hit,
    output wire [5:0] addr,
    output wire [7:0] partner
);
    // 48 entries x 8 bits, flattened: entry i lives at [i*8 +: 8]
    reg [383:0] key_mem = 384'd0;
    reg [383:0] val_mem = 384'd0;
    reg [47:0]  valid = 48'd0;
    reg [5:0]   wr_ptr = 6'd0;
    reg         hit_q = 1'b0;
    reg [5:0]   addr_q = 6'd0;
    reg [7:0]   partner_q = 8'd0;
    reg         ever_ins = 1'b0;
    reg         pre_flush = 1'b1;

    assign hit = hit_q;
    assign addr = addr_q;
    assign partner = partner_q;

    // parallel search, lowest matching index wins
    reg       m_hit;
    reg [5:0] m_addr;
    reg [7:0] m_partner;
    reg [7:0] sel;
    integer i;
    always @(*) begin
        m_hit = 1'b0;
        m_addr = 6'd0;
        m_partner = 8'd0;
        sel = 8'd0;
        for (i = 47; i >= 0; i = i - 1) begin
            sel = (op == 2'b01) ? val_mem[i*8 +: 8] : key_mem[i*8 +: 8];
            if (valid[i] && (sel == din_a)) begin
                m_hit = 1'b1;
                m_addr = i;
                m_partner = (op == 2'b01) ? key_mem[i*8 +: 8] : val_mem[i*8 +: 8];
            end
        end
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            valid <= 48'd0;
            hit_q <= 1'b0;
            addr_q <= 6'd0;
            partner_q <= 8'd0;
            ever_ins <= 1'b0;
            pre_flush <= 1'b1;
            wr_ptr <= 6'd0;
        end else if (en) begin
            case (op)
                2'b00, 2'b01: begin
                    hit_q <= m_hit;
                    addr_q <= m_addr;
                    partner_q <= m_partner;
                end
                2'b10: begin
                    key_mem[wr_ptr*8 +: 8] <= din_a;
                    val_mem[wr_ptr*8 +: 8] <= din_b;
                    valid[wr_ptr] <= 1'b1;
                    ever_ins <= 1'b1;
                    wr_ptr <= (wr_ptr == 6'd47) ? 6'd0 : wr_ptr + 6'd1;
                end
                default: begin
                    valid <= 48'd0;
                    hit_q <= 1'b0;
                    ever_ins <= 1'b0;
                    pre_flush <= 1'b0;
                end
            endcase
        end
    end

    // Precedence: before the first flush, a registered hit requires a prior insert
    always @(posedge clk)
        assert (!(pre_flush && hit_q) || ever_ins);
endmodule

module mempool_bank_rdata_mux (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req_valid,
    input wire [3:0] req_bank,
    input wire [255:0] bank_rdata,
    output reg [15:0] rdata,
    output wire rvalid,
    output wire [15:0] o_rsp_cnt
);
    reg v_q0, v_q1, v_q2;
    reg [3:0] idx_q0, idx_q1, idx_q2;
    reg [15:0] sel_q0, sel_q1, sel_q2;
    reg [15:0] rsp_cnt;

    initial begin
        v_q0 = 1'b0; v_q1 = 1'b0; v_q2 = 1'b0;
        idx_q0 = 4'd0; idx_q1 = 4'd0; idx_q2 = 4'd0;
        sel_q0 = 16'h0000; sel_q1 = 16'h0000; sel_q2 = 16'h0000;
        rsp_cnt = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            v_q0 <= 1'b0; v_q1 <= 1'b0; v_q2 <= 1'b0;
            idx_q0 <= 4'd0; idx_q1 <= 4'd0; idx_q2 <= 4'd0;
            sel_q0 <= 16'h0000; sel_q1 <= 16'h0000; sel_q2 <= 16'h0000;
            rsp_cnt <= 16'd0;
        end else if (en) begin
            v_q0 <= req_valid;
            idx_q0 <= req_bank;
            sel_q0 <= req_valid ? (16'h0001 << req_bank) : 16'h0000;
            v_q1 <= v_q0;
            idx_q1 <= idx_q0;
            sel_q1 <= sel_q0;
            v_q2 <= v_q1;
            idx_q2 <= idx_q1;
            sel_q2 <= sel_q1;
            if (v_q2)
                rsp_cnt <= rsp_cnt + 16'd1;
        end
    end

    integer b;
    always @(*) begin
        rdata = 16'h0000;
        for (b = 0; b < 16; b = b + 1)
            if (sel_q2[b])
                rdata = rdata | bank_rdata[b*16 +: 16];
    end

    assign rvalid = v_q2;
    assign o_rsp_cnt = rsp_cnt;

    always @(posedge clk)
        assert ((sel_q2 & (sel_q2 - 16'h0001)) == 16'h0000);
endmodule

module chipkill_decoder (
    input wire clk,
    input wire i_ce,
    input wire i_scrub,
    input wire [31:0] i_data,
    input wire [31:0] i_chk,
    output wire [31:0] o_data,
    output wire o_uncorr,
    output wire o_fail_valid,
    output wire [1:0] o_fail_id
);
    reg [31:0] syn;
    reg [31:0] dat;
    reg [3:0] fail_oh;
    reg [1:0] fail_id;
    reg fail_valid;
    reg uncorr;
    reg armed;
    initial begin
        syn = 32'h0; dat = 32'h0; fail_oh = 4'd0; fail_id = 2'd0;
        fail_valid = 1'b0; uncorr = 1'b0; armed = 1'b0;
    end

    wire [31:0] s = i_data ^ i_chk;
    wire e0 = |s[7:0];
    wire e1 = |s[15:8];
    wire e2 = |s[23:16];
    wire e3 = |s[31:24];
    wire [2:0] nerr = {2'b00, e0} + {2'b00, e1} + {2'b00, e2} + {2'b00, e3};
    wire [1:0] c = e3 ? 2'd3 : (e2 ? 2'd2 : (e1 ? 2'd1 : 2'd0));
    wire any_err = (nerr != 3'd0);
    wire mark = !fail_valid && (nerr == 3'd1);
    wire bad = (nerr > 3'd1) || (fail_valid && (nerr == 3'd1) && (c != fail_id));

    always @(posedge clk) begin
        if (i_scrub) begin
            syn <= 32'h0;
            fail_oh <= 4'd0;
            fail_id <= 2'd0;
            fail_valid <= 1'b0;
            uncorr <= 1'b0;
        end else if (i_ce) begin
            syn <= s;
            dat <= i_data;
            if (any_err) armed <= 1'b1;
            if (mark) begin
                fail_valid <= 1'b1;
                fail_id <= c;
                fail_oh <= fail_oh | (4'd1 << c);
            end
            if (bad) uncorr <= 1'b1;
        end
    end

    wire [31:0] chip_mask = fail_valid ? (32'h000000FF << {fail_id, 3'b000}) : 32'h0;
    assign o_data = dat ^ (syn & chip_mask);
    assign o_uncorr = uncorr;
    assign o_fail_valid = fail_valid;
    assign o_fail_id = fail_id;

    always @(posedge clk)
        if (armed)
            assert ((fail_oh & (fail_oh - 4'd1)) == 4'd0);
endmodule

module ptw_walker (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_start,
    input  wire [15:0] i_va,
    input  wire [15:0] i_root,
    input  wire        i_mem_valid,
    input  wire [15:0] i_mem_data,
    input  wire        i_ack,
    output wire        o_mem_req,
    output wire [15:0] o_mem_addr,
    output wire        o_done,
    output wire        o_fault,
    output wire [15:0] o_pa
);
    localparam [1:0]  S_IDLE = 2'd0;
    localparam [1:0]  S_WALK = 2'd1;
    localparam [1:0]  S_DONE = 2'd2;
    localparam [15:0] LAST_LVL = 16'd3;

    reg [1:0]  state   = S_IDLE;
    reg [15:0] lvl     = 16'd0;
    reg [15:0] reads   = 16'd0;
    reg [15:0] desc    = 16'd0;
    reg [15:0] va      = 16'd0;
    reg [15:0] walk_id = 16'd0;
    reg        fault   = 1'b0;
    reg        armed   = 1'b0;
    reg        pv      = 1'b0;

    wire [3:0] idx = (lvl == 16'd0) ? va[15:12] :
                     (lvl == 16'd1) ? va[11:8]  :
                     (lvl == 16'd2) ? va[7:4]   : va[3:0];

    assign o_mem_req  = (state == S_WALK);
    assign o_mem_addr = {desc[15:4], idx};
    assign o_done     = (state == S_DONE);
    assign o_fault    = fault;
    assign o_pa       = {desc[15:4], va[3:0]};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE;
            fault <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_start) begin
                        state   <= S_WALK;
                        lvl     <= 16'd0;
                        reads   <= 16'd0;
                        desc    <= i_root;
                        va      <= i_va;
                        walk_id <= walk_id + 16'd1;
                        fault   <= 1'b0;
                        armed   <= 1'b1;
                    end
                end
                S_WALK: begin
                    if (i_mem_valid) begin
                        reads <= reads + 16'd1;
                        desc  <= i_mem_data;
                        if (!i_mem_data[0] || (!i_mem_data[1] && lvl == LAST_LVL)) begin
                            fault <= 1'b1;
                            state <= S_DONE;
                        end else if (i_mem_data[1]) begin
                            state <= S_DONE;
                        end else begin
                            lvl <= lvl + 16'd1;
                        end
                    end
                end
                S_DONE: begin
                    if (i_ack) state <= S_IDLE;
                end
                default: state <= S_IDLE;
            endcase
        end
    end

    always @(posedge clk)
        if (armed && pv && $stable(walk_id) && $past(reads) >= 16'd4)
            assert ($stable(reads));
endmodule

module mpop_fifo (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire push,
    input wire [31:0] din,
    input wire [2:0] npop_req,
    input wire open,
    input wire close,
    output reg [31:0] dout0,
    output reg [31:0] dout1,
    output reg [31:0] dout2,
    output reg [31:0] dout3,
    output wire [2:0] npop_o,
    output wire [31:0] count_o
);
    reg [31:0] bank0 [0:3];
    reg [31:0] bank1 [0:3];
    reg [31:0] bank2 [0:3];
    reg [31:0] bank3 [0:3];
    integer k;
    initial begin
        for (k = 0; k < 4; k = k + 1) begin
            bank0[k] = 32'd0; bank1[k] = 32'd0; bank2[k] = 32'd0; bank3[k] = 32'd0;
        end
    end

    reg [4:0] wptr = 5'd0;
    reg [4:0] rptr = 5'd0;
    reg [31:0] count = 32'd0;
    reg win = 1'b0;
    reg push_ack = 1'b0;

    wire [4:0] occ = wptr - rptr;
    wire full = (occ >= 5'd16);
    wire do_push = push && !full;
    wire [2:0] req = (npop_req > 3'd4) ? 3'd4 : npop_req;
    wire [2:0] npop = ({2'b00, req} > occ) ? occ[2:0] : req;
    assign npop_o = npop;
    assign count_o = count;

    wire [3:0] i0 = rptr[3:0];
    wire [3:0] i1 = rptr[3:0] + 4'd1;
    wire [3:0] i2 = rptr[3:0] + 4'd2;
    wire [3:0] i3 = rptr[3:0] + 4'd3;

    always @(*) begin
        case (i0[1:0])
            2'd0: dout0 = bank0[i0[3:2]];
            2'd1: dout0 = bank1[i0[3:2]];
            2'd2: dout0 = bank2[i0[3:2]];
            default: dout0 = bank3[i0[3:2]];
        endcase
        case (i1[1:0])
            2'd0: dout1 = bank0[i1[3:2]];
            2'd1: dout1 = bank1[i1[3:2]];
            2'd2: dout1 = bank2[i1[3:2]];
            default: dout1 = bank3[i1[3:2]];
        endcase
        case (i2[1:0])
            2'd0: dout2 = bank0[i2[3:2]];
            2'd1: dout2 = bank1[i2[3:2]];
            2'd2: dout2 = bank2[i2[3:2]];
            default: dout2 = bank3[i2[3:2]];
        endcase
        case (i3[1:0])
            2'd0: dout3 = bank0[i3[3:2]];
            2'd1: dout3 = bank1[i3[3:2]];
            2'd2: dout3 = bank2[i3[3:2]];
            default: dout3 = bank3[i3[3:2]];
        endcase
    end

    always @(posedge clk) begin
        if (ce && do_push) begin
            case (wptr[1:0])
                2'd0: bank0[wptr[3:2]] <= din;
                2'd1: bank1[wptr[3:2]] <= din;
                2'd2: bank2[wptr[3:2]] <= din;
                default: bank3[wptr[3:2]] <= din;
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 5'd0;
            rptr <= 5'd0;
            count <= 32'd0;
            win <= 1'b0;
            push_ack <= 1'b0;
        end else if (ce) begin
            wptr <= wptr + {4'd0, do_push};
            rptr <= rptr + {2'd0, npop};
            count <= count + {31'd0, do_push} - {29'd0, npop};
            push_ack <= do_push;
            if (open) win <= 1'b1;
            else if (close) win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && $rose(push_ack))
            assert (count <= 32'd16);
endmodule

module stream_demux16 (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        in_valid,
    input  wire [3:0]  in_sel,
    input  wire [31:0] in_data,
    output wire        in_ready,
    output wire [15:0] out_valid,
    input  wire [15:0] out_ready,
    output wire [31:0] out_data
);
    reg [3:0]  sel_q   = 4'd0;
    reg [15:0] vld_q   = 16'd0;
    reg [31:0] data_q  = 32'd0;
    reg [31:0] acc_cnt = 32'd0;
    reg [31:0] dlv_cnt = 32'd0;
    reg        armed   = 1'b0;

    wire deliver = i_ce && vld_q[sel_q] && out_ready[sel_q];
    assign in_ready = (vld_q == 16'd0) || (vld_q[sel_q] && out_ready[sel_q]);
    wire accept  = i_ce && in_valid && in_ready;

    always @(posedge clk) begin
        if (rst) begin
            sel_q   <= 4'd0;
            vld_q   <= 16'd0;
            data_q  <= 32'd0;
            acc_cnt <= 32'd0;
            dlv_cnt <= 32'd0;
        end else if (i_ce) begin
            if (deliver) begin
                vld_q   <= 16'd0;
                dlv_cnt <= dlv_cnt + 32'd1;
            end
            if (accept) begin
                sel_q   <= in_sel;
                data_q  <= in_data;
                vld_q   <= (16'd1 << in_sel);
                acc_cnt <= acc_cnt + 32'd1;
                armed   <= 1'b1;
            end
        end
    end

    assign out_valid = vld_q;
    assign out_data  = data_q;

    assert property (!armed || ((acc_cnt - dlv_cnt) <= 32'd1));
endmodule

module stepper_seq (
    input wire clk,
    input wire i_ce,
    input wire i_open,
    input wire i_close,
    input wire i_arm,
    input wire i_start,
    input wire [7:0] i_rate,
    input wire i_wr,
    input wire [2:0] i_waddr,
    input wire [127:0] i_wdata,
    output wire [127:0] o_coil,
    output wire o_done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [1:0] fsm = S_IDLE;
    reg win = 1'b0;
    reg arm_seen = 1'b0;
    reg start_seen = 1'b0;
    reg [2:0] phase = 3'd0;
    reg [7:0] div = 8'd0;
    reg [7:0] rate = 8'd0;

    reg [127:0] pat [0:7];
    integer k;
    initial for (k = 0; k < 8; k = k + 1) pat[k] = 128'd1 << (k * 16);

    always @(posedge clk)
        if (i_ce && i_wr && !win)
            pat[i_waddr] <= i_wdata;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!win) begin
                if (i_open) begin
                    win <= 1'b1;
                    fsm <= S_IDLE;
                    arm_seen <= 1'b0;
                    start_seen <= 1'b0;
                    phase <= 3'd0;
                    div <= 8'd0;
                end
            end else if (i_close) begin
                win <= 1'b0;
            end else begin
                case (fsm)
                    S_IDLE: if (i_arm) begin
                        fsm <= S_ARMED;
                        arm_seen <= 1'b1;
                        rate <= i_rate;
                    end
                    S_ARMED: if (i_start) begin
                        fsm <= S_RUN;
                        start_seen <= 1'b1;
                        div <= 8'd0;
                    end
                    S_RUN: begin
                        if (div == rate) begin
                            div <= 8'd0;
                            phase <= phase + 3'd1;
                            if (phase == 3'd7)
                                fsm <= S_DONE;
                        end else begin
                            div <= div + 8'd1;
                        end
                    end
                    default: if (i_arm) begin
                        fsm <= S_ARMED;
                        start_seen <= 1'b0;
                        rate <= i_rate;
                    end
                endcase
            end
        end
    end

    assign o_coil = pat[phase];
    assign o_done = (fsm == S_DONE);

    always @(*) if (win && fsm == S_DONE) assert (start_seen);
    always @(*) if (win && start_seen) assert (arm_seen);
endmodule

module range_mask_insert (
    input  wire        clk,
    input  wire        req,
    input  wire        ce,
    input  wire [4:0]  i_start,
    input  wire [4:0]  i_end,
    input  wire [31:0] i_src,
    output wire [31:0] mask,
    output reg  [31:0] dst,
    output reg         busy
);
    reg [4:0]  start_idx = 5'd0;
    reg [4:0]  end_idx   = 5'd0;
    reg [4:0]  cur       = 5'd0;
    reg [31:0] timer     = 32'd0;
    reg [31:0] src       = 32'd0;
    reg        arm       = 1'b0;
    initial busy = 1'b0;
    initial dst  = 32'd0;

    // contiguous range mask decoder: bits start_idx..end_idx asserted
    assign mask = (32'hFFFFFFFF << start_idx) & (32'hFFFFFFFF >> (5'd31 - end_idx));

    wire [4:0] off = cur - start_idx;

    always @(posedge clk) begin
        if (!busy) begin
            if (req && (i_start <= i_end)) begin
                start_idx <= i_start;
                end_idx   <= i_end;
                cur       <= i_start;
                src       <= i_src;
                busy      <= 1'b1;
                timer     <= 32'd32;
                arm       <= 1'b1;
            end
        end else if (ce) begin
            dst[cur] <= src[off];
            timer    <= timer - 32'd1;
            if (cur == end_idx)
                busy <= 1'b0;
            else
                cur <= cur + 5'd1;
        end
    end

    always @(*) assert (!arm || !busy || (timer != 32'd0));
endmodule

module relo_belt (
    input wire clk,
    input wire rst,
    input wire en,
    input wire drop,
    input wire [63:0] din,
    input wire [4:0] rd_pos,
    input wire ckpt_open,
    input wire ckpt_close,
    output wire [63:0] dout
);
    reg [63:0] slot [0:31];
    reg [4:0] head;
    reg [63:0] drops;
    reg [63:0] win_cnt;
    reg win;
    integer i;

    initial begin
        for (i = 0; i < 32; i = i + 1)
            slot[i] = 64'd0;
        head = 5'd0;
        drops = 64'd0;
        win_cnt = 64'd0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 32; i = i + 1)
                slot[i] <= 64'd0;
            head <= 5'd0;
            drops <= 64'd0;
            win_cnt <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (drop) begin
                slot[head] <= din;
                head <= head + 5'd1;
                drops <= drops + 64'd1;
                if (win)
                    win_cnt <= win_cnt + 64'd1;
            end
            if (ckpt_close) begin
                win <= 1'b0;
            end else if (ckpt_open) begin
                win <= 1'b1;
                win_cnt <= 64'd0;
            end
        end
    end

    assign dout = slot[head - 5'd1 - rd_pos];

    always @(posedge clk)
        if (win && !rst)
            assert (head == drops[4:0]);
endmodule

module tb_drv_demux (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire         i_req,
    input  wire [3:0]   i_sel,
    input  wire [15:0]  i_data,
    output wire [255:0] o_bus,
    output wire         o_busy
);
    localparam [15:0] K = 16'd8;

    reg [3:0]   sel_r;
    reg [15:0]  data_r;
    reg [255:0] out_q;
    reg         pending;
    reg [15:0]  cnt;
    reg [15:0]  ph;

    initial sel_r   = 4'd0;
    initial data_r  = 16'd0;
    initial out_q   = 256'd0;
    initial pending = 1'b0;
    initial cnt     = 16'd0;
    initial ph      = 16'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            sel_r   <= 4'd0;
            data_r  <= 16'd0;
            out_q   <= 256'd0;
            pending <= 1'b0;
            cnt     <= 16'd0;
            ph      <= 16'd0;
        end else if (i_ce) begin
            if (!pending) begin
                if (i_req) begin
                    pending <= 1'b1;
                    sel_r   <= i_sel;
                    data_r  <= i_data;
                    cnt     <= K;
                    ph      <= 16'd0;
                end
            end else begin
                if (ph == K - 16'd1) begin
                    out_q[sel_r*16 +: 16] <= data_r;
                    pending <= 1'b0;
                    cnt     <= 16'd0;
                    ph      <= 16'd0;
                end else begin
                    ph  <= ph + 16'd1;
                    cnt <= cnt - 16'd1;
                end
            end
        end
    end

    assign o_bus  = out_q;
    assign o_busy = pending;

    assert property (!pending || cnt != 16'd0);
endmodule

module wal_quad_probe (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [63:0] x_in,
    input  wire        cap_req,
    input  wire        stop,
    output reg         done,
    output wire [63:0] i_out,
    output wire [63:0] q
);
    reg [63:0] d0, d1, d2, d3;
    reg [63:0] i_dly;
    reg [63:0] q_out;
    reg [63:0] cnt;
    reg [2:0]  fill;
    reg        pending;
    reg        win;

    initial begin
        d0 = 64'd0; d1 = 64'd0; d2 = 64'd0; d3 = 64'd0;
        i_dly = 64'd0; q_out = 64'd0; cnt = 64'd0;
        fill = 3'd0; pending = 1'b0; win = 1'b0; done = 1'b0;
    end

    assign i_out = i_dly;
    assign q = q_out;

    always @(posedge clk) begin
        if (rst) begin
            d0 <= 64'd0; d1 <= 64'd0; d2 <= 64'd0; d3 <= 64'd0;
            i_dly <= 64'd0; q_out <= 64'd0; cnt <= 64'd0;
            fill <= 3'd0; pending <= 1'b0; win <= 1'b0; done <= 1'b0;
        end else if (en) begin
            d0 <= x_in;
            d1 <= d0;
            d2 <= d1;
            d3 <= d2;
            i_dly <= d1;
            q_out <= (d0 - d3) + 64'd3 * (d1 - d2);
            done <= 1'b0;
            if (cap_req && !pending) begin
                pending <= 1'b1;
                fill    <= 3'd0;
                cnt     <= 64'd5;
                win     <= 1'b1;
            end else begin
                if (stop)
                    win <= 1'b0;
                if (pending) begin
                    if (fill + 3'd1 == 3'd4) begin
                        pending <= 1'b0;
                        cnt     <= 64'd0;
                        fill    <= 3'd4;
                        done    <= 1'b1;
                    end else begin
                        fill <= fill + 3'd1;
                        cnt  <= cnt - 64'd1;
                    end
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && (cnt == 64'd0) && !$past(cnt == 64'd0))
            assert (!pending);
endmodule

module lane_deskew4 (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [255:0] din,
    input  wire [3:0]   mk,
    output wire [255:0] dout,
    output wire         aligned_o,
    output wire         timeout_o
);
    reg [63:0] fifo [0:31];
    reg [11:0] wptr;
    reg [11:0] rptr;
    reg [3:0]  seen;
    reg        aligned;
    reg        win;
    reg [63:0] cd;
    reg        timeout;

    integer k;
    initial begin
        for (k = 0; k < 32; k = k + 1) fifo[k] = 64'd0;
        wptr = 12'd0; rptr = 12'd0; seen = 4'd0;
        aligned = 1'b0; win = 1'b0; cd = 64'd0; timeout = 1'b0;
    end

    wire       q        = !win && !aligned && (|mk);
    wire       force_mk = win && !aligned && (cd == 64'd1);
    wire [3:0] seen_n   = force_mk ? 4'hF : (seen | mk);

    integer i;
    always @(posedge clk) begin
        if (!rst_n) begin
            wptr <= 12'd0; rptr <= 12'd0; seen <= 4'd0;
            aligned <= 1'b0; win <= 1'b0; cd <= 64'd0; timeout <= 1'b0;
        end else if (en) begin
            for (i = 0; i < 4; i = i + 1) begin
                fifo[i*8 + wptr[i*3 +: 3]] <= din[i*64 +: 64];
                wptr[i*3 +: 3] <= wptr[i*3 +: 3] + 3'd1;
                if (aligned) rptr[i*3 +: 3] <= rptr[i*3 +: 3] + 3'd1;
            end
            seen    <= seen_n;
            timeout <= timeout | (win && !aligned && (cd == 64'd0));
            if (seen_n == 4'hF) begin
                aligned <= 1'b1;
                win     <= 1'b0;
                cd      <= 64'd0;
            end else if (q) begin
                win <= 1'b1;
                cd  <= 64'd8;
            end else if (win && !aligned) begin
                cd <= cd - 64'd1;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < 4; g = g + 1) begin : g_out
            assign dout[g*64 +: 64] = fifo[g*8 + rptr[g*3 +: 3]];
        end
    endgenerate

    assign aligned_o = aligned;
    assign timeout_o = timeout;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && win && !aligned && $stable(aligned))
            assert ($stable(timeout));
endmodule

module degate_trng_health (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [127:0] sample
);
    reg [127:0] last_smp = 128'd0;
    reg [127:0] ref_smp  = 128'd0;
    reg [127:0] hist [0:7];
    reg [2:0]   rep_cnt  = 3'd0;
    reg [2:0]   win_cnt  = 3'd0;
    reg [3:0]   apt_cnt  = 4'd0;
    reg         alarm    = 1'b0;
    reg         armed    = 1'b0;
    reg         pv       = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            hist[i] = 128'd0;
    end

    wire       rep_match = (sample == last_smp);
    wire [2:0] rep_nxt   = rep_match ? ((rep_cnt == 3'd7) ? 3'd7 : rep_cnt + 3'd1) : 3'd0;

    reg [3:0] apt_nxt;
    reg [2:0] win_nxt;
    always @(*) begin
        if (win_cnt == 3'd0) begin
            apt_nxt = 4'd1;
            win_nxt = 3'd1;
        end else if (win_cnt == 3'd7) begin
            apt_nxt = 4'd0;
            win_nxt = 3'd0;
        end else begin
            apt_nxt = apt_cnt + ((sample == ref_smp) ? 4'd1 : 4'd0);
            win_nxt = win_cnt + 3'd1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            last_smp <= 128'd0;
            ref_smp  <= 128'd0;
            rep_cnt  <= 3'd0;
            win_cnt  <= 3'd0;
            apt_cnt  <= 4'd0;
            alarm    <= 1'b0;
            armed    <= 1'b0;
        end else if (en) begin
            hist[win_cnt] <= sample;
            last_smp <= sample;
            rep_cnt  <= rep_nxt;
            if (win_cnt == 3'd0)
                ref_smp <= sample;
            apt_cnt  <= apt_nxt;
            win_cnt  <= win_nxt;
            if (rep_nxt >= 3'd5 || apt_nxt >= 4'd6)
                alarm <= 1'b1;
            if (win_cnt == 3'd7)
                armed <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (pv && !rst && armed && $stable(alarm))
            assert (!(apt_cnt[3] && win_cnt != 3'd0));
    end
endmodule

module tap_delay_chain (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire [31:0] cfg_tap,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    // 12-stage x 32-bit data chain plus a parallel marker chain
    reg [383:0] chain;
    reg [11:0]  mark;
    reg [31:0]  tap;
    reg [1:0]   phase;
    reg         started;
    reg         q_seen;

    initial chain   = 384'd0;
    initial mark    = 12'h000;
    initial tap     = 32'd0;
    initial phase   = IDLE;
    initial started = 1'b0;
    initial q_seen  = 1'b0;

    wire tap_ok   = (tap < 32'd12);
    wire tap_mark = tap_ok ? mark[tap[3:0]] : 1'b0;
    assign dout   = tap_ok ? chain[{tap[3:0], 5'b00000} +: 32] : 32'd0;
    assign done   = (phase == DONE);

    wire go_arm    = ce && (phase == IDLE) && arm;
    wire go_finish = ce && ((phase == ARMED) || (phase == RUN)) && tap_mark;
    wire go_start  = ce && (phase == ARMED) && start && !tap_mark;

    always @(posedge clk) begin
        if (ce) begin
            chain <= {chain[351:0], din};
            mark  <= {mark[10:0], go_start};
        end
        if (go_arm) begin
            phase  <= ARMED;
            q_seen <= 1'b1;
            tap    <= (cfg_tap < 32'd12) ? cfg_tap : 32'd11;
        end else if (go_finish) begin
            phase <= DONE;
        end else if (go_start) begin
            phase   <= RUN;
            started <= 1'b1;
        end
    end

    // after the first arm: finish is never observed unless start happened
    always @(posedge clk)
        if (q_seen) assert (phase != DONE || started);
endmodule

module pipe_ao22_track (
    input  wire        clk,
    input  wire        rst,
    input  wire        step,
    input  wire        in_valid,
    input  wire [31:0] din,
    input  wire        open_win,
    input  wire        close_win,
    output wire [31:0] dout,
    output wire        dout_valid
);
    reg        v1;
    reg [31:0] s1;
    reg        v2;
    reg [31:0] s2;
    reg        seen_in;
    reg [31:0] in_cnt;
    reg        armed;

    initial v1 = 1'b0;
    initial s1 = 32'd0;
    initial v2 = 1'b0;
    initial s2 = 32'd0;
    initial seen_in = 1'b0;
    initial in_cnt = 32'd0;
    initial armed = 1'b0;

    wire [31:0] s1_next;
    wire [31:0] s2_next;

    ao22 #(.W(32)) u_s1 (
        .a({32{in_valid}}), .b(din),
        .c({32{~in_valid}}), .d(s1),
        .y(s1_next)
    );

    ao22 #(.W(32)) u_s2 (
        .a({32{v1}}), .b(s1),
        .c({32{~v1}}), .d(s2),
        .y(s2_next)
    );

    assign dout = s2;
    assign dout_valid = v2;

    always @(posedge clk) begin
        if (rst) begin
            v1 <= 1'b0;
            s1 <= 32'd0;
            v2 <= 1'b0;
            s2 <= 32'd0;
            seen_in <= 1'b0;
            in_cnt <= 32'd0;
            armed <= 1'b0;
        end else if (step) begin
            v1 <= in_valid;
            s1 <= s1_next;
            v2 <= v1;
            s2 <= s2_next;
            seen_in <= seen_in | in_valid;
            if (in_valid && (in_cnt != 32'hFFFFFFFF))
                in_cnt <= in_cnt + 32'd1;
            if (open_win)
                armed <= 1'b1;
            else if (close_win)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed && v2) assert (seen_in);

    always @(posedge clk)
        if (armed && v2) assert (in_cnt != 32'd0);
endmodule

module ao22 #(parameter W = 32) (
    input  wire [W-1:0] a,
    input  wire [W-1:0] b,
    input  wire [W-1:0] c,
    input  wire [W-1:0] d,
    output wire [W-1:0] y
);
    assign y = (a & b) | (c & d);
endmodule

module sd_host_blk (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cmd_start,
    input wire [63:0] cmd_arg,
    input wire resp_valid,
    input wire [63:0] resp_in,
    input wire data_valid,
    input wire [63:0] data_in,
    input wire [1:0] rd_idx,
    output wire o_busy,
    output wire [63:0] o_resp,
    output wire [63:0] o_arg,
    output wire [63:0] o_data,
    output wire [63:0] o_words_done
);
    localparam [63:0] BLK_WORDS = 64'd8;

    reg [63:0] arg_reg;
    reg [63:0] resp_reg;
    reg        busy;
    reg [63:0] words_done;
    reg [63:0] words_left;
    reg [63:0] fifo [0:3];
    reg        armed;
    reg        pv;

    initial begin
        arg_reg = 64'd0;
        resp_reg = 64'd0;
        busy = 1'b0;
        words_done = 64'd0;
        words_left = BLK_WORDS;
        fifo[0] = 64'd0;
        fifo[1] = 64'd0;
        fifo[2] = 64'd0;
        fifo[3] = 64'd0;
        armed = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk) begin
        if (en) begin
            pv <= 1'b1;
            if (rst) begin
                words_done <= 64'd0;
                words_left <= BLK_WORDS;
                busy <= 1'b0;
                armed <= 1'b0;
            end else begin
                if (resp_valid) begin
                    resp_reg <= resp_in;
                    armed <= 1'b1;
                end
                if (cmd_start && !busy) begin
                    arg_reg <= cmd_arg;
                    words_done <= 64'd0;
                    words_left <= BLK_WORDS;
                    busy <= 1'b1;
                end else if (busy) begin
                    if (data_valid && words_left != 64'd0) begin
                        fifo[words_done[1:0]] <= data_in;
                        words_done <= words_done + 64'd1;
                        words_left <= words_left - 64'd1;
                    end
                    if (words_left == 64'd0)
                        busy <= 1'b0;
                end
            end
        end
    end

    assign o_busy = busy;
    assign o_resp = resp_reg;
    assign o_arg = arg_reg;
    assign o_data = fifo[rd_idx];
    assign o_words_done = words_done;

    always @(posedge clk)
        if (pv && $past(armed))
            assert ($past(words_done) <= 64'd8);
endmodule

module norm32 (
    input wire clk,
    input wire en,
    input wire arm,
    input wire load,
    input wire start,
    input wire ack,
    input wire [31:0] din,
    input wire [31:0] ein,
    output wire done,
    output wire [31:0] mant_o,
    output wire [31:0] exp_o
);
    reg [1:0] phase = 2'd0;
    reg [31:0] mant = 32'd0;
    reg [31:0] exp_r = 32'd0;
    reg [5:0] shamt = 6'd0;
    reg armed_f = 1'b0;
    reg started_f = 1'b0;
    reg q_seen = 1'b0;
    reg pv = 1'b0;

    assign done = (phase == 2'd3);
    assign mant_o = mant;
    assign exp_o = exp_r;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            q_seen <= q_seen | load;
            case (phase)
                2'd0: begin
                    if (arm) begin
                        mant <= din;
                        exp_r <= ein;
                        shamt <= 6'd0;
                        armed_f <= 1'b1;
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    if (start) begin
                        started_f <= 1'b1;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    if (mant[31] || (mant == 32'd0) || (shamt >= 6'd32)) begin
                        exp_r <= exp_r - {26'd0, shamt};
                        phase <= 2'd3;
                    end else begin
                        mant <= {mant[30:0], 1'b0};
                        shamt <= shamt + 6'd1;
                    end
                end
                2'd3: begin
                    if (ack) begin
                        armed_f <= 1'b0;
                        started_f <= 1'b0;
                        phase <= 2'd0;
                    end
                end
            endcase
        end
    end

    always @(posedge clk)
        if (pv && q_seen && $past(q_seen) && $past(phase) == 2'd3)
            assert ($past(armed_f) && $past(started_f));
endmodule

module zynq_pwr_dom (
    input  wire       clk,
    input  wire       en,
    input  wire       req_on,
    input  wire       req_off,
    input  wire [6:0] idx,
    output wire       root_ready,
    output wire       busy
);
    reg [127:0] dom_on;
    reg [7:0]   refcnt;
    reg         root_on;
    reg         pend;
    reg [7:0]   prog;
    reg [7:0]   cd;
    reg         first_n;
    reg         pv;

    initial dom_on  = 128'd0;
    initial refcnt  = 8'd0;
    initial root_on = 1'b0;
    initial pend    = 1'b0;
    initial prog    = 8'd0;
    initial cd      = 8'd0;
    initial first_n = 1'b1;
    initial pv      = 1'b0;

    wire do_on  = req_on && !req_off;
    wire do_off = req_off && !req_on && !pend;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (pend) begin
                prog <= prog + 8'd1;
                cd   <= cd - 8'd1;
                if (prog == 8'd19) begin
                    pend    <= 1'b0;
                    root_on <= 1'b1;
                end
            end
            if (do_on && !dom_on[idx]) begin
                dom_on[idx] <= 1'b1;
                refcnt      <= refcnt + 8'd1;
                if (refcnt == 8'd0 && !root_on && !pend) begin
                    pend <= 1'b1;
                    prog <= 8'd0;
                    cd   <= 8'd24;
                end
            end else if (do_off && dom_on[idx]) begin
                dom_on[idx] <= 1'b0;
                refcnt      <= refcnt - 8'd1;
                if (refcnt == 8'd1 && root_on) begin
                    root_on <= 1'b0;
                    first_n <= 1'b0;
                end
            end
        end
    end

    assign root_ready = root_on;
    assign busy       = pend;

    always @(posedge clk)
        if (pv && first_n && pend && $stable(pend))
            assert ($stable(cd == 8'd0) && cd != 8'd0);
endmodule

module lfsr_gpio (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr_out,
    input wire wr_dir,
    input wire wr_lock,
    input wire wr_unlock,
    input wire [31:0] wdata,
    input wire [31:0] pins_in,
    input wire sample,
    output reg [31:0] pin_drive,
    output reg [33:0] box_sum
);
    reg [31:0] out_data;
    reg [31:0] dir;
    reg [31:0] cap0;
    reg [31:0] cap1;
    reg [31:0] cap2;
    reg        lock_win;
    reg        pv;

    initial out_data  = 32'h0000_0000;
    initial dir       = 32'h0000_0000;
    initial pin_drive = 32'h0000_0000;
    initial cap0      = 32'h0000_0000;
    initial cap1      = 32'h0000_0000;
    initial cap2      = 32'h0000_0000;
    initial box_sum   = 34'h0_0000_0000;
    initial lock_win  = 1'b0;
    initial pv        = 1'b0;

    wire [31:0] nxt_out = wr_out ? wdata : out_data;
    wire [31:0] nxt_dir = wr_dir ? wdata : dir;
    wire [31:0] new_cap = pins_in & ~dir;

    always @(posedge clk) begin
        if (rst) begin
            out_data  <= 32'h0000_0000;
            dir       <= 32'h0000_0000;
            pin_drive <= 32'h0000_0000;
            cap0      <= 32'h0000_0000;
            cap1      <= 32'h0000_0000;
            cap2      <= 32'h0000_0000;
            box_sum   <= 34'h0_0000_0000;
            lock_win  <= 1'b0;
        end else if (en) begin
            out_data  <= nxt_out;
            dir       <= nxt_dir;
            pin_drive <= nxt_out & nxt_dir;
            if (sample) begin
                cap0    <= new_cap;
                cap1    <= cap0;
                cap2    <= cap1;
                box_sum <= box_sum + {2'b00, new_cap} - {2'b00, cap2};
            end
            if (wr_unlock)
                lock_win <= 1'b0;
            else if (wr_lock)
                lock_win <= 1'b1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && lock_win && $past(lock_win) && $stable(out_data) && $stable(dir))
            assert ($stable(pin_drive));
endmodule

module forth_rng_word (
    input  wire       clk,
    input  wire       ce,
    input  wire       go,
    output wire [7:0] rnd,
    output reg        busy
);
    reg [7:0] prng;
    reg [7:0] cd;
    reg [7:0] steps;
    initial begin prng = 8'h5A; cd = 8'd0; steps = 8'd0; busy = 1'b0; end

    // 8-bit xorshift (7,5,3)
    wire [7:0] x1 = prng ^ (prng << 7);
    wire [7:0] x2 = x1 ^ (x1 >> 5);
    wire [7:0] x3 = x2 ^ (x2 << 3);

    assign rnd = prng;

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (go) begin
                    busy  <= 1'b1;
                    steps <= 8'd0;
                    cd    <= 8'd8;
                end
            end else begin
                prng <= x3;
                cd   <= cd - 8'd1;
                if (steps == 8'd7)
                    busy <= 1'b0;
                else
                    steps <= steps + 8'd1;
            end
        end
    end

    // countdown never expires while the request is outstanding
    always @(posedge clk)
        if (busy)
            assert (cd != 8'd0);

    // on the final shift round, exactly one tick of budget remains
    always @(posedge clk)
        if (busy && steps == 8'd7)
            assert (cd == 8'd1);
endmodule

module udp_keccak_tagger (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        in_valid,
    input  wire        in_last,
    input  wire [15:0] in_data,
    input  wire        go,
    input  wire        ack,
    output wire [15:0] tag,
    output reg         done,
    output wire        busy
);
    localparam [1:0] P_IDLE = 2'd0, P_ARMED = 2'd1, P_RUN = 2'd2, P_DONE = 2'd3;

    reg [255:0] st;
    reg [3:0]   absorb_ptr;
    reg [4:0]   rnd;
    reg [1:0]   phase;
    reg         armed_flg;
    reg         started_flg;
    reg         seen_q;
    reg         done_q;

    initial begin
        st = 256'd0;
        absorb_ptr = 4'd0;
        rnd = 5'd0;
        phase = P_IDLE;
        armed_flg = 1'b0;
        started_flg = 1'b0;
        seen_q = 1'b0;
        done = 1'b0;
        done_q = 1'b0;
    end

    function [15:0] rotl;
        input [15:0] a;
        input [3:0]  r;
        begin
            rotl = (a << r) | (a >> (5'd16 - {1'b0, r}));
        end
    endfunction

    wire [15:0] rc = (16'h1 << rnd[3:0]) ^ {11'd0, rnd} ^ 16'h8081;

    reg [63:0]  C, D;
    reg [255:0] A1, B, nxt;
    integer x, y, i;

    always @(*) begin
        C = 64'd0;
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                C[16*x +: 16] = C[16*x +: 16] ^ st[16*(x+4*y) +: 16];
        for (x = 0; x < 4; x = x + 1)
            D[16*x +: 16] = C[16*((x+3)%4) +: 16] ^ rotl(C[16*((x+1)%4) +: 16], 4'd1);
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                A1[16*(x+4*y) +: 16] = st[16*(x+4*y) +: 16] ^ D[16*x +: 16];
        B = 256'd0;
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                B[16*(y+4*((x+3*y)%4)) +: 16] = rotl(A1[16*(x+4*y) +: 16], (((x+4*y)*(x+4*y+1))/2) % 16);
        for (x = 0; x < 4; x = x + 1)
            for (y = 0; y < 4; y = y + 1)
                nxt[16*(x+4*y) +: 16] = B[16*(x+4*y) +: 16] ^ ((~B[16*(((x+1)%4)+4*y) +: 16]) & B[16*(((x+2)%4)+4*y) +: 16]);
        nxt[15:0] = nxt[15:0] ^ rc;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            st <= 256'd0;
            absorb_ptr <= 4'd0;
            rnd <= 5'd0;
            phase <= P_IDLE;
            armed_flg <= 1'b0;
            started_flg <= 1'b0;
            seen_q <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            case (phase)
                P_IDLE: begin
                    if (in_valid) begin
                        for (i = 0; i < 16; i = i + 1)
                            if (i == absorb_ptr)
                                st[16*i +: 16] <= st[16*i +: 16] ^ in_data;
                        if (in_last) begin
                            phase <= P_ARMED;
                            armed_flg <= 1'b1;
                            seen_q <= 1'b1;
                            absorb_ptr <= 4'd0;
                        end else begin
                            absorb_ptr <= absorb_ptr + 4'd1;
                        end
                    end
                end
                P_ARMED: begin
                    if (go) begin
                        phase <= P_RUN;
                        rnd <= 5'd0;
                        started_flg <= 1'b1;
                    end
                end
                P_RUN: begin
                    st <= nxt;
                    if (rnd == 5'd23) begin
                        phase <= P_DONE;
                        done <= 1'b1;
                    end else begin
                        rnd <= rnd + 5'd1;
                    end
                end
                P_DONE: begin
                    if (ack) begin
                        phase <= P_IDLE;
                        done <= 1'b0;
                        armed_flg <= 1'b0;
                        started_flg <= 1'b0;
                        st <= 256'd0;
                    end
                end
            endcase
        end
    end

    always @(posedge clk) done_q <= done;

    assign tag  = st[15:0];
    assign busy = (phase == P_RUN);

    reg pv;
    initial pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && seen_q && done && !done_q)
            assert (armed_flg && started_flg);
endmodule

module awesome_frame_sync (
    input wire clk,
    input wire rst,
    input wire en,
    input wire hdr_ok,
    input wire win_clr,
    output reg [1:0] state
);
    localparam [1:0] HUNT = 2'd0, PRESYNC = 2'd1, SYNC = 2'd2;
    reg [31:0] good_cnt;
    reg [31:0] bad_cnt;
    reg [3:0]  bad_hist;
    reg        win;
    initial begin
        state = HUNT; good_cnt = 32'd0; bad_cnt = 32'd0; bad_hist = 4'd0; win = 1'b0;
    end

    wire q_evt = en && (state == PRESYNC) && hdr_ok && (good_cnt == 32'd2);

    always @(posedge clk) begin
        if (rst) begin
            state <= HUNT; good_cnt <= 32'd0; bad_cnt <= 32'd0; bad_hist <= 4'd0; win <= 1'b0;
        end else if (en) begin
            if (win_clr) win <= 1'b0;
            else if (q_evt) win <= 1'b1;
            case (state)
                HUNT: begin
                    if (hdr_ok) begin
                        state <= PRESYNC;
                        good_cnt <= 32'd1;
                    end
                end
                PRESYNC: begin
                    if (hdr_ok) begin
                        if (good_cnt == 32'd2) begin
                            state <= SYNC;
                            good_cnt <= 32'd0;
                            bad_cnt <= 32'd0;
                            bad_hist <= 4'd0;
                        end else begin
                            good_cnt <= good_cnt + 32'd1;
                        end
                    end else begin
                        state <= HUNT;
                        good_cnt <= 32'd0;
                        bad_cnt <= 32'd0;
                        bad_hist <= 4'd0;
                    end
                end
                SYNC: begin
                    if (hdr_ok) begin
                        bad_cnt <= 32'd0;
                        bad_hist <= {bad_hist[2:0], 1'b0};
                    end else if (bad_hist[2:0] == 3'b111) begin
                        state <= HUNT;
                        bad_cnt <= 32'd0;
                        bad_hist <= 4'd0;
                    end else begin
                        bad_cnt <= bad_cnt + 32'd1;
                        bad_hist <= {bad_hist[2:0], 1'b1};
                    end
                end
                default: begin
                    state <= HUNT;
                    good_cnt <= 32'd0;
                    bad_cnt <= 32'd0;
                    bad_hist <= 4'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (win && state == 2'd2)
            assert (bad_cnt <= 32'd3);
endmodule

module trace_buffer (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_trig,
    input  wire        i_flush,
    input  wire [63:0] i_sample,
    input  wire [5:0]  i_raddr,
    output wire [63:0] o_rdata,
    output wire        o_done,
    output wire [5:0]  o_trig_pos
);
    localparam [63:0] POST     = 64'd12;
    localparam [5:0]  DEPTH_M1 = 6'd47;

    reg [63:0] mem [0:47];
    reg [5:0]  wptr       = 6'd0;
    reg [5:0]  trig_pos   = 6'd0;
    reg        triggered  = 1'b0;
    reg        done       = 1'b0;
    reg [63:0] remaining  = 64'd0;
    reg [63:0] post_count = 64'd0;
    reg        no_abort   = 1'b1;
    reg        pv         = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 48; i = i + 1) mem[i] = 64'd0;
    end

    wire [5:0] wptr_nxt = (wptr == DEPTH_M1) ? 6'd0 : wptr + 6'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_flush) begin
                triggered  <= 1'b0;
                done       <= 1'b0;
                remaining  <= 64'd0;
                post_count <= 64'd0;
                no_abort   <= 1'b0;
            end else if (!done) begin
                mem[wptr] <= i_sample;
                wptr      <= wptr_nxt;
                if (!triggered) begin
                    if (i_trig) begin
                        triggered  <= 1'b1;
                        trig_pos   <= wptr;
                        remaining  <= POST;
                        post_count <= 64'd0;
                    end
                end else begin
                    remaining  <= remaining - 64'd1;
                    post_count <= post_count + 64'd1;
                    if (post_count == POST - 64'd1)
                        done <= 1'b1;
                end
            end
        end
    end

    assign o_rdata    = (i_raddr <= DEPTH_M1) ? mem[i_raddr] : 64'd0;
    assign o_done     = done;
    assign o_trig_pos = trig_pos;

    wire expired = (remaining == 64'd0);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && no_abort && $rose(expired))
            assert (done);
endmodule

module mips_i2c_deglitch (
    input wire clk,
    input wire rst,
    input wire en,
    input wire scl_in,
    input wire sda_in,
    input wire cfg_we,
    input wire [7:0] cfg_din,
    output wire scl_o,
    output wire sda_o
);
    reg [3:0] sh_scl = 4'b1111;
    reg [3:0] sh_sda = 4'b1111;
    reg st_scl = 1'b1;
    reg st_sda = 1'b1;
    reg [7:0] cnt_scl = 8'd0;
    reg [7:0] cnt_sda = 8'd0;
    reg [7:0] flen = 8'd3;
    reg armed = 1'b0;
    reg pv = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            sh_scl <= 4'b1111;
            sh_sda <= 4'b1111;
            st_scl <= 1'b1;
            st_sda <= 1'b1;
            cnt_scl <= 8'd0;
            cnt_sda <= 8'd0;
            flen <= 8'd3;
            armed <= 1'b0;
        end else if (en) begin
            sh_scl <= {sh_scl[2:0], scl_in};
            sh_sda <= {sh_sda[2:0], sda_in};
            if (cfg_we) begin
                flen <= (cfg_din > 8'd12) ? 8'd12 : cfg_din;
                cnt_scl <= 8'd0;
                cnt_sda <= 8'd0;
            end else begin
                if (sh_scl[3] != st_scl) begin
                    if (cnt_scl >= flen) begin
                        st_scl <= sh_scl[3];
                        cnt_scl <= 8'd0;
                        if (st_scl && !sh_scl[3])
                            armed <= 1'b1;
                    end else begin
                        cnt_scl <= cnt_scl + 8'd1;
                    end
                end else begin
                    cnt_scl <= 8'd0;
                end
                if (sh_sda[3] != st_sda) begin
                    if (cnt_sda >= flen) begin
                        st_sda <= sh_sda[3];
                        cnt_sda <= 8'd0;
                    end else begin
                        cnt_sda <= cnt_sda + 8'd1;
                    end
                end else begin
                    cnt_sda <= 8'd0;
                end
            end
        end
    end

    assign scl_o = st_scl;
    assign sda_o = st_sda;

    always @(posedge clk)
        if (pv && $past(armed))
            assert ($past(cnt_scl) <= 8'd12 && $past(cnt_sda) <= 8'd12);
endmodule

module sc_park_alu (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire uni_bit,
    input wire util_bit,
    input wire vis_bit,
    input wire win_bit,
    output wire [1:0] o_phase,
    output wire [15:0] o_ones,
    output wire [15:0] o_log0
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    reg [1:0] phase;
    reg arm_seen, start_seen, done_seen;
    reg [15:0] len_cnt;
    reg [15:0] ones_cnt;
    reg [15:0] log_q [0:7];
    reg [2:0] log_ptr;
    integer i;

    initial begin
        phase = IDLE;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        done_seen = 1'b0;
        len_cnt = 16'd0;
        ones_cnt = 16'd0;
        log_ptr = 3'd0;
        for (i = 0; i < 8; i = i + 1) log_q[i] = 16'd0;
    end

    wire m = uni_bit & util_bit;
    wire s = win_bit ? vis_bit : m;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done_seen <= 1'b0;
            len_cnt <= 16'd0;
            ones_cnt <= 16'd0;
            log_ptr <= 3'd0;
            for (i = 0; i < 8; i = i + 1) log_q[i] <= 16'd0;
        end else if (en) begin
            case (phase)
                IDLE: begin
                    if (arm_req) begin
                        phase <= ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (start_req) begin
                        phase <= RUN;
                        start_seen <= 1'b1;
                        len_cnt <= 16'd0;
                        ones_cnt <= 16'd0;
                    end
                end
                RUN: begin
                    len_cnt <= len_cnt + 16'd1;
                    ones_cnt <= ones_cnt + {15'd0, s};
                    if (len_cnt == 16'd699) begin
                        phase <= DONE;
                        done_seen <= 1'b1;
                        log_q[log_ptr] <= ones_cnt;
                        log_ptr <= log_ptr + 3'd1;
                    end
                end
                DONE: begin
                    if (arm_req) phase <= ARMED;
                end
            endcase
        end
    end

    assign o_phase = phase;
    assign o_ones = ones_cnt;
    assign o_log0 = log_q[0];

    always @(posedge clk)
        assert ((!done_seen || start_seen) && (!start_seen || arm_seen));
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module dnn_wfuse_ctrl (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire prog_req,
    input wire [2:0] prog_addr,
    input wire [31:0] prog_data,
    input wire lock_req,
    input wire sense_req,
    output wire [31:0] o_rd_data,
    output wire o_locked
);
    localparam [1:0] S_IDLE = 2'd0, S_BURN = 2'd1, S_SENSE = 2'd2;

    reg [31:0] fuse_shadow [0:7];
    reg [7:0]  prog_done;
    reg [31:0] prog_cnt;
    reg [1:0]  fsm;
    reg        pre_lock;
    reg [2:0]  burn_addr;
    reg [31:0] burn_data;
    reg [31:0] rd_data;

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) fuse_shadow[i] = 32'd0;
        prog_done = 8'd0;
        prog_cnt  = 32'd0;
        fsm       = S_IDLE;
        pre_lock  = 1'b1;
        burn_addr = 3'd0;
        burn_data = 32'd0;
        rd_data   = 32'd0;
    end

    wire [3:0] done_pop = prog_done[0] + prog_done[1] + prog_done[2] + prog_done[3]
                        + prog_done[4] + prog_done[5] + prog_done[6] + prog_done[7];

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) fuse_shadow[i] <= 32'd0;
            prog_done <= 8'd0;
            prog_cnt  <= 32'd0;
            fsm       <= S_IDLE;
            pre_lock  <= 1'b1;
            burn_addr <= 3'd0;
            burn_data <= 32'd0;
            rd_data   <= 32'd0;
        end else if (en) begin
            if (lock_req)
                pre_lock <= 1'b0;
            case (fsm)
                S_IDLE: begin
                    if (pre_lock && prog_req && !prog_done[prog_addr]) begin
                        burn_addr <= prog_addr;
                        burn_data <= prog_data;
                        fsm       <= S_BURN;
                    end else if (!pre_lock && sense_req) begin
                        burn_addr <= prog_addr;
                        fsm       <= S_SENSE;
                    end
                end
                S_BURN: begin
                    fuse_shadow[burn_addr] <= burn_data;
                    prog_done[burn_addr]   <= 1'b1;
                    prog_cnt               <= prog_cnt + 32'd1;
                    fsm                    <= S_IDLE;
                end
                S_SENSE: begin
                    rd_data  <= fuse_shadow[burn_addr];
                    prog_cnt <= prog_cnt + 32'd1;
                    fsm      <= S_IDLE;
                end
                default: fsm <= S_IDLE;
            endcase
        end
    end

    assign o_rd_data = rd_data;
    assign o_locked  = !pre_lock;

    always @(posedge clk)
        assert (!pre_lock || prog_cnt <= 32'd8);
endmodule

module ft60x_axi_default_slave (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire       arvalid,
    input  wire [7:0] arid,
    input  wire [7:0] arlen,
    input  wire       rready,
    input  wire       awvalid,
    input  wire [7:0] awid,
    input  wire       wvalid,
    input  wire       wlast,
    input  wire       bready,
    output wire       arready,
    output wire       rvalid,
    output wire [1:0] rresp,
    output wire       rlast,
    output wire [7:0] rid,
    output wire       awready,
    output wire       wready,
    output wire       bvalid,
    output wire [1:0] bresp,
    output wire [7:0] bid
);
    reg [7:0] rid_q   = 8'd0;
    reg [7:0] len_q   = 8'd0;
    reg [7:0] sent_q  = 8'd0;
    reg       busy    = 1'b0;
    reg       rbeat_q = 1'b0;
    reg       win     = 1'b0;
    reg [7:0] bid_q   = 8'd0;
    reg       wact    = 1'b0;
    reg       bpend   = 1'b0;

    assign arready = en & ~busy;
    assign rvalid  = en & busy;
    assign rresp   = 2'b11;
    assign rlast   = ((sent_q + 8'd1) == len_q);
    assign rid     = rid_q;
    assign awready = en & ~bpend & ~wact;
    assign wready  = en & wact;
    assign bvalid  = en & bpend;
    assign bresp   = 2'b11;
    assign bid     = bid_q;

    wire ar_hs = arvalid & arready;
    wire r_hs  = rvalid & rready;
    wire aw_hs = awvalid & awready;
    wire w_hs  = wvalid & wready;
    wire b_hs  = bvalid & bready;

    always @(posedge clk) begin
        if (!rst_n) begin
            rid_q   <= 8'd0;
            len_q   <= 8'd0;
            sent_q  <= 8'd0;
            busy    <= 1'b0;
            rbeat_q <= 1'b0;
            win     <= 1'b0;
            bid_q   <= 8'd0;
            wact    <= 1'b0;
            bpend   <= 1'b0;
        end else if (en) begin
            rbeat_q <= r_hs;
            if (ar_hs) begin
                rid_q  <= arid;
                len_q  <= ((arlen > 8'd15) ? 8'd15 : arlen) + 8'd1;
                sent_q <= 8'd0;
                busy   <= 1'b1;
                win    <= 1'b1;
            end else if (r_hs) begin
                if (rlast) begin
                    busy   <= 1'b0;
                    sent_q <= 8'd0;
                    win    <= 1'b0;
                end else begin
                    sent_q <= sent_q + 8'd1;
                end
            end
            if (aw_hs) begin
                bid_q <= awid;
                wact  <= 1'b1;
            end
            if (w_hs && wlast) begin
                wact  <= 1'b0;
                bpend <= 1'b1;
            end
            if (b_hs)
                bpend <= 1'b0;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && rst_n && win && $rose(rbeat_q))
            assert (sent_q <= 8'd16);
endmodule

module monocle_bscan (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire        capture,
    input  wire        update,
    input  wire        shift,
    input  wire        tdi,
    input  wire [23:0] pins_in,
    output wire        tdo,
    output wire [23:0] pins_out
);
    reg [23:0] shift_reg   = 24'd0;
    reg [23:0] update_reg  = 24'd0;
    reg [15:0] shifted_cnt = 16'd0;
    reg [15:0] remain_cnt  = 16'd24;
    reg        armed       = 1'b0;

    assign tdo      = shift_reg[0];
    assign pins_out = update_reg;

    wire frame_full  = (remain_cnt == 16'd0);
    wire frame_empty = (shifted_cnt == 16'd0);

    always @(posedge clk) begin
        if (!rst_n) begin
            shift_reg   <= 24'd0;
            update_reg  <= 24'd0;
            shifted_cnt <= 16'd0;
            remain_cnt  <= 16'd24;
            armed       <= 1'b0;
        end else if (en) begin
            if (capture) begin
                shift_reg   <= pins_in;
                shifted_cnt <= 16'd0;
                remain_cnt  <= 16'd24;
                armed       <= 1'b1;
            end else if (update) begin
                update_reg  <= shift_reg;
                shifted_cnt <= 16'd0;
                remain_cnt  <= 16'd24;
            end else if (shift && (remain_cnt != 16'd0)) begin
                shift_reg   <= {tdi, shift_reg[23:1]};
                shifted_cnt <= shifted_cnt + 16'd1;
                remain_cnt  <= remain_cnt - 16'd1;
            end
        end
    end

    always @(*)
        if (armed)
            assert (!(frame_full && frame_empty));
endmodule

module axi_goertzel_bin (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire b_ready,
    input wire clr,
    input wire [15:0] sample,
    input wire [15:0] coef_in,
    output reg done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUNNING = 2'd2, DONE = 2'd3;

    reg [1:0] phase = 2'd0;
    reg signed [15:0] s1 = 16'sd0;
    reg signed [15:0] s2 = 16'sd0;
    reg [15:0] cnt = 16'd0;
    reg [15:0] coef = 16'd0;
    reg armed_seen = 1'b0;
    reg started_seen = 1'b0;
    reg before_clr = 1'b1;
    initial done = 1'b0;

    wire signed [31:0] prod = $signed(coef) * s1;
    wire signed [31:0] fb = prod >>> 14;
    wire signed [15:0] s1_next = $signed(sample) + fb[15:0] - s2;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            s1 <= 16'sd0;
            s2 <= 16'sd0;
            cnt <= 16'd0;
            coef <= 16'd0;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            before_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase <= ARMED;
                        coef <= coef_in;
                        armed_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (start) begin
                        phase <= RUNNING;
                        started_seen <= 1'b1;
                        cnt <= 16'd0;
                        s1 <= 16'sd0;
                        s2 <= 16'sd0;
                    end
                end
                RUNNING: begin
                    s1 <= s1_next;
                    s2 <= s1;
                    if (cnt == 16'd23) begin
                        phase <= DONE;
                        done <= 1'b1;
                    end else begin
                        cnt <= cnt + 16'd1;
                    end
                end
                DONE: begin
                    if (b_ready) begin
                        phase <= IDLE;
                        done <= 1'b0;
                    end
                end
            endcase
            if (clr) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                before_clr <= 1'b0;
            end
        end
    end

    always @(*) assert (!before_clr || !done || (started_seen && armed_seen));
endmodule

module lim_mod_fold (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    input wire vld,
    input wire [63:0] chunk,
    output wire [15:0] res,
    output wire done
);
    localparam [63:0] M = 64'd65521;

    function [63:0] two64;
        input [31:0] dummy;
        integer i;
        reg [63:0] r;
        begin
            r = 64'd1;
            for (i = 0; i < 64; i = i + 1)
                r = (r * 64'd2) % M;
            two64 = r;
        end
    endfunction

    localparam [63:0] K = two64(0);

    function [63:0] kpow;
        input [31:0] n;
        integer i;
        reg [63:0] r;
        begin
            r = 64'd1;
            for (i = 0; i < n; i = i + 1)
                r = (r * K) % M;
            kpow = r;
        end
    endfunction

    localparam [63:0] C = kpow(256);

    reg [63:0] acc;
    reg [63:0] wreg;
    reg [8:0]  idx;
    reg        armed;
    initial acc = 64'd0;
    initial wreg = 64'd1;
    initial idx = 9'd0;
    initial armed = 1'b0;

    wire [64*257-1:0] wflat;
    genvar g;
    generate
        for (g = 0; g < 257; g = g + 1) begin : G_ROM
            localparam [63:0] WV = kpow(g);
            assign wflat[g*64 +: 64] = WV;
        end
    endgenerate

    wire [63:0] wexp = wflat[idx*64 +: 64];

    always @(posedge clk) begin
        if (rst) begin
            acc   <= 64'd0;
            wreg  <= 64'd1;
            idx   <= 9'd0;
            armed <= 1'b0;
        end else if (en) begin
            if (start) begin
                acc   <= 64'd0;
                wreg  <= 64'd1;
                idx   <= 9'd0;
                armed <= 1'b1;
            end else if (vld && (idx < 9'd256)) begin
                acc  <= (acc + (chunk % M) * wreg) % M;
                wreg <= (wreg * K) % M;
                idx  <= idx + 9'd1;
            end
        end
    end

    assign res  = acc[15:0];
    assign done = (idx == 9'd256);

    always @(posedge clk)
        if (armed && idx == 9'd256)
            assert (wreg == C);
endmodule

module lvds_port_perfmon (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         valid,
    input  wire         ready,
    input  wire [127:0] data,
    input  wire         win_start,
    output wire [31:0]  o_txn_cnt,
    output wire [35:0]  o_byte_cnt,
    output wire [31:0]  o_stall_cnt,
    output wire [47:0]  o_lat_cum,
    output wire [15:0]  o_win_cnt
);
    wire hs    = en & valid & ready;
    wire stall = en & valid & ~ready;

    reg [31:0] txn_cnt   = 32'd0;
    reg        hs_d      = 1'b0;
    reg [35:0] byte_cnt  = 36'd0;
    reg [31:0] stall_cnt = 32'd0;
    reg [15:0] lat_cur   = 16'd0;
    reg [47:0] lat_cum   = 48'd0;
    reg [15:0] win_cnt   = 16'd0;
    reg        armed     = 1'b0;
    reg        seen_txn  = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            txn_cnt   <= 32'd0;
            hs_d      <= 1'b0;
            byte_cnt  <= 36'd0;
            stall_cnt <= 32'd0;
            lat_cur   <= 16'd0;
            lat_cum   <= 48'd0;
            win_cnt   <= 16'd0;
            armed     <= 1'b0;
            seen_txn  <= 1'b0;
        end else if (en) begin
            hs_d <= hs;
            if (hs) begin
                txn_cnt  <= txn_cnt + 32'd1;
                seen_txn <= 1'b1;
                lat_cum  <= lat_cum + {32'd0, lat_cur};
                lat_cur  <= 16'd0;
            end else if (valid) begin
                lat_cur  <= lat_cur + 16'd1;
            end
            if (hs_d)
                byte_cnt <= byte_cnt + 36'd16;
            if (stall)
                stall_cnt <= stall_cnt + 32'd1;
            if (win_start) begin
                win_cnt <= 16'd0;
                armed   <= 1'b1;
            end else begin
                win_cnt <= win_cnt + 16'd1;
            end
        end
    end

    assign o_txn_cnt   = txn_cnt;
    assign o_byte_cnt  = byte_cnt;
    assign o_stall_cnt = stall_cnt;
    assign o_lat_cum   = lat_cum;
    assign o_win_cnt   = win_cnt;

    always @(posedge clk)
        if (armed && byte_cnt != 36'd0)
            assert (seen_txn);
endmodule

module jk_bounded_resp (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    output reg         busy,
    output reg  [63:0] work,
    output reg  [63:0] timer
);
    localparam [63:0] LEN = 64'd12;

    initial busy  = 1'b0;
    initial work  = 64'd0;
    initial timer = 64'd0;

    // JK latch inputs: J accepts a request, K signals completion
    wire j = start && !busy;
    wire k = busy && (work == 64'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy  <= 1'b0;
            work  <= 64'd0;
            timer <= 64'd0;
        end else if (ce) begin
            // gated JK latch: set / reset / invert while enabled, hold otherwise
            case ({j, k})
                2'b10:   busy <= 1'b1;
                2'b01:   busy <= 1'b0;
                2'b11:   busy <= ~busy;
                default: busy <= busy;
            endcase
            if (j) begin
                work  <= LEN;
                timer <= LEN + 64'd1;
            end else if (busy) begin
                if (work != 64'd0)
                    work <= work - 64'd1;
                timer <= timer - 64'd1;
            end
        end
    end

    // bounded response: countdown never expires while request outstanding
    always @(posedge clk)
        assert (!(busy && timer == 64'd0));
endmodule

module farrow_apb_bridge (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire hwr,
    input wire [31:0] hwdata,
    input wire hmu_wr,
    input wire [31:0] hmu,
    input wire pread,
    output wire [31:0] prdata
);
    reg [31:0] x0, x1, x2, x3;
    reg [31:0] c0, c1, c2, c3;
    reg [31:0] mu;
    reg [31:0] fill_cnt;
    reg out_valid;
    reg [31:0] y;
    reg hist_wr;

    initial begin
        x0 = 32'd0; x1 = 32'd0; x2 = 32'd0; x3 = 32'd0;
        c0 = 32'd0; c1 = 32'd0; c2 = 32'd0; c3 = 32'd0;
        mu = 32'd0; fill_cnt = 32'd0; out_valid = 1'b0;
        y = 32'd0; hist_wr = 1'b0;
    end

    // cubic Lagrange sub-filter taps (truncated arithmetic)
    wire [31:0] d02  = x0 - x2;
    wire [31:0] t1   = $signed(d02) >>> 1;
    wire [31:0] x1m5 = x1 * 32'd5;
    wire [31:0] t2   = x2 - ($signed(x1m5) >>> 1) + (x0 << 1);
    wire [31:0] s3   = (x3 - x0) + ((x1 - x2) * 32'd3);
    wire [31:0] t3   = $signed(s3) >>> 1;

    // Horner evaluation in Q0.32 mu
    wire [63:0] p3 = {32'd0, c3} * {32'd0, mu};
    wire [31:0] h3 = p3[63:32] + c2;
    wire [63:0] p2 = {32'd0, h3} * {32'd0, mu};
    wire [31:0] h2 = p2[63:32] + c1;
    wire [63:0] p1 = {32'd0, h2} * {32'd0, mu};
    wire [31:0] y_next = p1[63:32] + c0;

    wire rd_done = pread && (fill_cnt == 32'd4);

    always @(posedge clk) begin
        if (!rst_n) begin
            x0 <= 32'd0; x1 <= 32'd0; x2 <= 32'd0; x3 <= 32'd0;
            c0 <= 32'd0; c1 <= 32'd0; c2 <= 32'd0; c3 <= 32'd0;
            mu <= 32'd0; fill_cnt <= 32'd0; out_valid <= 1'b0;
            y <= 32'd0; hist_wr <= 1'b0;
        end else if (en) begin
            if (hwr) begin
                x3 <= x2;
                x2 <= x1;
                x1 <= x0;
                x0 <= hwdata;
                fill_cnt <= (fill_cnt >= 32'd4) ? 32'd4 : fill_cnt + 32'd1;
                hist_wr <= 1'b1;
            end
            c0 <= x1;
            c1 <= t1;
            c2 <= t2;
            c3 <= t3;
            if (hmu_wr)
                mu <= hmu;
            out_valid <= rd_done;
            if (rd_done)
                y <= y_next;
        end
    end

    assign prdata = y;

    always @(posedge clk)
        if (out_valid)
            assert (hist_wr);
endmodule

module round_disp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [34:0] din,
    input wire [1:0] mode_in,
    output reg [6:0] seg
);
    reg [31:0] trunc = 32'd0;
    reg [2:0]  grs = 3'b000;
    reg [1:0]  mode = 2'd0;
    reg [31:0] rounded = 32'd0;
    reg        armed = 1'b0;
    reg        pv = 1'b0;

    function inc_f;
        input [1:0] m;
        input [2:0] g;
        input lsb;
        begin
            case (m)
                2'd0: inc_f = g[2] & (g[1] | g[0] | lsb);
                2'd1: inc_f = 1'b0;
                2'd2: inc_f = g[2] | g[1] | g[0];
                default: inc_f = g[2];
            endcase
        end
    endfunction

    wire ld_inc = inc_f(mode_in, din[2:0], din[3]);
    wire rf_inc = inc_f(mode, grs, trunc[0]);

    always @(posedge clk) begin
        if (rst) begin
            trunc   <= 32'd0;
            grs     <= 3'b000;
            mode    <= 2'd0;
            rounded <= 32'd0;
            armed   <= 1'b0;
        end else if (en) begin
            if (load) begin
                trunc   <= din[34:3];
                grs     <= din[2:0];
                mode    <= mode_in;
                rounded <= din[34:3] + {31'd0, ld_inc};
                armed   <= 1'b1;
            end else begin
                rounded <= trunc + {31'd0, rf_inc};
            end
        end
    end

    always @(*) begin
        case (rounded[3:0])
            4'h0: seg = 7'b1111110;
            4'h1: seg = 7'b0110000;
            4'h2: seg = 7'b1101101;
            4'h3: seg = 7'b1111001;
            4'h4: seg = 7'b0110011;
            4'h5: seg = 7'b1011011;
            4'h6: seg = 7'b1011111;
            4'h7: seg = 7'b1110000;
            4'h8: seg = 7'b1111111;
            4'h9: seg = 7'b1111011;
            4'hA: seg = 7'b1110111;
            4'hB: seg = 7'b0011111;
            4'hC: seg = 7'b1001110;
            4'hD: seg = 7'b0111101;
            4'hE: seg = 7'b1001111;
            default: seg = 7'b1000111;
        endcase
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && !$past(rst) && armed && $stable(trunc) && $stable(grs) && $stable(mode))
            assert ($stable(rounded));
endmodule

module sevenseg_scan_mux (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_wr,
    input  wire [4:0]  i_waddr,
    input  wire [31:0] i_wdata,
    output reg  [6:0]  o_seg,
    output wire [31:0] o_anode
);
    // digit-index counter and one-hot digit drive (anode) register
    reg [31:0] dig_idx = 32'd0;
    reg [31:0] anode   = 32'h00000001;
    // shadow: digit 16 has been driven during this (first) frame
    reg        visited_hi = 1'b0;
    // scope register: high until the scan first wraps from digit 31 to 0
    reg        armed = 1'b1;
    // per-digit value registers
    reg [31:0] digit_val [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            digit_val[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (i_reset) begin
            dig_idx    <= 32'd0;
            anode      <= 32'h00000001;
            visited_hi <= 1'b0;
            armed      <= 1'b1;
        end else if (i_ce) begin
            if (dig_idx == 32'd31) begin
                dig_idx <= 32'd0;
                armed   <= 1'b0;
            end else begin
                dig_idx <= dig_idx + 32'd1;
            end
            anode <= {anode[30:0], anode[31]};
            if (anode[16])
                visited_hi <= 1'b1;
        end
    end

    always @(posedge clk)
        if (i_wr)
            digit_val[i_waddr] <= i_wdata;

    wire [31:0] cur_val = digit_val[dig_idx[4:0]];
    wire [3:0]  nib     = cur_val[3:0];

    always @(*) begin
        case (nib)
            4'h0: o_seg = 7'b1000000;
            4'h1: o_seg = 7'b1111001;
            4'h2: o_seg = 7'b0100100;
            4'h3: o_seg = 7'b0110000;
            4'h4: o_seg = 7'b0011001;
            4'h5: o_seg = 7'b0010010;
            4'h6: o_seg = 7'b0000010;
            4'h7: o_seg = 7'b1111000;
            4'h8: o_seg = 7'b0000000;
            4'h9: o_seg = 7'b0010000;
            4'hA: o_seg = 7'b0001000;
            4'hB: o_seg = 7'b0000011;
            4'hC: o_seg = 7'b1000110;
            4'hD: o_seg = 7'b0100001;
            4'hE: o_seg = 7'b0000110;
            default: o_seg = 7'b0001110;
        endcase
    end

    assign o_anode = ~anode;

    // Precedence, before first wrap: driving the last digit requires digit 16 to have been driven earlier
    always @(*)
        assert (!(armed && anode[31]) || visited_hi);
endmodule

module r2sdf_stage (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [63:0] x_in,
    output reg  [63:0] y_out,
    output reg         y_valid
);
    // single-delay-feedback memory: N/2 = 64 entries
    reg [63:0] dly [0:63];
    reg [63:0] ptr;       // stage control counter (0..63)
    reg        phase;     // 0 = fill, 1 = compute (butterfly)
    reg [63:0] bfly_cnt;  // butterflies issued
    reg        armed;     // high until the first frame's compute pass completes
    integer i;

    initial begin
        ptr = 64'd0; phase = 1'b0; bfly_cnt = 64'd0; armed = 1'b1;
        y_out = 64'd0; y_valid = 1'b0;
        for (i = 0; i < 64; i = i + 1) dly[i] = 64'd0;
    end

    wire [5:0]  idx    = ptr[5:0];
    wire [63:0] fb     = dly[idx];
    wire [63:0] bf_sum = fb + x_in;
    wire [63:0] bf_dif = fb - x_in;
    wire        last   = (ptr == 64'd63);

    always @(posedge clk) begin
        if (rst) begin
            ptr <= 64'd0; phase <= 1'b0; bfly_cnt <= 64'd0; armed <= 1'b1;
            y_out <= 64'd0; y_valid <= 1'b0;
        end else if (en) begin
            if (phase) begin
                // compute: butterfly between delayed sample and new sample
                dly[idx] <= bf_dif;
                y_out    <= bf_sum;
                bfly_cnt <= bfly_cnt + 64'd1;
                if (last) armed <= 1'b0;
            end else begin
                // fill: push new sample into delay line, drain previous differences
                dly[idx] <= x_in;
                y_out    <= fb;
            end
            y_valid <= 1'b1;
            if (last) begin
                ptr   <= 64'd0;
                phase <= ~phase;
            end else begin
                ptr <= ptr + 64'd1;
            end
        end
    end

    // before the first frame completes, at most 63 butterflies have been issued
    always @(posedge clk) if (armed) assert (bfly_cnt <= 64'd63);
endmodule

module pin_bist (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    output wire busy,
    output reg fail
);
    localparam [127:0] PAT = "PIN_UART_A15____";

    reg [127:0] mem [0:15];
    reg [3:0] addr = 4'd0;
    reg [1:0] phase = 2'd0;
    reg [6:0] countdown = 7'd0;
    reg win = 1'b0;
    initial fail = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            mem[i] = 128'd0;
    end

    assign busy = win;

    wire [5:0] pa = {phase, addr};
    wire [127:0] rd = mem[addr];
    wire [127:0] exp_rd = (phase == 2'd2) ? ~PAT : PAT;
    wire [127:0] wr = (phase == 2'd1) ? ~PAT : PAT;
    wire do_read = (phase != 2'd0);
    wire do_write = (phase != 2'd3);

    always @(posedge clk) begin
        if (!rst && en && win && do_write)
            mem[addr] <= wr;
    end

    always @(posedge clk) begin
        if (rst) begin
            win <= 1'b0;
            countdown <= 7'd0;
            addr <= 4'd0;
            phase <= 2'd0;
            fail <= 1'b0;
        end else if (en) begin
            if (!win) begin
                if (start) begin
                    win <= 1'b1;
                    countdown <= 7'd64;
                    addr <= 4'd0;
                    phase <= 2'd0;
                    fail <= 1'b0;
                end
            end else begin
                if (do_read && (rd != exp_rd))
                    fail <= 1'b1;
                {phase, addr} <= pa + 6'd1;
                if (pa == 6'd63) begin
                    win <= 1'b0;
                    countdown <= 7'd0;
                end else begin
                    countdown <= countdown - 7'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    wire cd_zero = (countdown == 7'd0);

    always @(posedge clk) begin
        if (pv && !rst && win && $stable(win))
            assert ($stable(cd_zero));
    end
endmodule

module wl_decim48 (
    input wire clk,
    input wire rst,
    input wire en,
    input wire flush,
    input wire [63:0] din,
    output wire [63:0] o_dout,
    output wire o_tick
);
    localparam [5:0]  LAST = 6'd47;
    localparam [63:0] WIN  = 64'd48;

    reg [5:0]  phase;
    reg [63:0] acc;
    reg [63:0] dout;
    reg [63:0] in_cnt;
    reg [63:0] out_cnt;
    reg        tick;
    reg        pre_flush;
    reg        pv;

    initial begin
        phase = 6'd0;
        acc = 64'd0;
        dout = 64'd0;
        in_cnt = 64'd0;
        out_cnt = 64'd0;
        tick = 1'b0;
        pre_flush = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            phase <= 6'd0;
            acc <= 64'd0;
            dout <= 64'd0;
            in_cnt <= 64'd0;
            out_cnt <= 64'd0;
            tick <= 1'b0;
            pre_flush <= 1'b1;
        end else if (en) begin
            if (flush) begin
                phase <= 6'd0;
                acc <= 64'd0;
                tick <= 1'b0;
                pre_flush <= 1'b0;
            end else begin
                in_cnt <= in_cnt + 64'd1;
                if (phase == LAST) begin
                    phase <= 6'd0;
                    dout <= acc + din;
                    acc <= 64'd0;
                    out_cnt <= out_cnt + 64'd1;
                    tick <= 1'b1;
                end else begin
                    phase <= phase + 6'd1;
                    acc <= acc + din;
                    tick <= 1'b0;
                end
            end
        end
    end

    assign o_dout = dout;
    assign o_tick = tick;

    always @(posedge clk)
        if (pv && !rst && pre_flush && $rose(tick))
            assert (in_cnt == WIN * out_cnt);
endmodule

module acc_normalizer (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        load,
    input  wire        shift,
    input  wire [63:0] din,
    output wire [63:0] norm_out,
    output wire [6:0]  exp_adj,
    output wire        done
);
    function [6:0] lzc_tree;
        input [63:0] x;
        reg [31:0] y32;
        reg [15:0] y16;
        reg [7:0]  y8;
        reg [3:0]  y4;
        reg [1:0]  y2;
        reg b5, b4, b3, b2, b1, b0;
        begin
            b5  = ~|x[63:32];
            y32 = b5 ? x[31:0] : x[63:32];
            b4  = ~|y32[31:16];
            y16 = b4 ? y32[15:0] : y32[31:16];
            b3  = ~|y16[15:8];
            y8  = b3 ? y16[7:0] : y16[15:8];
            b2  = ~|y8[7:4];
            y4  = b2 ? y8[3:0] : y8[7:4];
            b1  = ~|y4[3:2];
            y2  = b1 ? y4[1:0] : y4[3:2];
            b0  = ~y2[1];
            if (x == 64'd0)
                lzc_tree = 7'd64;
            else
                lzc_tree = {1'b0, b5, b4, b3, b2, b1, b0};
        end
    endfunction

    reg [63:0] data_r;
    reg [6:0]  lz_r;
    reg        armed_r;
    initial data_r  = 64'd0;
    initial lz_r    = 7'd64;
    initial armed_r = 1'b0;

    wire [6:0] lzc_din = lzc_tree(din);
    wire [6:0] lzc_cur = lzc_tree(data_r);

    always @(posedge clk) begin
        if (rst) begin
            data_r  <= 64'd0;
            lz_r    <= 7'd64;
            armed_r <= 1'b0;
        end else if (en) begin
            if (load) begin
                data_r  <= din;
                lz_r    <= lzc_din;
                armed_r <= 1'b1;
            end else if (shift && lz_r != 7'd0 && lz_r != 7'd64) begin
                data_r <= {data_r[62:0], 1'b0};
                lz_r   <= lz_r - 7'd1;
            end
        end
    end

    assign norm_out = data_r;
    assign exp_adj  = lz_r;
    assign done     = (lz_r == 7'd0);

    always @(*) if (armed_r) assert (!(done && !data_r[63]));
    always @(*) if (armed_r) assert (!(data_r[63] && lz_r != 7'd0));
endmodule

module vcd_tstamp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire snap_req,
    input wire rd_hi,
    output wire [31:0] rdata
);
    reg [31:0] cnt_lo, cnt_hi, snap_lo, snap_hi;
    reg        busy;
    reg [3:0]  cd;
    reg        win;
    reg        latched;

    initial begin
        cnt_lo = 32'd0; cnt_hi = 32'd0;
        snap_lo = 32'd0; snap_hi = 32'd0;
        busy = 1'b0; cd = 4'd0; win = 1'b0; latched = 1'b0;
    end

    wire accept = snap_req && (cd == 4'd0);

    assign rdata = rd_hi ? snap_hi : snap_lo;

    always @(posedge clk) begin
        if (rst) begin
            cnt_lo <= 32'd0; cnt_hi <= 32'd0;
            snap_lo <= 32'd0; snap_hi <= 32'd0;
            busy <= 1'b0; cd <= 4'd0; win <= 1'b0; latched <= 1'b0;
        end else if (en) begin
            cnt_lo <= cnt_lo + 32'd1;
            if (cnt_lo == 32'hFFFFFFFF)
                cnt_hi <= cnt_hi + 32'd1;

            if (accept) begin
                busy    <= 1'b1;
                cd      <= 4'd8;
                latched <= 1'b0;
            end else begin
                if (cd != 4'd0)
                    cd <= cd - 4'd1;
                if (busy && cd == 4'd5) begin
                    snap_lo <= cnt_lo;
                    snap_hi <= cnt_hi;
                    latched <= 1'b1;
                end
                if (busy && cd == 4'd1 && latched) begin
                    busy    <= 1'b0;
                    latched <= 1'b0;
                end
            end

            if (accept)
                win <= 1'b1;
            else if (rd_hi)
                win <= 1'b0;
        end
    end

    always @(posedge clk)
        if (win && busy)
            assert (cd != 4'd0);

    always @(posedge clk)
        if (win && busy)
            assert (cd <= 4'd8);
endmodule

module vcpu_minmax_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        open,
    input  wire        close,
    input  wire        arm,
    input  wire [15:0] a,
    input  wire [15:0] b,
    output reg  [15:0] min_out,
    output reg  [15:0] max_out,
    output reg         rdy
);
    localparam [1:0] S_IDLE     = 2'd0;
    localparam [1:0] S_ARMED    = 2'd1;
    localparam [1:0] S_STARTED  = 2'd2;
    localparam [1:0] S_FINISHED = 2'd3;

    reg [1:0]  st;
    reg        win, f_arm, f_start, f_done;
    reg [15:0] a_q, b_q, lo_q, hi_q;

    initial begin
        st = S_IDLE; win = 1'b0; f_arm = 1'b0; f_start = 1'b0; f_done = 1'b0;
        a_q = 16'd0; b_q = 16'd0; lo_q = 16'd0; hi_q = 16'd0;
        min_out = 16'd0; max_out = 16'd0; rdy = 1'b0;
    end

    // single magnitude decision drives both selections
    wire a_lt_b = (a_q < b_q);

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE; win <= 1'b0; f_arm <= 1'b0; f_start <= 1'b0; f_done <= 1'b0;
            a_q <= 16'd0; b_q <= 16'd0; lo_q <= 16'd0; hi_q <= 16'd0;
            min_out <= 16'd0; max_out <= 16'd0; rdy <= 1'b0;
        end else if (ce) begin
            rdy <= 1'b0;
            if (open && !win && st == S_IDLE) begin
                win     <= 1'b1;
                f_arm   <= 1'b0;
                f_start <= 1'b0;
                f_done  <= 1'b0;
            end else if (close) begin
                win <= 1'b0;
            end
            case (st)
                S_IDLE: if (arm) begin
                    a_q   <= a;
                    b_q   <= b;
                    f_arm <= 1'b1;
                    st    <= S_ARMED;
                end
                S_ARMED: begin
                    lo_q    <= a_lt_b ? a_q : b_q;
                    hi_q    <= a_lt_b ? b_q : a_q;
                    f_start <= 1'b1;
                    st      <= S_STARTED;
                end
                S_STARTED: begin
                    min_out <= lo_q;
                    max_out <= hi_q;
                    rdy     <= 1'b1;
                    f_done  <= 1'b1;
                    st      <= S_FINISHED;
                end
                default: st <= S_IDLE;
            endcase
        end
    end

    // after open until close: a finish is never seen without start and arm before it
    always @(*) assert (!(win && f_done) || (f_start && f_arm));
endmodule

module arrow_bound_cmp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire mode_in,
    input wire [7:0] cnt_in,
    input wire [7:0] len_in,
    output wire o_lt,
    output wire o_eq,
    output wire o_gt
);
    reg mode_r;
    reg [7:0] cnt_r;
    reg [7:0] len_r;
    reg lt_r, eq_r, gt_r;
    reg gt_q;
    initial mode_r = 1'b0;
    initial cnt_r = 8'd0;
    initial len_r = 8'd0;
    initial lt_r = 1'b0;
    initial eq_r = 1'b1;
    initial gt_r = 1'b0;
    initial gt_q = 1'b0;

    wire in_lt = mode_in ? ($signed(cnt_in) < $signed(len_in)) : (cnt_in < len_in);
    wire in_eq = (cnt_in == len_in);
    wire in_gt = !in_lt && !in_eq;

    wire cur_lt = mode_r ? ($signed(cnt_r) < $signed(len_r)) : (cnt_r < len_r);
    wire cur_eq = (cnt_r == len_r);

    wire [7:0] cnt_nx = cnt_r + 8'd1;

    always @(posedge clk) begin
        if (rst) begin
            mode_r <= 1'b0;
            cnt_r <= 8'd0;
            len_r <= 8'd0;
            lt_r <= 1'b0;
            eq_r <= 1'b1;
            gt_r <= 1'b0;
            gt_q <= 1'b0;
        end else if (en) begin
            gt_q <= gt_r;
            if (load) begin
                cnt_r <= cnt_in;
                len_r <= len_in;
                mode_r <= mode_in;
                lt_r <= in_lt;
                eq_r <= in_eq;
                gt_r <= in_gt;
            end else if (eq_r) begin
                eq_r <= 1'b0;
                gt_r <= 1'b1;
            end else if (lt_r) begin
                cnt_r <= cnt_nx;
                if (cnt_nx == len_r) begin
                    lt_r <= 1'b0;
                    eq_r <= 1'b1;
                end
            end
        end
    end

    assign o_lt = lt_r;
    assign o_eq = eq_r;
    assign o_gt = gt_r;

    always @(posedge clk)
        if (gt_r && !gt_q)
            assert (!lt_r && !eq_r);
endmodule

module irq_pulse_stretch (
    input  wire clk,
    input  wire ce,
    input  wire irq_pulse,
    input  wire win_open,
    input  wire win_close,
    output reg  irq_out
);
    localparam [63:0] LEN = 64'd12;

    reg [63:0] remain = 64'd0;
    reg [63:0] held   = 64'd0;
    reg        win    = 1'b0;
    initial irq_out = 1'b0;

    always @(posedge clk) begin
        if (ce) begin
            if (win_close)     win <= 1'b0;
            else if (win_open) win <= 1'b1;

            if (!irq_out) begin
                if (irq_pulse) begin
                    irq_out <= 1'b1;
                    remain  <= LEN - 64'd1;
                    held    <= 64'd1;
                end
            end else if (remain == 64'd0) begin
                irq_out <= 1'b0;
            end else begin
                remain <= remain - 64'd1;
                held   <= held + 64'd1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $fell(irq_out))
            assert (held <= LEN);
endmodule

module LispDebugBridge (
    input wire clk,
    input wire en,
    input wire start,
    input wire wr_in,
    input wire [3:0] addr_in,
    input wire [63:0] wdata_in,
    output wire busy_o,
    output wire [63:0] rdata_o,
    output wire [63:0] txn_o
);
    // host side
    reg busy = 1'b0;
    reg req_tgl = 1'b0;
    reg ack_s1 = 1'b0;
    reg ack_s2 = 1'b0;
    reg [3:0] addr_q = 4'd0;
    reg wr_q = 1'b0;
    reg [63:0] wdata_q = 64'd0;
    reg [63:0] rdata_q = 64'd0;
    reg [63:0] txn_cnt = 64'd0;
    // core side
    reg req_s1 = 1'b0;
    reg req_s2 = 1'b0;
    reg tgt_seen = 1'b0;
    reg ack_tgl = 1'b0;
    reg [63:0] regs [0:15];
    // verification shadow
    reg [3:0] shadow_addr = 4'd0;
    reg [63:0] shadow_wdata = 64'd0;
    reg win = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1)
            regs[i] = 64'd0;
    end

    wire tgt_fire = (req_s2 != tgt_seen);
    wire launch = start && !busy;

    // host side: launch and completion
    always @(posedge clk) begin
        if (en) begin
            ack_s1 <= ack_tgl;
            ack_s2 <= ack_s1;
            if (launch) begin
                addr_q       <= addr_in;
                wr_q         <= wr_in;
                wdata_q      <= wdata_in;
                req_tgl      <= ~req_tgl;
                busy         <= 1'b1;
                shadow_addr  <= addr_in;
                shadow_wdata <= wdata_in;
                win          <= 1'b1;
            end else if (busy && (ack_s2 == req_tgl)) begin
                busy    <= 1'b0;
                win     <= 1'b0;
                txn_cnt <= txn_cnt + 64'd1;
            end
        end
    end

    // core side: synchronizer and target access
    always @(posedge clk) begin
        if (en) begin
            req_s1 <= req_tgl;
            req_s2 <= req_s1;
            if (tgt_fire) begin
                if (wr_q)
                    regs[addr_q] <= wdata_q;
                else
                    rdata_q <= regs[addr_q];
                tgt_seen <= req_s2;
                ack_tgl  <= ~ack_tgl;
            end
        end
    end

    assign busy_o  = busy;
    assign rdata_o = rdata_q;
    assign txn_o   = txn_cnt;

    // A1: core acts only on the address the host launched
    always @(*) assert (!(win && tgt_fire) || (addr_q == shadow_addr));
    // A2: core writes only the data the host launched
    always @(*) assert (!(win && tgt_fire && wr_q) || (wdata_q == shadow_wdata));
endmodule

module metron_trace_latch (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [5:0] s,
    input wire [5:0] r,
    input wire trace_on,
    input wire trace_off,
    output wire [5:0] q_out,
    output wire [31:0] cnt_out
);
    reg [5:0] q;
    reg [31:0] live_cnt;
    reg win;
    initial q = 6'b000000;
    initial live_cnt = 32'd0;
    initial win = 1'b0;

    function [31:0] pc6;
        input [5:0] v;
        begin
            pc6 = {31'd0, v[0]} + {31'd0, v[1]} + {31'd0, v[2]}
                + {31'd0, v[3]} + {31'd0, v[4]} + {31'd0, v[5]};
        end
    endfunction

    wire [5:0] q_n = s | (~r & q);
    wire [5:0] rises = q_n & ~q;
    wire [5:0] falls = q & ~q_n;

    always @(posedge clk) begin
        if (rst) begin
            q <= 6'b000000;
            live_cnt <= 32'd0;
            win <= 1'b0;
        end else if (en) begin
            q <= q_n;
            live_cnt <= live_cnt + pc6(rises) - pc6(falls);
            win <= trace_on ? 1'b1 : (trace_off ? 1'b0 : win);
        end
    end

    assign q_out = q;
    assign cnt_out = live_cnt;

    assert property (!win || live_cnt <= 32'd6);
endmodule

module fracn_mash_ctrl (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire        clear,
    input  wire [31:0] int_in,
    input  wire [31:0] frac_in,
    input  wire [31:0] len_in,
    output reg  [31:0] div_ratio,
    output wire        busy
);
    localparam [1:0] P_IDLE  = 2'd0;
    localparam [1:0] P_ARMED = 2'd1;
    localparam [1:0] P_RUN   = 2'd2;
    localparam [1:0] P_DONE  = 2'd3;

    reg [1:0]  phase;
    reg        win;
    reg        seen_arm;
    reg        seen_start;
    reg [31:0] int_set;
    reg [31:0] frac_set;
    reg [31:0] len_set;
    reg [31:0] remaining;
    reg [31:0] acc1;
    reg [31:0] acc2;
    reg        c2_d;

    initial phase      = P_IDLE;
    initial win        = 1'b0;
    initial seen_arm   = 1'b0;
    initial seen_start = 1'b0;
    initial int_set    = 32'd0;
    initial frac_set   = 32'd0;
    initial len_set    = 32'd0;
    initial remaining  = 32'd0;
    initial acc1       = 32'd0;
    initial acc2       = 32'd0;
    initial c2_d       = 1'b0;
    initial div_ratio  = 32'd0;

    // two-stage MASH 1-1 sigma-delta modulator
    wire [32:0] sum1 = {1'b0, acc1} + {1'b0, frac_set};
    wire [32:0] sum2 = {1'b0, acc2} + {1'b0, sum1[31:0]};
    wire        c1   = sum1[32];
    wire        c2   = sum2[32];

    always @(posedge clk) begin
        if (rst) begin
            phase      <= P_IDLE;
            win        <= 1'b0;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            int_set    <= 32'd0;
            frac_set   <= 32'd0;
            len_set    <= 32'd0;
            remaining  <= 32'd0;
            acc1       <= 32'd0;
            acc2       <= 32'd0;
            c2_d       <= 1'b0;
            div_ratio  <= 32'd0;
        end else if (ce) begin
            case (phase)
                P_IDLE: if (arm) begin
                    int_set    <= int_in;
                    frac_set   <= frac_in;
                    len_set    <= len_in;
                    acc1       <= 32'd0;
                    acc2       <= 32'd0;
                    c2_d       <= 1'b0;
                    phase      <= P_ARMED;
                    win        <= 1'b1;
                    seen_arm   <= 1'b1;
                    seen_start <= 1'b0;
                end
                P_ARMED: if (start) begin
                    remaining  <= len_set;
                    phase      <= P_RUN;
                    seen_start <= 1'b1;
                end
                P_RUN: begin
                    acc1      <= sum1[31:0];
                    acc2      <= sum2[31:0];
                    c2_d      <= c2;
                    div_ratio <= int_set + {31'd0, c1} + {31'd0, c2} - {31'd0, c2_d};
                    if (remaining == 32'd0)
                        phase <= P_DONE;
                    else
                        remaining <= remaining - 32'd1;
                end
                P_DONE: if (clear) begin
                    phase      <= P_IDLE;
                    win        <= 1'b0;
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                end
            endcase
        end
    end

    assign busy = (phase == P_RUN);

    // chain precedence inside the arm..clear window: finish implies start and arm happened
    always @(posedge clk)
        if (win && phase == P_DONE)
            assert (seen_arm && seen_start);
endmodule

module mdio_master64 (
    input  wire        clk,
    input  wire        ce,
    input  wire        start,
    input  wire        op_rd,
    input  wire [4:0]  phy_ad,
    input  wire [4:0]  reg_ad,
    input  wire [15:0] wr_data,
    input  wire        mdio_i,
    output wire        mdio_o,
    output wire        mdio_oe,
    output wire        busy,
    output wire [63:0] o_rd_data
);
    localparam [2:0] IDLE = 3'd0, PRE = 3'd1, CMD = 3'd2, TA = 3'd3, DATA = 3'd4;

    reg [2:0]  phase      = IDLE;
    reg [63:0] pre_cnt    = 64'd0;
    reg [31:0] frame_sr   = 32'd0;
    reg [63:0] bit_cnt    = 64'd0;
    reg        ta         = 1'b0;
    reg        op_read    = 1'b0;
    reg [15:0] rx_sh      = 16'd0;
    reg [63:0] rd_data    = 64'd0;
    reg        ta_pending = 1'b0;

    always @(posedge clk) begin
        if (ce) begin
            case (phase)
                IDLE: begin
                    if (start) begin
                        op_read  <= op_rd;
                        frame_sr <= {2'b01, (op_rd ? 2'b10 : 2'b01), phy_ad, reg_ad, 2'b10, wr_data};
                        pre_cnt  <= 64'd0;
                        bit_cnt  <= 64'd0;
                        phase    <= PRE;
                    end
                end
                PRE: begin
                    if (pre_cnt == 64'd31) begin
                        pre_cnt <= 64'd0;
                        bit_cnt <= 64'd0;
                        phase   <= CMD;
                    end else begin
                        pre_cnt <= pre_cnt + 64'd1;
                    end
                end
                CMD: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (bit_cnt == 64'd13) begin
                        bit_cnt <= 64'd0;
                        ta      <= 1'b1;
                        phase   <= TA;
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                TA: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (bit_cnt == 64'd1) begin
                        bit_cnt <= 64'd0;
                        ta      <= 1'b0;
                        phase   <= DATA;
                        if (op_read) ta_pending <= 1'b1;
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                DATA: begin
                    frame_sr <= {frame_sr[30:0], 1'b0};
                    if (op_read) rx_sh <= {rx_sh[14:0], mdio_i};
                    if (bit_cnt == 64'd15) begin
                        bit_cnt <= 64'd0;
                        phase   <= IDLE;
                        if (op_read) begin
                            rd_data    <= {48'd0, rx_sh[14:0], mdio_i};
                            ta_pending <= 1'b0;
                        end
                    end else begin
                        bit_cnt <= bit_cnt + 64'd1;
                    end
                end
                default: begin
                    phase <= IDLE;
                    ta    <= 1'b0;
                end
            endcase
        end
    end

    assign mdio_oe   = (phase == PRE) || (phase == CMD) || ((phase == TA || phase == DATA) && !op_read);
    assign mdio_o    = (phase == PRE) ? 1'b1 : frame_sr[31];
    assign busy      = (phase != IDLE);
    assign o_rd_data = rd_data;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $stable(ta_pending))
            assert ($stable(rd_data));
endmodule

module ecc_err_logger (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire sw_arm,
    input wire err_valid,
    input wire err_ue,
    input wire [31:0] err_syn,
    input wire [31:0] err_addr,
    input wire sw_ack
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, CAPT = 2'd2, DONE = 2'd3;

    reg [1:0]  phase;
    reg [31:0] syn_q, addr_q;
    reg        type_q;
    reg [31:0] ce_cnt, ue_cnt;
    reg [31:0] log_mem [0:127];
    reg [6:0]  wp;
    reg        arm_seen, start_seen, fin_seen;

    integer i;
    initial begin
        phase = IDLE;
        syn_q = 32'd0;
        addr_q = 32'd0;
        type_q = 1'b0;
        ce_cnt = 32'd0;
        ue_cnt = 32'd0;
        wp = 7'd0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        fin_seen = 1'b0;
        for (i = 0; i < 128; i = i + 1) log_mem[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= IDLE;
            syn_q <= 32'd0;
            addr_q <= 32'd0;
            type_q <= 1'b0;
            ce_cnt <= 32'd0;
            ue_cnt <= 32'd0;
            wp <= 7'd0;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            fin_seen <= 1'b0;
        end else if (en) begin
            case (phase)
                IDLE, DONE: begin
                    if (sw_arm) begin
                        phase <= ARMED;
                        arm_seen <= 1'b1;
                    end
                end
                ARMED: begin
                    if (err_valid) begin
                        phase <= CAPT;
                        start_seen <= 1'b1;
                        syn_q <= err_syn;
                        addr_q <= err_addr;
                        type_q <= err_ue;
                        if (err_ue) begin
                            if (ue_cnt != 32'hFFFFFFFF) ue_cnt <= ue_cnt + 32'd1;
                        end else begin
                            if (ce_cnt != 32'hFFFFFFFF) ce_cnt <= ce_cnt + 32'd1;
                        end
                        log_mem[wp] <= err_addr;
                        wp <= wp + 7'd1;
                    end
                end
                CAPT: begin
                    if (sw_ack) begin
                        phase <= DONE;
                        fin_seen <= 1'b1;
                    end
                end
                default: phase <= phase;
            endcase
        end
    end

    assert property (!fin_seen || (start_seen && arm_seen));
endmodule

module babysoc_padmux (
    input wire clk,
    input wire rst,
    input wire en,
    input wire wr,
    input wire [2:0] wr_idx,
    input wire [2:0] wr_func,
    input wire lock_req,
    input wire [7:0] gpio_out,
    input wire pll_clk,
    input wire dac_bit,
    input wire uart_tx,
    output wire [7:0] pad_out,
    output wire o_err,
    output wire o_locked
);
    reg [23:0] func_sel;
    reg [31:0] wr_cnt;
    reg [31:0] cm_cnt;
    reg err;
    reg locked;
    reg pre_lock;
    integer k;

    initial begin
        func_sel = 24'd0;
        wr_cnt = 32'd0;
        cm_cnt = 32'd0;
        err = 1'b0;
        locked = 1'b0;
        pre_lock = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            func_sel <= 24'd0;
            wr_cnt <= 32'd0;
            cm_cnt <= 32'd0;
            err <= 1'b0;
            locked <= 1'b0;
            pre_lock <= 1'b1;
        end else if (en) begin
            if (wr && !locked) begin
                for (k = 0; k < 8; k = k + 1)
                    if (wr_idx == k) func_sel[k*3 +: 3] <= wr_func;
                wr_cnt <= wr_cnt + 32'd1;
                cm_cnt <= cm_cnt + 32'd1;
            end
            err <= err | (wr_cnt != cm_cnt);
            if (lock_req) begin
                locked <= 1'b1;
                pre_lock <= 1'b0;
            end
        end
    end

    genvar g;
    generate
        for (g = 0; g < 8; g = g + 1) begin : pads
            wire [2:0] fs = func_sel[g*3 +: 3];
            assign pad_out[g] = (fs == 3'd0) ? gpio_out[g] :
                                (fs == 3'd1) ? pll_clk :
                                (fs == 3'd2) ? dac_bit :
                                (fs == 3'd3) ? uart_tx : 1'b0;
        end
    endgenerate

    assign o_err = err;
    assign o_locked = locked;

    always @(posedge clk)
        if (pre_lock)
            assert (!err);
endmodule

module xs3_cell_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         step,
    input  wire         arm,
    input  wire         go,
    input  wire         clr,
    input  wire [127:0] a_in,
    input  wire [127:0] b_in,
    output reg  [127:0] result,
    output reg          carry_out
);
    reg [127:0] opa;
    reg [127:0] opb;
    reg [1:0]   phase;
    reg         armed_seen;
    reg         start_seen;
    reg         done;

    initial begin
        opa = 128'd0; opb = 128'd0; result = 128'd0; carry_out = 1'b0;
        phase = 2'd0; armed_seen = 1'b0; start_seen = 1'b0; done = 1'b0;
    end

    // Combinational excess-3 adder: 32 digits, binary add then +3/-3 correction
    wire [32:0]  c;
    wire [127:0] xs3_sum;
    assign c[0] = 1'b0;
    genvar i;
    generate
        for (i = 0; i < 32; i = i + 1) begin : g_dig
            wire [4:0] raw = {1'b0, opa[4*i +: 4]} + {1'b0, opb[4*i +: 4]} + {4'd0, c[i]};
            assign c[i+1] = raw[4];
            assign xs3_sum[4*i +: 4] = raw[4] ? (raw[3:0] + 4'd3) : (raw[3:0] - 4'd3);
        end
    endgenerate

    always @(posedge clk) begin
        if (rst) begin
            phase <= 2'd0; armed_seen <= 1'b0; start_seen <= 1'b0; done <= 1'b0;
        end else if (step) begin
            case (phase)
                2'd0: if (arm) begin
                    opa <= a_in;
                    armed_seen <= 1'b1;
                    phase <= 2'd1;
                end
                2'd1: if (go) begin
                    opb <= b_in;
                    start_seen <= 1'b1;
                    phase <= 2'd2;
                end
                2'd2: begin
                    result <= xs3_sum;
                    carry_out <= c[32];
                    done <= 1'b1;
                    phase <= 2'd3;
                end
                default: if (clr) begin
                    armed_seen <= 1'b0;
                    start_seen <= 1'b0;
                    done <= 1'b0;
                    phase <= 2'd0;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (done)
            assert (start_seen && armed_seen);
endmodule

module eth_sticky_align (
    input wire clk,
    input wire load,
    input wire shift,
    input wire [31:0] din,
    output wire [31:0] o_mant,
    output wire o_sticky,
    output wire [31:0] o_shamt
);
    localparam [31:0] PREAMBLE = 32'hD5555555;
    localparam [31:0] MAXSH = 32'd32;

    reg [31:0] mant;
    reg sticky;
    reg [31:0] shamt;
    reg [31:0] orig;
    reg armed;
    reg pv;

    initial begin
        mant = PREAMBLE;
        sticky = 1'b0;
        shamt = 32'd0;
        orig = PREAMBLE;
        armed = 1'b1;
        pv = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load) begin
            mant <= din;
            orig <= din;
            sticky <= 1'b0;
            shamt <= 32'd0;
            armed <= 1'b0;
        end else if (shift) begin
            mant <= mant >> 1;
            sticky <= sticky | mant[0];
            if (shamt != MAXSH)
                shamt <= shamt + 32'd1;
        end
    end

    assign o_mant = mant;
    assign o_sticky = sticky;
    assign o_shamt = shamt;

    always @(posedge clk)
        if (pv && armed && $stable(shamt))
            assert ($stable(mant));
endmodule

module jls_pausible_clkctl (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire areq,
    input wire mutex_gnt,
    input wire [31:0] din,
    input wire sof,
    input wire eof,
    input wire [7:0] raddr,
    output wire [31:0] dout,
    output wire ring_clk_en
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2;

    reg [1:0] phase = 2'd0;
    reg hs_latch = 1'b0;
    reg clk_en = 1'b1;
    reg [31:0] arm_cnt = 32'd0;
    reg [31:0] start_cnt = 32'd0;
    reg [31:0] fin_cnt = 32'd0;
    reg [7:0] wptr = 8'd0;
    reg win = 1'b0;
    reg [31:0] linebuf [0:255];

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1)
            linebuf[i] = 32'd0;
    end

    assign dout = linebuf[raddr];
    assign ring_clk_en = clk_en;

    always @(posedge clk) begin
        if (!rst_n) begin
            phase <= IDLE;
            hs_latch <= 1'b0;
            clk_en <= 1'b1;
            arm_cnt <= 32'd0;
            start_cnt <= 32'd0;
            fin_cnt <= 32'd0;
            wptr <= 8'd0;
            win <= 1'b0;
        end else if (en) begin
            if (eof)
                win <= 1'b0;
            else if (sof)
                win <= 1'b1;
            case (phase)
                IDLE: begin
                    if (areq) begin
                        hs_latch <= 1'b1;
                        phase <= ARMED;
                        arm_cnt <= arm_cnt + 32'd1;
                    end
                end
                ARMED: begin
                    if (mutex_gnt) begin
                        clk_en <= 1'b0;
                        phase <= STARTED;
                        start_cnt <= start_cnt + 32'd1;
                    end
                end
                STARTED: begin
                    wptr <= wptr + 8'd1;
                    hs_latch <= 1'b0;
                    clk_en <= 1'b1;
                    phase <= IDLE;
                    fin_cnt <= fin_cnt + 32'd1;
                end
                default: begin
                    phase <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk) begin
        if (rst_n && en && phase == STARTED)
            linebuf[wptr] <= din;
    end

    always @(posedge clk)
        if (win && phase == 2'd2)
            assert (arm_cnt == start_cnt && start_cnt == fin_cnt + 32'd1 && !clk_en);
endmodule

module dram_init_seq (
    input wire clk,
    input wire rst,
    input wire step,
    input wire rel,
    output reg [2:0] cmd,
    output reg cke,
    output reg init_done
);
    reg [3:0]  cmd_idx  = 4'd0;
    reg [63:0] wait_cnt = 64'd0;
    reg        zq_done  = 1'b0;
    reg        armed    = 1'b0;

    initial cmd = 3'd0;
    initial cke = 1'b0;
    initial init_done = 1'b0;

    function [63:0] cmd_delay;
        input [3:0] idx;
        begin
            case (idx)
                4'd0:    cmd_delay = 64'd4;
                4'd1:    cmd_delay = 64'd3;
                4'd14:   cmd_delay = 64'd4;
                default: cmd_delay = 64'd1;
            endcase
        end
    endfunction

    function [2:0] cmd_code;
        input [3:0] idx;
        begin
            if (idx == 4'd0)       cmd_code = 3'd1;
            else if (idx == 4'd1)  cmd_code = 3'd2;
            else if (idx == 4'd14) cmd_code = 3'd4;
            else if (idx == 4'd15) cmd_code = 3'd0;
            else                   cmd_code = 3'd3;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            cmd_idx   <= 4'd0;
            wait_cnt  <= 64'd0;
            zq_done   <= 1'b0;
            armed     <= 1'b0;
            init_done <= 1'b0;
            cmd       <= 3'd0;
            cke       <= 1'b0;
        end else if (step) begin
            cmd <= 3'd0;
            if (rel) armed <= 1'b0;
            if (wait_cnt != 64'd0) begin
                wait_cnt <= wait_cnt - 64'd1;
            end else if (cmd_idx != 4'd15) begin
                cmd      <= cmd_code(cmd_idx);
                wait_cnt <= cmd_delay(cmd_idx);
                cmd_idx  <= cmd_idx + 4'd1;
                if (cmd_idx == 4'd1) begin
                    cke <= 1'b1;
                    if (!rel) armed <= 1'b1;
                end
                if (cmd_idx == 4'd14) zq_done <= 1'b1;
            end else begin
                init_done <= 1'b1;
            end
        end
    end

    always @(posedge clk)
        if (armed && init_done)
            assert (zq_done);
endmodule

module mmio_router_tmo (
    input wire clk,
    input wire en,
    input wire cfg_we,
    input wire [5:0] cfg_idx,
    input wire [63:0] cfg_base,
    input wire [63:0] cfg_limit,
    input wire req,
    input wire [63:0] req_addr,
    input wire win_clr,
    output wire o_busy,
    output wire o_win,
    output wire [5:0] o_sel
);
    localparam [63:0] K = 64'd16;

    reg [63:0] base  [0:63];
    reg [63:0] limit [0:63];
    reg        busy;
    reg        win;
    reg [5:0]  sel;
    reg [63:0] cnt;
    reg [63:0] age;

    integer i;
    initial begin
        busy = 1'b0;
        win  = 1'b0;
        sel  = 6'd0;
        cnt  = 64'd0;
        age  = 64'd0;
        for (i = 0; i < 64; i = i + 1) begin
            base[i]  = 64'd0;
            limit[i] = 64'd0;
        end
    end

    reg       hit;
    reg [5:0] hidx;
    integer j;
    always @(*) begin
        hit  = 1'b0;
        hidx = 6'd0;
        for (j = 63; j >= 0; j = j - 1) begin
            if ((base[j] <= req_addr) && (req_addr <= limit[j])) begin
                hit  = 1'b1;
                hidx = j[5:0];
            end
        end
    end

    wire accept = req && hit && !busy;

    always @(posedge clk) begin
        if (en) begin
            if (cfg_we) begin
                base[cfg_idx]  <= cfg_base;
                limit[cfg_idx] <= cfg_limit;
            end
            if (win_clr)
                win <= 1'b0;
            else if (accept)
                win <= 1'b1;
            if (busy) begin
                if (age == K - 64'd1) begin
                    busy <= 1'b0;
                    cnt  <= 64'd0;
                    age  <= 64'd0;
                end else begin
                    cnt <= cnt - 64'd1;
                    age <= age + 64'd1;
                end
            end else if (accept) begin
                busy <= 1'b1;
                sel  <= hidx;
                cnt  <= K;
                age  <= 64'd0;
            end
        end
    end

    assign o_busy = busy;
    assign o_win  = win;
    assign o_sel  = sel;

    always @(posedge clk)
        if (win && busy)
            assert (cnt != 64'd0);

    always @(posedge clk)
        if (win && busy)
            assert (cnt <= K);
endmodule

module bypass_xact_reg (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm,
    input  wire        start,
    input  wire        finish,
    input  wire        open_w,
    input  wire        close_w,
    input  wire [31:0] din,
    output wire [31:0] dout,
    output wire        bypass_en
);
    // phase: 0 idle, 1 armed (word captured), 2 started (bypass engaged), 3 finished
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        win;
    reg [31:0] stored;
    reg [31:0] xact_cnt;
    reg        pv;

    initial begin
        phase = 2'd0;
        arm_seen = 1'b0;
        start_seen = 1'b0;
        win = 1'b0;
        stored = 32'd0;
        xact_cnt = 32'd0;
        pv = 1'b0;
    end

    // bypass multiplexer: steer input straight through while started,
    // the stored copy is left untouched
    assign bypass_en = (phase == 2'd2);
    assign dout = bypass_en ? din : stored;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (open_w)       win <= 1'b1;
            else if (close_w) win <= 1'b0;

            case (phase)
                2'd0: if (arm) begin
                    phase    <= 2'd1;
                    arm_seen <= 1'b1;
                    stored   <= din;
                end
                2'd1: if (start) begin
                    phase      <= 2'd2;
                    start_seen <= 1'b1;
                end
                2'd2: if (finish) begin
                    phase    <= 2'd3;
                    xact_cnt <= xact_cnt + 32'd1;
                end
                default: begin
                    phase      <= 2'd0;
                    arm_seen   <= 1'b0;
                    start_seen <= 1'b0;
                end
            endcase
        end
    end

    // chain precedence inside the window: a finish is only observed if
    // arm and start had both happened in the previous cycle's record
    always @(posedge clk)
        if (pv && win && phase == 2'd3)
            assert ($past(start_seen) && $past(arm_seen));
endmodule

module hls_pixclk_swallow (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [7:0] N,
    input wire [7:0] S,
    output wire strobe
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, STARTED = 2'd2, DONE = 2'd3;

    reg [3:0] pre_cnt = 4'd0;
    reg [7:0] p_cnt = 8'd0;
    reg [7:0] s_cnt = 8'd0;
    reg [7:0] n_reg = 8'd0;
    reg [7:0] s_reg = 8'd0;
    reg [1:0] phase = 2'd0;
    reg armed_seen = 1'b0;
    reg started_seen = 1'b0;
    reg q_seen = 1'b0;

    wire tc = (s_cnt != 8'd0) ? (pre_cnt == 4'd8) : (pre_cnt == 4'd7);
    wire hit = tc && (p_cnt <= 8'd1);
    assign strobe = en && !load && hit;

    always @(posedge clk) begin
        if (rst) begin
            pre_cnt <= 4'd0;
            p_cnt <= 8'd0;
            s_cnt <= 8'd0;
            n_reg <= 8'd0;
            s_reg <= 8'd0;
            phase <= IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            q_seen <= 1'b0;
        end else if (en) begin
            if (load) begin
                n_reg <= N;
                s_reg <= S;
                p_cnt <= N;
                s_cnt <= S;
                pre_cnt <= 4'd0;
                phase <= ARMED;
                armed_seen <= 1'b1;
                started_seen <= 1'b0;
                q_seen <= 1'b1;
            end else begin
                if (tc) begin
                    pre_cnt <= 4'd0;
                    if (p_cnt <= 8'd1) begin
                        p_cnt <= n_reg;
                        s_cnt <= s_reg;
                    end else begin
                        p_cnt <= p_cnt - 8'd1;
                        if (s_cnt != 8'd0)
                            s_cnt <= s_cnt - 8'd1;
                    end
                    case (phase)
                        ARMED: begin
                            phase <= STARTED;
                            started_seen <= 1'b1;
                        end
                        STARTED: begin
                            if (p_cnt <= 8'd1)
                                phase <= DONE;
                        end
                        default: phase <= phase;
                    endcase
                end else begin
                    pre_cnt <= pre_cnt + 4'd1;
                end
            end
        end
    end

    always @(*) assert (!(q_seen && phase == 2'd3) || (started_seen && armed_seen));
endmodule

module gf180_tapline_cal (
    input  wire        clk,
    input  wire        rst_n,
    input  wire        en,
    input  wire [63:0] din,
    input  wire        cal_start,
    input  wire        cal_done,
    output wire [63:0] dout,
    output wire [7:0]  tok_o,
    output wire [63:0] cal_cnt_o,
    output wire        win_o
);
    reg [63:0] tap  [0:7];
    reg [63:0] samp [0:7];
    reg [7:0]  tok;
    reg        win;
    reg [63:0] cal_cnt;
    integer i;

    initial begin
        for (i = 0; i < 8; i = i + 1) begin
            tap[i]  = 64'd0;
            samp[i] = 64'd0;
        end
        tok     = 8'd0;
        win     = 1'b0;
        cal_cnt = 64'd0;
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            for (i = 0; i < 8; i = i + 1) begin
                tap[i]  <= 64'd0;
                samp[i] <= 64'd0;
            end
            tok     <= 8'd0;
            win     <= 1'b0;
            cal_cnt <= 64'd0;
        end else if (en) begin
            tap[0] <= din;
            for (i = 1; i < 8; i = i + 1)
                tap[i] <= tap[i-1];
            for (i = 0; i < 8; i = i + 1)
                samp[i] <= tap[i];
            if (cal_start) begin
                win     <= 1'b1;
                tok     <= 8'b0000_0001;
                cal_cnt <= 64'd0;
            end else if (cal_done) begin
                win <= 1'b0;
                tok <= 8'd0;
            end else if (win) begin
                tok <= tok << 1;
                if (cal_cnt != 64'hFFFF_FFFF_FFFF_FFFF)
                    cal_cnt <= cal_cnt + 64'd1;
            end else begin
                tok <= 8'd0;
            end
        end
    end

    assign dout      = samp[7];
    assign tok_o     = tok;
    assign cal_cnt_o = cal_cnt;
    assign win_o     = win;

    always @(*)
        if (win)
            assert (!(tok[6] && tok[7]));
endmodule

module const_slicer (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       req,
    input  wire       cfg_we,
    input  wire [1:0] cfg_order,
    input  wire [7:0] in_i,
    input  wire [7:0] in_q,
    output reg  [3:0] dec_bits,
    output reg  [7:0] err_i,
    output reg  [7:0] err_q,
    output reg        done,
    output wire       busy_o
);
    reg [1:0] mod_order;
    reg [7:0] sym_i, sym_q;
    reg       busy;
    reg [7:0] cd;
    reg [7:0] phase;
    reg       pre_cfg;
    reg       pv;

    initial begin
        mod_order = 2'd1; sym_i = 8'd0; sym_q = 8'd0;
        busy = 1'b0; cd = 8'd0; phase = 8'd0;
        dec_bits = 4'd0; err_i = 8'd0; err_q = 8'd0; done = 1'b0;
        pre_cfg = 1'b1; pv = 1'b0;
    end

    assign busy_o = busy;

    wire si = sym_i[7];
    wire sq = sym_q[7];
    wire mi = sym_i[7] ^ sym_i[6];
    wire mq = sym_q[7] ^ sym_q[6];
    wire qam = mod_order[1];

    wire [7:0] qam_pt_i = si ? (mi ? 8'hA0 : 8'hE0) : (mi ? 8'h60 : 8'h20);
    wire [7:0] qam_pt_q = sq ? (mq ? 8'hA0 : 8'hE0) : (mq ? 8'h60 : 8'h20);
    wire [7:0] psk_pt_i = si ? 8'hC0 : 8'h40;
    wire [7:0] psk_pt_q = sq ? 8'hC0 : 8'h40;

    wire [7:0] pt_i = qam ? qam_pt_i : psk_pt_i;
    wire [7:0] pt_q = qam ? qam_pt_q : ((mod_order == 2'd0) ? 8'h00 : psk_pt_q);
    wire [3:0] bits = qam ? {mq, sq, mi, si}
                    : ((mod_order == 2'd0) ? {3'b000, si} : {2'b00, sq, si});

    always @(posedge clk) begin
        if (rst) begin
            busy  <= 1'b0;
            cd    <= 8'd0;
            phase <= 8'd0;
            done  <= 1'b0;
        end else if (ce) begin
            done <= 1'b0;
            if (cfg_we && !busy)
                mod_order <= cfg_order;
            if (!busy) begin
                if (req) begin
                    sym_i <= in_i;
                    sym_q <= in_q;
                    busy  <= 1'b1;
                    cd    <= 8'd4;
                    phase <= 8'd0;
                end
            end else begin
                cd <= cd - 8'd1;
                if (phase == 8'd3) begin
                    busy     <= 1'b0;
                    phase    <= 8'd0;
                    dec_bits <= bits;
                    err_i    <= sym_i - pt_i;
                    err_q    <= sym_q - pt_q;
                    done     <= 1'b1;
                end else begin
                    phase <= phase + 8'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (!rst && ce && cfg_we && !busy)
            pre_cfg <= 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_cfg && $past(busy))
            assert ($past(cd) != 8'd0);
endmodule

module bayer_tile_demosaic (
    input wire clk,
    input wire rst,
    input wire en,
    input wire start,
    input wire [63:0] pix_in,
    output reg [63:0] rgb_r,
    output reg [63:0] rgb_g,
    output reg [63:0] rgb_b,
    output reg done
);
    reg [63:0] tile [0:15];
    reg [63:0] idx;
    reg [63:0] cd;
    reg busy;
    reg [1:0] phase;
    reg win;
    reg pv;
    integer k;

    initial begin
        for (k = 0; k < 16; k = k + 1) tile[k] = 64'd0;
        idx = 64'd0;
        cd = 64'd0;
        busy = 1'b0;
        phase = 2'b00;
        win = 1'b0;
        pv = 1'b0;
        rgb_r = 64'd0;
        rgb_g = 64'd0;
        rgb_b = 64'd0;
        done = 1'b0;
    end

    wire [3:0] i0 = idx[3:0];
    wire [3:0] im = i0 - 4'd1;
    wire [3:0] ip = i0 + 4'd1;
    wire [63:0] c_px = tile[i0];
    wire [63:0] l_px = tile[im];
    wire [63:0] r_px = tile[ip];
    wire [63:0] avg = (l_px >> 1) + (r_px >> 1);
    wire [63:0] diag = (l_px >> 2) + (r_px >> 2) + (c_px >> 1);

    reg [63:0] nr, ng, nb;
    always @(*) begin
        case (phase)
            2'b00: begin nr = c_px; ng = avg;  nb = diag; end
            2'b01: begin nr = avg;  ng = c_px; nb = diag; end
            2'b10: begin nr = diag; ng = c_px; nb = avg;  end
            default: begin nr = diag; ng = avg; nb = c_px; end
        endcase
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            for (k = 0; k < 16; k = k + 1) tile[k] <= 64'd0;
            idx <= 64'd0;
            cd <= 64'd0;
            busy <= 1'b0;
            phase <= 2'b00;
            win <= 1'b0;
            rgb_r <= 64'd0;
            rgb_g <= 64'd0;
            rgb_b <= 64'd0;
            done <= 1'b0;
        end else if (en) begin
            if (start && !busy) begin
                busy <= 1'b1;
                win <= 1'b1;
                idx <= 64'd0;
                cd <= 64'd16;
                phase <= 2'b00;
                done <= 1'b0;
            end else if (busy) begin
                tile[i0] <= pix_in;
                rgb_r <= nr;
                rgb_g <= ng;
                rgb_b <= nb;
                idx <= idx + 64'd1;
                cd <= cd - 64'd1;
                phase[0] <= ~phase[0];
                if (i0[1:0] == 2'b11) phase[1] <= ~phase[1];
                if (idx == 64'd15) begin
                    busy <= 1'b0;
                    win <= 1'b0;
                    done <= 1'b1;
                end else begin
                    done <= 1'b0;
                end
            end else begin
                done <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(win) && $past(busy))
            assert ($past(cd) != 64'd0);
endmodule

module irq_prio_budget (
    input wire clk,
    input wire rst,
    input wire step,
    input wire [3:0] req,
    input wire [7:0] d0,
    input wire [7:0] d1,
    input wire [7:0] d2,
    input wire [7:0] d3,
    input wire dbg_wr,
    input wire [7:0] dbg_val,
    output reg [7:0] sel_data,
    output reg [1:0] sel_idx,
    output reg sel_vld,
    output reg [7:0] cnt
);
    reg armed;
    initial sel_data = 8'd0;
    initial sel_idx = 2'd0;
    initial sel_vld = 1'b0;
    initial cnt = 8'd0;
    initial armed = 1'b1;

    wire [7:0] c0 = (d0 > 8'd8)  ? 8'd8  : d0;
    wire [7:0] c1 = (d1 > 8'd12) ? 8'd12 : d1;
    wire [7:0] c2 = (d2 > 8'd16) ? 8'd16 : d2;
    wire [7:0] c3 = (d3 > 8'd20) ? 8'd20 : d3;

    reg [7:0] nxt_data;
    reg [1:0] nxt_idx;
    reg nxt_vld;
    always @(*) begin
        if (req[0]) begin
            nxt_data = c0; nxt_idx = 2'd0; nxt_vld = 1'b1;
        end else if (req[1]) begin
            nxt_data = c1; nxt_idx = 2'd1; nxt_vld = 1'b1;
        end else if (req[2]) begin
            nxt_data = c2; nxt_idx = 2'd2; nxt_vld = 1'b1;
        end else if (req[3]) begin
            nxt_data = c3; nxt_idx = 2'd3; nxt_vld = 1'b1;
        end else begin
            nxt_data = 8'd0; nxt_idx = 2'd0; nxt_vld = 1'b0;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            cnt <= 8'd0;
            sel_data <= 8'd0;
            sel_idx <= 2'd0;
            sel_vld <= 1'b0;
        end else if (dbg_wr) begin
            cnt <= dbg_val;
            armed <= 1'b0;
        end else if (step) begin
            if (cnt == sel_data) begin
                cnt <= 8'd0;
                sel_data <= nxt_data;
                sel_idx <= nxt_idx;
                sel_vld <= nxt_vld;
            end else begin
                cnt <= cnt + 8'd1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;
    always @(posedge clk)
        if (pv && $past(armed)) assert ($past(cnt) <= 8'd20);
endmodule

module json_key_fuzzy_match (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] key_in,
    input wire [7:0] query,
    input wire ld_tol,
    input wire [3:0] tol_in,
    input wire q_open,
    input wire q_close,
    output reg near,
    output reg far,
    output reg win
);
    reg [3:0] tol;
    reg pv;
    initial tol = 4'd0;
    initial near = 1'b0;
    initial far = 1'b1;
    initial win = 1'b0;
    initial pv = 1'b0;

    wire [7:0] diff = key_in ^ query;
    wire [3:0] dist = {3'd0, diff[0]} + {3'd0, diff[1]} + {3'd0, diff[2]} + {3'd0, diff[3]}
                    + {3'd0, diff[4]} + {3'd0, diff[5]} + {3'd0, diff[6]} + {3'd0, diff[7]};
    wire near_nxt = (dist <= tol);

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            tol  <= 4'd0;
            near <= 1'b0;
            far  <= 1'b1;
            win  <= 1'b0;
        end else if (en) begin
            if (ld_tol) tol <= tol_in;
            near <= near_nxt;
            far  <= far ^ (near ^ near_nxt);
            win  <= q_open ? 1'b1 : (q_close ? 1'b0 : win);
        end
    end

    always @(posedge clk)
        if (pv && $past(win))
            assert (!($past(near) && $past(far)));
endmodule

module hdlbits_cam (
    input wire clk,
    input wire rst,
    input wire en,
    input wire lookup,
    input wire [63:0] lookup_key,
    input wire wr_en,
    input wire wr_idx,
    input wire [63:0] wr_key,
    output wire hit,
    output wire [1:0] hit_vec
);
    reg [63:0] key_mem [0:1];
    reg [1:0] valid;
    reg s1_vld;
    reg [31:0] s1_key_hi;
    reg [1:0] s1_pm;
    reg s2_vld;
    reg [1:0] s2_match;
    reg [63:0] inflight;
    reg armed;

    initial key_mem[0] = 64'd0;
    initial key_mem[1] = 64'd0;
    initial valid = 2'b00;
    initial s1_vld = 1'b0;
    initial s1_key_hi = 32'd0;
    initial s1_pm = 2'b00;
    initial s2_vld = 1'b0;
    initial s2_match = 2'b00;
    initial inflight = 64'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            key_mem[0] <= 64'd0;
            key_mem[1] <= 64'd0;
            valid <= 2'b00;
            s1_vld <= 1'b0;
            s1_key_hi <= 32'd0;
            s1_pm <= 2'b00;
            s2_vld <= 1'b0;
            s2_match <= 2'b00;
            inflight <= 64'd0;
            armed <= 1'b0;
        end else if (en) begin
            if (wr_en) begin
                key_mem[wr_idx] <= wr_key;
                valid[wr_idx] <= 1'b1;
            end
            s1_vld <= lookup;
            s1_key_hi <= lookup_key[63:32];
            s1_pm[0] <= valid[0] & (key_mem[0][31:0] == lookup_key[31:0]);
            s1_pm[1] <= valid[1] & (key_mem[1][31:0] == lookup_key[31:0]);
            s2_vld <= s1_vld;
            s2_match[0] <= s1_pm[0] & (key_mem[0][63:32] == s1_key_hi);
            s2_match[1] <= s1_pm[1] & (key_mem[1][63:32] == s1_key_hi);
            inflight <= inflight + {63'd0, lookup} - {63'd0, s2_vld};
            armed <= armed | lookup;
        end
    end

    assign hit_vec = s2_vld ? s2_match : 2'b00;
    assign hit = |hit_vec;

    always @(*) assert (!armed || inflight <= 64'd2);
endmodule

module lssd_scan_dump (
    input  wire        clk,
    input  wire        en,
    input  wire        scan_req,
    input  wire        tdi,
    input  wire        cap,
    input  wire [63:0] sys_d0,
    input  wire [63:0] sys_d1,
    output wire        tdo,
    output wire        busy_o
);
    reg [63:0] l1_0 = 64'd0;
    reg [63:0] l1_1 = 64'd0;
    reg [63:0] l2_0 = 64'd0;
    reg [63:0] l2_1 = 64'd0;
    reg        busy = 1'b0;
    reg        ph   = 1'b0;
    reg [6:0]  sc   = 7'd0;
    reg [7:0]  cd   = 8'd0;

    assign tdo    = l2_1[63];
    assign busy_o = busy;

    always @(posedge clk) begin
        if (en) begin
            if (!busy) begin
                if (scan_req) begin
                    busy <= 1'b1;
                    cd   <= 8'd128;
                    sc   <= 7'd0;
                    ph   <= 1'b0;
                end else begin
                    if (cap) begin
                        l1_0 <= sys_d0;
                        l1_1 <= sys_d1;
                    end
                    l2_0 <= l1_0;
                    l2_1 <= l1_1;
                end
            end else begin
                cd <= cd - 8'd1;
                if (!ph) begin
                    l1_0 <= {l2_0[62:0], tdi};
                    l1_1 <= {l2_1[62:0], l2_0[63]};
                    ph   <= 1'b1;
                end else begin
                    l2_0 <= l1_0;
                    l2_1 <= l1_1;
                    ph   <= 1'b0;
                    if (sc == 7'd63) begin
                        busy <= 1'b0;
                        sc   <= 7'd0;
                    end else begin
                        sc   <= sc + 7'd1;
                    end
                end
            end
        end
    end

    always @(*) begin
        if (busy)
            assert (cd != 8'd0);
        else
            assert (cd == 8'd0);
    end
endmodule

module doomsday_cdr (
    input wire clk,
    input wire rst,
    input wire en,
    input wire rx,
    output reg finished
);
    reg [3:0]  samp;
    reg [1:0]  phase_sel;
    reg [2:0]  vote;
    reg [1:0]  os_cnt;
    reg [15:0] bit_cnt;
    reg        armed;
    reg        started;
    reg        no_slip;
    reg        prev_bit;

    initial begin
        samp = 4'b1111; phase_sel = 2'd0; vote = 3'b111; os_cnt = 2'd0;
        bit_cnt = 16'd0; armed = 1'b0; started = 1'b0; finished = 1'b0;
        no_slip = 1'b1; prev_bit = 1'b1;
    end

    wire [1:0] ph_m     = phase_sel - 2'd1;
    wire [1:0] ph_p     = phase_sel + 2'd1;
    wire [1:0] exp_edge = phase_sel + 2'd2;
    wire [1:0] dist     = os_cnt - exp_edge;
    wire edge_det  = samp[0] ^ rx;
    wire slip      = edge_det && (os_cnt != exp_edge);
    wire bit_valid = (os_cnt == 2'd3);
    wire rec_bit   = (vote[0] & vote[1]) | (vote[0] & vote[2]) | (vote[1] & vote[2]);
    wire idle_edge = (samp == 4'b1111) && !rx;

    always @(posedge clk) begin
        if (rst) begin
            samp <= 4'b1111; phase_sel <= 2'd0; vote <= 3'b111; os_cnt <= 2'd0;
            bit_cnt <= 16'd0; armed <= 1'b0; started <= 1'b0; finished <= 1'b0;
            no_slip <= 1'b1; prev_bit <= 1'b1;
        end else if (en) begin
            samp   <= {samp[2:0], rx};
            os_cnt <= os_cnt + 2'd1;
            vote   <= {samp[ph_p], samp[phase_sel], samp[ph_m]};
            if (slip) begin
                no_slip <= 1'b0;
                if (dist[1] == 1'b0) phase_sel <= phase_sel + 2'd1;
                else                 phase_sel <= phase_sel - 2'd1;
            end
            if (bit_valid) prev_bit <= rec_bit;
            if (idle_edge) armed <= 1'b1;
            if (armed && bit_valid && prev_bit && !rec_bit) started <= 1'b1;
            if (started && !finished && bit_valid && bit_cnt != 16'd383)
                bit_cnt <= bit_cnt + 16'd1;
            if (started && bit_cnt == 16'd383) finished <= 1'b1;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && no_slip)
            assert (!finished || $past(armed));
endmodule

module lpm_engine (
    input  wire        clk,
    input  wire        insert,
    input  wire        flush,
    input  wire [63:0] ins_prefix,
    input  wire [6:0]  ins_len,
    input  wire [63:0] key,
    output reg         hit,
    output reg  [4:0]  match_addr,
    output reg  [6:0]  match_len,
    output wire [63:0] o_count
);
    reg [63:0] prefix_mem [0:31];
    reg [6:0]  len_mem    [0:31];
    reg [31:0] valid;
    reg [5:0]  wr_ptr;
    reg [63:0] count;
    reg        armed;

    integer k;
    initial begin
        valid  = 32'd0;
        wr_ptr = 6'd0;
        count  = 64'd0;
        armed  = 1'b1;
        for (k = 0; k < 32; k = k + 1) begin
            prefix_mem[k] = 64'd0;
            len_mem[k]    = 7'd0;
        end
    end

    function [63:0] pmask;
        input [6:0] l;
        begin
            if (l >= 7'd64) pmask = ~64'd0;
            else            pmask = ~(~64'd0 >> l);
        end
    endfunction

    wire [6:0] ins_len_sat = (ins_len > 7'd64) ? 7'd64 : ins_len;

    always @(posedge clk) begin
        if (flush) begin
            valid  <= 32'd0;
            wr_ptr <= 6'd0;
            armed  <= 1'b0;
        end else if (insert && wr_ptr < 6'd32) begin
            prefix_mem[wr_ptr[4:0]] <= ins_prefix & pmask(ins_len_sat);
            len_mem[wr_ptr[4:0]]    <= ins_len_sat;
            valid[wr_ptr[4:0]]      <= 1'b1;
            wr_ptr <= wr_ptr + 6'd1;
            count  <= count + 64'd1;
        end
    end

    integer i;
    always @(*) begin
        hit        = 1'b0;
        match_addr = 5'd0;
        match_len  = 7'd0;
        for (i = 0; i < 32; i = i + 1) begin
            if (valid[i] && (((key ^ prefix_mem[i]) & pmask(len_mem[i])) == 64'd0)
                && (!hit || len_mem[i] > match_len)) begin
                hit        = 1'b1;
                match_addr = i[4:0];
                match_len  = len_mem[i];
            end
        end
    end

    assign o_count = count;

    always @(*)
        if (armed)
            assert (count <= 64'd32);
endmodule

module usb_route_lookup (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire i_pkt_valid,
    input wire [31:0] i_dest,
    input wire cfg_we,
    input wire [4:0] cfg_addr,
    input wire [31:0] cfg_data,
    output wire o_done,
    output wire [31:0] o_port
);
    localparam [1:0] P_IDLE = 2'd0, P_ARM = 2'd1, P_START = 2'd2, P_FIN = 2'd3;

    reg [1:0]  phase    = 2'd0;
    reg [31:0] step_cnt = 32'd0;
    reg        fin_q    = 1'b0;
    reg [31:0] dest_q   = 32'd0;
    reg [31:0] port_q   = 32'd0;

    reg [31:0] rt_mem [0:31];
    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            rt_mem[i] = 32'd0;
    end

    // routing table configuration write port
    always @(posedge clk)
        if (!i_reset && i_ce && cfg_we)
            rt_mem[cfg_addr] <= cfg_data;

    // lookup sequencer: arm (capture dest) -> start (table read) -> finish (port valid)
    always @(posedge clk) begin
        if (i_reset) begin
            phase    <= P_IDLE;
            step_cnt <= 32'd0;
            fin_q    <= 1'b0;
            dest_q   <= 32'd0;
            port_q   <= 32'd0;
        end else if (i_ce) begin
            fin_q <= (step_cnt == 32'd2);
            case (phase)
                P_IDLE:  if (i_pkt_valid) begin
                             phase  <= P_ARM;
                             dest_q <= i_dest;
                         end
                P_ARM:   phase <= P_START;
                P_START: begin
                             phase  <= P_FIN;
                             port_q <= rt_mem[dest_q[4:0]];
                         end
                default: phase <= P_IDLE;
            endcase
            case (step_cnt)
                32'd0:   if (i_pkt_valid) step_cnt <= 32'd1;
                32'd3:   step_cnt <= 32'd0;
                default: step_cnt <= step_cnt + 32'd1;
            endcase
        end
    end

    assign o_done = fin_q;
    assign o_port = port_q;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && fin_q)
            assert (($past(phase) == P_START) || ($past(phase) == P_FIN));
endmodule

module therm_totalizer (
    input  wire        clk,
    input  wire        en,
    input  wire [63:0] therm,
    output wire [63:0] out
);
    // popcount encoder
    reg [6:0] cnt;
    integer k;
    always @(*) begin
        cnt = 7'd0;
        for (k = 0; k < 64; k = k + 1)
            cnt = cnt + {6'd0, therm[k]};
    end

    wire [63:0] addend = {57'd0, cnt};

    reg [63:0] rca_sum;
    reg [63:0] cla_sum;
    reg        armed;
    reg        pv;
    initial rca_sum = 64'd0;
    initial cla_sum = 64'd0;
    initial armed   = 1'b0;
    initial pv      = 1'b0;

    // ripple-carry adder
    wire [64:0] rc;
    wire [63:0] rca_next;
    assign rc[0] = 1'b0;
    genvar i;
    generate
        for (i = 0; i < 64; i = i + 1) begin : g_rca
            assign rca_next[i] = rca_sum[i] ^ addend[i] ^ rc[i];
            assign rc[i+1] = (rca_sum[i] & addend[i]) | (rc[i] & (rca_sum[i] ^ addend[i]));
        end
    endgenerate

    // carry-lookahead adder, 4-bit groups
    wire [63:0] cg = cla_sum & addend;
    wire [63:0] cp = cla_sum ^ addend;
    wire [63:0] cc;
    wire [16:0] gcarry;
    wire [63:0] cla_next;
    assign gcarry[0] = 1'b0;
    genvar j;
    generate
        for (j = 0; j < 16; j = j + 1) begin : g_cla
            wire g0 = cg[4*j];   wire p0 = cp[4*j];
            wire g1 = cg[4*j+1]; wire p1 = cp[4*j+1];
            wire g2 = cg[4*j+2]; wire p2 = cp[4*j+2];
            wire g3 = cg[4*j+3]; wire p3 = cp[4*j+3];
            wire c0 = gcarry[j];
            assign cc[4*j]   = c0;
            assign cc[4*j+1] = g0 | (p0 & c0);
            assign cc[4*j+2] = g1 | (p1 & g0) | (p1 & p0 & c0);
            assign cc[4*j+3] = g2 | (p2 & g1) | (p2 & p1 & g0) | (p2 & p1 & p0 & c0);
            wire GG = g3 | (p3 & g2) | (p3 & p2 & g1) | (p3 & p2 & p1 & g0);
            wire PP = p3 & p2 & p1 & p0;
            assign gcarry[j+1] = GG | (PP & c0);
        end
    endgenerate
    assign cla_next = cp ^ cc;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (en) begin
            rca_sum <= rca_next;
            cla_sum <= cla_next;
            armed   <= armed | therm[63];
        end
    end

    assign out = rca_sum;

    always @(posedge clk)
        if (pv && armed && $past(en))
            assert (rca_sum == $past(cla_sum) + {57'd0, $past(cnt)});
endmodule

module axis_scan_lockup (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_sof,
    input  wire        i_eof,
    input  wire        i_vld,
    input  wire [63:0] i_data,
    output wire        o_vld,
    output wire [63:0] o_data
);
    // Scan segment A (MAC-side domain): 4 beats of 64-bit stream data
    reg [3:0]   a_v;
    reg [255:0] a_d;
    // Lockup latch between segments: holds A's tail beat for a half cycle
    reg         lk_v;
    reg [63:0]  lk_d;
    // Scan segment B (UDP-side domain): 4 beats
    reg [3:0]   b_v;
    reg [255:0] b_d;
    // Occupancy of valid beats across the whole chain (8 entries + lockup)
    reg [63:0]  occ;
    // Packet window: opened by start-of-frame, closed by end-of-frame
    reg         armed;

    initial a_v   = 4'b0000;
    initial a_d   = 256'd0;
    initial lk_v  = 1'b0;
    initial lk_d  = 64'd0;
    initial b_v   = 4'b0000;
    initial b_d   = 256'd0;
    initial occ   = 64'd0;
    initial armed = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            a_v   <= 4'b0000;
            a_d   <= 256'd0;
            lk_v  <= 1'b0;
            lk_d  <= 64'd0;
            b_v   <= 4'b0000;
            b_d   <= 256'd0;
            occ   <= 64'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            a_v   <= {a_v[2:0], i_vld};
            a_d   <= {a_d[191:0], i_data};
            lk_v  <= a_v[3];
            lk_d  <= a_d[255:192];
            b_v   <= {b_v[2:0], lk_v};
            b_d   <= {b_d[191:0], lk_d};
            occ   <= occ + {63'd0, i_vld} - {63'd0, b_v[3]};
            armed <= (armed | i_sof) & ~i_eof;
        end
    end

    assign o_vld  = b_v[3];
    assign o_data = b_d[255:192];

    always @(*)
        assert (!armed || occ <= 64'd9);
endmodule

module autobaud_detect (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_rx,
    input  wire        i_arm,
    input  wire        i_clr,
    output wire [31:0] o_divisor,
    output wire        o_locked
);
    localparam [1:0] S_IDLE  = 2'd0;
    localparam [1:0] S_ARMED = 2'd1;
    localparam [1:0] S_MEAS  = 2'd2;
    localparam [1:0] S_DONE  = 2'd3;

    reg [1:0]  stage     = S_IDLE;
    reg        measuring = 1'b0;
    reg [31:0] timer     = 32'd0;
    reg [31:0] divisor   = 32'd0;
    reg        rx_q      = 1'b1;
    reg        win       = 1'b0;
    reg        pv        = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            rx_q <= i_rx;
            if (i_clr) begin
                stage     <= S_IDLE;
                measuring <= 1'b0;
                timer     <= 32'd0;
                win       <= 1'b0;
            end else begin
                if (i_arm) win <= 1'b1;
                // edge-capture timer: count start-bit width
                if (measuring) begin
                    if (i_rx) begin
                        divisor   <= timer + 32'd1;
                        measuring <= 1'b0;
                    end else begin
                        timer <= timer + 32'd1;
                    end
                end
                // measurement-state register: arm -> start -> finish
                case (stage)
                    S_IDLE:  if (i_arm) stage <= S_ARMED;
                    S_ARMED: if (rx_q && !i_rx) begin
                                 stage     <= S_MEAS;
                                 measuring <= 1'b1;
                                 timer     <= 32'd0;
                             end
                    S_MEAS:  if (i_rx) stage <= S_DONE;
                    default: ;
                endcase
            end
        end
    end

    assign o_divisor = divisor;
    assign o_locked  = (stage == S_DONE);

    always @(posedge clk)
        if (pv && win && $stable(stage))
            assert ($stable(divisor));
endmodule

module udp_hamming_tx (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         req,
    input  wire [127:0] data_i,
    input  wire         link_down,
    output wire [136:0] code_o,
    output wire         valid_o
);
    reg [127:0] data_q;
    reg [8:0]   chk_q;
    reg [1:0]   step;
    reg [2:0]   cd;
    reg         busy;
    reg [136:0] code_q;
    reg         valid_q;
    reg         pre_r;

    initial begin
        data_q  = 128'd0;
        chk_q   = 9'd0;
        step    = 2'd0;
        cd      = 3'd0;
        busy    = 1'b0;
        code_q  = 137'd0;
        valid_q = 1'b0;
        pre_r   = 1'b1;
    end

    assign code_o  = code_q;
    assign valid_o = valid_q;

    // current 32-bit beat
    wire [31:0] beat = data_q[{step, 5'b00000} +: 32];

    // Hamming contribution of this beat: data bit idx sits at position 129+idx
    reg [8:0] beat_chk;
    reg [5:0] j;
    always @(*) begin
        beat_chk = 9'd0;
        for (j = 6'd0; j < 6'd32; j = j + 6'd1) begin
            if (beat[j[4:0]]) begin
                beat_chk[7:0] = beat_chk[7:0] ^ (8'd129 + {1'b0, step, j[4:0]});
                beat_chk[8]   = ~beat_chk[8];
            end
        end
    end

    wire [8:0] chk_next  = chk_q ^ beat_chk;
    wire       par_final = chk_next[8] ^ (^chk_next[7:0]);

    always @(posedge clk) begin
        if (!rst_n) begin
            data_q  <= 128'd0;
            chk_q   <= 9'd0;
            step    <= 2'd0;
            cd      <= 3'd0;
            busy    <= 1'b0;
            code_q  <= 137'd0;
            valid_q <= 1'b0;
        end else if (en) begin
            if (busy) begin
                chk_q <= chk_next;
                step  <= step + 2'd1;
                cd    <= cd - 3'd1;
                if (step == 2'd3) begin
                    code_q  <= {par_final, chk_next[7:0], data_q};
                    valid_q <= 1'b1;
                    busy    <= 1'b0;
                end
            end else if (req) begin
                data_q  <= data_i;
                chk_q   <= 9'd0;
                step    <= 2'd0;
                cd      <= 3'd4;
                busy    <= 1'b1;
                valid_q <= 1'b0;
            end
        end
    end

    // scope register: ignores en
    always @(posedge clk) begin
        if (!rst_n)
            pre_r <= 1'b1;
        else if (link_down)
            pre_r <= 1'b0;
    end

    always @(posedge clk)
        if (pre_r) assert (!(busy && cd == 3'd0));
endmodule

module manch_h16_rx (
    input  wire        clk,
    input  wire        en,
    input  wire        sof,
    input  wire        abort,
    input  wire        rx,
    output wire        done,
    output wire [15:0] word,
    output wire        err_o,
    output wire        mid_strobe
);
    reg [31:0] phase;
    reg        last_lvl;
    reg [31:0] shreg;
    reg [31:0] bits_left;
    reg [31:0] deadline;
    reg        busy;
    reg        err;
    reg        win;
    reg        pv;

    initial begin
        phase = 32'd0;
        last_lvl = 1'b0;
        shreg = 32'd0;
        bits_left = 32'd0;
        deadline = 32'd0;
        busy = 1'b0;
        err = 1'b0;
        win = 1'b0;
        pv = 1'b0;
    end

    assign mid_strobe = busy && (phase == 32'd8);
    assign done  = en && busy && !abort && (phase == 32'd15) && (bits_left == 32'd1);
    assign word  = shreg[15:0];
    assign err_o = err;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (en) begin
            if (abort) begin
                busy <= 1'b0;
                win  <= 1'b0;
            end else if (sof && !busy) begin
                busy      <= 1'b1;
                win       <= 1'b1;
                bits_left <= 32'd16;
                phase     <= 32'd0;
                deadline  <= 32'd256;
                err       <= 1'b0;
            end else if (busy) begin
                deadline <= (deadline != 32'd0) ? (deadline - 32'd1) : 32'd0;
                if (phase == 32'd15) begin
                    phase     <= 32'd0;
                    bits_left <= bits_left - 32'd1;
                    if (bits_left == 32'd1) begin
                        busy <= 1'b0;
                        win  <= 1'b0;
                    end
                end else begin
                    phase <= phase + 32'd1;
                end
                if (phase == 32'd4)
                    last_lvl <= rx;
                if (phase == 32'd12) begin
                    if (last_lvl != rx)
                        shreg <= {shreg[30:0], last_lvl};
                    else begin
                        shreg <= {shreg[30:0], 1'b0};
                        err   <= 1'b1;
                    end
                    last_lvl <= rx;
                end
            end
        end
    end

    always @(posedge clk)
        if (pv && win && $rose(mid_strobe))
            assert (deadline != 32'd0);
endmodule

module tbdr_tile_dir (
    input  wire         clk,
    input  wire         en,
    input  wire         rd_req,
    input  wire         wr_req,
    input  wire [3:0]   req_line,
    input  wire [2:0]   req_id,
    input  wire [127:0] wdata,
    input  wire         inv_ack,
    input  wire         tile_begin,
    input  wire         tile_end,
    output reg          gnt_s,
    output reg          gnt_x,
    output reg          win,
    output reg          busy,
    output reg  [3:0]   ack_cnt
);
    reg [31:0]   st_f;
    reg [127:0]  shr_f;
    reg [47:0]   own_f;
    reg [2047:0] data_f;
    reg [3:0]    tline;
    reg [2:0]    treq;
    reg [127:0]  tdata;

    initial begin
        st_f    = 32'd0;
        shr_f   = 128'd0;
        own_f   = 48'd0;
        data_f  = 2048'd0;
        tline   = 4'd0;
        treq    = 3'd0;
        tdata   = 128'd0;
        busy    = 1'b0;
        ack_cnt = 4'd0;
        gnt_s   = 1'b0;
        gnt_x   = 1'b0;
        win     = 1'b0;
    end

    wire [7:0] shr_cur  = shr_f[req_line*8 +: 8];
    wire [7:0] id_mask  = 8'd1 << req_id;
    wire [7:0] others   = shr_cur & ~id_mask;
    wire [3:0] pop      = {3'd0, others[0]} + {3'd0, others[1]} + {3'd0, others[2]} + {3'd0, others[3]}
                        + {3'd0, others[4]} + {3'd0, others[5]} + {3'd0, others[6]} + {3'd0, others[7]};
    wire       no_other = (others == 8'd0);
    wire       wr_go    = wr_req && !busy;
    wire       rd_go    = rd_req && !wr_req && !busy;
    wire       ack_go   = inv_ack && (ack_cnt != 4'd0);
    wire       ack_last = ack_go && (ack_cnt == 4'd1);

    always @(posedge clk) begin
        if (en) begin
            gnt_s <= rd_go;
            gnt_x <= (wr_go && no_other) || ack_last;
            win   <= tile_begin ? 1'b1 : (tile_end ? 1'b0 : win);

            if (wr_go) begin
                if (!no_other) begin
                    busy    <= 1'b1;
                    ack_cnt <= pop;
                    tline   <= req_line;
                    treq    <= req_id;
                    tdata   <= wdata;
                    st_f[req_line*2 +: 2] <= 2'd3;
                end else begin
                    data_f[req_line*128 +: 128] <= wdata;
                    st_f[req_line*2 +: 2]       <= 2'd2;
                    own_f[req_line*3 +: 3]      <= req_id;
                    shr_f[req_line*8 +: 8]      <= 8'd0;
                end
            end else if (rd_go) begin
                shr_f[req_line*8 + req_id] <= 1'b1;
                st_f[req_line*2 +: 2]      <= 2'd1;
            end

            if (ack_go) begin
                ack_cnt <= ack_cnt - 4'd1;
                if (ack_cnt == 4'd1) begin
                    busy <= 1'b0;
                    st_f[tline*2 +: 2]       <= 2'd2;
                    own_f[tline*3 +: 3]      <= treq;
                    shr_f[tline*8 +: 8]      <= 8'd0;
                    data_f[tline*128 +: 128] <= tdata;
                end
            end
        end
    end

    always @(*) if (win) assert (!(gnt_s && gnt_x));
endmodule

module swd_target_port (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        swdio_in,
    output wire        swdio_oe,
    output wire        swdio_out,
    output wire [31:0] o_wdata,
    output wire        o_busy
);
    localparam [2:0] PH_IDLE = 3'd0;
    localparam [2:0] PH_REQ  = 3'd1;
    localparam [2:0] PH_TRN1 = 3'd2;
    localparam [2:0] PH_ACK  = 3'd3;
    localparam [2:0] PH_DATA = 3'd4;
    localparam [2:0] PH_TRN2 = 3'd5;
    localparam [31:0] K = 32'd38;

    reg [2:0]  phase;
    reg [7:0]  req_sr;
    reg [31:0] bitcnt;
    reg [31:0] data_sr;
    reg        par_acc;
    reg        rnw_q;
    reg        outstanding;
    reg [31:0] countdown;
    reg        no_err;
    reg [31:0] wdata;

    initial begin
        phase = PH_IDLE;
        req_sr = 8'd0;
        bitcnt = 32'd0;
        data_sr = 32'd0;
        par_acc = 1'b0;
        rnw_q = 1'b0;
        outstanding = 1'b0;
        countdown = 32'd0;
        no_err = 1'b1;
        wdata = 32'd0;
    end

    wire [7:0] req_full = {swdio_in, req_sr[7:1]};
    wire req_ok = req_full[0] && !req_full[6] && req_full[7] &&
                  (req_full[5] == ^req_full[4:1]);

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE;
            req_sr <= 8'd0;
            bitcnt <= 32'd0;
            data_sr <= 32'd0;
            par_acc <= 1'b0;
            rnw_q <= 1'b0;
            outstanding <= 1'b0;
            countdown <= 32'd0;
            no_err <= 1'b1;
            wdata <= 32'd0;
        end else if (ce) begin
            case (phase)
                PH_IDLE: begin
                    if (swdio_in) begin
                        req_sr <= req_full;
                        bitcnt <= 32'd1;
                        phase <= PH_REQ;
                    end
                end
                PH_REQ: begin
                    req_sr <= req_full;
                    if (bitcnt == 32'd7) begin
                        bitcnt <= 32'd0;
                        if (req_ok) begin
                            phase <= PH_TRN1;
                            outstanding <= 1'b1;
                            countdown <= K;
                            rnw_q <= req_full[2];
                        end else begin
                            phase <= PH_IDLE;
                            no_err <= 1'b0;
                        end
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                    end
                end
                PH_TRN1: begin
                    phase <= PH_ACK;
                    bitcnt <= 32'd0;
                    countdown <= countdown - 32'd1;
                    par_acc <= 1'b0;
                    if (rnw_q) data_sr <= wdata;
                    else data_sr <= 32'd0;
                end
                PH_ACK: begin
                    countdown <= countdown - 32'd1;
                    if (bitcnt == 32'd2) begin
                        phase <= PH_DATA;
                        bitcnt <= 32'd0;
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                    end
                end
                PH_DATA: begin
                    countdown <= countdown - 32'd1;
                    if (bitcnt == 32'd32) begin
                        phase <= PH_TRN2;
                        bitcnt <= 32'd0;
                        if (!rnw_q) begin
                            if (par_acc != swdio_in) no_err <= 1'b0;
                            else wdata <= data_sr;
                        end
                    end else begin
                        bitcnt <= bitcnt + 32'd1;
                        if (rnw_q) begin
                            par_acc <= par_acc ^ data_sr[0];
                            data_sr <= {1'b0, data_sr[31:1]};
                        end else begin
                            par_acc <= par_acc ^ swdio_in;
                            data_sr <= {swdio_in, data_sr[31:1]};
                        end
                    end
                end
                PH_TRN2: begin
                    phase <= PH_IDLE;
                    outstanding <= 1'b0;
                    countdown <= 32'd0;
                end
                default: begin
                    phase <= PH_IDLE;
                end
            endcase
        end
    end

    assign swdio_oe  = (phase == PH_ACK) || (phase == PH_DATA && rnw_q);
    assign swdio_out = (phase == PH_ACK) ? (bitcnt == 32'd0) :
                       ((bitcnt == 32'd32) ? par_acc : data_sr[0]);
    assign o_wdata = wdata;
    assign o_busy  = outstanding;

    assert property (!no_err || !outstanding || countdown != 32'd0);
endmodule

module sd_line_fill_uart #(
    parameter [15:0] CLKS_PER_BIT = 16'd16
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        rx,
    input  wire        flush,
    output wire [15:0] o_occ,
    output wire        o_full,
    output wire        o_ferr,
    output wire [15:0] o_word0
);
    localparam [1:0] S_IDLE  = 2'd0;
    localparam [1:0] S_START = 2'd1;
    localparam [1:0] S_DATA  = 2'd2;
    localparam [1:0] S_STOP  = 2'd3;

    reg [1:0]  st;
    reg [15:0] baud_cnt;
    reg [15:0] bit_cnt;
    reg [15:0] shreg;
    reg [15:0] line [0:7];
    reg [2:0]  wr_ptr;
    reg [15:0] occ;
    reg        line_full;
    reg        frame_err;
    reg        armed;
    reg        rx_prev;

    integer i;
    initial begin
        st = S_IDLE;
        baud_cnt = 16'd0;
        bit_cnt = 16'd0;
        shreg = 16'd0;
        wr_ptr = 3'd0;
        occ = 16'd0;
        line_full = 1'b0;
        frame_err = 1'b0;
        armed = 1'b0;
        rx_prev = 1'b1;
        for (i = 0; i < 8; i = i + 1) line[i] = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            st <= S_IDLE;
            baud_cnt <= 16'd0;
            bit_cnt <= 16'd0;
            shreg <= 16'd0;
            wr_ptr <= 3'd0;
            occ <= 16'd0;
            line_full <= 1'b0;
            frame_err <= 1'b0;
            armed <= 1'b0;
            rx_prev <= 1'b1;
        end else if (en) begin
            rx_prev <= rx;
            case (st)
                S_IDLE: begin
                    baud_cnt <= 16'd0;
                    bit_cnt <= 16'd0;
                    if (rx_prev && !rx) st <= S_START;
                end
                S_START: begin
                    if (baud_cnt == (CLKS_PER_BIT >> 1) - 16'd1) begin
                        baud_cnt <= 16'd0;
                        if (!rx) st <= S_DATA;
                        else st <= S_IDLE;
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
                S_DATA: begin
                    if (baud_cnt == CLKS_PER_BIT - 16'd1) begin
                        baud_cnt <= 16'd0;
                        shreg <= {rx, shreg[15:1]};
                        if (bit_cnt == 16'd15) begin
                            bit_cnt <= 16'd0;
                            st <= S_STOP;
                        end else begin
                            bit_cnt <= bit_cnt + 16'd1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
                S_STOP: begin
                    if (baud_cnt == CLKS_PER_BIT - 16'd1) begin
                        baud_cnt <= 16'd0;
                        st <= S_IDLE;
                        if (!rx) begin
                            frame_err <= 1'b1;
                        end else if (!line_full) begin
                            line[wr_ptr] <= shreg;
                            wr_ptr <= wr_ptr + 3'd1;
                            occ <= occ + 16'd1;
                            line_full <= ((occ + 16'd1) == 16'd8);
                            armed <= 1'b1;
                        end
                    end else begin
                        baud_cnt <= baud_cnt + 16'd1;
                    end
                end
            endcase
            if (flush) begin
                occ <= 16'd0;
                wr_ptr <= 3'd0;
                line_full <= 1'b0;
                frame_err <= 1'b0;
            end
        end
    end

    assign o_occ = occ;
    assign o_full = line_full;
    assign o_ferr = frame_err;
    assign o_word0 = line[0];

    always @(posedge clk)
        if (armed)
            assert (occ <= 16'd8);
endmodule

module bitserial_alu (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       arm,
    input  wire       start,
    input  wire       ack,
    input  wire [1:0] op,
    input  wire [7:0] a_in,
    input  wire [7:0] b_in,
    output wire [7:0] result,
    output wire       done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;

    reg [1:0] phase      = 2'd0;
    reg [7:0] cnt        = 8'd0;
    reg       seen_arm   = 1'b0;
    reg       seen_start = 1'b0;
    reg [1:0] op_r       = 2'd0;
    reg [7:0] opa        = 8'd0;
    reg [7:0] opb        = 8'd0;
    reg [7:0] res        = 8'd0;
    reg       carry      = 1'b0;

    wire abit = opa[0];
    wire bbit = (op_r == 2'd1) ? ~opb[0] : opb[0];
    wire sbit = abit ^ bbit ^ carry;
    wire cout = (abit & bbit) | (abit & carry) | (bbit & carry);
    wire fbit = (op_r == 2'd2) ? (abit & opb[0]) :
                (op_r == 2'd3) ? (abit ^ opb[0]) : sbit;

    assign result = res;
    assign done   = (phase == DONE);

    always @(posedge clk) begin
        if (rst) begin
            phase      <= IDLE;
            cnt        <= 8'd0;
            seen_arm   <= 1'b0;
            seen_start <= 1'b0;
            carry      <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: begin
                    if (arm) begin
                        phase      <= ARMED;
                        seen_arm   <= 1'b1;
                        seen_start <= 1'b0;
                        op_r       <= op;
                    end
                end
                ARMED: begin
                    if (start) begin
                        phase      <= RUN;
                        seen_start <= 1'b1;
                        cnt        <= 8'd0;
                        opa        <= a_in;
                        opb        <= b_in;
                        res        <= 8'd0;
                        carry      <= (op_r == 2'd1);
                    end
                end
                RUN: begin
                    res   <= {fbit, res[7:1]};
                    opa   <= {1'b0, opa[7:1]};
                    opb   <= {1'b0, opb[7:1]};
                    carry <= (op_r[1] == 1'b0) ? cout : 1'b0;
                    if (cnt == 8'd7) begin
                        phase <= DONE;
                        cnt   <= 8'd8;
                    end else begin
                        cnt <= cnt + 8'd1;
                    end
                end
                DONE: begin
                    if (ack) begin
                        phase      <= IDLE;
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
            endcase
        end
    end

    assert property (phase != 2'd3 || (seen_arm && seen_start));
endmodule

module tplan_banner_gen (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire arm_req,
    input wire start_req,
    input wire abort_req,
    input wire wr_en,
    input wire [4:0] wr_addr,
    input wire [63:0] wr_data,
    output wire [7:0] o_pix,
    output wire o_done
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, FIN = 2'd3;

    reg [63:0] char_mem [0:23];
    reg [63:0] col_cnt;
    reg [63:0] row_cnt;
    reg [63:0] frame_cnt;
    reg [1:0]  phase;
    reg        arm_seen;
    reg        start_seen;
    reg        done;
    reg        before_abort;
    reg [7:0]  pix_row;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1)
            char_mem[i] = 64'd32;
    end
    initial col_cnt = 64'd0;
    initial row_cnt = 64'd0;
    initial frame_cnt = 64'd0;
    initial phase = IDLE;
    initial arm_seen = 1'b0;
    initial start_seen = 1'b0;
    initial done = 1'b0;
    initial before_abort = 1'b1;
    initial pix_row = 8'h00;

    function [7:0] font_row;
        input [7:0] c;
        input [2:0] r;
        begin
            case (c)
                8'h54: font_row = (r == 3'd0) ? 8'hFE : 8'h10;
                8'h50: font_row = (r < 3'd4) ? 8'hFC : 8'h80;
                8'h41: font_row = (r == 3'd0) ? 8'h38 : ((r == 3'd4) ? 8'hFE : 8'h82);
                8'h53: font_row = (r[0]) ? 8'h80 : 8'h7C;
                8'h20: font_row = 8'h00;
                default: font_row = c ^ {r, r, r[1:0]};
            endcase
        end
    endfunction

    wire [7:0] cur_char = (col_cnt < 64'd24) ? char_mem[col_cnt[4:0]][7:0] : 8'h20;
    wire last_col = (col_cnt >= 64'd23);
    wire last_row = (row_cnt >= 64'd7);

    always @(posedge clk) begin
        if (!rst_n) begin
            col_cnt <= 64'd0;
            row_cnt <= 64'd0;
            frame_cnt <= 64'd0;
            phase <= IDLE;
            arm_seen <= 1'b0;
            start_seen <= 1'b0;
            done <= 1'b0;
            before_abort <= 1'b1;
            pix_row <= 8'h00;
        end else if (en) begin
            if (wr_en && (wr_addr < 5'd24))
                char_mem[wr_addr] <= wr_data;
            if (abort_req) begin
                phase <= IDLE;
                arm_seen <= 1'b0;
                start_seen <= 1'b0;
                done <= 1'b0;
                before_abort <= 1'b0;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                    ARMED: begin
                        if (start_req) begin
                            phase <= RUN;
                            start_seen <= 1'b1;
                            col_cnt <= 64'd0;
                            row_cnt <= 64'd0;
                        end
                    end
                    RUN: begin
                        pix_row <= font_row(cur_char, row_cnt[2:0]);
                        if (last_col) begin
                            col_cnt <= 64'd0;
                            if (last_row) begin
                                row_cnt <= 64'd0;
                                phase <= FIN;
                                done <= 1'b1;
                                frame_cnt <= frame_cnt + 64'd1;
                            end else begin
                                row_cnt <= row_cnt + 64'd1;
                            end
                        end else begin
                            col_cnt <= col_cnt + 64'd1;
                        end
                    end
                    FIN: begin
                        if (arm_req) begin
                            phase <= ARMED;
                            arm_seen <= 1'b1;
                            done <= 1'b0;
                        end
                    end
                endcase
            end
        end
    end

    assign o_pix = pix_row;
    assign o_done = done;

    always @(posedge clk)
        if (before_abort && done)
            assert (arm_seen && start_seen);
endmodule

module cplx_mixer (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        lock,
    input  wire        unlock,
    input  wire [63:0] s_i,
    input  wire [63:0] s_q,
    input  wire [63:0] lo_i,
    input  wire [63:0] lo_q,
    output reg  [63:0] y_i,
    output reg  [63:0] y_q
);
    // stage 1: four partial products of (s_i + j s_q) * (lo_i + j lo_q)
    reg [63:0] pp_ii, pp_qq, pp_iq, pp_qi;
    // shadow: the partial products that were summed into the current output
    reg [63:0] sp_ii, sp_qq, sp_iq, sp_qi;
    // observation window: opened by LO lock, closed by unlock (may never close)
    reg win;
    reg pv;

    initial begin
        pp_ii = 64'd0; pp_qq = 64'd0; pp_iq = 64'd0; pp_qi = 64'd0;
        sp_ii = 64'd0; sp_qq = 64'd0; sp_iq = 64'd0; sp_qi = 64'd0;
        y_i = 64'd0; y_q = 64'd0;
        win = 1'b0;
        pv = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            pp_ii <= 64'd0; pp_qq <= 64'd0; pp_iq <= 64'd0; pp_qi <= 64'd0;
            sp_ii <= 64'd0; sp_qq <= 64'd0; sp_iq <= 64'd0; sp_qi <= 64'd0;
            y_i <= 64'd0; y_q <= 64'd0;
        end else if (ce) begin
            pp_ii <= s_i * lo_i;
            pp_qq <= s_q * lo_q;
            pp_iq <= s_i * lo_q;
            pp_qi <= s_q * lo_i;
            sp_ii <= pp_ii;
            sp_qq <= pp_qq;
            sp_iq <= pp_iq;
            sp_qi <= pp_qi;
            y_i   <= pp_ii - pp_qq;
            y_q   <= pp_iq + pp_qi;
        end
    end

    always @(posedge clk) begin
        if (rst)         win <= 1'b0;
        else if (lock)   win <= 1'b1;
        else if (unlock) win <= 1'b0;
    end

    // precedence: within the lock window, an output change must be preceded by
    // a change in the partial products that feed the summer
    always @(posedge clk)
        if (pv && win && $stable(sp_ii) && $stable(sp_qq) && $stable(sp_iq) && $stable(sp_qi))
            assert ($stable(y_i) && $stable(y_q));
endmodule

module bfx_unit (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [2:0] i_op,
    input  wire       i_lock,
    input  wire       i_unlock,
    input  wire [7:0] i_src,
    input  wire [7:0] i_dst,
    output wire [7:0] o_res
);
    // field control: start position, width, and remaining headroom above the field
    reg [7:0] pos;
    reg [7:0] wid;
    reg [7:0] rem;
    reg [7:0] res;
    reg       win;
    initial pos = 8'd0;
    initial wid = 8'd0;
    initial rem = 8'd8;
    initial res = 8'd0;
    initial win = 1'b0;

    localparam OP_GROW = 3'd0, OP_SHRINK = 3'd1, OP_ADV = 3'd2, OP_RET = 3'd3,
               OP_EXTZ = 3'd4, OP_EXTS = 3'd5, OP_INS = 3'd6, OP_NOP = 3'd7;

    wire [7:0] mask = (wid >= 8'd8) ? 8'hFF : ((8'd1 << wid) - 8'd1);
    wire [7:0] ext  = (i_src >> pos) & mask;
    wire       sbit = ((wid != 8'd0) && (wid < 8'd8)) ? ext[wid[2:0] - 3'd1] : 1'b0;
    wire [7:0] exts = sbit ? (ext | ~mask) : ext;
    wire [7:0] ins  = (i_dst & ~(mask << pos)) | ((i_src & mask) << pos);

    always @(posedge clk) begin
        if (i_reset) begin
            pos <= 8'd0;
            wid <= 8'd0;
            rem <= 8'd8;
            res <= 8'd0;
            win <= 1'b0;
        end else if (i_ce) begin
            if (i_unlock)
                win <= 1'b0;
            else if (i_lock)
                win <= 1'b1;
            case (i_op)
                OP_GROW:   if (rem != 8'd0) begin wid <= wid + 8'd1; rem <= rem - 8'd1; end
                OP_SHRINK: if (wid != 8'd0) begin wid <= wid - 8'd1; rem <= rem + 8'd1; end
                OP_ADV:    if (rem != 8'd0) begin pos <= pos + 8'd1; rem <= rem - 8'd1; end
                OP_RET:    if (pos != 8'd0) begin pos <= pos - 8'd1; rem <= rem + 8'd1; end
                OP_EXTZ:   res <= ext;
                OP_EXTS:   res <= exts;
                OP_INS:    res <= ins;
                default:   ;
            endcase
        end
    end

    assign o_res = res;

    // between lock and unlock: field width never exceeds the word size
    always @(posedge clk)
        if (win) assert (wid <= 8'd8);
endmodule

module pmod_simd_div (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire       req,
    input  wire       req_mode,
    input  wire [7:0] dividend,
    input  wire [7:0] divisor,
    input  wire       cfg_wr,
    output reg        resp_valid,
    output wire [7:0] quotient,
    output wire [7:0] remainder,
    output wire       busy_o
);
    reg       busy = 1'b0;
    reg       mode = 1'b0;
    reg [7:0] prem = 8'd0;
    reg [7:0] dvs  = 8'd0;
    reg [7:0] quo  = 8'd0;
    reg [7:0] cnt  = 8'd0;
    reg [7:0] dl   = 8'd0;
    reg       pre  = 1'b1;
    initial resp_valid = 1'b0;

    assign quotient  = quo;
    assign remainder = prem;
    assign busy_o    = busy;

    wire [7:0] w_cur = mode     ? 8'd4 : 8'd8;
    wire [7:0] w_req = req_mode ? 8'd4 : 8'd8;
    wire       last  = (cnt == (w_cur - 8'd1));

    // 8-bit lane
    wire [8:0] r8  = {prem, quo[7]};
    wire       ge8 = (r8 >= {1'b0, dvs});
    wire [8:0] s8  = r8 - {1'b0, dvs};

    // two 4-bit lanes
    wire [4:0] rlo  = {prem[3:0], quo[3]};
    wire       gelo = (rlo >= {1'b0, dvs[3:0]});
    wire [4:0] slo  = rlo - {1'b0, dvs[3:0]};
    wire [4:0] rhi  = {prem[7:4], quo[7]};
    wire       gehi = (rhi >= {1'b0, dvs[7:4]});
    wire [4:0] shi  = rhi - {1'b0, dvs[7:4]};

    wire [7:0] prem_n = mode ? {(gehi ? shi[3:0] : rhi[3:0]), (gelo ? slo[3:0] : rlo[3:0])}
                             : (ge8 ? s8[7:0] : r8[7:0]);
    wire [7:0] quo_n  = mode ? {quo[6:4], gehi, quo[2:0], gelo}
                             : {quo[6:0], ge8};

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                busy <= 1'b0;
                cnt  <= 8'd0;
                dl   <= 8'd0;
                mode <= 1'b0;
                pre  <= 1'b1;
                resp_valid <= 1'b0;
            end else begin
                resp_valid <= 1'b0;
                if (!busy) begin
                    if (cfg_wr)
                        pre <= 1'b0;
                    if (req) begin
                        prem <= 8'd0;
                        quo  <= dividend;
                        dvs  <= divisor;
                        mode <= req_mode;
                        cnt  <= 8'd0;
                        dl   <= w_req;
                        busy <= 1'b1;
                    end
                end else begin
                    prem <= prem_n;
                    quo  <= quo_n;
                    cnt  <= cnt + 8'd1;
                    dl   <= dl - 8'd1;
                    if (last) begin
                        busy <= 1'b0;
                        resp_valid <= 1'b1;
                    end
                end
            end
        end
    end

    // A1: countdown never expires while an operation is outstanding
    always @(*)
        if (pre && busy)
            assert (dl != 8'd0);

    // A2: deadline and completion coincide
    always @(*)
        if (pre && busy && dl == 8'd1)
            assert (cnt == (mode ? 8'd3 : 8'd7));
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
    output reg rest_ack
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
                        ramp_ack <= 1'b1;
                        state <= S_REST;
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
endmodule

module tcu_useq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [2:0]  op,
    input  wire        cond,
    input  wire [1:0]  sel,
    input  wire        tw_en,
    input  wire [1:0]  tw_idx,
    input  wire [15:0] tw_data,
    output wire [15:0] upc_o,
    output wire        ret_valid_o
);
    localparam [2:0] OP_INC  = 3'd0;
    localparam [2:0] OP_JMP  = 3'd1;
    localparam [2:0] OP_BR   = 3'd2;
    localparam [2:0] OP_CALL = 3'd3;
    localparam [2:0] OP_RET  = 3'd4;

    reg [15:0] upc;
    reg [15:0] jt0, jt1, jt2, jt3;
    reg [15:0] ret_reg;
    reg        ret_valid;
    reg [15:0] shadow_ret;
    reg        pv;

    initial upc = 16'h0000;
    initial jt0 = 16'h0000;
    initial jt1 = 16'h0000;
    initial jt2 = 16'h0000;
    initial jt3 = 16'h0000;
    initial ret_reg = 16'h0000;
    initial ret_valid = 1'b0;
    initial shadow_ret = 16'h0000;
    initial pv = 1'b0;

    reg [15:0] tgt;
    always @(*) begin
        case (sel)
            2'd0: tgt = jt0;
            2'd1: tgt = jt1;
            2'd2: tgt = jt2;
            default: tgt = jt3;
        endcase
    end

    wire [15:0] upc_inc = upc + 16'h0001;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            upc        <= 16'h0000;
            jt0        <= 16'h0000;
            jt1        <= 16'h0000;
            jt2        <= 16'h0000;
            jt3        <= 16'h0000;
            ret_reg    <= 16'h0000;
            ret_valid  <= 1'b0;
            shadow_ret <= 16'h0000;
        end else if (en) begin
            if (tw_en) begin
                case (tw_idx)
                    2'd0: jt0 <= tw_data;
                    2'd1: jt1 <= tw_data;
                    2'd2: jt2 <= tw_data;
                    default: jt3 <= tw_data;
                endcase
            end
            case (op)
                OP_INC:  upc <= upc_inc;
                OP_JMP:  upc <= tgt;
                OP_BR:   upc <= cond ? tgt : upc_inc;
                OP_CALL: begin
                    ret_reg    <= upc_inc;
                    shadow_ret <= upc_inc;
                    ret_valid  <= 1'b1;
                    upc        <= tgt;
                end
                OP_RET: begin
                    if (ret_valid) begin
                        upc       <= ret_reg;
                        ret_valid <= 1'b0;
                    end else begin
                        upc <= upc_inc;
                    end
                end
                default: upc <= upc_inc;
            endcase
        end
    end

    assign upc_o = upc;
    assign ret_valid_o = ret_valid;

    always @(posedge clk)
        if (pv && $past(en) && !$past(rst) && ($past(op) == 3'd4) && $past(ret_valid))
            assert (upc == $past(shadow_ret));
endmodule

module razor_shadow_stage (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire [63:0] d_main,
    input  wire [63:0] d_late,
    output reg  [63:0] main_q,
    output reg  [63:0] shadow_q,
    output reg  [63:0] err_cnt,
    output reg         razor_err
);
    localparam [1:0] IDLE    = 2'd0;
    localparam [1:0] ARMED   = 2'd1;
    localparam [1:0] STARTED = 2'd2;
    localparam [1:0] DONE    = 2'd3;

    reg [1:0] phase = IDLE;
    reg armed = 1'b0;
    reg started = 1'b0;
    reg finished = 1'b0;

    initial begin
        main_q    = 64'd0;
        shadow_q  = 64'd0;
        err_cnt   = 64'd0;
        razor_err = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase     <= IDLE;
            armed     <= 1'b0;
            started   <= 1'b0;
            finished  <= 1'b0;
            main_q    <= 64'd0;
            shadow_q  <= 64'd0;
            err_cnt   <= 64'd0;
            razor_err <= 1'b0;
        end else if (ce) begin
            case (phase)
                IDLE: begin
                    main_q   <= d_main;
                    armed    <= 1'b1;
                    started  <= 1'b0;
                    finished <= 1'b0;
                    phase    <= ARMED;
                end
                ARMED: begin
                    shadow_q <= d_late;
                    started  <= 1'b1;
                    phase    <= STARTED;
                end
                STARTED: begin
                    razor_err <= (main_q != shadow_q);
                    if (main_q != shadow_q) begin
                        main_q  <= shadow_q;
                        err_cnt <= err_cnt + 64'd1;
                    end
                    finished <= 1'b1;
                    phase    <= DONE;
                end
                default: begin
                    armed    <= 1'b0;
                    started  <= 1'b0;
                    finished <= 1'b0;
                    phase    <= IDLE;
                end
            endcase
        end
    end

    always @(posedge clk)
        if (finished) assert (started && armed);
endmodule

module iq_imbalance_corr (
    input  wire         clk,
    input  wire         rst,
    input  wire         ce,
    input  wire         in_valid,
    input  wire [127:0] i_in,
    input  wire [127:0] q_in,
    input  wire         coef_we,
    input  wire [7:0]   gain_in,
    input  wire [7:0]   phase_in,
    input  wire         cal_start,
    input  wire         cal_stop,
    output wire         out_valid,
    output wire [127:0] i_out,
    output wire [127:0] q_out,
    output wire [2:0]   inflight_o
);
    // programmable correction coefficients (Q1.7 fixed point)
    reg [7:0] gain;
    reg [7:0] phase;
    // pipeline valid bits
    reg v0, v1, v2, v3;
    // pipeline data
    reg [127:0] i0, q0, i1, i2, i3, q3;
    reg [135:0] p_i, p_q;
    reg [136:0] s2;
    // occupancy of the correction pipeline
    reg [2:0] inflight;
    // calibration observation window
    reg win;

    initial begin
        gain = 8'd128; phase = 8'd0;
        v0 = 1'b0; v1 = 1'b0; v2 = 1'b0; v3 = 1'b0;
        i0 = 128'd0; q0 = 128'd0; i1 = 128'd0; i2 = 128'd0; i3 = 128'd0; q3 = 128'd0;
        p_i = 136'd0; p_q = 136'd0; s2 = 137'd0;
        inflight = 3'd0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            gain <= 8'd128; phase <= 8'd0;
            v0 <= 1'b0; v1 <= 1'b0; v2 <= 1'b0; v3 <= 1'b0;
            inflight <= 3'd0;
            win <= 1'b0;
        end else if (ce) begin
            if (coef_we) begin
                gain  <= gain_in;
                phase <= phase_in;
            end
            // stage 0: capture complex sample
            v0 <= in_valid;
            i0 <= i_in;
            q0 <= q_in;
            // stage 1: correction matrix products
            v1  <= v0;
            i1  <= i0;
            p_q <= q0 * gain;
            p_i <= i0 * phase;
            // stage 2: cross-branch sum
            v2 <= v1;
            i2 <= i1;
            s2 <= p_q + p_i;
            // stage 3: corrected output
            v3 <= v2;
            i3 <= i2;
            q3 <= s2[134:7];
            // occupancy bookkeeping
            inflight <= inflight + {2'b00, in_valid} - {2'b00, v3};
            // calibration window: opened by cal_start, closed by cal_stop
            if (cal_start)
                win <= 1'b1;
            else if (cal_stop)
                win <= 1'b0;
        end
    end

    assign out_valid  = v3;
    assign i_out      = i3;
    assign q_out      = q3;
    assign inflight_o = inflight;

    // within a calibration window, at most 4 samples are in flight
    always @(posedge clk)
        if (win)
            assert (inflight <= 3'd4);

    // within a calibration window, an empty pipeline presents no output
    always @(posedge clk)
        if (win && inflight == 3'd0)
            assert (!v3);
endmodule

module wstrobe_demux_bank (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_we,
    input  wire [4:0]  i_addr,
    input  wire [63:0] i_data,
    input  wire        i_ce,
    output wire [31:0] o_strobe,
    output wire        o_busy,
    output wire [63:0] o_num_valid
);
    reg        pending;
    reg [4:0]  addr_q;
    reg [63:0] data_q;
    reg [31:0] valid;
    reg [63:0] num_valid;
    reg        armed;
    reg [63:0] bank [0:31];
    integer i;
    initial begin
        pending = 1'b0;
        addr_q = 5'd0;
        data_q = 64'd0;
        valid = 32'd0;
        num_valid = 64'd0;
        armed = 1'b0;
        for (i = 0; i < 32; i = i + 1) bank[i] = 64'd0;
    end

    wire fire = pending && i_ce;
    wire [31:0] strobe = fire ? (32'd1 << addr_q) : 32'd0;
    wire newly_valid = |(strobe & ~valid);

    reg [63:0] valid_pop;
    integer k;
    always @(*) begin
        valid_pop = 64'd0;
        for (k = 0; k < 32; k = k + 1)
            valid_pop = valid_pop + {63'd0, valid[k]};
    end

    always @(posedge clk) begin
        if (rst) begin
            pending <= 1'b0;
            valid <= 32'd0;
            num_valid <= 64'd0;
        end else begin
            if (fire) begin
                pending <= 1'b0;
                valid <= valid | strobe;
                if (newly_valid)
                    num_valid <= num_valid + 64'd1;
                armed <= 1'b1;
            end else if (i_we && !pending) begin
                pending <= 1'b1;
                addr_q <= i_addr;
                data_q <= i_data;
            end
        end
    end

    always @(posedge clk) begin
        for (i = 0; i < 32; i = i + 1)
            if (!rst && strobe[i]) bank[i] <= data_q;
    end

    assign o_strobe = strobe;
    assign o_busy = pending;
    assign o_num_valid = num_valid;

    assert property (!armed || (num_valid <= 64'd32));
endmodule

module caribou_cuckoo_barrett (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        req,
    input  wire [31:0] a,
    input  wire [31:0] b,
    input  wire        rehash,
    input  wire [31:0] new_mod,
    output reg  [32:0] res_r,
    output reg         done,
    output reg         busy,
    output reg         expired
);
    reg [31:0] mod_r;
    reg [32:0] mu_r;
    reg [63:0] prod_r;
    reg [31:0] q_r;
    reg [2:0]  stage;
    reg [31:0] cnt;
    reg        pre_rehash;

    initial begin
        mod_r      = 32'hFFFF_FFFF;
        mu_r       = 33'h1_0000_0001;
        prod_r     = 64'd0;
        q_r        = 32'd0;
        res_r      = 33'd0;
        stage      = 3'd0;
        cnt        = 32'd0;
        busy       = 1'b0;
        done       = 1'b0;
        expired    = 1'b0;
        pre_rehash = 1'b1;
    end

    wire [64:0] two64   = {1'b1, 64'd0};
    wire [64:0] mu_full = (new_mod == 32'd0) ? 65'd0 : (two64 / {33'd0, new_mod});
    wire [96:0] pm      = prod_r * mu_r;
    wire [63:0] qm      = q_r * mod_r;
    wire [63:0] diff    = prod_r - qm;
    wire [32:0] mod_ext = {1'b0, mod_r};

    always @(posedge clk) begin
        if (rst) begin
            mod_r      <= 32'hFFFF_FFFF;
            mu_r       <= 33'h1_0000_0001;
            prod_r     <= 64'd0;
            q_r        <= 32'd0;
            res_r      <= 33'd0;
            stage      <= 3'd0;
            cnt        <= 32'd0;
            busy       <= 1'b0;
            done       <= 1'b0;
            expired    <= 1'b0;
            pre_rehash <= 1'b1;
        end else if (en) begin
            if (rehash) pre_rehash <= 1'b0;
            if (!busy) begin
                if (req) begin
                    prod_r <= a * b;
                    busy   <= 1'b1;
                    stage  <= 3'd0;
                    cnt    <= 32'd5;
                    done   <= 1'b0;
                end else if (rehash) begin
                    mod_r <= new_mod;
                    mu_r  <= mu_full[32:0];
                    done  <= 1'b0;
                end
            end else begin
                cnt     <= cnt - 32'd1;
                expired <= expired | ((cnt == 32'd1) && (stage != 3'd4));
                case (stage)
                    3'd0: begin
                        q_r   <= pm[95:64];
                        stage <= 3'd1;
                    end
                    3'd1: begin
                        res_r <= diff[32:0];
                        stage <= 3'd2;
                    end
                    3'd2: begin
                        if (res_r >= mod_ext) res_r <= res_r - mod_ext;
                        stage <= 3'd3;
                    end
                    3'd3: begin
                        if (res_r >= mod_ext) res_r <= res_r - mod_ext;
                        stage <= 3'd4;
                    end
                    3'd4: begin
                        done <= 1'b1;
                        busy <= 1'b0;
                    end
                    default: begin
                        stage <= stage;
                    end
                endcase
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) begin
        pv <= 1'b1;
        if (pv && pre_rehash && en && $stable(done))
            assert ($stable(expired));
    end
endmodule

module kaze_gust_meter (
    input wire clk,
    input wire rst,
    input wire en,
    input wire inc,
    input wire q_open,
    input wire r_close,
    output wire calm,
    output wire storm
);
    reg [63:0] b;
    reg [63:0] g;
    reg        win;
    initial b = 64'd0;
    initial g = 64'd0;
    initial win = 1'b0;

    wire [63:0] b_nxt = b + 64'd1;

    always @(posedge clk) begin
        if (rst) begin
            b   <= 64'd0;
            g   <= 64'd0;
            win <= 1'b0;
        end else if (en) begin
            if (inc) begin
                b <= b_nxt;
                g <= b_nxt ^ (b_nxt >> 1);
            end
            win <= q_open ? 1'b1 : (r_close ? 1'b0 : win);
        end
    end

    // stateless prefix-XOR Gray-to-binary network, MSB down
    wire [63:0] conv;
    assign conv[63] = g[63];
    genvar i;
    generate
        for (i = 62; i >= 0; i = i - 1) begin : g2b
            assign conv[i] = conv[i+1] ^ g[i];
        end
    endgenerate

    assign calm  = (b == 64'd0);
    assign storm = (conv == 64'hFFFF_FFFF_FFFF_FFFF);

    always @(posedge clk)
        if (win) assert (!((b == 64'd0) && (conv == 64'hFFFF_FFFF_FFFF_FFFF)));
endmodule

module smbus_pec_mon (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire scl_low,
    input wire wvalid,
    input wire [127:0] wdata
);
    localparam [5:0] TMAX = 6'd50;

    reg [5:0]   low_cnt      = 6'd0;
    reg         timeout_flag = 1'b0;
    reg         before_to    = 1'b1;
    reg [127:0] wbuf         = 128'd0;
    reg         pend         = 1'b0;
    reg         pend_cnt     = 1'b0;
    reg [7:0]   pec_acc      = 8'h00;
    reg [6:0]   wcnt         = 7'd0;
    reg [7:0]   pec_snap     = 8'h00;
    reg         pv           = 1'b0;

    function [7:0] crc8_128;
        input [7:0] c;
        input [127:0] d;
        integer i;
        reg [7:0] r;
        reg fb;
        begin
            r = c;
            for (i = 127; i >= 0; i = i - 1) begin
                fb = r[7] ^ d[i];
                r = {r[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
            end
            crc8_128 = r;
        end
    endfunction

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (!rst_n) begin
            low_cnt      <= 6'd0;
            timeout_flag <= 1'b0;
            before_to    <= 1'b1;
            wbuf         <= 128'd0;
            pend         <= 1'b0;
            pend_cnt     <= 1'b0;
            pec_acc      <= 8'h00;
            wcnt         <= 7'd0;
            pec_snap     <= 8'h00;
        end else if (en) begin
            if (!scl_low)
                low_cnt <= 6'd0;
            else if (low_cnt < TMAX)
                low_cnt <= low_cnt + 6'd1;

            if (low_cnt == TMAX - 6'd1 && scl_low) begin
                timeout_flag <= 1'b1;
                before_to    <= 1'b0;
            end

            if (wvalid)
                wbuf <= wdata;

            if (wvalid)
                pend <= 1'b1;
            else if (pend)
                pend <= 1'b0;

            if (wvalid)
                pend_cnt <= 1'b1;
            else if (pend_cnt)
                pend_cnt <= 1'b0;

            if (pend)
                pec_acc <= crc8_128(pec_acc, wbuf);

            if (pend_cnt) begin
                wcnt     <= wcnt + 7'd1;
                pec_snap <= crc8_128(pec_acc, wbuf);
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(rst_n) && before_to && $past(before_to) && $stable(wcnt))
            assert ($stable(pec_acc));
endmodule

module rst_seq24 (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_cfg_we,
    input  wire [127:0] i_cfg_order,
    input  wire [127:0] i_cfg_delay,
    input  wire         i_start,
    output wire [23:0]  o_dom_rst,
    output wire         o_busy
);
    localparam [4:0] LAST   = 5'd23;
    localparam [9:0] BUDGET = 10'd768;

    // programmed release order (24 x 5-bit domain ids) and per-step delays (24 x 5-bit)
    reg [127:0] cfg_order = 128'd0;
    reg [127:0] cfg_delay = 128'd0;
    reg [4:0]   step_idx  = 5'd0;
    reg [4:0]   dly_cnt   = 5'd0;
    reg [23:0]  dom_rst   = 24'hFFFFFF;
    reg         busy      = 1'b0;
    reg [9:0]   budget    = 10'd0;

    wire [4:0] cur_dom = cfg_order[step_idx*5 +: 5];
    wire [4:0] nxt_dly = cfg_delay[(step_idx + 5'd1)*5 +: 5];

    always @(posedge clk) begin
        if (i_ce) begin
            if (!busy) begin
                if (i_cfg_we) begin
                    cfg_order <= i_cfg_order;
                    cfg_delay <= i_cfg_delay;
                end else if (i_start) begin
                    busy     <= 1'b1;
                    step_idx <= 5'd0;
                    dly_cnt  <= cfg_delay[4:0];
                    budget   <= BUDGET;
                    dom_rst  <= 24'hFFFFFF;
                end
            end else begin
                budget <= budget - 10'd1;
                if (dly_cnt != 5'd0) begin
                    dly_cnt <= dly_cnt - 5'd1;
                end else begin
                    if (cur_dom < 5'd24)
                        dom_rst[cur_dom] <= 1'b0;
                    if (step_idx == LAST) begin
                        busy     <= 1'b0;
                        step_idx <= 5'd0;
                    end else begin
                        step_idx <= step_idx + 5'd1;
                        dly_cnt  <= nxt_dly;
                    end
                end
            end
        end
    end

    assign o_dom_rst = dom_rst;
    assign o_busy    = busy;

    // after start accepted until sequence done: watchdog countdown never expires
    always @(*)
        assert (!busy || budget != 10'd0);
endmodule

module tc_trace_cache (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire [1:0]   op,
    input  wire [3:0]   idx,
    input  wire [31:0]  fill_start,
    input  wire [3:0]   fill_flags,
    input  wire [127:0] fill_instr,
    input  wire [31:0]  fill_next,
    input  wire         trace_begin,
    input  wire         trace_end,
    input  wire [31:0]  fetch_pc,
    output reg          hit,
    output reg  [3:0]   hit_idx,
    output reg  [3:0]   hit_flags,
    output reg  [127:0] hit_instr,
    output reg  [31:0]  hit_next
);
    reg [15:0] valid = 16'h0000;
    reg [31:0] occ   = 32'd0;
    reg        win   = 1'b0;

    reg [31:0] start_addr [0:15];
    reg [3:0]  br_flags   [0:15];
    reg [31:0] slot       [0:63];
    reg [31:0] next_fa    [0:15];

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) begin
            start_addr[i] = 32'd0;
            br_flags[i]   = 4'd0;
            next_fa[i]    = 32'd0;
        end
        for (i = 0; i < 64; i = i + 1)
            slot[i] = 32'd0;
    end

    // control state: valid, occupancy, window
    always @(posedge clk) begin
        if (!rst_n) begin
            valid <= 16'h0000;
            occ   <= 32'd0;
            win   <= 1'b0;
        end else if (en) begin
            case (op)
                2'd1: begin
                    valid[idx] <= 1'b1;
                    if (!valid[idx]) occ <= occ + 32'd1;
                end
                2'd2: begin
                    valid[idx] <= 1'b0;
                    if (valid[idx]) occ <= occ - 32'd1;
                end
                2'd3: begin
                    valid <= 16'h0000;
                    occ   <= 32'd0;
                end
                default: ;
            endcase
            if (trace_begin)
                win <= 1'b1;
            else if (trace_end || op == 2'd3)
                win <= 1'b0;
        end
    end

    // data storage
    always @(posedge clk) begin
        if (rst_n && en && op == 2'd1) begin
            start_addr[idx]        <= fill_start;
            br_flags[idx]          <= fill_flags;
            next_fa[idx]           <= fill_next;
            slot[{idx, 2'd0}]      <= fill_instr[31:0];
            slot[{idx, 2'd1}]      <= fill_instr[63:32];
            slot[{idx, 2'd2}]      <= fill_instr[95:64];
            slot[{idx, 2'd3}]      <= fill_instr[127:96];
        end
    end

    // combinational lookup
    integer j;
    always @(*) begin
        hit     = 1'b0;
        hit_idx = 4'd0;
        for (j = 15; j >= 0; j = j - 1) begin
            if (valid[j] && start_addr[j] == fetch_pc) begin
                hit     = 1'b1;
                hit_idx = j[3:0];
            end
        end
        hit_flags = br_flags[hit_idx];
        hit_next  = next_fa[hit_idx];
        hit_instr = {slot[{hit_idx, 2'd3}], slot[{hit_idx, 2'd2}],
                     slot[{hit_idx, 2'd1}], slot[{hit_idx, 2'd0}]};
    end

    // properties
    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $stable(valid))
            assert ($stable(occ));

    always @(posedge clk)
        if (win)
            assert (occ <= 32'd16);
endmodule

module block_parity_tally (
    input  wire        clk,
    input  wire        ce,
    input  wire        start,
    input  wire        stop,
    input  wire [15:0] din,
    output reg         par_q,
    output reg  [15:0] word_cnt,
    output reg  [15:0] odd_cnt,
    output reg         win
);
    // XOR parity tree: 16 -> 8 -> 4 -> 2 -> 1
    wire [7:0] l1;
    wire [3:0] l2;
    wire [1:0] l3;
    wire       par;
    assign l1[0] = din[0]  ^ din[1];
    assign l1[1] = din[2]  ^ din[3];
    assign l1[2] = din[4]  ^ din[5];
    assign l1[3] = din[6]  ^ din[7];
    assign l1[4] = din[8]  ^ din[9];
    assign l1[5] = din[10] ^ din[11];
    assign l1[6] = din[12] ^ din[13];
    assign l1[7] = din[14] ^ din[15];
    assign l2[0] = l1[0] ^ l1[1];
    assign l2[1] = l1[2] ^ l1[3];
    assign l2[2] = l1[4] ^ l1[5];
    assign l2[3] = l1[6] ^ l1[7];
    assign l3[0] = l2[0] ^ l2[1];
    assign l3[1] = l2[2] ^ l2[3];
    assign par   = l3[0] ^ l3[1];

    // 8-entry block buffer with per-word parity
    reg [15:0] mem  [0:7];
    reg        mpar [0:7];
    integer i;
    initial begin
        par_q    = 1'b0;
        word_cnt = 16'd0;
        odd_cnt  = 16'd0;
        win      = 1'b0;
        for (i = 0; i < 8; i = i + 1) begin
            mem[i]  = 16'd0;
            mpar[i] = 1'b0;
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            par_q <= par;  // optional output register of the tree
            if (start) begin
                win      <= 1'b1;
                word_cnt <= 16'd0;
                odd_cnt  <= 16'd0;
            end else if (win) begin
                if (stop) begin
                    win <= 1'b0;
                end else if (word_cnt < 16'd8) begin
                    mem[word_cnt[2:0]]  <= din;
                    mpar[word_cnt[2:0]] <= par;
                    word_cnt <= word_cnt + 16'd1;
                    if (par) odd_cnt <= odd_cnt + 16'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // after start until stop: at most 8 odd-parity words are tallied
    always @(posedge clk)
        if (pv && $past(win))
            assert ($past(odd_cnt) <= 16'd8);
endmodule

module tpu_dct_xpose (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [15:0] sample_in,
    output wire [15:0] acc_out
);
    reg phase = 1'b0;
    reg [15:0] wr_cnt = 16'd0;
    reg [15:0] rd_cnt = 16'd0;
    reg [15:0] wr_seen = 16'd0;
    reg [15:0] acc = 16'd0;
    reg [15:0] coef_idx = 16'd0;
    reg [15:0] mem [0:23];
    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) mem[i] = 16'd0;
    end

    assign acc_out = acc;

    function [15:0] cosv;
        input [2:0] idx;
        begin
            case (idx)
                3'd0: cosv = 16'd23170;
                3'd1: cosv = 16'd32138;
                3'd2: cosv = 16'd30274;
                3'd3: cosv = 16'd27246;
                3'd4: cosv = 16'd23170;
                3'd5: cosv = 16'd18205;
                3'd6: cosv = 16'd12540;
                default: cosv = 16'd6393;
            endcase
        end
    endfunction

    wire [31:0] row_prod = sample_in * cosv(coef_idx[2:0]);
    wire [15:0] rd_word = (rd_cnt < 16'd24) ? mem[rd_cnt[4:0]] : 16'd0;
    wire [31:0] col_prod = rd_word * cosv(coef_idx[2:0]);

    always @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            wr_cnt <= 16'd0;
            rd_cnt <= 16'd0;
            wr_seen <= 16'd0;
            acc <= 16'd0;
            coef_idx <= 16'd0;
        end else if (en) begin
            if (!phase) begin
                if (wr_cnt == 16'd24) begin
                    phase <= 1'b1;
                    rd_cnt <= 16'd0;
                end else begin
                    if (wr_cnt < 16'd24) mem[wr_cnt[4:0]] <= row_prod[15:0];
                    wr_cnt <= wr_cnt + 16'd1;
                    wr_seen <= wr_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end
            end else begin
                if (rd_cnt < 16'd24) begin
                    acc <= acc + col_prod[15:0];
                    rd_cnt <= rd_cnt + 16'd1;
                    coef_idx <= coef_idx + 16'd1;
                end else begin
                    phase <= 1'b0;
                    wr_cnt <= 16'd0;
                    wr_seen <= 16'd0;
                    rd_cnt <= 16'd0;
                    acc <= 16'd0;
                end
            end
        end
    end

    assert property (!phase || (rd_cnt <= wr_seen));
endmodule

module axis_luma_compressor (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        s_tvalid,
    input  wire        s_tuser,
    input  wire        s_tlast,
    input  wire [63:0] s_luma,
    input  wire [63:0] thr,
    input  wire [5:0]  ratio_sh,
    input  wire        eof,
    output wire        s_tready,
    output wire        m_tvalid,
    output wire        m_tuser,
    output wire        m_tlast,
    output wire [63:0] m_luma,
    output wire [63:0] o_gain,
    output wire [63:0] o_hist0,
    output wire        o_win
);
    localparam [63:0] UNITY = 64'h0000_0001_0000_0000;
    localparam [63:0] SLEW_LEN = 64'd8;

    reg [63:0] env;
    reg [63:0] gain;
    reg [63:0] tgt;
    reg        pend;
    reg [63:0] cd;
    reg [63:0] step;
    reg [63:0] hist [0:7];
    reg        win;

    integer i;
    initial begin
        env  = 64'd0;
        gain = UNITY;
        tgt  = UNITY;
        pend = 1'b0;
        cd   = 64'd0;
        step = 64'd0;
        win  = 1'b0;
        for (i = 0; i < 8; i = i + 1) hist[i] = UNITY;
    end

    assign s_tready = en;
    wire acc = en && s_tvalid;

    wire [63:0] reduction = (env > thr) ? ((env - thr) >> ratio_sh) : 64'd0;
    wire [63:0] new_tgt   = (reduction >= gain) ? 64'd0 : (gain - reduction);
    wire [63:0] gain_next = (tgt < gain) ? (gain - ((gain - tgt) >> 3))
                                         : (gain + ((tgt - gain) >> 3));
    wire [63:0] env_next  = (s_luma > env) ? (env + ((s_luma - env) >> 2))
                                           : (env - ((env - s_luma) >> 5));

    always @(posedge clk) begin
        if (rst) begin
            env  <= 64'd0;
            gain <= UNITY;
            tgt  <= UNITY;
            pend <= 1'b0;
            cd   <= 64'd0;
            step <= 64'd0;
            win  <= 1'b0;
            for (i = 0; i < 8; i = i + 1) hist[i] <= UNITY;
        end else if (en) begin
            if (acc)
                env <= env_next;
            if (!pend) begin
                if (acc && (env > thr)) begin
                    tgt  <= new_tgt;
                    pend <= 1'b1;
                    cd   <= SLEW_LEN;
                    step <= 64'd0;
                end
            end else begin
                gain <= gain_next;
                hist[step[2:0]] <= gain;
                cd   <= cd - 64'd1;
                step <= step + 64'd1;
                if (step == 64'd7)
                    pend <= 1'b0;
            end
            if (acc && s_tuser)
                win <= 1'b1;
            else if (eof)
                win <= 1'b0;
        end
    end

    wire [127:0] prod = s_luma * gain;
    assign m_luma   = prod[95:32];
    assign m_tvalid = s_tvalid;
    assign m_tuser  = s_tuser;
    assign m_tlast  = s_tlast;
    assign o_gain   = gain;
    assign o_hist0  = hist[0];
    assign o_win    = win;

    always @(*) assert (!(win && pend) || cd != 64'd0);
endmodule

module aes_round_seq64 (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire arm,
    input wire start,
    input wire ack,
    input wire [63:0] pt,
    input wire [63:0] key_in,
    output wire done,
    output wire [63:0] ct
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, RUN = 2'd2, DONE = 2'd3;
    localparam [63:0] NR = 64'd10;

    reg [1:0] phase;
    reg arm_seen, start_seen;
    reg [63:0] rnd;
    reg [63:0] st;
    reg [63:0] rk;
    initial begin
        phase = IDLE; arm_seen = 1'b0; start_seen = 1'b0;
        rnd = 64'd0; st = 64'd0; rk = 64'd0;
    end

    function [3:0] sbox4(input [3:0] x);
        case (x)
            4'h0: sbox4 = 4'hC; 4'h1: sbox4 = 4'h5; 4'h2: sbox4 = 4'h6; 4'h3: sbox4 = 4'hB;
            4'h4: sbox4 = 4'h9; 4'h5: sbox4 = 4'h0; 4'h6: sbox4 = 4'hA; 4'h7: sbox4 = 4'hD;
            4'h8: sbox4 = 4'h3; 4'h9: sbox4 = 4'hE; 4'hA: sbox4 = 4'hF; 4'hB: sbox4 = 4'h8;
            4'hC: sbox4 = 4'h4; 4'hD: sbox4 = 4'h7; 4'hE: sbox4 = 4'h1; default: sbox4 = 4'h2;
        endcase
    endfunction

    function [63:0] sub64(input [63:0] x);
        integer i;
        begin
            sub64 = 64'd0;
            for (i = 0; i < 16; i = i + 1)
                sub64[i*4 +: 4] = sbox4(x[i*4 +: 4]);
        end
    endfunction

    function [63:0] shift64(input [63:0] x);
        integer r, c;
        begin
            shift64 = 64'd0;
            for (c = 0; c < 4; c = c + 1)
                for (r = 0; r < 4; r = r + 1)
                    shift64[(4*c+r)*4 +: 4] = x[(4*((c+r)%4)+r)*4 +: 4];
        end
    endfunction

    function [63:0] mix64(input [63:0] x);
        integer c;
        reg [15:0] col;
        begin
            mix64 = 64'd0;
            for (c = 0; c < 4; c = c + 1) begin
                col = x[c*16 +: 16];
                mix64[c*16 +: 16] = col ^ {col[11:0], col[15:12]} ^ {col[7:0], col[15:8]};
            end
        end
    endfunction

    wire last_round = (rnd == NR - 64'd1);
    wire [63:0] after_shift = shift64(sub64(st));
    wire [63:0] round_out = (last_round ? after_shift : mix64(after_shift)) ^ rk;

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE; arm_seen <= 1'b0; start_seen <= 1'b0;
            rnd <= 64'd0; st <= 64'd0; rk <= 64'd0;
        end else if (ce) begin
            case (phase)
                IDLE: if (arm) begin
                    phase <= ARMED; arm_seen <= 1'b1; start_seen <= 1'b0;
                    st <= pt ^ key_in; rk <= key_in;
                end
                ARMED: if (start) begin
                    phase <= RUN; start_seen <= 1'b1; rnd <= 64'd0;
                end
                RUN: begin
                    st <= round_out;
                    rk <= {rk[62:0], rk[63]} ^ rnd;
                    rnd <= rnd + 64'd1;
                    if (last_round) phase <= DONE;
                end
                default: if (ack) begin
                    phase <= IDLE; arm_seen <= 1'b0; start_seen <= 1'b0;
                end
            endcase
        end
    end

    assign done = (phase == DONE);
    assign ct = st;

    always @(posedge clk)
        if (phase == DONE)
            assert (arm_seen && start_seen);
endmodule

module fp_align_shifter (
    input  wire        clk,
    input  wire        rst,
    input  wire        load,
    input  wire        i_ce,
    input  wire [63:0] a_exp,
    input  wire [63:0] a_sig,
    input  wire [63:0] b_exp,
    input  wire [63:0] b_sig,
    output reg  [63:0] sig,
    output reg  [63:0] exp_out,
    output reg  [63:0] cnt,
    output reg         g,
    output reg         r,
    output reg         s,
    output wire        busy
);
    // shadow: some nonzero bit has been shifted out of the significand
    reg lost  = 1'b0;
    // sticky scope register: set at the first accepted alignment request
    reg armed = 1'b0;

    initial sig     = 64'd0;
    initial exp_out = 64'd0;
    initial cnt     = 64'd0;
    initial g       = 1'b0;
    initial r       = 1'b0;
    initial s       = 1'b0;

    assign busy = (cnt != 64'd0);

    always @(posedge clk) begin
        if (rst) begin
            sig     <= 64'd0;
            exp_out <= 64'd0;
            cnt     <= 64'd0;
            g       <= 1'b0;
            r       <= 1'b0;
            s       <= 1'b0;
            lost    <= 1'b0;
        end else if (load) begin
            armed <= 1'b1;
            if (a_exp >= b_exp) begin
                exp_out <= a_exp;
                sig     <= b_sig;
                cnt     <= a_exp - b_exp;
            end else begin
                exp_out <= b_exp;
                sig     <= a_sig;
                cnt     <= b_exp - a_exp;
            end
            g    <= 1'b0;
            r    <= 1'b0;
            s    <= 1'b0;
            lost <= 1'b0;
        end else if (i_ce && cnt != 64'd0) begin
            sig  <= {1'b0, sig[63:1]};
            g    <= sig[0];
            r    <= g;
            s    <= s | r;
            lost <= lost | sig[0];
            cnt  <= cnt - 64'd1;
        end
    end

    // precedence, after first load: sticky set now => a nonzero bit was shifted out earlier
    always @(*) assert (!armed || !s || lost);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
    output reg         fault
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
            fault  <= miss_q;
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
endmodule

module metro_led_scan (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        wr_en,
    input  wire [5:0]  wr_addr,
    input  wire [63:0] wr_data,
    output wire [63:0] row_drv,
    output wire [63:0] col_drv
);
    reg [63:0] frame_mem_r [0:63];
    reg [63:0] row_idx_r = 64'd0;
    reg [63:0] row_sel_r = 64'h0000_0000_0000_0001;
    reg [63:0] col_r     = 64'd0;
    reg        armed_r   = 1'b0;
    reg        pv_r      = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 64; i = i + 1)
            frame_mem_r[i] = 64'd0;
    end

    assign row_drv = row_sel_r;
    assign col_drv = col_r;

    always_ff @(posedge clk) begin
        if (wr_en)
            frame_mem_r[wr_addr] <= wr_data;
    end

    always_ff @(posedge clk) begin
        if (rst)
            row_idx_r <= 64'd0;
        else if (en)
            row_idx_r <= (row_idx_r == 64'd63) ? 64'd0 : (row_idx_r + 64'd1);
    end

    always_ff @(posedge clk) begin
        if (rst)
            row_sel_r <= 64'h0000_0000_0000_0001;
        else if (en)
            row_sel_r <= {row_sel_r[62:0], row_sel_r[63]};
    end

    always_ff @(posedge clk) begin
        if (rst)
            col_r <= 64'd0;
        else if (en)
            col_r <= frame_mem_r[row_idx_r[5:0]];
    end

    always_ff @(posedge clk) begin
        if (rst)
            armed_r <= 1'b0;
        else if (en && (row_idx_r == 64'd63))
            armed_r <= 1'b1;
    end

    always_ff @(posedge clk) begin
        pv_r <= 1'b1;
    end

    always @(posedge clk) begin
        if (pv_r && $past(armed_r))
            assert (!($past(row_sel_r[0]) && $past(row_sel_r[63])));
    end
endmodule

module dadda4x4 (
    input  wire [3:0] a,
    input  wire [3:0] b,
    output wire [7:0] p
);
    // partial products pij = a[i] & b[j], weight i+j
    wire p00 = a[0] & b[0];
    wire p01 = a[0] & b[1];
    wire p02 = a[0] & b[2];
    wire p03 = a[0] & b[3];
    wire p10 = a[1] & b[0];
    wire p11 = a[1] & b[1];
    wire p12 = a[1] & b[2];
    wire p13 = a[1] & b[3];
    wire p20 = a[2] & b[0];
    wire p21 = a[2] & b[1];
    wire p22 = a[2] & b[2];
    wire p23 = a[2] & b[3];
    wire p30 = a[3] & b[0];
    wire p31 = a[3] & b[1];
    wire p32 = a[3] & b[2];
    wire p33 = a[3] & b[3];
    // Dadda stage 1: reduce max column height 4 -> 3 (two half adders)
    wire s1 = p03 ^ p12;
    wire c1 = p03 & p12;
    wire s2 = p13 ^ p22;
    wire c2 = p13 & p22;
    // Dadda stage 2: reduce height 3 -> 2 (one half adder, three full adders)
    wire s3 = p02 ^ p11;
    wire c3 = p02 & p11;
    wire s4 = s1 ^ p21 ^ p30;
    wire c4 = (s1 & p21) | (s1 & p30) | (p21 & p30);
    wire s5 = s2 ^ p31 ^ c1;
    wire c5 = (s2 & p31) | (s2 & c1) | (p31 & c1);
    wire s6 = p23 ^ p32 ^ c2;
    wire c6 = (p23 & p32) | (p23 & c2) | (p32 & c2);
    // final carry-propagate adder over columns 1..6
    wire [5:0] row_x = {p33, s6, s5, s4, s3, p01};
    wire [5:0] row_y = {c6, c5, c4, c3, p20, p10};
    wire [6:0] cpa = {1'b0, row_x} + {1'b0, row_y};
    assign p = {cpa, p00};
endmodule

module dadda_simd_mul (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_load,
    input  wire         i_flush,
    input  wire [127:0] i_data,
    output wire [127:0] o_prod
);
    reg [127:0] op_r;
    reg [127:0] prod_r;
    reg         v1;
    reg [1:0]   op_gen;
    reg [1:0]   p_gen;
    reg         armed;
    reg         pv;
    initial op_r   = 128'h0;
    initial prod_r = 128'h0;
    initial v1     = 1'b0;
    initial op_gen = 2'd0;
    initial p_gen  = 2'd0;
    initial armed  = 1'b0;
    initial pv     = 1'b0;

    // 16 lanes, each lane packs {a[3:0], b[3:0]} in 8 bits of the operand word
    wire [127:0] tree_p;
    genvar k;
    generate
        for (k = 0; k < 16; k = k + 1) begin : lane
            dadda4x4 u_mul (
                .a(op_r[8*k+7:8*k+4]),
                .b(op_r[8*k+3:8*k]),
                .p(tree_p[8*k+7:8*k])
            );
        end
    endgenerate

    always @(posedge clk) begin
        if (i_ce) begin
            if (v1) begin
                prod_r <= tree_p;
                p_gen  <= op_gen;
            end
            if (i_load) begin
                op_r   <= i_data;
                op_gen <= op_gen + 2'd1;
                v1     <= 1'b1;
            end else if (v1) begin
                v1 <= 1'b0;
            end
            if (i_flush)
                armed <= 1'b0;
            else if (i_load)
                armed <= 1'b1;
        end
    end

    assign o_prod = prod_r;

    always @(posedge clk) pv <= 1'b1;

    // after first load until flush: never (product tag unchanged AND product changed)
    always @(posedge clk)
        if (pv && armed && $stable(p_gen))
            assert ($stable(prod_r));
endmodule

module ctr_drbg_engine (
    input wire clk,
    input wire rst,
    input wire ce,
    input wire [1:0] cmd,
    input wire [31:0] entropy,
    output reg busy,
    output reg [31:0] out_data,
    output reg [31:0] reseed_ctr
);
    // cmd: 2'b01 instantiate, 2'b10 reseed, 2'b11 generate
    reg [31:0] key = 32'd0;
    reg [31:0] v = 32'd0;
    reg [31:0] timer = 32'd0;
    reg [31:0] rnd = 32'd0;
    reg [1:0] op = 2'b00;
    initial busy = 1'b0;
    initial out_data = 32'd0;
    initial reseed_ctr = 32'd0;

    always @(posedge clk) begin
        if (rst) begin
            key <= 32'd0;
            v <= 32'd0;
            timer <= 32'd0;
            rnd <= 32'd0;
            op <= 2'b00;
            busy <= 1'b0;
            out_data <= 32'd0;
            reseed_ctr <= 32'd0;
        end else if (ce) begin
            if (!busy) begin
                if (cmd != 2'b00) begin
                    busy <= 1'b1;
                    op <= cmd;
                    rnd <= 32'd0;
                    timer <= 32'd8;
                end
            end else begin
                v <= v + 32'd1;
                key <= {key[26:0], key[31:27]} ^ (v + 32'h9E3779B9) ^ ((op != 2'b11) ? entropy : 32'd0);
                rnd <= rnd + 32'd1;
                timer <= timer - 32'd1;
                if (rnd == 32'd5) begin
                    busy <= 1'b0;
                    timer <= 32'd0;
                    rnd <= 32'd0;
                    case (op)
                        2'b01: reseed_ctr <= 32'd1;
                        2'b10: reseed_ctr <= 32'd1;
                        2'b11: begin
                            reseed_ctr <= reseed_ctr + 32'd1;
                            out_data <= v ^ key;
                        end
                        default: reseed_ctr <= reseed_ctr;
                    endcase
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $past(busy)) assert ($past(timer) != 32'd0);
endmodule

module irq_pulse_stretch (
    input  wire clk,
    input  wire ce,
    input  wire irq_pulse,
    input  wire win_open,
    input  wire win_close,
    output reg  irq_out
);
    localparam [63:0] LEN = 64'd12;
localparam [63:0] TAIL = 64'd4;

    reg [63:0] remain = 64'd0;
    reg [63:0] held   = 64'd0;
reg [63:0] tail   = 64'd0;
    reg        win    = 1'b0;
    initial irq_out = 1'b0;

    always @(posedge clk) begin
        if (ce) begin
            if (win_close)     win <= 1'b0;
            else if (win_open) win <= 1'b1;

            if (!irq_out) begin
                if (irq_pulse) begin
                    irq_out <= 1'b1;
remain  <= LEN - TAIL - 64'd1;
tail    <= TAIL;
                    held    <= 64'd1;
                end
end else if (remain == 64'd0 && tail != 64'd0) begin
remain <= tail - 64'd1;
tail   <= 64'd0;
held   <= held + 64'd1;
end else if (remain == 64'd0) begin
                irq_out <= 1'b0;
            end else begin
                remain <= remain - 64'd1;
                held   <= held + 64'd1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $fell(irq_out))
            assert (held <= LEN);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;
reg [127:0] bq_d0, bq_d1, bq_d2, bq_d3;
reg [127:0] bq_head;
reg [3:0] bq_tag;
reg [1:0] bq_wp, bq_rp;
reg [2:0] bq_cnt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;
initial bq_d0 = 128'h0;
initial bq_d1 = 128'h0;
initial bq_d2 = 128'h0;
initial bq_d3 = 128'h0;
initial bq_tag = 4'h0;
initial bq_wp = 2'd0;
initial bq_rp = 2'd0;
initial bq_cnt = 3'd0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
wire bq_empty = (bq_cnt == 3'd0);
wire bq_full = (bq_cnt >= 3'd4);
wire bq_pop = en && !clr_cmd && !bq_empty && (fsm != S_DONE);
wire bq_push = en && !clr_cmd && beat_valid && (!bq_full || bq_pop);
wire push_tag = (fsm == S_ARMED) && match0;
wire head_start = bq_pop && bq_tag[bq_rp];
wire match1 = bq_pop && (((bq_head ^ wval1) & wmask1) == 128'h0);

always @(*) begin
case (bq_rp)
2'd0: bq_head = bq_d0;
2'd1: bq_head = bq_d1;
2'd2: bq_head = bq_d2;
default: bq_head = bq_d3;
endcase
end

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
S_ARMED: if (head_start) fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
bq_d0 <= 128'h0;
bq_d1 <= 128'h0;
bq_d2 <= 128'h0;
bq_d3 <= 128'h0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
if (bq_push && push_tag) started_seen <= 1'b1;
if (bq_pop) begin
bq_tag[bq_rp] <= 1'b0;
bq_rp <= bq_rp + 2'd1;
end
if (bq_push) begin
case (bq_wp)
2'd0: bq_d0 <= beat_data;
2'd1: bq_d1 <= beat_data;
2'd2: bq_d2 <= beat_data;
default: bq_d3 <= beat_data;
endcase
bq_tag[bq_wp] <= push_tag;
bq_wp <= bq_wp + 2'd1;
end
case ({bq_push, bq_pop})
2'b10: bq_cnt <= bq_cnt + 3'd1;
2'b01: bq_cnt <= bq_cnt - 3'd1;
default: bq_cnt <= bq_cnt;
endcase
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);

   always @(posedge clk)
       if (win && en && cnt != 4'd0)
           assert (out_q[63:48] == {12'h0, cnt - 4'd1});
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  dbg_stat
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [7:0]  n_start;
reg [7:0]  n_stop;
reg [15:0] n_words;
reg [15:0] en_cyc;
reg [7:0]  win_len;
reg [7:0]  max_win;
reg        wrap_seen;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
n_start   = 8'd0;
n_stop    = 8'd0;
n_words   = 16'd0;
en_cyc    = 16'd0;
win_len   = 8'd0;
max_win   = 8'd0;
wrap_seen = 1'b0;
dbg_stat  = 32'h0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
n_start   <= 8'd0;
n_stop    <= 8'd0;
n_words   <= 16'd0;
en_cyc    <= 16'd0;
win_len   <= 8'd0;
max_win   <= 8'd0;
wrap_seen <= 1'b0;
dbg_stat  <= 32'h0;
        end else if (en) begin
en_cyc <= en_cyc + 16'd1;
if (start && n_start != 8'hFF) n_start <= n_start + 8'd1;
if (stop && !start && n_stop != 8'hFF) n_stop <= n_stop + 8'd1;
if (!start && !stop && win) begin
    n_words <= n_words + 16'd1;
    if (rd_ptr == 3'd7) wrap_seen <= 1'b1;
    if (win_len != 8'hFF) win_len <= win_len + 8'd1;
end
if (start) win_len <= 8'd0;
if (win_len > max_win) max_win <= win_len;
dbg_stat <= {n_start[3:0], n_stop[3:0], max_win, n_words[11:0], wrap_seen, en_cyc[2:0]};
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
output wire [15:0]  qual_cnt_o,
output reg  [31:0]  dbg_o,
output wire         wdt_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

   localparam [19:0] WDT_LIMIT = 20'd65535;

   reg [31:0] cyc_cnt;
   reg [31:0] beat_cnt;
   reg [15:0] wr0_cnt;
   reg [15:0] wr1_cnt;
   reg [15:0] arm_cnt;
   reg [15:0] clr_cnt;
   reg [15:0] hit_cnt;
   reg [15:0] sr_cnt;
   reg        done_d;
   reg        sr_d;
   reg [1:0]  fsm_d;
   reg [19:0] wdt_cnt;
   reg        wdt_to;
   reg [3:0]  err_bits;
   reg [2:0]  err_code;
   reg [31:0] err_ts;
   reg        err_valid;

   initial cyc_cnt   = 32'd0;
   initial beat_cnt  = 32'd0;
   initial wr0_cnt   = 16'd0;
   initial wr1_cnt   = 16'd0;
   initial arm_cnt   = 16'd0;
   initial clr_cnt   = 16'd0;
   initial hit_cnt   = 16'd0;
   initial sr_cnt    = 16'd0;
   initial done_d    = 1'b0;
   initial sr_d      = 1'b0;
   initial fsm_d     = 2'd0;
   initial wdt_cnt   = 20'd0;
   initial wdt_to    = 1'b0;
   initial err_bits  = 4'd0;
   initial err_code  = 3'd0;
   initial err_ts    = 32'd0;
   initial err_valid = 1'b0;
   initial dbg_o     = 32'd0;

   wire       dbg_fsm_busy  = (fsm_a == 2'd1) || (fsm_a == 2'd2);
   wire       dbg_fsm_move  = (fsm_a != fsm_d);
   wire       dbg_clr_a     = en_a && clr_cmd;
   wire       err_arm_busy  = en_a && arm_cmd && !clr_cmd && (fsm_a != 2'd0);
   wire       err_wr_busy   = en_a && wr_en && dbg_fsm_busy;
   wire       err_wdt       = dbg_fsm_busy && (wdt_cnt == WDT_LIMIT);
   wire       err_bod       = bod_clr && !en_b;
   wire [3:0] err_now       = {err_bod, err_wdt, err_wr_busy, err_arm_busy};
   wire [2:0] err_enc       = err_now[0] ? 3'd1 :
                              err_now[1] ? 3'd2 :
                              err_now[2] ? 3'd3 :
                              err_now[3] ? 3'd4 : 3'd0;
   wire       done_rise     = done_a && !done_d;
   wire       sr_rise       = slot_reset_b && !sr_d;

   reg [31:0] dbg_mux;
   always @(*) begin
       case ({wr_sel, sel_in})
           3'd0: dbg_mux = cyc_cnt;
           3'd1: dbg_mux = beat_cnt;
           3'd2: dbg_mux = {wr1_cnt, wr0_cnt};
           3'd3: dbg_mux = {arm_cnt, clr_cnt};
           3'd4: dbg_mux = {hit_cnt, sr_cnt};
           3'd5: dbg_mux = {err_valid, 3'd0, err_code, 1'b0, err_bits, wdt_to, wdt_cnt[18:0]};
           3'd6: dbg_mux = err_ts;
           default: dbg_mux = {thr_b, streak_b};
       endcase
   end

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
           cyc_cnt   <= 32'd0;
           beat_cnt  <= 32'd0;
           wr0_cnt   <= 16'd0;
           wr1_cnt   <= 16'd0;
           arm_cnt   <= 16'd0;
           clr_cnt   <= 16'd0;
           hit_cnt   <= 16'd0;
           sr_cnt    <= 16'd0;
           done_d    <= 1'b0;
           sr_d      <= 1'b0;
           fsm_d     <= 2'd0;
           wdt_cnt   <= 20'd0;
           wdt_to    <= 1'b0;
           err_bits  <= 4'd0;
           err_code  <= 3'd0;
           err_ts    <= 32'd0;
           err_valid <= 1'b0;
           dbg_o     <= 32'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
           cyc_cnt <= cyc_cnt + 32'd1;
           if (beat_valid && (beat_cnt != 32'hFFFFFFFF))
               beat_cnt <= beat_cnt + 32'd1;
           if (en_a && wr_en && !wr_sel && (wr0_cnt != 16'hFFFF))
               wr0_cnt <= wr0_cnt + 16'd1;
           if (en_a && wr_en && wr_sel && (wr1_cnt != 16'hFFFF))
               wr1_cnt <= wr1_cnt + 16'd1;
           if (en_a && arm_cmd && (arm_cnt != 16'hFFFF))
               arm_cnt <= arm_cnt + 16'd1;
           if (dbg_clr_a && (clr_cnt != 16'hFFFF))
               clr_cnt <= clr_cnt + 16'd1;
           done_d <= done_a;
           sr_d   <= slot_reset_b;
           fsm_d  <= fsm_a;
           if (done_rise && (hit_cnt != 16'hFFFF))
               hit_cnt <= hit_cnt + 16'd1;
           if (sr_rise && (sr_cnt != 16'hFFFF))
               sr_cnt <= sr_cnt + 16'd1;
           if (!dbg_fsm_busy || dbg_fsm_move || dbg_clr_a)
               wdt_cnt <= 20'd0;
           else if (wdt_cnt != WDT_LIMIT)
               wdt_cnt <= wdt_cnt + 20'd1;
           if (dbg_clr_a)
               wdt_to <= 1'b0;
           else if (err_wdt)
               wdt_to <= 1'b1;
           if (bod_clr && en_b) begin
               err_bits  <= 4'd0;
               err_code  <= 3'd0;
               err_ts    <= 32'd0;
               err_valid <= 1'b0;
           end else begin
               err_bits <= err_bits | err_now;
               if (!err_valid && (err_now != 4'd0)) begin
                   err_valid <= 1'b1;
                   err_code  <= err_enc;
                   err_ts    <= cyc_cnt;
               end
           end
           dbg_o <= dbg_mux;
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
   assign wdt_o      = wdt_to;
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;
reg [127:0] bq_d0, bq_d1, bq_d2, bq_d3;
reg [127:0] bq_head;
reg [3:0] bq_tag;
reg [1:0] bq_wp, bq_rp;
reg [2:0] bq_cnt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;
initial bq_d0 = 128'h0;
initial bq_d1 = 128'h0;
initial bq_d2 = 128'h0;
initial bq_d3 = 128'h0;
initial bq_tag = 4'h0;
initial bq_wp = 2'd0;
initial bq_rp = 2'd0;
initial bq_cnt = 3'd0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
wire bq_empty = (bq_cnt == 3'd0);
wire bq_full = (bq_cnt >= 3'd4);
wire bq_pop = en && !clr_cmd && !bq_empty && (fsm != S_DONE);
wire bq_push = en && !clr_cmd && beat_valid && (!bq_full || bq_pop);
wire push_tag = (fsm == S_ARMED) && match0;
wire head_start = bq_pop && bq_tag[bq_rp];
wire match1 = bq_pop && (((bq_head ^ wval1) & wmask1) == 128'h0);

always @(*) begin
case (bq_rp)
2'd0: bq_head = bq_d0;
2'd1: bq_head = bq_d1;
2'd2: bq_head = bq_d2;
default: bq_head = bq_d3;
endcase
end

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
S_ARMED: if (head_start) fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
bq_d0 <= 128'h0;
bq_d1 <= 128'h0;
bq_d2 <= 128'h0;
bq_d3 <= 128'h0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
if (bq_push && push_tag) started_seen <= 1'b1;
if (bq_pop) begin
bq_tag[bq_rp] <= 1'b0;
bq_rp <= bq_rp + 2'd1;
end
if (bq_push) begin
case (bq_wp)
2'd0: bq_d0 <= beat_data;
2'd1: bq_d1 <= beat_data;
2'd2: bq_d2 <= beat_data;
default: bq_d3 <= beat_data;
endcase
bq_tag[bq_wp] <= push_tag;
bq_wp <= bq_wp + 2'd1;
end
case ({bq_push, bq_pop})
2'b10: bq_cnt <= bq_cnt + 3'd1;
2'b01: bq_cnt <= bq_cnt - 3'd1;
default: bq_cnt <= bq_cnt;
endcase
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);

   always @(posedge clk)
       if (!rst) assert (!(fsm == S_ARMED && started_seen) || (bq_cnt != 3'd0));
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  dbg_stat
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [7:0]  n_start;
reg [7:0]  n_stop;
reg [15:0] n_words;
reg [15:0] en_cyc;
reg [7:0]  win_len;
reg [7:0]  max_win;
reg        wrap_seen;
reg        half_beat;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
n_start   = 8'd0;
n_stop    = 8'd0;
n_words   = 16'd0;
en_cyc    = 16'd0;
win_len   = 8'd0;
max_win   = 8'd0;
wrap_seen = 1'b0;
half_beat = 1'b0;
dbg_stat  = 32'h0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
n_start   <= 8'd0;
n_stop    <= 8'd0;
n_words   <= 16'd0;
en_cyc    <= 16'd0;
win_len   <= 8'd0;
max_win   <= 8'd0;
wrap_seen <= 1'b0;
half_beat <= 1'b0;
dbg_stat  <= 32'h0;
        end else if (en) begin
en_cyc <= en_cyc + 16'd1;
if (start && n_start != 8'hFF) n_start <= n_start + 8'd1;
if (stop && !start && n_stop != 8'hFF) n_stop <= n_stop + 8'd1;
if (!start && !stop && win) begin
    n_words <= n_words + 16'd1;
    if (rd_ptr == 3'd7) wrap_seen <= 1'b1;
    if (win_len != 8'hFF) win_len <= win_len + 8'd1;
end
if (start) win_len <= 8'd0;
if (win_len > max_win) max_win <= win_len;
dbg_stat <= {n_start[3:0], n_stop[3:0], max_win, n_words[11:0], wrap_seen, half_beat, en_cyc[1:0]};
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
half_beat <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
half_beat <= 1'b0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
if (half_beat) cnt <= cnt + 4'd2;
half_beat <= !half_beat;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o
,
    output wire armed_seen_a_o,
    output wire bo_flag_b_o,
    output wire brk_q_o,
    output wire [15:0] deb_cnt_b_o,
    output wire done_a_o,
    output wire [1:0] fsm_a_o,
    output wire q_ok_o,
    output wire [15:0] qual_cnt_obs,
    output wire started_seen_a_o,
    output wire [15:0] streak_b_o,
    output wire [15:0] thr_b_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
    assign armed_seen_a_o = armed_seen_a;
    assign bo_flag_b_o = bo_flag_b;
    assign brk_q_o = brk_q;
    assign deb_cnt_b_o = deb_cnt_b;
    assign done_a_o = done_a;
    assign fsm_a_o = fsm_a;
    assign q_ok_o = q_ok;
    assign qual_cnt_obs = qual_cnt;
    assign started_seen_a_o = started_seen_a;
    assign streak_b_o = streak_b;
    assign thr_b_o = thr_b;
endmodule

module GF8MulCore (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [7:0] a_in,
    input wire [7:0] b_in,
    input wire [7:0] poly_in,
    input wire poly_we,
    output reg done,
    output wire [7:0] result
,
    output wire [7:0] bitcnt_o,
    output wire busy_o,
    output wire [7:0] deadline_o
);
    reg [7:0] acc;
    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [7:0] poly;
    reg [7:0] bitcnt;
    reg [7:0] deadline;
    reg busy;
    reg armed;

    initial begin
        acc = 8'd0;
        a_reg = 8'd0;
        b_reg = 8'd0;
        poly = 8'd0;
        bitcnt = 8'd0;
        deadline = 8'd0;
        busy = 1'b0;
        armed = 1'b0;
        done = 1'b0;
    end

    assign result = acc;

    wire [7:0] a_shl = {a_reg[6:0], 1'b0};
    wire [7:0] xtime = a_reg[7] ? (a_shl ^ poly) : a_shl;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd0;
            a_reg <= 8'd0;
            b_reg <= 8'd0;
            poly <= 8'd0;
            bitcnt <= 8'd0;
            deadline <= 8'd0;
            busy <= 1'b0;
            armed <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            done <= 1'b0;
            if (poly_we && !busy)
                poly <= poly_in;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    armed <= 1'b1;
                    acc <= 8'd0;
                    a_reg <= a_in;
                    b_reg <= b_in;
                    bitcnt <= 8'd8;
                    deadline <= 8'd9;
                end
            end else if (bitcnt != 8'd0) begin
                if (b_reg[0])
                    acc <= acc ^ a_reg;
                a_reg <= xtime;
                b_reg <= {1'b0, b_reg[7:1]};
                bitcnt <= bitcnt - 8'd1;
                deadline <= deadline - 8'd1;
            end else begin
                busy <= 1'b0;
                deadline <= 8'd0;
                done <= 1'b1;
            end
        end
    end

    assert property (!(armed && busy) || (deadline != 8'd0));
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign deadline_o = deadline;
endmodule

module vbrk_gf8_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    input  wire         job_cap,
    input  wire         en_m,
    input  wire [7:0]   poly_in,
    input  wire         poly_we,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o,
    output wire         gf_done,
    output wire [7:0]   gf_result,
    output wire         job_pend_o,
    output wire         job_inflight_o,
    output wire [7:0]   job_wd_o,
    output wire         gf_busy_o,
    output wire [7:0]   gf_deadline_o
);
    wire        a_done;
    wire        a_slot_reset;
    wire        a_brk;
    wire [15:0] a_qual_cnt_out;
    wire        a_armed_seen;
    wire        a_bo_flag;
    wire        a_brk_q;
    wire [15:0] a_deb_cnt;
    wire        a_done_mirror;
    wire [1:0]  a_fsm;
    wire        a_q_ok;
    wire [15:0] a_qual_cnt;
    wire        a_started_seen;
    wire [15:0] a_streak;
    wire [15:0] a_thr;

    wire        m_done;
    wire [7:0]  m_result;
    wire [7:0]  m_bitcnt;
    wire        m_busy;
    wire [7:0]  m_deadline;

    reg        job_pend     = 1'b0;
    reg [7:0]  job_a        = 8'd0;
    reg [7:0]  job_b        = 8'd0;
    reg        job_inflight = 1'b0;
    reg [7:0]  job_wd       = 8'd0;

    vbrk_bod_top u_a (
        .clk(clk),
        .rst(rst),
        .en_a(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .cap_en(cap_en),
        .en_b(en_b),
        .bod_clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .done(a_done),
        .slot_reset(a_slot_reset),
        .brk_o(a_brk),
        .qual_cnt_o(a_qual_cnt_out),
        .armed_seen_a_o(a_armed_seen),
        .bo_flag_b_o(a_bo_flag),
        .brk_q_o(a_brk_q),
        .deb_cnt_b_o(a_deb_cnt),
        .done_a_o(a_done_mirror),
        .fsm_a_o(a_fsm),
        .q_ok_o(a_q_ok),
        .qual_cnt_obs(a_qual_cnt),
        .started_seen_a_o(a_started_seen),
        .streak_b_o(a_streak),
        .thr_b_o(a_thr)
    );

    GF8MulCore u_m (
        .clk(clk),
        .rst(rst),
        .en(en_m),
        .req(job_pend),
        .a_in(job_a),
        .b_in(job_b),
        .poly_in(poly_in),
        .poly_we(poly_we),
        .done(m_done),
        .result(m_result),
        .bitcnt_o(m_bitcnt),
        .busy_o(m_busy),
        .deadline_o(m_deadline)
    );

    wire job_issue = en_m && job_pend && !m_busy;

    always @(posedge clk) begin
        if (rst) begin
            job_pend     <= 1'b0;
            job_a        <= 8'd0;
            job_b        <= 8'd0;
            job_inflight <= 1'b0;
            job_wd       <= 8'd0;
        end else begin
            if (!job_pend) begin
                if (job_cap && a_brk_q) begin
                    job_pend <= 1'b1;
                    job_a    <= a_qual_cnt[7:0];
                    job_b    <= a_deb_cnt[7:0];
                end
            end else if (job_issue) begin
                job_pend <= 1'b0;
            end
            if (en_m) begin
                if (job_issue) begin
                    job_inflight <= 1'b1;
                    job_wd       <= 8'd9;
                end else if (job_inflight) begin
                    if (m_bitcnt == 8'd0) begin
                        job_inflight <= 1'b0;
                        job_wd       <= 8'd0;
                    end else begin
                        job_wd <= job_wd - 8'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (job_inflight)
            assert (job_wd != 8'd0);

    assign done           = a_done;
    assign slot_reset     = a_slot_reset;
    assign brk_o          = a_brk;
    assign qual_cnt_o     = a_qual_cnt_out;
    assign gf_done        = m_done;
    assign gf_result      = m_result;
    assign job_pend_o     = job_pend;
    assign job_inflight_o = job_inflight;
    assign job_wd_o       = job_wd;
    assign gf_busy_o      = m_busy;
    assign gf_deadline_o  = m_deadline;
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
output reg          out_v,
output reg  [31:0]  dbg_stat
,
    output wire [3:0] cnt_o,
    output wire half_beat_o,
    output wire [2:0] rd_ptr_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
reg [7:0]  n_start;
reg [7:0]  n_stop;
reg [15:0] n_words;
reg [15:0] en_cyc;
reg [7:0]  win_len;
reg [7:0]  max_win;
reg        wrap_seen;
reg        half_beat;

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
n_start   = 8'd0;
n_stop    = 8'd0;
n_words   = 16'd0;
en_cyc    = 16'd0;
win_len   = 8'd0;
max_win   = 8'd0;
wrap_seen = 1'b0;
half_beat = 1'b0;
dbg_stat  = 32'h0;
        out_q  = 128'h0;
        out_v  = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
n_start   <= 8'd0;
n_stop    <= 8'd0;
n_words   <= 16'd0;
en_cyc    <= 16'd0;
win_len   <= 8'd0;
max_win   <= 8'd0;
wrap_seen <= 1'b0;
half_beat <= 1'b0;
dbg_stat  <= 32'h0;
        end else if (en) begin
en_cyc <= en_cyc + 16'd1;
if (start && n_start != 8'hFF) n_start <= n_start + 8'd1;
if (stop && !start && n_stop != 8'hFF) n_stop <= n_stop + 8'd1;
if (!start && !stop && win) begin
    n_words <= n_words + 16'd1;
    if (rd_ptr == 3'd7) wrap_seen <= 1'b1;
    if (win_len != 8'hFF) win_len <= win_len + 8'd1;
end
if (start) win_len <= 8'd0;
if (win_len > max_win) max_win <= win_len;
dbg_stat <= {n_start[3:0], n_stop[3:0], max_win, n_words[11:0], wrap_seen, half_beat, en_cyc[1:0]};
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
half_beat <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
            end else if (win) begin
                out_q <= rom_word;
                out_v <= 1'b1;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
half_beat <= 1'b0;
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
if (half_beat) cnt <= cnt + 4'd2;
half_beat <= !half_beat;
                end
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
    assign cnt_o = cnt;
    assign half_beat_o = half_beat;
    assign rd_ptr_o = rd_ptr;
endmodule

module prbs_win_checker (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_bit,
    input  wire        i_arm,
    input  wire        i_disarm,
    output wire        o_sync,
    output wire [63:0] o_errs
,
    output wire [63:0] err_cnt_o,
    output wire [63:0] err_snap_o,
    output wire win_o,
    output wire [63:0] win_errs_o
);
    localparam [63:0] SYNC_LEN = 64'd8;
    localparam [63:0] LOSS_LEN = 64'd4;
    localparam [63:0] MAXV     = 64'hFFFFFFFFFFFFFFFF;

    reg [63:0] ref_sr;
    reg        sync;
    reg [63:0] match_run;
    reg [63:0] bad_run;
    reg [63:0] err_cnt;
    reg        win;
    reg [63:0] err_snap;
    reg [63:0] win_errs;

    initial ref_sr    = 64'h1;
    initial sync      = 1'b0;
    initial match_run = 64'd0;
    initial bad_run   = 64'd0;
    initial err_cnt   = 64'd0;
    initial win       = 1'b0;
    initial err_snap  = 64'd0;
    initial win_errs  = 64'd0;

    // PRBS x^64 + x^63 + x^61 + x^60 + 1 prediction
    wire        pred    = ref_sr[63] ^ ref_sr[62] ^ ref_sr[60] ^ ref_sr[59];
    wire        mism    = sync && (i_bit != pred);
    wire        cnt_inc = mism && (err_cnt != MAXV);
    wire [63:0] err_nxt = cnt_inc ? (err_cnt + 64'd1) : err_cnt;
    wire        lose    = mism && ((bad_run + 64'd1) >= LOSS_LEN);
    wire        open_w  = i_arm && sync && !lose && !i_disarm;
    wire        close_w = i_disarm || lose;

    always @(posedge clk) begin
        if (i_reset) begin
            ref_sr    <= 64'h1;
            sync      <= 1'b0;
            match_run <= 64'd0;
            bad_run   <= 64'd0;
            err_cnt   <= 64'd0;
            win       <= 1'b0;
            err_snap  <= 64'd0;
            win_errs  <= 64'd0;
        end else if (i_ce) begin
            err_cnt <= err_nxt;
            if (!sync) begin
                // self-synchronising: load incoming stream into reference
                ref_sr  <= {ref_sr[62:0], i_bit};
                bad_run <= 64'd0;
                if (i_bit == pred) begin
                    if ((match_run + 64'd1) >= SYNC_LEN) begin
                        sync      <= 1'b1;
                        match_run <= 64'd0;
                    end else begin
                        match_run <= match_run + 64'd1;
                    end
                end else begin
                    match_run <= 64'd0;
                end
            end else begin
                // locked: free-run the local reference
                ref_sr    <= {ref_sr[62:0], pred};
                match_run <= 64'd0;
                if (mism) begin
                    if (lose) begin
                        sync    <= 1'b0;
                        bad_run <= 64'd0;
                    end else begin
                        bad_run <= bad_run + 64'd1;
                    end
                end else begin
                    bad_run <= 64'd0;
                end
            end
            // measurement window: opened by arm while locked, closed by disarm or sync loss
            if (win) begin
                if (close_w) win <= 1'b0;
                if (cnt_inc) win_errs <= win_errs + 64'd1;
            end else if (open_w) begin
                win      <= 1'b1;
                err_snap <= err_nxt;
                win_errs <= 64'd0;
            end
        end
    end

    assign o_sync = sync;
    assign o_errs = err_cnt;

    // Precedence inside the window: a nonzero window tally requires the global
    // counter to have advanced past the snapshot recorded when the window opened.
    always @(*)
        if (win && (win_errs != 64'd0))
            assert (err_cnt != err_snap);

    // With no window errors, the global counter must still equal the snapshot.
    always @(*)
        if (win && (win_errs == 64'd0))
            assert (err_cnt == err_snap);
    assign err_cnt_o = err_cnt;
    assign err_snap_o = err_snap;
    assign win_o = win;
    assign win_errs_o = win_errs;
endmodule

module route_prbs_top (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    input  wire         ld,
    input  wire         step,
    input  wire         arm,
    input  wire         disarm,
    output wire [127:0] out_q,
    output wire         out_v,
    output wire [31:0]  dbg_stat,
    output wire         o_sync,
    output wire [63:0]  o_errs,
    output wire         win_o,
    output wire [8:0]   stg_o
);
    wire [3:0]  a_cnt;
    wire        a_half_beat;
    wire [2:0]  a_rd_ptr;
    wire [63:0] b_err_cnt;
    wire [63:0] b_err_snap;
    wire        b_win;
    wire [63:0] b_win_errs;

    xbar_route_rom u_a (
        .clk(clk), .rst_n(rst_n), .en(en), .start(start), .stop(stop),
        .out_q(out_q), .out_v(out_v), .dbg_stat(dbg_stat),
        .cnt_o(a_cnt), .half_beat_o(a_half_beat), .rd_ptr_o(a_rd_ptr)
    );

    // beat staging register: latches the route cursor, then sequences it locally
    reg       g_v;
    reg [2:0] g_ptr;
    reg [3:0] g_cnt;
    reg       g_hb;

    initial begin
        g_v   = 1'b0;
        g_ptr = 3'd0;
        g_cnt = 4'd0;
        g_hb  = 1'b0;
    end

    wire g_load = ld && out_v;
    wire g_adv  = step && g_v && !g_load;

    always @(posedge clk) begin
        if (!rst_n) begin
            g_v   <= 1'b0;
            g_ptr <= 3'd0;
            g_cnt <= 4'd0;
            g_hb  <= 1'b0;
        end else if (g_load) begin
            g_v   <= 1'b1;
            g_ptr <= a_rd_ptr;
            g_cnt <= a_cnt;
            g_hb  <= a_half_beat;
        end else if (g_adv) begin
            if (g_ptr == 3'd7) begin
                g_ptr <= 3'd0;
                g_cnt <= 4'd0;
                g_hb  <= 1'b0;
            end else begin
                g_ptr <= g_ptr + 3'd1;
                if (g_hb) g_cnt <= g_cnt + 4'd2;
                g_hb  <= !g_hb;
            end
        end
    end

    wire stg_bit = g_ptr[0] ^ g_ptr[1] ^ g_ptr[2] ^ g_cnt[1] ^ g_cnt[2] ^ g_hb;
    wire b_ce    = g_adv;
    wire b_rst   = !rst_n;

    prbs_win_checker u_b (
        .clk(clk), .i_reset(b_rst), .i_ce(b_ce), .i_bit(stg_bit),
        .i_arm(arm), .i_disarm(disarm),
        .o_sync(o_sync), .o_errs(o_errs),
        .err_cnt_o(b_err_cnt), .err_snap_o(b_err_snap),
        .win_o(b_win), .win_errs_o(b_win_errs)
    );

    assign win_o = b_win;
    assign stg_o = {g_v, g_ptr, g_cnt, g_hb};

    // a staged cursor must always name a beat within the eight-entry route table
    always @(*)
        if (g_v)
            assert (g_cnt <= 4'd7);
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;
localparam [1:0] OV_DEPTH = 2'd2;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;
reg [127:0] bq_d0, bq_d1, bq_d2, bq_d3;
reg [127:0] bq_head;
reg [3:0] bq_tag;
reg [1:0] bq_wp, bq_rp;
reg [2:0] bq_cnt;
reg [127:0] ov_d0, ov_d1;
reg [127:0] ov_head;
reg [1:0] ov_tag;
reg ov_wp, ov_rp;
reg [1:0] ov_cnt;
reg [127:0] bq_in_data;
reg bq_in_tag;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;
initial bq_d0 = 128'h0;
initial bq_d1 = 128'h0;
initial bq_d2 = 128'h0;
initial bq_d3 = 128'h0;
initial bq_tag = 4'h0;
initial bq_wp = 2'd0;
initial bq_rp = 2'd0;
initial bq_cnt = 3'd0;
initial ov_d0 = 128'h0;
initial ov_d1 = 128'h0;
initial ov_tag = 2'h0;
initial ov_wp = 1'b0;
initial ov_rp = 1'b0;
initial ov_cnt = 2'd0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
wire bq_empty = (bq_cnt == 3'd0);
wire bq_full = (bq_cnt >= 3'd4);
wire bq_pop = en && !clr_cmd && !bq_empty && (fsm != S_DONE);
wire bq_space = !bq_full || bq_pop;
wire ov_empty = (ov_cnt == 2'd0);
wire ov_full = (ov_cnt >= OV_DEPTH);
wire ov_drain = en && !clr_cmd && !ov_empty && bq_space;
wire beat_direct = en && !clr_cmd && beat_valid && ov_empty && bq_space;
wire ov_fill = en && !clr_cmd && beat_valid && !beat_direct && (!ov_full || ov_drain);
wire beat_accept = beat_direct || ov_fill;
wire bq_push = ov_drain || beat_direct;
wire push_tag = (fsm == S_ARMED) && match0;
wire start_drop = en && !clr_cmd && push_tag && !beat_accept;
wire head_start = bq_pop && bq_tag[bq_rp];
wire match1 = bq_pop && (((bq_head ^ wval1) & wmask1) == 128'h0);

always @(*) begin
case (bq_rp)
2'd0: bq_head = bq_d0;
2'd1: bq_head = bq_d1;
2'd2: bq_head = bq_d2;
default: bq_head = bq_d3;
endcase
end
always @(*) begin
case (ov_rp)
1'b0: ov_head = ov_d0;
default: ov_head = ov_d1;
endcase
end
always @(*) begin
if (ov_empty) begin
bq_in_data = beat_data;
bq_in_tag = push_tag;
end else begin
bq_in_data = ov_head;
bq_in_tag = ov_tag[ov_rp];
end
end

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
S_ARMED: if (start_drop && !started_seen) fsm_nxt = S_IDLE;
else if (head_start) fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
bq_d0 <= 128'h0;
bq_d1 <= 128'h0;
bq_d2 <= 128'h0;
bq_d3 <= 128'h0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
ov_d0 <= 128'h0;
ov_d1 <= 128'h0;
ov_tag <= 2'h0;
ov_wp <= 1'b0;
ov_rp <= 1'b0;
ov_cnt <= 2'd0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
bq_tag <= 4'h0;
bq_wp <= 2'd0;
bq_rp <= 2'd0;
bq_cnt <= 3'd0;
ov_tag <= 2'h0;
ov_wp <= 1'b0;
ov_rp <= 1'b0;
ov_cnt <= 2'd0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
if (beat_accept && push_tag) started_seen <= 1'b1;
if (bq_pop) begin
bq_tag[bq_rp] <= 1'b0;
bq_rp <= bq_rp + 2'd1;
end
if (bq_push) begin
case (bq_wp)
2'd0: bq_d0 <= bq_in_data;
2'd1: bq_d1 <= bq_in_data;
2'd2: bq_d2 <= bq_in_data;
default: bq_d3 <= bq_in_data;
endcase
bq_tag[bq_wp] <= bq_in_tag;
bq_wp <= bq_wp + 2'd1;
end
if (ov_drain) begin
ov_tag[ov_rp] <= 1'b0;
ov_rp <= ov_rp + 1'b1;
end
if (ov_fill) begin
case (ov_wp)
1'b0: ov_d0 <= beat_data;
default: ov_d1 <= beat_data;
endcase
ov_tag[ov_wp] <= push_tag;
ov_wp <= ov_wp + 1'b1;
end
case ({ov_fill, ov_drain})
2'b10: ov_cnt <= ov_cnt + 2'd1;
2'b01: ov_cnt <= ov_cnt - 2'd1;
default: ov_cnt <= ov_cnt;
endcase
case ({bq_push, bq_pop})
2'b10: bq_cnt <= bq_cnt + 3'd1;
2'b01: bq_cnt <= bq_cnt - 3'd1;
default: bq_cnt <= bq_cnt;
endcase
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);

   always @(posedge clk)
       if (!rst) assert (!(fsm == S_ARMED && started_seen) || (bq_cnt != 3'd0));
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
,
    output wire [3:0] cnt_o,
    output wire pf_vld_o,
    output wire [127:0] pf_word_o,
    output wire [2:0] rd_ptr_o,
    output wire win_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
localparam [1:0] ROM_LAT  = 2'd3;
localparam [3:0] MAX_PASS = 4'd15;
reg [127:0] pf_word;
reg         pf_vld;
reg [1:0]   pf_wait;
reg [3:0]   pass_cnt;
reg         sweep_done;
wire [127:0] issue_word = {pf_word[127:80], 12'h0, pass_cnt, pf_word[63:0]};

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
pf_word    = 128'h0;
pf_vld     = 1'b0;
pf_wait    = 2'd0;
pass_cnt   = 4'd0;
sweep_done = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
pf_word    <= 128'h0;
pf_vld     <= 1'b0;
pf_wait    <= 2'd0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
pf_vld     <= 1'b0;
pf_wait    <= 2'd0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
end else if (win && pf_vld) begin
out_q  <= issue_word;
                out_v <= 1'b1;
pf_vld <= 1'b0;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
if (pass_cnt == MAX_PASS) begin
win        <= 1'b0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b1;
end else begin
pass_cnt <= pass_cnt + 4'd1;
end
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
end else if (win) begin
if (pf_wait == ROM_LAT) begin
pf_word <= rom_word;
pf_vld  <= 1'b1;
pf_wait <= 2'd0;
end else begin
pf_wait <= pf_wait + 2'd1;
end
end else if (sweep_done) begin
out_v <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);

   always @(posedge clk)
       if (win && en && cnt != 4'd0)
           assert (out_q[63:48] == {12'h0, cnt - 4'd1});
    assign cnt_o = cnt;
    assign pf_vld_o = pf_vld;
    assign pf_word_o = pf_word;
    assign rd_ptr_o = rd_ptr;
    assign win_o = win;
endmodule

module xbar_route_pool (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire [5:0] req,
    input  wire [5:0] rel,
    output wire [3:0] pool_o,
    output wire [5:0] held_o,
    output wire [5:0] win_vec_o,
    output wire [5:0] vld_vec_o
);
    localparam [3:0] TOTAL = 4'd4;

    reg [3:0] pool;
    reg h0, h1, h2, h3, h4, h5;

    initial begin
        pool = TOTAL;
        h0 = 1'b0; h1 = 1'b0; h2 = 1'b0;
        h3 = 1'b0; h4 = 1'b0; h5 = 1'b0;
    end

    wire can_gnt = en && (pool != 4'd0);
    wire w0 = req[0] && !h0;
    wire w1 = req[1] && !h1;
    wire w2 = req[2] && !h2;
    wire w3 = req[3] && !h3;
    wire w4 = req[4] && !h4;
    wire w5 = req[5] && !h5;
    wire g0 = can_gnt && w0;
    wire g1 = can_gnt && w1 && !w0;
    wire g2 = can_gnt && w2 && !w0 && !w1;
    wire g3 = can_gnt && w3 && !w0 && !w1 && !w2;
    wire g4 = can_gnt && w4 && !w0 && !w1 && !w2 && !w3;
    wire g5 = can_gnt && w5 && !w0 && !w1 && !w2 && !w3 && !w4;
    wire any_g = g0 | g1 | g2 | g3 | g4 | g5;

    wire c0 = rel[0] && h0;
    wire c1 = rel[1] && h1;
    wire c2 = rel[2] && h2;
    wire c3 = rel[3] && h3;
    wire c4 = rel[4] && h4;
    wire c5 = rel[5] && h5;
    wire r0 = en && c0;
    wire r1 = en && c1 && !c0;
    wire r2 = en && c2 && !c0 && !c1;
    wire r3 = en && c3 && !c0 && !c1 && !c2;
    wire r4 = en && c4 && !c0 && !c1 && !c2 && !c3;
    wire r5 = en && c5 && !c0 && !c1 && !c2 && !c3 && !c4;
    wire any_r = r0 | r1 | r2 | r3 | r4 | r5;

    wire [127:0] oq0, oq1, oq2, oq3, oq4, oq5;
    wire ov0, ov1, ov2, ov3, ov4, ov5;
    wire [3:0] cnt0, cnt1, cnt2, cnt3, cnt4, cnt5;
    wire pfv0, pfv1, pfv2, pfv3, pfv4, pfv5;
    wire [127:0] pfw0, pfw1, pfw2, pfw3, pfw4, pfw5;
    wire [2:0] rdp0, rdp1, rdp2, rdp3, rdp4, rdp5;
    wire win0, win1, win2, win3, win4, win5;

    xbar_route_rom u0 (.clk(clk), .rst_n(rst_n), .en(en), .start(g0), .stop(r0), .out_q(oq0), .out_v(ov0), .cnt_o(cnt0), .pf_vld_o(pfv0), .pf_word_o(pfw0), .rd_ptr_o(rdp0), .win_o(win0));
    xbar_route_rom u1 (.clk(clk), .rst_n(rst_n), .en(en), .start(g1), .stop(r1), .out_q(oq1), .out_v(ov1), .cnt_o(cnt1), .pf_vld_o(pfv1), .pf_word_o(pfw1), .rd_ptr_o(rdp1), .win_o(win1));
    xbar_route_rom u2 (.clk(clk), .rst_n(rst_n), .en(en), .start(g2), .stop(r2), .out_q(oq2), .out_v(ov2), .cnt_o(cnt2), .pf_vld_o(pfv2), .pf_word_o(pfw2), .rd_ptr_o(rdp2), .win_o(win2));
    xbar_route_rom u3 (.clk(clk), .rst_n(rst_n), .en(en), .start(g3), .stop(r3), .out_q(oq3), .out_v(ov3), .cnt_o(cnt3), .pf_vld_o(pfv3), .pf_word_o(pfw3), .rd_ptr_o(rdp3), .win_o(win3));
    xbar_route_rom u4 (.clk(clk), .rst_n(rst_n), .en(en), .start(g4), .stop(r4), .out_q(oq4), .out_v(ov4), .cnt_o(cnt4), .pf_vld_o(pfv4), .pf_word_o(pfw4), .rd_ptr_o(rdp4), .win_o(win4));
    xbar_route_rom u5 (.clk(clk), .rst_n(rst_n), .en(en), .start(g5), .stop(r5), .out_q(oq5), .out_v(ov5), .cnt_o(cnt5), .pf_vld_o(pfv5), .pf_word_o(pfw5), .rd_ptr_o(rdp5), .win_o(win5));

    always @(posedge clk) begin
        if (!rst_n) begin
            pool <= TOTAL;
            h0 <= 1'b0; h1 <= 1'b0; h2 <= 1'b0;
            h3 <= 1'b0; h4 <= 1'b0; h5 <= 1'b0;
        end else begin
            if (g0) h0 <= 1'b1; else if (r0) h0 <= 1'b0;
            if (g1) h1 <= 1'b1; else if (r1) h1 <= 1'b0;
            if (g2) h2 <= 1'b1; else if (r2) h2 <= 1'b0;
            if (g3) h3 <= 1'b1; else if (r3) h3 <= 1'b0;
            if (g4) h4 <= 1'b1; else if (r4) h4 <= 1'b0;
            if (g5) h5 <= 1'b1; else if (r5) h5 <= 1'b0;
            pool <= pool - {3'b0, any_g} + {3'b0, any_r};
        end
    end

    always @(posedge clk)
        assert (pool <= TOTAL);

    assign pool_o    = pool;
    assign held_o    = {h5, h4, h3, h2, h1, h0};
    assign win_vec_o = {win5, win4, win3, win2, win1, win0};
    assign vld_vec_o = {ov5, ov4, ov3, ov2, ov1, ov0};
endmodule

module vbrk_cmp (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    output reg          done
,
    output wire armed_seen_o,
    output wire [1:0] fsm_o,
    output wire started_seen_o
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_RUN = 2'd2, S_DONE = 2'd3;

    reg [127:0] wval0, wval1, wmask0, wmask1;
    reg [1:0] fsm;
    reg armed_seen, started_seen, pre_clr;
    reg [1:0] fsm_nxt;

    initial wval0 = 128'h0;
    initial wval1 = 128'h0;
    initial wmask0 = 128'h0;
    initial wmask1 = 128'h0;
    initial fsm = S_IDLE;
    initial armed_seen = 1'b0;
    initial started_seen = 1'b0;
    initial pre_clr = 1'b1;
    initial done = 1'b0;

    wire match0 = beat_valid && (((beat_data ^ wval0) & wmask0) == 128'h0);
    wire match1 = beat_valid && (((beat_data ^ wval1) & wmask1) == 128'h0);

    always @(posedge clk)
        if (en && wr_en) begin
            if (wr_sel) begin
                wval1  <= wr_val;
                wmask1 <= wr_mask;
            end else begin
                wval0  <= wr_val;
                wmask0 <= wr_mask;
            end
        end

    always @(*) begin
        fsm_nxt = fsm;
        if (clr_cmd)
            fsm_nxt = S_IDLE;
        else case (fsm)
            S_IDLE:  if (arm_cmd) fsm_nxt = S_ARMED;
            S_ARMED: if (match0)  fsm_nxt = S_RUN;
            S_RUN:   if (match1)  fsm_nxt = S_DONE;
            default: fsm_nxt = fsm;
        endcase
    end

    always @(posedge clk)
        if (rst) begin
            fsm <= S_IDLE;
            armed_seen <= 1'b0;
            started_seen <= 1'b0;
            pre_clr <= 1'b1;
            done <= 1'b0;
        end else if (en) begin
            fsm  <= fsm_nxt;
            done <= (fsm_nxt == S_DONE);
            if (clr_cmd) begin
                armed_seen <= 1'b0;
                started_seen <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (fsm == S_IDLE && arm_cmd) armed_seen <= 1'b1;
                if (fsm == S_ARMED && match0) started_seen <= 1'b1;
            end
        end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && pre_clr && $rose(done))
            assert (armed_seen && started_seen);
    assign armed_seen_o = armed_seen;
    assign fsm_o = fsm;
    assign started_seen_o = started_seen;
endmodule

module coyote_vfpga_bod (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire cmp_low,
    input wire clr,
    input wire sel_wr,
    input wire [1:0] sel_in,
    output wire slot_reset
,
    output wire bo_flag_o,
    output wire [15:0] deb_cnt_o,
    output wire [15:0] streak_o,
    output wire [15:0] thr_o
);
    reg [15:0] deb_cnt = 16'd0;
    reg [1:0]  thr_sel = 2'd0;
    reg        bo_flag = 1'b0;
    reg [15:0] streak  = 16'd0;
    reg        pv      = 1'b0;

    reg [15:0] thr;
    always @(*) begin
        case (thr_sel)
            2'd0: thr = 16'd4;
            2'd1: thr = 16'd16;
            2'd2: thr = 16'd256;
            default: thr = 16'd4096;
        endcase
    end

    wire [16:0] deb_inc    = {1'b0, deb_cnt} + 17'd1;
    wire [15:0] streak_inc = (streak == 16'hFFFF) ? 16'hFFFF : (streak + 16'd1);

    always @(posedge clk) begin
        if (!rst_n) begin
            deb_cnt <= 16'd0;
            thr_sel <= 2'd0;
            bo_flag <= 1'b0;
            streak  <= 16'd0;
        end else if (en) begin
            if (!cmp_low) begin
                deb_cnt <= 16'd0;
                streak  <= 16'd0;
            end else begin
                streak <= streak_inc;
                if (!bo_flag) begin
                    deb_cnt <= deb_inc[15:0];
                    if (deb_inc >= {1'b0, thr})
                        bo_flag <= 1'b1;
                end
            end
            if (clr) begin
                bo_flag <= 1'b0;
                deb_cnt <= 16'd0;
            end
            if (sel_wr && (deb_cnt == 16'd0))
                thr_sel <= sel_in;
        end
    end

    assign slot_reset = bo_flag;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $rose(bo_flag))
            assert (streak >= thr);
    assign bo_flag_o = bo_flag;
    assign deb_cnt_o = deb_cnt;
    assign streak_o = streak;
    assign thr_o = thr;
endmodule

module vbrk_bod_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o
,
    output wire armed_seen_a_o,
    output wire bo_flag_b_o,
    output wire brk_q_o,
    output wire [15:0] deb_cnt_b_o,
    output wire done_a_o,
    output wire [1:0] fsm_a_o,
    output wire q_ok_o,
    output wire [15:0] qual_cnt_obs,
    output wire started_seen_a_o,
    output wire [15:0] streak_b_o,
    output wire [15:0] thr_b_o
);
    wire        done_a;
    wire        armed_seen_a;
    wire        started_seen_a;
    wire [1:0]  fsm_a;
    wire        bo_flag_b;
    wire [15:0] deb_cnt_b;
    wire [15:0] streak_b;
    wire [15:0] thr_b;
    wire        slot_reset_b;

    reg        brk_q    = 1'b0;
    reg        q_ok     = 1'b0;
    reg [15:0] qual_cnt = 16'd0;

    vbrk_cmp u_cmp (
        .clk(clk),
        .rst(rst),
        .en(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .done(done_a),
        .armed_seen_o(armed_seen_a),
        .fsm_o(fsm_a),
        .started_seen_o(started_seen_a)
    );

    coyote_vfpga_bod u_bod (
        .clk(clk),
        .rst_n(!rst),
        .en(en_b),
        .cmp_low(brk_q),
        .clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .slot_reset(slot_reset_b),
        .bo_flag_o(bo_flag_b),
        .deb_cnt_o(deb_cnt_b),
        .streak_o(streak_b),
        .thr_o(thr_b)
    );

    wire brk_qualified = brk_q && q_ok;

    always @(posedge clk) begin
        if (rst) begin
            brk_q    <= 1'b0;
            q_ok     <= 1'b0;
            qual_cnt <= 16'd0;
        end else begin
            if (cap_en) begin
                brk_q <= done_a;
                q_ok  <= armed_seen_a && started_seen_a;
            end
            if (en_b) begin
                if (brk_qualified)
                    qual_cnt <= (qual_cnt == 16'hFFFF) ? 16'hFFFF : (qual_cnt + 16'd1);
                else
                    qual_cnt <= 16'd0;
            end
        end
    end

    always @(posedge clk)
        assert (qual_cnt >= deb_cnt_b);

    assign done       = done_a;
    assign slot_reset = slot_reset_b;
    assign brk_o      = brk_q;
    assign qual_cnt_o = qual_cnt;
    assign armed_seen_a_o = armed_seen_a;
    assign bo_flag_b_o = bo_flag_b;
    assign brk_q_o = brk_q;
    assign deb_cnt_b_o = deb_cnt_b;
    assign done_a_o = done_a;
    assign fsm_a_o = fsm_a;
    assign q_ok_o = q_ok;
    assign qual_cnt_obs = qual_cnt;
    assign started_seen_a_o = started_seen_a;
    assign streak_b_o = streak_b;
    assign thr_b_o = thr_b;
endmodule

module GF8MulCore (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [7:0] a_in,
    input wire [7:0] b_in,
    input wire [7:0] poly_in,
    input wire poly_we,
    output reg done,
    output wire [7:0] result
,
    output wire [7:0] bitcnt_o,
    output wire busy_o,
    output wire [7:0] deadline_o
);
    reg [7:0] acc;
    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [7:0] poly;
    reg [7:0] bitcnt;
    reg [7:0] deadline;
    reg busy;
    reg armed;

    initial begin
        acc = 8'd0;
        a_reg = 8'd0;
        b_reg = 8'd0;
        poly = 8'd0;
        bitcnt = 8'd0;
        deadline = 8'd0;
        busy = 1'b0;
        armed = 1'b0;
        done = 1'b0;
    end

    assign result = acc;

    wire [7:0] a_shl = {a_reg[6:0], 1'b0};
    wire [7:0] xtime = a_reg[7] ? (a_shl ^ poly) : a_shl;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd0;
            a_reg <= 8'd0;
            b_reg <= 8'd0;
            poly <= 8'd0;
            bitcnt <= 8'd0;
            deadline <= 8'd0;
            busy <= 1'b0;
            armed <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            done <= 1'b0;
            if (poly_we && !busy)
                poly <= poly_in;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    armed <= 1'b1;
                    acc <= 8'd0;
                    a_reg <= a_in;
                    b_reg <= b_in;
                    bitcnt <= 8'd8;
                    deadline <= 8'd9;
                end
            end else if (bitcnt != 8'd0) begin
                if (b_reg[0])
                    acc <= acc ^ a_reg;
                a_reg <= xtime;
                b_reg <= {1'b0, b_reg[7:1]};
                bitcnt <= bitcnt - 8'd1;
                deadline <= deadline - 8'd1;
            end else begin
                busy <= 1'b0;
                deadline <= 8'd0;
                done <= 1'b1;
            end
        end
    end

    assert property (!(armed && busy) || (deadline != 8'd0));
    assign bitcnt_o = bitcnt;
    assign busy_o = busy;
    assign deadline_o = deadline;
endmodule

module vbrk_gf8_top (
    input  wire         clk,
    input  wire         rst,
    input  wire         en_a,
    input  wire         beat_valid,
    input  wire [127:0] beat_data,
    input  wire         wr_en,
    input  wire         wr_sel,
    input  wire [127:0] wr_val,
    input  wire [127:0] wr_mask,
    input  wire         arm_cmd,
    input  wire         clr_cmd,
    input  wire         cap_en,
    input  wire         en_b,
    input  wire         bod_clr,
    input  wire         sel_wr,
    input  wire [1:0]   sel_in,
    input  wire         job_cap,
    input  wire         en_m,
    input  wire [7:0]   poly_in,
    input  wire         poly_we,
    output wire         done,
    output wire         slot_reset,
    output wire         brk_o,
    output wire [15:0]  qual_cnt_o,
    output wire         gf_done,
    output wire [7:0]   gf_result,
    output wire         job_pend_o,
    output wire         job_inflight_o,
    output wire [7:0]   job_wd_o,
    output wire         gf_busy_o,
output wire [7:0]   gf_deadline_o,
output wire [7:0]   job_iss_cnt_o,
output wire [7:0]   job_ret_cnt_o
);
    wire        a_done;
    wire        a_slot_reset;
    wire        a_brk;
    wire [15:0] a_qual_cnt_out;
    wire        a_armed_seen;
    wire        a_bo_flag;
    wire        a_brk_q;
    wire [15:0] a_deb_cnt;
    wire        a_done_mirror;
    wire [1:0]  a_fsm;
    wire        a_q_ok;
    wire [15:0] a_qual_cnt;
    wire        a_started_seen;
    wire [15:0] a_streak;
    wire [15:0] a_thr;

    wire        m_done;
    wire [7:0]  m_result;
    wire [7:0]  m_bitcnt;
    wire        m_busy;
    wire [7:0]  m_deadline;

    reg        job_pend     = 1'b0;
    reg [7:0]  job_a        = 8'd0;
    reg [7:0]  job_b        = 8'd0;
    reg        job_inflight = 1'b0;
    reg [7:0]  job_wd       = 8'd0;
reg [7:0]  job_iss_cnt  = 8'd0;
reg [7:0]  job_ret_cnt  = 8'd0;

    vbrk_bod_top u_a (
        .clk(clk),
        .rst(rst),
        .en_a(en_a),
        .beat_valid(beat_valid),
        .beat_data(beat_data),
        .wr_en(wr_en),
        .wr_sel(wr_sel),
        .wr_val(wr_val),
        .wr_mask(wr_mask),
        .arm_cmd(arm_cmd),
        .clr_cmd(clr_cmd),
        .cap_en(cap_en),
        .en_b(en_b),
        .bod_clr(bod_clr),
        .sel_wr(sel_wr),
        .sel_in(sel_in),
        .done(a_done),
        .slot_reset(a_slot_reset),
        .brk_o(a_brk),
        .qual_cnt_o(a_qual_cnt_out),
        .armed_seen_a_o(a_armed_seen),
        .bo_flag_b_o(a_bo_flag),
        .brk_q_o(a_brk_q),
        .deb_cnt_b_o(a_deb_cnt),
        .done_a_o(a_done_mirror),
        .fsm_a_o(a_fsm),
        .q_ok_o(a_q_ok),
        .qual_cnt_obs(a_qual_cnt),
        .started_seen_a_o(a_started_seen),
        .streak_b_o(a_streak),
        .thr_b_o(a_thr)
    );

    GF8MulCore u_m (
        .clk(clk),
        .rst(rst),
        .en(en_m),
        .req(job_pend),
        .a_in(job_a),
        .b_in(job_b),
        .poly_in(poly_in),
        .poly_we(poly_we),
        .done(m_done),
        .result(m_result),
        .bitcnt_o(m_bitcnt),
        .busy_o(m_busy),
        .deadline_o(m_deadline)
    );

    wire job_issue = en_m && job_pend && !m_busy;
wire job_drain  = (m_bitcnt == 8'd0) && (job_iss_cnt != job_ret_cnt);
wire job_retire = en_m && !job_issue && job_inflight && job_drain;

    always @(posedge clk) begin
        if (rst) begin
            job_pend     <= 1'b0;
            job_a        <= 8'd0;
            job_b        <= 8'd0;
            job_inflight <= 1'b0;
            job_wd       <= 8'd0;
job_iss_cnt  <= 8'd0;
job_ret_cnt  <= 8'd0;
        end else begin
            if (!job_pend) begin
                if (job_cap && a_brk_q) begin
                    job_pend <= 1'b1;
                    job_a    <= a_qual_cnt[7:0];
                    job_b    <= a_deb_cnt[7:0];
                end
            end else if (job_issue) begin
                job_pend <= 1'b0;
            end
            if (en_m) begin
if (job_issue)
job_iss_cnt <= job_iss_cnt + 8'd1;
if (job_retire)
job_ret_cnt <= job_ret_cnt + 8'd1;
                if (job_issue) begin
                    job_inflight <= 1'b1;
                    job_wd       <= 8'd9;
                end else if (job_inflight) begin
if (job_drain) begin
                        job_inflight <= 1'b0;
                        job_wd       <= 8'd0;
                    end else begin
                        job_wd <= job_wd - 8'd1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        if (job_inflight)
            assert (job_wd != 8'd0);

    assign done           = a_done;
    assign slot_reset     = a_slot_reset;
    assign brk_o          = a_brk;
    assign qual_cnt_o     = a_qual_cnt_out;
    assign gf_done        = m_done;
    assign gf_result      = m_result;
    assign job_pend_o     = job_pend;
    assign job_inflight_o = job_inflight;
    assign job_wd_o       = job_wd;
    assign gf_busy_o      = m_busy;
    assign gf_deadline_o  = m_deadline;
assign job_iss_cnt_o  = job_iss_cnt;
assign job_ret_cnt_o  = job_ret_cnt;
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
    output reg          out_v
,
    output wire [3:0] cnt_o,
    output wire pf_vld_o,
    output wire [127:0] pf_word_o,
    output wire [2:0] rd_ptr_o,
    output wire win_o
);
    reg       win;
    reg [2:0] rd_ptr;
    reg [3:0] cnt;
localparam [1:0] ROM_LAT  = 2'd3;
localparam [3:0] MAX_PASS = 4'd15;
reg [127:0] pf_word;
reg         pf_vld;
reg [1:0]   pf_wait;
reg [3:0]   pass_cnt;
reg         sweep_done;
wire [127:0] issue_word = {pf_word[127:80], 12'h0, pass_cnt, pf_word[63:0]};

    initial begin
        win    = 1'b0;
        rd_ptr = 3'd0;
        cnt    = 4'd0;
        out_q  = 128'h0;
        out_v  = 1'b0;
pf_word    = 128'h0;
pf_vld     = 1'b0;
pf_wait    = 2'd0;
pass_cnt   = 4'd0;
sweep_done = 1'b0;
    end

    reg [127:0] rom_word;
    always @(*) begin
        case (rd_ptr)
            3'd0: rom_word = 128'h0001_0002_0000_0000_0000_FFFF_0000_0001;
            3'd1: rom_word = 128'h0002_0004_0001_0000_0001_FFFF_0000_0002;
            3'd2: rom_word = 128'h0004_0008_0002_0000_0002_FFFF_0000_0004;
            3'd3: rom_word = 128'h0008_0010_0003_0000_0003_FFFF_0000_0008;
            3'd4: rom_word = 128'h0010_0020_0004_0000_0004_FFFF_0000_0010;
            3'd5: rom_word = 128'h0020_0040_0005_0000_0005_FFFF_0000_0020;
            3'd6: rom_word = 128'h0040_0080_0006_0000_0006_FFFF_0000_0040;
            default: rom_word = 128'h0080_0001_0007_0000_0007_FFFF_0000_0080;
        endcase
    end

    always @(posedge clk) begin
        if (!rst_n) begin
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
pf_word    <= 128'h0;
pf_vld     <= 1'b0;
pf_wait    <= 2'd0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b0;
        end else if (en) begin
            if (start) begin
                win    <= 1'b1;
                rd_ptr <= 3'd0;
                cnt    <= 4'd0;
pf_vld     <= 1'b0;
pf_wait    <= 2'd0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b0;
            end else if (stop) begin
                win <= 1'b0;
end else if (win && pf_vld) begin
out_q  <= issue_word;
                out_v <= 1'b1;
pf_vld <= 1'b0;
                if (rd_ptr == 3'd7) begin
                    rd_ptr <= 3'd0;
                    cnt    <= 4'd0;
if (pass_cnt == MAX_PASS) begin
win        <= 1'b0;
pass_cnt   <= 4'd0;
sweep_done <= 1'b1;
end else begin
pass_cnt <= pass_cnt + 4'd1;
end
                end else begin
                    rd_ptr <= rd_ptr + 3'd1;
                    cnt    <= cnt + 4'd1;
                end
end else if (win) begin
if (pf_wait == ROM_LAT) begin
pf_word <= rom_word;
pf_vld  <= 1'b1;
pf_wait <= 2'd0;
end else begin
pf_wait <= pf_wait + 2'd1;
end
end else if (sweep_done) begin
out_v <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);

   always @(posedge clk)
       if (win && en && cnt != 4'd0)
           assert (out_q[63:48] == {12'h0, cnt - 4'd1});
    assign cnt_o = cnt;
    assign pf_vld_o = pf_vld;
    assign pf_word_o = pf_word;
    assign rd_ptr_o = rd_ptr;
    assign win_o = win;
endmodule

module xbar_route_pool (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire [5:0] req,
    input  wire [5:0] rel,
    output wire [3:0] pool_o,
    output wire [5:0] held_o,
    output wire [5:0] win_vec_o,
    output wire [5:0] vld_vec_o
,
    output wire [3:0] cnt0_o,
    output wire [3:0] cnt1_o,
    output wire [3:0] cnt2_o,
    output wire [3:0] cnt3_o,
    output wire [3:0] cnt4_o,
    output wire [3:0] cnt5_o,
    output wire h0_o,
    output wire h1_o,
    output wire h2_o,
    output wire h3_o,
    output wire h4_o,
    output wire h5_o,
    output wire [127:0] oq0_o,
    output wire [127:0] oq1_o,
    output wire [127:0] oq2_o,
    output wire [127:0] oq3_o,
    output wire [127:0] oq4_o,
    output wire [127:0] oq5_o,
    output wire pfv0_o,
    output wire pfv1_o,
    output wire pfv2_o,
    output wire pfv3_o,
    output wire pfv4_o,
    output wire pfv5_o,
    output wire [127:0] pfw0_o,
    output wire [127:0] pfw1_o,
    output wire [127:0] pfw2_o,
    output wire [127:0] pfw3_o,
    output wire [127:0] pfw4_o,
    output wire [127:0] pfw5_o,
    output wire [3:0] pool_obs,
    output wire [2:0] rdp0_o,
    output wire [2:0] rdp1_o,
    output wire [2:0] rdp2_o,
    output wire [2:0] rdp3_o,
    output wire [2:0] rdp4_o,
    output wire [2:0] rdp5_o,
    output wire win0_o,
    output wire win1_o,
    output wire win2_o,
    output wire win3_o,
    output wire win4_o,
    output wire win5_o
);
    localparam [3:0] TOTAL = 4'd4;

    reg [3:0] pool;
    reg h0, h1, h2, h3, h4, h5;

    initial begin
        pool = TOTAL;
        h0 = 1'b0; h1 = 1'b0; h2 = 1'b0;
        h3 = 1'b0; h4 = 1'b0; h5 = 1'b0;
    end

    wire can_gnt = en && (pool != 4'd0);
    wire w0 = req[0] && !h0;
    wire w1 = req[1] && !h1;
    wire w2 = req[2] && !h2;
    wire w3 = req[3] && !h3;
    wire w4 = req[4] && !h4;
    wire w5 = req[5] && !h5;
    wire g0 = can_gnt && w0;
    wire g1 = can_gnt && w1 && !w0;
    wire g2 = can_gnt && w2 && !w0 && !w1;
    wire g3 = can_gnt && w3 && !w0 && !w1 && !w2;
    wire g4 = can_gnt && w4 && !w0 && !w1 && !w2 && !w3;
    wire g5 = can_gnt && w5 && !w0 && !w1 && !w2 && !w3 && !w4;
    wire any_g = g0 | g1 | g2 | g3 | g4 | g5;

    wire c0 = rel[0] && h0;
    wire c1 = rel[1] && h1;
    wire c2 = rel[2] && h2;
    wire c3 = rel[3] && h3;
    wire c4 = rel[4] && h4;
    wire c5 = rel[5] && h5;
    wire r0 = en && c0;
    wire r1 = en && c1 && !c0;
    wire r2 = en && c2 && !c0 && !c1;
    wire r3 = en && c3 && !c0 && !c1 && !c2;
    wire r4 = en && c4 && !c0 && !c1 && !c2 && !c3;
    wire r5 = en && c5 && !c0 && !c1 && !c2 && !c3 && !c4;
    wire any_r = r0 | r1 | r2 | r3 | r4 | r5;

    wire [127:0] oq0, oq1, oq2, oq3, oq4, oq5;
    wire ov0, ov1, ov2, ov3, ov4, ov5;
    wire [3:0] cnt0, cnt1, cnt2, cnt3, cnt4, cnt5;
    wire pfv0, pfv1, pfv2, pfv3, pfv4, pfv5;
    wire [127:0] pfw0, pfw1, pfw2, pfw3, pfw4, pfw5;
    wire [2:0] rdp0, rdp1, rdp2, rdp3, rdp4, rdp5;
    wire win0, win1, win2, win3, win4, win5;

    xbar_route_rom u0 (.clk(clk), .rst_n(rst_n), .en(en), .start(g0), .stop(r0), .out_q(oq0), .out_v(ov0), .cnt_o(cnt0), .pf_vld_o(pfv0), .pf_word_o(pfw0), .rd_ptr_o(rdp0), .win_o(win0));
    xbar_route_rom u1 (.clk(clk), .rst_n(rst_n), .en(en), .start(g1), .stop(r1), .out_q(oq1), .out_v(ov1), .cnt_o(cnt1), .pf_vld_o(pfv1), .pf_word_o(pfw1), .rd_ptr_o(rdp1), .win_o(win1));
    xbar_route_rom u2 (.clk(clk), .rst_n(rst_n), .en(en), .start(g2), .stop(r2), .out_q(oq2), .out_v(ov2), .cnt_o(cnt2), .pf_vld_o(pfv2), .pf_word_o(pfw2), .rd_ptr_o(rdp2), .win_o(win2));
    xbar_route_rom u3 (.clk(clk), .rst_n(rst_n), .en(en), .start(g3), .stop(r3), .out_q(oq3), .out_v(ov3), .cnt_o(cnt3), .pf_vld_o(pfv3), .pf_word_o(pfw3), .rd_ptr_o(rdp3), .win_o(win3));
    xbar_route_rom u4 (.clk(clk), .rst_n(rst_n), .en(en), .start(g4), .stop(r4), .out_q(oq4), .out_v(ov4), .cnt_o(cnt4), .pf_vld_o(pfv4), .pf_word_o(pfw4), .rd_ptr_o(rdp4), .win_o(win4));
    xbar_route_rom u5 (.clk(clk), .rst_n(rst_n), .en(en), .start(g5), .stop(r5), .out_q(oq5), .out_v(ov5), .cnt_o(cnt5), .pf_vld_o(pfv5), .pf_word_o(pfw5), .rd_ptr_o(rdp5), .win_o(win5));

    always @(posedge clk) begin
        if (!rst_n) begin
            pool <= TOTAL;
            h0 <= 1'b0; h1 <= 1'b0; h2 <= 1'b0;
            h3 <= 1'b0; h4 <= 1'b0; h5 <= 1'b0;
        end else begin
            if (g0) h0 <= 1'b1; else if (r0) h0 <= 1'b0;
            if (g1) h1 <= 1'b1; else if (r1) h1 <= 1'b0;
            if (g2) h2 <= 1'b1; else if (r2) h2 <= 1'b0;
            if (g3) h3 <= 1'b1; else if (r3) h3 <= 1'b0;
            if (g4) h4 <= 1'b1; else if (r4) h4 <= 1'b0;
            if (g5) h5 <= 1'b1; else if (r5) h5 <= 1'b0;
            pool <= pool - {3'b0, any_g} + {3'b0, any_r};
        end
    end

    always @(posedge clk)
        assert (pool <= TOTAL);

    assign pool_o    = pool;
    assign held_o    = {h5, h4, h3, h2, h1, h0};
    assign win_vec_o = {win5, win4, win3, win2, win1, win0};
    assign vld_vec_o = {ov5, ov4, ov3, ov2, ov1, ov0};
    assign cnt0_o = cnt0;
    assign cnt1_o = cnt1;
    assign cnt2_o = cnt2;
    assign cnt3_o = cnt3;
    assign cnt4_o = cnt4;
    assign cnt5_o = cnt5;
    assign h0_o = h0;
    assign h1_o = h1;
    assign h2_o = h2;
    assign h3_o = h3;
    assign h4_o = h4;
    assign h5_o = h5;
    assign oq0_o = oq0;
    assign oq1_o = oq1;
    assign oq2_o = oq2;
    assign oq3_o = oq3;
    assign oq4_o = oq4;
    assign oq5_o = oq5;
    assign pfv0_o = pfv0;
    assign pfv1_o = pfv1;
    assign pfv2_o = pfv2;
    assign pfv3_o = pfv3;
    assign pfv4_o = pfv4;
    assign pfv5_o = pfv5;
    assign pfw0_o = pfw0;
    assign pfw1_o = pfw1;
    assign pfw2_o = pfw2;
    assign pfw3_o = pfw3;
    assign pfw4_o = pfw4;
    assign pfw5_o = pfw5;
    assign pool_obs = pool;
    assign rdp0_o = rdp0;
    assign rdp1_o = rdp1;
    assign rdp2_o = rdp2;
    assign rdp3_o = rdp3;
    assign rdp4_o = rdp4;
    assign rdp5_o = rdp5;
    assign win0_o = win0;
    assign win1_o = win1;
    assign win2_o = win2;
    assign win3_o = win3;
    assign win4_o = win4;
    assign win5_o = win5;
endmodule

module xbar_route_credit4 (
    input  wire        clk,
    input  wire        rst_n,
    input  wire [3:0]  en,
    input  wire [23:0] req,
    input  wire [23:0] rel,
    output wire [3:0]  spool_o,
    output wire [15:0] ipool_o,
    output wire [3:0]  busy_o
);
    localparam [3:0] TOTAL = 4'd8;

    reg [3:0] spool;
    initial spool = TOTAL;

    wire [3:0] i0_pool, i1_pool, i2_pool, i3_pool;
    wire [5:0] i0_held, i1_held, i2_held, i3_held;
    wire i0_h0, i0_h1, i0_h2, i0_h3, i0_h4, i0_h5;
    wire i1_h0, i1_h1, i1_h2, i1_h3, i1_h4, i1_h5;
    wire i2_h0, i2_h1, i2_h2, i2_h3, i2_h4, i2_h5;
    wire i3_h0, i3_h1, i3_h2, i3_h3, i3_h4, i3_h5;
    wire [3:0] i0_cnt0, i0_cnt1, i0_cnt2, i0_cnt3, i0_cnt4, i0_cnt5;
    wire [3:0] i1_cnt0, i1_cnt1, i1_cnt2, i1_cnt3, i1_cnt4, i1_cnt5;
    wire [3:0] i2_cnt0, i2_cnt1, i2_cnt2, i2_cnt3, i2_cnt4, i2_cnt5;
    wire [3:0] i3_cnt0, i3_cnt1, i3_cnt2, i3_cnt3, i3_cnt4, i3_cnt5;
    wire [2:0] i0_rdp0, i0_rdp1, i0_rdp2, i0_rdp3, i0_rdp4, i0_rdp5;
    wire [2:0] i1_rdp0, i1_rdp1, i1_rdp2, i1_rdp3, i1_rdp4, i1_rdp5;
    wire [2:0] i2_rdp0, i2_rdp1, i2_rdp2, i2_rdp3, i2_rdp4, i2_rdp5;
    wire [2:0] i3_rdp0, i3_rdp1, i3_rdp2, i3_rdp3, i3_rdp4, i3_rdp5;
    wire i0_win0, i0_win1, i0_win2, i0_win3, i0_win4, i0_win5;
    wire i1_win0, i1_win1, i1_win2, i1_win3, i1_win4, i1_win5;
    wire i2_win0, i2_win1, i2_win2, i2_win3, i2_win4, i2_win5;
    wire i3_win0, i3_win1, i3_win2, i3_win3, i3_win4, i3_win5;
    wire [127:0] i0_oq0, i0_oq1, i0_oq2, i0_oq3, i0_oq4, i0_oq5;
    wire [127:0] i1_oq0, i1_oq1, i1_oq2, i1_oq3, i1_oq4, i1_oq5;
    wire [127:0] i2_oq0, i2_oq1, i2_oq2, i2_oq3, i2_oq4, i2_oq5;
    wire [127:0] i3_oq0, i3_oq1, i3_oq2, i3_oq3, i3_oq4, i3_oq5;
    wire i0_pfv0, i0_pfv1, i0_pfv2, i0_pfv3, i0_pfv4, i0_pfv5;
    wire i1_pfv0, i1_pfv1, i1_pfv2, i1_pfv3, i1_pfv4, i1_pfv5;
    wire i2_pfv0, i2_pfv1, i2_pfv2, i2_pfv3, i2_pfv4, i2_pfv5;
    wire i3_pfv0, i3_pfv1, i3_pfv2, i3_pfv3, i3_pfv4, i3_pfv5;
    wire [127:0] i0_pfw0, i0_pfw1, i0_pfw2, i0_pfw3, i0_pfw4, i0_pfw5;
    wire [127:0] i1_pfw0, i1_pfw1, i1_pfw2, i1_pfw3, i1_pfw4, i1_pfw5;
    wire [127:0] i2_pfw0, i2_pfw1, i2_pfw2, i2_pfw3, i2_pfw4, i2_pfw5;
    wire [127:0] i3_pfw0, i3_pfw1, i3_pfw2, i3_pfw3, i3_pfw4, i3_pfw5;

    wire cred_avail = (spool != 4'd0);

    wire want0 = en[0] && (i0_pool != 4'd0) && ((req[5:0]   & ~i0_held) != 6'd0);
    wire want1 = en[1] && (i1_pool != 4'd0) && ((req[11:6]  & ~i1_held) != 6'd0);
    wire want2 = en[2] && (i2_pool != 4'd0) && ((req[17:12] & ~i2_held) != 6'd0);
    wire want3 = en[3] && (i3_pool != 4'd0) && ((req[23:18] & ~i3_held) != 6'd0);

    wire take0 = cred_avail && want0;
    wire take1 = cred_avail && want1 && !want0;
    wire take2 = cred_avail && want2 && !want0 && !want1;
    wire take3 = cred_avail && want3 && !want0 && !want1 && !want2;
    wire any_take = take0 | take1 | take2 | take3;

    wire [5:0] q0 = take0 ? req[5:0]   : 6'd0;
    wire [5:0] q1 = take1 ? req[11:6]  : 6'd0;
    wire [5:0] q2 = take2 ? req[17:12] : 6'd0;
    wire [5:0] q3 = take3 ? req[23:18] : 6'd0;

    wire give0 = en[0] && ((rel[5:0]   & i0_held) != 6'd0);
    wire give1 = en[1] && ((rel[11:6]  & i1_held) != 6'd0);
    wire give2 = en[2] && ((rel[17:12] & i2_held) != 6'd0);
    wire give3 = en[3] && ((rel[23:18] & i3_held) != 6'd0);
    wire [2:0] n_give = {2'b0, give0} + {2'b0, give1} + {2'b0, give2} + {2'b0, give3};

    wire [2:0] t0 = {2'b0, i0_h0} + {2'b0, i0_h1} + {2'b0, i0_h2} + {2'b0, i0_h3} + {2'b0, i0_h4} + {2'b0, i0_h5};
    wire [2:0] t1 = {2'b0, i1_h0} + {2'b0, i1_h1} + {2'b0, i1_h2} + {2'b0, i1_h3} + {2'b0, i1_h4} + {2'b0, i1_h5};
    wire [2:0] t2 = {2'b0, i2_h0} + {2'b0, i2_h1} + {2'b0, i2_h2} + {2'b0, i2_h3} + {2'b0, i2_h4} + {2'b0, i2_h5};
    wire [2:0] t3 = {2'b0, i3_h0} + {2'b0, i3_h1} + {2'b0, i3_h2} + {2'b0, i3_h3} + {2'b0, i3_h4} + {2'b0, i3_h5};

    xbar_route_pool p0 (.clk(clk), .rst_n(rst_n), .en(en[0]), .req(q0), .rel(rel[5:0]),
        .pool_o(i0_pool), .held_o(i0_held), .win_vec_o(), .vld_vec_o(),
        .cnt0_o(i0_cnt0), .cnt1_o(i0_cnt1), .cnt2_o(i0_cnt2), .cnt3_o(i0_cnt3), .cnt4_o(i0_cnt4), .cnt5_o(i0_cnt5),
        .h0_o(i0_h0), .h1_o(i0_h1), .h2_o(i0_h2), .h3_o(i0_h3), .h4_o(i0_h4), .h5_o(i0_h5),
        .oq0_o(i0_oq0), .oq1_o(i0_oq1), .oq2_o(i0_oq2), .oq3_o(i0_oq3), .oq4_o(i0_oq4), .oq5_o(i0_oq5),
        .pfv0_o(i0_pfv0), .pfv1_o(i0_pfv1), .pfv2_o(i0_pfv2), .pfv3_o(i0_pfv3), .pfv4_o(i0_pfv4), .pfv5_o(i0_pfv5),
        .pfw0_o(i0_pfw0), .pfw1_o(i0_pfw1), .pfw2_o(i0_pfw2), .pfw3_o(i0_pfw3), .pfw4_o(i0_pfw4), .pfw5_o(i0_pfw5),
        .pool_obs(),
        .rdp0_o(i0_rdp0), .rdp1_o(i0_rdp1), .rdp2_o(i0_rdp2), .rdp3_o(i0_rdp3), .rdp4_o(i0_rdp4), .rdp5_o(i0_rdp5),
        .win0_o(i0_win0), .win1_o(i0_win1), .win2_o(i0_win2), .win3_o(i0_win3), .win4_o(i0_win4), .win5_o(i0_win5));

    xbar_route_pool p1 (.clk(clk), .rst_n(rst_n), .en(en[1]), .req(q1), .rel(rel[11:6]),
        .pool_o(i1_pool), .held_o(i1_held), .win_vec_o(), .vld_vec_o(),
        .cnt0_o(i1_cnt0), .cnt1_o(i1_cnt1), .cnt2_o(i1_cnt2), .cnt3_o(i1_cnt3), .cnt4_o(i1_cnt4), .cnt5_o(i1_cnt5),
        .h0_o(i1_h0), .h1_o(i1_h1), .h2_o(i1_h2), .h3_o(i1_h3), .h4_o(i1_h4), .h5_o(i1_h5),
        .oq0_o(i1_oq0), .oq1_o(i1_oq1), .oq2_o(i1_oq2), .oq3_o(i1_oq3), .oq4_o(i1_oq4), .oq5_o(i1_oq5),
        .pfv0_o(i1_pfv0), .pfv1_o(i1_pfv1), .pfv2_o(i1_pfv2), .pfv3_o(i1_pfv3), .pfv4_o(i1_pfv4), .pfv5_o(i1_pfv5),
