                  out_v    <= 1'b1;
                  eq_rp    <= eq_rp + 1'b1;
                  if (eq_last)
                      cnt <= 4'd0;
                  else
                      cnt <= cnt + 4'd1;
              end
              case ({eq_push, eq_pop})
                  2'b10:   eq_used <= eq_used + 2'd1;
                  2'b01:   eq_used <= eq_used - 2'd1;
                  default: eq_used <= eq_used;
              endcase
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module mpu_region_checker (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    output reg         grant,
output reg         fault,
output reg  [3:0]  n_acc_in,   // accesses accepted into the lookup stage
output reg  [3:0]  n_acc_out,  // accesses retired from the lookup stage
output reg  [15:0] dbg_status   // rotating debug/statistics readout
,
    output wire hit_q_o,
    output wire miss_q_o
);
    // 24 regions: 16-bit base, 16-bit limit, 2-bit permission {write, read}
    reg [383:0] base_flat  = 384'd0;
    reg [383:0] limit_flat = 384'd0;
    reg [47:0]  perm_flat  = 48'd0;

    reg pre_lock = 1'b1;   // high until the configuration is locked for the first time
    reg hit_q    = 1'b0;
    reg miss_q   = 1'b0;
    reg pv       = 1'b0;

    initial grant = 1'b0;
    initial fault = 1'b0;
initial n_acc_in  = 4'd0;
initial n_acc_out = 4'd0;
   // ---- debug / statistics bank (observability only) ----
   reg [7:0]  dbg_grant_cnt   = 8'd0;
   reg [7:0]  dbg_fault_cnt   = 8'd0;
   reg [5:0]  dbg_cfg_wr_cnt  = 6'd0;
   reg [5:0]  dbg_cfg_rej_cnt = 6'd0;
   reg [7:0]  dbg_idle_cnt    = 8'd0;
   reg        dbg_wdog_trip   = 1'b0;
   reg [15:0] dbg_addr_d1     = 16'd0;
   reg [15:0] dbg_fault_addr  = 16'd0;
   reg [1:0]  dbg_sel         = 2'd0;
   initial dbg_status = 16'd0;

    reg hit;
    integer i;
    always @(*) begin
        hit = 1'b0;
        for (i = 0; i < 24; i = i + 1) begin
            if ((acc_write ? perm_flat[2*i+1] : perm_flat[2*i]) &&
                (acc_addr >= base_flat[16*i +: 16]) &&
                (acc_addr <= limit_flat[16*i +: 16]))
                hit = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (i_ce) begin
            if (cfg_we && pre_lock && (cfg_idx < 5'd24)) begin
                base_flat[cfg_idx*16 +: 16]  <= cfg_base;
                limit_flat[cfg_idx*16 +: 16] <= cfg_limit;
                perm_flat[cfg_idx*2 +: 2]    <= cfg_perm;
            end
            if (lock_req)
                pre_lock <= 1'b0;
            hit_q  <= acc_valid && hit;
            miss_q <= acc_valid && !hit;
            grant  <= hit_q;
// a hit retiring while the ledger shows nothing outstanding is a spurious response
fault  <= miss_q || (hit_q && (n_acc_in == n_acc_out));
if (acc_valid)
    n_acc_in <= n_acc_in + 4'd1;
if (hit_q || miss_q)
    n_acc_out <= n_acc_out + 4'd1;
        end
    end

    always @(posedge clk) pv <= 1'b1;

   always @(posedge clk) begin
       if (i_ce) begin
           dbg_addr_d1 <= acc_addr;
           if (grant && (dbg_grant_cnt != 8'hFF))
               dbg_grant_cnt <= dbg_grant_cnt + 8'd1;
           if (fault && (dbg_fault_cnt != 8'hFF))
               dbg_fault_cnt <= dbg_fault_cnt + 8'd1;
           if (miss_q)
               dbg_fault_addr <= dbg_addr_d1;
           if (cfg_we) begin
               if (pre_lock && (cfg_idx < 5'd24))
                   dbg_cfg_wr_cnt <= dbg_cfg_wr_cnt + 6'd1;
               else
                   dbg_cfg_rej_cnt <= dbg_cfg_rej_cnt + 6'd1;
           end
           if (acc_valid) begin
               dbg_idle_cnt  <= 8'd0;
               dbg_wdog_trip <= 1'b0;
           end else if (dbg_idle_cnt == 8'hFF)
               dbg_wdog_trip <= 1'b1;
           else
               dbg_idle_cnt <= dbg_idle_cnt + 8'd1;
           dbg_sel <= dbg_sel + 2'd1;
           case (dbg_sel)
               2'd0:    dbg_status <= {dbg_grant_cnt, dbg_fault_cnt};
               2'd1:    dbg_status <= {dbg_cfg_wr_cnt, dbg_cfg_rej_cnt, pre_lock, dbg_wdog_trip, 2'b00};
               2'd2:    dbg_status <= dbg_fault_addr;
               default: dbg_status <= {dbg_idle_cnt, 4'd0, n_acc_in - n_acc_out};
           endcase
       end
   end

    always @(posedge clk)
        if (pv && pre_lock && $rose(fault))
            assert (!grant);
    assign hit_q_o = hit_q;
    assign miss_q_o = miss_q;
endmodule

module rgmii_relay_fifo (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [3:0]  rxd_rise,
    input  wire [3:0]  rxd_fall,
    input  wire        ctl_rise,
    input  wire        ctl_fall,
    input  wire        rd_en,
    output wire [31:0] dout,
    output wire        empty,
    output wire [31:0] o_occ
,
    output wire [31:0] occ_o,
    output wire [31:0] rd_cnt_o,
    output wire [31:0] wr_cnt_o
);
    reg [4:0]  cap_rise;
    reg [4:0]  cap_fall;
    reg [1:0]  byte_ph;
    reg [23:0] shift;
    reg [31:0] mem [0:3];
    reg [31:0] wr_cnt;
    reg [31:0] rd_cnt;
    reg [31:0] occ;
    reg        armed;

    initial begin
        cap_rise = 5'd0;
        cap_fall = 5'd0;
        byte_ph  = 2'd0;
        shift    = 24'd0;
        mem[0]   = 32'd0;
        mem[1]   = 32'd0;
        mem[2]   = 32'd0;
        mem[3]   = 32'd0;
        wr_cnt   = 32'd0;
        rd_cnt   = 32'd0;
        occ      = 32'd0;
        armed    = 1'b0;
    end

    wire       rx_dv   = cap_rise[4];
    wire [7:0] rx_byte = {cap_fall[3:0], cap_rise[3:0]};
    wire [31:0] diff   = wr_cnt - rd_cnt;
    wire       full    = (diff == 32'd4);
    wire       push    = en && rx_dv && (byte_ph == 2'd3) && !full;
    wire       pop     = en && rd_en && (wr_cnt != rd_cnt);

    always @(posedge clk) begin
        if (rst) begin
            cap_rise <= 5'd0;
            cap_fall <= 5'd0;
            byte_ph  <= 2'd0;
            shift    <= 24'd0;
            mem[0]   <= 32'd0;
            mem[1]   <= 32'd0;
            mem[2]   <= 32'd0;
            mem[3]   <= 32'd0;
            wr_cnt   <= 32'd0;
            rd_cnt   <= 32'd0;
            occ      <= 32'd0;
            armed    <= 1'b0;
        end else if (en) begin
            cap_rise <= {ctl_rise, rxd_rise};
            cap_fall <= {ctl_fall, rxd_fall};
            armed    <= armed | rx_dv;
            if (rx_dv) begin
                byte_ph <= byte_ph + 2'd1;
                case (byte_ph)
                    2'd0: shift[7:0]   <= rx_byte;
                    2'd1: shift[15:8]  <= rx_byte;
                    2'd2: shift[23:16] <= rx_byte;
                    default: ;
                endcase
            end
            if (push) begin
                mem[wr_cnt[1:0]] <= {rx_byte, shift};
                wr_cnt <= wr_cnt + 32'd1;
            end
            if (pop)
                rd_cnt <= rd_cnt + 32'd1;
            occ <= occ + (push ? 32'd1 : 32'd0) - (pop ? 32'd1 : 32'd0);
        end
    end

    assign dout  = mem[rd_cnt[1:0]];
    assign empty = (wr_cnt == rd_cnt);
    assign o_occ = occ;

    always @(posedge clk)
        if (armed)
            assert (occ <= 32'd4);
    assign occ_o = occ;
    assign rd_cnt_o = rd_cnt;
    assign wr_cnt_o = wr_cnt;
endmodule

module mpu_verdict_relay (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_idx,
    input  wire [15:0] cfg_base,
    input  wire [15:0] cfg_limit,
    input  wire [1:0]  cfg_perm,
    input  wire        lock_req,
    input  wire        acc_valid,
    input  wire        acc_write,
    input  wire [15:0] acc_addr,
    input  wire        relay_en,
    input  wire        rd_en,
    output wire        grant,
    output wire        fault,
    output wire [15:0] dbg_status,
    output wire [31:0] dout,
    output wire        empty,
    output wire [31:0] o_occ,
    output reg         pend_vld,
    output reg  [7:0]  pend_byte,
    output reg         tx_vld,
    output reg  [7:0]  tx_byte,
    output reg  [3:0]  vseq,
    output reg  [7:0]  drop_cnt
);
    wire        a_grant;
    wire        a_fault;
    wire [3:0]  a_n_in;
    wire [3:0]  a_n_out;
    wire [15:0] a_dbg;
    wire        a_hit_q;
    wire        a_miss_q;

    wire [31:0] b_dout;
    wire        b_empty;
    wire [31:0] b_o_occ;
    wire [31:0] b_occ;
    wire [31:0] b_rd_cnt;
    wire [31:0] b_wr_cnt;

    initial pend_vld  = 1'b0;
    initial pend_byte = 8'd0;
    initial tx_vld    = 1'b0;
    initial tx_byte   = 8'd0;
    initial vseq      = 4'd0;
    initial drop_cnt  = 8'd0;

    mpu_region_checker u_mpu (
        .clk(clk),
        .i_ce(i_ce),
        .cfg_we(cfg_we),
        .cfg_idx(cfg_idx),
        .cfg_base(cfg_base),
        .cfg_limit(cfg_limit),
        .cfg_perm(cfg_perm),
        .lock_req(lock_req),
        .acc_valid(acc_valid),
        .acc_write(acc_write),
        .acc_addr(acc_addr),
        .grant(a_grant),
        .fault(a_fault),
        .n_acc_in(a_n_in),
        .n_acc_out(a_n_out),
        .dbg_status(a_dbg),
        .hit_q_o(a_hit_q),
        .miss_q_o(a_miss_q)
    );

    // a lookup retiring from the MPU lookup stage produces one verdict record
    wire       verdict_ev   = i_ce && (a_hit_q || a_miss_q);
    wire [7:0] verdict_byte = {2'b01, a_miss_q, a_hit_q, vseq};
    wire       pend_free    = !pend_vld || relay_en;

    always @(posedge clk) begin
        if (rst) begin
            pend_vld  <= 1'b0;
            pend_byte <= 8'd0;
            tx_vld    <= 1'b0;
            tx_byte   <= 8'd0;
            vseq      <= 4'd0;
            drop_cnt  <= 8'd0;
        end else begin
            if (relay_en) begin
                tx_vld <= pend_vld;
                if (pend_vld)
                    tx_byte <= pend_byte;
            end
            if (verdict_ev && pend_free) begin
                pend_vld  <= 1'b1;
                pend_byte <= verdict_byte;
                vseq      <= vseq + 4'd1;
            end else if (relay_en) begin
                pend_vld <= 1'b0;
            end
            if (verdict_ev && !pend_free && (drop_cnt != 8'hFF))
                drop_cnt <= drop_cnt + 8'd1;
        end
    end

    rgmii_relay_fifo u_fifo (
        .clk(clk),
        .rst(rst),
        .en(relay_en),
        .rxd_rise(tx_byte[3:0]),
        .rxd_fall(tx_byte[7:4]),
        .ctl_rise(tx_vld),
        .ctl_fall(tx_vld),
        .rd_en(rd_en),
        .dout(b_dout),
        .empty(b_empty),
        .o_occ(b_o_occ),
        .occ_o(b_occ),
        .rd_cnt_o(b_rd_cnt),
        .wr_cnt_o(b_wr_cnt)
    );

    assign grant      = a_grant;
    assign fault      = a_fault;
    assign dbg_status = a_dbg;
    assign dout       = b_dout;
    assign empty      = b_empty;
    assign o_occ      = b_o_occ;

    // every record on the relay link is a well-formed verdict: type tag 01, exactly one of miss/hit
    always @(posedge clk)
        if (tx_vld)
            assert ((tx_byte[7:6] == 2'b01) && (tx_byte[5] != tx_byte[4]));
endmodule

module pg_seq (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_req,
    output reg win,
    output reg [2:0] state,
    output reg save_ack,
    output reg ramp_ack,
output reg rest_ack,
output reg vfy_busy,
output reg [2:0] vfy_cnt,
output reg [1:0] retry_cnt,
output reg [1:0] last_retry,
output reg retry_exh
,
    output wire [7:0] ramp_cnt_o
);
    localparam [2:0] S_IDLE = 3'd0, S_SAVE = 3'd1, S_RAMP = 3'd2, S_REST = 3'd3, S_DONE = 3'd4;
    localparam [7:0] RAMP_LAST = 8'd15;
localparam [2:0] VFY_LAST = 3'd5;
localparam [1:0] RETRY_MAX = 2'd3;

    reg [7:0] ramp_cnt;

    initial begin
        state = S_IDLE; win = 1'b0;
        save_ack = 1'b0; ramp_ack = 1'b0; rest_ack = 1'b0;
        ramp_cnt = 8'd0;
vfy_busy = 1'b0; vfy_cnt = 3'd0;
retry_cnt = 2'd0; last_retry = 2'd0; retry_exh = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            state <= S_IDLE; win <= 1'b0;
            save_ack <= 1'b0; ramp_ack <= 1'b0; rest_ack <= 1'b0;
            ramp_cnt <= 8'd0;
vfy_busy <= 1'b0; vfy_cnt <= 3'd0;
retry_cnt <= 2'd0; last_retry <= 2'd0; retry_exh <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_req) begin
                        state <= S_SAVE;
                        win <= 1'b1;
                        save_ack <= 1'b0;
                        ramp_ack <= 1'b0;
                        rest_ack <= 1'b0;
retry_cnt <= 2'd0;
retry_exh <= 1'b0;
                    end
                end
                S_SAVE: begin
                    save_ack <= 1'b1;
                    ramp_cnt <= 8'd0;
                    state <= S_RAMP;
                end
                S_RAMP: begin
                    if (ramp_cnt == RAMP_LAST) begin
if (!vfy_busy) begin
vfy_busy <= 1'b1;
vfy_cnt <= 3'd0;
end
                    end else begin
                        ramp_cnt <= ramp_cnt + 8'd1;
                    end
                end
                S_REST: begin
                    rest_ack <= 1'b1;
                    state <= S_DONE;
                end
                S_DONE: begin
last_retry <= retry_cnt;
                    state <= S_IDLE;
                    win <= 1'b0;
                end
                default: begin
                    state <= S_IDLE;
                    win <= 1'b0;
                end
            endcase
// Post-ramp rail verification. The rail must settle for VFY_LAST+1
// enabled cycles before the ramp is acknowledged. A request seen while
// settling means the saved context is stale: drop the save and redo it,
// up to RETRY_MAX times, after which the ramp is accepted and flagged.
if (vfy_busy) begin
if (i_req && retry_cnt != RETRY_MAX) begin
vfy_busy <= 1'b0;
retry_cnt <= retry_cnt + 2'd1;
save_ack <= 1'b0;
state <= S_SAVE;
end else begin
if (i_req)
retry_exh <= 1'b1;
if (vfy_cnt == VFY_LAST) begin
vfy_busy <= 1'b0;
ramp_ack <= 1'b1;
state <= S_REST;
end else begin
vfy_cnt <= vfy_cnt + 3'd1;
end
end
end
        end
    end

    // Chain precedence inside the power-down window: save before ramp, ramp before restore
    always @(posedge clk)
        if (win && ramp_ack)
            assert (save_ack);

    always @(posedge clk)
        if (win && rest_ack)
            assert (ramp_ack);
    assign ramp_cnt_o = ramp_cnt;
endmodule

module pg_seq_pool (
    input wire clk,
    input wire rst,
    input wire [5:0] i_ce,
    input wire [5:0] i_req,
    output wire [2:0] pool_o,
    output wire [5:0] gnt_o,
    output wire [5:0] win_o,
    output wire [17:0] state_o,
    output wire [5:0] save_ack_o,
    output wire [5:0] ramp_ack_o,
    output wire [5:0] rest_ack_o,
    output wire [5:0] vfy_busy_o,
    output wire [17:0] vfy_cnt_o,
    output wire [11:0] retry_cnt_o,
    output wire [11:0] last_retry_o,
    output wire [5:0] retry_exh_o,
   output reg [3:0] cr_issued,
   output reg [3:0] cr_returned,
    output wire [47:0] ramp_cnt_o
);
    // Shared power-down budget: at most TOTAL rails may be in a window at once.
    localparam [2:0] TOTAL = 3'd4;

    reg [2:0] pool;
    initial pool = TOTAL;
   initial cr_issued = 4'd0;
   initial cr_returned = 4'd0;

    wire win_t0, win_t1, win_t2, win_t3, win_t4, win_t5;
    wire [2:0] state_t0, state_t1, state_t2, state_t3, state_t4, state_t5;
    wire save_t0, save_t1, save_t2, save_t3, save_t4, save_t5;
    wire ramp_t0, ramp_t1, ramp_t2, ramp_t3, ramp_t4, ramp_t5;
    wire rest_t0, rest_t1, rest_t2, rest_t3, rest_t4, rest_t5;
    wire vbusy_t0, vbusy_t1, vbusy_t2, vbusy_t3, vbusy_t4, vbusy_t5;
    wire [2:0] vcnt_t0, vcnt_t1, vcnt_t2, vcnt_t3, vcnt_t4, vcnt_t5;
    wire [1:0] rcnt_t0, rcnt_t1, rcnt_t2, rcnt_t3, rcnt_t4, rcnt_t5;
    wire [1:0] lretry_t0, lretry_t1, lretry_t2, lretry_t3, lretry_t4, lretry_t5;
    wire rexh_t0, rexh_t1, rexh_t2, rexh_t3, rexh_t4, rexh_t5;
    wire [7:0] rampc_t0, rampc_t1, rampc_t2, rampc_t3, rampc_t4, rampc_t5;

    wire [5:0] w = {win_t5, win_t4, win_t3, win_t2, win_t1, win_t0};
    wire [5:0] done = {(state_t5 == 3'd4), (state_t4 == 3'd4), (state_t3 == 3'd4),
                       (state_t2 == 3'd4), (state_t1 == 3'd4), (state_t0 == 3'd4)};

    // Idle sequencers asking to enter a window; lowest index wins a free credit.
    wire [5:0] cand = ~w & i_req & i_ce;
   // Credits currently out on loan, read from the lifetime grant/return ledger.
   wire [3:0] outstanding = cr_issued - cr_returned;
   wire [5:0] gnt = (outstanding != {1'b0, TOTAL}) ? (cand & (~cand + 6'd1)) : 6'd0;
    // A sequencer leaving S_DONE hands its credit back.
    wire [5:0] rel = w & done & i_ce;
    // Requests inside a window are retry requests and always pass through.
    wire [5:0] req_g = i_req & (w | gnt);
   // Number of credits handed back this cycle (several rails may finish together).
   wire [2:0] rel_cnt = {2'b00, rel[0]} + {2'b00, rel[1]} + {2'b00, rel[2]}
                      + {2'b00, rel[3]} + {2'b00, rel[4]} + {2'b00, rel[5]};

    wire [3:0] pool_n = {1'b0, pool}
                      + {3'b000, rel[0]} + {3'b000, rel[1]} + {3'b000, rel[2]}
                      + {3'b000, rel[3]} + {3'b000, rel[4]} + {3'b000, rel[5]}
                      - {3'b000, (|gnt)};

    always @(posedge clk) begin
        if (rst) begin
            pool <= TOTAL;
           cr_issued <= 4'd0;
           cr_returned <= 4'd0;
        end else begin
            pool <= pool_n[2:0];
           cr_issued <= cr_issued + {3'b000, (|gnt)};
           cr_returned <= cr_returned + {1'b0, rel_cnt};
        end
    end

    // A full pool means no rail is inside a power-down window.
    always @(posedge clk)
        if (pool == 3'd4)
            assert (w == 6'd0);

    pg_seq u0 (.clk(clk), .rst(rst), .i_ce(i_ce[0]), .i_req(req_g[0]), .win(win_t0), .state(state_t0), .save_ack(save_t0), .ramp_ack(ramp_t0), .rest_ack(rest_t0), .vfy_busy(vbusy_t0), .vfy_cnt(vcnt_t0), .retry_cnt(rcnt_t0), .last_retry(lretry_t0), .retry_exh(rexh_t0), .ramp_cnt_o(rampc_t0));
    pg_seq u1 (.clk(clk), .rst(rst), .i_ce(i_ce[1]), .i_req(req_g[1]), .win(win_t1), .state(state_t1), .save_ack(save_t1), .ramp_ack(ramp_t1), .rest_ack(rest_t1), .vfy_busy(vbusy_t1), .vfy_cnt(vcnt_t1), .retry_cnt(rcnt_t1), .last_retry(lretry_t1), .retry_exh(rexh_t1), .ramp_cnt_o(rampc_t1));
