                   pf_data[pf_wp] <= pf_in_data;
                   pf_tag[pf_wp]  <= pf_in_tag;
                   pf_wp          <= pf_wp + 2'd1;
               end
               if (pf_pop) begin
                  eq_data[eq_wp] <= pf_data[pf_rp];
                  eq_tag[eq_wp]  <= pf_head_tag;
                  eq_wp          <= eq_wp + 1'b1;
                  pf_rp          <= pf_rp + 2'd1;
              end
if (ln_pop) begin
    out_q    <= ln_data;
    out_tag  <= ln_tag[2:0];
    out_last <= ln_last;
    out_par  <= ^ln_data;
    out_v    <= 1'b1;
