if (eq_pop) begin
    ln_data <= eq_data[eq_rp];
    ln_tag  <= eq_head_tag;
    eq_rp   <= eq_rp + 1'b1;
end
if (eq_pop)
    ln_v <= 1'b1;
else if (ln_pop)
    ln_v <= 1'b0;
              case ({eq_push, eq_pop})
                  2'b10:   eq_used <= eq_used + 2'd1;
                  2'b01:   eq_used <= eq_used - 2'd1;
                  default: eq_used <= eq_used;
