                   ra_rp <= ra_rp + 2'd1;
                   if (ra_res > ra_lat_o)
                       ra_lat_o <= ra_res;
                   if (ra_par_bad)
                       ra_perr_o <= ra_perr_o + 16'd1;
ra_pop_o <= ra_pop_o + 16'd1;
if (ra_par_bad && !bk_ferr_v_o) begin
    bk_ferr_o   <= {1'b0, ra_head_tag[2:0]};
    bk_ferr_v_o <= 1'b1;
end
               end
if (rb_pop) begin
    rb_rp    <= rb_rp + 2'd1;
    rb_pop_o <= rb_pop_o + 16'd1;
    if (rb_res > rb_lat_o)
        rb_lat_o <= rb_res;
    if (rb_par_bad)
        rb_perr_o <= rb_perr_o + 16'd1;
    if (rb_par_bad && !bk_ferr_v_o) begin
        bk_ferr_o   <= {1'b1, rb_head_tag[2:0]};
        bk_ferr_v_o <= 1'b1;
    end
end
               ra_v <= ra_v_nxt;
rb_v <= rb_v_nxt;
               if (pf_push) begin
                   pf_data[pf_wp] <= pf_in_data;
                   pf_tag[pf_wp]  <= pf_in_tag;
                   pf_wp          <= pf_wp + 2'd1;
               end
               if (pf_pop) begin
                  eq_data[eq_wp] <= pf_data[pf_rp];
                  eq_tag[eq_wp]  <= pf_head_tag;
                  eq_wp          <= eq_wp + 1'b1;
                  pf_rp          <= pf_rp + 2'd1;
              end
if (ln_pop) begin
    out_q    <= ln_data;
    out_tag  <= ln_tag[2:0];
    out_last <= ln_last;
    out_par  <= ^ln_data;
    out_v    <= 1'b1;
    if (ln_last)
        cnt <= 4'd0;
    else
        cnt <= cnt + 4'd1;
end
if (eq_pop) begin
    ln_data <= eq_data[eq_rp];
    ln_tag  <= eq_head_tag;
    eq_rp   <= eq_rp + 1'b1;
end
if (eq_pop)
    ln_v <= 1'b1;
else if (ln_pop)
    ln_v <= 1'b0;
              case ({eq_push, eq_pop})
                  2'b10:   eq_used <= eq_used + 2'd1;
                  2'b01:   eq_used <= eq_used - 2'd1;
                  default: eq_used <= eq_used;
              endcase
               case ({pf_push, pf_pop})
                   2'b10:   pf_used <= pf_used + 3'd1;
                   2'b01:   pf_used <= pf_used - 3'd1;
                   default: pf_used <= pf_used;
               endcase
            end
        end
    end

    always @(posedge clk)
        if (win && en)
            assert (cnt <= 4'd7);
endmodule

module xbar_route_rom (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         en,
    input  wire         start,
    input  wire         stop,
    output reg  [127:0] out_q,
