    2'd1: bk_stat_o <= {ra_occ_o, rb_occ_o};
    2'd2: bk_stat_o <= {ra_old_o, rb_old_o};
    default: bk_stat_o <= {bk_ferr_v_o, 3'h0, bk_ferr_o, 8'h0, rb_lat_o, ra_lat_o};
