ra_rp      <= 2'd0;
ra_hwm_o   <= 3'd0;
ra_lat_o   <= 8'd0;
ra_perr_o  <= 16'd0;
ra_blk_o   <= 16'd0;
ra_byp_o   <= 16'd0;
ra_fetch_o <= 16'd0;
rb_data[0] <= 128'h0;
rb_data[1] <= 128'h0;
rb_data[2] <= 128'h0;
rb_data[3] <= 128'h0;
rb_tag[0]  <= 4'd0;
rb_tag[1]  <= 4'd0;
rb_tag[2]  <= 4'd0;
rb_tag[3]  <= 4'd0;
rb_ts[0]   <= 8'd0;
rb_ts[1]   <= 8'd0;
rb_ts[2]   <= 8'd0;
rb_ts[3]   <= 8'd0;
rb_par     <= 4'd0;
rb_v       <= 4'd0;
rb_wp      <= 2'd0;
rb_rp      <= 2'd0;
rb_hwm_o   <= 3'd0;
rb_lat_o   <= 8'd0;
rb_perr_o  <= 16'd0;
rb_blk_o   <= 16'd0;
rb_fetch_o <= 16'd0;
bk_coll_o  <= 16'd0;
ra_pop_o   <= 16'd0;
rb_pop_o   <= 16'd0;
ra_occ_o   <= 16'd0;
rb_occ_o   <= 16'd0;
ra_old_o   <= 16'd0;
rb_old_o   <= 16'd0;
bk_ferr_o  <= 4'd0;
bk_ferr_v_o <= 1'b0;
bk_stat_o  <= 32'h0;
pf_ins_o   <= 16'd0;
pf_ret_o   <= 16'd0;
out_tag    <= 3'd0;
out_last   <= 1'b0;
out_par    <= 1'b0;
            win    <= 1'b0;
            rd_ptr <= 3'd0;
            cnt    <= 4'd0;
cnt_pnd <= 1'b0;
            out_q  <= 128'h0;
            out_v  <= 1'b0;
