module token_bucket_pool (
    input  wire       clk,
    input  wire       rst,
    input  wire [5:0] drip_req,
    input  wire [5:0] spend_req,
    output reg  [3:0] pool,
    output wire [5:0] hi_flags,
    output reg        starved
);
    localparam [3:0] TOTAL = 4'd8;

    // per-instance observable state
    wire [2:0] t0, t1, t2, t3, t4, t5;
    wire       h0, h1, h2, h3, h4, h5;

    // a bucket wants a credit only if the drip would really land:
    // not already full, and not cancelled by a concurrent accepted spend
    wire [5:0] want;
    assign want[0] = drip_req[0] && (t0 != 3'd4) && !(spend_req[0] && (t0 != 3'd0));
    assign want[1] = drip_req[1] && (t1 != 3'd4) && !(spend_req[1] && (t1 != 3'd0));
    assign want[2] = drip_req[2] && (t2 != 3'd4) && !(spend_req[2] && (t2 != 3'd0));
    assign want[3] = drip_req[3] && (t3 != 3'd4) && !(spend_req[3] && (t3 != 3'd0));
    assign want[4] = drip_req[4] && (t4 != 3'd4) && !(spend_req[4] && (t4 != 3'd0));
    assign want[5] = drip_req[5] && (t5 != 3'd4) && !(spend_req[5] && (t5 != 3'd0));

    wire credit_avail = (pool != 4'd0);

    // one credit per cycle, fixed priority
    wire [5:0] grant;
    assign grant[0] = credit_avail && want[0];
    assign grant[1] = credit_avail && want[1] && !want[0];
    assign grant[2] = credit_avail && want[2] && !want[0] && !want[1];
    assign grant[3] = credit_avail && want[3] && !want[0] && !want[1] && !want[2];
    assign grant[4] = credit_avail && want[4] && !want[0] && !want[1] && !want[2] && !want[3];
    assign grant[5] = credit_avail && want[5] && !want[0] && !want[1] && !want[2] && !want[3] && !want[4];
    wire grant_any = grant[0] || grant[1] || grant[2] || grant[3] || grant[4] || grant[5];

   // the arbitration result is registered before it reaches the buckets: the
   // credit leaves the pool in the grant cycle, the drip lands the cycle after
   reg  [5:0] grant_q;
   wire       inflight = (grant_q != 6'd0);

   // a bucket may have filled up, or be spending, by the time the staged drip
   // arrives; a drip that cannot land refunds its credit to the pool
   wire [5:0] landed;
   assign landed[0] = grant_q[0] && (t0 != 3'd4) && !(spend_req[0] && (t0 != 3'd0));
   assign landed[1] = grant_q[1] && (t1 != 3'd4) && !(spend_req[1] && (t1 != 3'd0));
   assign landed[2] = grant_q[2] && (t2 != 3'd4) && !(spend_req[2] && (t2 != 3'd0));
   assign landed[3] = grant_q[3] && (t3 != 3'd4) && !(spend_req[3] && (t3 != 3'd0));
   assign landed[4] = grant_q[4] && (t4 != 3'd4) && !(spend_req[4] && (t4 != 3'd0));
   assign landed[5] = grant_q[5] && (t5 != 3'd4) && !(spend_req[5] && (t5 != 3'd0));
   wire landed_any = landed[0] || landed[1] || landed[2] || landed[3] || landed[4] || landed[5];
   wire refund = inflight && !landed_any;

    // a released token returns its credit
    wire [5:0] rel;
   assign rel[0] = spend_req[0] && (t0 != 3'd0) && !(grant_q[0] && (t0 != 3'd4));
   assign rel[1] = spend_req[1] && (t1 != 3'd0) && !(grant_q[1] && (t1 != 3'd4));
   assign rel[2] = spend_req[2] && (t2 != 3'd0) && !(grant_q[2] && (t2 != 3'd4));
   assign rel[3] = spend_req[3] && (t3 != 3'd0) && !(grant_q[3] && (t3 != 3'd4));
   assign rel[4] = spend_req[4] && (t4 != 3'd0) && !(grant_q[4] && (t4 != 3'd4));
   assign rel[5] = spend_req[5] && (t5 != 3'd0) && !(grant_q[5] && (t5 != 3'd4));

    wire [3:0] rel_cnt = {3'd0, rel[0]} + {3'd0, rel[1]} + {3'd0, rel[2]} +
                         {3'd0, rel[3]} + {3'd0, rel[4]} + {3'd0, rel[5]};

   token_bucket u0 (.clk(clk), .rst(rst), .drip(grant_q[0]), .spend(spend_req[0]), .tokens(t0), .tokens_hi(h0));
   token_bucket u1 (.clk(clk), .rst(rst), .drip(grant_q[1]), .spend(spend_req[1]), .tokens(t1), .tokens_hi(h1));
   token_bucket u2 (.clk(clk), .rst(rst), .drip(grant_q[2]), .spend(spend_req[2]), .tokens(t2), .tokens_hi(h2));
   token_bucket u3 (.clk(clk), .rst(rst), .drip(grant_q[3]), .spend(spend_req[3]), .tokens(t3), .tokens_hi(h3));
   token_bucket u4 (.clk(clk), .rst(rst), .drip(grant_q[4]), .spend(spend_req[4]), .tokens(t4), .tokens_hi(h4));
   token_bucket u5 (.clk(clk), .rst(rst), .drip(grant_q[5]), .spend(spend_req[5]), .tokens(t5), .tokens_hi(h5));

    assign hi_flags = {h5, h4, h3, h2, h1, h0};

   initial grant_q = 6'd0;

    initial pool    = TOTAL;
    initial starved = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            pool    <= TOTAL;
           grant_q <= 6'd0;
            starved <= 1'b0;
        end else begin
           grant_q <= grant;
           pool <= pool + rel_cnt + {3'd0, refund} - {3'd0, grant_any};
            if (pool == 4'd0) starved <= 1'b1;
        end
    end

    // when the pool is exhausted all credits sit in the buckets, so at least
    // one bucket must be above its high-water mark
    always @(posedge clk)
        if (pool == 4'd0)
            assert (h0 || h1 || h2 || h3 || h4 || h5);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
    output reg tokens_hi
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module dma_copier (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] rd_data,
    output reg  [3:0] wr_addr,
    output reg  [3:0] remaining,
    output reg  [7:0] wr_data,
    output wire       done
);
    localparam [3:0] TOTAL = 4'd8;

    initial wr_addr   = 4'd0;
    initial remaining = TOTAL;
    initial wr_data   = 8'h00;

    assign done = (remaining == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr   <= 4'd0;
            remaining <= TOTAL;
            wr_data   <= 8'h00;
        end else if (ce && remaining != 4'd0) begin
            wr_addr   <= wr_addr + 4'd1;
            remaining <= remaining - 4'd1;
            wr_data   <= rd_data;
        end
    end

    // P: while the block copy is still in flight, the write pointer must stay
    // inside the destination block (0..7).
    always @(posedge clk)
        if (!done)
            assert (wr_addr <= 4'd7);
endmodule

// Top level: a token-bucket rate limiter feeds a burst queue which drives the
// DMA copier one beat at a time.  The queue holds a whole burst's worth of
// beats plus the source word latched when the burst was granted.
module bucket_dma_top (
    input  wire       clk,
    input  wire       rst,
    input  wire       drip,
    input  wire       run,
    input  wire [7:0] src_data,
    output wire [2:0] tokens,
    output wire       tokens_hi,
    output wire [3:0] wr_addr,
    output wire [3:0] remaining,
    output wire [7:0] wr_data,
    output wire       done,
    output reg  [2:0] pending
);
    reg [7:0] hold;
   reg [7:0] wbeat_d;
   reg       wbeat_v;

    initial pending = 3'd0;
    initial hold    = 8'h00;
   initial wbeat_v = 1'b0;
   initial wbeat_d = 8'h00;

    // One beat leaves the queue per enabled cycle; each beat also spends a
   // token out of the bucket.  A beat is first captured in the write-beat
   // stage and is retired into the copier on the following enabled cycle,
   // so the stage must be free before the queue may issue again.
   wire beat   = run && (pending != 3'd0) && (remaining != 4'd0) && !wbeat_v;
   wire commit = run && wbeat_v;

    // A fresh burst is granted only when the bucket is above its low-water
    // mark, the queue has drained, and the block copy is still in flight.
   wire load = tokens_hi && (pending == 3'd0) && !wbeat_v && (remaining != 4'd0);

    // Grant no more beats than either the bucket or the destination block can
    // support.
    wire [2:0] grant = (remaining < {1'b0, tokens}) ? remaining[2:0] : tokens;

    always @(posedge clk) begin
        if (rst) begin
            pending <= 3'd0;
            hold    <= 8'h00;
           wbeat_v <= 1'b0;
           wbeat_d <= 8'h00;
       end else begin
           if (load) begin
            pending <= grant;
            hold    <= src_data;
           end else if (beat) begin
            pending <= pending - 3'd1;
           end
           // Write-beat pipeline stage: holds the in-flight beat until the
           // copier is enabled again.
           wbeat_v <= beat || (wbeat_v && !commit);
           if (beat) wbeat_d <= hold;
       end
    end

    token_bucket u_bucket (
        .clk       (clk),
        .rst       (rst),
        .drip      (drip),
       .spend     (commit),
        .tokens    (tokens),
        .tokens_hi (tokens_hi)
    );

    dma_copier u_dma (
        .clk       (clk),
        .rst       (rst),
       .ce        (commit),
       .rd_data   (wbeat_d),
        .wr_addr   (wr_addr),
        .remaining (remaining),
        .wr_data   (wr_data),
        .done      (done)
    );

    // Composed property: any beat still sitting in the burst queue must have
    // somewhere left to land in the destination block.
    always @(posedge clk)
        if (pending != 3'd0)
            assert (remaining != 4'd0);
endmodule

module token_bucket (
    input wire clk,
    input wire rst,
    input wire drip,
    input wire spend,
    output reg [2:0] tokens,
output reg tokens_hi,
output reg [3:0] drip_count
);
    wire drip_en  = drip  && (tokens != 3'd4);
    wire spend_en = spend && (tokens != 3'd0);
    wire inc = drip_en && !spend_en;
    wire dec = spend_en && !drip_en;

    initial tokens   = 3'd0;
    initial tokens_hi = 1'b0;
initial drip_count = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens    <= 3'd0;
            tokens_hi <= 1'b0;
drip_count <= 4'd0;
        end else begin
            if (inc)      tokens <= tokens + 3'd1;
            else if (dec) tokens <= tokens - 3'd1;

            if (inc && tokens == 3'd1)      tokens_hi <= 1'b1;
            else if (dec && tokens == 3'd2) tokens_hi <= 1'b0;
if (drip_en && drip_count != 4'd15) drip_count <= drip_count + 4'd1;
        end
    end

    always @(posedge clk)
        if (tokens_hi) assert (tokens != 3'd0);
endmodule

module credit_pool_top (
    input wire clk,
    input wire rst,
    input wire [3:0] req,
    input wire [3:0] rel,
    output reg [3:0] pool,
    output wire [4:0] total_tokens,
output wire [3:0] hi_flags,
output reg [3:0] grant_hist
);
    localparam [3:0] TOTAL = 4'd8;

    wire [2:0] t0, t1, t2, t3;
    wire       h0, h1, h2, h3;
    wire [3:0] dc0, dc1, dc2, dc3;

    reg [1:0] rr_ptr;

    wire want0 = req[0] && (t0 != 3'd4) && !(rel[0] && (t0 != 3'd0));
    wire want1 = req[1] && (t1 != 3'd4) && !(rel[1] && (t1 != 3'd0));
    wire want2 = req[2] && (t2 != 3'd4) && !(rel[2] && (t2 != 3'd0));
    wire want3 = req[3] && (t3 != 3'd4) && !(rel[3] && (t3 != 3'd0));
    wire [3:0] want = {want3, want2, want1, want0};

    wire [1:0] p0 = rr_ptr;
    wire [1:0] p1 = rr_ptr + 2'd1;
    wire [1:0] p2 = rr_ptr + 2'd2;
    wire [1:0] p3 = rr_ptr + 2'd3;

    wire [1:0] sel_idx = want[p0] ? p0 :
                         want[p1] ? p1 :
                         want[p2] ? p2 : p3;

    wire grant_any = (want != 4'd0) && (pool != 4'd0);
    wire grant0 = grant_any && (sel_idx == 2'd0);
    wire grant1 = grant_any && (sel_idx == 2'd1);
    wire grant2 = grant_any && (sel_idx == 2'd2);
    wire grant3 = grant_any && (sel_idx == 2'd3);

    token_bucket u0 (.clk(clk), .rst(rst), .drip(grant0), .spend(rel[0]),
                     .tokens(t0), .tokens_hi(h0), .drip_count(dc0));
    token_bucket u1 (.clk(clk), .rst(rst), .drip(grant1), .spend(rel[1]),
                     .tokens(t1), .tokens_hi(h1), .drip_count(dc1));
    token_bucket u2 (.clk(clk), .rst(rst), .drip(grant2), .spend(rel[2]),
                     .tokens(t2), .tokens_hi(h2), .drip_count(dc2));
    token_bucket u3 (.clk(clk), .rst(rst), .drip(grant3), .spend(rel[3]),
                     .tokens(t3), .tokens_hi(h3), .drip_count(dc3));

    wire dec0 = rel[0] && (t0 != 3'd0) && !grant0;
    wire dec1 = rel[1] && (t1 != 3'd0) && !grant1;
    wire dec2 = rel[2] && (t2 != 3'd0) && !grant2;
    wire dec3 = rel[3] && (t3 != 3'd0) && !grant3;

    wire [2:0] ret = {2'b00, dec0} + {2'b00, dec1} +
                     {2'b00, dec2} + {2'b00, dec3};

    assign total_tokens = {2'b00, t0} + {2'b00, t1} +
                          {2'b00, t2} + {2'b00, t3};
    assign hi_flags = {h3, h2, h1, h0};

    initial pool   = TOTAL;
    initial rr_ptr = 2'd0;
initial grant_hist = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            pool   <= TOTAL;
            rr_ptr <= 2'd0;
grant_hist <= 4'd0;
        end else begin
            pool <= pool - {3'b000, grant_any} + {1'b0, ret};
            if (grant_any) rr_ptr <= sel_idx + 2'd1;
grant_hist <= {grant_hist[2:0], grant_any};
        end
    end

    always @(posedge clk)
        if (pool == 4'd0) assert (h0 || h1 || h2 || h3);
endmodule

// frame preemption controller
// A HOLD control symbol (K-code 0) sent while a frame is in flight suspends
// it so a higher-priority frame can be framed in between; a HOLD sent
// between frames resumes the most recently suspended one. Up to four frames
// can be stacked; o_ready drops when the stack is full and further HOLDs
// inside a frame are refused and counted rather than silently lost.
module fm_preempt_ctl (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [1:0]  i_phase,
    input  wire        i_rd,
    input  wire        i_sof,
    input  wire        i_eof,
    input  wire        i_data_sym,
    input  wire [15:0] i_cur_len,
    output wire        o_suspend,
    output wire        o_resume,
    output wire [9:0]  o_ctl_sym,
    output wire [15:0] o_rest_len,
    output reg  [2:0]  o_depth,
    output wire        o_ready,
    output reg  [15:0] o_preempt_cnt,
    output reg  [15:0] o_resume_cnt,
    output reg  [7:0]  o_refuse_cnt,
    output reg  [11:0] o_max_hold,
    output reg  [7:0]  o_frag_frames,
    output reg  [15:0] o_intr_bytes,
    output reg  [7:0]  o_status
);
    localparam [1:0]  K_HOLD   = 2'd0;
    localparam [1:0]  PH_ALIGN = 2'd1, PH_PKT = 2'd2;
    localparam [2:0]  DEPTH    = 3'd4;
    localparam [11:0] AGE_MAX  = 12'hFFF;
    localparam [3:0]  FRAG_MAX = 4'hF;

    // per-slot context of a suspended frame
    reg [15:0] sv_len  [0:3];
    reg [3:0]  sv_frag [0:3];
    reg [11:0] sv_age  [0:3];
    reg [3:0]  cur_frag;
    reg        full_seen;
    reg        last_was_resume;
    integer i;

    initial begin
        o_depth = 3'd0; o_preempt_cnt = 16'd0; o_resume_cnt = 16'd0; o_refuse_cnt = 8'd0;
        o_max_hold = 12'd0; o_frag_frames = 8'd0; o_intr_bytes = 16'd0; o_status = 8'd0;
        cur_frag = 4'd0; full_seen = 1'b0; last_was_resume = 1'b0;
        for (i = 0; i < 4; i = i + 1) begin
            sv_len[i] = 16'd0; sv_frag[i] = 4'd0; sv_age[i] = 12'd0;
        end
    end

    wire       hold_k   = i_ce && i_k && (i_kcode == K_HOLD);
    wire       full     = (o_depth == DEPTH);
    wire       empty    = (o_depth == 3'd0);
    wire       refused  = hold_k && (i_phase == PH_PKT) && full;
    wire [1:0] push_idx = o_depth[1:0];
    wire [1:0] top_idx  = o_depth[1:0] - 2'd1;
    wire       stale    = !empty && (sv_age[top_idx] == AGE_MAX);
    wire [3:0] frag_nxt = (cur_frag != FRAG_MAX) ? (cur_frag + 4'd1) : cur_frag;

    assign o_ready    = !full;
    assign o_suspend  = hold_k && (i_phase == PH_PKT) && !full;
    assign o_resume   = hold_k && (i_phase == PH_ALIGN) && !empty;
    assign o_rest_len = sv_len[top_idx];
    // K28.0 marks a suspend, K28.4 a resume; both are disparity neutral
    assign o_ctl_sym  = o_suspend ? (i_rd ? 10'b1100001011 : 10'b0011110100)
                                  : (i_rd ? 10'b1100001101 : 10'b0011110010);

    always @(posedge clk) begin
        if (rst) begin
            o_depth <= 3'd0; o_preempt_cnt <= 16'd0; o_resume_cnt <= 16'd0; o_refuse_cnt <= 8'd0;
            o_max_hold <= 12'd0; o_frag_frames <= 8'd0; o_intr_bytes <= 16'd0; o_status <= 8'd0;
            cur_frag <= 4'd0; full_seen <= 1'b0; last_was_resume <= 1'b0;
            for (i = 0; i < 4; i = i + 1) begin
                sv_len[i] <= 16'd0; sv_frag[i] <= 4'd0; sv_age[i] <= 12'd0;
            end
        end else begin
            // slot context: capture on suspend, age while parked
            for (i = 0; i < 4; i = i + 1) begin
                if (o_suspend && (i == push_idx)) begin
                    sv_len[i]  <= i_cur_len;
                    sv_frag[i] <= frag_nxt;
                    sv_age[i]  <= 12'd0;
                end else if (i_ce && (i < o_depth) && (sv_age[i] != AGE_MAX)) begin
                    sv_age[i]  <= sv_age[i] + 12'd1;
                end
            end
            // stack pointer and per-frame fragment tracking
            if (o_suspend) begin
                o_depth         <= o_depth + 3'd1;
                last_was_resume <= 1'b0;
                if (o_depth == DEPTH - 3'd1) full_seen <= 1'b1;
                if (o_preempt_cnt != 16'hFFFF) o_preempt_cnt <= o_preempt_cnt + 16'd1;
            end else if (o_resume) begin
                o_depth         <= o_depth - 3'd1;
                cur_frag        <= sv_frag[top_idx];
                last_was_resume <= 1'b1;
                if (sv_age[top_idx] > o_max_hold) o_max_hold <= sv_age[top_idx];
                if (o_resume_cnt != 16'hFFFF) o_resume_cnt <= o_resume_cnt + 16'd1;
            end else if (i_sof) begin
                cur_frag <= 4'd0;
            end else if (i_eof) begin
                cur_frag <= 4'd0;
                if ((cur_frag != 4'd0) && (o_frag_frames != 8'hFF)) o_frag_frames <= o_frag_frames + 8'd1;
            end
            if (refused && (o_refuse_cnt != 8'hFF)) o_refuse_cnt <= o_refuse_cnt + 8'd1;
            // bytes of other frames sent while at least one frame is parked
            if (i_data_sym && !empty && (o_intr_bytes != 16'hFFFF)) o_intr_bytes <= o_intr_bytes + 16'd1;
            o_status <= {full, empty, stale, last_was_resume, full_seen,
                         (cur_frag != 4'd0), (o_refuse_cnt != 8'd0), (o_intr_bytes != 16'd0)};
        end
    end
endmodule

module fm_link_8b10b_framer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_k,
    input  wire [1:0]  i_kcode,
    input  wire [7:0]  i_data,
    output reg  [9:0]  o_sym,
    output reg         o_rd,
    output reg  [31:0] o_sym_cnt,
output reg  [31:0] o_pkt_cnt,
output reg  [15:0] o_err_cnt,
output reg  [15:0] o_max_len,
output reg         o_wdog,
output reg  [7:0]  o_mon_status,
output wire [2:0]  o_pre_depth,
output wire        o_pre_ready,
output wire [15:0] o_pre_cnt,
output wire [15:0] o_pre_resume_cnt,
output wire [7:0]  o_pre_refuse_cnt,
output wire [11:0] o_pre_max_hold,
output wire [7:0]  o_pre_frag_frames,
output wire [15:0] o_pre_intr_bytes,
output wire [7:0]  o_pre_status
);
    localparam [1:0] K_COMMA = 2'd1, K_SOF = 2'd2, K_EOF = 2'd3;
    localparam [1:0] PH_IDLE = 2'd0, PH_ALIGN = 2'd1, PH_PKT = 2'd2;

    reg [1:0] phase;
    reg seen_comma, seen_start, seen_end;
// link monitor / statistics (debug visibility only)
localparam [11:0] WDOG_LIMIT = 12'd2047;
reg [15:0] idle_cnt;
reg [11:0] wdog_cnt;
reg [15:0] cur_len;
reg [7:0]  rd_hist;
reg [1:0]  last_kcode;
reg        bad_k_seen;

    initial begin
        phase = PH_IDLE; seen_comma = 1'b0; seen_start = 1'b0; seen_end = 1'b0;
        o_sym = 10'd0; o_rd = 1'b0; o_sym_cnt = 32'd0; o_pkt_cnt = 32'd0;
idle_cnt = 16'd0; wdog_cnt = 12'd0; cur_len = 16'd0; rd_hist = 8'd0;
last_kcode = 2'd0; bad_k_seen = 1'b0;
o_err_cnt = 16'd0; o_max_len = 16'd0; o_wdog = 1'b0; o_mon_status = 8'd0;
    end

    function [5:0] enc6;
        input [4:0] x;
        begin
            case (x)
                5'd0:  enc6 = 6'b100111;
                5'd1:  enc6 = 6'b011101;
                5'd2:  enc6 = 6'b101101;
                5'd3:  enc6 = 6'b110001;
                5'd4:  enc6 = 6'b110101;
                5'd5:  enc6 = 6'b101001;
                5'd6:  enc6 = 6'b011001;
                5'd7:  enc6 = 6'b111000;
                5'd8:  enc6 = 6'b111001;
                5'd9:  enc6 = 6'b100101;
                5'd10: enc6 = 6'b010101;
                5'd11: enc6 = 6'b110100;
                5'd12: enc6 = 6'b001101;
                5'd13: enc6 = 6'b101100;
                5'd14: enc6 = 6'b011100;
                5'd15: enc6 = 6'b010111;
                5'd16: enc6 = 6'b011011;
                5'd17: enc6 = 6'b100011;
                5'd18: enc6 = 6'b010011;
                5'd19: enc6 = 6'b110010;
                5'd20: enc6 = 6'b001011;
                5'd21: enc6 = 6'b101010;
                5'd22: enc6 = 6'b011010;
                5'd23: enc6 = 6'b111010;
                5'd24: enc6 = 6'b110011;
                5'd25: enc6 = 6'b100110;
                5'd26: enc6 = 6'b010110;
                5'd27: enc6 = 6'b110110;
                5'd28: enc6 = 6'b001110;
                5'd29: enc6 = 6'b101110;
                5'd30: enc6 = 6'b011110;
                default: enc6 = 6'b101011;
            endcase
        end
    endfunction

    function [3:0] enc4;
        input [2:0] y;
        begin
            case (y)
                3'd0: enc4 = 4'b1011;
                3'd1: enc4 = 4'b1001;
                3'd2: enc4 = 4'b0101;
                3'd3: enc4 = 4'b1100;
                3'd4: enc4 = 4'b1101;
                3'd5: enc4 = 4'b1010;
                3'd6: enc4 = 4'b0110;
                default: enc4 = 4'b1110;
            endcase
        end
    endfunction

    function [2:0] ones6;
        input [5:0] v;
        begin
            ones6 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]} + {2'b00, v[4]} + {2'b00, v[5]};
        end
    endfunction

    function [2:0] ones4;
        input [3:0] v;
        begin
            ones4 = {2'b00, v[0]} + {2'b00, v[1]} + {2'b00, v[2]} + {2'b00, v[3]};
        end
    endfunction

    // 5b/6b sub-block with running-disparity selection
    wire [5:0] c6m    = enc6(i_data[4:0]);
    wire       bal6   = (ones6(c6m) == 3'd3);
    wire       alt6   = !bal6 || (i_data[4:0] == 5'd7);
    wire [5:0] c6     = (alt6 && o_rd) ? ~c6m : c6m;
    wire       rd_mid = bal6 ? o_rd : ~o_rd;
    // 3b/4b sub-block
    wire [3:0] c4m    = enc4(i_data[7:5]);
    wire       bal4   = (ones4(c4m) == 3'd2);
    wire       alt4   = !bal4 || (i_data[7:5] == 3'd3);
    wire [3:0] c4     = (alt4 && rd_mid) ? ~c4m : c4m;
    wire       rd_dat = bal4 ? rd_mid : ~rd_mid;

    // framing sequence: comma (arm) -> start-of-frame (start) -> end-of-frame (finish)
    wire do_comma = i_ce && i_k && (i_kcode == K_COMMA);
    wire do_sof   = i_ce && i_k && (i_kcode == K_SOF) && (phase == PH_ALIGN);
    wire do_eof   = i_ce && i_k && (i_kcode == K_EOF) && (phase == PH_PKT);
    wire do_data  = i_ce && !i_k;
    // frame preemption: K-code 0 (HOLD) suspends / resumes the frame in flight
    wire        pre_suspend, pre_resume;
    wire [9:0]  pre_sym;
    wire [15:0] pre_rest_len;
    wire [2:0]  pre_depth;
    assign o_pre_depth = pre_depth;
    fm_preempt_ctl u_preempt (
        .clk           (clk),
        .rst           (rst),
        .i_ce          (i_ce),
        .i_k           (i_k),
        .i_kcode       (i_kcode),
        .i_phase       (phase),
        .i_rd          (o_rd),
        .i_sof         (do_sof),
        .i_eof         (do_eof),
        .i_data_sym    (do_data),
        .i_cur_len     (cur_len),
        .o_suspend     (pre_suspend),
        .o_resume      (pre_resume),
        .o_ctl_sym     (pre_sym),
        .o_rest_len    (pre_rest_len),
        .o_depth       (pre_depth),
        .o_ready       (o_pre_ready),
        .o_preempt_cnt (o_pre_cnt),
        .o_resume_cnt  (o_pre_resume_cnt),
        .o_refuse_cnt  (o_pre_refuse_cnt),
        .o_max_hold    (o_pre_max_hold),
        .o_frag_frames (o_pre_frag_frames),
        .o_intr_bytes  (o_pre_intr_bytes),
        .o_status      (o_pre_status)
    );
// monitor-side decodes
wire bad_k        = i_ce && i_k && !do_comma && !do_sof && !do_eof && !pre_suspend && !pre_resume;
wire mon_pkt_data = do_data && (phase == PH_PKT);
wire [15:0] len_nxt = cur_len + 16'd1;

    always @(posedge clk) begin
        if (rst) begin
            phase <= PH_IDLE; seen_comma <= 1'b0; seen_start <= 1'b0; seen_end <= 1'b0;
            o_sym <= 10'd0; o_rd <= 1'b0; o_sym_cnt <= 32'd0; o_pkt_cnt <= 32'd0;
idle_cnt <= 16'd0; wdog_cnt <= 12'd0; cur_len <= 16'd0; rd_hist <= 8'd0;
last_kcode <= 2'd0; bad_k_seen <= 1'b0;
o_err_cnt <= 16'd0; o_max_len <= 16'd0; o_wdog <= 1'b0; o_mon_status <= 8'd0;
        end else if (do_comma) begin
            o_sym      <= o_rd ? 10'b1100000101 : 10'b0011111010;
            o_rd       <= ~o_rd;
            seen_comma <= 1'b1;
            if (phase == PH_IDLE) phase <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_sof) begin
            o_sym      <= o_rd ? 10'b0010010111 : 10'b1101101000;
            seen_start <= 1'b1;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_eof) begin
            o_sym      <= o_rd ? 10'b0100010111 : 10'b1011101000;
            seen_end   <= 1'b1;
            phase      <= PH_ALIGN;
            o_pkt_cnt  <= o_pkt_cnt + 32'd1;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (do_data) begin
            o_sym      <= {c6, c4};
            o_rd       <= rd_dat;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (pre_suspend) begin
            o_sym      <= pre_sym;
            phase      <= PH_ALIGN;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end else if (pre_resume) begin
            o_sym      <= pre_sym;
            phase      <= PH_PKT;
            o_sym_cnt  <= o_sym_cnt + 32'd1;
        end
if (!rst) begin
// idle cycle counter (saturating)
if (!i_ce && (idle_cnt != 16'hFFFF)) idle_cnt <= idle_cnt + 16'd1;
// illegal / out-of-sequence control symbol logger
if (bad_k) begin
bad_k_seen <= 1'b1;
if (o_err_cnt != 16'hFFFF) o_err_cnt <= o_err_cnt + 16'd1;
end
if (i_ce && i_k) last_kcode <= i_kcode;
// comma watchdog
if (do_comma) begin
wdog_cnt <= 12'd0;
o_wdog   <= 1'b0;
end else if (wdog_cnt != WDOG_LIMIT) begin
wdog_cnt <= wdog_cnt + 12'd1;
end else begin
o_wdog   <= 1'b1;
end
// packet payload length tracker
if (do_sof) begin
cur_len <= 16'd0;
end else if (pre_resume) begin
cur_len <= pre_rest_len;
end else if (mon_pkt_data && (cur_len != 16'hFFFF)) begin
cur_len <= len_nxt;
if (len_nxt > o_max_len) o_max_len <= len_nxt;
end
// running disparity history
if (i_ce) rd_hist <= {rd_hist[6:0], o_rd};
o_mon_status <= {bad_k_seen, (idle_cnt[15:12] != 4'd0), last_kcode, rd_hist[3:0]};
end
    end

    always @(*) assert (!seen_end || (seen_start && seen_comma));
endmodule

// Doorbell register block for a 32-channel layout-render accelerator.
// A remote agent rings doorbells (sets per-channel pending bits); the local
// agent acknowledges them (clears bits). pend_count mirrors the number of
// outstanding doorbells. busy_q / empty_q are registered status flags that a
// session window (win) observes.
module doorbell_block (
    input  wire        clk,
    input  wire        ce,          // global enable / idle condition
    input  wire        ring,        // remote agent rings a doorbell
    input  wire [4:0]  ring_ch,
    input  wire        ack,         // local agent clears a doorbell
    input  wire [4:0]  ack_ch,
    input  wire        open_sess,   // Q : opens the observation window
    input  wire        close_sess   // R : closes the observation window
);

    reg [31:0] pending    = 32'd0;   // 32 per-channel pending bits
    reg [15:0] pend_count = 16'd0;   // number of outstanding doorbells
    reg        busy_q     = 1'b0;    // registered "something pending"
    reg        empty_q    = 1'b1;    // registered "nothing pending"
    reg        win        = 1'b0;    // session window register
    reg        pv         = 1'b0;    // past-valid

    wire do_set = ce && ring && !pending[ring_ch];
    wire do_clr = ce && !do_set && ack && pending[ack_ch];

    always @(posedge clk)
        pv <= 1'b1;

    // window can be opened and closed repeatedly
    always @(posedge clk) begin
        if (ce) begin
            if (close_sess)     win <= 1'b0;
            else if (open_sess) win <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            if (do_set) begin
                pending[ring_ch] <= 1'b1;
                pend_count       <= pend_count + 16'd1;
            end else if (do_clr) begin
                pending[ack_ch]  <= 1'b0;
                pend_count       <= pend_count - 16'd1;
            end
            // status flags sampled from the current doorbell state
            busy_q  <= (pend_count != 16'd0);
            empty_q <= (pending    == 32'd0);
        end
    end

    // P: inside an open session, the busy flag never rises while the
    //    empty flag is still asserted (the two are never true together).
    always @(posedge clk)
        if (pv && win && $rose(busy_q))
            assert (!empty_q);

endmodule

module bilinear_scaler (
    input  wire        clk,
    input  wire        ce,        // advance the fractional position accumulator
    input  wire        ld_en,     // load a sample into the line buffer
    input  wire [3:0]  ld_addr,
    input  wire [15:0] ld_data,
    input  wire [15:0] phase_step,
    output reg  [15:0] out_pix
);
    // ---- scaler state -------------------------------------------------
    reg [15:0] frac;     // fractional source position
    reg [15:0] fcomp;    // complementary weight, kept as ~frac by construction
    reg [15:0] pa;       // left  neighbour of the line buffer window
    reg [15:0] pb;       // right neighbour of the line buffer window
    reg [15:0] rd_idx;   // line buffer read cursor
    reg [15:0] lbuf [0:15];
    reg        pv;

    integer i;
    initial begin
        frac    = 16'h0000;
        fcomp   = 16'hFFFF;
        pa      = 16'h0000;
        pb      = 16'h0000;
        rd_idx  = 16'h0000;
        out_pix = 16'h0000;
        pv      = 1'b0;
        for (i = 0; i < 16; i = i + 1) lbuf[i] = 16'h0000;
    end

    // ---- fractional position accumulator -------------------------------
    wire [16:0] acc_sum   = {1'b0, frac} + {1'b0, phase_step};
    wire        carry     = acc_sum[16];
    wire [15:0] frac_next = acc_sum[15:0];

    // the complement register drives the neighbour choice of the blender
    wire        pick_a    = fcomp[15];

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ld_en)
            lbuf[ld_addr] <= ld_data;
        if (ce) begin
            frac    <= frac_next;
            fcomp   <= ~frac_next;
            out_pix <= pick_a ? pa : pb;
            if (carry) begin
                pa     <= pb;
                pb     <= lbuf[rd_idx[3:0]];
                rd_idx <= rd_idx + 16'd1;
            end
        end
    end

    // ---- property -------------------------------------------------------
    always @(posedge clk)
        if (pv && $past(ce))
            assert (out_pix == ($past(frac[15]) ? $past(pb) : $past(pa)));
endmodule

module decoded_timeout_tracker (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [2:0]  chan,
    output reg         done,
    output reg  [15:0] total
);
    // outstanding-request state
    reg        busy;
    reg  [2:0] sel;        // latched channel number
    reg  [7:0] onehot;     // latched binary-decoder word
    reg [15:0] timer;      // bounded-response countdown

    // per-channel completion counters: 8 entries, 16 bits each
    reg [15:0] cnt [0:7];
    integer i;

    initial begin
        busy   = 1'b0;
        sel    = 3'd0;
        onehot = 8'd0;
        timer  = 16'd0;
        done   = 1'b0;
        total  = 16'd0;
        for (i = 0; i < 8; i = i + 1) cnt[i] = 16'd0;
    end

    // request acceptance
    wire accept = ce && !busy && start;

    // combinational binary decoder: one of 8 outputs, selected by chan,
    // activated only under the accept enable
    wire [7:0] dec_out = accept ? (8'h01 << chan) : 8'h00;

    // completion is signalled through the latched decode: the countdown
    // tick is fanned out over the eight channel strobes
    wire        expire_tick = ce && busy && (timer == 16'd1);
    wire [7:0]  strobe      = onehot & {8{expire_tick}};
    wire        complete    = |strobe;

    always @(posedge clk) begin
        if (rst) begin
            busy   <= 1'b0;
            sel    <= 3'd0;
            onehot <= 8'd0;
            timer  <= 16'd0;
            done   <= 1'b0;
            total  <= 16'd0;
        end else begin
            if (ce)
                done <= complete;

            if (accept) begin
                busy   <= 1'b1;
                sel    <= chan;
                onehot <= dec_out;
                timer  <= 16'd8;
            end else if (complete) begin
                busy   <= 1'b0;
                timer  <= 16'd0;
            end else if (ce && busy) begin
                timer  <= timer - 16'd1;
            end

            if (complete) begin
                cnt[sel] <= cnt[sel] + 16'd1;
                total    <= total + 16'd1;
            end
        end
    end

    // P1: the countdown never expires while a request is still outstanding
    always @(posedge clk)
        if (busy)
            assert (timer != 16'd0);

    // P2: a completion is always reported through exactly one decoded channel
    always @(posedge clk)
        if (done)
            assert ((onehot != 8'd0) && ((onehot & (onehot - 8'd1)) == 8'd0));
endmodule

// 2x4 block interleaver: symbols written row-wise, read column-wise.
// 8 entries of 64-bit words, 64-bit write and read index counters.
module block_interleaver_ki (
    input  wire        i_clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire [63:0] i_sym,
    output wire [63:0] o_sym,
    output wire        o_valid
);
    // storage: 8 entries, 64-bit symbols
    reg [63:0] mem [0:7];

    // row-wise write index and column-wise read index (64-bit counters)
    reg [63:0] wr_cnt;
    reg [63:0] rd_cnt;

    // 0 = filling the block row-wise, 1 = draining the block column-wise
    reg        phase;

    // per-entry occupancy mask
    reg [7:0]  filled;

    integer idx;
    initial begin
        wr_cnt = 64'd0;
        rd_cnt = 64'd0;
        phase  = 1'b0;
        filled = 8'h00;
        for (idx = 0; idx < 8; idx = idx + 1)
            mem[idx] = 64'd0;
    end

    // row-wise write address
    wire [2:0] wr_addr = wr_cnt[2:0];

    // column-wise read address: k = c*2 + r  ->  addr = r*4 + c
    // which is a one-bit rotation of the 3-bit read index
    wire [2:0] rd_addr = { rd_cnt[0], rd_cnt[2:1] };

    always @(posedge i_clk) begin
        if (i_reset) begin
            wr_cnt <= 64'd0;
            rd_cnt <= 64'd0;
            phase  <= 1'b0;
            filled <= 8'h00;
        end else if (i_ce) begin
            if (phase == 1'b0) begin
                mem[wr_addr]    <= i_sym;
                filled[wr_addr] <= 1'b1;
                if (wr_cnt == 64'd7) begin
                    wr_cnt <= 64'd0;
                    rd_cnt <= 64'd0;
                    phase  <= 1'b1;
                end else begin
                    wr_cnt <= wr_cnt + 64'd1;
                end
            end else begin
                filled[rd_addr] <= 1'b0;
                if (rd_cnt == 64'd7) begin
                    rd_cnt <= 64'd0;
                    wr_cnt <= 64'd0;
                    phase  <= 1'b0;
                end else begin
                    rd_cnt <= rd_cnt + 64'd1;
                end
            end
        end
    end

    assign o_sym   = mem[rd_addr];
    assign o_valid = (phase == 1'b1);

    // P: whenever the interleaver is draining, the entry currently addressed
    // by the column-wise read pointer is an entry that has been written.
    always @(*)
        assert (phase == 1'b0 || filled[rd_addr]);
endmodule

module costas_loop (
    input wire clk,
    input wire rst,
    input wire enable,
    input wire signed [31:0] i_sample,
    input wire signed [31:0] q_sample,
    output reg signed [31:0] phase_error,
    output reg [31:0] occupancy
);
    reg [31:0] valid_samples_stored;
    reg signed [31:0] last_i_sample, last_q_sample;
    reg arm;
    reg pv = 0;
    initial begin
        phase_error = 32'd0;
        last_i_sample = 32'd0;
        last_q_sample = 32'd0;
        occupancy = 32'd0;
        valid_samples_stored = 32'd0;
        arm = 1'b0;
    end

    always @(posedge clk) pv <= 1;

    always @(posedge clk) begin
        if (rst) begin
            phase_error <= 32'd0;
            last_i_sample <= 32'd0;
            last_q_sample <= 32'd0;
            occupancy <= 32'd0;
            valid_samples_stored <= 32'd0;
            arm <= 1'b0;
        end else begin
            if (enable) begin
                phase_error <= i_sample * last_q_sample - q_sample * last_i_sample;
                last_i_sample <= i_sample;
                last_q_sample <= q_sample;
                if (occupancy < 32'd48) begin
                    occupancy <= occupancy + 1;
                    valid_samples_stored <= valid_samples_stored + 1;
                end
            end else begin
                arm <= 1'b1;
            end
        end
    end

    always @(posedge clk) if (pv && arm) assert (occupancy <= 32'd48);
endmodule

module burst_addr_gen (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        req,
    input  wire [63:0] i_base,
    input  wire [63:0] i_beats,
    output wire [63:0] o_addr,
    output wire        o_valid,
    output wire        o_last
);
    localparam [63:0] K = 64'd16;

    reg [63:0] base       = 64'd0;
    reg [63:0] idx        = 64'd0;
    reg [63:0] beats      = 64'd0;
    reg [63:0] beats_left = 64'd0;
    reg        busy       = 1'b0;
    reg        win        = 1'b0;

    assign o_addr  = base + (idx << 3);
    assign o_valid = busy;
    assign o_last  = busy && (idx == beats - 64'd1);

    wire accept = req && !busy && (i_beats >= 64'd1) && (i_beats <= K);

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                base       <= i_base;
                idx        <= 64'd0;
                beats      <= i_beats;
                beats_left <= i_beats;
                busy       <= 1'b1;
                win        <= 1'b1;
            end else if (busy) begin
                idx        <= idx + 64'd1;
                beats_left <= beats_left - 64'd1;
                busy       <= (idx != beats - 64'd1);
            end
        end
    end

    always @(*) begin
        if (win && busy)
            assert (beats_left != 64'd0);
    end
endmodule

module turbo_siso_wintrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       flush,
    input  wire       meas_win,
    input  wire       meas_frame,
    input  wire [7:0] rx_llr,
    output wire [7:0] extrinsic,
    output wire       frame_done
);
    // max-log-MAP recursion state
    reg [7:0] alpha_mem [0:63];
    reg [7:0] beta_reg  [0:1];
    reg [7:0] gamma_mem [0:63];
    reg [7:0] llr_mem   [0:63];
    reg [7:0] ext_mem   [0:63];
    integer i;
    initial begin
        for (i = 0; i < 64; i = i + 1) begin
            alpha_mem[i] = 8'd0;
            beta_reg[i]  = 8'd0;
            gamma_mem[i] = 8'd0;
            llr_mem[i]   = 8'd0;
            ext_mem[i]   = 8'd0;
        end
    end

    reg [7:0] win_cnt = 8'd0;
    reg       sat     = 1'b0;
    reg       armed   = 1'b0;
    reg [7:0] frame   = 8'd0;

    wire [7:0] alpha_prev = alpha_mem[63];
    wire [7:0] beta_next  = beta_reg[1];
    wire [7:0] alpha_sum  = alpha_prev + rx_llr;
    wire [7:0] gamma    = (alpha_sum > beta_next) ? alpha_sum : beta_next;
    wire [7:0] ext_hat  = alpha_sum - beta_next;
    assign extrinsic = ext_hat;
    assign frame_done = (frame == 8'd63);

    always @(posedge clk) begin
        if (rst) begin
            win_cnt <= 8'd0;
            sat     <= 1'b0;
            armed   <= 1'b0;
            frame   <= 8'd0;
        end else if (ce) begin
            if (flush) begin
                win_cnt <= 8'd0;
                sat     <= 1'b0;
                armed   <= 1'b0;
                frame   <= 8'd0;
            end else begin
                frame <= frame + 8'd1;
                if (meas_win) begin
                    if (win_cnt != 8'd200) begin
                        win_cnt <= win_cnt + 8'd1;
                        if (win_cnt == 8'd127)
                            sat <= 1'b1;
                    end
                end
                if (meas_frame)
                    armed <= 1'b1;
                for (i = 0; i < 64; i = i + 1) begin
                    llr_mem[i]   <= rx_llr;
                    gamma_mem[i] <= gamma;
                    ext_mem[i]   <= ext_hat;
                end
                beta_reg[0] <= beta_next;
                beta_reg[1] <= gamma;
                for (i = 0; i < 64; i = i + 1)
                    alpha_mem[i] <= alpha_sum;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (win_cnt <= 8'd200);
endmodule

module ic_cap_unit (
    input  wire        clk,
    input  wire        ce,
    input  wire        arm_ev,
    input  wire        sel_wr,
    input  wire        sel_val,
    input  wire        cap_req,
    input  wire        ext_edge,
    output reg         pending,
    output reg         over,
    output reg  [31:0] cap,
    output reg  [31:0] cd
);
    localparam [31:0] TIMEOUT = 32'd48;

    reg        edge_sel;
    reg        armed;
    reg  [31:0] timer;

    initial begin
        edge_sel = 1'b0;
        armed    = 1'b0;
        pending  = 1'b0;
        over     = 1'b0;
        cap      = 32'd0;
        timer    = 32'd0;
        cd       = 32'd0;
    end

    wire req_acc = !pending && cap_req;
    wire done    = pending && (timer == 32'd47);
    wire edge_det = (edge_sel ? ext_edge : !ext_edge);

    always @(posedge clk) begin
        if (ce) begin
            if (arm_ev)
                armed <= 1'b1;
            if (sel_wr)
                edge_sel <= sel_val;
            if (done) begin
                pending <= 1'b0;
                cd      <= 32'd0;
                if (edge_det)
                    over <= 1'b1;
            end else if (req_acc) begin
                pending <= 1'b1;
                timer   <= 32'd0;
                cd      <= TIMEOUT;
            end else if (pending) begin
                timer <= timer + 32'd1;
                cd    <= cd - 32'd1;
                if (edge_det) begin
                    cap <= timer;
                    over <= 1'b0;
                end
            end
        end
    end

    // after the unit has been armed: countdown never expires while the
    // capture request is still outstanding
    always @(posedge clk)
        if (armed && pending)
            assert (cd != 32'd0);

    // and the free-running timer never wraps while the engine is pending
    always @(posedge clk)
        if (armed && pending)
            assert (timer != 32'hFFFFFFFF);
endmodule

module patfill_engine (
    input  wire        clk,
    input  wire        i_rst,
    input  wire        i_ce,
    input  wire        i_start,
    input  wire [2:0]  i_pat_sel,
    input  wire [63:0] i_dst,
    input  wire [63:0] i_len,
    output wire        o_busy,
    output wire [63:0] o_dst,
    output wire [63:0] o_cnt,
    output wire [63:0] o_fill
);
    localparam [63:0] K = 64'd6;

    reg [63:0] fill_pat = 64'd0;
    reg [63:0] dst      = 64'd0;
    reg [63:0] len      = 64'd0;
    reg [63:0] cnt      = 64'd0;
    reg [2:0]  wptr     = 3'd0;
    reg        busy     = 1'b0;
    reg        armed    = 1'b0;

    wire [63:0] pat_next = (i_pat_sel == 3'd0) ? fill_pat :
                            ((i_pat_sel == 3'd1) ? {fill_pat[62:0], fill_pat[63]} :
                            ((i_pat_sel == 3'd2) ? (fill_pat + 64'd5) :
                            ((i_pat_sel == 3'd3) ? (fill_pat ^ 64'hFFFF_FFFF_FFFF_FFFF) :
                            ((i_pat_sel == 3'd4) ? (fill_pat >> 1) : fill_pat))));

    always @(posedge clk) begin
        if (i_rst) begin
            fill_pat <= 64'd0;
            dst      <= 64'd0;
            len      <= 64'd0;
            cnt      <= 64'd0;
            wptr     <= 3'd0;
            busy     <= 1'b0;
        end else if (i_ce) begin
            if (!busy) begin
                if (i_start && (i_len != 64'd0)) begin
                    fill_pat <= 64'd0;
                    dst      <= i_dst;
                    len      <= (i_len > K) ? K : i_len;
                    cnt      <= (i_len > K) ? K : i_len;
                    wptr     <= 3'd0;
                    busy     <= 1'b1;
                    armed    <= 1'b1;
                end
            end else begin
                fill_pat <= pat_next;
                dst      <= dst + 64'd1;
                len      <= len - 64'd1;
                cnt      <= cnt - 64'd1;
                wptr     <= wptr + 3'd1;
                if ((len - 64'd1) == 64'd0)
                    busy <= 1'b0;
            end
        end
    end

    assign o_busy = busy;
    assign o_dst  = dst;
    assign o_cnt  = cnt;
    assign o_fill = fill_pat;

    always @(posedge clk)
        if (armed && busy)
            assert (cnt != 64'd0);
endmodule

module stitch_demux (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       pkt_valid,
    input  wire       pkt_sof,
    input  wire       pkt_eof,
    input  wire [7:0] pkt_data,
    input  wire [1:0] pkt_dest,
    input  wire       win_open,
    input  wire       win_close,
    output reg        o_pkt_start,
    output reg        o_pkt_end,
    output reg [1:0]  o_route,
    output reg [7:0]  o_data
);
    // stream demux state
    reg [1:0] route;
    reg       in_pkt;
    // chain-precedence bookkeeping inside the observation window
    reg       armed;
    reg       arm_seen;
    reg       start_seen;

    initial begin
        route       = 2'd0;
        in_pkt      = 1'b0;
        armed       = 1'b0;
        arm_seen    = 1'b0;
        start_seen  = 1'b0;
        o_pkt_start = 1'b0;
        o_pkt_end   = 1'b0;
        o_route     = 2'd0;
        o_data      = 8'h00;
    end

    always @(posedge clk) begin
        if (rst) begin
            route       <= 2'd0;
            in_pkt      <= 1'b0;
            armed       <= 1'b0;
            arm_seen    <= 1'b0;
            start_seen  <= 1'b0;
            o_pkt_start <= 1'b0;
            o_pkt_end   <= 1'b0;
            o_route     <= 2'd0;
            o_data      <= 8'h00;
        end else if (ce) begin
            o_pkt_start <= 1'b0;
            o_pkt_end   <= 1'b0;
            if (pkt_valid) begin
                if (pkt_sof) begin
                    route      <= pkt_dest;
                    in_pkt     <= 1'b1;
                    o_pkt_start <= 1'b1;
                    o_route     <= pkt_dest;
                    o_data      <= pkt_data;
                    start_seen  <= 1'b1;
                end else if (pkt_eof) begin
                    in_pkt     <= 1'b0;
                    o_pkt_end  <= 1'b1;
                    o_route    <= route;
                    o_data     <= pkt_data;
                end else if (in_pkt) begin
                    o_route    <= route;
                    o_data     <= pkt_data;
                end
            end
            if (win_open) begin
                armed    <= 1'b1;
                arm_seen <= 1'b1;
            end else if (win_close) begin
                armed    <= 1'b0;
            end
        end
    end

    // Chain precedence inside the observation window: a packet start can only be
    // observed if arm and start-of-packet already happened.
    always @(posedge clk)
        if (armed)
            assert (!o_pkt_start || (arm_seen && start_seen));
endmodule

module arb_book_rebuild (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_pkt_valid,
    input  wire [1:0]  i_pkt_type,
    input  wire [63:0] i_pkt_data,
    output wire [63:0] o_code,
    output wire        o_done
);
    localparam [1:0] P_IDLE = 2'd0, P_ARM = 2'd1, P_RUN = 2'd2, P_DONE = 2'd3;

    reg [1:0]  phase;
    reg        hist_arm;
    reg        hist_start;
    reg [63:0] code;
    reg [63:0] seq_mem [0:31];

    initial phase    = P_IDLE;
    initial hist_arm = 1'b0;
    initial hist_start = 1'b0;
    initial code     = 64'd0;

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1)
            seq_mem[i] = {63'd0, i[1:0]};
    end

    // next-state lookup: price-delta codes of an order-book rebuild walk
    function [63:0] nxt;
        input [63:0] cur;
        begin
            case (cur[1:0])
                2'd0: nxt = 64'h1;
                2'd1: nxt = 64'h2;
                2'd2: nxt = 64'h3;
                default: nxt = 64'h0;
            endcase
        end
    endfunction

    wire [63:0] nxt_code = nxt(code);

    always @(posedge clk) begin
        if (rst) begin
            phase    <= P_IDLE;
            hist_arm <= 1'b0;
            hist_start <= 1'b0;
            code     <= 64'd0;
        end else if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (i_pkt_valid && i_pkt_type == 2'd1) begin
                        phase    <= P_ARM;
                        hist_arm <= 1'b1;
                        code     <= i_pkt_data;
                    end
                end
                P_ARM: begin
                    if (i_pkt_valid && i_pkt_type == 2'd2) begin
                        phase      <= P_RUN;
                        hist_start <= 1'b1;
                    end
                end
                P_RUN: begin
                    if (i_pkt_valid) begin
                        if (i_pkt_type == 2'd3) begin
                            phase <= P_DONE;
                        end else begin
                            code <= nxt_code;
                        end
                    end
                end
                default: begin
                    if (i_pkt_valid && i_pkt_type == 2'd0) begin
                        phase    <= P_IDLE;
                        hist_arm <= 1'b0;
                        hist_start <= 1'b0;
                    end
                end
            endcase
        end
    end

    assign o_code = code;
    assign o_done = (phase == P_DONE);

    // chain precedence: finish is never observed without arm and start
    always @(posedge clk)
        assert (phase != P_DONE || (hist_arm && hist_start));
endmodule

module fetchline_demux (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_flush,
    input  wire [1:0]   i_sel,
    input  wire [127:0] i_word,
    output wire [127:0] o_port0,
    output wire [127:0] o_port1,
    output wire [127:0] o_port2,
    output wire [127:0] o_port3,
    output wire [3:0]   o_occ
);
    // 8-entry store holding fetch lines (operand words) routed by the demux
    reg [127:0] mem [0:7];
    reg [3:0]   wptr  = 4'd0;   // next free entry
    reg [3:0]   occ   = 4'd0;   // number of valid entries
    reg         armed = 1'b0;   // sticky: set at the first store

    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 128'd0;
    end

    wire do_store = i_ce && !i_flush && (occ != 4'd8) && (wptr != 4'd8);

    always @(posedge clk) begin
        if (do_store) begin
            mem[wptr[2:0]] <= i_word;
            wptr          <= wptr + 4'd1;
            occ           <= occ + 4'd1;
            armed         <= 1'b1;
        end else if (i_ce && i_flush) begin
            wptr  <= 4'd0;
            occ   <= 4'd0;
        end
    end

    // demux: route the incoming operand word to one of four output ports
    assign o_port0 = (i_sel == 2'd0) ? i_word : mem[0];
    assign o_port1 = (i_sel == 2'd1) ? i_word : mem[1];
    assign o_port2 = (i_sel == 2'd2) ? i_word : mem[2];
    assign o_port3 = (i_sel == 2'd3) ? i_word : mem[3];

    assign o_occ = occ;

    // after the first store, occupancy never exceeds the 8-entry store depth
    assert property (!armed || (occ <= 4'd8));
endmodule

module pw_measure_unit (
    input  wire         clk,
    input  wire         ce,
    input  wire         arm,
    input  wire         start,
    input  wire         stop,
    input  wire         wave,
    output reg          done,
    output reg [127:0]  high_out,
    output reg [127:0]  per_out
);
    localparam [1:0] S_IDLE = 2'd0, S_ARMED = 2'd1, S_MEAS = 2'd2, S_DONE = 2'd3;

    reg [127:0] cnt       = 128'd0;
    reg [127:0] high_cap  = 128'd0;
    reg [127:0] per_cap   = 128'd0;
    reg [1:0]   st        = S_IDLE;
    reg         seen_arm  = 1'b0;
    reg         seen_start= 1'b0;
    reg         armed     = 1'b0;
    reg         win       = 1'b0;
    reg         prev_wave = 1'b0;

    initial done    = 1'b0;
    initial high_out= 128'd0;
    initial per_out = 128'd0;

    wire edge = ce && (wave != prev_wave);

    always @(posedge clk) begin
        prev_wave <= wave;
        done      <= 1'b0;
        if (ce) begin
            if (stop) begin
                win <= 1'b0;
                armed <= 1'b0;
            end else if (start) begin
                win <= 1'b1;
            end
        end
    end

    always @(posedge clk) begin
        if (ce && st != S_IDLE)
            cnt <= cnt + 128'd1;
    end

    always @(posedge clk) begin
        case (st)
            S_IDLE: begin
                if (arm) begin
                    st       <= S_ARMED;
                    seen_arm <= 1'b1;
                    cnt      <= 128'd0;
                end
            end
            S_ARMED: begin
                if (edge) begin
                    st         <= S_MEAS;
                    seen_start <= 1'b1;
                    high_cap   <= 128'd0;
                    per_cap    <= 128'd0;
                end
            end
            S_MEAS: begin
                if (edge) begin
                    st     <= S_DONE;
                    done   <= 1'b1;
                    high_out <= high_cap;
                    per_out  <= per_cap;
                end else begin
                    if (wave) high_cap <= high_cap + 128'd1;
                    per_cap <= per_cap + 128'd1;
                end
            end
            S_DONE: begin
                if (arm) begin
                    st       <= S_ARMED;
                    seen_arm <= 1'b1;
                    cnt      <= 128'd0;
                end
            end
        endcase
    end

    always @(posedge clk)
        if (win && st == S_DONE)
            assert (seen_start && seen_arm);
endmodule

module ckpt_dirty_ram (
    input wire clk,
    input wire rst,
    input wire en,
    input wire we,
    input wire [6:0] addr,
    input wire [7:0] wdata,
    input wire ckpt,
    input wire rls,
    output wire [7:0] rdata
);
    reg [7:0] mem [0:127];
    reg [15:0] dirty;
    reg [7:0] clean;
    reg win;
    reg pv;
    integer k;
    initial begin
        for (k = 0; k < 128; k = k + 1) mem[k] = 8'd0;
    end
    initial dirty = 16'h0000;
    initial clean = 8'd16;
    initial win = 1'b0;
    initial pv = 1'b0;

    wire [3:0] blk = addr[6:3];

    reg [7:0] dirty_pop;
    integer i;
    always @(*) begin
        dirty_pop = 8'd0;
        for (i = 0; i < 16; i = i + 1)
            dirty_pop = dirty_pop + {7'd0, dirty[i]};
    end

    always @(posedge clk) begin
        if (rst) begin
            dirty <= 16'h0000;
            clean <= 8'd16;
            win <= 1'b0;
        end else if (en) begin
            if (ckpt) begin
                dirty <= 16'h0000;
                clean <= 8'd16;
                win <= 1'b1;
            end else begin
                if (rls) win <= 1'b0;
                if (we) begin
                    dirty[blk] <= 1'b1;
                    if (!dirty[blk] && clean != 8'd0)
                        clean <= clean - 8'd1;
                end
            end
        end
    end

    always @(posedge clk) begin
        if (!rst && en && we && !ckpt)
            mem[addr] <= wdata;
    end

    assign rdata = mem[addr];

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (pv && win && $past(win) && $stable(clean))
            assert ($stable(dirty));
    end
endmodule

module trivium_core (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_load,
    input  wire [79:0] i_key,
    input  wire [79:0] i_iv,
    output wire        o_ks,
    output wire        o_ready
);
    reg [92:0]  a;
    reg [83:0]  b;
    reg [110:0] c;
    reg [63:0]  wcnt;
    reg         busy;
    reg         ready;
    reg         armed;

    initial a = 93'd0;
    initial b = 84'd0;
    initial c = {3'b111, 108'd0};
    initial wcnt = 64'd0;
    initial busy = 1'b1;
    initial ready = 1'b0;
    initial armed = 1'b1;

    wire t1a = a[65] ^ a[92];
    wire t2a = b[68] ^ b[83];
    wire t3a = c[65] ^ c[110];
    wire z   = t1a ^ t2a ^ t3a;
    wire t1  = t1a ^ (a[90] & a[91]) ^ b[77];
    wire t2  = t2a ^ (b[81] & b[82]) ^ c[86];
    wire t3  = t3a ^ (c[108] & c[109]) ^ a[68];

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_load) begin
                a     <= {13'd0, i_key};
                b     <= {4'd0, i_iv};
                c     <= {3'b111, 108'd0};
                wcnt  <= 64'd0;
                busy  <= 1'b1;
                ready <= 1'b0;
                armed <= 1'b0;
            end else begin
                a <= {a[91:0], t3};
                b <= {b[82:0], t1};
                c <= {c[109:0], t2};
                if (busy) begin
                    wcnt <= wcnt + 64'd1;
                    if (wcnt == 64'd1151)
                        busy <= 1'b0;
                end
                ready <= ready | (wcnt >= 64'd1151);
            end
        end
    end

    assign o_ks    = ready & z;
    assign o_ready = ready;

    always @(posedge clk)
        if (armed) assert (!(busy && ready));
endmodule

module rnd_unit_win (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [63:0] trunc_in,
    input  wire [2:0]  grs_in,
    input  wire [1:0]  mode,
    input  wire        sign_in,
    output reg  [63:0] res_q
);
    reg [5:0]  stat_q;
    reg [63:0] log_mem [0:127];
    reg [6:0]  wr_ptr;
    reg [63:0] up_cnt;
    reg [63:0] dn_cnt;

    integer i;
    initial begin
        res_q  = 64'd0;
        stat_q = 6'd0;
        wr_ptr = 7'd0;
        up_cnt = 64'd0;
        dn_cnt = 64'd0;
        for (i = 0; i < 128; i = i + 1) log_mem[i] = 64'd0;
    end

    wire g   = grs_in[2];
    wire r   = grs_in[1];
    wire s   = grs_in[0];
    wire lsb = trunc_in[0];
    wire any_bits = g | r | s;

    reg rup;
    always @(*) begin
        case (mode)
            2'b00:   rup = g & (r | s | lsb);
            2'b01:   rup = 1'b0;
            2'b10:   rup = any_bits & ~sign_in;
            default: rup = any_bits & sign_in;
        endcase
    end

    wire [63:0] res_next = trunc_in + {63'd0, rup};
    wire [64:0] win_sum  = {1'b0, up_cnt} + {1'b0, dn_cnt};

    always @(posedge clk) begin
        if (rst) begin
            res_q  <= 64'd0;
            stat_q <= 6'd0;
            wr_ptr <= 7'd0;
            up_cnt <= 64'd0;
            dn_cnt <= 64'd0;
        end else if (en) begin
            res_q  <= res_next;
            stat_q <= {grs_in, mode, sign_in};
            log_mem[wr_ptr] <= res_next;
            wr_ptr <= wr_ptr + 7'd1;
            if (win_sum == 65'd99) begin
                up_cnt <= 64'd0;
                dn_cnt <= 64'd0;
            end else if (rup) begin
                up_cnt <= up_cnt + 64'd1;
            end else begin
                dn_cnt <= dn_cnt + 64'd1;
            end
        end
    end

    always @(*) assert (up_cnt <= 64'd99);
    always @(*) assert (dn_cnt <= 64'd99);
endmodule

module cnn_act_shreg (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire [1:0] mode,
    input  wire [7:0] din,
    input  wire       flush,
    output wire       out_sat
);
    reg [7:0] win;
    reg [7:0] cnt;
    reg       loaded;
    reg       pristine;
    reg       pv;
    initial win = 8'h00;
    initial cnt = 8'h00;
    initial loaded = 1'b0;
    initial pristine = 1'b1;
    initial pv = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            win      <= 8'h00;
            cnt      <= 8'h00;
            loaded   <= 1'b0;
            pristine <= 1'b1;
        end else if (en) begin
            if (flush) begin
                win      <= 8'h00;
                pristine <= 1'b0;
            end else begin
                case (mode)
                    2'b01: win <= {win[6:0], 1'b0};
                    2'b10: win <= {1'b0, win[7:1]};
                    2'b11: begin
                        win <= din;
                        if (cnt != 8'hFF) cnt <= cnt + 8'h01;
                        if (din != 8'h00) loaded <= 1'b1;
                    end
                    default: win <= win;
                endcase
            end
        end
    end

    assign out_sat = win[7];

    always @(posedge clk)
        if (pv && pristine && $rose(win[7]))
            assert (loaded);
endmodule

