                    cfg_ats_cache_en[tl_cfg_func +: 1] <= tl_cfg_ctl[8];
                    cfg_ari_forward_en[tl_cfg_func +: 1] <= tl_cfg_ctl[7];
                    cfg_atomic_request_en[tl_cfg_func +: 1] <= tl_cfg_ctl[6];
