//#############################################################################
//# Function: Generic counter                                                 #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_counter
  #(parameter N   = 4,       // width of data inputs
    parameter SYN = "TRUE",   // synthesizable
    parameter TYPE = "DEFAULT"// implementation type
    )
   (
    //inputs
    input 	       clk, // clk input
    input 	       in, // input to count
    input 	       en, // enable counter
    input 	       dec,//1=decrement, 0 = increment
    input 	       autowrap, //auto wrap counter
    input 	       load, // load counter
    input [N-1:0]      load_data, // input data to load
    //outputs
    output reg [N-1:0] count, // count value
    output 	       wraparound // wraparound indicator
    );

   wire [N-1:0]	 inb;
   wire [N-1:0]  count_in;

   //Increment decrement option
   assign inb[N-1:0] = dec ? {{(N-1){1'b1}},~in} : {{(N-1){1'b0}},in};
   assign cin        = dec ? 1'b1 : 1'b0;

   // counter
   always @(posedge clk)
     if(load)
       count[N-1:0] <= load_data[N-1:0];
     else if (en & ~(wraparound & ~autowrap))
       count[N-1:0] <= count_in[N-1:0];

   assign wraparound = (dec & en & ~(|count[N-1:0])) |
		       (~dec & en & (&count[N-1:0]));

   // Soft/hard adder
   generate
      if(SYN == "TRUE")  begin
	 assign count_in[N-1:0] =count[N-1:0] + inb[N-1:0];
      end
      else begin
	 asic_add #(.TYPE(TYPE),
		    .N(N))
	 asic_add (// Outputs
		   .sum		(cout_in[N-1:0]),
		   .carry	(),
		   .cout	(),
		   // Inputs
		   .a		(count[N-1:0]),
		   .b		(in_mux[N-1:0]),
		   .k		({(N){1'b0}}),
		   .cin		(cin));
      end
   endgenerate

initial count = {N{1'b0}};
reg past_valid = 1'b0;
// Qualify history after the first enabled or load operation.
// Holding both controls low also holds this monitor unchanged.
always @(posedge clk)
  if (load || en)
    past_valid <= 1'b1;

// If the first operation is an increment, its result is one.
always @(posedge clk)
  if (past_valid && $past(!past_valid && en && !load && !dec && in))
    assert (count == {{(N-1){1'b0}}, 1'b1});
endmodule // oh_counter

//#############################################################################
//# Function: Rising Edge Sampled Register                                    #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_reg1
  #(parameter N    = 1,        // vector width
    parameter SYN  = "TRUE",   // synthesizable (or not)
    parameter TYPE = "DEFAULT" // scell type/size
    )
   ( input          nreset, //async active low reset
     input 	    clk,    // clk
     input 	    en,     // write enable
     input [N-1:0]  in,     // input data
     output [N-1:0] out     // output data (stable/latched when clk=1)
     );

   //TODO: Implement all classes of flip-flops
   generate
      if(SYN == "TRUE") begin
	 reg [N-1:0]      out_reg;
	 always @ (posedge clk or negedge nreset)
	   if(!nreset)
	     out_reg[N-1:0] <= 'b0;
	   else if(en)
	     out_reg[N-1:0] <= in[N-1:0];
	 assign out[N-1:0] = out_reg[N-1:0];
      end
      else begin
	 genvar 	     i;
	 for (i=0;i<N;i=i+1) begin
	    asic_reg1 #(.TYPE(TYPE))
	    asic_reg1  (// Outputs
			.out	(out[i]),
			// Inputs
			.nreset	(nreset),
			.clk	(clk),
			.en	(en),
			.in	(in[i]));
	 end
      end
   endgenerate
initial genblk1.out_reg = {N{1'b0}};
reg pv = 1'b0;
// Conservatively establish past validity only after an enabled write.
always @(posedge clk or negedge nreset)
  if (!nreset)
    pv <= 1'b0;
  else if (en)
    pv <= 1'b1;

// Immediately before the first enabled write, storage was still zero.
always @(posedge clk)
  if (pv)
    assert ($past(pv) || ($past(out) == {N{1'b0}}));
endmodule

//#############################################################################
//# Function: One hot N:1 MUX                                                 #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_mux
  #(parameter N   = 32,        // vector width
    parameter M   = 2,         // number of vectors
    parameter SYN  = "TRUE",    // synthesizable (or not)
    parameter TYPE = "DEFAULT"  // implementation type
    )
   (
    input [M-1:0]   sel, // select vector
    input [M*N-1:0] in,  // concatenated input {..,in1[N-1:0],in0[N-1:0]
    output [N-1:0]  out  // output
    );

   generate
      if(SYN == "TRUE") begin
	 reg [N-1:0]     mux;
	 integer 	 i;
	 always @*
	   begin
	      mux[N-1:0] = 'b0;
	      for(i=0;i<M;i=i+1)
		mux[N-1:0] = mux[N-1:0] | {(N){sel[i]}} & in[((i+1)*N-1)-:N];
	   end
	 assign out[N-1:0] = mux[N-1:0];
      end
      else begin
	 //TODO: implement
	 asic_mux #(.TYPE(TYPE),
		    .N(N))
	 asic_mux(.out	(out),
		  .sel  (sel[N-1:0]),
		  .in	(in[N-1:0]));
      end
   endgenerate
endmodule
//#############################################################################
//# Function: Parametrized register file                                      #
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_regfile
  # (parameter REGS  = 4,          // number of registeres
     parameter RW    = 4,         // register width
     parameter RP    = 5,          // read ports
     parameter WP    = 3,          // write prots
     parameter RAW   = $clog2(REGS)// (derived) rf addr width
     )
   (//Control inputs
    input 	       clk,
    // Write Ports (concatenated)
    input [WP-1:0]     wr_valid, // write access
    input [WP*RAW-1:0] wr_addr, // register address
    input [WP*RW-1:0]  wr_data, // write data
    // Read Ports (concatenated)
    input [RP-1:0]     rd_valid, // read access
    input [RP*RAW-1:0] rd_addr, // register address
    output [RP*RW-1:0] rd_data // output data
    );


   reg [RW-1:0]        mem[0:REGS-1];
   wire [WP-1:0]       write_en [0:REGS-1];
   wire [RW-1:0]       datamux [0:REGS-1];

   genvar 	       i,j;

   //TODO: Make an array of cells

   //#########################################
   // write ports
   //#########################################

   //One hote write enables
   for(i=0;i<REGS;i=i+1)
     begin: gen_regwrite
	for(j=0;j<WP;j=j+1)
	  begin: gen_wp
	     assign write_en[i][j] = wr_valid[j] & (wr_addr[j*RAW+:RAW] == i);
	  end
     end

   //Multi Write-Port Mux
   for(i=0;i<REGS;i=i+1)
     begin: gen_wrmux
	oh_mux #(.N(RW), .M(WP))
	iwrmux(.out (datamux[i][RW-1:0]),
	       .sel (write_en[i][WP-1:0]),
	       .in  (wr_data[WP*RW-1:0]));
     end

   //Memory Array Write
   for(i=0;i<REGS;i=i+1)
     begin: gen_reg
	always @ (posedge clk)
	  if (|write_en[i][WP-1:0])
	    mem[i] <= datamux[i];
end


   //#########################################
   // read ports
   //#########################################

   for (i=0;i<RP;i=i+1) begin: gen_rdport
      assign rd_data[i*RW+:RW] = {(RW){rd_valid[i]}} &
				mem[rd_addr[i*RAW+:RAW]];
   end

integer init_idx;
initial begin
  for (init_idx = 0; init_idx < REGS; init_idx = init_idx + 1)
    mem[init_idx] = {RW{1'b0}};
end
// Past-valid becomes true after the first write-enabled clock.
reg pv = 1'b0;
always @(posedge clk)
  if (|wr_valid)
    pv <= 1'b1;

// Immediately after the first write-enabled clock, an unwritten
// word zero must still contain its initialized value.
always @(posedge clk)
  if (pv)
    assert ($past(pv) || $past(|write_en[0]) ||
            (mem[0] == {RW{1'b0}}));
endmodule // oh_regfile

 //#############################################################################
//# Function: RAM (Single Port)
//#############################################################################
//# Author:   Andreas Olofsson                                                #
//# License:  MIT (see LICENSE file in OH! repository)                        #
//#############################################################################

module oh_ram
  #(parameter N       = 4,           // FIFO width
    parameter DEPTH   = 4,           // FIFO depth
    parameter REG     = 1,            // Register fifo output
    parameter SYN     = "TRUE",       // hard (macro) or soft (rtl)
    parameter TYPE    = "DEFAULT",    // pass through variable for hard macro
    parameter SHAPE   = "SQUARE",     // hard macro shape (square, tall, wide)
    parameter AW      = $clog2(DEPTH) // rd_count width (derived)
    )
   (// Memory interface (dual port)
    input 	   clk, //write clock
    input 	   en, //write enable
    input [N-1:0]  wem, //per bit write enable
    input [AW-1:0] addr,//write address
    input [N-1:0]  din, //write data
    output [N-1:0] dout,//read output data
    // BIST interface
    input 	   bist_en, // bist enable
    input 	   bist_we, // write enable global signal
    input [N-1:0]  bist_wem, // write enable vector
    input [AW-1:0] bist_addr, // address
    input [N-1:0]  bist_din, // data input
    // Power/repair (hard macro only)
    input 	   shutdown, // shutdown signal
    input 	   vss, // ground signal
    input 	   vdd, // memory array power
    input 	   vddio, // periphery/io power
    input [7:0]    memconfig, // generic memory config
    input [7:0]    memrepair // repair vector
    );

   generate

      if(SYN == "TRUE") begin: rtl
	 // Generic RTL RAM
	 reg [N-1:0] 	   ram    [0:DEPTH-1];
	 wire [N-1:0] 	   rdata;
	 integer 	   i;

	 //write port
	 always @(posedge clk)
	   for (i=0;i<N;i=i+1)
	     if (en & wem[i])
               ram[addr[AW-1:0]][i] <= din[i];

	 //read port
	 assign rdata[N-1:0] = ram[addr[AW-1:0]];

	 //configurable output register
	 reg [N-1:0] 	     rd_reg;
	 always @ (posedge clk)
	   if(en)
	     rd_reg[N-1:0] <= rdata[N-1:0];

	 //Drive output from register or RAM directly
	 assign dout[N-1:0] = (REG==1) ? rd_reg[N-1:0] : rdata[N-1:0];

      end // block: rtl
      else begin: hard
	 // Hard macro ASIC RAM
	 asic_memory_sp #(.N(N),
			  .DEPTH(DEPTH),
			  .SHAPE(SHAPE),
			  .REG(REG))
	 asic_memory_sp ();
      end // block: hard
   endgenerate
genvar f_init_addr;
generate
  for (f_init_addr = 0; f_init_addr < DEPTH; f_init_addr = f_init_addr + 1) begin : f_initialize_ram
    initial rtl.ram[f_init_addr] = {N{1'b0}};
  end
endgenerate
initial begin
  rtl.rd_reg = {N{1'b0}};
  rtl.i = N;
end
wire [(N*DEPTH)-1:0] f_ram_flat;
genvar f_observe_addr;
generate
  for (f_observe_addr = 0; f_observe_addr < DEPTH; f_observe_addr = f_observe_addr + 1) begin : f_observe_ram
    assign f_ram_flat[f_observe_addr*N +: N] = rtl.ram[f_observe_addr];
  end
endgenerate

reg f_enabled_pv = 1'b0;
always @(posedge clk)
  if (en)
    f_enabled_pv <= 1'b1;

// The first enabled access reads the initially zero memory,
// including when that access simultaneously writes it.
always @(posedge clk)
  if (f_enabled_pv)
    assert (!$past(en && !f_enabled_pv) || (dout == {N{1'b0}}));
endmodule // oh_memory_dp

