    GNU General Public License for more details.

    You should have received a copy of the GNU General Public License
    along with this program.  If not, see <https://www.gnu.org/licenses/>.
*/
`timescale 1ns / 1ps
/*
    SPI master
    - 3/4-wire mode support (4-wire by default)
    - configurable flexible divider coefficient
    Note that it is mainly targeting the STMicro LIS3DH sensor SPI protocol.
    In particular:
    - SPI clock polarity/phase
    - 3-wire mode (ie: tristate window)
    Maybe there are some specifics that should/could be reworked to make it more general..

    Divider coefficient (10000 by default when parameter DIV_COEF==0) can be changed:
    - set nbits=5'd0
    - set mosi_data[31:16]=16'h8080    `set divcoef as mosi_data[15:0]`
    - set mosi_data[15:0]=divider      (eg: 16'h4e20 (20000))
    - set request=1
    - then after some clocks:
     - set request=0

    Define `SPI3WIRE to implement 3-wire mode support. Must then be enabled (see below) to switch the SPI master to 3-wire mode.
    (SPI slave must also be set to 3-wire by some means accordingly of course)
    To enable the 3-wire mode (or disable it to standard/default 4-wire mode):
    - set nbits=5'd0
    - then either:
     - set mosi_data[31:0]=16'h81010000 `set 3-wire on`
    - or:
     - set mosi_data[31:0]=16'h81000000 `set 3-wire off (default 4-wire)`
    - set request=1
    - then after some clocks:
     - set request=0
*/
module spi_master #( parameter integer DIV_COEF = 4) (
    input               clk_in,         // Logic clock
    input               nrst,           // SPI is active when nreset is HIGH

    input               request,        // Request to start transfer: Active HIGH
    input   [4:0]       nbits,          // Number of bits (nbits=15 => 16; nbits=0 is reserved)
    input  [31:0]       mosi_data,      // Parallel FPGA data write to SPI
    output [31:0]       miso_data,      // Parallel FPGA data read from SPI
    output              ready,          // Active HIGH when transfer has finished

    output              spi_csn,        // SPI CSN output (active LOW)
    output              spi_sck,        // SPI clock output
    inout               spi_mosi,       // SPI master output slave input (default 4-wire); or m/s i/o (3-wire enabled)
    input               spi_miso        // SPI master data input, slave data output
);
`ifdef SPI_DIV_COEF
    localparam div_coef_ = `SPI_DIV_COEF;
`else
    localparam div_coef_ = (DIV_COEF == 0) ? 16'd10000 : DIV_COEF - 1;
`endif

    localparam
        STATE_Idle = 0,
        STATE_Run = 1,
        STATE_High = 2,
        STATE_Low = 3,
        STATE_Finish = 4,
        STATE_End = 5,
        STATE_Config = 6;
    reg [2:0] state = STATE_Idle;
    reg csnff = 1;
    reg sckff = 1;
    reg mosiff = 1;
    reg readyff = 0;
    reg [31:0] mosi_reg = 0;
    reg [31:0] miso_reg = 0;
    reg [4:0] nbits_reg = 0;
    reg [4:0] bit_counter = 0;
    reg oe = 1'b0;
    reg rd = 1'b0;
`ifdef SPI3WIRE
    reg spi3w = 1'b0;
    reg rd_tri = 1'b0;
//    assign spi_mosi = spi3w ? (oe ? mosiff : 1'bz) : mosiff;
    assign spi_mosi = !oe || (spi3w && rd_tri) ? 1'bz : mosiff;
//    assign spi_mosi = !oe ? 1'bz : mosiff;
`else
    reg rd_tri = 0;             // should remove
    reg spi3w = 0;              // should remove
    assign spi_mosi = oe ? mosiff : 1'bz;
`endif
    assign ready = readyff;
    assign miso_data = miso_reg;
    assign spi_csn = oe ? csnff : 1'bz;
    assign spi_sck = oe ? sckff : 1'bz;

    // Frequency divider
    reg divider_out = 0;
    reg [15:0] divider = 0;
    reg [15:0] div_coef = div_coef_;
    reg configure = 0;
    always @(posedge clk_in) begin
        if (!nrst || configure) begin
            divider <= 0;
            divider_out <= 0;
            if (nrst && configure) begin
                div_coef <= (nbits == 5'd0) && (mosi_data[31] && mosi_data[23]) ? mosi_data[15:0] : div_coef;
            end
        end else begin
            if (divider <= div_coef) begin
                divider <= divider + 16'd1;
                divider_out <= 0;
            end else begin
                divider <= 0;
                divider_out <= 1;
            end
        end
    end

    always @(posedge clk_in) begin
        if (!nrst) begin
`ifdef SPI3WIRE
            rd_tri <= 0;
`endif
            oe <= 0;
            rd <= 0;
            csnff <= 1;
            sckff <= 1;
            mosiff <= 1;
            readyff <= 0;
            mosi_reg <= 0;
            miso_reg <= 0;
            nbits_reg <= 0;
            bit_counter <= 0;
            state <= STATE_Idle;
        end else begin
            case (state)
                STATE_Idle: begin
                    configure <= 0;
                    if (request) begin
                        if (nbits == 5'd0) begin
`ifdef SPI3WIRE
                            spi3w <= (nbits == 5'd0) && (mosi_data[31] && mosi_data[24]) ? mosi_data[16] : spi3w;
`endif
                            configure <= 1;     // give divider process a chance to configure for one clock
                        end else begin
                            oe <= 1;
                            mosi_reg <= mosi_data;
                            nbits_reg <= nbits;
                            bit_counter <= nbits;
                            csnff <= 0;
                            readyff <= 0;
                            state <= STATE_Run;
                        end
                    end
                end
                STATE_Run: begin
                    if (nbits_reg == 5'd31) begin
                        rd <= mosi_reg[31];
                        state <= STATE_High;
                    end else begin
                        mosi_reg <= mosi_reg << 1;
                        nbits_reg <= nbits_reg + 5'd1;
                    end
                end
                STATE_High: if (divider_out) begin
                    sckff <= 0;
                    mosiff <= mosi_reg[31];
                    state <= STATE_Low;
`ifdef SPI3WIRE
                        if (bit_counter == (nbits - 5'd8)) begin
                            if (spi3w && rd) begin
                                rd_tri <= 1;
                            end
                        end
`endif
                end
                STATE_Low: if (divider_out) begin
                    sckff <= 1;
`ifdef SPI3WIRE
                    miso_reg <= {miso_reg[30:0], spi3w ? spi_mosi : rd ? spi_miso : 1'b0};
`else
                    miso_reg <= {miso_reg[30:0], spi_miso};
`endif
                    if (bit_counter == 5'd0) begin
                        state <= STATE_Finish;
                    end else begin
`ifdef SPI3WIRE_
                        if (bit_counter == (nbits - 5'd8)) begin
                            if (spi3w && rd) begin
                                rd_tri <= 1;
                            end
                        end
`endif
                        bit_counter <= bit_counter - 5'd1;
                        mosi_reg <= mosi_reg << 1;
                        state <= STATE_High;
                    end
                end
                STATE_Finish: if (divider_out) begin
                    csnff <= 1;
                    state <= STATE_End;
                end
                STATE_End: if (divider_out) begin
                    readyff <= 1;
                    rd <= 0;
                    oe <= 0;
`ifdef SPI3WIRE
                    rd_tri <= 0;
`endif
                    state <= STATE_Idle;
                end
            endcase
        end
    end
always @(posedge clk_in) assert ((div_coef != 16'd0) || (sckff == (state != STATE_Low)));
endmodule

module wdog_bounded (
    input  wire clk,
    input  wire rst,     // synchronous reset
    input  wire ce,      // timebase enable: when low the whole watchdog idles
    input  wire kick,    // software pets the dog
    output wire o_bark,  // timeout reached, reset request to the host
    output wire o_armed
);
    // The watchdog counts timebase ticks since the last kick.  When it reaches
    // LIMIT it latches the bark flag and freezes; only a kick (or reset)
    // restarts it.  Note the freeze is decided by the latched flag, not by a
    // fresh comparison against LIMIT.
    parameter [4:0] LIMIT = 5'd20;

    reg [4:0] wdt;
    reg       expired;
    reg       armed;   // sticky: set the first time the dog is ever kicked

    initial wdt     = 5'd0;
    initial expired = 1'b0;
    initial armed   = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            wdt     <= 5'd0;
            expired <= 1'b0;
            armed   <= 1'b0;
        end else if (ce) begin
            if (kick) begin
                wdt     <= 5'd0;
                expired <= 1'b0;
                armed   <= 1'b1;
            end else if (!expired) begin
                wdt <= wdt + 5'd1;
                if ((wdt + 5'd1) == LIMIT)
                    expired <= 1'b1;
            end
        end
    end

    assign o_bark  = expired;
    assign o_armed = armed;

    // Property: once the watchdog has been armed by a first kick, the elapsed
    // tick count never exceeds the programmed timeout, even though the counter
    // is five bits wide and could hold up to 31.
    always @(*)
        if (armed)
            assert (wdt <= LIMIT);

endmodule

// Four-phase req/ack handshake engine with a busy mirror and
// per-client ownership / response routing tags.
//
//   phase 0 : idle            (req=0, ack=0)
//   phase 1 : req asserted    (req=1, ack=0)
//   phase 2 : ack observed    (req=1, ack=1)
//   phase 3 : req withdrawn   (req=0, ack=1)  -> waits for ack to drop
//
// busy is a separate register that mirrors "phase != 0"; the start path is
// gated on !busy only, exactly as a real controller would do.
module fourphase_owner (
    input  wire clk,
    input  wire i_ce,        // idle condition: nothing moves when low
    input  wire i_req,       // a client wants the channel
    input  wire i_sel,       // which client (0 -> A, 1 -> B)
    input  wire i_ack_in,    // ack wire coming back from the target
    output wire o_busy,
    output wire o_req,
    output wire o_ack
);

    reg [1:0] phase;
    reg       busy;
    reg       req;
    reg       ack;
    reg       own_a, own_b;   // who currently owns the channel
    reg       resp_a, resp_b; // where the response will be routed
    reg       virgin;         // high until the first handshake ever completes

    initial phase  = 2'd0;
    initial busy   = 1'b0;
    initial req    = 1'b0;
    initial ack    = 1'b0;
    initial own_a  = 1'b0;
    initial own_b  = 1'b0;
    initial resp_a = 1'b0;
    initial resp_b = 1'b0;
    initial virgin = 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!busy) begin
                // channel believed free: latch the owner and drive req
                if (i_req) begin
                    phase <= 2'd1;
                    req   <= 1'b1;
                    busy  <= 1'b1;
                    if (i_sel)
                        own_b <= 1'b1;
                    else
                        own_a <= 1'b1;
                end
            end else begin
                case (phase)
                    2'd1: if (i_ack_in) begin
                              // ack rose: snapshot the response route
                              phase  <= 2'd2;
                              ack    <= 1'b1;
                              resp_a <= own_a;
                              resp_b <= own_b;
                          end
                    2'd2: begin
                              // req may only drop now that ack is high
                              phase <= 2'd3;
                              req   <= 1'b0;
                          end
                    2'd3: if (!i_ack_in) begin
                              phase  <= 2'd0;
                              ack    <= 1'b0;
                              busy   <= 1'b0;
                              own_a  <= 1'b0;
                              own_b  <= 1'b0;
                              resp_a <= 1'b0;
                              resp_b <= 1'b0;
                              virgin <= 1'b0;   // first completion disarms
                          end
                    default: ;
                endcase
            end
        end
    end

    assign o_busy = busy;
    assign o_req  = req;
    assign o_ack  = ack;

    // Before the first handshake has ever completed, there must never be two
    // owners at once, and never two response routes at once.
    always @(posedge clk)
        if (virgin) assert (!(own_a && own_b));

    always @(posedge clk)
        if (virgin) assert (!(resp_a && resp_b));

endmodule

module split_total_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [5:0] up,
    output reg  [5:0] down,
    output reg  [5:0] maxv
);
    // The workload of TOTAL units is split between a rising share (up) and a
    // remaining share (down); one enable moves exactly one unit across, so the
    // two counters always sum to TOTAL.  maxv tracks the larger of the shares.
    localparam [5:0] TOTAL = 6'd20;

    initial begin
        up   = 6'd0;
        down = TOTAL;
        maxv = TOTAL;
    end

    wire do_step = step && (down != 6'd0);

    wire [5:0] nxt_up   = up   + 6'd1;
    wire [5:0] nxt_down = down - 6'd1;
    wire [5:0] nxt_max  = (nxt_up > nxt_down) ? nxt_up : nxt_down;

    always @(posedge clk) begin
        if (rst) begin
            up   <= 6'd0;
            down <= TOTAL;
            maxv <= TOTAL;
        end else if (do_step) begin
            up   <= nxt_up;
            down <= nxt_down;
            maxv <= nxt_max;
        end
    end

    // P: the larger share can never drop below half of the total.
    always @(*)
        assert (maxv >= 6'd10);
endmodule

// Input-pin debouncer for a core's external interrupt/reset pin.
// A change on the raw pin must be seen on K=4 consecutive enabled samples
// before the clean output flips.  A countdown register tracks the deadline
// of the outstanding change request.
module pin_debounce_deadline (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // sample enable; low => full idle
    input  wire       raw,     // raw asynchronous pin value (already synced)
    output reg        clean,   // debounced value
    output reg        req      // a pin change is currently outstanding
);
    localparam [2:0] K = 3'd4;

    reg [2:0] stab;  // number of consecutive samples disagreeing with clean
    reg [2:0] cnt;   // countdown to the guaranteed flip deadline

    initial begin
        clean = 1'b0;
        stab  = 3'd0;
        cnt   = K;
        req   = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            clean <= 1'b0;
            stab  <= 3'd0;
            cnt   <= K;
            req   <= 1'b0;
        end else if (ce) begin
            if (raw != clean) begin
                if (stab == K - 3'd1) begin
                    // final identical sample: commit the flip, retire request
                    clean <= ~clean;
                    stab  <= 3'd0;
                    cnt   <= K;
                    req   <= 1'b0;
                end else begin
                    stab  <= stab + 3'd1;
                    cnt   <= cnt - 3'd1;
                    req   <= 1'b1;
                end
            end else begin
                // sample agrees with the clean value: abandon the request
                stab  <= 3'd0;
                cnt   <= K;
                req   <= 1'b0;
            end
        end
    end

    // Bounded response (safety form): the deadline countdown must never reach
    // zero while a pin-change request is still outstanding.
    always @(posedge clk)
        assert (!req || cnt != 3'd0);
endmodule

// Transaction scoreboard with a completion deadline countdown.
// issued/retired are wrapping transaction counters; outst is the occupancy
// of the issue window (WINDOW deep). Every outstanding transaction is forced
// to retire before its RELOAD-cycle deadline countdown reaches zero.
module scoreboard_deadline (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes the scoreboard
    input  wire issue,
    input  wire retire,
    output wire busy
);
    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;

    reg [3:0] issued;
    reg [3:0] retired;
    reg [2:0] outst;    // outstanding transactions = issued - retired
    reg [2:0] timer;    // deadline countdown for the oldest outstanding item
    reg       armed;    // sticky: set the first time a transaction is accepted
    reg       pv;       // past valid

    initial begin
        issued  = 4'd0;
        retired = 4'd0;
        outst   = 3'd0;
        timer   = 3'd0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    assign busy = (outst != 3'd0);

    // deadline flag: the countdown has run out
    wire expired = (timer == 3'd0);

    // the design completes a transaction itself when the deadline is imminent
    wire force_ret = (outst != 3'd0) && (timer == 3'd1);

    wire do_issue  = ce && issue && (outst < WINDOW);
    wire do_retire = ce && (outst != 3'd0) && (retire || force_ret);

    wire [2:0] outst_n = do_issue ? (do_retire ? outst : outst + 3'd1)
                                  : (do_retire ? outst - 3'd1 : outst);

    always @(posedge clk) begin
        pv <= 1'b1;

        if (do_issue) begin
            armed  <= 1'b1;
            issued <= issued + 4'd1;
        end

        if (do_retire)
            retired <= retired + 4'd1;

        outst <= outst_n;

        if (do_issue || do_retire) begin
            // any scoreboard event restarts (or clears) the deadline
            if (outst_n == 3'd0) timer <= 3'd0;
            else                 timer <= RELOAD;
        end else if (ce && (outst != 3'd0)) begin
            timer <= timer - 3'd1;
        end
    end

    // Bounded response, safety form, in no-change style, scoped after arming:
    // once a transaction has been accepted, whenever the outstanding count did
    // not change and work is still outstanding, the deadline flag must not
    // change either (i.e. the countdown cannot expire under an outstanding
    // request).
    always @(posedge clk) begin
        if (pv && armed && (outst != 3'd0) && $stable(outst))
            assert ($stable(expired));
    end
endmodule

module arb_lock_pending (
    input  wire       clk,
    input  wire       ce,      // global enable / idle when low
    input  wire [3:0] req,     // new requests, latched into pend
    input  wire       rel,     // current owner releases the lock
    output wire [3:0] grant,
    output wire [2:0] occupancy
);
    // pending request bitmap and its redundant occupancy counter
    reg [3:0] pend  = 4'b0000;
    reg [2:0] pcnt  = 3'd0;
    // fixed-priority arbiter with a lock bit freezing the winner
    reg       lock  = 1'b0;
    reg [1:0] owner = 2'd0;
    reg       pv    = 1'b0;   // past-valid

    // fixed priority: lowest index wins
    wire [1:0] pick = pend[0] ? 2'd0 :
                      pend[1] ? 2'd1 :
                      pend[2] ? 2'd2 : 2'd3;
    wire       any  = |pend;

    // service completion: the locked owner releases, its pending bit retires
    wire       do_clr   = ce && lock && rel;
    wire [3:0] clr_mask = do_clr ? (4'b0001 << owner) : 4'b0000;
    // only genuinely new requests are inserted
    wire [3:0] set_mask = ce ? (req & ~pend & ~clr_mask) : 4'b0000;
    wire [2:0] nset     = set_mask[0] + set_mask[1] + set_mask[2] + set_mask[3];

    assign grant     = lock ? (4'b0001 << owner) : 4'b0000;
    assign occupancy = pcnt;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            pend <= (pend | set_mask) & ~clr_mask;
            pcnt <= pcnt + nset - (do_clr ? 3'd1 : 3'd0);
            if (lock) begin
                if (rel)
                    lock <= 1'b0;      // frozen winner until it releases
            end else if (any) begin
                lock  <= 1'b1;
                owner <= pick;
            end
        end
    end

    // P: if the pending bitmap did not change, the occupancy must not have
    // changed either, and the occupancy stays within its real bound of 4.
    always @(posedge clk)
        if (pv && $stable(pend))
            assert ($stable(pcnt) && (pcnt <= 3'd4));
endmodule

module triage_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    output reg  [3:0] grant,
    output reg        locked,
    output reg  [1:0] owner
);
    // Fixed-priority select: channel 0 (escalate) highest, 3 (archive) lowest.
    reg [1:0] sel_idx;
    reg [3:0] sel_oh;

    always @(*) begin
        casez (req)
            4'b???1: begin sel_idx = 2'd0; sel_oh = 4'b0001; end
            4'b??10: begin sel_idx = 2'd1; sel_oh = 4'b0010; end
            4'b?100: begin sel_idx = 2'd2; sel_oh = 4'b0100; end
            4'b1000: begin sel_idx = 2'd3; sel_oh = 4'b1000; end
            default: begin sel_idx = 2'd0; sel_oh = 4'b0000; end
        endcase
    end

    initial begin
        grant  = 4'b0000;
        locked = 1'b0;
        owner  = 2'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            grant  <= 4'b0000;
            locked <= 1'b0;
            owner  <= 2'd0;
        end else if (ce) begin
            if (!locked) begin
                // idle: hand the bus to the highest-priority requester and lock
                if (|req) begin
                    grant  <= sel_oh;
                    owner  <= sel_idx;
                    locked <= 1'b1;
                end
            end else begin
                // locked: grant bits survive only while their request persists,
                // and the lock is released when the owner drops its request
                grant  <= grant & req;
                locked <= req[owner];
            end
        end
    end

    // P: whenever the arbiter is locked, somebody actually holds the bus.
    always @(*) assert (!locked || grant != 4'b0000);
endmodule

module credit_pool (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // step enable: low leaves all state unchanged
    input  wire i_take,    // 1 = take a credit, 0 = give one back
    output wire o_full,
    output wire o_empty,
    output wire [3:0] o_used,
    output wire [3:0] o_avail
);
    localparam [3:0] CAP = 4'd12;

    // up counter: credits handed out
    reg [3:0] used;
    // down counter: credits still on the shelf
    reg [3:0] avail;

    initial used  = 4'd0;
    initial avail = CAP;

    wire take_fire = i_ce &&  i_take && (used != CAP);
    wire give_fire = i_ce && !i_take && (used != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            used  <= 4'd0;
            avail <= CAP;
        end else if (take_fire) begin
            used  <= used  + 4'd1;   // stepped up
            avail <= avail - 4'd1;   // stepped down, same enable
        end else if (give_fire) begin
            used  <= used  - 4'd1;
            avail <= avail + 4'd1;
        end
    end

    assign o_full  = (avail == 4'd0);
    assign o_empty = (used  == 4'd0);
    assign o_used  = used;
    assign o_avail = avail;

    // P: whenever the shelf is empty, every credit of the pool is out on loan
    always @(posedge clk)
        if (avail == 4'd0)
            assert (used == CAP);
endmodule

module rr_chain_arb (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [1:0] stage
);
    // round-robin arbiter state
    reg [1:0] last_gnt;
    // chain-precedence bookkeeping: arm (line0) -> start (line1) -> finish (line2)
    reg       seen_arm;
    reg       seen_start;
    // sticky scope register: set the first time any grant is issued
    reg       armed;

    initial begin
        last_gnt   = 2'd3;
        gnt        = 4'b0000;
        stage      = 2'd0;
        seen_arm   = 1'b0;
        seen_start = 1'b0;
        armed      = 1'b0;
    end

    // combinational round-robin grant: one-hot, never on a non-requesting line
    reg [3:0] gnt_c;
    always @(*) begin
        case (last_gnt)
            2'd0: gnt_c = req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 : 4'b0000;
            2'd1: gnt_c = req[2] ? 4'b0100 :
                          req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 : 4'b0000;
            2'd2: gnt_c = req[3] ? 4'b1000 :
                          req[0] ? 4'b0001 :
                          req[1] ? 4'b0010 :
                          req[2] ? 4'b0100 : 4'b0000;
            default: gnt_c = req[0] ? 4'b0001 :
                             req[1] ? 4'b0010 :
                             req[2] ? 4'b0100 :
                             req[3] ? 4'b1000 : 4'b0000;
        endcase
    end

    wire [1:0] gnt_idx = gnt_c[0] ? 2'd0 :
                         gnt_c[1] ? 2'd1 :
                         gnt_c[2] ? 2'd2 : 2'd3;

    wire fire = i_ce && (gnt_c != 4'b0000);

    always @(posedge clk) begin
        gnt <= fire ? gnt_c : 4'b0000;
        if (fire) begin
            last_gnt <= gnt_idx;
            armed    <= 1'b1;
            case (stage)
                2'd0: begin
                    if (gnt_c[0]) begin
                        stage    <= 2'd1;   // ARM step
                        seen_arm <= 1'b1;
                    end
                end
                2'd1: begin
                    if (gnt_c[1]) begin
                        stage      <= 2'd2; // START step
                        seen_start <= 1'b1;
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                2'd2: begin
                    if (gnt_c[2]) begin
                        stage <= 2'd3;      // FINISH step
                    end else if (gnt_c[3]) begin
                        stage      <= 2'd0; // abort line
                        seen_arm   <= 1'b0;
                        seen_start <= 1'b0;
                    end
                end
                default: begin
                    stage      <= 2'd0;     // retire transaction
                    seen_arm   <= 1'b0;
                    seen_start <= 1'b0;
                end
            endcase
        end
    end

    // P: once the arbiter has ever granted (sticky armed), a finished
    // transaction can only be observed if arm and start really happened.
    always @(posedge clk)
        if (armed && stage == 2'd3)
            assert (seen_arm && seen_start);
endmodule

module gray_deadline_tracker (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       req,       // request pulse
    output wire [3:0] o_gray,
    output wire [3:0] o_bin,
    output wire [3:0] o_timer,
    output wire       o_busy,
    output wire       o_on_time
);
    // ---- gray counter with its binary shadow -------------------------
    reg [3:0] bin;
    reg [3:0] gray;

    // ---- bounded-response deadline machinery -------------------------
    reg [3:0] timer;      // countdown for the outstanding request
    reg       busy;       // request outstanding
    reg [3:0] goal_gray;  // gray code the counter should show at completion
    reg       armed;      // sticky: set the first time a request is seen

    reg       pv;         // past valid

    localparam [3:0] K = 4'd8;   // response bound

    initial begin
        bin       = 4'd0;
        gray      = 4'd0;
        timer     = 4'd0;
        busy      = 1'b0;
        goal_gray = 4'd0;
        armed     = 1'b0;
        pv        = 1'b0;
    end

    wire [3:0] bin_nxt  = bin + 4'd1;
    wire [3:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);

    wire [3:0] goal_bin = bin + K;

    wire accept = i_ce && armed && req && !busy;
    wire tick   = i_ce && busy;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            // gray counter advances together with its binary shadow
            bin  <= bin_nxt;
            gray <= gray_nxt;

            // sticky arm: first request ever seen arms the monitor forever
            if (req) armed <= 1'b1;

            if (accept) begin
                busy      <= 1'b1;
                timer     <= K;
                goal_gray <= goal_bin ^ (goal_bin >> 1);
            end else if (busy) begin
                if (timer == 4'd1) begin
                    // completion lands exactly on the deadline tick
                    busy  <= 1'b0;
                    timer <= 4'd0;
                end else begin
                    timer <= timer - 4'd1;
                end
            end
        end
    end

    assign o_gray    = gray;
    assign o_bin     = bin;
    assign o_timer   = timer;
    assign o_busy    = busy;
    assign o_on_time = busy && (gray == goal_gray);

    // P: after the monitor is armed, while a request is outstanding the
    // deadline countdown may only move when the gray counter moves --
    // it can never silently run down toward expiry.
    always @(posedge clk)
        if (pv && armed && busy && $stable(gray))
            assert ($stable(timer));
endmodule

module token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: nothing moves when low
    input  wire       req,
    output reg        grant_q,
    output reg [3:0]  tokens
);
    localparam [3:0] BURST  = 4'd12; // bucket cap
    localparam [3:0] REFILL = 4'd3;  // tokens added per timer tick
    localparam [2:0] PERIOD = 3'd4;  // refill timer top

    reg [2:0] timer;
    reg       saw_refill;            // shadow: a refill tick has occurred

    wire       tick     = (timer == PERIOD);
    wire       do_grant = ce && req && (tokens != 4'd0);
    wire [4:0] sum      = {1'b0, tokens} + {1'b0, REFILL};
    wire [3:0] refilled = (sum > {1'b0, BURST}) ? BURST : sum[3:0];

    initial begin
        timer      = 3'd0;
        tokens     = 4'd0;
        saw_refill = 1'b0;
        grant_q    = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            timer      <= 3'd0;
            tokens     <= 4'd0;
            saw_refill <= 1'b0;
            grant_q    <= 1'b0;
        end else if (ce) begin
            timer   <= tick ? 3'd0 : (timer + 3'd1);
            grant_q <= do_grant;

            if (tick)
                saw_refill <= 1'b1;

            case ({tick, do_grant})
                2'b10:   tokens <= refilled;
                2'b01:   tokens <= tokens - 4'd1;
                2'b11:   tokens <= (refilled == 4'd0) ? 4'd0 : (refilled - 4'd1);
                default: tokens <= tokens;
            endcase
        end
    end

    // Precedence: a registered grant can only be observed if a refill tick
    // was recorded earlier in the shadow bit.
    always @(posedge clk)
        if (grant_q)
            assert (saw_refill);

endmodule

module npu_psum_lane (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,      // lane enable / idle when low
    input  wire        i_req,     // new accumulation request
    input  wire [7:0]  i_a,
    input  wire [7:0]  i_b,
    output reg  [19:0] o_psum,
    output reg         o_done
);
    // a full psum accumulation takes exactly MAX MAC steps
    localparam [3:0] MAX = 4'd12;

    // saturating up-counter: clamps at 12 although 4 bits admit 15
    reg [3:0] acc_cnt = 4'd0;
    // countdown that guarantees completion of an accepted request
    reg [4:0] ttl     = 5'd0;
    reg       busy    = 1'b0;

    initial o_psum = 20'd0;
    initial o_done = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            acc_cnt <= 4'd0;
            ttl     <= 5'd0;
            busy    <= 1'b0;
            o_psum  <= 20'd0;
            o_done  <= 1'b0;
        end else if (i_ce) begin
            o_done <= 1'b0;
            if (!busy) begin
                if (i_req) begin
                    busy    <= 1'b1;
                    acc_cnt <= 4'd0;
                    ttl     <= 5'd13;   // MAX + 1 cycles of slack
                    o_psum  <= 20'd0;
                end
            end else begin
                o_psum  <= o_psum + (i_a * i_b);
                acc_cnt <= (acc_cnt == MAX) ? MAX : acc_cnt + 4'd1;
                ttl     <= ttl - 5'd1;
                if ((acc_cnt + 4'd1) == MAX) begin
                    busy   <= 1'b0;
                    o_done <= 1'b1;
                end
            end
        end
    end

    // Bounded response, safety form: the completion countdown must never
    // expire while an accepted accumulation request is still outstanding.
    assert property (!busy || ttl != 5'd0);

endmodule

// Debounced external halt request line for a small RISC-V core.
// The raw request must be seen identical for K = 4 consecutive enabled
// samples before the clean (core-visible) halt request is allowed to flip.
module halt_debounce (
    input  wire clk,
    input  wire i_ce,          // sample enable; low => whole design idles
    input  wire i_raw_halt,    // noisy external halt request
    output wire o_halt_req,    // debounced request presented to the core
    output wire o_stable
);
    // ---------------- state ----------------
    reg [1:0] cnt      = 2'd0; // consecutive-identical-sample counter (0..3)
    reg       cand     = 1'b0; // candidate (last raw sample) value
    reg       stable_f = 1'b0; // set once the candidate has been stable K-1 times
    reg       clean    = 1'b0; // debounced output

    reg       pv       = 1'b0; // past-valid

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_raw_halt != cand) begin
                // glitch: restart the stability measurement
                cand     <= i_raw_halt;
                cnt      <= 2'd0;
                stable_f <= 1'b0;
            end else begin
                // another identical sample; counter saturates at K-1
                if (cnt != 2'd3)
                    cnt <= cnt + 2'd1;
                if (cnt == 2'd2)
                    stable_f <= 1'b1;
                // only a candidate already marked stable may drive the output
                if (stable_f)
                    clean <= cand;
            end
        end
    end

    assign o_halt_req = clean;
    assign o_stable   = stable_f;

    // Property: the debounced output may only have changed on the previous
    // edge if the stability counter was saturated at K-1 at that time.
    always @(posedge clk)
        if (pv && (clean != $past(clean)))
            assert ($past(cnt) == 2'd3);
endmodule

module elastic_two_entry (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_push,
    input  wire       i_pop,
    input  wire [7:0] i_data,
    output wire       o_valid,
    output wire       o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);

    // ---- two-entry elastic buffer -------------------------------------
    // one valid flag per slot, plus head/tail slot selectors.
    reg        v0, v1;      // slot occupancy flags
    reg        head, tail;  // which slot is read / written next
    reg [7:0]  d0, d1;      // slot payloads
    reg [2:0]  count;       // redundant occupancy counter

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial head  = 1'b0;
    initial tail  = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;

    // status is derived from the FLAGS, not from the counter
    assign o_full  = v0 && v1;
    assign o_valid = v0 || v1;
    assign o_data  = head ? d1 : d0;
    assign o_count = count;

    wire do_push = i_push && !o_full;
    wire do_pop  = i_pop  &&  o_valid;

    // idle condition: i_push == 0 && i_pop == 0 leaves all state alone
    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            head  <= 1'b0;
            tail  <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
        end else begin
            if (do_push) begin
                if (tail == 1'b0) begin
                    v0 <= 1'b1;
                    d0 <= i_data;
                end else begin
                    v1 <= 1'b1;
                    d1 <= i_data;
                end
                tail <= ~tail;
            end

            if (do_pop) begin
                if (head == 1'b0)
                    v0 <= 1'b0;
                else
                    v1 <= 1'b0;
                head <= ~head;
            end

            count <= count + (do_push ? 3'd1 : 3'd0)
                            - (do_pop  ? 3'd1 : 3'd0);
        end
    end

    // ---- property: while the buffer holds anything, the occupancy
    //      counter never exceeds the two-entry depth (the register is
    //      three bits wide, so 3..7 are representable).
    always @(posedge i_clk)
        if (o_valid)
            assert (count <= 3'd2);

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       issue,
    output wire       done,
    output wire [2:0] occupancy
);
    // fixed-latency (4 stage) in-flight shift register
    reg [3:0] pipe       = 4'b0000;
    // occupancy counter: issue increments, stage-3 drain decrements
    reg [2:0] occ        = 3'd0;
    // shadow register: records that an issue has already happened
    reg       seen_issue = 1'b0;
    reg       pv         = 1'b0;

    assign done      = ce && pipe[3];
    assign occupancy = occ;

    always @(posedge clk) begin
        if (rst) begin
            pipe       <= 4'b0000;
            occ        <= 3'd0;
            seen_issue <= 1'b0;
        end else if (ce) begin
            pipe <= {pipe[2:0], issue};
            occ  <= occ + (issue ? 3'd1 : 3'd0) - (pipe[3] ? 3'd1 : 3'd0);
            if (issue)
                seen_issue <= 1'b1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: a retire observed last cycle must have been preceded by an issue
    always @(posedge clk)
        if (pv)
            assert (!($past(ce) && $past(pipe[3])) || $past(seen_issue));
endmodule

module gray_quantum_counter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // scheduler quantum tick enable
    output wire [3:0] o_gray,
    output wire [2:0] o_ones
);
    // Ten quantum slots (0..9). The binary shadow does the arithmetic,
    // the gray register is what leaves the clock domain. Terminal count is
    // detected on the gray word, as the CDC-facing logic sees it.
    localparam [3:0] GRAY_LAST = 4'b1101; // gray code of 4'd9

    reg [3:0] bin  = 4'd0;
    reg [3:0] gray = 4'b0000;

    wire       wrap    = (gray == GRAY_LAST);
    wire [3:0] bin_nxt = wrap ? 4'd0 : (bin + 4'd1);

    // occupancy of the gray word: how many lanes are asserted this slot
    wire [2:0] ones = {2'b00, gray[0]} + {2'b00, gray[1]} +
                      {2'b00, gray[2]} + {2'b00, gray[3]};
    wire       occ_hi = (ones >= 3'd3);

    assign o_gray = gray;
    assign o_ones = ones;

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'd0;
            gray <= 4'b0000;
        end else if (i_ce) begin
            bin  <= bin_nxt;
            gray <= bin_nxt ^ (bin_nxt >> 1);
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Bounded existence: the gray word never carries four asserted lanes,
    // so whenever the high-occupancy flag rises it rises to exactly three.
    always @(posedge clk)
        if (pv && $rose(occ_hi))
            assert (ones == 3'd3);
endmodule

module fifo_burst_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] wdata,
    output wire       full,
    output wire       empty,
    output reg  [7:0] rdata
);
    // ---------------- state ----------------
    reg [2:0] wptr  = 3'd0;   // write pointer
    reg [2:0] rptr  = 3'd0;   // read pointer
    reg [3:0] count = 4'd0;   // occupancy
    reg       armed = 1'b0;   // window: set when the FIFO fills, cleared when it drains
    reg [7:0] mem [0:7];

    initial rdata = 8'h00;

    assign full  = (count == 4'd8);
    assign empty = (count == 4'd0);

    wire do_push = push && !full;
    wire do_pop  = pop  && !empty;

    wire [3:0] nxt_count = count + (do_push ? 4'd1 : 4'd0) - (do_pop ? 4'd1 : 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            wptr  <= 3'd0;
            rptr  <= 3'd0;
            count <= 4'd0;
            armed <= 1'b0;
            rdata <= 8'h00;
        end else begin
            if (do_push) begin
                mem[wptr] <= wdata;
                wptr      <= wptr + 3'd1;
            end
            if (do_pop) begin
                rdata <= mem[rptr];
                rptr  <= rptr + 3'd1;
            end
            count <= nxt_count;
            // window register: opened by a full condition, closed by a drain to empty
            if (nxt_count == 4'd0)
                armed <= 1'b0;
            else if (nxt_count == 4'd8)
                armed <= 1'b1;
        end
    end

    // ---------------- properties ----------------
    // Inside the burst window (armed), the pointers must agree with the occupancy.
    always @(posedge clk) begin
        if (armed && count == 4'd1)
            assert (wptr == ((rptr + 3'd1) & 3'd7));
        if (armed && count == 4'd8)
            assert (wptr == rptr);
    end
endmodule

// DRC check engine: each accepted board-check job walks a saturating
// step counter up to MAXSTEP while a completion countdown runs down.
module drc_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       start,     // new check job requested
    output reg        busy,      // request outstanding
    output reg [3:0]  progress,  // saturating up-counter, clamps at MAXSTEP
    output reg [3:0]  deadline,  // completion countdown
    output reg        armed,     // sticky: a job has been accepted at least once
    output reg        done
);
    localparam [3:0] MAXSTEP = 4'd10;

    initial begin
        busy     = 1'b0;
        progress = 4'd0;
        deadline = 4'd0;
        armed    = 1'b0;
        done     = 1'b0;
    end

    wire accept   = i_ce && start && !busy;
    wire step     = i_ce && busy;
    wire last     = (progress + 4'd1 >= MAXSTEP);

    always @(posedge clk) begin
        if (rst) begin
            busy     <= 1'b0;
            progress <= 4'd0;
            deadline <= 4'd0;
            armed    <= 1'b0;
            done     <= 1'b0;
        end else if (accept) begin
            busy     <= 1'b1;
            progress <= 4'd0;
            deadline <= MAXSTEP;
            armed    <= 1'b1;   // sticky once set, never cleared except by rst
            done     <= 1'b0;
        end else if (step) begin
            // saturating up-counter: clamps at MAXSTEP, never reaches 4'd15
            progress <= (progress == MAXSTEP) ? MAXSTEP : progress + 4'd1;
            deadline <= (deadline == 4'd0)    ? 4'd0    : deadline - 4'd1;
            if (last) begin
                busy <= 1'b0;
                done <= 1'b1;
            end
        end
    end

    // P: while the engine has ever been armed and a check is outstanding,
    // the completion countdown must not have expired.
    always @(*)
        if (armed && busy)
            assert (deadline != 4'd0);
endmodule

// Tracks UART frames in flight through a fixed-latency 4-stage serializer.
// Each issued frame is marked in a shift register; it retires 4 cycles later.
// occ is an independently maintained occupancy counter.
module uart_inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // baud tick / pipeline advance enable
    input  wire       i_issue,   // a new frame is handed to the serializer
    output wire       o_idle,    // tracker says: nothing outstanding
    output wire       o_inflight,// serializer stages say: something outstanding
    output wire       o_retire,  // a frame leaves the last stage this tick
    output wire [2:0] o_count
);

    reg [3:0] pipe;  // one mark per occupied serializer stage
    reg [2:0] occ;   // running occupancy count

    initial pipe = 4'b0000;
    initial occ  = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            pipe <= 4'b0000;
            occ  <= 3'd0;
        end else if (i_ce) begin
            pipe <= {pipe[2:0], i_issue};
            occ  <= occ + (i_issue ? 3'd1 : 3'd0) - (pipe[3] ? 3'd1 : 3'd0);
        end
    end

    assign o_idle     = (occ == 3'd0);
    assign o_inflight = |pipe;
    assign o_retire   = i_ce && pipe[3];
    assign o_count    = occ;

    // P: the tracker can never claim idle while a stage still holds a frame.
    always @(*)
        assert (!(o_idle && o_inflight));

endmodule

module uart_rx_onehot (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // baud tick / enable: low freezes all state
    input  wire       rx,
    input  wire       take,    // consumer accepts the byte parked in STOP
    output wire [7:0] o_data,
    output wire       o_ferr,
    output wire       o_busy
);
    // one-hot phase FSM:
    //   st[0]      IDLE
    //   st[1]      START bit
    //   st[2..9]   data bits D0..D7 (one state per bit)
    //   st[10]     STOP bit / byte parked
    reg [10:0] st;
    reg [3:0]  nbits;   // frame phase index: 0..10 only, though 4 bits hold 15
    reg [7:0]  sr;
    reg        ferr;
    reg        pv;

    initial st    = 11'b000_0000_0001;
    initial nbits = 4'd0;
    initial sr    = 8'h00;
    initial ferr  = 1'b0;
    initial pv    = 1'b0;

    wire idle   = st[0];
    wire startb = st[1];
    wire datab  = |st[9:2];
    wire stopb  = st[10];

    wire start_det = ce && idle   && !rx;   // falling edge of the line
    wire adv       = ce && (startb || datab);
    wire done      = ce && stopb  && take;

    // next-state decode: every source bit drives exactly one destination bit
    reg [10:0] nxt;
    always @(*) begin
        nxt      = 11'd0;
        nxt[0]   = (st[0] && rx) || (st[10] && take);
        nxt[1]   = st[0] && !rx;
        nxt[2]   = st[1];
        nxt[3]   = st[2];
        nxt[4]   = st[3];
        nxt[5]   = st[4];
        nxt[6]   = st[5];
        nxt[7]   = st[6];
        nxt[8]   = st[7];
        nxt[9]   = st[8];
        nxt[10]  = st[9] || (st[10] && !take);
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            st    <= 11'b000_0000_0001;
            nbits <= 4'd0;
            sr    <= 8'h00;
            ferr  <= 1'b0;
        end else if (ce) begin
            st <= nxt;
            if (start_det)     nbits <= 4'd1;   // load: start bit is phase 1
            else if (done)     nbits <= 4'd0;
            else if (adv)      nbits <= nbits + 4'd1;
            if (datab)         sr    <= {rx, sr[7:1]};
            if (done)          ferr  <= !rx;    // stop bit must be high
        end
    end

    assign o_data = sr;
    assign o_ferr = ferr;
    assign o_busy = !idle;

    // P: the phase counter changes on every phase change, and it never counts
    // past the 10 phases of a frame -- stated as a no-change check.
    always @(posedge clk)
        if (pv && $stable(nbits))
            assert ($stable(st) && nbits <= 4'd10);
endmodule

module wdog_gray_mon (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,      // idle condition: all state frozen when low
    input  wire i_arm,     // Q: opens the monitoring window
    input  wire i_ack,     // R: closes the monitoring window
    output wire o_bite,
    output wire o_grace,
    output wire o_sys_reset
);
    // ---- timer domain: free running gray coded tick pointer -------------
    reg [2:0] cnt;   // binary tick counter
    reg [2:0] g;     // registered gray code of cnt

    // ---- monitor domain: two flop synchronizer on the gray pointer ------
    reg [2:0] s1, s2;

    // ---- window / latched reset ----------------------------------------
    reg armed;
    reg rst_latch;

    initial cnt       = 3'd0;
    initial g         = 3'd0;
    initial s1        = 3'd0;
    initial s2        = 3'd0;
    initial armed     = 1'b0;
    initial rst_latch = 1'b0;

    wire [2:0] nxt = cnt + 3'd1;

    always @(posedge i_clk)
        if (i_rst) begin
            cnt <= 3'd0;
            g   <= 3'd0;
        end else if (i_ce) begin
            cnt <= nxt;
            g   <= nxt ^ (nxt >> 1);
        end

    always @(posedge i_clk)
        if (i_rst) begin
            s1 <= 3'd0;
            s2 <= 3'd0;
        end else if (i_ce) begin
            s1 <= g;    // first flop: freshly captured pointer
            s2 <= s1;   // second flop: stable pointer sample
        end

    // gray -> binary decode of both synchronizer stages
    wire [2:0] mon = { s2[2], s2[2]^s2[1], s2[2]^s2[1]^s2[0] };
    wire [2:0] pre = { s1[2], s1[2]^s1[1], s1[2]^s1[1]^s1[0] };

    // terminal count seen on the stable sample -> watchdog bites
    assign o_bite  = (mon == 3'd7);
    // deep inside the grace region on the freshly captured sample
    assign o_grace = (pre == 3'd2);

    assign o_sys_reset = rst_latch;

    always @(posedge i_clk)
        if (i_rst) begin
            armed     <= 1'b0;
            rst_latch <= 1'b0;
        end else if (i_ce) begin
            if (i_ack)      armed <= 1'b0;
            else if (i_arm) armed <= 1'b1;

            if (i_ack)                     rst_latch <= 1'b0;
            else if (armed && o_bite)      rst_latch <= 1'b1;
        end

    // P: inside the monitoring window the bite and grace indications are
    // never asserted together.
    always @(posedge i_clk)
        if (armed)
            assert (!(o_bite && o_grace));
endmodule

module pdk_reqtrack (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire       i_arm,     // Q event: arms the tracker (sticky)
    input  wire       i_launch,  // start step: issue a request into the array
    output wire       o_retire,  // finish step: request leaves last stage
    output wire [2:0] o_inflight
);
    parameter STAGES = 4;

    // shift register tracking in-flight requests through the stage array
    reg [STAGES-1:0] pipe;
    // separate count of set bits in that shift register
    reg [2:0]        cnt;
    // sticky arm register (scope): set the first time i_arm is seen, never cleared
    reg              armed;
    // sticky record that a start actually happened after arming
    reg              started;

    initial pipe    = {STAGES{1'b0}};
    initial cnt     = 3'd0;
    initial armed   = 1'b0;
    initial started = 1'b0;

    // a launch is only accepted once the tracker has been armed
    wire accept = i_ce && i_launch && armed;
    wire retire = i_ce && pipe[STAGES-1];

    assign o_retire   = retire;
    assign o_inflight = cnt;

    always @(posedge clk) begin
        if (rst) begin
            pipe    <= {STAGES{1'b0}};
            cnt     <= 3'd0;
            armed   <= 1'b0;
            started <= 1'b0;
        end else if (i_ce) begin
            pipe    <= { pipe[STAGES-2:0], (i_launch && armed) };
            cnt     <= cnt + ((i_launch && armed) ? 3'd1 : 3'd0)
                           - (pipe[STAGES-1]    ? 3'd1 : 3'd0);
            armed   <= armed || i_arm;
            started <= started || (i_launch && armed);
        end
    end

    // Chain precedence, after the sticky arm: while armed, the tracker can never
    // report outstanding work unless a start was really accepted first.
    always @(posedge clk)
        if (armed && (cnt != 3'd0))
            assert (started);

endmodule

module lfsr_precedence (
    input  wire       clk,
    input  wire       step,      // enable: when low, all state is frozen
    output wire       out_bit,
    output wire [3:0] state_o
);
    // 4-bit maximal-length LFSR, polynomial x^4 + x^3 + 1.
    // Seeded nonzero, so the all-zeros lockup state is never entered.
    reg [3:0] lfsr    = 4'h1;
    reg [3:0] prev    = 4'h8;   // shadow register: the value that preceded lfsr
    reg       stepped = 1'b0;   // records that a shift happened on the last edge

    wire [3:0] nxt = {lfsr[2:0], lfsr[3] ^ lfsr[2]};

    assign out_bit = lfsr[0];
    assign state_o = lfsr;

    always @(posedge clk) begin
        stepped <= step;
        if (step) begin
            prev <= lfsr;   // shadow captures the earlier value
            lfsr <= nxt;
        end
    end

    // Precedence: whenever a shift has just been observed, the value now on the
    // register must differ from the shadowed value that preceded it -- the
    // generator always makes progress.
    always @(posedge clk)
        if (stepped)
            assert (lfsr != prev);

endmodule

module credit_deadline (
    input  wire clk,
    input  wire i_ce,      // global enable: low => all state frozen
    input  wire rst,
    input  wire req,       // producer wants to spend a credit
    output wire grant,
    output wire busy
);
    localparam [2:0] TOTAL = 3'd4;   // configured credit pool

    // credits held by the producer, credits outstanding at the consumer
    reg [2:0] credits;
    reg [2:0] outst;
    // consumer needs two enabled cycles to retire one outstanding credit
    reg       svc;
    // bounded-response deadline countdown for the outstanding credits
    reg [3:0] timer;

    initial begin
        credits = 3'd4;
        outst   = 3'd0;
        svc     = 1'b0;
        timer   = 4'd0;
    end

    wire do_spend  = req && (credits != 3'd0);
    wire do_return = (outst != 3'd0) && (svc == 1'b1);

    assign grant = i_ce && do_spend;
    assign busy  = (outst != 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (rst) begin
                credits <= TOTAL;
                outst   <= 3'd0;
                svc     <= 1'b0;
                timer   <= 4'd0;
            end else begin
                // credit conservation: one token moves per event
                credits <= credits - (do_spend  ? 3'd1 : 3'd0)
                                   + (do_return ? 3'd1 : 3'd0);
                outst   <= outst   + (do_spend  ? 3'd1 : 3'd0)
                                   - (do_return ? 3'd1 : 3'd0);

                // two-cycle service phase per outstanding credit
                if (outst == 3'd0)
                    svc <= 1'b0;
                else
                    svc <= ~svc;

                // deadline budget: each spend buys 2 cycles, one cycle burnt
                timer <= timer - ((timer != 4'd0) ? 4'd1 : 4'd0)
                               + (do_spend ? 4'd2 : 4'd0);
            end
        end
    end

    // Bounded response (safety): the countdown must never expire while a
    // credit is still outstanding at the consumer.
    always @(posedge clk)
        if (outst != 3'd0)
            assert (timer != 4'd0);

endmodule

// Valid/ready pipeline stage with a skid buffer carrying a three-step
// command chain: ARM -> START -> FINISH -> ARM -> ...
// The buffered word is only meaningful while the stage is stalled.
module chain_skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,       // global enable / idle condition
    input  wire       in_valid,   // producer offers its next chain word
    input  wire       out_ready,  // consumer accepts
    output wire       o_valid,
    output wire [1:0] o_code,
    output wire       o_in_ready
);
    localparam [1:0] ARM    = 2'd1;
    localparam [1:0] START  = 2'd2;
    localparam [1:0] FINISH = 2'd3;

    // producer chain position: next word emitted is src_phase+1
    reg [1:0] src_phase  = 2'd0;
    // consumer chain position: 0 = nothing armed, 1 = armed, 2 = started
    reg [1:0] phase      = 2'd0;

    // output (skid) register pair
    reg       out_valid  = 1'b0;
    reg [1:0] out_code   = ARM;
    reg       skid_valid = 1'b0;
    reg [1:0] skid_code  = ARM;

    wire [1:0] in_code  = src_phase + 2'd1;
    wire       in_ready = !skid_valid;
    wire       out_room = !out_valid || out_ready;
    wire       in_fire  = step && in_valid && in_ready;
    wire       out_fire = step && out_valid && out_ready;

    assign o_valid    = out_valid;
    assign o_code     = out_code;
    assign o_in_ready = in_ready;

    always @(posedge clk) begin
        if (rst) begin
            src_phase  <= 2'd0;
            phase      <= 2'd0;
            out_valid  <= 1'b0;
            out_code   <= ARM;
            skid_valid <= 1'b0;
            skid_code  <= ARM;
        end else if (step) begin
            // output register: drain skid first, else take the fresh word
            if (out_room) begin
                if (skid_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= skid_code;
                end else if (in_valid) begin
                    out_valid <= 1'b1;
                    out_code  <= in_code;
                end else begin
                    out_valid <= 1'b0;
                end
            end

            // skid buffer: only loaded while the stage is stalled
            if (skid_valid) begin
                if (out_room)
                    skid_valid <= 1'b0;
            end else if (in_valid && !out_room) begin
                skid_valid <= 1'b1;
                skid_code  <= in_code;
            end

            // producer advances on every accepted word
            if (in_valid && in_ready)
                src_phase <= (src_phase == 2'd2) ? 2'd0 : src_phase + 2'd1;

            // consumer chain tracker advances on every delivered word
            if (out_valid && out_ready)
                phase <= (out_code == FINISH) ? 2'd0 : out_code;
        end
    end

    // P (two assertions): a later chain step is never delivered unless the
    // earlier ones already were.
    always @(*)
        assert (!(out_fire && out_code == FINISH) || phase == 2'd2);

    always @(*)
        assert (!(out_fire && out_code == START) || phase == 2'd1);
endmodule

module elevator_call_gen (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,
    output reg  [1:0] floor,
    output reg        dir,
    output reg  [3:0] pending,
    output reg  [2:0] dry_cnt,
    output reg  [3:0] lf
);
    // 4-bit maximal-length LFSR (x^4 + x^3 + 1), period 15, never all-zeros.
    initial lf      = 4'b0001;
    initial floor   = 2'd0;
    initial dir     = 1'b1;   // 1 = up, 0 = down
    initial pending = 4'b0000;
    initial dry_cnt = 3'd0;

    wire [3:0] lf_next    = {lf[2:0], lf[3] ^ lf[2]};

    // A pseudo-random hall call is issued unless the LFSR is in its
    // single low state 4'b0001.
    wire       new_call   = (lf[3:1] != 3'b000);
    wire [1:0] call_floor = lf[1:0];

    wire at_top = (floor == 2'd3);
    wire at_bot = (floor == 2'd0);

    wire [1:0] floor_next = dir ? (at_top ? floor : floor + 2'd1)
                                : (at_bot ? floor : floor - 2'd1);
    wire       dir_next   = dir ? (at_top ? 1'b0 : 1'b1)
                                : (at_bot ? 1'b1 : 1'b0);

    wire [3:0] set_mask   = new_call ? (4'b0001 << call_floor) : 4'b0000;
    wire [3:0] clr_mask   = (4'b0001 << floor);

    always @(posedge clk) begin
        if (rst) begin
            lf      <= 4'b0001;
            floor   <= 2'd0;
            dir     <= 1'b1;
            pending <= 4'b0000;
            dry_cnt <= 3'd0;
        end else if (step) begin
            lf      <= lf_next;
            floor   <= floor_next;
            dir     <= dir_next;
            pending <= (pending | set_mask) & ~clr_mask;
            // consecutive enabled steps during which no new call appeared
            dry_cnt <= new_call ? 3'd0 : (dry_cnt + 3'd1);
        end
    end

    // Bounded existence: the call-starvation streak never exceeds 3,
    // although the counter is 3 bits wide.
    assert property (dry_cnt <= 3'd3);
endmodule

module seq_match_window (
    input  wire       clk,
    input  wire       i_ce,    // global enable: when low, nothing changes
    input  wire       data,    // serial bit stream
    input  wire       start,   // Q: opens the measurement window
    input  wire       stop,    // R: closes the measurement window
    output reg        armed,   // window register
    output reg  [3:0] mcnt,    // matches counted inside the window
    output reg  [3:0] slots,   // remaining match credits
    output reg  [2:0] prog     // match progress into the pattern 1011
);
    localparam [3:0] BUDGET = 4'd3;

    initial armed = 1'b0;
    initial mcnt  = 4'd0;
    initial slots = BUDGET;
    initial prog  = 3'd0;

    // full pattern 1-0-1-1 seen when three bits are already matched and data==1
    wire hit = (prog == 3'd3) && data;

    always @(posedge clk) begin
        if (i_ce) begin
            // ---- match-progress register (never exceeds the pattern length) ----
            case (prog)
                3'd0: prog <= data ? 3'd1 : 3'd0;
                3'd1: prog <= data ? 3'd1 : 3'd2;
                3'd2: prog <= data ? 3'd3 : 3'd0;
                3'd3: prog <= data ? 3'd1 : 3'd2;  // overlap-aware restart
                default: prog <= 3'd0;
            endcase

            // ---- window + credit bookkeeping ----
            if (stop) begin
                armed <= 1'b0;
            end else if (start) begin
                armed <= 1'b1;
                mcnt  <= 4'd0;
                slots <= BUDGET;
            end else if (armed && hit && (slots != 4'd0)) begin
                mcnt  <= mcnt  + 4'd1;
                slots <= slots - 4'd1;
            end
        end
    end

    // Property: inside an open window, at most 3 pattern occurrences are recorded,
    // even though mcnt is 4 bits wide.
    always @(posedge clk)
        if (armed) assert (mcnt <= 4'd3);
endmodule

module fetch_credit_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,        // idle condition: when low, nothing moves
    input  wire       fetch,     // issue an instruction into the fetch queue
    input  wire       retire,    // instruction leaves the queue
    output reg  [3:0] used,      // up counter: occupancy of the fetch queue
    output reg  [3:0] credits,   // down counter: remaining free slots
    output wire       can_fetch
);
    // queue depth is 12, but both counters are 4 bits wide (0..15)
    localparam [3:0] DEPTH = 4'd12;

    initial used    = 4'd0;
    initial credits = DEPTH;

    assign can_fetch = (credits != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            used    <= 4'd0;
            credits <= DEPTH;
        end else if (en) begin
            if (fetch && !retire && credits != 4'd0) begin
                // one slot moves from the free pool into the queue
                used    <= used + 4'd1;
                credits <= credits - 4'd1;
            end else if (retire && !fetch && used != 4'd0) begin
                // one slot moves back from the queue into the free pool
                used    <= used - 4'd1;
                credits <= credits + 4'd1;
            end
            // simultaneous fetch+retire: slot handed straight over, no change
        end
    end

    // P (two assertions, global scope, bounded existence at most 12):
    // neither counter can ever exceed the queue depth, which is strictly
    // smaller than what their 4-bit width admits.
    always @(posedge clk) begin
        assert (used <= DEPTH);
        assert (credits <= DEPTH);
    end
endmodule

// Sliding-window grant rate limiter for an accelerator DMA port.
// A shift register of the last 8 cycles of grants, plus a running
// count of the ones in that window used to throttle new requests.
module dma_rate_limiter (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // idle condition: low leaves all state unchanged
    input  wire i_req,
    output wire o_grant
);
    localparam [3:0] MAXG = 4'd3;   // at most 3 grants per 8-cycle window

    reg [7:0] win;    // recent grant history, win[7] is the oldest entry
    reg [3:0] ones;   // mirrors the number of ones in win
    reg       armed;  // sticky: set the first time a grant is issued

    initial begin
        win   = 8'd0;
        ones  = 4'd0;
        armed = 1'b0;
    end

    wire grant = i_ce && i_req && (ones < MAXG);
    assign o_grant = grant;

    wire [3:0] inc = grant  ? 4'd1 : 4'd0;
    wire [3:0] dec = win[7] ? 4'd1 : 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            win   <= 8'd0;
            ones  <= 4'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            win  <= {win[6:0], grant};
            ones <= ones + inc - dec;
            if (grant)
                armed <= 1'b1;
        end
    end

    // Two status conditions exported to the scheduler
    wire sat       = (ones == MAXG);   // window quota exhausted
    wire win_empty = (win == 8'd0);    // no grants anywhere in the window

    // Absence: once the port has issued its first grant, the limiter can
    // never report a saturated quota and an empty window at the same time.
    assert property (!armed || !(sat && win_empty));

endmodule

module dma_burst_dimmer (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // beat enable / idle when low
    input  wire       i_start,
    input  wire [3:0] i_beats,
    input  wire [3:0] i_duty,
    output wire       o_busy,
    output wire       o_beat,
    output wire       o_pwm
);

    // ---- DMA burst engine state ----
    reg [3:0] beats_left;   // beats remaining in the burst
    reg [3:0] done_cnt;     // beats already pushed out
    reg [3:0] total;        // beats requested by the accepted burst
    reg [3:0] duty;         // dimming level latched with the burst
    reg       busy;         // up exactly while beats remain

    initial beats_left = 4'd0;
    initial done_cnt   = 4'd0;
    initial total      = 4'd0;
    initial duty       = 4'd0;
    initial busy       = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            done_cnt   <= 4'd0;
            total      <= 4'd0;
            duty       <= 4'd0;
            busy       <= 1'b0;
        end else if (i_start && !busy && (i_beats != 4'd0)) begin
            // accept a new burst
            beats_left <= i_beats;
            total      <= i_beats;
            done_cnt   <= 4'd0;
            duty       <= i_duty;
            busy       <= 1'b1;
        end else if (i_ce) begin
            // retire one beat
            if (beats_left != 4'd0)
                beats_left <= beats_left - 4'd1;
            if (beats_left <= 4'd1)
                busy <= 1'b0;
            if (busy)
                done_cnt <= done_cnt + 4'd1;
        end
    end

    assign o_busy = busy;
    assign o_beat = busy && i_ce;
    assign o_pwm  = busy && (done_cnt < duty);

    // ---- P: whenever the engine is not busy, the whole burst has been pushed ----
    always @(posedge i_clk)
        if (!busy)
            assert (done_cnt == total);

endmodule

module wdt_absence (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       arm,       // Q: opens the window
    input  wire       disarm,    // R: closes the window (may never arrive)
    input  wire       kick,      // pet the watchdog
    output reg  [3:0] cnt,
    output reg        expired,
    output reg        safe,
    output reg        armed
);
    localparam [3:0] LIMIT = 4'd10;  // timeout value
    localparam [3:0] WARN  = 4'd8;   // below this the timer is in the safe zone

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial safe    = 1'b1;
    initial armed   = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
            // window register: set by arm, cleared by disarm
            if (arm)
                armed <= 1'b1;
            else if (disarm)
                armed <= 1'b0;

            // the watchdog only runs inside the window
            if (armed) begin
                if (kick) begin
                    cnt     <= 4'd0;
                    expired <= 1'b0;
                    safe    <= 1'b1;
                end else if (cnt == LIMIT) begin
                    cnt     <= LIMIT;      // saturate at the timeout
                    expired <= 1'b1;
                    safe    <= 1'b0;
                end else begin
                    cnt     <= cnt + 4'd1;
                    expired <= expired || ((cnt + 4'd1) == LIMIT); // sticky
                    safe    <= ((cnt + 4'd1) < WARN);
                end
            end
        end
    end

    // P: once armed (and until disarmed, if ever), the timer can never report
    // both "expired" and "safe" at the same time.
    always @(*)
        if (armed)
            assert (!(expired && safe));
endmodule

module boot_chunk_loader (
    input  wire i_clk,
    input  wire i_ce,      // idle when low: no state changes at all
    input  wire i_start,   // accept a fresh load request
    output wire o_expired,
    output wire o_done,
    output wire [7:0] o_total
);
    // A chunk loader that accumulates 3 bytes of payload per accepted step.
    // The accumulator is kept in two carry-save halves (acc_a, acc_b) whose
    // sum is the true byte total; `total` is the redundant true running sum.
    localparam [3:0] TMAX  = 4'd8;   // countdown granted to a request
    localparam [7:0] LIMIT = 8'd24;  // bytes that constitute completion

    reg [7:0] acc_a;
    reg [7:0] acc_b;
    reg [7:0] total;
    reg [3:0] timer;
    reg       pv;

    initial acc_a = 8'd0;
    initial acc_b = 8'd0;
    initial total = 8'd0;
    initial timer = TMAX;
    initial pv    = 1'b0;

    wire [7:0] csum    = acc_a + acc_b;   // halves recombined
    wire       expired = (timer == 4'd0);

    assign o_expired = expired;
    assign o_done    = (csum >= LIMIT);
    assign o_total   = total;

    always @(posedge i_clk)
        pv <= 1'b1;

    always @(posedge i_clk) begin
        if (i_ce) begin
            if (i_start) begin
                acc_a <= 8'd0;
                acc_b <= 8'd0;
                total <= 8'd0;
                timer <= TMAX;
            end else if (timer != 4'd0) begin
                acc_a <= acc_a + 8'd1;   // low carry-save half
                acc_b <= acc_b + 8'd2;   // high carry-save half
                total <= total + 8'd3;   // true total
                timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never expire while the
    // load request is still outstanding.  Edge form: the cycle `expired` rises,
    // the recombined accumulator must already show a completed transfer.
    always @(posedge i_clk)
        if (pv)
            assert (!$rose(expired) || (acc_a + acc_b >= LIMIT));
endmodule

module wdog_scan (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,      // scanner step enable; low => whole design idles
    input  wire i_kick,    // full substring match: hard kick of the watchdog
    input  wire i_feed,    // partial match: partial credit, no flag clear
    output wire o_timeout,
    output wire [7:0] o_pos
);
    // Watchdog for a character-scan engine: the scanner must report progress
    // before LIMIT idle steps elapse, otherwise the search is declared timed out.
    localparam [3:0] LIMIT = 4'd12;

    reg [3:0] wd;       // cycles since last progress, saturates at LIMIT
    reg       expired;  // sticky timeout flag
    reg [7:0] pos;      // current character position in the haystack

    initial wd      = 4'd0;
    initial expired = 1'b0;
    initial pos     = 8'd0;

    always @(posedge clk) begin
        if (rst) begin
            wd      <= 4'd0;
            expired <= 1'b0;
            pos     <= 8'd0;
        end else if (i_ce) begin
            pos <= pos + 8'd1;
            if (i_kick) begin
                // full match: reload the watchdog and drop the timeout flag
                wd      <= 4'd0;
                expired <= 1'b0;
            end else if (i_feed) begin
                // partial credit: only granted while the counter has not
                // saturated.  Note the gate looks at the COUNTER, not the flag.
                if (wd != LIMIT)
                    wd <= (wd > 4'd4) ? (wd - 4'd4) : 4'd0;
            end else begin
                // no progress this step: count up and saturate at LIMIT
                if (wd != LIMIT) begin
                    wd <= wd + 4'd1;
                    if ((wd + 4'd1) == LIMIT)
                        expired <= 1'b1;
                end
            end
        end
    end

    assign o_timeout = expired;
    assign o_pos     = pos;

    // P: a reported timeout always comes with a counter in the top half of
    // its range (the watchdog really did run out of slack).
    always @(posedge clk) assert (!expired || wd[3]);
endmodule

module credit_ledger (
    input  wire        clk,
    input  wire        i_ce,
    output wire [4:0]  o_gray,
    output wire        o_drained
);
    // up counter and down counter stepped by the same enable; their sum is 20
    reg [4:0] up;
    reg [4:0] dn;

    // shadow register: records that the up counter has already reached 10
    reg       mark;

    // "before R" scope: starts high, cleared the first time the ledger drains
    reg       before_done;

    initial up          = 5'd0;
    initial dn          = 5'd20;
    initial mark        = 1'b0;
    initial before_done = 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (dn == 5'd0) begin
                before_done <= 1'b0;   // the drained event has been observed
            end else begin
                up   <= up + 5'd1;
                dn   <= dn - 5'd1;
                mark <= mark | (up == 5'd9);
            end
        end
    end

    // gray view of the shadow binary up counter (clock-domain-crossing flavour)
    assign o_gray    = up ^ (up >> 1);
    assign o_drained = (dn == 5'd0);

    // Property: before the ledger has ever drained, seeing fewer than ten
    // credits left means the up counter must already have passed ten.
    always @(*)
        if (before_done && (dn <= 5'd9))
            assert (mark);
endmodule

module serial_retire_counter (
    input  wire i_clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_bit,
    output wire o_word_done,
    output wire o_saturated
);
    // Bit-serial datapath: one bit per enabled cycle, 32 bits per word.
    // Every completed 32-bit word retires one operation; the retire counter
    // is a saturating up-counter that clamps at 20, well below the 31 its
    // 5-bit register could hold.
    localparam [4:0] MAX_RETIRE = 5'd20;

    reg [4:0]  sh;       // serial bit index 0..31
    reg [31:0] word;     // serial shift register (datapath flavour)
    reg [4:0]  retired;  // saturating up-counter, clamps at MAX_RETIRE
    reg        done;     // "counter has reached the clamp" flag

    initial sh      = 5'd0;
    initial word    = 32'd0;
    initial retired = 5'd0;
    initial done    = 1'b0;

    wire word_last = (sh == 5'd31);

    always @(posedge i_clk) begin
        if (i_rst) begin
            sh      <= 5'd0;
            word    <= 32'd0;
            retired <= 5'd0;
            done    <= 1'b0;
        end else if (i_ce) begin
            sh   <= sh + 5'd1;
            word <= { i_bit, word[31:1] };
            if (word_last) begin
                if (!done)
                    retired <= retired + 5'd1;
                done <= done || (retired == (MAX_RETIRE - 5'd1));
            end
        end
    end

    assign o_word_done = word_last;
    assign o_saturated = done;

    // P: the retire count never exceeds 20, although the register admits 31.
    always @(posedge i_clk)
        assert (retired <= MAX_RETIRE);
endmodule

// Packet-capture sensor credit window.
// TOTAL = 8 stream credits.  A burst send spends 3 credits (they become
// "outstanding" bytes in flight); the collector returns exactly one credit
// per enabled cycle while anything is outstanding.  A deadline register is
// reloaded on every accepted burst and counts down otherwise; it must never
// expire while credits are still outstanding.
module credit_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire       i_send,    // producer requests a burst
    output wire       o_busy
);
    reg [3:0] avail;   // credits held by the sensor
    reg [3:0] outst;   // credits outstanding (in flight)
    reg [3:0] timer;   // completion deadline countdown
    reg       armed;   // sticky: set the first time a burst is accepted

    initial avail = 4'd8;
    initial outst = 4'd0;
    initial timer = 4'd0;
    initial armed = 1'b0;

    wire send_ok = i_send && (avail >= 4'd3);
    wire retire  = (outst != 4'd0);

    assign o_busy = (outst != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            avail <= 4'd8;
            outst <= 4'd0;
            timer <= 4'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            if (send_ok) begin
                // spend three credits, one may come back the same cycle
                avail <= avail - 4'd3 + (retire ? 4'd1 : 4'd0);
                outst <= outst + 4'd3 - (retire ? 4'd1 : 4'd0);
                timer <= 4'd9;          // fresh completion deadline
                armed <= 1'b1;          // sticky arm
            end else if (retire) begin
                avail <= avail + 4'd1;
                outst <= outst - 4'd1;
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end else begin
                if (timer != 4'd0)
                    timer <= timer - 4'd1;
            end
        end
    end

    // Bounded response (safety form), scoped after the first accepted burst:
    // the deadline never expires while credits are still outstanding.
    always @(*)
        assert (!armed || !((timer == 4'd0) && (outst != 4'd0)));
endmodule

module dma_burst_engine (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire [3:0]  i_len,
    input  wire [27:0] i_addr,
    output wire        o_busy,
    output wire        o_last,
    output wire [27:0] o_addr,
    output wire [3:0]  o_sent
);

    // ---- burst engine state -------------------------------------------
    reg        busy       = 1'b0;   // up exactly while beats remain
    reg [3:0]  beats      = 4'd0;   // beats remaining in current burst
    reg [3:0]  words_sent = 4'd0;   // beats already issued this burst
    reg [3:0]  len_reg    = 4'd0;   // latched burst length
    reg [27:0] addr       = 28'd0;  // running beat address

    wire start_ok = start && (i_len != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            busy       <= 1'b0;
            beats      <= 4'd0;
            words_sent <= 4'd0;
            len_reg    <= 4'd0;
            addr       <= 28'd0;
        end else if (ce) begin
            if (busy) begin
                // issue one beat
                beats      <= beats - 4'd1;
                words_sent <= words_sent + 4'd1;
                addr       <= addr + 28'd4;
                if (beats == 4'd1)
                    busy <= 1'b0;
            end else if (start_ok) begin
                // accept a new burst descriptor
                busy       <= 1'b1;
                beats      <= i_len;
                words_sent <= 4'd0;
                len_reg    <= i_len;
                addr       <= i_addr;
            end
        end
        // ce low: engine stalls, every register holds its value
    end

    assign o_busy = busy;
    assign o_last = busy && (beats == 4'd1);
    assign o_addr = addr;
    assign o_sent = words_sent;

    // ---- property: while the engine is busy it has strictly fewer beats
    // ---- issued than the latched burst length -------------------------
    always @(posedge clk)
        if (busy)
            assert (words_sent < len_reg);

endmodule

module histogram_sampler (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // sample-enable; low => whole histogram idles
    input  wire [1:0] i_sel,     // which bin the incoming sample lands in
    output reg  [3:0] bin0,
    output reg  [3:0] bin1,
    output reg  [3:0] bin2,
    output reg  [3:0] bin3,
    output reg  [3:0] total,
    output wire       o_full
);
    // sampling window closes after MAXS samples have been binned
    localparam [3:0] MAXS = 4'd12;

    initial bin0  = 4'd0;
    initial bin1  = 4'd0;
    initial bin2  = 4'd0;
    initial bin3  = 4'd0;
    initial total = 4'd0;

    assign o_full = (total == MAXS);

    wire take = i_ce && (total < MAXS);

    always @(posedge clk) begin
        if (rst) begin
            bin0  <= 4'd0;
            bin1  <= 4'd0;
            bin2  <= 4'd0;
            bin3  <= 4'd0;
            total <= 4'd0;
        end else if (take) begin
            case (i_sel)
                2'd0: bin0 <= bin0 + 4'd1;
                2'd1: bin1 <= bin1 + 4'd1;
                2'd2: bin2 <= bin2 + 4'd1;
                2'd3: bin3 <= bin3 + 4'd1;
            endcase
            total <= total + 4'd1;
        end
    end

    // P: no single bin's occupancy can ever exceed the sampling-window size,
    // even though the 4-bit bin register could physically hold 15.
    always @(*)
        assert (bin1 <= MAXS);
endmodule

// Log-event chain detector: watches a token stream for the ordered
// sequence AUTH_REQ -> SESSION_OPEN -> SUDO_OK and raises an alert.
module log_chain_detect (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire [2:0] tok,     // event token from the parsed log line
    output wire       o_armed,
    output wire       o_started,
    output wire       o_alert
);
    localparam [2:0] PAT0 = 3'd1;  // AUTH_REQ
    localparam [2:0] PAT1 = 3'd4;  // SESSION_OPEN
    localparam [2:0] PAT2 = 3'd6;  // SUDO_OK
    localparam [2:0] PLEN = 3'd3;

    // match-progress register: how many pattern tokens seen in order
    reg [2:0] prog;
    // chain-stage flags, set as the progress register passes each stage
    reg       r_arm;
    reg       r_start;
    reg       r_fin;

    initial prog    = 3'd0;
    initial r_arm   = 1'b0;
    initial r_start = 1'b0;
    initial r_fin   = 1'b0;

    wire [2:0] expect_tok = (prog == 3'd0) ? PAT0 :
                            (prog == 3'd1) ? PAT1 : PAT2;

    wire advance = ce && (prog < PLEN) && (tok == expect_tok);

    always @(posedge clk) begin
        if (rst) begin
            prog    <= 3'd0;
            r_arm   <= 1'b0;
            r_start <= 1'b0;
            r_fin   <= 1'b0;
        end else if (advance) begin
            prog <= prog + 3'd1;
            if (prog == 3'd0) r_arm   <= 1'b1;
            if (prog == 3'd1) r_start <= 1'b1;
            if (prog == 3'd2) r_fin   <= 1'b1;
        end
    end

    assign o_armed   = r_arm;
    assign o_started = r_start;
    assign o_alert   = r_fin;

    // Chain precedence, globally: the finish stage can never be observed
    // unless both earlier stages of the chain already happened.
    assert property (!r_fin || (r_start && r_arm));
endmodule

module sb_window (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_issue,
    input  wire i_retire,
    input  wire i_open,
    input  wire i_close,
    output wire o_full,
    output wire o_empty,
    output wire o_mon
);
    localparam [3:0] WINDOW = 4'd8;

    // transaction scoreboard: issued count, retired count, and a redundant
    // outstanding-transaction register maintained in parallel
    reg [4:0] iss;
    reg [4:0] ret;
    reg [3:0] out_r;

    // registered status flags (one cycle stale, updated only when enabled)
    reg       full_q;
    reg       empty_q;

    // monitoring window: opened by i_open, closed by i_close
    reg       mon;

    reg       pv;

    initial iss     = 5'd0;
    initial ret     = 5'd0;
    initial out_r   = 4'd0;
    initial full_q  = 1'b0;
    initial empty_q = 1'b1;
    initial mon     = 1'b0;
    initial pv      = 1'b0;

    wire acc_iss = i_ce && i_issue  && (out_r <  WINDOW);
    wire acc_ret = i_ce && i_retire && (out_r != 4'd0);

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk)
        if (i_rst) begin
            iss   <= 5'd0;
            ret   <= 5'd0;
            out_r <= 4'd0;
        end else begin
            if (acc_iss) iss <= iss + 5'd1;
            if (acc_ret) ret <= ret + 5'd1;
            if (acc_iss && !acc_ret)
                out_r <= out_r + 4'd1;
            else if (!acc_iss && acc_ret)
                out_r <= out_r - 4'd1;
        end

    always @(posedge clk)
        if (i_rst) begin
            full_q  <= 1'b0;
            empty_q <= 1'b1;
        end else if (i_ce) begin
            full_q  <= (out_r == WINDOW);
            empty_q <= (iss == ret);
        end

    always @(posedge clk)
        if (i_rst)
            mon <= 1'b0;
        else if (i_ce) begin
            if (i_close)
                mon <= 1'b0;
            else if (i_open)
                mon <= 1'b1;
        end

    assign o_full  = full_q;
    assign o_empty = empty_q;
    assign o_mon   = mon;

    // P: inside an open monitoring window, when the full flag rises the
    // scoreboard must not simultaneously report empty
    always @(posedge clk)
        if (pv && mon && $rose(full_q))
            assert (!empty_q);
endmodule

module net_router_progress (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire i_route,
    input wire i_rip,
    output reg [3:0] routed,
    output reg [3:0] unrouted
);
    // Total number of nets in the board; every net is either routed or unrouted.
    localparam [3:0] TOTAL = 4'd12;

    initial routed   = 4'd0;
    initial unrouted = TOTAL;

    // One shared enable steps the up counter and the down counter together.
    wire do_route = i_ce && i_route && !i_rip   && (unrouted != 4'd0);
    wire do_rip   = i_ce && i_rip   && !i_route && (routed   != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            routed   <= 4'd0;
            unrouted <= TOTAL;
        end else if (do_route) begin
            routed   <= routed   + 4'd1;
            unrouted <= unrouted - 4'd1;
        end else if (do_rip) begin
            routed   <= routed   - 4'd1;
            unrouted <= unrouted + 4'd1;
        end
    end

    // P: the routed and unrouted net counts can only coincide at the half-way
    // mark, because together they always account for all TOTAL nets.
    always @(posedge clk)
        assert (routed != unrouted || routed == 4'd6);
endmodule

module gray_ptr_cdc (
    input  wire       clk,
    input  wire       i_ce,      // domain-crossing sample enable (idle when low)
    input  wire       i_inc,     // advance the source pointer
    output wire [2:0] o_sync
);
    // source-side binary pointer and its gray encoding
    reg [2:0] bin   = 3'd0;
    // two-flop synchronizer carrying the gray pointer across the boundary
    reg [2:0] s1    = 3'd0;
    reg [2:0] s2    = 3'd0;
    // shadow binary pointers recording what each synchronizer stage encodes
    reg [2:0] b1    = 3'd0;
    reg [2:0] b2    = 3'd0;
    // sticky arm: set the first time a sample actually happens
    reg       armed = 1'b0;

    wire [2:0] gray = bin ^ (bin >> 1);
    wire [2:0] diff = s1 ^ s2;

    assign o_sync = s2;

    always @(posedge clk) begin
        if (i_ce) begin
            bin   <= bin + (i_inc ? 3'd1 : 3'd0);
            s1    <= gray;
            s2    <= s1;
            b1    <= bin;
            b2    <= b1;
            armed <= 1'b1;
        end
    end

    // Universality, after the synchronizer has been armed: the two captured
    // gray samples never differ in more than one bit.
    always @(*)
        if (armed)
            assert ((diff & (diff - 3'd1)) == 3'd0);
endmodule

module gfx_frame_fsm (
    input  wire clk,
    input  wire i_reset,
    input  wire i_ce,
    input  wire i_start,
    output wire o_vsync,
    output wire [2:0] o_state
);
    // binary-encoded frame pipeline states; 5,6,7 are unreachable encodings
    localparam [2:0] S_IDLE    = 3'd0;
    localparam [2:0] S_CLEAR   = 3'd1;
    localparam [2:0] S_DRAW    = 3'd2;
    localparam [2:0] S_BLIT    = 3'd3;
    localparam [2:0] S_PRESENT = 3'd4;

    reg [2:0] state;
    reg [1:0] draw_cnt;
    reg       cleared_seen;   // shadow: framebuffer was cleared this frame

    initial state        = S_IDLE;
    initial draw_cnt     = 2'd0;
    initial cleared_seen = 1'b0;

    wire draw_done = (draw_cnt == 2'd3);

    always @(posedge clk) begin
        if (i_reset) begin
            state        <= S_IDLE;
            draw_cnt     <= 2'd0;
            cleared_seen <= 1'b0;
        end else if (i_ce) begin
            case (state)
                S_IDLE: begin
                    if (i_start) begin
                        state    <= S_CLEAR;
                        draw_cnt <= 2'd0;
                    end
                end
                S_CLEAR: begin
                    // the clear pass is the "earlier event" the shadow records
                    cleared_seen <= 1'b1;
                    state        <= S_DRAW;
                end
                S_DRAW: begin
                    if (draw_done)
                        state <= S_BLIT;
                    else
                        draw_cnt <= draw_cnt + 2'd1;
                end
                S_BLIT: begin
                    state <= S_PRESENT;
                end
                S_PRESENT: begin
                    state        <= S_IDLE;
                    draw_cnt     <= 2'd0;
                    cleared_seen <= 1'b0;
                end
                default: begin
                    // encodings 5/6/7 never occur by construction; the
                    // synthesised decoder folds them onto the present stage
                    state <= S_PRESENT;
                end
            endcase
        end
    end

    assign o_vsync = (state == S_PRESENT);
    assign o_state = state;

    // Precedence, global: presenting a frame implies the clear pass happened earlier
    always @(posedge clk)
        if (state == S_PRESENT)
            assert (cleared_seen);
endmodule

// Triple-modular-redundant power-rail sequencer step counter.
// Three shadow copies of the sequencer step code are advanced independently;
// the exported step code is the bitwise majority vote of the three copies.
// prev_voted is a precedence shadow: it records the voted code as it was at
// the previous advance, so the present code must be the successor of the code
// that was observed earlier.
module tmr_rail_sequencer (
    input  wire       clk,
    input  wire       ce,        // advance / load enable; low => design idles
    input  wire       load,      // reload the sequencer with an external code
    input  wire [2:0] code_in,
    input  wire       q_start,   // opens the monitoring window
    input  wire       r_stop,    // closes the monitoring window
    output wire [2:0] voted
);

    // three shadow registers of the TMR voter
    reg [2:0] shadow_a = 3'd1;
    reg [2:0] shadow_b = 3'd1;
    reg [2:0] shadow_c = 3'd1;

    // precedence shadow: voted code at the previous advance
    reg [2:0] prev_voted = 3'd0;

    // window register: set by q_start, cleared by r_stop, reopenable
    reg       win = 1'b0;

    // bitwise majority vote
    assign voted = (shadow_a & shadow_b) | (shadow_a & shadow_c) |
                   (shadow_b & shadow_c);

    always @(posedge clk) begin
        if (ce) begin
            if (load) begin
                shadow_a   <= code_in;
                shadow_b   <= code_in;
                shadow_c   <= code_in;
                prev_voted <= code_in - 3'd1;
            end else begin
                shadow_a   <= shadow_a + 3'd1;
                shadow_b   <= shadow_b + 3'd1;
                shadow_c   <= shadow_c + 3'd1;
                prev_voted <= voted;
            end
        end
    end

    always @(posedge clk) begin
        if (r_stop)
            win <= 1'b0;
        else if (q_start)
            win <= 1'b1;
    end

    // Property: inside the monitoring window, the voted step code must be the
    // immediate successor of the code recorded earlier in prev_voted.
    always @(posedge clk)
        assert (!win || (voted == prev_voted + 3'd1));

endmodule

module lfsr_token_arbiter (
    input  wire clk,
    input  wire ce,
    output wire o_gnt_a,
    output wire o_gnt_b,
    output wire o_full,
    output wire o_empty
);
    // maximal-length 4-bit LFSR (x^4 + x^3 + 1): cycles through all 15
    // nonzero states, so the all-zeros lockup state is never entered.
    reg [3:0] lfsr;
    reg       gnt_a, gnt_b;
    reg [2:0] credit, used;
    reg       f_full, f_empty;
    reg       armed;

    initial begin
        lfsr    = 4'h1;
        gnt_a   = 1'b0;
        gnt_b   = 1'b0;
        credit  = 3'd4;
        used    = 3'd0;
        f_full  = 1'b0;
        f_empty = 1'b1;
        armed   = 1'b0;
    end

    wire       fb   = lfsr[3] ^ lfsr[2];
    wire [3:0] nxt  = {lfsr[2:0], fb};
    wire       lock = (lfsr == 4'd0);

    // token movement between the two credit pools, steered by the LFSR
    wire take_a = lfsr[0]  && (credit != 3'd0);
    wire give_b = !lfsr[0] && (used   != 3'd0);

    wire [2:0] nc = take_a ? (credit - 3'd1) : (give_b ? (credit + 3'd1) : credit);
    wire [2:0] nu = take_a ? (used   + 3'd1) : (give_b ? (used   - 3'd1) : used);

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= nxt;

            // grant decode: in the lockup state the decode degenerates and
            // asserts both grants at once
            gnt_a <= lock ? 1'b1 : nxt[0];
            gnt_b <= lock ? 1'b1 : !nxt[0];

            credit <= nc;
            used   <= nu;

            f_full  <= (nc == 3'd0);
            f_empty <= (nu == 3'd0);

            if (lfsr == 4'hF)
                armed <= 1'b1;
        end
    end

    assign o_gnt_a = gnt_a;
    assign o_gnt_b = gnt_b;
    assign o_full  = f_full;
    assign o_empty = f_empty;

    // P1: two grants are never asserted together, once the arbiter has been armed
    always @(posedge clk)
        if (armed)
            assert (!(gnt_a && gnt_b));

    // P2: the full and empty flags are never asserted together, once armed
    always @(posedge clk)
        if (armed)
            assert (!(f_full && f_empty));
endmodule

module clkdiv_phase_tick (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output wire       div_en,
    output wire [3:0] beat_o,
    output wire [2:0] phase_o
);
    // Divide-by-5 phase counter with a parallel one-hot phase ring.
    // The divided enable pulse fires exactly on the cycle after the phase wraps.
    localparam [2:0] DIVM1 = 3'd4;

    reg [2:0] phase;
    reg [4:0] oh;      // one-hot mirror of the phase counter
    reg       tick;    // registered divided-enable pulse
    reg [3:0] beat;    // slow-domain beat counter, advanced by tick

    initial phase = 3'd0;
    initial oh    = 5'b00001;
    initial tick  = 1'b0;
    initial beat  = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            phase <= 3'd0;
            oh    <= 5'b00001;
            tick  <= 1'b0;
            beat  <= 4'd0;
        end else if (ce) begin
            phase <= (phase == DIVM1) ? 3'd0 : (phase + 3'd1);
            oh    <= { oh[3:0], oh[4] };
            tick  <= oh[4];
            beat  <= beat + { 3'b000, tick };
        end
    end

    assign div_en  = tick;
    assign beat_o  = beat;
    assign phase_o = phase;

    // P: whenever the divided enable is asserted, the phase counter has just wrapped.
    always @(posedge clk)
        if (tick)
            assert (phase == 3'd0);
endmodule

module dma_burst_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // engine clock-enable / idle when low
    input  wire       i_start,   // Q: opens the transfer window
    input  wire [3:0] i_len,     // burst length in beats
    input  wire       i_ack,     // R: closes the transfer window
    output wire       o_busy,
    output wire       o_drained
);

    // beats-remaining counter and the two status flags derived from it
    reg [3:0] beats_left;
    reg       busy;
    reg       drained;

    // window register: set by a new burst (Q), cleared by the ack (R)
    reg       win;

    initial beats_left = 4'd0;
    initial busy       = 1'b0;
    initial drained    = 1'b1;
    initial win        = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            beats_left <= 4'd0;
            busy       <= 1'b0;
            drained    <= 1'b1;
            win        <= 1'b0;
        end else if (i_ce) begin
            if (i_start && !busy) begin
                // load a new burst descriptor and open the window
                beats_left <= i_len;
                busy       <= (i_len != 4'd0);
                drained    <= (i_len == 4'd0);
                win        <= 1'b1;
            end else if (busy) begin
                // retire one beat
                beats_left <= beats_left - 4'd1;
                busy       <= (beats_left != 4'd1);
                drained    <= (beats_left <= 4'd1);
                if (i_ack)
                    win <= 1'b0;
            end else if (i_ack) begin
                // close the window between transfers
                win <= 1'b0;
            end
        end
    end

    assign o_busy    = busy;
    assign o_drained = drained;

    // P: inside an open transfer window the engine is never simultaneously
    // reporting "busy" and "drained".
    always @(posedge i_clk)
        if (win)
            assert (!(busy && drained));

endmodule

module deb_evt_fifo (
    input  wire clk,
    input  wire i_ce,      // sample enable: low freezes all state
    input  wire raw,       // raw (noisy) button level
    input  wire pop,       // consumer request
    output wire empty,
    output wire full,
    output reg  o_level    // last popped debounced level
);
    // ---- debouncer: saturating stability counter ----
    reg [1:0] stab;
    reg       deb;

    // ---- event FIFO: pointers + occupancy ----
    reg [1:0] wptr, rptr;
    reg [2:0] count;
    reg [1:0] tail;        // shadow: write pointer snapshot taken at the last push
    reg       mem [0:3];

    // ---- scope register: high until the FIFO has ever been full ----
    reg       never_full;

    // ---- past-valid ----
    reg       pv;

    initial begin
        stab = 2'd0; deb = 1'b0;
        wptr = 2'd0; rptr = 2'd0; count = 3'd0;
        tail = 2'd0;
        never_full = 1'b1;
        pv = 1'b0;
        o_level = 1'b0;
        mem[0] = 1'b0; mem[1] = 1'b0; mem[2] = 1'b0; mem[3] = 1'b0;
    end

    assign empty = (count == 3'd0);
    assign full  = (count == 3'd4);

    // a debounced edge is committed once raw has disagreed with deb for 3 samples
    wire deb_commit = (raw != deb) && (stab == 2'd2);

    wire do_push = i_ce && deb_commit && !full;
    wire do_pop  = i_ce && pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            if (raw != deb) begin
                if (stab == 2'd2) stab <= 2'd0;
                else              stab <= stab + 2'd1;
            end else begin
                stab <= 2'd0;
            end
            if (deb_commit) deb <= raw;

            if (do_push) begin
                mem[wptr] <= raw;
                wptr      <= wptr + 2'd1;
                tail      <= wptr + 2'd1;
            end

            if (do_pop) begin
                o_level <= mem[rptr];
                rptr    <= rptr + 2'd1;
            end

            case ({do_push, do_pop})
                2'b10:   count <= count + 3'd1;
                2'b01:   count <= count - 3'd1;
                default: count <= count;
            endcase

            if (count == 3'd4) never_full <= 1'b0;
        end
        pv <= 1'b1;
    end

    // Precedence, before-first-full scope, stated about the previous cycle:
    // if the queue has just been drained empty by a pop, the read pointer must
    // have reached the write-pointer snapshot recorded at the earlier push.
    always @(posedge clk)
        if (pv && never_full && (count == 3'd0) && $past(do_pop))
            assert (rptr == $past(tail));
endmodule

// Tracks in-flight requests in an 8-deep shift register with a separate
// population count.  A parity/CDC error input permanently degrades the
// tracker: once `err` has been seen, the count stops being maintained
// while the shift register keeps shifting.  The occupancy relations are
// therefore only claimed before that first error.
module inflight_tracker (
    input  wire       clk,
    input  wire       step,      // idle condition: step low freezes all state
    input  wire       req,       // new request enters the pipeline this step
    input  wire       err,       // degradation event (clears the arming reg)
    output reg  [7:0] inflight,  // one bit per pipeline stage, MSB retires
    output reg  [3:0] count,     // number of set bits in `inflight`
    output reg        live       // arming register: high before any err
);

    initial inflight = 8'd0;
    initial count    = 4'd0;
    initial live     = 1'b1;

    wire retire = inflight[7];

    always @(posedge clk) begin
        if (err)
            live <= 1'b0;

        if (step) begin
            inflight <= {inflight[6:0], req};
            // the bookkeeping count is only kept faithful while undegraded
            if (live && !err)
                count <= count + (req ? 4'd1 : 4'd0) - (retire ? 4'd1 : 4'd0);
        end
    end

    // Two universality properties, both scoped to "before the first err".
    always @(posedge clk) begin
        if (live && count == 4'd0)
            assert (inflight == 8'h00);
        if (live && count == 4'd8)
            assert (inflight == 8'hFF);
    end

endmodule

module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       issue,     // new operation issued this advance
    output wire       o_retire,  // fixed-latency result leaving the unit
    output wire [2:0] o_occ
);
    // 4-deep fixed-latency shift register: bit k = op issued k cycles ago
    reg [3:0] pipe;
    // occupancy: incremented on issue, decremented when the tail drains
    reg [2:0] occ;
    // sticky arm: set the first time an operation is ever issued
    reg       armed;

    initial pipe  = 4'b0000;
    initial occ   = 3'd0;
    initial armed = 1'b0;

    assign o_retire = i_ce && pipe[3];
    assign o_occ    = occ;

    always @(posedge clk) begin
        if (rst) begin
            pipe  <= 4'b0000;
            occ   <= 3'd0;
            armed <= 1'b0;
        end else if (i_ce) begin
            pipe <= {pipe[2:0], issue};
            occ  <= occ + (issue ? 3'd1 : 3'd0) - (pipe[3] ? 3'd1 : 3'd0);
            if (issue)
                armed <= 1'b1;
        end
    end

    // P: once the unit has ever issued, at most 4 operations are in flight.
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd4);
endmodule

module irq_priority_grant (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [7:0] req,
    output reg  [7:0] pending,
    output reg  [7:0] ever_req,
    output reg  [2:0] grant_idx,
    output reg        grant_valid
);

    // Requests currently outstanding plus whatever arrives this cycle
    wire [7:0] sel = pending | req;

    // Combinational priority encoder: lowest index wins
    reg [2:0] enc_idx;
    reg       enc_valid;
    integer   i;
    always @(*) begin
        enc_idx   = 3'd0;
        enc_valid = 1'b0;
        for (i = 7; i >= 0; i = i - 1) begin
            if (sel[i]) begin
                enc_idx   = i;
                enc_valid = 1'b1;
            end
        end
    end

    initial pending     = 8'd0;
    initial ever_req    = 8'd0;  // shadow: every line that has ever asserted
    initial grant_idx   = 3'd0;
    initial grant_valid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            pending     <= 8'd0;
            ever_req    <= 8'd0;
            grant_idx   <= 3'd0;
            grant_valid <= 1'b0;
        end else if (ce) begin
            ever_req    <= ever_req | req;
            grant_valid <= enc_valid;
            grant_idx   <= enc_idx;
            if (enc_valid)
                pending <= sel & ~(8'd1 << enc_idx);
            else
                pending <= 8'd0;
        end
    end

    // The encoded index is only meaningful while grant_valid is set:
    // whenever a grant is presented, that line must have requested earlier.
    always @(*)
        assert (!grant_valid || ever_req[grant_idx]);

endmodule

module rr_coin_arbiter (
    input  wire       clk,
    input  wire       step,
    input  wire [3:0] req,
    output reg  [3:0] gnt,
    output reg  [3:0] last,
    output reg        armed,
    output reg  [5:0] credit,
    output reg        dispense
);
    // Four coin slots compete for the single credit accumulator port.
    // Slots 0,1 drop 5c pieces; slots 2,3 drop 10c pieces.

    initial gnt      = 4'b0000;
    initial last     = 4'b0001;
    initial armed    = 1'b0;
    initial credit   = 6'd0;
    initial dispense = 1'b0;

    // Cyclic priority picks, one per possible position of the last-grant token.
    wire [3:0] sel0 = req[1] ? 4'b0010 : req[2] ? 4'b0100 : req[3] ? 4'b1000 : req[0] ? 4'b0001 : 4'b0000;
    wire [3:0] sel1 = req[2] ? 4'b0100 : req[3] ? 4'b1000 : req[0] ? 4'b0001 : req[1] ? 4'b0010 : 4'b0000;
    wire [3:0] sel2 = req[3] ? 4'b1000 : req[0] ? 4'b0001 : req[1] ? 4'b0010 : req[2] ? 4'b0100 : 4'b0000;
    wire [3:0] sel3 = req[0] ? 4'b0001 : req[1] ? 4'b0010 : req[2] ? 4'b0100 : req[3] ? 4'b1000 : 4'b0000;

    // Round-robin next grant: token in `last` selects which pick is used.
    wire [3:0] nxt = (last[0] ? sel0 : 4'b0000) |
                     (last[1] ? sel1 : 4'b0000) |
                     (last[2] ? sel2 : 4'b0000) |
                     (last[3] ? sel3 : 4'b0000);

    // Coin value of the winning slot (priority-coded so it is at most 10c).
    wire [5:0] coin = (nxt[0] | nxt[1]) ? 6'd5 : ((nxt[2] | nxt[3]) ? 6'd10 : 6'd0);
    wire [6:0] sum  = {1'b0, credit} + {1'b0, coin};

    always @(posedge clk) begin
        if (step) begin
            gnt <= nxt;
            if (|nxt) begin
                last  <= nxt;
                armed <= 1'b1;   // sticky: set the first time a grant is issued
            end
            if (sum >= 7'd25) begin
                credit   <= sum[5:0] - 6'd25;
                dispense <= 1'b1;
            end else begin
                credit   <= sum[5:0];
                dispense <= 1'b0;
            end
        end
    end

    // Once the arbiter has ever granted, two coin slots must never be
    // granted the accumulator port at the same time.
    always @(*)
        assert (!armed || !(gnt[0] && gnt[2]));
endmodule

module pingpong_tile_buffer (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire       wr_en,
    input  wire       rd_en,
    input  wire [7:0] wr_data,
    output reg  [7:0] rd_data,
    output wire       o_sel
);
    localparam [1:0] LAST = 2'd3;

    // ping-pong double buffer: one half owned by the rasterizer (writer),
    // the other half owned by the shader fetch port (reader)
    reg       sel;                 // master ping-pong select bit
    reg       wr_half, rd_half;    // half currently addressed by each port
    reg [1:0] wcnt, rcnt;          // offset inside the owned half
    reg       wr_full, rd_empty;   // per-half handshake flags
    reg [7:0] mem [0:7];
    integer   i;

    initial begin
        sel     = 1'b0;
        wr_half = 1'b0;
        rd_half = 1'b1;
        wcnt    = 2'd0;
        rcnt    = 2'd0;
        wr_full = 1'b0;
        rd_empty= 1'b1;
        rd_data = 8'h00;
        for (i = 0; i < 8; i = i + 1) mem[i] = 8'h00;
    end

    wire [2:0] wr_addr = {wr_half, wcnt};
    wire [2:0] rd_addr = {rd_half, rcnt};

    wire w_step = i_ce && wr_en && !wr_full;
    wire r_step = i_ce && rd_en && !rd_empty;
    wire swap   = i_ce && wr_full && rd_empty;

    assign o_sel = sel;

    always @(posedge clk) begin
        if (rst) begin
            sel      <= 1'b0;
            wr_half  <= 1'b0;
            rd_half  <= 1'b1;
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b1;
        end else if (swap) begin
            sel      <= ~sel;
            wr_half  <= ~sel;   // writer takes the freshly drained half
            rd_half  <=  sel;   // reader takes the freshly filled half
            wcnt     <= 2'd0;
            rcnt     <= 2'd0;
            wr_full  <= 1'b0;
            rd_empty <= 1'b0;
        end else begin
            if (w_step) begin
                mem[wr_addr] <= wr_data;
                wcnt <= wcnt + 2'd1;
                if (wcnt == LAST) wr_full <= 1'b1;
            end
            if (r_step) begin
                rd_data <= mem[rd_addr];
                rcnt <= rcnt + 2'd1;
                if (rcnt == LAST) rd_empty <= 1'b1;
            end
        end
    end

    // P: whenever both ports perform an access in the same cycle they never
    // touch the same buffer location
    always @(posedge clk)
        if (i_ce && wr_en && rd_en && !wr_full && !rd_empty)
            assert (wr_addr != rd_addr);
endmodule

module credit_rr_arbiter (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle when low
    input  wire [3:0] req,       // four requesters
    input  wire       ret,       // consumer returns one credit
    output reg  [1:0] rr_ptr,    // rotating priority pointer
    output reg  [3:0] grant,     // one-hot grant
    output reg  [3:0] credits,   // credits held by the producer
    output reg  [3:0] outstanding // credits in flight at the consumer
);
    localparam [3:0] TOTAL = 4'd8;

    initial rr_ptr      = 2'd0;
    initial grant       = 4'b0000;
    initial credits     = TOTAL;
    initial outstanding = 4'd0;

    // rotating priority selection: first requester at or after rr_ptr
    wire [1:0] idx = req[rr_ptr]          ? rr_ptr          :
                     req[rr_ptr + 2'd1]   ? rr_ptr + 2'd1   :
                     req[rr_ptr + 2'd2]   ? rr_ptr + 2'd2   :
                                            rr_ptr + 2'd3;

    wire have_credit = (credits != 4'd0);
    wire any_req     = |req;

    // a grant spends one credit; it becomes outstanding until returned
    wire do_grant = i_ce && have_credit && any_req;
    wire do_ret   = i_ce && ret && (outstanding != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            rr_ptr      <= 2'd0;
            grant       <= 4'b0000;
            credits     <= TOTAL;
            outstanding <= 4'd0;
        end else if (i_ce) begin
            grant <= do_grant ? (4'b0001 << idx) : 4'b0000;
            if (do_grant)
                rr_ptr <= idx + 2'd1;

            if (do_grant && !do_ret) begin
                credits     <= credits - 4'd1;
                outstanding <= outstanding + 4'd1;
            end else if (!do_grant && do_ret) begin
                credits     <= credits + 4'd1;
                outstanding <= outstanding - 4'd1;
            end
        end
    end

    // P: whenever nothing is in flight, the producer holds every credit
    always @(posedge clk)
        if (outstanding == 4'd0)
            assert (credits == TOTAL);
endmodule

module handshake (
    input wire clk,
    input wire i_reset,
    input wire i_ce,
    input wire req,
    output wire ack,
    output reg busy
);
    reg [1:0] phase;
    initial phase = 2'b00;
    initial busy = 1'b0;

    always @(posedge clk)
        if (i_reset) begin
            phase <= 2'b00;
            busy <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                2'b00: if (req) begin
                           phase <= 2'b01;
                           busy <= 1'b1;
                       end
                2'b01: phase <= 2'b10;
                2'b10: phase <= 2'b11;
                2'b11: if (ack) begin
                           phase <= 2'b00;
                           busy <= 1'b0;
                       end
            endcase
        end

    assign ack = (phase == 2'b11);

    always @(posedge clk)
        if (busy && !req)
            assert (phase != 2'b00);
endmodule

module lfsr_counter (
    input wire clk,
    input wire rst,
    input wire enable,
    output reg [3:0] lfsr,
    output reg [2:0] countdown
);
    initial begin lfsr = 4'd3; countdown = 3'd0; end

    always @(posedge clk) begin
        if (rst) begin
            lfsr <= 4'd3;
            countdown <= 3'd0;
        end else if (enable) begin
            lfsr <= {lfsr[2:0], lfsr[3] ^ lfsr[1]};
            if (countdown > 3'd0)
                countdown <= countdown - 1;
            else
                countdown <= 3'd3;
        end
    end

    always @(*)
        if (countdown == 3'd0)
            assert (lfsr != 4'd0);
endmodule

module disasm_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire       kick,      // an instruction was successfully decoded
    output reg  [3:0] count,     // cycles since last kick
    output reg        expired,   // decoder hung: limit was reached
    output reg        healthy    // plenty of slack left
);
    localparam [3:0] LIMIT = 4'd10;   // timeout
    localparam [3:0] WARN  = 4'd8;    // slack threshold

    initial begin
        count   = 4'd0;
        expired = 1'b0;
        healthy = 1'b1;
    end

    // next value of the stall counter: kick clears it, otherwise it
    // counts up and saturates at the timeout limit
    wire [3:0] nxt = kick              ? 4'd0  :
                     (count == LIMIT)  ? LIMIT :
                                         count + 4'd1;

    always @(posedge clk) begin
        if (rst) begin
            count   <= 4'd0;
            expired <= 1'b0;
            healthy <= 1'b1;
        end else if (i_ce) begin
            count   <= nxt;
            // sticky until the decoder is kicked
            expired <= kick ? 1'b0 : (expired || (nxt == LIMIT));
            healthy <= (nxt < WARN);
        end
    end

    // P: the timeout flag and the slack flag are never raised together
    always @(posedge clk)
        if (expired)
            assert (!healthy);
endmodule

// In-flight request tracker: an 8-deep shift register of outstanding
// requests plus a separately maintained count of the set bits, with a
// three-step chain monitor (arm -> start -> finish).
module inflight_chain_monitor (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       issue,   // launch a new request into the pipe
    output wire [1:0] phase,
    output wire       busy
);
    // ---- structural state -------------------------------------------------
    reg [7:0] pipe      = 8'd0;   // one bit per in-flight request slot
    reg [3:0] count     = 4'd0;   // separately maintained popcount of pipe

    // ---- three-step chain monitor ----------------------------------------
    reg       arm_seen  = 1'b0;   // step 1: a request was issued
    reg       start_seen= 1'b0;   // step 2: a request was actually in flight
    reg       fin_seen  = 1'b0;   // step 3: a request retired out of stage 7

    wire ins    = issue;
    wire retire = pipe[7];

    always @(posedge clk) begin
        if (rst) begin
            pipe       <= 8'd0;
            count      <= 4'd0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            fin_seen   <= 1'b0;
        end else if (ce) begin
            pipe  <= {pipe[6:0], ins};
            count <= count + {3'd0, ins} - {3'd0, retire};

            if (ins)            arm_seen   <= 1'b1;
            if (count != 4'd0)  start_seen <= 1'b1;
            if (retire)         fin_seen   <= 1'b1;
        end
    end

    assign phase = fin_seen   ? 2'd3 :
                   start_seen ? 2'd2 :
                   arm_seen   ? 2'd1 : 2'd0;
    assign busy  = (count != 4'd0);

    // ---- property: chain precedence, global scope -------------------------
    // A finish can never be observed unless a start was observed, which can
    // never be observed unless an arm was observed.
    always @(posedge clk)
        assert (!fin_seen || (start_seen && arm_seen));

endmodule

// Serial debug-link pattern probe: detects the fixed 4-bit sync pattern 1101
// arriving MSB-first on i_bit, gated by the probe clock-enable i_ce.
// Match progress is tracked twice: as a binary progress counter (prog) and as
// an independently-updated one-hot shadow (hot). A 4-bit capture window (win)
// records the most recent bits seen.
module swd_sync_probe (
    input  wire clk,
    input  wire i_ce,      // probe strobe: low => link idle, all state frozen
    input  wire i_bit,     // serial bit from the debug pin
    output reg  detect     // registered pulse: full pattern just completed
);
    localparam [3:0] PATTERN = 4'b1101;

    reg [2:0] prog;        // match progress, 0..4 (4 == pattern length)
    reg [4:0] hot;         // one-hot shadow of the same progress
    reg [3:0] win;         // last four bits received, MSB = oldest

    initial begin
        prog   = 3'd0;
        hot    = 5'b00001;
        win    = 4'b0000;
        detect = 1'b0;
    end

    // ---- next progress from the binary counter -------------------------
    reg [2:0] nprog;
    always @(*) begin
        case (prog)
            3'd0:    nprog = i_bit ? 3'd1 : 3'd0;              // want 1
            3'd1:    nprog = i_bit ? 3'd2 : 3'd0;              // want 1
            3'd2:    nprog = i_bit ? 3'd2 : 3'd3;              // want 0
            3'd3:    nprog = i_bit ? 3'd4 : 3'd0;              // want 1
            3'd4:    nprog = i_bit ? 3'd2 : 3'd0;              // overlap "1"
            default: nprog = prog;
        endcase
    end

    // ---- next progress from the one-hot shadow (own state only) --------
    reg [4:0] nhot;
    always @(*) begin
        case (hot)
            5'b00001: nhot = i_bit ? 5'b00010 : 5'b00001;
            5'b00010: nhot = i_bit ? 5'b00100 : 5'b00001;
            5'b00100: nhot = i_bit ? 5'b00100 : 5'b01000;
            5'b01000: nhot = i_bit ? 5'b10000 : 5'b00001;
            5'b10000: nhot = i_bit ? 5'b00100 : 5'b00001;
            default:  nhot = 5'b00001;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            prog   <= nprog;
            hot    <= nhot;
            win    <= {win[2:0], i_bit};
            detect <= (nprog == 3'd4);
        end
    end

    // ---- property: two universal relations, globally --------------------
    always @(posedge clk) begin
        assert (detect == hot[4]);
        if (prog == 3'd4)
            assert (win == PATTERN);
    end
endmodule

module fsm_phase_window (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [4:0] o_phase,
    output wire       o_busy
);
    // binary-encoded FSM: only 0..4 are legal encodings, 5..7 are unreachable
    localparam [2:0] S_IDLE   = 3'd0,
                     S_FETCH  = 3'd1,
                     S_DECODE = 3'd2,
                     S_EXEC   = 3'd3,
                     S_WRITE  = 3'd4;

    reg [2:0] state;
    reg [4:0] dec;   // shadow one-hot decode of state
    reg       win;   // window register: opened by a job start, closed at retire

    initial state = S_IDLE;
    initial dec   = 5'b00001;
    initial win   = 1'b0;

    reg [2:0] nstate;
    always @(*) begin
        case (state)
            S_IDLE:   nstate = i_start ? S_FETCH : S_IDLE;
            S_FETCH:  nstate = S_DECODE;
            S_DECODE: nstate = S_EXEC;
            S_EXEC:   nstate = S_WRITE;
            S_WRITE:  nstate = S_IDLE;
            default:  nstate = 3'd5;   // illegal-encoding trap, never taken
        endcase
    end

    // one-hot decode of the next state; illegal encodings decode to all-zero
    wire [4:0] ndec = (nstate == S_IDLE)   ? 5'b00001 :
                      (nstate == S_FETCH)  ? 5'b00010 :
                      (nstate == S_DECODE) ? 5'b00100 :
                      (nstate == S_EXEC)   ? 5'b01000 :
                      (nstate == S_WRITE)  ? 5'b10000 : 5'b00000;

    always @(posedge i_clk) begin
        if (i_rst) begin
            state <= S_IDLE;
            dec   <= 5'b00001;
            win   <= 1'b0;
        end else if (i_ce) begin
            state <= nstate;
            dec   <= ndec;
            if ((state == S_IDLE) && i_start)
                win <= 1'b1;               // Q: a job is launched
            else if (state == S_WRITE)
                win <= 1'b0;               // R: the job retires
        end
    end

    assign o_phase = dec;
    assign o_busy  = win;

    // P: inside the job window the phase decode always names some phase
    always @(posedge i_clk)
        assert (!win || (|dec));
endmodule

module issue_token_bucket (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // pipeline advance / idle when low
    input  wire [1:0] i_req,     // dual-issue: 0, 1 or 2 slots want to issue
    output wire [1:0] o_grant,   // slots actually granted this cycle
    output reg  [3:0] tokens     // credits left in the bucket
);
    localparam [3:0] BURST  = 4'd8;   // bucket capacity
    localparam [2:0] PERIOD = 3'd5;   // refill timer period

    // thermometer-coded shadow of the bucket occupancy
    reg [7:0] bucket;
    // refill timer
    reg [2:0] tick_cnt;

    initial begin
        tokens   = 4'd0;
        bucket   = 8'h00;
        tick_cnt = 3'd0;
    end

    wire       tick    = (tick_cnt == PERIOD);
    wire [1:0] req_c   = (i_req == 2'd3) ? 2'd2 : i_req;

    // grants are limited by available credits
    wire [1:0] n_drain = (tokens >= {2'b00, req_c}) ? req_c : tokens[1:0];

    // refill one credit per timer tick, capped at the burst size
    wire       do_ref  = tick && (tokens != BURST);

    wire [7:0] b_ref   = do_ref ? {bucket[6:0], 1'b1} : bucket;
    wire [7:0] b_nxt   = b_ref >> n_drain;
    wire [3:0] t_nxt   = tokens + (do_ref ? 4'd1 : 4'd0) - {2'b00, n_drain};

    assign o_grant = i_ce ? n_drain : 2'd0;

    always @(posedge clk) begin
        if (rst) begin
            tokens   <= 4'd0;
            bucket   <= 8'h00;
            tick_cnt <= 3'd0;
        end else if (i_ce) begin
            tokens   <= t_nxt;
            bucket   <= b_nxt;
            tick_cnt <= tick ? 3'd0 : (tick_cnt + 3'd1);
        end
    end

    // P: whenever the credit counter reads empty, the thermometer shadow
    //    of the bucket must be empty as well.
    always @(posedge clk)
        if (tokens == 4'd0)
            assert (bucket == 8'h00);

endmodule

module phase_divider_pair (
    input  wire       clk,
    input  wire       ce,       // divider step enable; low = idle, all state held
    input  wire       resync,   // realigns both phase counters, retires the pristine scope
    output reg  [2:0] phase,    // primary phase counter, mod 5
    output reg  [2:0] cnt,      // skewed phase counter, mod 5, built 2 phases ahead
    output reg        en_load,  // divided enable: fires the cycle after phase wraps
    output reg        en_sample,// divided enable: fires the cycle after cnt wraps
    output reg        pristine  // high until the first resync has ever happened
);

    // The skewed counter is constructed 2 phases ahead of the primary phase
    // counter, so the two divided-enable pulses are interleaved by design.
    initial phase     = 3'd0;
    initial cnt       = 3'd2;
    initial en_load   = 1'b0;
    initial en_sample = 1'b0;
    initial pristine  = 1'b1;

    always @(posedge clk) begin
        if (resync) begin
            // hard realignment: both phase counters are slammed to zero, which
            // destroys the constructed skew (and retires the pristine scope)
            phase     <= 3'd0;
            cnt       <= 3'd0;
            en_load   <= 1'b0;
            en_sample <= 1'b0;
            pristine  <= 1'b0;
        end
        else if (ce) begin
            phase     <= (phase == 3'd4) ? 3'd0 : phase + 3'd1;
            cnt       <= (cnt   == 3'd4) ? 3'd0 : cnt   + 3'd1;
            // each divided enable pulses exactly when its phase counter wraps
            en_load   <= (phase == 3'd4);
            en_sample <= (cnt   == 3'd4);
        end
    end

    // Absence: while the divider has never been resynced, the two divided
    // enables are never asserted in the same cycle.
    always @(posedge clk)
        if (pristine)
            assert (!(en_load && en_sample));

endmodule

module pwm_prio_duty (
    input  wire       clk,
    input  wire       ce,
    input  wire [7:0] req,
    output reg        out_r,
    output reg        vld_r
);
    // ---------------- PWM state ----------------
    reg [2:0] cnt;        // period counter 0..7
    reg [3:0] duty;       // active duty value 0..8
    reg [3:0] hi_cnt;     // cycles spent high inside the current period
    reg       shadow_nz;  // shadow: the duty programmed for this period was nonzero
    reg       armed;      // scope: high until the first all-zero request load

    initial begin
        cnt       = 3'd0;
        duty      = 4'd4;   // reset duty is nonzero
        hi_cnt    = 4'd0;
        shadow_nz = 1'b1;   // matches reset duty
        armed     = 1'b1;
        out_r     = 1'b0;
        vld_r     = 1'b0;
    end

    // ---------------- priority encoder over the request vector ----------------
    reg [2:0] idx;
    reg       vld;
    always @(*) begin
        vld = |req;
        if      (req[7]) idx = 3'd7;
        else if (req[6]) idx = 3'd6;
        else if (req[5]) idx = 3'd5;
        else if (req[4]) idx = 3'd4;
        else if (req[3]) idx = 3'd3;
        else if (req[2]) idx = 3'd2;
        else if (req[1]) idx = 3'd1;
        else             idx = 3'd0;
    end

    // requested duty: highest set index + 1, or 0 when no request
    wire [3:0] duty_req = vld ? ({1'b0, idx} + 4'd1) : 4'd0;

    // ---------------- comparator: high exactly while cnt < duty ----------------
    wire out  = ({1'b0, cnt} < duty);
    wire wrap = (cnt == 3'd7);

    always @(posedge clk) begin
        if (ce) begin
            cnt   <= cnt + 3'd1;   // free-running, wraps 7 -> 0
            out_r <= out;          // registered output stage
            vld_r <= vld;
            if (wrap) begin
                // period boundary: latch the new duty and its shadow flag together
                duty      <= duty_req;
                shadow_nz <= (duty_req != 4'd0);
                hi_cnt    <= 4'd0;
                if (duty_req == 4'd0)
                    armed <= 1'b0; // the scope-closing event R
            end else begin
                hi_cnt <= hi_cnt + (out ? 4'd1 : 4'd0);
            end
        end
    end

    // Precedence, in the "before the first zero-duty program" scope:
    // if the output has been high at all inside this period, then a nonzero
    // duty must have been recorded in the shadow flag earlier.
    always @(posedge clk)
        if (armed && hi_cnt != 4'd0)
            assert (shadow_nz);
endmodule

module txn_scoreboard (
    input wire clk,
    input wire ce,
    input wire issue,
    input wire retire_req,
    output reg [2:0] outstanding,
    output reg       armed
);
    // issued/retired transaction counters (scoreboard)
    reg [3:0] issued;
    reg [3:0] retired;
    // bounded-response countdown for the oldest outstanding transaction
    reg [2:0] ttl;

    localparam [2:0] WINDOW = 3'd4;
    localparam [2:0] RELOAD = 3'd5;

    initial begin
        issued      = 4'd0;
        retired     = 4'd0;
        outstanding = 3'd0;
        ttl         = RELOAD;
        armed       = 1'b0;
    end

    // the completion engine is forced to retire when the countdown hits one
    wire force_retire = (outstanding != 3'd0) && (ttl == 3'd1);
    wire do_retire    = (retire_req && (outstanding != 3'd0)) || force_retire;
    wire do_issue     = issue && (outstanding < WINDOW);

    wire [2:0] nxt_out = outstanding
                       + (do_issue  ? 3'd1 : 3'd0)
                       - (do_retire ? 3'd1 : 3'd0);

    always @(posedge clk) begin
        if (ce) begin
            if (do_issue) begin
                issued <= issued + 4'd1;
                armed  <= 1'b1;          // sticky: never cleared
            end
            if (do_retire)
                retired <= retired + 4'd1;

            outstanding <= nxt_out;

            if (do_retire)
                ttl <= RELOAD;           // a completion restarts the window
            else if (nxt_out != 3'd0)
                ttl <= ttl - 3'd1;       // tick down while work is pending
            else
                ttl <= RELOAD;           // idle scoreboard parks at full
        end
    end

    // P: once the scoreboard has ever accepted a transaction, the completion
    // countdown never expires while transactions are still outstanding.
    always @(posedge clk)
        if (armed && (outstanding != 3'd0))
            assert (ttl != 3'd0);
endmodule

module onehot_fsm (
    input wire clk,
    input wire rst,
    input wire enable,
    input wire [1:0] next_state_sel,
    output reg [3:0] state
);
    initial state = 4'b0001;

    always @(posedge clk) begin
        if (rst)
            state <= 4'b0001;
        else if (enable) begin
            case (next_state_sel)
                2'b00: state <= 4'b0001;
                2'b01: state <= 4'b0010;
                2'b10: state <= 4'b0100;
                2'b11: state <= 4'b1000;
            endcase
        end
    end

    always @(posedge clk)
        if (enable) assert (!(state[0] && state[1]) && !(state[0] && state[2]) && !(state[0] && state[3]) && !(state[1] && state[2]) && !(state[1] && state[3]) && !(state[2] && state[3]));

    always @(posedge clk) if (enable) assert (state == 4'b0001 || state == 4'b0010 || state == 4'b0100 || state == 4'b1000);
endmodule

// Tracks outstanding memory requests issued into a 4-deep load/store pipeline.
// A shift register records which pipeline stages hold a live request; a separate
// counter tracks how many are in flight.
module inflight_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       step,   // pipeline advance / clock-enable
    input  wire       req,    // a new request is issued into stage 0
    output wire       f_idle, // no requests outstanding (from the counter)
    output wire       f_full, // all pipeline slots occupied (from the counter)
    output wire       f_any,  // some stage holds a request (from the shifter)
    output wire       f_slot  // some stage is free (from the shifter)
);

    reg [3:0] inflight;
    reg [2:0] cnt;

    initial inflight = 4'b0000;
    initial cnt      = 3'd0;

    // the request leaving the last stage completes this cycle
    wire retire = inflight[3];

    always @(posedge clk) begin
        if (rst) begin
            inflight <= 4'b0000;
            cnt      <= 3'd0;
        end else if (step) begin
            inflight <= {inflight[2:0], req};
            cnt      <= cnt + {2'b00, req} - {2'b00, retire};
        end
    end

    assign f_idle = (cnt == 3'd0);
    assign f_full = (cnt == 3'd4);
    assign f_any  = |inflight;
    assign f_slot = ~(&inflight);

    // P: the counter-derived flags and the shifter-derived flags may never
    // contradict each other -- idle together with an occupied stage, or
    // full together with a free stage.
    always @(posedge clk) assert (!(f_idle && f_any));
    always @(posedge clk) assert (!(f_full && f_slot));

endmodule

module dma_burst_shadow (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // global enable / idle condition
    input  wire       start,
    input  wire [3:0] len,
    output wire       beat_stb,
    output wire       busy_o,
    output wire [3:0] done_o
);
    // burst engine state
    reg        busy       = 1'b0;  // up exactly while beats remain
    reg [3:0]  beats      = 4'd0;  // beats remaining in current burst
    reg [3:0]  beats_done = 4'd0;  // beats already transferred
    reg [3:0]  shadow_len = 4'd0;  // shadow of the length programmed at start

    assign beat_stb = ce && busy;
    assign busy_o   = busy;
    assign done_o   = beats_done;

    always @(posedge clk) begin
        if (rst) begin
            busy       <= 1'b0;
            beats      <= 4'd0;
            beats_done <= 4'd0;
            shadow_len <= 4'd0;
        end else if (ce) begin
            if (busy) begin
                beats      <= beats - 4'd1;
                beats_done <= beats_done + 4'd1;
                busy       <= (beats != 4'd1);
            end else if (start && (len != 4'd0)) begin
                busy       <= 1'b1;
                beats      <= len;
                shadow_len <= len;   // record the earlier programming event
                beats_done <= 4'd0;
            end
        end
    end

    // P (two assertions, both about the shadow of the earlier start):
    // while a beat can still be observed, strictly fewer beats have been done
    // than were programmed earlier; and once idle, exactly the programmed
    // number of beats has been done.
    always @(posedge clk)
        assert (!busy || (beats_done < shadow_len));

    always @(posedge clk)
        assert (busy || (beats_done == shadow_len));
endmodule

module fourphase_occupancy (
    input  wire       clk,
    input  wire       i_ce,          // global enable / idle when low
    input  wire       start,         // master wants a new transaction
    input  wire       dev_ack_ready, // device is ready to raise ack
    output reg        req,
    output reg        ack,
    output reg        busy,
    output reg [2:0]  occ,           // outstanding-transaction occupancy
    output reg        armed
);
    // four-phase handshake sequencer:
    //   phase 0 : idle        (req=0, ack=0)
    //   phase 1 : req raised  (req=1, ack=0)
    //   phase 2 : ack raised  (req=1, ack=1)
    //   phase 3 : req dropped (req=0, ack=1)   -> ack drops, back to idle
    reg [1:0] phase;
    reg       pv;

    initial begin
        phase = 2'd0;
        req   = 1'b0;
        ack   = 1'b0;
        busy  = 1'b0;
        occ   = 3'd0;
        armed = 1'b0;
        pv    = 1'b0;
    end

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                2'd0: begin
                    // request may only be launched from idle
                    if (start) begin
                        req   <= 1'b1;
                        busy  <= 1'b1;      // busy mirrors the phase
                        occ   <= occ + 3'd1;
                        phase <= 2'd1;
                    end
                end
                2'd1: begin
                    // req is held; it may not drop until ack rises
                    if (dev_ack_ready) begin
                        ack   <= 1'b1;
                        phase <= 2'd2;
                    end
                end
                2'd2: begin
                    // ack seen -> now req is allowed to drop
                    req   <= 1'b0;
                    phase <= 2'd3;
                end
                2'd3: begin
                    // ack drops, transaction retires
                    ack   <= 1'b0;
                    busy  <= 1'b0;
                    occ   <= occ - 3'd1;
                    armed <= 1'b1;   // sticky: first completed handshake arms
                    phase <= 2'd0;
                end
            endcase
        end
    end

    // Property: once at least one handshake has completed (armed), every time the
    // busy flag rises the occupancy must not exceed two.
    always @(posedge clk)
        if (pv && armed && $rose(busy))
            assert (occ <= 3'd2);
endmodule

module pingpong_rotbuf (
    input  wire        clk,
    input  wire        step,      // enable / idle when low
    input  wire [15:0] din,
    input  wire [3:0]  amt,
    output reg  [15:0] dout,
    output wire        wr_half,
    output wire        rd_half
);
    // ------------------------------------------------------------------
    // one-cycle barrel rotator (staged shift-by-1/2/4/8 collapses to this)
    // ------------------------------------------------------------------
    wire [31:0] dbl = {din, din};
    wire [15:0] rot = dbl[15:0] >> amt | dbl[31:16] << (16 - amt);

    // ------------------------------------------------------------------
    // ping-pong double buffer: 2 halves of 4 words.
    // address = {half_select, index}
    // ------------------------------------------------------------------
    reg [2:0] waddr;
    reg [2:0] raddr;
    reg [15:0] mem [0:7];
    reg        pv;

    integer i;
    initial begin
        waddr = 3'b000;   // writer starts in half 0
        raddr = 3'b100;   // reader starts in half 1
        dout  = 16'h0000;
        pv    = 1'b0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 16'h0000;
    end

    assign wr_half = waddr[2];
    assign rd_half = raddr[2];

    // each side flips its own half when its own index field wraps
    wire wswap = step && (waddr[1:0] == 2'b11);
    wire rswap = step && (raddr[1:0] == 2'b11);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (step) begin
            mem[waddr] <= rot;
            dout       <= mem[raddr];

            waddr <= {wswap ? ~waddr[2] : waddr[2], waddr[1:0] + 2'b01};
            raddr <= {rswap ? ~raddr[2] : raddr[2], raddr[1:0] + 2'b01};
        end
    end

    // ------------------------------------------------------------------
    // P: whenever the writer migrates up into the high half, the reader
    //     must at that moment be sitting in the low half.
    // ------------------------------------------------------------------
    always @(posedge clk)
        if (pv && $rose(waddr[2]))
            assert (raddr[2] == 1'b0);
endmodule

module saturating_counter (
    input wire clk,
    input wire rst,
    input wire step,
    input wire trigger,
    output reg [1:0] count,
    output reg armed
);
    initial begin
        count = 2'd0;
        armed = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            count <= 2'd0;
            armed <= 1'b0;
        end else begin
            if (trigger)
                armed <= 1'b1;
            if (step && !armed)
                count <= (count == 2'd2) ? 2'd2 : count + 1;
        end
    end

    always @(posedge clk)
        if (armed)
            assert (count <= 2'd2);

    always @(posedge clk)
        if (armed)
            assert (count != 2'd3);
endmodule

module prio_arb_lock (
    input  wire       clk,
    input  wire       ce,
    input  wire [3:0] req,
    output reg  [3:0] grant
);
    // fixed-priority arbiter (master 0 highest) with a lock bit that freezes
    // the current winner until that winner drops its request
    reg       locked;
    reg [1:0] lock_id;
    reg       armed;   // sticky: set the first time a grant is ever issued
    reg       pv;      // past-valid

    initial begin
        grant   = 4'b0000;
        locked  = 1'b0;
        lock_id = 2'd0;
        armed   = 1'b0;
        pv      = 1'b0;
    end

    wire       any = |req;
    wire [1:0] win = req[0] ? 2'd0 :
                     req[1] ? 2'd1 :
                     req[2] ? 2'd2 : 2'd3;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            if (locked) begin
                if (req[lock_id]) begin
                    // hold the locked winner: grant is re-driven from lock_id
                    grant   <= (4'b0001 << lock_id);
                    locked  <= 1'b1;
                    armed   <= 1'b1;
                end else begin
                    // winner released: drop the lock for one cycle
                    grant   <= 4'b0000;
                    locked  <= 1'b0;
                end
            end else begin
                if (any) begin
                    grant   <= (4'b0001 << win);
                    lock_id <= win;
                    locked  <= 1'b1;
                    armed   <= 1'b1;
                end else begin
                    grant   <= 4'b0000;
                    locked  <= 1'b0;
                end
            end
        end
    end

    // Universality, after the arbiter has ever granted (armed):
    // while the lock bit did not change and is held, the grant must not change.
    always @(posedge clk)
        if (pv && armed && locked && $stable(locked))
            assert ($stable(grant));
endmodule

module alu_result_fifo (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       push,
    input  wire       pop,
    input  wire [7:0] a,
    input  wire [7:0] b,
    input  wire [1:0] op,
    output reg  [7:0] o_data,
    output reg        o_zero,
    output reg        o_carry,
    output wire       full,
    output wire       empty,
    output reg  [3:0] count
);
    // ---- FIFO state: separate write/read pointers plus occupancy counter ----
    reg [2:0] wptr, rptr;
    reg [8:0] mem [0:7];   // {carry, result} slices
    integer i;

    initial begin
        wptr    = 3'd0;
        rptr    = 3'd0;
        count   = 4'd0;
        o_data  = 8'h00;
        o_zero  = 1'b1;
        o_carry = 1'b0;
        for (i = 0; i < 8; i = i + 1) mem[i] = 9'd0;
    end

    // ---- 8-bit ALU slice: add, subtract, and, or (carry out in bit 8) ----
    wire [8:0] w_sum = {1'b0, a} + {1'b0, b};
    wire [8:0] w_dif = {1'b0, a} - {1'b0, b};
    reg  [8:0] alu;
    always @(*) begin
        case (op)
            2'b00:   alu = w_sum;
            2'b01:   alu = w_dif;
            2'b10:   alu = {1'b0, a & b};
            default: alu = {1'b0, a | b};
        endcase
    end

    // ---- full/empty derived from the POINTERS, not from the counter ----
    assign full  = ((wptr - rptr) == 3'd5);
    assign empty = (wptr == rptr);

    wire do_push = i_ce && push && !full;
    wire do_pop  = i_ce && pop  && !empty;

    always @(posedge clk) begin
        if (do_push) begin
            mem[wptr] <= alu;
            wptr      <= wptr + 3'd1;
        end
        if (do_pop) begin
            o_data  <= mem[rptr][7:0];
            o_carry <= mem[rptr][8];
            o_zero  <= (mem[rptr][7:0] == 8'h00);
            rptr    <= rptr + 3'd1;
        end
        if (do_push && !do_pop)
            count <= count + 4'd1;
        else if (!do_push && do_pop)
            count <= count - 4'd1;
        else
            count <= count;
    end

    // P: occupancy never exceeds the depth of 5, though the register holds 15
    always @(*) assert (count <= 4'd5);
endmodule

// Serial sequence detector for the fixed pattern 1011 (MSB first).
// prog = length of the longest suffix of the input stream that is a prefix
// of the pattern (KMP style match progress, never exceeds pattern length).
// hist is a shadow register holding the three most recently consumed bits.
// armed is a sticky register set the first time a full match is observed.
module seq_det_1011 (
    input  wire clk,
    input  wire ce,    // idle when low: no state changes at all
    input  wire din,
    output wire match,
    output wire armed_o
);
    reg [2:0] prog;   // match progress, 0..3
    reg [2:0] hist;   // shadow of last three consumed bits, hist[0] = newest
    reg       armed;  // sticky: first full pattern occurrence has happened
    reg       pv;     // past valid

    initial begin
        prog  = 3'd0;
        hist  = 3'b000;
        armed = 1'b0;
        pv    = 1'b0;
    end

    assign match   = ce && (prog == 3'd3) && din;
    assign armed_o = armed;

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            hist <= {hist[1:0], din};
            case (prog)
                3'd0:    prog <= din ? 3'd1 : 3'd0;
                3'd1:    prog <= din ? 3'd1 : 3'd2;
                3'd2:    prog <= din ? 3'd3 : 3'd0;
                3'd3:    prog <= din ? 3'd1 : 3'd2;
                default: prog <= din ? 3'd1 : 3'd0;
            endcase
            if (match)
                armed <= 1'b1;
        end
    end

    // Property: once the detector has armed (a full 1011 was seen earlier),
    // whenever the shadow history of consumed bits did not change, the match
    // progress must not have changed either.
    always @(posedge clk)
        if (pv && armed && $stable(hist))
            assert ($stable(prog));
endmodule

module credit_counter (
    input wire clk,
    input wire rst,
    input wire i_ce,
    input wire increment,
    input wire decrement,
    output reg [2:0] count
);
    reg [1:0] wptr, rptr;
    initial begin wptr = 0; rptr = 0; count = 0; end

    wire do_increment = i_ce && increment && count != 3'd4;
    wire do_decrement = i_ce && decrement && count != 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 0; rptr <= 0; count <= 0;
        end else begin
            if (do_increment) wptr <= wptr + 1;
            if (do_decrement) rptr <= rptr + 1;
            case ({do_increment, do_decrement})
                2'b10:   count <= count + 1;
                2'b01:   count <= count - 1;
                default: count <= count;
            endcase
        end
    end

    always @(posedge clk)
        if (count == 3'd0)
            assert (wptr == rptr);

    always @(posedge clk)
        if (count == 3'd4)
            assert (wptr - rptr == 2'd4);
endmodule

// In-flight tracker for a fixed-latency chart-query render pipeline.
// Each issued query walks a 4-stage valid shift register; occupancy is the
// number of ones currently resident in that shift register.
module query_pipe_tracker (
    input  wire       clk,
    input  wire       ce,        // pipeline advance / idle control
    input  wire       issue,     // a new query is pushed into stage 0
    output wire       retire,    // a rendered result leaves the last stage
    output wire       full,      // tracker says all 4 slots are busy
    output reg  [2:0] occ        // queries in flight
);

    reg [3:0] pipe;              // fixed-latency valid shift register
    reg       ever_issued;       // shadow: an issue has been observed earlier
    reg       armed;             // scope: still before the pipe was ever full

    initial begin
        pipe        = 4'b0000;
        occ         = 3'd0;
        ever_issued = 1'b0;
        armed       = 1'b1;
    end

    assign retire = pipe[3];
    assign full   = (occ == 3'd4);

    always @(posedge clk) begin
        if (ce) begin
            // drain: stage 3 retires, everything shifts, stage 0 takes issue
            pipe <= {pipe[2:0], issue};

            // occupancy bookkeeping: +1 on issue, -1 on retire
            occ  <= occ + {2'b00, issue} - {2'b00, pipe[3]};

            // shadow register for the earlier event
            if (issue) ever_issued <= 1'b1;

            // scope closes the first time the unit reports saturation
            if (full)  armed <= 1'b0;
        end
    end

    // Precedence, before the unit was ever full:
    // if work is in flight now, an issue must have happened earlier.
    always @(posedge clk)
        if (armed && occ != 3'd0)
            assert (ever_issued);

endmodule

module dma_copier_chain (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_clear,
    input  wire [3:0] i_len,
    output wire       o_done,
    output wire       o_busy,
    output wire       o_err
);
    // phase slice codes (gray-ish), each with its stored parity bit
    localparam [1:0] PH_IDLE  = 2'b00,   // parity 0
                     PH_ARMED = 2'b01,   // parity 1
                     PH_BUSY  = 2'b11,   // parity 0
                     PH_DONE  = 2'b10;   // parity 1

    // parity-protected register slice holding the engine phase
    reg [1:0] phase   = PH_IDLE;
    reg       par     = 1'b0;

    // descriptor word counter
    reg [3:0] count   = 4'd0;

    // chain history bits: arm happened, start happened
    reg       h_arm   = 1'b0;
    reg       h_start = 1'b0;

    // slice checker: stored parity must match stored phase
    wire slice_bad = (par != (^phase));

    always @(posedge clk) begin
        if (i_ce) begin
            if (slice_bad) begin
                // corrupted descriptor slice: abort, report done immediately
                phase <= PH_DONE;
                par   <= 1'b1;
            end else begin
                case (phase)
                PH_IDLE:
                    if (i_arm) begin
                        phase   <= PH_ARMED;
                        par     <= 1'b1;
                        count   <= i_len;
                        h_arm   <= 1'b1;
                    end
                PH_ARMED:
                    if (i_start) begin
                        phase   <= PH_BUSY;
                        par     <= 1'b0;
                        h_start <= 1'b1;
                    end
                PH_BUSY:
                    if (count == 4'd0) begin
                        phase <= PH_DONE;
                        par   <= 1'b1;
                    end else begin
                        count <= count - 4'd1;
                    end
                PH_DONE:
                    if (i_clear) begin
                        phase <= PH_IDLE;
                        par   <= 1'b0;
                    end
                endcase
            end
        end
    end

    assign o_done = (phase == PH_DONE);
    assign o_busy = (phase == PH_BUSY);
    assign o_err  = slice_bad;

    // chain precedence, globally: a finish can never be seen unless the
    // arm step and then the start step were actually taken
    always @(posedge clk)
        if (phase == PH_DONE) assert (h_arm);

    always @(posedge clk)
        if (phase == PH_DONE) assert (h_start);
endmodule

module elastic_tag_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       start,      // Q: opens the observation window
    input  wire       stop,       // R: closes the observation window
    input  wire       push,
    input  wire       pop,
    input  wire [3:0] din,
    output wire [3:0] head_data,
    output wire       head_valid,
    output wire       marked_seen
);
    // two-entry elastic buffer: one valid flag per slot, head/tail flags,
    // plus an occupancy counter that mirrors the flags
    reg [1:0] cnt;
    reg       hp, tp;      // head flag / tail flag
    reg       v0, v1;      // per-slot occupancy flags
    reg [3:0] mem0, mem1;

    // window + shadow register for the precedence check
    reg       win;
    reg       seen_hi;

    initial begin
        cnt     = 2'd0;
        hp      = 1'b0;
        tp      = 1'b0;
        v0      = 1'b0;
        v1      = 1'b0;
        mem0    = 4'd0;
        mem1    = 4'd0;
        win     = 1'b0;
        seen_hi = 1'b0;
    end

    // a window may only be opened on an empty buffer; it may be reopened
    wire start_acc = start && !win && (cnt == 2'd0);
    wire stop_acc  = stop && win && !start_acc;

    wire do_push = push && !start_acc && (cnt != 2'd2);
    wire do_pop  = pop  && !start_acc && (cnt != 2'd0);

    assign head_valid  = hp ? v1   : v0;
    assign head_data   = hp ? mem1 : mem0;
    assign marked_seen = seen_hi;

    always @(posedge clk) begin
        if (rst) begin
            cnt     <= 2'd0;
            hp      <= 1'b0;
            tp      <= 1'b0;
            v0      <= 1'b0;
            v1      <= 1'b0;
            win     <= 1'b0;
            seen_hi <= 1'b0;
        end else begin
            if (do_push) begin
                if (tp) begin
                    mem1 <= din;
                    v1   <= 1'b1;
                end else begin
                    mem0 <= din;
                    v0   <= 1'b1;
                end
                tp <= ~tp;
            end

            if (do_pop) begin
                if (hp) v1 <= 1'b0;
                else    v0 <= 1'b0;
                hp <= ~hp;
            end

            cnt <= cnt + (do_push ? 2'd1 : 2'd0) - (do_pop ? 2'd1 : 2'd0);

            if (start_acc) begin
                win     <= 1'b1;
                seen_hi <= 1'b0;
            end else if (stop_acc) begin
                win     <= 1'b0;
            end else if (do_push && win && din[3]) begin
                seen_hi <= 1'b1;
            end
        end
    end

    // Precedence, inside the window: a marked item can only be observed at the
    // head if a marked item was pushed earlier in this same window.
    assert property (!win || !head_valid || !head_data[3] || seen_hi);
endmodule

module credit_pool (
    input  wire clk,
    input  wire cfg,      // one-shot: install the configured credit total
    input  wire send,     // producer spends a credit
    input  wire ret,      // consumer returns a credit
    output wire ok_to_send,
    output wire [3:0] o_credits,
    output wire [3:0] o_outstanding
);
    parameter [3:0] TOTAL = 4'd8;

    // sticky arm register: set the first time the pool is configured, never cleared
    reg       armed = 1'b0;
    // credits held by the producer
    reg [3:0] credits = 4'd0;
    // credits spent and not yet returned
    reg [3:0] outstanding = 4'd0;

    wire do_cfg  = cfg && !armed;
    wire do_send = armed && send && (credits != 4'd0);
    wire do_ret  = armed && ret  && (outstanding != 4'd0);

    always @(posedge clk) begin
        if (do_cfg) begin
            armed       <= 1'b1;
            credits     <= TOTAL;
            outstanding <= 4'd0;
        end else begin
            credits     <= credits     - {3'b000, do_send} + {3'b000, do_ret};
            outstanding <= outstanding + {3'b000, do_send} - {3'b000, do_ret};
        end
    end

    assign ok_to_send    = armed && (credits != 4'd0);
    assign o_credits     = credits;
    assign o_outstanding = outstanding;

    // P: once the pool has been armed, an idle link (nothing outstanding)
    // means every credit is back in the producer's hands.
    always @(posedge clk)
        if (armed && (outstanding == 4'd0))
            assert (credits == TOTAL);
endmodule

// Debug-probe challenge sequencer: a maximal-length LFSR supplies one tick per
// chain step (arm -> start -> finish). The LFSR is seeded non-zero and can never
// enter the all-zeros lockup state, so every FSM advance is accompanied by a
// genuine change of the challenge shift register.
module probe_chain_seq (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    input  wire       arm,
    input  wire       start,
    input  wire       fin,
    output reg  [1:0] stage,
    output reg        pre_done,
    output reg  [3:0] chal
);
    // stage encoding: 0 = IDLE, 1 = ARMED, 2 = RUNNING, 3 = DONE
    reg [3:0] lfsr;
    reg       pv;

    initial lfsr     = 4'b0001;
    initial chal     = 4'b0000;
    initial stage    = 2'd0;
    initial pre_done = 1'b1;   // before-scope: high until the first DONE ever
    initial pv       = 1'b0;

    // x^4 + x^3 + 1 : period 15 over the non-zero states
    wire       fb        = lfsr[3] ^ lfsr[2];
    wire [3:0] lfsr_next = {lfsr[2:0], fb};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            lfsr <= lfsr_next;
            case (stage)
                2'd0: if (arm) begin
                          stage <= 2'd1;
                          chal  <= lfsr;      // latch the challenge word on arm
                      end
                2'd1: if (start) stage <= 2'd2;
                2'd2: if (fin) begin
                          stage    <= 2'd3;   // finish: clears the before-scope
                          pre_done <= 1'b0;
                      end
                default: stage <= 2'd0;
            endcase
        end
    end

    // P: before the first finish has ever been observed, the chain FSM cannot
    //    move unless the challenge shift register moved with it.
    always @(posedge clk)
        if (pv && pre_done && $stable(lfsr))
            assert ($stable(stage));
endmodule

module elastic_profile_buf (
    input wire       i_clk,
    input wire       i_rst,
    input wire       i_push,
    input wire       i_pop,
    input wire [7:0] i_data,
    output wire      o_valid,
    output wire      o_full,
    output wire [7:0] o_data,
    output wire [2:0] o_count
);
    // Two-entry elastic buffer holding profiling samples.
    // Entry 0 is the head, entry 1 is the tail.  v0/v1 are the head/tail
    // occupancy flags; count is a separate occupancy register that is
    // maintained in parallel with the flags.
    reg       v0, v1;
    reg [7:0] d0, d1;
    reg [2:0] count;

    initial v0    = 1'b0;
    initial v1    = 1'b0;
    initial d0    = 8'h00;
    initial d1    = 8'h00;
    initial count = 3'd0;

    // "full" is decided purely by the tail flag
    wire w_full  = v1;
    wire do_push = i_push && !w_full;
    wire do_pop  = i_pop  && v0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            v0    <= 1'b0;
            v1    <= 1'b0;
            d0    <= 8'h00;
            d1    <= 8'h00;
            count <= 3'd0;
        end else if (do_push && do_pop) begin
            // head leaves, new sample becomes the head: occupancy unchanged
            d0    <= i_data;
        end else if (do_push) begin
            if (!v0) begin
                v0 <= 1'b1;
                d0 <= i_data;
            end else begin
                v1 <= 1'b1;
                d1 <= i_data;
            end
            count <= count + 3'd1;
        end else if (do_pop) begin
            // tail slides down into the head slot
            v0    <= v1;
            d0    <= d1;
            v1    <= 1'b0;
            count <= count - 3'd1;
        end
        // i_push = i_pop = 0 : the buffer idles, all state held
    end

    assign o_valid = v0;
    assign o_full  = w_full;
    assign o_data  = d0;
    assign o_count = count;

    // P: whenever the buffer is not reporting full, the recorded occupancy
    // is at most one sample (the 3-bit register would allow up to 7).
    always @(posedge i_clk)
        if (!w_full)
            assert (count <= 3'd1);
endmodule

module hwm_stack_ptr (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_push,
    input  wire       i_pop,
    output wire       o_deep,
    output wire [3:0] o_mark,
    output wire [3:0] o_sp
);
    localparam [3:0] THRESH = 4'd4;

    // stack pointer and its high-water mark
    reg [3:0] sp;
    reg [3:0] hwm;
    reg       mark_deep;   // registered "mark has crossed THRESH" flag
    reg       pv;          // past-valid

    initial sp        = 4'd0;
    initial hwm       = 4'd0;
    initial mark_deep = 1'b0;
    initial pv        = 1'b0;

    wire do_push = i_ce && i_push && !i_pop && (sp != 4'hF);
    wire do_pop  = i_ce && i_pop  && !i_push && (sp != 4'h0);

    wire [3:0] sp_nx  = do_push ? (sp + 4'd1)
                      : (do_pop ? (sp - 4'd1) : sp);

    // the mark never falls below the pointer and only ratchets upward
    wire [3:0] hwm_nx = (sp_nx > hwm) ? sp_nx : hwm;

    always @(posedge clk) begin
        if (i_ce) begin
            sp        <= sp_nx;
            hwm       <= hwm_nx;
            mark_deep <= (hwm_nx >= THRESH);
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_deep = mark_deep;
    assign o_mark = hwm;
    assign o_sp   = sp;

    // Precedence: the deep-mark flag can only rise because the pointer itself
    // has just reached that depth, so the depth must be visible right now.
    always @(posedge clk)
        if (pv && $rose(mark_deep))
            assert (sp >= THRESH);

endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire ce,      // idle condition: ce low freezes all state
    input  wire req,
    input  wire flush,   // the scope event R: first flush clears the chain flags
    output wire grant
);
    localparam LIMIT = 4;

    // sliding window of recent grants plus a mirroring count of ones
    reg [7:0] win;
    reg [3:0] ones;

    // three-step chain: arm -> start -> finish
    reg saw_arm, saw_start, saw_finish;

    // scope register: high until the first flush ever happens
    reg before_flush;

    initial begin
        win          = 8'b0;
        ones         = 4'd0;
        saw_arm      = 1'b0;
        saw_start    = 1'b0;
        saw_finish   = 1'b0;
        before_flush = 1'b1;
    end

    // rate limiter: a grant is only issued while the window is not saturated
    assign grant = req && (ones < LIMIT);

    // the count of ones moves by at most one per sample
    wire [3:0] ones_next = ones + {3'b000, grant} - {3'b000, win[7]};

    // chain milestones, keyed on the occupancy of the window
    wire arm_evt    = ce && (ones_next == 4'd1);
    wire start_evt  = ce && (ones_next == 4'd2);
    wire finish_evt = ce && (ones_next == 4'd4);

    always @(posedge clk) begin
        if (ce) begin
            win  <= {win[6:0], grant};
            ones <= ones_next;
            if (flush) begin
                before_flush <= 1'b0;
                saw_arm      <= 1'b0;
                saw_start    <= 1'b0;
                saw_finish   <= 1'b0;
            end else begin
                if (arm_evt)    saw_arm    <= 1'b1;
                if (start_evt)  saw_start  <= 1'b1;
                if (finish_evt) saw_finish <= 1'b1;
            end
        end
    end

    // Chain precedence, in the scope before the first flush:
    // finish can never be observed unless start and arm already happened.
    assert property (!before_flush || !saw_finish || (saw_start && saw_arm));

endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       start,
    input  wire [3:0] req_len,
    output reg        busy,
    output reg        beat_valid
);
    // beats remaining in the current burst
    reg [3:0] beats;
    // beats already pushed out in the current burst
    reg [3:0] done_cnt;
    // sticky: set the first time a burst is ever launched
    reg       armed;

    // the engine never accepts a burst longer than 5 beats
    wire [3:0] clamped = (req_len > 4'd5) ? 4'd5 : req_len;

    initial begin
        beats      = 4'd0;
        done_cnt   = 4'd0;
        busy       = 1'b0;
        armed      = 1'b0;
        beat_valid = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            beats      <= 4'd0;
            done_cnt   <= 4'd0;
            busy       <= 1'b0;
            armed      <= 1'b0;
            beat_valid <= 1'b0;
        end else if (ce) begin
            beat_valid <= 1'b0;
            if (busy) begin
                // one beat of the burst leaves the engine
                beats      <= beats - 4'd1;
                done_cnt   <= done_cnt + 4'd1;
                busy       <= (beats > 4'd1);
                beat_valid <= 1'b1;
            end else if (start && clamped != 4'd0) begin
                beats    <= clamped;
                done_cnt <= 4'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
            end
        end
    end

    // P: once the engine has ever started a burst, no burst ever delivers
    // more than 5 beats, even though done_cnt is 4 bits wide.
    always @(posedge clk)
        if (armed)
            assert (done_cnt <= 4'd5);
endmodule

// PWM channel for a wire-logic accelerator block.
// Period counter walks 0..PER-1, duty is double buffered at the period edge,
// and high_cnt accumulates the number of high cycles elapsed in the period.
module pwm_channel (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // idle when low: no state changes at all
    input  wire       i_load,
    input  wire [3:0] i_duty,
    output wire       pwm_out,
    output reg        armed
);
    localparam [3:0] PER = 4'd12;

    reg [3:0] cnt;       // period counter, 0 .. PER-1
    reg [3:0] duty;      // active duty, 0 .. PER
    reg [3:0] high_cnt;  // high cycles elapsed so far this period

    initial begin
        cnt      = 4'd0;
        duty     = 4'd0;
        high_cnt = 4'd0;
        armed    = 1'b0;
    end

    // the construct: output high exactly while the counter is below the duty
    assign pwm_out = (cnt < duty);

    wire [3:0] duty_clamped = (i_duty > PER) ? PER : i_duty;
    wire       at_edge      = (cnt == PER - 4'd1);

    always @(posedge clk) begin
        if (rst) begin
            cnt      <= 4'd0;
            duty     <= 4'd0;
            high_cnt <= 4'd0;
            armed    <= 1'b0;
        end else if (i_ce) begin
            if (at_edge) begin
                // period rolls over: new duty takes effect, accumulator clears
                cnt      <= 4'd0;
                high_cnt <= 4'd0;
                armed    <= 1'b1;            // sticky, never cleared
                if (i_load)
                    duty <= duty_clamped;
            end else begin
                cnt      <= cnt + 4'd1;
                high_cnt <= high_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // Property (universality, after the first completed period):
    // the accumulated high time never exceeds the duty, and the live output
    // agrees with the accumulator's headroom.
    always @(posedge clk)
        if (armed)
            assert (high_cnt <= duty);

    always @(posedge clk)
        if (armed)
            assert (pwm_out == (high_cnt < duty));
endmodule

module stack_hwm_limit (
    input  wire       clk,
    input  wire       rst,
    input  wire       push,
    input  wire       pop,
    output reg  [3:0] sp,
    output reg  [3:0] hwm,
    output wire       full
);
    // depth limit is enforced through the ratcheting high-water mark,
    // never through the pointer itself
    localparam [3:0] LIMIT = 4'd10;

    wire [3:0] sp_next = sp + 4'd1;

    assign full = (hwm >= LIMIT);

    initial sp  = 4'd0;
    initial hwm = 4'd0;

    always @(posedge clk) begin
        if (rst) begin
            sp  <= 4'd0;
            hwm <= 4'd0;
        end else if (pop && (sp != 4'd0)) begin
            sp  <= sp - 4'd1;          // mark never falls back
        end else if (push && !full) begin
            sp  <= sp_next;
            if (sp_next > hwm)
                hwm <= sp_next;        // mark only ratchets upward
        end
    end

    // P, part 1: occupancy never exceeds 10 though 4 bits allow 15
    always @(posedge clk)
        assert (sp <= LIMIT);

    // P, part 2: the high-water mark never exceeds 10 either
    always @(posedge clk)
        assert (hwm <= LIMIT);
endmodule

module gray_sync_pointer (
    input wire clk,
    input wire i_ce,
    input wire inc,
    output wire [3:0] o_ptr
);
    // source-domain binary pointer and its registered gray encoding
    reg [3:0] bin;
    reg [3:0] gray_r;
    // two-flop synchronizer carrying the gray pointer to the other domain
    reg [3:0] sync1;
    reg [3:0] sync2;

    initial begin
        bin    = 4'd0;
        gray_r = 4'd0;
        sync1  = 4'd0;
        sync2  = 4'd0;
    end

    wire [3:0] bin_nxt  = inc ? (bin + 4'd1) : bin;
    wire [3:0] gray_nxt = bin_nxt ^ (bin_nxt >> 1);

    always @(posedge clk) begin
        if (i_ce) begin
            bin    <= bin_nxt;
            gray_r <= gray_nxt;
            sync1  <= gray_r;
            sync2  <= sync1;
        end
    end

    assign o_ptr = sync2;

    // difference between the two consecutive samples held in the chain
    wire [3:0] diff = sync1 ^ sync2;

    // P: whenever the synchronizer stages disagree, they disagree in exactly one bit
    always @(posedge clk)
        if (sync1 != sync2)
            assert ((diff & (diff - 4'd1)) == 4'd0);
endmodule

module rr_arb_shadow (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    input  wire       arm,
    input  wire       clr,
    output reg  [3:0] gnt
);
    // round-robin arbiter state
    reg [1:0] ptr;       // last granted line index
    // precedence shadow of the previous grant decision
    reg [3:0] prev_gnt;
    reg [1:0] prev_ptr;
    reg [3:0] hist;      // lines the pointer has rested on since arming
    reg       armed;     // window register: set by arm, cleared by clr

    initial begin
        gnt      = 4'b0000;
        ptr      = 2'd0;
        prev_gnt = 4'b0000;
        prev_ptr = 2'd0;
        hist     = 4'b0000;
        armed    = 1'b0;
    end

    // rotating priority: start just past the last grant
    wire [1:0] c0 = ptr + 2'd1;
    wire [1:0] c1 = ptr + 2'd2;
    wire [1:0] c2 = ptr + 2'd3;
    wire [1:0] c3 = ptr;

    reg       sel_val;
    reg [1:0] sel_idx;
    always @(*) begin
        if (req[c0])      begin sel_val = 1'b1; sel_idx = c0;   end
        else if (req[c1]) begin sel_val = 1'b1; sel_idx = c1;   end
        else if (req[c2]) begin sel_val = 1'b1; sel_idx = c2;   end
        else if (req[c3]) begin sel_val = 1'b1; sel_idx = c3;   end
        else              begin sel_val = 1'b0; sel_idx = 2'd0; end
    end

    // one-hot (or all-zero) next grant, never on a non-requesting line
    wire [3:0] nxt = sel_val ? (4'b0001 << sel_idx) : 4'b0000;

    always @(posedge clk) begin
        if (rst) begin
            gnt      <= 4'b0000;
            ptr      <= 2'd0;
            prev_gnt <= 4'b0000;
            prev_ptr <= 2'd0;
            hist     <= 4'b0000;
            armed    <= 1'b0;
        end else begin
            if (ce) begin
                gnt      <= nxt;
                if (sel_val) ptr <= sel_idx;
                prev_gnt <= gnt;
                prev_ptr <= ptr;
                hist     <= hist | (4'b0001 << ptr);
            end
            // opening the observation window restarts the shadow record
            if (arm && !armed) begin
                armed    <= 1'b1;
                prev_gnt <= 4'b0000;
                prev_ptr <= 2'd0;
                hist     <= 4'b0000;
            end else if (clr) begin
                armed <= 1'b0;
            end
        end
    end

    // after arm, until clr (which may never come): a recorded grant must have
    // been preceded by the pointer standing on that very line
    always @(posedge clk) begin
        if (armed)
            assert (prev_gnt == 4'b0000 || prev_gnt == (4'b0001 << prev_ptr));
        if (armed)
            assert (prev_gnt == 4'b0000 || (hist & prev_gnt) != 4'b0000);
    end
endmodule

// Voice-activity frame accumulator with saturating speech-run counter.
// cnt counts consecutive voiced frames and clamps at MAX=12 (a 4-bit reg
// could hold 15).  peak is a shadow register remembering the largest run
// length ever observed, armed is a sticky flag set the first time a run
// reaches the confirmation threshold, and gate is the speech-active output.
module vad_run_accumulator (
    input  wire       clk,
    input  wire       step,      // frame strobe; low => design idles
    input  wire       voice,     // current frame is above energy threshold
    output reg  [3:0] cnt,
    output reg  [3:0] peak,
    output reg        armed,
    output reg        gate
);
    localparam [3:0] MAX     = 4'd12;
    localparam [3:0] CONFIRM = 4'd8;
    localparam [3:0] OPEN    = 4'd4;

    initial cnt   = 4'd0;
    initial peak  = 4'd0;
    initial armed = 1'b0;
    initial gate  = 1'b0;

    // saturating up-counter, cleared on a silent frame
    wire [3:0] cnt_nxt = voice ? ((cnt == MAX) ? MAX : cnt + 4'd1) : 4'd0;

    always @(posedge clk) begin
        if (step) begin
            cnt <= cnt_nxt;

            // shadow register: highest run length seen so far
            if (cnt_nxt > peak)
                peak <= cnt_nxt;

            // sticky arm: a confirmed speech run has happened at least once
            if (cnt_nxt >= CONFIRM)
                armed <= 1'b1;

            // speech-active output
            gate <= (cnt_nxt >= OPEN);
        end
    end

    // Precedence, in the "after armed" scope: once a confirmed run has been
    // observed, any cycle in which the gate is open must be backed by a shadow
    // peak that already reached the confirmation threshold.
    always @(posedge clk)
        if (armed && gate)
            assert (peak >= CONFIRM);
endmodule

module lfsr_grant_arb (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output reg  [1:0] gnt,
    output wire [4:0] o_state
);
    // Maximal-length 5-bit Galois-style shift register, x^5 + x^3 + 1.
    // Seeded nonzero, so the all-zeros lockup state is unreachable.
    reg [4:0] lfsr;

    initial lfsr = 5'h01;
    initial gnt  = 2'b01;

    wire       fb  = lfsr[4] ^ lfsr[2];
    wire [4:0] nxt = {lfsr[3:0], fb};

    // Pseudo-random round-robin: the low bit of the shift register picks
    // which of the two requesters is granted next cycle.  The all-zeros
    // lockup pattern decodes to the illegal "both owners" encoding.
    wire [1:0] sel = (lfsr == 5'd0) ? 2'b11 :
                     (lfsr[0]      ? 2'b01 : 2'b10);

    always @(posedge clk) begin
        if (rst) begin
            lfsr <= 5'h01;
            gnt  <= 2'b01;
        end else if (i_ce) begin
            lfsr <= nxt;
            gnt  <= sel;
        end
    end

    assign o_state = lfsr;

    // Absence: the two grants are never asserted together.
    always @(*)
        if (gnt[0])
            assert (!gnt[1]);
endmodule

module token_bucket_deadline (
    input  wire clk,
    input  wire i_ce,
    input  wire req,
    output wire grant,
    output wire expired
);
    // burst size of the bucket and the response deadline for one request
    localparam [2:0] BURST   = 3'd4;
    localparam [3:0] TIMEOUT = 4'd6;

    reg [2:0] tokens;    // token bucket, capped at BURST
    reg [1:0] tick_cnt;   // refill timer, counts down, tick at zero
    reg       pending;    // window register: set by accepted request, cleared by grant
    reg [3:0] deadline;   // bounded-response countdown for the pending request

    initial tokens   = BURST;
    initial tick_cnt = 2'd3;
    initial pending  = 1'b0;
    initial deadline = 4'd0;

    wire tick     = (tick_cnt == 2'd0);
    wire do_grant = pending && (tokens != 3'd0);

    assign grant   = i_ce && do_grant;
    assign expired = pending && (deadline == 4'd0);

    // refill timer
    always @(posedge clk) if (i_ce)
        tick_cnt <= tick ? 2'd3 : (tick_cnt - 2'd1);

    // bucket: drains on a grant, refills on a tick, saturates at BURST
    always @(posedge clk) if (i_ce) begin
        if (do_grant && tick)
            tokens <= tokens;                 // one out, one in
        else if (do_grant)
            tokens <= tokens - 3'd1;
        else if (tick && (tokens < BURST))
            tokens <= tokens + 3'd1;
    end

    // request window and its countdown
    always @(posedge clk) if (i_ce) begin
        if (do_grant)
            pending <= 1'b0;
        else if (pending)
            deadline <= deadline - 4'd1;
        else if (req) begin
            pending  <= 1'b1;
            deadline <= TIMEOUT;
        end
    end

    // P: inside the request window the countdown never expires
    always @(posedge clk)
        if (pending) assert (deadline != 4'd0);
endmodule

module credit_ledger (
    input  wire       clk,
    input  wire       rst,
    input  wire       issue,          // producer spends a credit (dispatch a signing request)
    input  wire       ret,            // consumer returns a credit (signature delivered)
    output reg  [3:0] credits_avail,  // credits held by the dispatcher
    output reg  [3:0] credits_out,    // credits outstanding in the signing pipeline
    output reg        hit_hw,         // shadow: outstanding count once reached the high-water mark
    output reg        started         // shadow: at least one request was ever issued
);
    localparam [3:0] TOTAL = 4'd8;
    localparam [3:0] HW    = 4'd4;

    initial credits_avail = TOTAL;
    initial credits_out   = 4'd0;
    initial hit_hw        = 1'b0;
    initial started       = 1'b0;

    // idle when issue and ret are both low (or both high): nothing changes
    wire do_issue = issue && !ret && (credits_avail != 4'd0);
    wire do_ret   = ret && !issue && (credits_out   != 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            credits_avail <= TOTAL;
            credits_out   <= 4'd0;
            hit_hw        <= 1'b0;
            started       <= 1'b0;
        end else begin
            if (do_issue) begin
                credits_avail <= credits_avail - 4'd1;
                credits_out   <= credits_out   + 4'd1;
                started       <= 1'b1;
                if (credits_out >= (HW - 4'd1))
                    hit_hw <= 1'b1;
            end else if (do_ret) begin
                credits_avail <= credits_avail + 4'd1;
                credits_out   <= credits_out   - 4'd1;
            end
        end
    end

    // Precedence, global scope, two assertions sharing one relation:
    //  - if the dispatcher is down to half its credits, the pipeline must have
    //    reached the high-water mark at some earlier point;
    //  - if the dispatcher no longer holds the full budget, some request must
    //    have been issued earlier.
    always @(posedge clk) begin
        if (credits_avail <= HW)
            assert (hit_hw);
        if (credits_avail != TOTAL)
            assert (started);
    end
endmodule

// Fixed-latency packet capture pipeline with an in-flight occupancy tracker.
// A sensor issues a captured packet into a 4-deep fixed-latency staging
// pipeline; the packet emerges four enabled cycles later and is handed to the
// stream encoder.  o_inflight counts packets currently inside the pipeline.
module pkt_inflight_tracker (
    input  wire       clk,
    input  wire       rst,      // synchronous reset
    input  wire       i_ce,     // capture clock enable (low = sensor idle)
    input  wire       i_issue,  // a new packet is pushed into the pipeline
    output reg        o_drain,  // pulses when a packet left the pipeline
    output reg  [2:0] o_inflight
);

    // fixed-latency shift register: one valid bit per pipeline stage
    reg [3:0] pipe;

    initial pipe       = 4'b0000;
    initial o_inflight = 3'd0;
    initial o_drain    = 1'b0;

    // a packet reaching the last stage exits on the next enabled cycle
    wire exits = pipe[3];

    always @(posedge clk) begin
        if (rst) begin
            pipe       <= 4'b0000;
            o_inflight <= 3'd0;
            o_drain    <= 1'b0;
        end else if (i_ce) begin
            pipe       <= {pipe[2:0], i_issue};
            o_inflight <= o_inflight
                        + (i_issue ? 3'd1 : 3'd0)
                        - (exits   ? 3'd1 : 3'd0);
            o_drain    <= exits;
        end
    end

    // P (universality, global): whenever a packet is about to leave the
    // pipeline, the occupancy tracker must not read empty.
    assert property (!pipe[3] || o_inflight != 3'd0);

endmodule

// Kernel task handshake tracker.
// The progress accumulator is kept in two carry-save halves acc_a/acc_b whose
// sum is the true phase count (0=idle, 1=armed, 2=started, 3=finished).
// A tiny FSM (ph_ref) enforces the arm -> start -> finish chain, and sticky
// flags record that each earlier step was really observed.
module cs_chain_tracker (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       i_track,   // Q event: arms the observation scope, sticky
    input  wire       i_arm,
    input  wire       i_start,
    input  wire       i_finish,
    output wire [3:0] o_total,
    output wire       o_done
);
    // carry-save halves of the progress accumulator
    reg [2:0] acc_a, acc_b;
    // redundant direct copy of the phase, used by the sequencer
    reg [2:0] ph_ref;
    // which half receives the next increment
    reg       tog;
    // chain witnesses
    reg       arm_seen, start_seen;
    // sticky scope register (set the first time i_track is seen)
    reg       armed;

    initial begin
        acc_a      = 3'd0;
        acc_b      = 3'd0;
        ph_ref     = 3'd0;
        tog        = 1'b0;
        arm_seen   = 1'b0;
        start_seen = 1'b0;
        armed      = 1'b0;
    end

    // true total recombined from the two halves
    wire [3:0] total = {1'b0, acc_a} + {1'b0, acc_b};
    assign o_total = total;
    assign o_done  = (total == 4'd3);

    // one chain step at a time, in order
    wire adv = i_ce && (((ph_ref == 3'd0) && i_arm)    ||
                        ((ph_ref == 3'd1) && i_start)  ||
                        ((ph_ref == 3'd2) && i_finish));

    always @(posedge clk) begin
        if (rst) begin
            acc_a      <= 3'd0;
            acc_b      <= 3'd0;
            ph_ref     <= 3'd0;
            tog        <= 1'b0;
            arm_seen   <= 1'b0;
            start_seen <= 1'b0;
            armed      <= 1'b0;
        end else begin
            if (i_ce && i_track)
                armed <= 1'b1;

            if (adv) begin
                // split increment: the two halves always re-sum to the phase
                if (tog) acc_b <= acc_b + 3'd1;
                else     acc_a <= acc_a + 3'd1;
                tog    <= ~tog;
                ph_ref <= ph_ref + 3'd1;

                if (ph_ref == 3'd0) arm_seen   <= 1'b1;
                if (ph_ref == 3'd1) start_seen <= 1'b1;
            end
        end
    end

    // Chain precedence, in the sticky "after i_track" scope:
    // a finished accumulation can never be observed unless both the arm and
    // the start steps were witnessed first.
    always @(*)
        if (armed && (total == 4'd3))
            assert (start_seen && arm_seen);
endmodule

// Sliding-window grant rate limiter for an inference-accelerator arbiter.
// A shift register of the last 8 cycles' grants plus a mirrored count of ones.
module window_rate_limiter (
    input  wire clk,
    input  wire ce,      // idle condition: when low, nothing changes
    input  wire req,     // request a grant this cycle
    input  wire flush,   // clear the accounting (credit reset)
    output wire grant,
    output wire full
);
    localparam [3:0] LIMIT = 4'd4;

    // sliding window of recent grants and its mirrored population count
    reg [7:0] win        = 8'd0;
    reg [3:0] ones       = 4'd0;

    // shadow register: saturating count of grants ever issued (since last flush)
    reg [2:0] seen       = 3'd0;

    // scope arming register: high until the first flush ever happens
    reg       pre_flush  = 1'b1;

    // registered throttle indication
    reg       throttled  = 1'b0;

    reg       pv         = 1'b0;

    assign full  = (ones >= LIMIT);
    assign grant = ce && !flush && req && !full;

    always @(posedge clk)
        pv <= 1'b1;

    always @(posedge clk) begin
        if (ce) begin
            if (flush) begin
                seen      <= 3'd0;
                pre_flush <= 1'b0;
                throttled <= 1'b0;
            end else begin
                win  <= {win[6:0], grant};
                ones <= ones + (grant ? 4'd1 : 4'd0) - (win[7] ? 4'd1 : 4'd0);
                if (grant && (seen != 3'd4))
                    seen <= seen + 3'd1;
                throttled <= req && full;
            end
        end
    end

    // Precedence, before-first-flush scope, edge style:
    // the throttle signal may only rise after LIMIT grants have been observed.
    always @(posedge clk)
        if (pv && pre_flush && $rose(throttled))
            assert (seen == 3'd4);
endmodule

// Simple token-lexer FSM: binary-encoded states 0..4, encodings 5..7 unused.
module lex_fsm (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,      // idle when low: all state frozen
    input  wire [1:0] cls,     // 0=escape/backslash, 1=alpha, 2=digit, 3=quote
    output reg  [2:0] st,
    output reg  [2:0] len
);
    localparam [2:0] S_IDLE  = 3'd0;
    localparam [2:0] S_IDENT = 3'd1;
    localparam [2:0] S_NUM   = 3'd2;
    localparam [2:0] S_STR   = 3'd3;
    localparam [2:0] S_ESC   = 3'd4;

    wire [2:0] len_inc = (len == 3'd7) ? 3'd7 : (len + 3'd1);

    initial st  = S_IDLE;
    initial len = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            st  <= S_IDLE;
            len <= 3'd0;
        end else if (ce) begin
            case (st)
                S_IDLE: begin
                    if (cls == 2'd1) begin
                        st  <= S_IDENT;
                        len <= 3'd1;
                    end else if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= 3'd1;
                    end else if (cls == 2'd3) begin
                        st  <= S_STR;
                        len <= 3'd0;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_IDENT: begin
                    if (cls == 2'd1 || cls == 2'd2) begin
                        st  <= S_IDENT;
                        len <= len_inc;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_NUM: begin
                    if (cls == 2'd2) begin
                        st  <= S_NUM;
                        len <= len_inc;
                    end else begin
                        st  <= S_IDLE;
                        len <= 3'd0;
                    end
                end
                S_STR: begin
                    if (cls == 2'd3) begin
                        st  <= S_IDLE;   // closing quote ends the token
                        len <= 3'd0;
                    end else if (cls == 2'd0) begin
                        st  <= S_ESC;    // backslash: next char is literal
                        len <= len;
                    end else begin
                        st  <= S_STR;
                        len <= len_inc;
                    end
                end
                S_ESC: begin
                    st  <= S_STR;
                    len <= len_inc;
                end
                default: begin
                    // unreachable encodings 5..7: recover to IDLE
                    st  <= S_IDLE;
                end
            endcase
        end
    end

    // P: in the IDLE state the accumulated token length is always zero.
    always @(*)
        if (st == 3'd0)
            assert (len == 3'd0);
endmodule

module csa_accumulator (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
    output wire       o_pending,
    output wire       o_exact
);
    // carry-save accumulator: the running total is kept as two halves,
    // a sum half and a carry half, which always add up to the true total.
    reg [7:0] s;      // sum half
    reg [7:0] c;      // carry half (always even by construction)
    reg [7:0] total;  // redundant plain-binary shadow of the same total
    reg       armed;  // sticky: set the first time a nonzero cell is folded in

    initial begin
        s     = 8'd0;
        c     = 8'd0;
        total = 8'd0;
        armed = 1'b0;
    end

    wire [7:0] next_s = s ^ c ^ i_data;
    wire [7:0] next_c = ((s & c) | (s & i_data) | (c & i_data)) << 1;

    always @(posedge clk) begin
        if (i_ce) begin
            s     <= next_s;
            c     <= next_c;
            total <= total + i_data;
            if (i_data != 8'd0)
                armed <= 1'b1;
        end
    end

    // a carry is still outstanding in the redundant representation
    wire pending = (c != 8'd0);
    // the sum half alone already equals the plain-binary total
    wire exact   = (s == total);

    assign o_total   = total;
    assign o_pending = pending;
    assign o_exact   = exact;

    // Once the accumulator has been armed by a first real fold-in, the
    // "carry outstanding" and "sum half already exact" conditions must
    // never be asserted at the same time.
    always @(*)
        if (armed)
            assert (!(pending && exact));
endmodule

module counter_pair (
    input wire clk,
    input wire rst,
    input wire enable,
    output reg [2:0] up_cnt,
    output reg [2:0] down_cnt
);
    initial begin up_cnt = 0; down_cnt = 4; end

    always @(posedge clk) begin
        if (rst) begin
            up_cnt <= 0;
            down_cnt <= 4;
        end else if (enable) begin
            up_cnt <= up_cnt + 1;
            down_cnt <= down_cnt - 1;
        end
    end

    reg pv = 0;
    always @(posedge clk) pv <= 1;

    always @(posedge clk) if (pv) assert (!$rose(up_cnt) || (up_cnt + down_cnt == 3'd4));
    always @(posedge clk) if (pv) assert (!$rose(down_cnt) || (up_cnt + down_cnt == 3'd4));
endmodule

module nest_depth_tracker (
    input  wire       clk,
    input  wire       ce,        // idle when low: no token consumed
    input  wire       tok_open,  // '(' style token
    input  wire       tok_close, // ')' style token
    output reg  [3:0] depth,     // current nesting depth (stack pointer)
    output reg  [3:0] mark       // high-water mark of nesting depth
);
    localparam [3:0] MAXD = 4'd8;

    initial depth = 4'd0;
    initial mark  = 4'd0;

    wire do_push = ce && tok_open && !tok_close && (depth < MAXD);
    wire do_pop  = ce && tok_close && !tok_open && (depth != 4'd0);

    always @(posedge clk) begin
        if (do_push) begin
            depth <= depth + 4'd1;
            // mark never falls, only ratchets upward
            if ((depth + 4'd1) > mark)
                mark <= depth + 4'd1;
        end else if (do_pop) begin
            depth <= depth - 4'd1;
            mark  <= mark;
        end else begin
            depth <= depth;
            mark  <= mark;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Precedence: a non-empty nesting depth observed now must have been
    // preceded by a high-water mark that was already within one of it.
    always @(posedge clk)
        if (pv && (depth != 4'd0))
            assert (depth <= $past(mark) + 4'd1);
endmodule

module tmr_alert_window (
    input  wire       clk,
    input  wire       ce,       // global enable: low => all state frozen
    input  wire       load,     // write a new severity into the redundant bank
    input  wire [3:0] sev_in,
    input  wire       q_open,   // Q: escalation opened  (arms the window)
    input  wire       r_close,  // R: escalation closed  (disarms the window)
    output wire [3:0] voted,
    output wire       in_window
);
    // triple-modular-redundant severity register
    reg [3:0] copy_a;
    reg [3:0] copy_b;
    reg [3:0] copy_c;

    // shadow register: severity recorded at the moment the window opened
    reg [3:0] arm_val;
    // window register: set by Q, cleared by R
    reg       armed;

    initial begin
        copy_a  = 4'b0000;
        copy_b  = 4'b0000;
        copy_c  = 4'b0000;
        arm_val = 4'b0000;
        armed   = 1'b0;
    end

    // bitwise majority voter over the three shadow copies
    wire [3:0] vote = (copy_a & copy_b) | (copy_a & copy_c) | (copy_b & copy_c);

    assign voted     = vote;
    assign in_window = armed;

    // the bank is only rewritten while the window is closed and not opening
    wire do_load = ce && load && !armed && !q_open;

    always @(posedge clk) begin
        if (do_load) begin
            copy_a <= sev_in;
            copy_b <= sev_in;
            copy_c <= sev_in;
        end
        if (ce) begin
            if (r_close) begin
                armed <= 1'b0;
            end else if (q_open) begin
                armed   <= 1'b1;
                arm_val <= copy_a;   // capture from the primary copy
            end
        end
    end

    // P: inside the escalation window, what is voted now must be exactly the
    // severity that was recorded earlier, when the window was opened.
    always @(*)
        if (armed)
            assert (vote == arm_val);

endmodule

module pwm_duty_tracker (
    input  wire       clk,
    input  wire       ce,
    input  wire [3:0] duty_in,
    output reg  [2:0] count,
    output reg  [3:0] duty,
    output reg  [3:0] high_cnt,
    output reg        out
);
    // clamped duty request, latched only at the period boundary
    wire [3:0] duty_c = (duty_in > 4'd8) ? 4'd8 : duty_in;

    initial count    = 3'd0;
    initial duty     = 4'd4;
    initial high_cnt = 4'd0;
    initial out      = 1'b1;   // 0 < 4

    always @(posedge clk) begin
        if (ce) begin
            if (count == 3'd7) begin
                // end of period: restart, adopt new duty
                count    <= 3'd0;
                duty     <= duty_c;
                high_cnt <= 4'd0;
                out      <= (4'd0 < duty_c);
            end else begin
                count    <= count + 3'd1;
                // accumulate one high cycle whenever the output is asserted
                high_cnt <= high_cnt + (out ? 4'd1 : 4'd0);
                out      <= (({1'b0, count} + 4'd1) < duty);
            end
        end
    end

    // P (part 1): while the output is high, every elapsed cycle of this
    // period was a high cycle
    always @(posedge clk)
        if (out) assert (high_cnt == {1'b0, count});

    // P (part 2): once the output has dropped, exactly duty high cycles
    // have been accumulated in this period
    always @(posedge clk)
        if (!out) assert (high_cnt == duty);
endmodule

// Tile-render pixel pipeline pacing: a /5 phase counter feeding a /4 row
// counter, plus an accumulator of paced cycles within one tile (20 steps)
// and a high-water mark of that accumulator.
module tilepipe_div (
    input  wire i_clk,
    input  wire i_ce,        // pipeline advance / idle when low
    output wire o_tile_en,   // divided-enable pulse: fires when the chain wraps
    output wire [4:0] o_peak
);
    // ---- phase counter (divide by 5) ----
    reg [2:0] phase;
    initial   phase = 3'd0;

    // ---- row counter (divide by 4 of the phase wrap) ----
    reg [1:0] row;
    initial   row = 2'd0;

    // ---- accumulated paced cycles inside the current tile ----
    reg [4:0] total;
    initial   total = 5'd0;

    // ---- high-water mark of the accumulator (monotone) ----
    reg [4:0] peak;
    initial   peak = 5'd0;

    reg pv;
    initial pv = 1'b0;

    wire ph_wrap  = (phase == 3'd4);
    wire row_wrap = ph_wrap && (row == 2'd3);

    // accumulator is cleared only by the divided-enable pulse, never by its
    // own value
    wire [4:0] nxt_total = row_wrap ? 5'd0 : (total + 5'd1);

    always @(posedge i_clk) begin
        pv <= 1'b1;
        if (i_ce) begin
            phase <= ph_wrap ? 3'd0 : (phase + 3'd1);
            if (ph_wrap)
                row <= row_wrap ? 2'd0 : (row + 2'd1);
            total <= nxt_total;
            if (nxt_total > peak)
                peak <= nxt_total;
        end
    end

    assign o_tile_en = i_ce && row_wrap;
    assign o_peak    = peak;

    // P: the high-water mark of the tile accumulator never climbs past 19,
    // even though the register is 5 bits wide (would allow 31): once it has
    // reached 19 it must never change again.
    always @(posedge i_clk)
        if (pv && ($past(peak) == 5'd19))
            assert ($stable(peak));
endmodule

module window_rate_limiter (
    input  wire clk,
    input  wire i_rst,
    input  wire i_ce,
    input  wire i_req,
    output wire o_grant
);
    parameter W     = 4;
    parameter LIMIT = 3;

    // sliding window of the last W grant decisions
    reg [W-1:0] win;
    // count of ones that mirrors the window by construction
    reg [2:0]   ones;
    // sticky arm register: set the first time a grant is ever issued
    reg         armed;
    reg         pv;

    initial win   = 0;
    initial ones  = 0;
    initial armed = 0;
    initial pv    = 0;

    // the bit about to leave the window
    wire [2:0] retiring = win[W-1] ? 3'd1 : 3'd0;
    // occupancy of the window once the oldest slot retires
    wire [2:0] eff      = ones - retiring;

    // rate decision is taken from the mirrored count, not from the window
    wire allow = i_req && (eff < LIMIT);

    assign o_grant = i_ce && allow;

    always @(posedge clk) begin
        if (i_rst) begin
            win   <= 0;
            ones  <= 0;
            armed <= 0;
        end else if (i_ce) begin
            win  <= { win[W-2:0], allow };
            ones <= ones - retiring + (allow ? 3'd1 : 3'd0);
            if (allow)
                armed <= 1'b1;
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    // Precedence, after the limiter has armed: a grant observed one cycle ago
    // must have been preceded by a window that was not already saturated, so
    // the window can never be completely full of grants.
    always @(posedge clk)
        if (pv && armed)
            assert (!($past(i_ce) && $past(allow)) || (win != 4'hF));
endmodule

module lfsr_prio_precedence (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    output wire       o_valid,
    output wire [2:0] o_index
);
    // ---------------------------------------------------------------
    // 8-bit Fibonacci LFSR (taps 8,6,5,4) driving an 8-bit request
    // vector.  A nonzero state always maps to a nonzero state, so the
    // all-zeros lockup value is never produced.
    // ---------------------------------------------------------------
    reg [7:0] lfsr;
    reg [7:0] req_q;     // registered request vector (encoder input)
    reg [1:0] req_seen;  // shadow: history of "a request was present"
    reg       val_q;     // registered valid output
    reg [2:0] idx_q;     // registered index output

    initial lfsr     = 8'h01;
    initial req_q    = 8'h01;
    initial req_seen = 2'b11;
    initial val_q    = 1'b1;
    initial idx_q    = 3'd0;

    wire       fb        = lfsr[7] ^ lfsr[5] ^ lfsr[4] ^ lfsr[3];
    wire [7:0] lfsr_next = { lfsr[6:0], fb };

    // combinational priority encoder over the registered request vector
    wire       vld = |req_q;
    wire [2:0] idx = req_q[7] ? 3'd7 :
                     req_q[6] ? 3'd6 :
                     req_q[5] ? 3'd5 :
                     req_q[4] ? 3'd4 :
                     req_q[3] ? 3'd3 :
                     req_q[2] ? 3'd2 :
                     req_q[1] ? 3'd1 : 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            lfsr     <= 8'h01;
            req_q    <= 8'h01;
            req_seen <= 2'b11;
            val_q    <= 1'b1;
            idx_q    <= 3'd0;
        end else if (ce) begin
            lfsr     <= lfsr_next;
            req_q    <= lfsr;
            req_seen <= { req_seen[0], |lfsr };
            val_q    <= vld;
            idx_q    <= idx;
        end
    end

    assign o_valid = val_q;
    assign o_index = idx_q;

    // Precedence: whenever the registered output stage reports a valid
    // index, the shadow history must record that a request bit was
    // actually present earlier in the pipeline.
    assert property (!o_valid || req_seen[1]);
endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       i_ce,     // idle condition: low freezes all state
    input  wire       start,    // Q: opens the status window
    input  wire [3:0] len,      // requested burst length (beats)
    input  wire       ack,      // R: host acknowledges, closes the window
    output reg        busy,
    output reg  [3:0] beats
);
    // shadow register: records the length that was requested earlier
    reg [3:0] req_len;
    // beats actually pushed out so far in the current burst
    reg [3:0] done_cnt;
    // window register: set by start, cleared by ack
    reg       armed;

    initial busy     = 1'b0;
    initial beats    = 4'd0;
    initial req_len  = 4'd0;
    initial done_cnt = 4'd0;
    initial armed    = 1'b0;

    wire accept = start && !armed && (len != 4'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            if (accept) begin
                beats    <= len;
                req_len  <= len;      // shadow capture of the earlier event
                done_cnt <= 4'd0;
                busy     <= 1'b1;
                armed    <= 1'b1;
            end else if (busy) begin
                beats    <= beats - 4'd1;
                done_cnt <= done_cnt + 4'd1;
                busy     <= (beats != 4'd1);
            end else if (armed && ack) begin
                armed    <= 1'b0;
            end
        end
    end

    // P, part 1: inside the window, while beats remain the burst cannot yet have
    // delivered everything that was requested earlier.
    always @(posedge clk)
        if (armed && busy)
            assert (done_cnt < req_len);

    // P, part 2: inside the window, once the engine is no longer busy the
    // delivered count must exactly match the earlier requested length.
    always @(posedge clk)
        if (armed && !busy)
            assert (done_cnt == req_len);
endmodule

module chess_clock_seq_alarm (
    input  wire clk,
    input  wire i_ce,      // clock tick enable; low freezes the whole mechanism
    input  wire sym,       // observed press: 1 = white side, 0 = black side
    output reg  alarm
);
    // match-progress register for the fixed press pattern 1,0,1,1
    // (white, black, white, white) -- the blitz alarm trigger
    reg [2:0] prog;
    // shadow register: latches that the half-way progress (2 symbols) occurred
    reg       seen_half;
    // "before R" scope register: high until the alarm pattern first completes
    reg       before_alarm;

    initial prog         = 3'd0;
    initial seen_half    = 1'b0;
    initial before_alarm = 1'b1;
    initial alarm        = 1'b0;

    reg [2:0] nxt;
    wire match = (prog == 3'd3) && sym;

    always @(*) begin
        case (prog)
            3'd0: nxt = sym ? 3'd1 : 3'd0;
            3'd1: nxt = sym ? 3'd1 : 3'd2;
            3'd2: nxt = sym ? 3'd3 : 3'd0;
            3'd3: nxt = sym ? 3'd0 : 3'd2;  // overlap: "10" survives
            default: nxt = 3'd0;
        endcase
    end

    always @(posedge clk) begin
        if (i_ce) begin
            prog      <= nxt;
            seen_half <= match ? 1'b0 : (seen_half | (nxt == 3'd2));
            alarm     <= match;
            if (match)
                before_alarm <= 1'b0;
        end
    end

    // Precedence, in the scope before the alarm has ever fired:
    // three-quarter progress can only be observed if half progress happened earlier.
    always @(posedge clk)
        assert (!before_alarm || (prog != 3'd3) || seen_half);
endmodule

module debounce_hist_arm (
    input  wire i_clk,
    input  wire i_ce,
    input  wire i_raw,
    output wire o_clean,
    output wire o_armed,
    output wire o_settled
);
    // K identical consecutive samples are required before the clean output flips.
    localparam [2:0] KC = 3'd4;
    localparam       HW = 8;

    reg [2:0]      cnt;     // stability counter, saturates at KC
    reg            sample;  // current candidate level being timed
    reg            clean;   // debounced (committed) level
    reg [HW-1:0]   hist;    // raw sample history, hist[0] is the newest sample
    reg            armed;   // sticky: set the first time the filter commits

    initial cnt    = 3'd0;
    initial sample = 1'b0;
    initial clean  = 1'b0;
    initial hist   = {HW{1'b0}};
    initial armed  = 1'b0;

    always @(posedge i_clk) if (i_ce) begin
        hist <= { hist[HW-2:0], i_raw };
        if (i_raw != sample) begin
            // new level seen: retime from scratch
            sample <= i_raw;
            cnt    <= 3'd0;
        end else if (cnt < KC) begin
            cnt <= cnt + 3'd1;
            if (cnt == (KC - 3'd1)) begin
                // KC identical consecutive samples: commit the level
                clean <= sample;
                armed <= 1'b1;
            end
        end
    end

    assign o_clean   = clean;
    assign o_armed   = armed;
    assign o_settled = (cnt == KC);

    // Universality, after the filter has armed: whenever the stability counter
    // is nonzero the two newest raw samples must agree.
    always @(*)
        if (armed)
            assert ((cnt == 3'd0) || (hist[1] == hist[0]));
endmodule

module handshake_deadline (
    input  wire       clk,
    input  wire       i_ce,      // global enable / idle condition
    input  wire       start,     // upstream wants a parse burst
    input  wire       done,      // target signals completion early
    output wire       req,
    output wire       ack,
    output wire       busy_o,
    output wire       timeout
);
    // four-phase handshake: IDLE -> REQ (req rises) -> ACK (ack rises)
    //                       -> DROP (req drops) -> IDLE (ack drops)
    localparam [1:0] P_IDLE = 2'd0,
                     P_REQ  = 2'd1,
                     P_ACK  = 2'd2,
                     P_DROP = 2'd3;

    reg [1:0] phase = P_IDLE;   // handshake phase
    reg       busy  = 1'b0;     // mirrors the phase by construction
    reg [2:0] cnt   = 3'd4;     // completion deadline countdown

    assign req    = (phase == P_REQ)  || (phase == P_ACK);
    assign ack    = (phase == P_ACK)  || (phase == P_DROP);
    assign busy_o = busy;

    // the deadline has expired while the engine is still engaged
    assign timeout = busy && (cnt == 3'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            case (phase)
                P_IDLE: begin
                    if (start) begin
                        phase <= P_REQ;   // req rises
                        busy  <= 1'b1;
                    end
                end
                P_REQ: begin
                    // req may not drop here; the target must raise ack first.
                    // the deadline forces the ack phase on the last tick,
                    // so the countdown can never run through zero.
                    if (done || cnt <= 3'd1)
                        phase <= P_ACK;   // ack rises
                    else
                        cnt   <= cnt - 3'd1;
                end
                P_ACK: begin
                    phase <= P_DROP;      // req drops, ack still high
                end
                P_DROP: begin
                    phase <= P_IDLE;      // ack drops
                    busy  <= 1'b0;
                    cnt   <= 3'd4;        // rearm the deadline
                end
            endcase
        end
    end

    // P1: the completion deadline never expires while the engine is engaged
    always @(posedge clk)
        assert (!timeout);

    // P2: while a request is outstanding the deadline is a live value
    always @(posedge clk)
        if (phase == 2'd1)
            assert (cnt >= 3'd1 && cnt <= 3'd4);
endmodule

module split_accumulator (
    input  wire       clk,
    input  wire       en,      // accumulate enable (idle when low)
    input  wire       bump,    // desync event: nudges one half only
    input  wire [7:0] v,       // addend
    output wire       halves_equal,
    output wire       total_odd
);
    // Accumulator split into two halves; by construction part_a + part_b == total
    reg [7:0] part_a;
    reg [7:0] part_b;
    reg [7:0] total;   // shadow of the true running sum
    reg       toggle;  // selects which half receives the next addend
    reg       pre_bump; // armed until the first bump event ever occurs

    initial part_a   = 8'd0;
    initial part_b   = 8'd0;
    initial total    = 8'd0;
    initial toggle   = 1'b0;
    initial pre_bump = 1'b1;

    assign halves_equal = (part_a == part_b);
    assign total_odd    = total[0];

    always @(posedge clk) begin
        if (bump) begin
            // breaks the split/total relation on purpose, and disarms the scope
            part_a   <= part_a + 8'd1;
            pre_bump <= 1'b0;
        end else if (en) begin
            if (!toggle)
                part_a <= part_a + v;
            else
                part_b <= part_b + v;
            total  <= total + v;
            toggle <= ~toggle;
        end
    end

    // Absence, in the scope "before the first bump":
    // the halves-balanced flag and the odd-total flag are never both true.
    always @(*)
        assert (!pre_bump || !(halves_equal && total_odd));
endmodule

// Gray-coded write pointer crossing into a second clock domain through a
// two-flop synchronizer, with a shadow register that records the first
// nonzero sample observed on the first synchronizer stage.
module gray_cdc_first_sample (
    input  wire       clk,
    input  wire       ce,      // idle condition: ce low freezes all state
    output wire [3:0] sync_ptr
);
    reg [3:0] wbin;         // binary write pointer (saturating)
    reg [3:0] wgray;        // gray-coded write pointer
    reg [3:0] s1, s2;       // two-flop synchronizer stages
    reg       sh_valid;     // shadow: a nonzero stage-1 sample was seen
    reg [3:0] sh_val;       // shadow: value of that first nonzero sample
    reg       before_first; // scope: high until s2 has ever been nonzero
    reg       pv;           // past-valid

    initial begin
        wbin         = 4'd0;
        wgray        = 4'b0000;
        s1           = 4'b0000;
        s2           = 4'b0000;
        sh_valid     = 1'b0;
        sh_val       = 4'b0000;
        before_first = 1'b1;
        pv           = 1'b0;
    end

    wire [3:0] wbin_nxt = (wbin == 4'hF) ? wbin : (wbin + 4'd1);

    always @(posedge clk) begin
        pv <= 1'b1;
        if (ce) begin
            wbin  <= wbin_nxt;
            wgray <= wbin_nxt ^ (wbin_nxt >> 1);
            s1    <= wgray;
            s2    <= s1;
            if (!sh_valid && (s1 != 4'b0000)) begin
                sh_valid <= 1'b1;
                sh_val   <= s1;
            end
            before_first <= before_first && (s2 == 4'b0000);
        end
    end

    assign sync_ptr = s2;

    wire s2_nz = (s2 != 4'b0000);

    // Precedence, in the scope before the pointer has ever been seen on the
    // far side: when the synchronized pointer first becomes nonzero, that
    // very value must already have been recorded in the shadow register.
    always @(posedge clk)
        if (pv && before_first && $rose(s2_nz))
            assert (sh_valid && (sh_val == s2));
endmodule

module rr_arbiter_insight (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] req,
    output reg  [3:0] grant,
    output reg        gvalid,
    output reg  [3:0] last
);
    // priority token starts just after the last granted line
    wire [3:0] base = {last[2:0], last[3]};

    // unrolled ring scan over two copies of the request vector
    wire [7:0] r8 = {req, req};
    wire [7:0] b8 = {base, base};
    wire [7:0] tok;

    assign tok[0] = b8[0];
    assign tok[1] = b8[1] | (tok[0] & ~r8[0]);
    assign tok[2] = b8[2] | (tok[1] & ~r8[1]);
    assign tok[3] = b8[3] | (tok[2] & ~r8[2]);
    assign tok[4] = b8[4] | (tok[3] & ~r8[3]);
    assign tok[5] = b8[5] | (tok[4] & ~r8[4]);
    assign tok[6] = b8[6] | (tok[5] & ~r8[5]);
    assign tok[7] = b8[7] | (tok[6] & ~r8[6]);

    wire [7:0] g8  = r8 & tok;
    wire [3:0] gnt = g8[3:0] | g8[7:4];

    initial last   = 4'b0001;
    initial grant  = 4'b0000;
    initial gvalid = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            last   <= 4'b0001;
            grant  <= 4'b0000;
            gvalid <= 1'b0;
        end else if (ce) begin
            grant  <= gnt;
            gvalid <= |gnt;
            if (|gnt)
                last <= gnt;
        end
    end

    // P: whenever a grant is outstanding, no two lines are granted together
    always @(posedge clk)
        if (gvalid)
            assert ((grant & (grant - 4'd1)) == 4'd0);
endmodule

module axi_grant_watchdog (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    input  wire [3:0] req,
    input  wire       done,
    output reg        gnt_valid,
    output reg [1:0]  gnt_idx,
    output reg [2:0]  timer,
    output reg [2:0]  elapsed,
    output wire [3:0] o_gnt
);
    // Latency budget granted to an accepted request.
    localparam [2:0] BUDGET = 3'd5;

    // ---------------------------------------------------------------
    // Priority encoder over the request vector: lowest index wins.
    // The encoded index is only meaningful while gnt_valid is set.
    // ---------------------------------------------------------------
    wire       enc_valid = |req;
    wire [1:0] enc_idx   = req[0] ? 2'd0 :
                           req[1] ? 2'd1 :
                           req[2] ? 2'd2 : 2'd3;

    // Retirement of the outstanding grant: either the slave answered,
    // or the budget has been fully consumed.
    wire retire = gnt_valid && (done || ((elapsed == 3'd4) && (timer == 3'd1)));

    assign o_gnt = gnt_valid ? (4'b0001 << gnt_idx) : 4'b0000;

    initial gnt_valid = 1'b0;
    initial gnt_idx   = 2'd0;
    initial timer     = 3'd0;
    initial elapsed   = 3'd0;

    always @(posedge clk) begin
        if (rst) begin
            gnt_valid <= 1'b0;
            gnt_idx   <= 2'd0;
            timer     <= 3'd0;
            elapsed   <= 3'd0;
        end else if (i_ce) begin
            if (!gnt_valid) begin
                if (enc_valid) begin
                    gnt_valid <= 1'b1;
                    gnt_idx   <= enc_idx;
                    timer     <= BUDGET;   // credits left
                    elapsed   <= 3'd0;     // cycles burnt
                end
            end else if (retire) begin
                gnt_valid <= 1'b0;
                timer     <= 3'd0;
                elapsed   <= 3'd0;
            end else begin
                timer   <= timer   - 3'd1;
                elapsed <= elapsed + 3'd1;
            end
        end
    end

    // Bounded response, safety form: the countdown must never reach zero
    // while a grant is still outstanding ...
    always @(posedge clk)
        assert (!gnt_valid || (timer != 3'd0));

    // ... and the elapsed-cycle counter must never run past the budget
    // window while a grant is still outstanding.
    always @(posedge clk)
        assert (!gnt_valid || (elapsed <= 3'd4));
endmodule

module vd_sheet_loader (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    input  wire       i_last_row,
    output wire       o_loading,
    output wire       o_ready,
    output wire [3:0] o_rows
);
    // binary-encoded loader FSM: IDLE/OPEN/HEADER/ROWS/DONE
    // encodings 101, 110, 111 are never entered by construction
    localparam [2:0] S_IDLE   = 3'b000,
                     S_OPEN   = 3'b001,
                     S_HEADER = 3'b010,
                     S_ROWS   = 3'b011,
                     S_DONE   = 3'b100;

    reg [2:0] st;
    reg       loading;
    reg       ready;
    reg [3:0] rows;

    initial st      = S_IDLE;
    initial loading = 1'b0;
    initial ready   = 1'b0;
    initial rows    = 4'd0;

    always @(posedge clk) begin
        if (i_reset) begin
            st      <= S_IDLE;
            loading <= 1'b0;
            ready   <= 1'b0;
            rows    <= 4'd0;
        end else if (i_ce) begin
            case (st)
                S_IDLE: begin
                    if (i_start) begin
                        st      <= S_OPEN;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                    end else begin
                        st      <= S_IDLE;
                        loading <= 1'b0;
                        ready   <= 1'b0;
                    end
                end
                S_OPEN: begin
                    st      <= S_HEADER;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                    rows    <= 4'd0;
                end
                S_HEADER: begin
                    st      <= S_ROWS;
                    loading <= 1'b1;
                    ready   <= 1'b0;
                end
                S_ROWS: begin
                    if (i_last_row) begin
                        st      <= S_DONE;
                        loading <= 1'b0;
                        ready   <= 1'b1;
                    end else begin
                        st      <= S_ROWS;
                        loading <= 1'b1;
                        ready   <= 1'b0;
                        rows    <= rows + 4'd1;
                    end
                end
                S_DONE: begin
                    st      <= S_IDLE;
                    loading <= 1'b0;
                    ready   <= 1'b0;
                end
                default: begin
                    // illegal encoding: parked recovery path, asserts both flags
                    st      <= 3'b110;
                    loading <= 1'b1;
                    ready   <= 1'b1;
                end
            endcase
        end
    end

    assign o_loading = loading;
    assign o_ready   = ready;
    assign o_rows    = rows;

    // P: the loader is never simultaneously loading and ready
    always @(posedge clk)
        assert (!(loading && ready));
endmodule

// Priority arbiter for per-subchannel energy detect flags.
// Stage 0: combinational priority encode of the request vector.
// Stage 1: registered half-occupancy flags + priority-half decision.
// Stage 2: registered valid, registered index (only meaningful while valid),
//          and the two half-band grant flags.
module wifi_pri_grant (
    input  wire       clk,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output reg        o_vld,
    output reg  [2:0] o_idx,
    output reg        o_grant_lo,
    output reg        o_grant_hi
);
    // ---------------- stage 0: combinational priority encoder ------------
    wire req_lo = |i_req[3:0];
    wire req_hi = |i_req[7:4];

    reg [2:0] enc;
    always @(*) begin
        casez (i_req)
            8'b???????1: enc = 3'd0;
            8'b??????10: enc = 3'd1;
            8'b?????100: enc = 3'd2;
            8'b????1000: enc = 3'd3;
            8'b???10000: enc = 3'd4;
            8'b??100000: enc = 3'd5;
            8'b?1000000: enc = 3'd6;
            8'b10000000: enc = 3'd7;
            default:     enc = 3'd0;
        endcase
    end

    // ---------------- stage 1 registers ---------------------------------
    reg       s1_vld;
    reg       s1_req_lo;
    reg       s1_req_hi;
    reg       s1_pri_hi;   // upper half wins only when lower half is empty
    reg [2:0] s1_idx;

    initial begin
        s1_vld    = 1'b0;
        s1_req_lo = 1'b0;
        s1_req_hi = 1'b0;
        s1_pri_hi = 1'b0;
        s1_idx    = 3'd0;
        o_vld      = 1'b0;
        o_idx      = 3'd0;
        o_grant_lo = 1'b0;
        o_grant_hi = 1'b0;
    end

    always @(posedge clk) begin
        if (i_ce) begin
            // stage 1 capture
            s1_vld    <= req_lo | req_hi;
            s1_req_lo <= req_lo;
            s1_req_hi <= req_hi;
            s1_pri_hi <= req_hi && !req_lo;
            s1_idx    <= enc;

            // stage 2 capture
            o_vld      <= s1_vld;
            o_idx      <= s1_idx;
            o_grant_lo <= s1_vld && s1_req_lo;
            o_grant_hi <= s1_vld && s1_pri_hi;
        end
    end

    // P: while the encoded index is valid, the two half-band grants are
    //    never asserted together.
    always @(posedge clk)
        if (o_vld)
            assert (!(o_grant_lo && o_grant_hi));

endmodule

// Tracks in-flight requests in an 8-deep shift register, with a separate
// running count of how many slots are currently occupied.
module inflight_tracker (
    input  wire       clk,
    input  wire       step,     // pipeline advance / idle when low
    input  wire       issue,    // a new request enters slot 0 on this step
    output reg  [7:0] shift,    // occupancy of pipeline slots 0..7
    output reg  [3:0] count,    // number of occupied slots
    output wire       retire,   // request leaving the last slot this step
    output wire       busy
);

    initial shift = 8'b0000_0000;
    initial count = 4'd0;

    assign retire = step && shift[7];
    assign busy   = (count != 4'd0);

    always @(posedge clk) begin
        if (step) begin
            shift <= {shift[6:0], issue};
            count <= count + (issue ? 4'd1 : 4'd0) - (shift[7] ? 4'd1 : 4'd0);
        end
    end

    // P: whenever the occupancy count reads zero, no slot may hold a request.
    always @(*)
        assert (count != 4'd0 || shift == 8'b0000_0000);

endmodule

module csa_accum_parity (
    input  wire       clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_clear,
    input  wire [7:0] i_data,
    output wire [7:0] o_total,
    output wire [7:0] o_ref
);
    // accumulator kept in carry-save form: two halves that always sum to the
    // true running total held in the reference register
    reg [7:0] acc_s = 8'h00;   // sum half
    reg [7:0] acc_c = 8'h00;   // carry half (always even by construction)
    reg [7:0] total = 8'h00;   // plain ripple-carry reference accumulator

    wire [7:0] sum_bits   = acc_s ^ acc_c ^ i_data;
    wire [7:0] maj_bits   = (acc_s & acc_c) | (acc_s & i_data) | (acc_c & i_data);
    wire [7:0] carry_bits = {maj_bits[6:0], 1'b0};

    always @(posedge clk) begin
        if (i_rst) begin
            acc_s <= 8'h00;
            acc_c <= 8'h00;
            total <= 8'h00;
        end else if (i_ce) begin
            if (i_clear) begin
                acc_s <= 8'h00;
                acc_c <= 8'h00;
                total <= 8'h00;
            end else begin
                acc_s <= sum_bits;
                acc_c <= carry_bits;
                total <= total + i_data;
            end
        end
    end

    assign o_total = acc_s + acc_c;
    assign o_ref   = total;

    // P: while the unit is actually accumulating, the low bit of the sum half
    // alone already carries the parity of the true total.
    always @(posedge clk)
        if (i_ce && !i_clear)
            assert (acc_s[0] == total[0]);
endmodule

module gray_shadow_ctr (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,
    output wire [3:0] o_gray,
    output wire [3:0] o_bin
);
    // Binary shadow counter and its gray-coded twin.  The gray register is
    // advanced by the classic single-bit-toggle rule, computed from the gray
    // value alone; the binary shadow is a plain increment.
    reg [3:0] bin;
    reg [3:0] gray;
    reg       pv;

    initial bin  = 4'b0000;
    initial gray = 4'b0000;
    initial pv   = 1'b0;

    // Next gray value: toggle bit 0 when the parity is even, otherwise toggle
    // the bit just above the lowest set bit (with the top bit handling wrap).
    function [3:0] gnext(input [3:0] g);
        begin
            if (!(^g))     gnext = g ^ 4'b0001;
            else if (g[0]) gnext = g ^ 4'b0010;
            else if (g[1]) gnext = g ^ 4'b0100;
            else           gnext = g ^ 4'b1000;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            bin  <= 4'b0000;
            gray <= 4'b0000;
        end else if (i_ce) begin
            bin  <= bin + 4'b0001;
            gray <= gnext(gray);
        end
    end

    always @(posedge clk)
        pv <= 1'b1;

    assign o_gray = gray;
    assign o_bin  = bin;

    // Top bit of the gray word and top bit of the binary shadow: the most
    // significant gray bit is just the most significant binary bit, so neither
    // may move without the other.
    wire g_msb = gray[3];
    wire b_msb = bin[3];

    // P: whenever the gray MSB did not change, the shadow MSB did not change.
    always @(posedge clk)
        if (pv && $stable(g_msb))
            assert ($stable(b_msb));
endmodule

module dma_burst_engine (
    input  wire       clk,
    input  wire       ce,      // global enable: low => all state frozen
    input  wire       start,
    input  wire [4:0] len_in,
    input  wire       resp,    // a beat response returns
    output reg        busy
);
    // beats still to be issued in the current burst
    reg [4:0] beats_rem = 5'd0;
    // outstanding (issued, not yet responded) beats
    reg [3:0] outst     = 4'd0;
    // free issue slots; by construction outst + credits == 4
    reg [3:0] credits   = 4'd4;

    initial busy = 1'b0;

    // burst length is clamped to the engine maximum of 12 beats
    wire [4:0] len_cap = (len_in > 5'd12) ? 5'd12 : len_in;

    wire do_load  = ce && !busy && start && (len_cap != 5'd0);
    wire do_issue = ce &&  busy && (credits != 4'd0);
    wire do_resp  = ce &&  resp && (outst   != 4'd0);

    // beats-remaining counter and busy flag
    always @(posedge clk) begin
        if (do_load) begin
            beats_rem <= len_cap;
            busy      <= 1'b1;
        end else if (do_issue) begin
            beats_rem <= beats_rem - 5'd1;
            if (beats_rem == 5'd1)
                busy <= 1'b0;
        end
    end

    // outstanding / credit bookkeeping
    always @(posedge clk) begin
        if (do_issue && !do_resp) begin
            outst   <= outst   + 4'd1;
            credits <= credits - 4'd1;
        end else if (do_resp && !do_issue) begin
            outst   <= outst   - 4'd1;
            credits <= credits + 4'd1;
        end
    end

    // P: while the engine is busy, at most 4 beats are ever outstanding
    always @(posedge clk)
        if (busy)
            assert (outst <= 4'd4);
endmodule

module sat_watermark_flags (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire       i_inc,
    input  wire       i_clear,
    output wire [3:0] o_count,
    output wire       o_full,
    output wire       o_empty
);
    // saturating up-counter: clamps at MAX = 10, register admits up to 15
    localparam [3:0] MAX = 4'd10;

    reg [3:0] cnt;
    reg       full_f;
    reg       empty_f;

    initial cnt     = 4'd0;
    initial full_f  = 1'b0;
    initial empty_f = 1'b1;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            full_f  <= 1'b0;
            empty_f <= 1'b1;
        end else if (i_ce) begin
            if (i_clear) begin
                cnt     <= 4'd0;
                full_f  <= 1'b0;
                empty_f <= 1'b1;
            end else if (i_inc && (cnt != MAX)) begin
                cnt <= cnt + 4'd1;
                // watermark flags are maintained incrementally, only on the
                // edges where the count actually crosses a boundary
                if (cnt == 4'd0)
                    empty_f <= 1'b0;
                if (cnt == (MAX - 4'd1))
                    full_f <= 1'b1;
            end
        end
    end

    assign o_count = cnt;
    assign o_full  = full_f;
    assign o_empty = empty_f;

    // P: the saturation flag and the zero flag are never asserted together
    always @(posedge i_clk)
        if (!i_rst)
            assert (!(o_full && o_empty));
endmodule

module lex_onehot_esc (
    input wire       i_clk,
    input wire       i_reset,
    input wire       i_ce,
    input wire [7:0] i_char,
    output wire      o_in_string,
    output wire [3:0] o_esc_count
);
    // one-hot lexer state: exactly one bit set by construction
    localparam S_IDLE  = 0;
    localparam S_IDENT = 1;
    localparam S_NUM   = 2;
    localparam S_STR   = 3;
    localparam S_ESC   = 4;

    reg [4:0] st;
    reg [3:0] cnt;   // escape sequences counted in the current string literal
    reg       arm;   // sticky: set the first time a string literal is being scanned
    reg       pv;

    initial st  = 5'b00001;
    initial cnt = 4'd0;
    initial arm = 1'b0;
    initial pv  = 1'b0;

    wire is_q   = (i_char == 8'h22);
    wire is_bs  = (i_char == 8'h5C);
    wire is_dig = (i_char >= 8'h30) && (i_char <= 8'h39);
    wire is_alp = ((i_char | 8'h20) >= 8'h61) && ((i_char | 8'h20) <= 8'h7A);

    reg [4:0] nst;
    reg [3:0] ncnt;

    always @(*) begin
        nst  = st;
        ncnt = cnt;
        if (st[S_IDLE]) begin
            if (is_q) begin
                nst  = 5'b01000;   // open quote: enter string, fresh escape count
                ncnt = 4'd0;
            end else if (is_dig)
                nst = 5'b00100;
            else if (is_alp)
                nst = 5'b00010;
            else
                nst = 5'b00001;
        end else if (st[S_IDENT]) begin
            nst = (is_alp || is_dig) ? 5'b00010 : 5'b00001;
        end else if (st[S_NUM]) begin
            nst = is_dig ? 5'b00100 : 5'b00001;
        end else if (st[S_STR]) begin
            if (is_q) begin
                nst  = 5'b00001;   // close quote: escape count retired
                ncnt = 4'd0;
            end else if (is_bs)
                nst = 5'b10000;    // ESC is reachable only from STR
            else
                nst = 5'b01000;
        end else if (st[S_ESC]) begin
            nst  = 5'b01000;       // ESC always returns to STR
            ncnt = (cnt == 4'd8) ? 4'd8 : (cnt + 4'd1);
        end
    end

    always @(posedge i_clk) begin
        if (i_reset) begin
            st  <= 5'b00001;
            cnt <= 4'd0;
        end else if (i_ce) begin
            st  <= nst;
            cnt <= ncnt;
        end

        if (i_ce && !i_reset && (st[S_STR] || st[S_ESC]))
            arm <= 1'b1;

        pv <= 1'b1;
    end

    assign o_in_string  = st[S_STR] || st[S_ESC];
    assign o_esc_count  = cnt;

    // Universality, in the "after arm" scope, stated about the previous cycle:
    // once a string literal has been seen, the escape counter is always zero
    // whenever the lexer sits in the IDLE state.
    always @(posedge i_clk)
        if (pv && arm)
            assert (!$past(st[S_IDLE]) || ($past(cnt) == 4'd0));
endmodule

module hist_precedence (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_op,     // 0 = add one sample to bin i_sel, 1 = remove one
    input  wire [1:0] i_sel,
    output reg  [5:0] total
);
    // histogram bins
    reg [3:0] bin0, bin1, bin2, bin3;

    // shadow of the earlier event: which bin got the very first sample
    reg [1:0] first_bin;
    reg       saw_sample;

    // scope arming register: high until the first removal aimed at first_bin
    reg       pre_purge;

    // shadow high-water mark of the first-sampled bin's count
    reg [3:0] hi_first;

    initial begin
        bin0       = 4'd0;
        bin1       = 4'd0;
        bin2       = 4'd0;
        bin3       = 4'd0;
        total      = 6'd0;
        first_bin  = 2'd0;
        saw_sample = 1'b0;
        pre_purge  = 1'b1;
        hi_first   = 4'd0;
    end

    wire [3:0] sel_cnt   = (i_sel == 2'd0) ? bin0 :
                           (i_sel == 2'd1) ? bin1 :
                           (i_sel == 2'd2) ? bin2 : bin3;

    wire [3:0] first_cnt = (first_bin == 2'd0) ? bin0 :
                           (first_bin == 2'd1) ? bin1 :
                           (first_bin == 2'd2) ? bin2 : bin3;

    wire do_add = i_ce && !i_op && (total != 6'd31) && (sel_cnt != 4'd15);
    wire do_rem = i_ce &&  i_op && (sel_cnt != 4'd0);
    wire purge  = i_ce &&  i_op && saw_sample && (i_sel == first_bin);

    wire armed  = pre_purge && saw_sample;

    // count the first-sampled bin will hold after this cycle
    wire [3:0] first_nxt =
        (do_add && !saw_sample)                          ? (sel_cnt   + 4'd1) :
        (do_add && saw_sample && (i_sel == first_bin))    ? (first_cnt + 4'd1) :
        (do_rem && saw_sample && (i_sel == first_bin))    ? (first_cnt - 4'd1) :
                                                            first_cnt;

    always @(posedge clk) begin
        if (i_ce) begin
            if (do_add) begin
                total <= total + 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 + 4'd1;
                    2'd1:    bin1 <= bin1 + 4'd1;
                    2'd2:    bin2 <= bin2 + 4'd1;
                    default: bin3 <= bin3 + 4'd1;
                endcase
                if (!saw_sample) begin
                    saw_sample <= 1'b1;
                    first_bin  <= i_sel;
                end
            end else if (do_rem) begin
                total <= total - 6'd1;
                case (i_sel)
                    2'd0:    bin0 <= bin0 - 4'd1;
                    2'd1:    bin1 <= bin1 - 4'd1;
                    2'd2:    bin2 <= bin2 - 4'd1;
                    default: bin3 <= bin3 - 4'd1;
                endcase
            end

            if (purge)
                pre_purge <= 1'b0;

            if (do_add && !saw_sample)
                hi_first <= sel_cnt + 4'd1;
            else if (first_nxt > hi_first)
                hi_first <= first_nxt;
        end
    end

    // P: before any sample has ever been purged from the first-sampled bin,
    // the earlier arrival recorded in the shadow registers must still be
    // accounted for in the total-samples register.
    always @(posedge clk)
        if (armed) assert (total >= 6'd1);

    always @(posedge clk)
        if (armed) assert (total >= {2'b00, hi_first});
endmodule

module json_watchdog (
    input  wire clk,
    input  wire i_ce,      // parser step enable; low = idle, no state changes
    input  wire kick,      // parser signals progress on the document stream
    output reg  expired,   // watchdog fired: no kick within LIMIT steps
    output reg  halted     // parse session shut down after the strike cap
);
    localparam [3:0] LIMIT = 4'd6;

    // stall counter: steps since the last kick
    reg [3:0] timer;
    // registered "timer is one tick short of LIMIT" marker
    reg       pre;
    // how many times the watchdog has fired during this session
    reg [2:0] strikes;

    reg pv; // past-valid

    initial begin
        timer   = 4'd0;
        pre     = 1'b0;
        expired = 1'b0;
        halted  = 1'b0;
        strikes = 3'd0;
        pv      = 1'b0;
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce && !halted) begin
            if (kick) begin
                // parser made progress: rearm the watchdog
                timer   <= 4'd0;
                pre     <= 1'b0;
                expired <= 1'b0;
            end else if (!expired) begin
                if (pre) begin
                    // stall counter reaches the limit: fire, record a strike
                    timer   <= LIMIT;
                    pre     <= 1'b0;
                    expired <= 1'b1;
                    strikes <= strikes + 3'd1;
                    halted  <= ((strikes + 3'd1) == 3'd2);
                end else begin
                    timer <= timer + 4'd1;
                    pre   <= ((timer + 4'd1) == (LIMIT - 4'd1));
                end
            end
            // expired and not kicked: everything frozen until a kick arrives
        end
    end

    // P: the strike counter may only move on the cycle the stall counter moves,
    //    and it never climbs past its cap of two.
    always @(posedge clk)
        if (pv && $stable(timer))
            assert ($stable(strikes) && strikes <= 3'd2);

endmodule

module wifi_radio_owner_fsm (
    input  wire clk,
    input  wire rst,
    input  wire step,      // idle/enable: low freezes all state
    input  wire rx_start,  // preamble detected by the receiver
    input  wire tx_req,    // MAC wants the air for a frame
    output wire radio_tx,  // transmit chain owns the radio
    output wire radio_rx   // receive chain owns the radio
);
    // one-hot MAC air-interface FSM:
    //   bit0 = IDLE, bit1 = RX_FRAME, bit2 = TX_PREAMBLE,
    //   bit3 = TX_DATA, bit4 = ACK_WAIT
    reg [4:0] state;
    initial state = 5'b00001;

    wire s_idle  = state[0];
    wire s_rx    = state[1];
    wire s_txpre = state[2];
    wire s_tx    = state[3];
    wire s_ackw  = state[4];

    // next-state as a per-bit OR of its legal source states
    wire [4:0] nxt;
    assign nxt[0] = (s_idle & ~rx_start & ~tx_req) | s_rx | s_ackw;
    assign nxt[1] = s_idle & rx_start;                 // RX wins the air
    assign nxt[2] = s_idle & tx_req & ~rx_start;       // else start TX ramp
    assign nxt[3] = s_txpre;                           // preamble -> data
    assign nxt[4] = s_tx;                              // data -> wait for ACK

    always @(posedge clk) begin
        if (rst)
            state <= 5'b00001;
        else if (step)
            state <= nxt;
    end

    // decoded radio ownership
    assign radio_tx = s_txpre | s_tx;
    assign radio_rx = s_rx    | s_ackw;

    // P: the transmit and receive chains never own the radio together
    always @(*)
        assert (!(radio_tx && radio_rx));
endmodule

// Credit-managed transfer engine: three credit pools, one per chain step.
// A credit is spent on ARM, handed on at START and returned by the consumer
// at FINISH.  Total credits in the system is fixed at TOTAL by construction.
module credit_chain (
    input  wire clk,
    input  wire i_ce,      // global enable: low => the engine idles
    input  wire i_arm,
    input  wire i_start,
    input  wire i_done,
    input  wire i_flush,
    output wire o_fin_seen,
    output wire o_busy
);
    localparam [3:0] TOTAL = 4'd3;

    // ---- credit counter: credits held + credits in each stage == TOTAL ----
    reg [3:0] free_cr;    // credits held by the producer
    reg [3:0] armed_cr;   // credits spent on ARM, awaiting START
    reg [3:0] busy_cr;    // credits outstanding at the consumer

    // ---- chain history (arm -> start -> finish) ----
    reg ever_arm;
    reg ever_start;
    reg ever_fin;

    // ---- before-flush scope register: starts high, cleared by first flush ----
    reg nf;

    initial begin
        free_cr    = TOTAL;
        armed_cr   = 4'd0;
        busy_cr    = 4'd0;
        ever_arm   = 1'b0;
        ever_start = 1'b0;
        ever_fin   = 1'b0;
        nf         = 1'b1;
    end

    wire do_flush = i_ce &&  i_flush;
    wire do_arm   = i_ce && !i_flush && i_arm   && (free_cr  != 4'd0);
    wire do_start = i_ce && !i_flush && i_start && (armed_cr != 4'd0);
    wire do_fin   = i_ce && !i_flush && i_done  && (busy_cr  != 4'd0);

    always @(posedge clk) begin
        if (do_flush) begin
            // all credits are recalled to the producer; the chain record for
            // this session is dropped, the finish record is kept.
            free_cr    <= TOTAL;
            armed_cr   <= 4'd0;
            busy_cr    <= 4'd0;
            ever_arm   <= 1'b0;
            ever_start <= 1'b0;
            nf         <= 1'b0;
        end else if (i_ce) begin
            free_cr  <= free_cr  - do_arm   + do_fin;
            armed_cr <= armed_cr + do_arm   - do_start;
            busy_cr  <= busy_cr  + do_start - do_fin;
            if (do_arm)   ever_arm   <= 1'b1;
            if (do_start) ever_start <= 1'b1;
            if (do_fin)   ever_fin   <= 1'b1;
        end
    end

    assign o_fin_seen = ever_fin;
    assign o_busy     = (busy_cr != 4'd0);

    // Chain precedence, in the before-flush scope: a FINISH can never have been
    // observed unless an ARM and a START were observed first.
    always @(*)
        if (nf)
            assert (!ever_fin || (ever_arm && ever_start));
endmodule

// Multi-zone thermostat front end with hysteresis and a power budget.
// The active-zone mask is a parity protected register slice; a maintained
// occupancy counter and a remaining-budget counter track it.
module zone_heat_budget (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,      // idle when low: all state frozen
    input  wire [2:0] i_zone,    // zone under consideration this cycle
    input  wire [7:0] i_temp,    // measured temperature of that zone
    output wire       o_fault,   // parity mismatch on the zone slice
    output wire [3:0] o_nact,
    output wire [3:0] o_budget
);
    parameter [7:0] T_LOW  = 8'd40;   // below this, zone asks for heat
    parameter [7:0] T_HIGH = 8'd60;   // above this, zone releases heat
    localparam [3:0] BUDGET = 4'd4;   // at most 4 heaters may run at once

    // ---- parity protected register slice -------------------------------
    reg [7:0] zone;    // one bit per zone heater
    reg       zpar;    // parity bit covering zone
    initial   zone = 8'h00;
    initial   zpar = 1'b0;

    // ---- bookkeeping registers -----------------------------------------
    reg [3:0] nact;    // number of heaters currently on
    reg [3:0] budget;  // remaining power slots
    initial   nact   = 4'd0;
    initial   budget = BUDGET;

    wire fault = (zpar != (^zone));
    assign o_fault  = fault;
    assign o_nact   = nact;
    assign o_budget = budget;

    // hysteresis: nothing happens inside the dead band, so no chattering
    wire req_on  = i_ce && !fault && (i_temp <  T_LOW);
    wire req_off = i_ce && !fault && (i_temp >  T_HIGH);

    wire do_on  = req_on  && !zone[i_zone] && (budget != 4'd0);
    wire do_off = req_off &&  zone[i_zone];

    always @(posedge i_clk) begin
        if (i_rst) begin
            zone   <= 8'h00;
            zpar   <= 1'b0;
            nact   <= 4'd0;
            budget <= BUDGET;
        end else if (do_on) begin
            zone[i_zone] <= 1'b1;
            zpar         <= ~zpar;      // one data bit flips, parity flips
            nact         <= nact + 4'd1;
            budget       <= budget - 4'd1;
        end else if (do_off) begin
            zone[i_zone] <= 1'b0;
            zpar         <= ~zpar;
            nact         <= nact - 4'd1;
            budget       <= budget + 4'd1;
        end
    end

    wire heating = (zone != 8'h00);

    // P: whenever any heater is running, occupancy never exceeds the
    //    power budget of 4 (the counter is 4 bits wide).
    always @(posedge i_clk)
        if (heating)
            assert (nact <= 4'd4);
endmodule

module notebook_cell_arbiter (
    input  wire       clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire [7:0] i_req,
    output wire [2:0] o_idx,
    output wire       o_valid
);
    // Stage 1: registered priority-encoder result
    reg [2:0] idx;
    reg       valid;
    // Stage 2: exported result (index only meaningful while valid2 is set)
    reg [2:0] idx2;
    reg       valid2;
    // Shadow register: sticky history of every cell that has ever requested
    reg [7:0] hist;
    // Sticky arm: set the first time any cell requests service
    reg       arm;

    initial idx    = 3'd0;
    initial valid  = 1'b0;
    initial idx2   = 3'd0;
    initial valid2 = 1'b0;
    initial hist   = 8'h00;
    initial arm    = 1'b0;

    function [2:0] penc(input [7:0] r);
        begin
            if      (r[0]) penc = 3'd0;
            else if (r[1]) penc = 3'd1;
            else if (r[2]) penc = 3'd2;
            else if (r[3]) penc = 3'd3;
            else if (r[4]) penc = 3'd4;
            else if (r[5]) penc = 3'd5;
            else if (r[6]) penc = 3'd6;
            else if (r[7]) penc = 3'd7;
            else           penc = 3'd0;
        end
    endfunction

    always @(posedge clk) begin
        if (i_reset) begin
            idx    <= 3'd0;
            valid  <= 1'b0;
            idx2   <= 3'd0;
            valid2 <= 1'b0;
            hist   <= 8'h00;
            arm    <= 1'b0;
        end else if (i_ce) begin
            // stage 2 takes last cycle's encode
            idx2   <= idx;
            valid2 <= valid;
            // stage 1 encodes the current request vector
            idx    <= penc(i_req);
            valid  <= |i_req;
            // shadow history grows in the same cycle as the encode
            hist   <= hist | i_req;
            if (|i_req)
                arm <= 1'b1;
        end
    end

    assign o_idx   = idx2;
    assign o_valid = valid2;

    // Precedence, after arm: a published index must name a cell that
    // requested service at some earlier time.
    always @(posedge clk)
        if (arm && valid2)
            assert (hist[idx2]);
endmodule

module pwm_duty_accum (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire [3:0] duty_in,
    output wire       pwm_out,
    output wire [3:0] on_cycles
);
    // 8-cycle PWM period: cnt runs 0..7, output high exactly while cnt < duty.
    localparam [2:0] PERIOD_MAX = 3'd7;

    reg [2:0] cnt    = 3'd0;   // period counter
    reg [3:0] duty   = 4'd0;   // duty register, clamped to 0..8
    reg [3:0] on_cnt = 4'd0;   // high cycles accumulated so far this period

    // structural output: high exactly while the period counter is below duty
    assign pwm_out   = ({1'b0, cnt} < duty);
    assign on_cycles = on_cnt;

    always @(posedge clk) begin
        if (rst) begin
            cnt    <= 3'd0;
            duty   <= 4'd0;
            on_cnt <= 4'd0;
        end else if (ce) begin
            if (cnt == PERIOD_MAX) begin
                // period boundary: restart counter, latch new duty, clear accumulator
                cnt    <= 3'd0;
                duty   <= (duty_in > 4'd8) ? 4'd8 : duty_in;
                on_cnt <= 4'd0;
            end else begin
                cnt    <= cnt + 3'd1;
                on_cnt <= on_cnt + (pwm_out ? 4'd1 : 4'd0);
            end
        end
    end

    // P: the accumulated high time within a period never exceeds the duty setting
    always @(posedge clk)
        assert (on_cnt <= duty);
endmodule

module gray_profile_bucket (
    input  wire       i_clk,
    input  wire       i_reset,
    input  wire       i_ce,
    input  wire       i_start,
    output wire [3:0] o_gray,
    output wire       o_hi_bucket,
    output wire       o_lo_bucket,
    output wire       o_armed
);
    // binary sample counter and its gray-coded shadow
    reg [3:0] bin;
    reg [3:0] gray;

    // profiling bucket flags, sampled from the two representations
    reg       flag_hi;   // sampled from the gray view
    reg       flag_lo;   // sampled from the binary view

    // sticky arming register: set the first time a profiling run starts
    reg       armed;

    initial bin     = 4'd0;
    initial gray    = 4'd0;
    initial flag_hi = 1'b0;
    initial flag_lo = 1'b0;
    initial armed   = 1'b0;

    wire [3:0] bin_next = bin + 4'd1;

    always @(posedge i_clk) begin
        if (i_reset) begin
            bin     <= 4'd0;
            gray    <= 4'd0;
            flag_hi <= 1'b0;
            flag_lo <= 1'b0;
            armed   <= 1'b0;
        end else if (i_ce) begin
            bin     <= bin_next;
            gray    <= bin_next ^ (bin_next >> 1);
            // hi bucket recognised from the gray encoding of sample 8
            flag_hi <= (gray == 4'b1100);
            // lo bucket recognised directly from the binary shadow
            flag_lo <= (bin < 4'd8);
            if (i_start)
                armed <= 1'b1;
        end
    end

    assign o_gray      = gray;
    assign o_hi_bucket = flag_hi;
    assign o_lo_bucket = flag_lo;
    assign o_armed     = armed;

    // Absence, in the "after arming" scope: once a profiling run has been
    // started, a sample can never be reported in the high bucket and the
    // low bucket at the same time.
    always @(posedge i_clk)
        if (armed && flag_hi)
            assert (!flag_lo);
endmodule

// Sliding-window grant rate limiter: an 8-cycle shift register of recent
// grants plus an occupancy counter that mirrors its population count.
// A grant may only be issued if no grant occurred in the last two cycles,
// which spaces grants at least 3 cycles apart and therefore caps the
// occupancy of the 8-deep window at 3, far below the 4-bit counter range.
module grant_window_limiter (
    input  wire       clk,
    input  wire       ce,      // idle when low: no state changes
    input  wire       req,
    output wire       grant,
    output reg  [7:0] win,
    output reg  [3:0] ones
);

    reg armed = 1'b0;   // sticky: set the first time a grant is issued
    reg pv    = 1'b0;   // past-valid

    initial win  = 8'b0000_0000;
    initial ones = 4'd0;

    // spacing rule: nothing granted in the two most recent slots
    wire allow = (win[1:0] == 2'b00);
    wire g     = ce && req && allow;

    assign grant = g;

    always @(posedge clk) begin
        if (ce) begin
            win  <= {win[6:0], g};
            ones <= ones + (g ? 4'd1 : 4'd0) - (win[7] ? 4'd1 : 4'd0);
        end
        if (g)
            armed <= 1'b1;
        pv <= 1'b1;
    end

    // Bounded existence, at most 3, in the scope after the first grant.
    always @(posedge clk)
        if (pv && armed)
            assert ((ones <= 4'd3) && ($past(ones) <= 4'd3));

endmodule

module counter (
    input wire clk,
    input wire rst,
    input wire enable,
    input wire trigger,
    output reg [3:0] up_count,
    output reg [3:0] down_count,
    output reg arm
);
    initial begin up_count = 4'd0; down_count = 4'd5; arm = 1'b0; end

    always @(posedge clk) begin
        if (rst) begin
            up_count <= 4'd0; down_count <= 4'd5; arm <= 1'b0;
        end else begin
            if (trigger && !arm) arm <= 1'b1;
            if (enable) begin
                up_count <= up_count + 1;
                down_count <= down_count - 1;
            end
        end
    end

    always @(*)
        if (arm)
            assert (up_count != down_count);
endmodule

module skid_parity_window (
    input  wire       clk,
    input  wire       rst,
    input  wire       i_ce,        // stage enable: low => full idle
    input  wire       i_valid,
    input  wire [7:0] i_data,
    input  wire       i_dready,    // downstream ready
    input  wire       i_close,     // closes the observation window
    output wire       o_ready,
    output reg        o_valid,
    output reg  [7:0] o_data
);

    // ---- skid buffer stage state ----
    reg        stall;      // skid slot occupied
    reg  [7:0] skid;       // buffered word (meaningful only while stall)
    reg        skid_par;   // shadow parity of the buffered word

    reg        o_par;      // shadow parity of the presented word

    // ---- observation window (opened by a skid release, closed by i_close) ----
    reg        win;
    reg  [7:0] acc_data;    // xor of words released inside the window
    reg        acc_par;     // xor of their shadow parities

    initial begin
        stall    = 1'b0;
        skid     = 8'h00;
        skid_par = 1'b0;
        o_valid  = 1'b0;
        o_data   = 8'h00;
        o_par    = 1'b0;
        win      = 1'b0;
        acc_data = 8'h00;
        acc_par  = 1'b0;
    end

    assign o_ready = !stall;

    wire do_release = i_ce &&  stall &&  i_dready;
    wire do_direct  = i_ce && !stall &&  i_valid && (i_dready || !o_valid);
    wire do_capture = i_ce && !stall &&  i_valid && o_valid && !i_dready;
    wire do_drop    = i_ce && !stall && !i_valid && i_dready && o_valid;

    always @(posedge clk) begin
        if (rst) begin
            stall    <= 1'b0;
            skid     <= 8'h00;
            skid_par <= 1'b0;
            o_valid  <= 1'b0;
            o_data   <= 8'h00;
            o_par    <= 1'b0;
            win      <= 1'b0;
            acc_data <= 8'h00;
            acc_par  <= 1'b0;
        end else begin
            // datapath
            if (do_release) begin
                o_valid <= 1'b1;
                o_data  <= skid;
                o_par   <= skid_par;
                stall   <= 1'b0;
            end else if (do_direct) begin
                o_valid <= 1'b1;
                o_data  <= i_data;
                o_par   <= ^i_data;
            end else if (do_capture) begin
                stall    <= 1'b1;
                skid     <= i_data;
                skid_par <= ^i_data;
            end else if (do_drop) begin
                o_valid <= 1'b0;
            end

            // window: opened by a release, closed by i_close
            if (i_ce) begin
                if (i_close)         win <= 1'b0;
                else if (do_release) win <= 1'b1;
            end

            // in-window accumulation of released words
            if (do_release) begin
                if (win) begin
                    acc_data <= acc_data ^ skid;
                    acc_par  <= acc_par  ^ skid_par;
                end else begin
                    acc_data <= skid;
                    acc_par  <= skid_par;
                end
            end
        end
    end

    // ---- property: inside the window, both shadow parities track their words ----
    always @(posedge clk) begin
        if (win) begin
            assert (o_par   == (^o_data));
            assert (acc_par == (^acc_data));
        end
    end

endmodule

module lock_arbiter_occ (
    input  wire       i_clk,
    input  wire       i_rst,
    input  wire       i_ce,
    input  wire [3:0] i_req,
    output wire [3:0] o_grant,
    output wire       o_busy
);
    // fixed-priority arbiter with a lock bit that freezes the winner
    reg [3:0] grant;
    reg       lock;
    // shadow occupancy counter: how many grants are currently outstanding
    reg [2:0] occ;

    initial grant = 4'b0000;
    initial lock  = 1'b0;
    initial occ   = 3'd0;

    wire        busy    = (grant != 4'b0000);
    wire        any_req = (i_req != 4'b0000);

    // fixed priority: channel 0 highest
    wire [3:0] pri_grant = i_req[0] ? 4'b0001 :
                           i_req[1] ? 4'b0010 :
                           i_req[2] ? 4'b0100 :
                           i_req[3] ? 4'b1000 : 4'b0000;

    // while locked, the current winner keeps the bus as long as it still asks
    wire holding = busy && lock && ((grant & i_req) != 4'b0000);

    always @(posedge i_clk) begin
        if (i_rst) begin
            grant <= 4'b0000;
            lock  <= 1'b0;
            occ   <= 3'd0;
        end else if (i_ce) begin
            if (busy) begin
                if (!holding) begin
                    // winner released: drop the grant and free the slot
                    grant <= 4'b0000;
                    lock  <= 1'b0;
                    occ   <= occ - 3'd1;
                end
            end else if (any_req) begin
                // bus free: award it and lock it
                grant <= pri_grant;
                lock  <= 1'b1;
                occ   <= occ + 3'd1;
            end
        end
    end

    assign o_grant = grant;
    assign o_busy  = busy;

    // at most one grant may be outstanding at any time
    always @(*)
        assert (occ <= 3'd1);
endmodule

module pwm_precedence (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [3:0] duty_in,
    output wire       o_pwm,
    output wire       o_period_start
);
    // 12-cycle PWM period: counter runs 0..11 and reloads.
    localparam [3:0] PERIOD_M1 = 4'd11;

    reg [3:0] cnt;       // period counter
    reg [3:0] duty_act;  // active duty, latched at period start
    reg [3:0] duty_pend; // pending (requested) duty
    reg [3:0] hi_left;   // shadow: high-cycle budget recorded at last period start

    initial cnt       = 4'd0;
    initial duty_act  = 4'd0;
    initial duty_pend = 4'd0;
    initial hi_left   = 4'd0;

    wire wrap = (cnt == PERIOD_M1);

    // seeded construct: output high exactly while the counter is below the duty
    assign o_pwm          = (cnt < duty_act);
    assign o_period_start = (cnt == 4'd0);

    always @(posedge clk) begin
        if (ce) begin
            if (wrap) begin
                // new period: both the active duty and the high budget are
                // (re)loaded from the pending duty requested earlier
                cnt      <= 4'd0;
                duty_act <= duty_pend;
                hi_left  <= duty_pend;
            end else begin
                cnt <= cnt + 4'd1;
                if (hi_left != 4'd0)
                    hi_left <= hi_left - 4'd1;
            end
            if (load)
                duty_pend <= duty_in;
        end
    end

    // past-valid register so cycle zero is not judged
    reg pv = 0;
    always @(posedge clk)
        pv <= 1'b1;

    // Precedence: if the output was driven high last cycle, then a nonzero
    // high-cycle budget (recorded at the earlier period start) must still have
    // been available at that time.
    always @(posedge clk)
        if (pv && $past(o_pwm))
            assert ($past(hi_left) != 4'd0);
endmodule

module wdog_saturate (
    input wire i_clk,
    input wire i_rst,
    input wire i_ce,
    input wire i_kick,
    input wire i_ack,
    output wire o_reset,
    output wire [3:0] o_elapsed,
    output wire [3:0] o_remain
);
    // Watchdog window: TIMEOUT ticks without a kick latches a system reset.
    localparam [3:0] TIMEOUT = 4'd12;

    // Saturating up-counter of ticks since the last kick.  It clamps at
    // TIMEOUT (12) even though the 4-bit register admits values up to 15.
    reg [3:0] cnt;
    // Mirror: ticks of grace remaining, saturating down at zero.
    reg [3:0] rem;
    // Latched reset request, cleared only by an acknowledge.
    reg       latched;

    initial cnt     = 4'd0;
    initial rem     = TIMEOUT;
    initial latched = 1'b0;

    always @(posedge i_clk) begin
        if (i_rst) begin
            cnt     <= 4'd0;
            rem     <= TIMEOUT;
            latched <= 1'b0;
        end else if (i_ce) begin
            if (i_kick) begin
                cnt <= 4'd0;
                rem <= TIMEOUT;
            end else begin
                if (cnt < TIMEOUT)
                    cnt <= cnt + 4'd1;
                if (rem != 4'd0)
                    rem <= rem - 4'd1;
            end

            if (i_ack)
                latched <= 1'b0;
            else if (!i_kick && (rem == 4'd1))
                latched <= 1'b1;
        end
    end

    assign o_reset   = latched;
    assign o_elapsed = cnt;
    assign o_remain  = rem;

    // Universality, global scope: whenever the grace window has run out, the
    // elapsed-tick counter must be sitting on its saturation value.
    always @(posedge i_clk)
        if (rem == 4'd0)
            assert (cnt == TIMEOUT);
endmodule

// Four-phase request/acknowledge handshake between a driver and a
// peripheral service unit, with separate idle and busy status flags.
module fourphase_handshake (
    input  wire clk,
    input  wire rst,
    input  wire i_ce,        // global enable / idle condition
    input  wire start,       // driver wants to open a transaction
    input  wire slave_ack,   // peripheral raises acknowledge
    input  wire slave_drop,  // peripheral releases acknowledge
    output wire o_req,
    output wire o_ack,
    output wire o_idle,
    output wire o_busy
);
    // phase encoding:
    //   0 : IDLE      req=0 ack=0
    //   1 : REQ       req=1 ack=0
    //   2 : ACK       req=1 ack=1
    //   3 : DROP      req=0 ack=1   (req may only fall after ack has risen)
    reg [1:0] phase;
    reg       req_r;
    reg       ack_r;
    reg       idle_r;
    reg       busy_r;

    initial begin
        phase  = 2'd0;
        req_r  = 1'b0;
        ack_r  = 1'b0;
        idle_r = 1'b1;
        busy_r = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase  <= 2'd0;
            req_r  <= 1'b0;
            ack_r  <= 1'b0;
            idle_r <= 1'b1;
            busy_r <= 1'b0;
        end else if (i_ce) begin
            case (phase)
                2'd0: begin
                    // leave idle only by raising req; idle flag drops here
                    if (start) begin
                        phase  <= 2'd1;
                        req_r  <= 1'b1;
                        idle_r <= 1'b0;
                    end
                end
                2'd1: begin
                    // peripheral acknowledges; service becomes busy
                    if (slave_ack) begin
                        phase  <= 2'd2;
                        ack_r  <= 1'b1;
                        busy_r <= 1'b1;
                    end
                end
                2'd2: begin
                    // req is allowed to fall now that ack is high
                    phase <= 2'd3;
                    req_r <= 1'b0;
                end
                default: begin
                    // peripheral releases ack, transaction closes
                    if (slave_drop) begin
                        phase  <= 2'd0;
                        ack_r  <= 1'b0;
                        busy_r <= 1'b0;
                        idle_r <= 1'b1;
                    end
                end
            endcase
        end
    end

    assign o_req  = req_r;
    assign o_ack  = ack_r;
    assign o_idle = idle_r;
    assign o_busy = busy_r;

    // P: the service unit is never reported idle and busy at the same time.
    always @(*)
        assert (!(idle_r && busy_r));
endmodule

module skid_stage (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,          // idle condition: en low freezes all state
    input  wire       in_valid,
    input  wire [7:0] in_data,
    input  wire       out_ready,
    output wire       in_ready,
    output reg        out_valid,
    output reg  [7:0] out_data
);
    // skid buffer: only meaningful while the stall flag skid_valid is up
    reg        skid_valid;
    reg  [7:0] skid_data;

    // redundant occupancy counter (3 bits wide, but only 0..2 are real)
    reg  [2:0] occ;

    // sticky arm: set the first time a word is actually accepted
    reg        armed;

    initial begin
        out_valid  = 1'b0;
        out_data   = 8'h00;
        skid_valid = 1'b0;
        skid_data  = 8'h00;
        occ        = 3'd0;
        armed      = 1'b0;
    end

    assign in_ready = !skid_valid;

    wire accept = en && in_valid && in_ready;
    wire drain  = en && out_valid && out_ready;

    always @(posedge clk) begin
        if (rst) begin
            out_valid  <= 1'b0;
            out_data   <= 8'h00;
            skid_valid <= 1'b0;
            skid_data  <= 8'h00;
            occ        <= 3'd0;
            armed      <= 1'b0;
        end else if (en) begin
            // output register / skid promotion
            if (!out_valid || out_ready) begin
                if (skid_valid) begin
                    out_data   <= skid_data;
                    out_valid  <= 1'b1;
                    skid_valid <= 1'b0;
                end else if (in_valid) begin
                    out_data  <= in_data;
                    out_valid <= 1'b1;
                end else begin
                    out_valid <= 1'b0;
                end
            end else begin
                // downstream stalled: park the incoming word in the skid slot
                if (in_valid && !skid_valid) begin
                    skid_data  <= in_data;
                    skid_valid <= 1'b1;
                end
            end

            // occupancy bookkeeping, tracked independently of the flags
            occ <= occ + (accept ? 3'd1 : 3'd0) - (drain ? 3'd1 : 3'd0);

            if (accept) armed <= 1'b1;
        end
    end

    // P, part 1: once the stage has ever accepted a word, occupancy never
    // exceeds 2 even though the counter is 3 bits wide
    always @(posedge clk)
        if (armed)
            assert (occ <= 3'd2);

    // P, part 2: once armed, whenever the skid slot holds a meaningful word the
    // stage is occupancy-saturated at exactly 2
    always @(posedge clk)
        if (armed)
            assert (!skid_valid || occ == 3'd2);
endmodule

module wdt_strike_monitor (
    input  wire       clk,
    input  wire       ce,      // global enable: low freezes the whole watchdog
    input  wire       kick,    // software kick / feed of the watchdog
    output reg  [3:0] cnt,     // watchdog up-counter
    output reg        expired, // timeout flag (counter reached the limit)
    output reg  [2:0] misses,  // number of missed kicks (strike counter)
    output reg        halted,  // lockout after too many strikes
    output reg        armed    // sticky: set at the first kick, never cleared
);

    localparam [3:0] TIMEOUT = 4'd9;  // watchdog limit
    localparam [2:0] MAXMISS = 3'd3;  // strikes tolerated before lockout

    initial cnt     = 4'd0;
    initial expired = 1'b0;
    initial misses  = 3'd0;
    initial halted  = 1'b0;
    initial armed   = 1'b0;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (ce && !halted) begin
            if (kick) begin
                // feeding the dog rewinds the timer and clears the timeout
                cnt     <= 4'd0;
                expired <= 1'b0;
                armed   <= 1'b1;
            end else if (!expired) begin
                // free running towards the limit; saturates there
                cnt <= cnt + 4'd1;
                if (cnt + 4'd1 == TIMEOUT) begin
                    expired <= 1'b1;
                    misses  <= misses + 3'd1;
                    if (misses == MAXMISS - 3'd1)
                        halted <= 1'b1;   // lockout: freeze everything
                end
            end
        end
    end

    // P: once the watchdog has ever been kicked, the strike counter observed
    //    in the previous cycle never exceeded MAXMISS (3) although it is 3 bits wide.
    always @(posedge clk)
        if (pv && armed)
            assert ($past(misses) <= MAXMISS);

endmodule

module txn_scoreboard_deadline (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_issue,
    input  wire       i_retire,
    output wire [3:0] o_outstanding,
    output wire       o_armed
);
    // Scoreboard: issued vs retired transaction counters.
    reg [3:0] issued   = 4'd0;
    reg [3:0] retired  = 4'd0;
    // Completion countdown for the oldest outstanding transaction.
    reg [2:0] deadline = 3'd5;
    // Registered early-warning flag that triggers the forced retire.
    reg       urgent   = 1'b0;
    // Sticky arm: set the first time a transaction is ever accepted.
    reg       armed    = 1'b0;

    wire [3:0] outstanding = issued - retired;

    wire issue_ok  = i_issue && (outstanding < 4'd4);
    wire force_ret = urgent && (deadline == 3'd1);
    wire retire_ok = (outstanding != 4'd0) && (i_retire || force_ret);

    wire [3:0] out_n = outstanding
                     + (issue_ok  ? 4'd1 : 4'd0)
                     - (retire_ok ? 4'd1 : 4'd0);

    wire [2:0] dl_n = (retire_ok || (issue_ok && (outstanding == 4'd0))) ? 3'd5 :
                      ((outstanding != 4'd0) ? (deadline - 3'd1) : deadline);

    always @(posedge clk) begin
        if (i_ce) begin
            if (issue_ok)  issued  <= issued  + 4'd1;
            if (retire_ok) retired <= retired + 4'd1;
            deadline <= dl_n;
            urgent   <= (out_n != 4'd0) && (dl_n <= 3'd2);
            if (issue_ok) armed <= 1'b1;
        end
    end

    assign o_outstanding = outstanding;
    assign o_armed       = armed;

    // Bounded response (safety form), after-Q scope: once the scoreboard has
    // ever accepted a transaction, the completion countdown must never expire
    // while work is still outstanding.
    always @(posedge clk)
        if (armed && (outstanding != 4'd0))
            assert (deadline != 3'd0);
endmodule

module toast_spi_cs_seq (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         push,
    input  wire [4:0]   push_slv,
    input  wire [127:0] push_data,
    input  wire [7:0]   cfg_setup,
    input  wire [7:0]   cfg_hold,
    input  wire [7:0]   cfg_gap,
    output wire [23:0]  cs_n,
    output wire         mosi,
    output wire         busy,
    output wire         full
);
    localparam [2:0] ST_IDLE  = 3'd0;
    localparam [2:0] ST_SETUP = 3'd1;
    localparam [2:0] ST_XFER  = 3'd2;
    localparam [2:0] ST_HOLD  = 3'd3;
    localparam [2:0] ST_GAP   = 3'd4;

    reg [2:0]   st     = ST_IDLE;
    reg [4:0]   sel    = 5'd0;
    reg [7:0]   dly    = 8'd0;
    reg [6:0]   bitcnt = 7'd0;
    reg [23:0]  cs_vec = 24'd0;
    reg [127:0] shreg  = 128'd0;

    reg [4:0]   q_slv [0:23];
    reg [127:0] q_dat [0:23];
    reg [4:0]   wptr  = 5'd0;
    reg [4:0]   rptr  = 5'd0;
    reg [4:0]   count = 5'd0;

    integer i;
    initial begin
        for (i = 0; i < 24; i = i + 1) begin
            q_slv[i] = 5'd0;
            q_dat[i] = 128'd0;
        end
    end

    wire [4:0]   head_raw = q_slv[rptr];
    wire [4:0]   head_slv = (head_raw < 5'd24) ? head_raw : 5'd0;
    wire [127:0] head_dat = q_dat[rptr];

    wire can_pop = (count != 5'd0) &&
                   ((st == ST_IDLE) || ((st == ST_GAP) && (dly == 8'd0)));
    wire do_push = push && (count < 5'd24);

    wire [4:0] wptr_nx = (wptr == 5'd23) ? 5'd0 : wptr + 5'd1;
    wire [4:0] rptr_nx = (rptr == 5'd23) ? 5'd0 : rptr + 5'd1;

    assign cs_n = ~cs_vec;
    assign mosi = shreg[127];
    assign busy = (st != ST_IDLE);
    assign full = (count == 5'd24);

    always @(posedge clk) begin
        if (rst) begin
            st     <= ST_IDLE;
            sel    <= 5'd0;
            dly    <= 8'd0;
            bitcnt <= 7'd0;
            cs_vec <= 24'd0;
            shreg  <= 128'd0;
            wptr   <= 5'd0;
            rptr   <= 5'd0;
            count  <= 5'd0;
        end else if (en) begin
            if (do_push) begin
                q_slv[wptr] <= (push_slv < 5'd24) ? push_slv : 5'd0;
                q_dat[wptr] <= push_data;
                wptr <= wptr_nx;
            end
            if (can_pop)
                rptr <= rptr_nx;
            if (do_push && !can_pop)
                count <= count + 5'd1;
            else if (!do_push && can_pop)
                count <= count - 5'd1;

            case (st)
                ST_IDLE: begin
                    if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end
                end
                ST_SETUP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        bitcnt <= 7'd127;
                        st     <= ST_XFER;
                    end
                end
                ST_XFER: begin
                    shreg <= {shreg[126:0], 1'b0};
                    if (bitcnt != 7'd0)
                        bitcnt <= bitcnt - 7'd1;
                    else begin
                        dly <= cfg_hold;
                        st  <= ST_HOLD;
                    end
                end
                ST_HOLD: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else begin
                        cs_vec <= cs_vec & ~(24'd1 << sel);
                        dly    <= cfg_gap;
                        st     <= ST_GAP;
                    end
                end
                ST_GAP: begin
                    if (dly != 8'd0)
                        dly <= dly - 8'd1;
                    else if (can_pop) begin
                        sel    <= head_slv;
                        cs_vec <= cs_vec | (24'd1 << head_slv);
                        shreg  <= head_dat;
                        dly    <= cfg_setup;
                        st     <= ST_SETUP;
                    end else
                        st <= ST_IDLE;
                end
                default: st <= ST_IDLE;
            endcase
        end
    end

    // No two slave selects asserted at once while the sequencer is active
    always @(posedge clk)
        if (st != ST_IDLE)
            assert ((cs_vec & (cs_vec - 24'd1)) == 24'd0);
endmodule

module vcd_mac_learn (
    input wire clk,
    input wire rst,
    input wire en,
    input wire learn_v,
    input wire [31:0] src_mac,
    input wire [3:0] src_port,
    input wire look_v,
    input wire [31:0] dst_mac,
    input wire age_tick,
    input wire win_open,
    input wire win_close,
    output wire o_hit,
    output wire [3:0] o_port,
    output wire o_win
);
    reg [383:0] key_flat;
    reg [47:0]  port_flat;
    reg [11:0]  valid;
    reg [11:0]  age;
    reg [3:0]   rr_ptr;
    reg [31:0]  learn_cnt;
    reg         hit_q;
    reg [3:0]   out_port;
    reg         win;

    initial key_flat = 384'd0;
    initial port_flat = 48'd0;
    initial valid = 12'd0;
    initial age = 12'd0;
    initial rr_ptr = 4'd0;
    initial learn_cnt = 32'd0;
    initial hit_q = 1'b0;
    initial out_port = 4'd0;
    initial win = 1'b0;

    assign o_hit = hit_q;
    assign o_port = out_port;
    assign o_win = win;

    integer i;
    reg match_any;
    reg [3:0] match_idx;
    reg free_any;
    reg [3:0] free_idx;
    reg look_hit;
    reg [3:0] look_idx;
    always @(*) begin
        match_any = 1'b0; match_idx = 4'd0;
        free_any = 1'b0;  free_idx = 4'd0;
        look_hit = 1'b0;  look_idx = 4'd0;
        for (i = 11; i >= 0; i = i - 1) begin
            if (valid[i] && (key_flat[i*32 +: 32] == src_mac)) begin
                match_any = 1'b1; match_idx = i;
            end
            if (!valid[i]) begin
                free_any = 1'b1; free_idx = i;
            end
            if (valid[i] && (key_flat[i*32 +: 32] == dst_mac)) begin
                look_hit = 1'b1; look_idx = i;
            end
        end
    end

    wire [3:0] tgt = match_any ? match_idx : (free_any ? free_idx : rr_ptr);

    reg [11:0] valid_n;
    reg [11:0] age_n;
    always @(*) begin
        valid_n = valid;
        age_n = age;
        if (age_tick) begin
            valid_n = valid & age;
            age_n = 12'd0;
        end
        if (look_v && look_hit)
            age_n[look_idx] = 1'b1;
        if (learn_v) begin
            valid_n[tgt] = 1'b1;
            age_n[tgt] = 1'b1;
        end
    end

    always @(posedge clk) begin
        if (rst) begin
            key_flat <= 384'd0;
            port_flat <= 48'd0;
            valid <= 12'd0;
            age <= 12'd0;
            rr_ptr <= 4'd0;
            learn_cnt <= 32'd0;
            hit_q <= 1'b0;
            out_port <= 4'd0;
            win <= 1'b0;
        end else if (en) begin
            valid <= valid_n;
            age <= age_n;
            hit_q <= look_v & look_hit;
            if (look_v && look_hit)
                out_port <= port_flat[look_idx*4 +: 4];
            if (learn_v) begin
                key_flat[tgt*32 +: 32] <= src_mac;
                port_flat[tgt*4 +: 4] <= src_port;
                if (!match_any)
                    rr_ptr <= (rr_ptr >= 4'd11) ? 4'd0 : rr_ptr + 4'd1;
                if (learn_cnt != 32'hFFFFFFFF)
                    learn_cnt <= learn_cnt + 32'd1;
            end
            if (win_close)
                win <= 1'b0;
            else if (win_open)
                win <= 1'b1;
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && !rst && win && $rose(hit_q))
            assert (learn_cnt != 32'd0);
endmodule

module bank_steer_demux (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        req,
    input  wire        resp,
    input  wire [15:0] addr,
    output reg  [3:0]  pending,
    output reg  [1:0]  phase,
    output reg  [15:0] done_cnt
);
    // phase: 0 = IDLE, 1 = ARMED (bank decoded), 2 = STARTED (bank pending), 3 = FINISHED
    reg [1:0]  bank_idx;
    reg [15:0] addr_q;

    initial phase    = 2'd0;
    initial pending  = 4'd0;
    initial bank_idx = 2'd0;
    initial addr_q   = 16'd0;
    initial done_cnt = 16'd0;

    always @(posedge clk) begin
        if (rst) begin
            phase    <= 2'd0;
            pending  <= 4'd0;
            bank_idx <= 2'd0;
            addr_q   <= 16'd0;
            done_cnt <= 16'd0;
        end else if (ce) begin
            case (phase)
                2'd0: if (req) begin
                    addr_q   <= addr;
                    bank_idx <= addr[1:0];
                    phase    <= 2'd1;
                end
                2'd1: begin
                    pending <= pending | (4'd1 << bank_idx);
                    phase   <= 2'd2;
                end
                2'd2: if (resp) begin
                    pending  <= pending & ~(4'd1 << bank_idx);
                    phase    <= 2'd3;
                    done_cnt <= done_cnt + 16'd1;
                end
                default: phase <= 2'd0;
            endcase
        end
    end

    // A finish can only be observed once the started bank request has been retired
    always @(*) assert (phase != 2'd3 || pending == 4'd0);
endmodule

module median_tick_filter (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        in_valid,
    input  wire [15:0] in_px,
    input  wire        sess_open,
    input  wire        sess_close,
    output wire [15:0] med_px,
    output wire        med_valid,
    output wire [15:0] fill_out
);
    // 8-entry sliding window of 16-bit price samples (packed)
    reg [127:0] win   = 128'd0;
    // thermometer occupancy mask: one bit per filled slot
    reg [7:0]   mask  = 8'h00;
    // occupancy counter, saturates at 8
    reg [15:0]  fill  = 16'd0;
    // trading-session window register (scope: open .. close)
    reg         armed = 1'b0;

    // odd-even transposition sorting network over 8 entries
    function [127:0] sort8;
        input [127:0] v;
        integer st, j;
        reg [127:0] t;
        reg [15:0] a, b;
        begin
            t = v;
            for (st = 0; st < 8; st = st + 1) begin
                for (j = (st % 2); j < 7; j = j + 2) begin
                    a = t[16*j +: 16];
                    b = t[16*(j+1) +: 16];
                    if (a > b) begin
                        t[16*j +: 16]     = b;
                        t[16*(j+1) +: 16] = a;
                    end
                end
            end
            sort8 = t;
        end
    endfunction

    wire [127:0] sorted = sort8(win);
    assign med_px    = sorted[16*3 +: 16];
    assign med_valid = mask[7];
    assign fill_out  = fill;

    always @(posedge clk) begin
        if (rst) begin
            win   <= 128'd0;
            mask  <= 8'h00;
            fill  <= 16'd0;
            armed <= 1'b0;
        end else if (ce) begin
            if (sess_close) begin
                armed <= 1'b0;
                mask  <= 8'h00;
                fill  <= 16'd0;
            end else begin
                if (sess_open)
                    armed <= 1'b1;
                if (in_valid) begin
                    win  <= {win[111:0], in_px};
                    mask <= {mask[6:0], 1'b1};
                    if (!mask[7])
                        fill <= fill + 16'd1;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // inside a session, whenever the clock-enable burst ends, occupancy is at most 8
    always @(posedge clk)
        if (pv && armed && $fell(ce))
            assert (fill <= 16'd8);
endmodule

module gshare_streak (
    input  wire        clk,
    input  wire        upd,
    input  wire        taken,
    input  wire [63:0] upd_pc,
    input  wire [63:0] fetch_pc,
    input  wire        restore,
    input  wire [63:0] restore_ghr,
    output wire        pred_taken
);
    reg [63:0] ghr      = 64'd0;
    reg [63:0] streak_t = 64'd0;
    reg [63:0] streak_n = 64'd0;
    reg        armed    = 1'b1;
    reg [1:0]  pht [0:255];
    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1)
            pht[i] = 2'b01;
    end

    wire [7:0] fidx = fetch_pc[9:2] ^ ghr[7:0];
    wire [7:0] uidx = upd_pc[9:2] ^ ghr[7:0];
    assign pred_taken = pht[fidx][1];

    wire [63:0] t_inc = (streak_t == 64'hFFFF_FFFF_FFFF_FFFF) ? streak_t : streak_t + 64'd1;
    wire [63:0] n_inc = (streak_n == 64'hFFFF_FFFF_FFFF_FFFF) ? streak_n : streak_n + 64'd1;

    always @(posedge clk) begin
        if (restore) begin
            ghr   <= restore_ghr;
            armed <= 1'b0;
        end else if (upd) begin
            ghr <= {ghr[62:0], taken};
            if (taken) begin
                pht[uidx] <= (pht[uidx] == 2'b11) ? 2'b11 : pht[uidx] + 2'b01;
                if (!ghr[0]) begin
                    streak_t <= 64'd1;
                    streak_n <= 64'd0;
                end else begin
                    streak_t <= t_inc;
                end
            end else begin
                pht[uidx] <= (pht[uidx] == 2'b00) ? 2'b00 : pht[uidx] - 2'b01;
                if (ghr[0]) begin
                    streak_n <= 64'd1;
                    streak_t <= 64'd0;
                end else begin
                    streak_n <= n_inc;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && armed)
            assert (!($past(streak_t) != 64'd0 && $past(streak_n) != 64'd0));
endmodule

module nyuzi_scan_demux (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         ir_load,
    input  wire [7:0]   ir_data,
    input  wire         shift,
    input  wire         scan_in,
    output wire [255:0] chain_si,
    output reg          frame_done
);
    reg [7:0]  chain_sel;
    reg [15:0] shift_cnt;
    reg [15:0] remaining;
    reg        armed;

    initial chain_sel  = 8'd0;
    initial shift_cnt  = 16'd0;
    initial remaining  = 16'd999;
    initial armed      = 1'b0;
    initial frame_done = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            chain_sel  <= 8'd0;
            shift_cnt  <= 16'd0;
            remaining  <= 16'd999;
            armed      <= 1'b0;
            frame_done <= 1'b0;
        end else if (en) begin
            frame_done <= 1'b0;
            if (ir_load) begin
                chain_sel <= ir_data;
                shift_cnt <= 16'd0;
                remaining <= 16'd999;
                armed     <= 1'b1;
            end else if (shift) begin
                if (remaining == 16'd0) begin
                    shift_cnt  <= 16'd0;
                    remaining  <= 16'd999;
                    frame_done <= 1'b1;
                end else begin
                    shift_cnt <= shift_cnt + 16'd1;
                    remaining <= remaining - 16'd1;
                end
            end
        end
    end

    wire si_bit = scan_in & shift & en;
    assign chain_si = {255'd0, si_bit} << chain_sel;

    always @(posedge clk)
        if (armed) assert (shift_cnt <= 16'd999);
endmodule

module sd_dac_lockstep (
    input wire clk,
    input wire ce,
    input wire mute,
    input wire [15:0] din,
    output reg dout,
    output reg dchk
);
    // main first-order sigma-delta error accumulator
    reg [15:0] acc = 16'h0000;
    // lockstep reference accumulator (does not see mute)
    reg [15:0] acc_chk = 16'h0000;
    // scope register: high until the first mute event
    reg before_mute = 1'b1;
    reg pv = 1'b0;

    initial dout = 1'b0;
    initial dchk = 1'b0;

    wire [16:0] sum     = {1'b0, acc}     + {1'b0, din};
    wire [16:0] sum_chk = {1'b0, acc_chk} + {1'b0, din};

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (mute) begin
            acc  <= 16'h0000;
            dout <= 1'b0;
        end else if (ce) begin
            acc  <= sum[15:0];
            dout <= sum[16];
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            acc_chk <= sum_chk[15:0];
            dchk    <= sum_chk[16];
        end
    end

    always @(posedge clk) begin
        if (mute)
            before_mute <= 1'b0;
    end

    // Absence, before first mute: never (reference bit held) and (main bit toggled)
    always @(posedge clk)
        if (pv && before_mute)
            assert (!($stable(dchk) && !$stable(dout)));
endmodule

module yat_phase_ring (
    input  wire        clk,
    input  wire        rst,
    input  wire        advance,
    output wire [31:0] fetch_phase,
    output wire [31:0] exec_phase
);
    reg [31:0] fetch_ring;
    reg [31:0] exec_ring;

    initial fetch_ring = 32'h00000000;
    initial exec_ring  = 32'h00000000;

    // Fetch-side Johnson phase token
    always @(posedge clk) begin
        if (rst)
            fetch_ring <= 32'h00000000;
        else if (advance)
            fetch_ring <= {fetch_ring[30:0], ~fetch_ring[31]};
    end

    // Execute-side shadow ring checked by the hazard unit
    always @(posedge clk) begin
        if (rst)
            exec_ring <= 32'h00000000;
        else if (advance)
            exec_ring <= {exec_ring[30:0], ~exec_ring[31]};
    end

    assign fetch_phase = fetch_ring;
    assign exec_phase  = exec_ring;

    assert property (fetch_ring[31] == exec_ring[31]);
endmodule

module rns_alu (
    input wire clk,
    input wire en,
    input wire [1:0] op,
    input wire [7:0] op_a,
    output wire [7:0] result,
    output wire rns_zero
);
    localparam OP_LOAD = 2'd0;
    localparam OP_ADD  = 2'd1;
    localparam OP_SUB  = 2'd2;
    localparam OP_MUL  = 2'd3;

    // residue registers, one per modulus channel (moduli 5 and 7)
    reg [2:0] r5;
    reg [2:0] r7;
    // binary mirror accumulator modulo 35 (= 5*7)
    reg [7:0] acc;
    // sticky scope register: set at the first LOAD
    reg armed;

    initial begin
        r5 = 3'd0;
        r7 = 3'd0;
        acc = 8'd0;
        armed = 1'b0;
    end

    // operand residues
    wire [15:0] opw = {8'd0, op_a};
    wire [15:0] a5  = opw % 16'd5;
    wire [15:0] a7  = opw % 16'd7;
    wire [15:0] a35 = opw % 16'd35;

    wire [15:0] r5w  = {13'd0, r5};
    wire [15:0] r7w  = {13'd0, r7};
    wire [15:0] accw = {8'd0, acc};

    // channel 5
    wire [15:0] n5_add = (r5w + a5) % 16'd5;
    wire [15:0] n5_sub = (r5w + 16'd5 - a5) % 16'd5;
    wire [15:0] n5_mul = (r5w * a5) % 16'd5;
    // channel 7
    wire [15:0] n7_add = (r7w + a7) % 16'd7;
    wire [15:0] n7_sub = (r7w + 16'd7 - a7) % 16'd7;
    wire [15:0] n7_mul = (r7w * a7) % 16'd7;
    // binary mirror mod 35
    wire [15:0] nb_add = (accw + a35) % 16'd35;
    wire [15:0] nb_sub = (accw + 16'd35 - a35) % 16'd35;
    wire [15:0] nb_mul = (accw * a35) % 16'd35;

    always @(posedge clk) begin
        if (en) begin
            case (op)
                OP_LOAD: begin
                    r5 <= a5[2:0];
                    r7 <= a7[2:0];
                    acc <= a35[7:0];
                    armed <= 1'b1;
                end
                OP_ADD: begin
                    r5 <= n5_add[2:0];
                    r7 <= n7_add[2:0];
                    acc <= nb_add[7:0];
                end
                OP_SUB: begin
                    r5 <= n5_sub[2:0];
                    r7 <= n7_sub[2:0];
                    acc <= nb_sub[7:0];
                end
                default: begin
                    r5 <= n5_mul[2:0];
                    r7 <= n7_mul[2:0];
                    acc <= nb_mul[7:0];
                end
            endcase
        end
    end

    assign result = acc;
    assign rns_zero = (r5 == 3'd0) && (r7 == 3'd0);

    // Absence after first LOAD: RNS zero flag and nonzero binary mirror never together
    assert property (!armed || !((r5 == 3'd0) && (r7 == 3'd0) && (acc != 8'd0)));
endmodule

module ro_entropy_harvester (
    input  wire        clk,
    input  wire        sample_en,
    input  wire [2:0]  ro_phase,
    output reg  [31:0] o_word,
    output reg         o_valid
);
    // collection shift register and sample counter
    reg [31:0] shreg      = 32'd0;
    reg [31:0] sample_cnt = 32'd0;
    // scope register: high until the first full word is harvested
    reg        armed      = 1'b1;
    initial o_word  = 32'd0;
    initial o_valid = 1'b0;

    // raw entropy bit: XOR of free-running oscillator phases
    wire raw_bit = ^ro_phase;

    always @(posedge clk) begin
        if (sample_en) begin
            shreg <= {shreg[30:0], raw_bit};
            if (sample_cnt == 32'd31) begin
                sample_cnt <= 32'd0;
                o_word     <= {shreg[30:0], raw_bit};
                o_valid    <= 1'b1;
                armed      <= 1'b0;
            end else begin
                sample_cnt <= sample_cnt + 32'd1;
                o_valid    <= 1'b0;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // before the first harvest, the top collection bit never changes
    always @(posedge clk)
        if (pv && armed) assert (shreg[31] == $past(shreg[31]));
endmodule

module dram_ret_est (
    input  wire       clk,
    input  wire       rst,
    input  wire       en,
    input  wire [3:0] x,
    output wire [7:0] est
);
    reg [7:0] tiv0, tiv1, tiv2, tiv3;
    reg [7:0] to0, to1, to2, to3;
    reg [3:0] idx1, idx2;
    reg [7:0] tiv_r, to_r, sum_q;
    reg       arm;

    initial begin
        tiv0 = 8'd200; tiv1 = 8'd150; tiv2 = 8'd100; tiv3 = 8'd60;
        to0  = 8'd0;   to1  = 8'd12;  to2  = 8'd24;  to3  = 8'd36;
        idx1 = 4'd0; tiv_r = 8'd200; to_r = 8'd0;
        idx2 = 4'd0; sum_q = 8'd200; arm = 1'b0;
    end

    wire [7:0] tiv_sel = (x[3:2] == 2'd0) ? tiv0 :
                         (x[3:2] == 2'd1) ? tiv1 :
                         (x[3:2] == 2'd2) ? tiv2 : tiv3;
    wire [7:0] to_sel  = (x[1:0] == 2'd0) ? to0 :
                         (x[1:0] == 2'd1) ? to1 :
                         (x[1:0] == 2'd2) ? to2 : to3;

    always @(posedge clk) begin
        if (rst) begin
            tiv0 <= 8'd200; tiv1 <= 8'd150; tiv2 <= 8'd100; tiv3 <= 8'd60;
            to0  <= 8'd0;   to1  <= 8'd12;  to2  <= 8'd24;  to3  <= 8'd36;
            idx1 <= 4'd0; tiv_r <= 8'd200; to_r <= 8'd0;
            idx2 <= 4'd0; sum_q <= 8'd200; arm <= 1'b0;
        end else if (en) begin
            idx1  <= x;
            tiv_r <= tiv_sel;
            to_r  <= to_sel;
            idx2  <= idx1;
            sum_q <= tiv_r + to_r;
            arm   <= 1'b1;
        end
    end

    assign est = sum_q;

    wire [7:0] exp_tiv2 = (idx2[3:2] == 2'd0) ? 8'd200 :
                          (idx2[3:2] == 2'd1) ? 8'd150 :
                          (idx2[3:2] == 2'd2) ? 8'd100 : 8'd60;
    wire [7:0] exp_to2  = (idx2[1:0] == 2'd0) ? 8'd0 :
                          (idx2[1:0] == 2'd1) ? 8'd12 :
                          (idx2[1:0] == 2'd2) ? 8'd24 : 8'd36;
    wire [7:0] exp_sum2 = exp_tiv2 + exp_to2;

    always @(posedge clk)
        if (arm)
            assert (sum_q == exp_sum2);
endmodule

module dfx_quiesce (
    input wire clk,
    input wire rst,
    input wire en,
    input wire issue,
    input wire ret,
    output wire bus_quiet
);
    reg [15:0] out_cnt;
    reg [15:0] iss_cnt;
    reg [15:0] ret_cnt;
    reg        armed;
    initial out_cnt = 16'd0;
    initial iss_cnt = 16'd0;
    initial ret_cnt = 16'd0;
    initial armed   = 1'b0;

    wire iss_ok = issue && (out_cnt != 16'hFFFF);
    wire ret_ok = ret && (out_cnt != 16'd0);

    always @(posedge clk) begin
        if (rst) begin
            out_cnt <= 16'd0;
            iss_cnt <= 16'd0;
            ret_cnt <= 16'd0;
            armed   <= 1'b0;
        end else if (en) begin
            out_cnt <= out_cnt + {15'd0, iss_ok} - {15'd0, ret_ok};
            iss_cnt <= iss_cnt + {15'd0, iss_ok};
            ret_cnt <= ret_cnt + {15'd0, ret_ok};
            armed   <= armed | iss_ok;
        end
    end

    assign bus_quiet = ~(out_cnt[0] | out_cnt[1] | out_cnt[2] | out_cnt[3] |
                         out_cnt[4] | out_cnt[5] | out_cnt[6] | out_cnt[7] |
                         out_cnt[8] | out_cnt[9] | out_cnt[10] | out_cnt[11] |
                         out_cnt[12] | out_cnt[13] | out_cnt[14] | out_cnt[15]);

    always @(posedge clk)
        if (armed && bus_quiet)
            assert (ret_cnt == iss_cnt);
endmodule

module crc_residue_chk (
    input  wire clk,
    input  wire ce,
    input  wire start,
    input  wire din,
    output reg  done,
    output reg  err
);
    // bit-serial CRC-8 (poly x^8+x^2+x+1) residue checker:
    // 8 data bits followed by 8 appended CRC bits; residue must be zero
    reg [7:0] crc    = 8'h00;
    reg [7:0] bitcnt = 8'd0;   // bits consumed in current frame
    reg [7:0] timer  = 8'd0;   // completion watchdog countdown
    reg       busy   = 1'b0;   // frame outstanding
    reg       armed  = 1'b1;   // scope: no CRC error has ever been flagged
    initial done = 1'b0;
    initial err  = 1'b0;

    wire       fb       = crc[7] ^ din;
    wire [7:0] crc_next = {crc[6:0], 1'b0} ^ (fb ? 8'h07 : 8'h00);
    wire       last     = busy && ce && (bitcnt == 8'd15);

    always @(posedge clk) begin
        if (!busy) begin
            if (start) begin
                busy   <= 1'b1;
                bitcnt <= 8'd0;
                timer  <= 8'd16;
                crc    <= 8'h00;
                done   <= 1'b0;
                err    <= 1'b0;
            end
        end else if (ce) begin
            crc    <= crc_next;
            bitcnt <= bitcnt + 8'd1;
            timer  <= timer - 8'd1;
            if (bitcnt == 8'd15) begin
                busy <= 1'b0;
                done <= 1'b1;
                err  <= (crc_next != 8'h00);
            end
        end
        if (last && (crc_next != 8'h00))
            armed <= 1'b0;
    end

    // before the first CRC error: the watchdog never expires while a frame is outstanding
    always @(*)
        assert (!armed || !busy || timer != 8'd0);
endmodule

module flow_hash_steer (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        pkt_valid,
    input  wire [7:0]  src,
    input  wire [7:0]  dst,
    input  wire [7:0]  port,
    input  wire        cfg_we,
    input  wire [4:0]  cfg_addr,
    input  wire [7:0]  cfg_data,
    output reg  [7:0]  hash_q,
    output reg  [7:0]  q_sel,
    output reg         out_valid
);
    // 32-entry indirection table, 8-bit words, entry i at bits [8i+7:8i]
    reg [255:0] tbl_flat;
    initial tbl_flat = {8{8'd3, 8'd2, 8'd1, 8'd0}};
    initial hash_q = 8'd0;
    initial q_sel = 8'd0;
    initial out_valid = 1'b0;

    // header hash
    wire [7:0] h = src ^ {dst[3:0], dst[7:4]} ^ {port[6:0], port[7]};
    wire [4:0] hidx = h[4:0];
    wire [255:0] sh = tbl_flat >> {hidx, 3'b000};
    wire [7:0] entry = sh[7:0];

    integer i;
    always @(posedge clk) begin
        if (rst) begin
            tbl_flat  <= {8{8'd3, 8'd2, 8'd1, 8'd0}};
            hash_q    <= 8'd0;
            q_sel     <= 8'd0;
            out_valid <= 1'b0;
        end else if (en) begin
            for (i = 0; i < 32; i = i + 1)
                if (cfg_we && cfg_addr == i[4:0])
                    tbl_flat[i*8 +: 8] <= {6'd0, cfg_data[1:0]};
            out_valid <= pkt_valid;
            if (pkt_valid) begin
                hash_q <= h;
                q_sel  <= entry;
            end
        end
    end

    always @(posedge clk)
        if (out_valid) assert (q_sel < 8'd4);
endmodule

module vrf_lanes (
    input  wire        clk,
    input  wire        ce,
    input  wire        lock,
    input  wire        unlock,
    input  wire        we,
    input  wire [6:0]  waddr,
    input  wire        wsel_alu,
    input  wire [63:0] wdata0,
    input  wire [63:0] wdata1,
    input  wire [6:0]  ra0,
    input  wire [6:0]  rb0,
    input  wire [6:0]  ra1,
    input  wire [6:0]  rb1,
    input  wire        cfg_we,
    input  wire [6:0]  cfg_addr,
    input  wire [1:0]  cfg_ew,
    output wire [63:0] out0,
    output wire [63:0] out1,
    output wire [63:0] o_wr_count
);
    reg [63:0] lane0_mem [0:127];
    reg [63:0] lane1_mem [0:127];
    reg [1:0]  ew_cfg    [0:127];
    reg [63:0] lane0_elems;
    reg [63:0] lane1_elems;
    reg [63:0] wr_count;
    reg        armed;
    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) begin
            lane0_mem[i] = 64'd0;
            lane1_mem[i] = 64'd0;
            ew_cfg[i]    = 2'd0;
        end
        lane0_elems = 64'd0;
        lane1_elems = 64'd0;
        wr_count    = 64'd0;
        armed       = 1'b0;
    end

    wire [63:0] alu0 = lane0_mem[ra0] + lane0_mem[rb0];
    wire [63:0] alu1 = lane1_mem[ra1] + lane1_mem[rb1];
    wire [63:0] elems = 64'd1 << ew_cfg[waddr];

    always @(posedge clk) begin
        if (ce) begin
            if (we) begin
                lane0_mem[waddr] <= wsel_alu ? alu0 : wdata0;
                lane1_mem[waddr] <= wsel_alu ? alu1 : wdata1;
                lane0_elems <= lane0_elems + elems;
                lane1_elems <= lane1_elems + elems;
                wr_count    <= wr_count + 64'd1;
            end
            if (cfg_we)
                ew_cfg[cfg_addr] <= cfg_ew;
            if (lock)
                armed <= 1'b1;
            else if (unlock)
                armed <= 1'b0;
        end
    end

    assign out0 = alu0;
    assign out1 = alu1;
    assign o_wr_count = wr_count;

    always @(*) assert (!armed || (lane0_elems == lane1_elems));
endmodule

module ras_walker (
    input wire clk,
    input wire rst,
    input wire en,
    input wire call,
    input wire ret,
    input wire [63:0] call_addr,
    output reg [63:0] ret_addr,
    output reg ret_valid
);
    reg [63:0] ras0, ras1;
    reg [1:0]  tos;
    reg        pend;
    reg [63:0] stg;
    reg [63:0] cnt;
    reg        win;
    reg        pv;

    initial ras0 = 64'd0;
    initial ras1 = 64'd0;
    initial tos = 2'd0;
    initial pend = 1'b0;
    initial stg = 64'd0;
    initial cnt = 64'd0;
    initial win = 1'b0;
    initial ret_addr = 64'd0;
    initial ret_valid = 1'b0;
    initial pv = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            ras0 <= 64'd0;
            ras1 <= 64'd0;
            tos <= 2'd0;
            pend <= 1'b0;
            stg <= 64'd0;
            cnt <= 64'd0;
            win <= 1'b0;
            ret_addr <= 64'd0;
            ret_valid <= 1'b0;
        end else if (en) begin
            ret_valid <= 1'b0;
            if (pend) begin
                if (stg == 64'd3) begin
                    ret_addr <= tos[0] ? ras1 : ras0;
                    ret_valid <= 1'b1;
                    pend <= 1'b0;
                    win <= 1'b0;
                    stg <= 64'd0;
                end else begin
                    stg <= stg + 64'd1;
                    cnt <= cnt - 64'd1;
                end
            end else if (ret && tos != 2'd0) begin
                tos <= tos - 2'd1;
                pend <= 1'b1;
                stg <= 64'd0;
                cnt <= 64'd4;
                win <= 1'b1;
            end else if (call && tos < 2'd2) begin
                if (tos == 2'd0) ras0 <= call_addr;
                else ras1 <= call_addr;
                tos <= tos + 2'd1;
            end
        end
    end

    always @(posedge clk)
        if (pv && $past(en) && $past(win) && $past(pend))
            assert ($past(cnt) != 64'd0);
endmodule

module dbg_failover_mux (
    input  wire       clk,
    input  wire       rst_n,
    input  wire       en,
    input  wire [7:0] pri_data,
    input  wire [7:0] bak_data,
    input  wire       pri_fault,
    input  wire       pri_ok,
    output wire [7:0] out_data
);
    reg [7:0] health     = 8'd0;
    reg       arm_f      = 1'b0;
    reg       start_f    = 1'b0;
    reg       fin_f      = 1'b0;
    reg       active_src = 1'b0;
    reg       pv         = 1'b0;

    assign out_data = active_src ? bak_data : pri_data;

    always @(posedge clk) begin
        if (!rst_n) begin
            health     <= 8'd0;
            arm_f      <= 1'b0;
            start_f    <= 1'b0;
            fin_f      <= 1'b0;
            active_src <= 1'b0;
        end else if (en) begin
            if (pri_ok && fin_f && active_src) begin
                health     <= 8'd0;
                arm_f      <= 1'b0;
                start_f    <= 1'b0;
                fin_f      <= 1'b0;
                active_src <= 1'b0;
            end else begin
                if (pri_fault && health != 8'hFF)
                    health <= health + 8'd1;
                if (health >= 8'd3 && !arm_f)
                    arm_f <= 1'b1;
                if (arm_f && pri_fault && !start_f)
                    start_f <= 1'b1;
                if (start_f && !fin_f)
                    fin_f <= 1'b1;
                if (start_f && arm_f && !active_src)
                    active_src <= 1'b1;
            end
        end
    end

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && $stable(fin_f))
            assert ($stable(active_src));
endmodule

module zz_reorder (
    input  wire        i_clk,
    input  wire        i_reset,
    input  wire        i_in_valid,
    input  wire [31:0] i_coef,
    input  wire        i_out_ready,
    output reg         o_valid,
    output reg  [31:0] o_coef,
    output wire        o_full,
    output wire        o_empty
);
    // two 64-entry banks = 128-entry block memory (ping-pong)
    reg [31:0] mem [0:127];
    reg [1:0]  bank_valid = 2'b00;
    reg        w_bank = 1'b0;
    reg        r_bank = 1'b0;
    reg [31:0] w_idx = 32'd0;
    reg [31:0] r_idx = 32'd0;
    reg [31:0] nfull = 32'd0;
    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1) mem[i] = 32'd0;
        o_valid = 1'b0;
        o_coef  = 32'd0;
    end

    // zigzag index-sequence ROM: zigzag position -> raster position
    function [5:0] zz;
        input [5:0] k;
        case (k)
            6'd0: zz=6'd0;   6'd1: zz=6'd1;   6'd2: zz=6'd8;   6'd3: zz=6'd16;
            6'd4: zz=6'd9;   6'd5: zz=6'd2;   6'd6: zz=6'd3;   6'd7: zz=6'd10;
            6'd8: zz=6'd17;  6'd9: zz=6'd24;  6'd10: zz=6'd32; 6'd11: zz=6'd25;
            6'd12: zz=6'd18; 6'd13: zz=6'd11; 6'd14: zz=6'd4;  6'd15: zz=6'd5;
            6'd16: zz=6'd12; 6'd17: zz=6'd19; 6'd18: zz=6'd26; 6'd19: zz=6'd33;
            6'd20: zz=6'd40; 6'd21: zz=6'd48; 6'd22: zz=6'd41; 6'd23: zz=6'd34;
            6'd24: zz=6'd27; 6'd25: zz=6'd20; 6'd26: zz=6'd13; 6'd27: zz=6'd6;
            6'd28: zz=6'd7;  6'd29: zz=6'd14; 6'd30: zz=6'd21; 6'd31: zz=6'd28;
            6'd32: zz=6'd35; 6'd33: zz=6'd42; 6'd34: zz=6'd49; 6'd35: zz=6'd56;
            6'd36: zz=6'd57; 6'd37: zz=6'd50; 6'd38: zz=6'd43; 6'd39: zz=6'd36;
            6'd40: zz=6'd29; 6'd41: zz=6'd22; 6'd42: zz=6'd15; 6'd43: zz=6'd23;
            6'd44: zz=6'd30; 6'd45: zz=6'd37; 6'd46: zz=6'd44; 6'd47: zz=6'd51;
            6'd48: zz=6'd58; 6'd49: zz=6'd59; 6'd50: zz=6'd52; 6'd51: zz=6'd45;
            6'd52: zz=6'd38; 6'd53: zz=6'd31; 6'd54: zz=6'd39; 6'd55: zz=6'd46;
            6'd56: zz=6'd53; 6'd57: zz=6'd60; 6'd58: zz=6'd61; 6'd59: zz=6'd54;
            6'd60: zz=6'd47; 6'd61: zz=6'd55; 6'd62: zz=6'd62; default: zz=6'd63;
        endcase
    endfunction

    wire wr_go   = i_in_valid && !bank_valid[w_bank];
    wire rd_go   = i_out_ready && bank_valid[r_bank];
    wire wr_done = wr_go && (w_idx == 32'd63);
    wire rd_done = rd_go && (r_idx == 32'd63);

    assign o_full  = (nfull == 32'd2);
    assign o_empty = !bank_valid[r_bank];

    // raster-order write into the current write bank
    always @(posedge i_clk)
        if (!i_reset && wr_go)
            mem[{w_bank, w_idx[5:0]}] <= i_coef;

    always @(posedge i_clk) begin
        if (i_reset) begin
            bank_valid <= 2'b00;
            w_bank     <= 1'b0;
            r_bank     <= 1'b0;
            w_idx      <= 32'd0;
            r_idx      <= 32'd0;
            nfull      <= 32'd0;
            o_valid    <= 1'b0;
        end else begin
            if (wr_go)   w_idx  <= wr_done ? 32'd0 : w_idx + 32'd1;
            if (wr_done) w_bank <= ~w_bank;
            if (rd_go)   r_idx  <= rd_done ? 32'd0 : r_idx + 32'd1;
            if (rd_done) r_bank <= ~r_bank;
            if (wr_done) bank_valid[w_bank] <= 1'b1;
            if (rd_done) bank_valid[r_bank] <= 1'b0;
            case ({wr_done, rd_done})
                2'b10:   nfull <= nfull + 32'd1;
                2'b01:   nfull <= nfull - 32'd1;
                default: nfull <= nfull;
            endcase
            // zigzag-order read from the current read bank
            if (i_out_ready) begin
                o_valid <= bank_valid[r_bank];
                if (rd_go)
                    o_coef <= mem[{r_bank, zz(r_idx[5:0])}];
            end
        end
    end

    // absence: the buffer is never full and empty at the same time
    always @(posedge i_clk)
        if (o_full)
            assert (!o_empty);
endmodule

module darki2s_tx (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [63:0] smp_l,
    input wire [63:0] smp_r,
    input wire start,
    input wire stop,
    output wire sd,
    output wire o_ws
);
    localparam [63:0] SLOT_END = 64'd63;
    reg [63:0] sh_l, sh_r, bit_cnt;
    reg ws, own_l, own_r, win;
    initial begin
        sh_l = 64'd0; sh_r = 64'd0; bit_cnt = 64'd0;
        ws = 1'b0; own_l = 1'b1; own_r = 1'b0; win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            sh_l <= 64'd0;
            sh_r <= 64'd0;
            bit_cnt <= 64'd0;
            ws <= 1'b0;
            own_l <= 1'b1;
            own_r <= 1'b0;
            win <= 1'b0;
        end else if (en) begin
            win <= start ? 1'b1 : (stop ? 1'b0 : win);
            if (bit_cnt == SLOT_END) begin
                bit_cnt <= 64'd0;
                ws <= ~ws;
                own_l <= own_r;
                own_r <= ~ws;
                if (~ws) begin
                    sh_r <= smp_r;
                    if (own_l) sh_l <= {sh_l[62:0], 1'b0};
                end else begin
                    sh_l <= smp_l;
                    if (own_r) sh_r <= {sh_r[62:0], 1'b0};
                end
            end else begin
                bit_cnt <= bit_cnt + 64'd1;
                if (own_l) sh_l <= {sh_l[62:0], 1'b0};
                if (own_r) sh_r <= {sh_r[62:0], 1'b0};
            end
        end
    end

    assign sd = ws ? sh_r[63] : sh_l[63];
    assign o_ws = ws;

    always @(posedge clk)
        if (win)
            assert (!(own_l && own_r));
endmodule

module tile_rf_led (
    input wire clk,
    input wire rst,
    input wire en,
    input wire ld,
    input wire [63:0] ld_data,
    input wire consume,
    input wire reshape,
    input wire [4:0] new_rows,
    output wire o_full,
    output wire [63:0] o_row0,
    output wire [63:0] o_fill
);
    localparam [4:0] DEF_ROWS = 5'd12;
    localparam [4:0] MAX_ROWS = 5'd16;

    reg [63:0] mem [0:15];
    reg [4:0] wptr;
    reg [63:0] fill_cnt;
    reg [4:0] shape_rows;
    reg pristine;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) mem[i] = 64'd0;
        wptr = 5'd0;
        fill_cnt = 64'd0;
        shape_rows = DEF_ROWS;
        pristine = 1'b1;
    end

    always @(posedge clk) begin
        if (rst) begin
            wptr <= 5'd0;
            fill_cnt <= 64'd0;
            shape_rows <= DEF_ROWS;
            pristine <= 1'b1;
        end else if (en) begin
            if (consume) begin
                wptr <= 5'd0;
                fill_cnt <= 64'd0;
            end else if (ld && (wptr != shape_rows)) begin
                mem[wptr[3:0]] <= ld_data;
                wptr <= wptr + 5'd1;
                fill_cnt <= fill_cnt + 64'd1;
            end else if (reshape && (wptr == 5'd0)) begin
                shape_rows <= (new_rows > MAX_ROWS) ? MAX_ROWS : new_rows;
                pristine <= 1'b0;
            end
        end
    end

    assign o_full = (wptr == shape_rows);
    assign o_row0 = mem[0];
    assign o_fill = fill_cnt;

    always @(posedge clk)
        if (pristine)
            assert (fill_cnt <= 64'd12);
endmodule

module benes_lane_shuffler (
    input  wire         clk,
    input  wire         rst,
    input  wire         en,
    input  wire         in_valid,
    input  wire [511:0] in_data,
    input  wire [7:0]   in_sel,
    input  wire         cfg_we,
    input  wire [7:0]   cfg_addr,
    input  wire [19:0]  cfg_bits,
    output wire         out_valid,
    output wire [511:0] out_data,
    output wire [63:0]  o_beats_done
);
    reg [19:0]  cfg_tab   [0:255];
    reg [3:0]   stage_cfg [0:4];
    reg [19:0]  cfg_pipe  [0:3];
    reg [511:0] data_pipe [0:4];
    reg [4:0]   valid_pipe;
    reg [63:0]  inflight;
    reg [63:0]  beats_done;
    reg         armed;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) cfg_tab[i] = 20'd0;
        for (i = 0; i < 5; i = i + 1) begin
            stage_cfg[i] = 4'd0;
            data_pipe[i] = 512'd0;
        end
        for (i = 0; i < 4; i = i + 1) cfg_pipe[i] = 20'd0;
        valid_pipe = 5'd0;
        inflight   = 64'd0;
        beats_done = 64'd0;
        armed      = 1'b0;
    end

    // butterfly stage, pair distance 4
    function [511:0] sw4;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw4[0*64 +: 64] = c[0] ? d[4*64 +: 64] : d[0*64 +: 64];
            sw4[4*64 +: 64] = c[0] ? d[0*64 +: 64] : d[4*64 +: 64];
            sw4[1*64 +: 64] = c[1] ? d[5*64 +: 64] : d[1*64 +: 64];
            sw4[5*64 +: 64] = c[1] ? d[1*64 +: 64] : d[5*64 +: 64];
            sw4[2*64 +: 64] = c[2] ? d[6*64 +: 64] : d[2*64 +: 64];
            sw4[6*64 +: 64] = c[2] ? d[2*64 +: 64] : d[6*64 +: 64];
            sw4[3*64 +: 64] = c[3] ? d[7*64 +: 64] : d[3*64 +: 64];
            sw4[7*64 +: 64] = c[3] ? d[3*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 2
    function [511:0] sw2;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw2[0*64 +: 64] = c[0] ? d[2*64 +: 64] : d[0*64 +: 64];
            sw2[2*64 +: 64] = c[0] ? d[0*64 +: 64] : d[2*64 +: 64];
            sw2[1*64 +: 64] = c[1] ? d[3*64 +: 64] : d[1*64 +: 64];
            sw2[3*64 +: 64] = c[1] ? d[1*64 +: 64] : d[3*64 +: 64];
            sw2[4*64 +: 64] = c[2] ? d[6*64 +: 64] : d[4*64 +: 64];
            sw2[6*64 +: 64] = c[2] ? d[4*64 +: 64] : d[6*64 +: 64];
            sw2[5*64 +: 64] = c[3] ? d[7*64 +: 64] : d[5*64 +: 64];
            sw2[7*64 +: 64] = c[3] ? d[5*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    // pair distance 1 (middle stage)
    function [511:0] sw1;
        input [511:0] d;
        input [3:0]   c;
        begin
            sw1[0*64 +: 64] = c[0] ? d[1*64 +: 64] : d[0*64 +: 64];
            sw1[1*64 +: 64] = c[0] ? d[0*64 +: 64] : d[1*64 +: 64];
            sw1[2*64 +: 64] = c[1] ? d[3*64 +: 64] : d[2*64 +: 64];
            sw1[3*64 +: 64] = c[1] ? d[2*64 +: 64] : d[3*64 +: 64];
            sw1[4*64 +: 64] = c[2] ? d[5*64 +: 64] : d[4*64 +: 64];
            sw1[5*64 +: 64] = c[2] ? d[4*64 +: 64] : d[5*64 +: 64];
            sw1[6*64 +: 64] = c[3] ? d[7*64 +: 64] : d[6*64 +: 64];
            sw1[7*64 +: 64] = c[3] ? d[6*64 +: 64] : d[7*64 +: 64];
        end
    endfunction

    wire [19:0] cfg0 = cfg_tab[in_sel];

    always @(posedge clk) begin
        if (rst) begin
            for (i = 0; i < 256; i = i + 1) cfg_tab[i] <= 20'd0;
            for (i = 0; i < 5; i = i + 1) begin
                stage_cfg[i] <= 4'd0;
                data_pipe[i] <= 512'd0;
            end
            for (i = 0; i < 4; i = i + 1) cfg_pipe[i] <= 20'd0;
            valid_pipe <= 5'd0;
            inflight   <= 64'd0;
            beats_done <= 64'd0;
            armed      <= 1'b0;
        end else if (en) begin
            if (cfg_we) begin
                cfg_tab[cfg_addr] <= cfg_bits;
                armed <= 1'b1;
            end
            data_pipe[0] <= sw4(in_data, cfg0[3:0]);
            stage_cfg[0] <= cfg0[3:0];
            cfg_pipe[0]  <= cfg0;
            data_pipe[1] <= sw2(data_pipe[0], cfg_pipe[0][7:4]);
            stage_cfg[1] <= cfg_pipe[0][7:4];
            cfg_pipe[1]  <= cfg_pipe[0];
            data_pipe[2] <= sw1(data_pipe[1], cfg_pipe[1][11:8]);
            stage_cfg[2] <= cfg_pipe[1][11:8];
            cfg_pipe[2]  <= cfg_pipe[1];
            data_pipe[3] <= sw2(data_pipe[2], cfg_pipe[2][15:12]);
            stage_cfg[3] <= cfg_pipe[2][15:12];
            cfg_pipe[3]  <= cfg_pipe[2];
            data_pipe[4] <= sw4(data_pipe[3], cfg_pipe[3][19:16]);
            stage_cfg[4] <= cfg_pipe[3][19:16];
            valid_pipe <= {valid_pipe[3:0], in_valid};
            inflight   <= inflight + {63'd0, in_valid} - {63'd0, valid_pipe[4]};
            if (valid_pipe[4])
                beats_done <= beats_done + 64'd1;
        end
    end

    assign out_valid    = valid_pipe[4];
    assign out_data     = data_pipe[4];
    assign o_beats_done = beats_done;

    always @(posedge clk)
        if (armed)
            assert (inflight <= 64'd5);
endmodule

module prbs_win_checker (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_bit,
    input  wire        i_arm,
    input  wire        i_disarm,
    output wire        o_sync,
    output wire [63:0] o_errs
);
    localparam [63:0] SYNC_LEN = 64'd8;
    localparam [63:0] LOSS_LEN = 64'd4;
    localparam [63:0] MAXV     = 64'hFFFFFFFFFFFFFFFF;

    reg [63:0] ref_sr;
    reg        sync;
    reg [63:0] match_run;
    reg [63:0] bad_run;
    reg [63:0] err_cnt;
    reg        win;
    reg [63:0] err_snap;
    reg [63:0] win_errs;

    initial ref_sr    = 64'h1;
    initial sync      = 1'b0;
    initial match_run = 64'd0;
    initial bad_run   = 64'd0;
    initial err_cnt   = 64'd0;
    initial win       = 1'b0;
    initial err_snap  = 64'd0;
    initial win_errs  = 64'd0;

    // PRBS x^64 + x^63 + x^61 + x^60 + 1 prediction
    wire        pred    = ref_sr[63] ^ ref_sr[62] ^ ref_sr[60] ^ ref_sr[59];
    wire        mism    = sync && (i_bit != pred);
    wire        cnt_inc = mism && (err_cnt != MAXV);
    wire [63:0] err_nxt = cnt_inc ? (err_cnt + 64'd1) : err_cnt;
    wire        lose    = mism && ((bad_run + 64'd1) >= LOSS_LEN);
    wire        open_w  = i_arm && sync && !lose && !i_disarm;
    wire        close_w = i_disarm || lose;

    always @(posedge clk) begin
        if (i_reset) begin
            ref_sr    <= 64'h1;
            sync      <= 1'b0;
            match_run <= 64'd0;
            bad_run   <= 64'd0;
            err_cnt   <= 64'd0;
            win       <= 1'b0;
            err_snap  <= 64'd0;
            win_errs  <= 64'd0;
        end else if (i_ce) begin
            err_cnt <= err_nxt;
            if (!sync) begin
                // self-synchronising: load incoming stream into reference
                ref_sr  <= {ref_sr[62:0], i_bit};
                bad_run <= 64'd0;
                if (i_bit == pred) begin
                    if ((match_run + 64'd1) >= SYNC_LEN) begin
                        sync      <= 1'b1;
                        match_run <= 64'd0;
                    end else begin
                        match_run <= match_run + 64'd1;
                    end
                end else begin
                    match_run <= 64'd0;
                end
            end else begin
                // locked: free-run the local reference
                ref_sr    <= {ref_sr[62:0], pred};
                match_run <= 64'd0;
                if (mism) begin
                    if (lose) begin
                        sync    <= 1'b0;
                        bad_run <= 64'd0;
                    end else begin
                        bad_run <= bad_run + 64'd1;
                    end
                end else begin
                    bad_run <= 64'd0;
                end
            end
            // measurement window: opened by arm while locked, closed by disarm or sync loss
            if (win) begin
                if (close_w) win <= 1'b0;
                if (cnt_inc) win_errs <= win_errs + 64'd1;
            end else if (open_w) begin
                win      <= 1'b1;
                err_snap <= err_nxt;
                win_errs <= 64'd0;
            end
        end
    end

    assign o_sync = sync;
    assign o_errs = err_cnt;

    // Precedence inside the window: a nonzero window tally requires the global
    // counter to have advanced past the snapshot recorded when the window opened.
    always @(*)
        if (win && (win_errs != 64'd0))
            assert (err_cnt != err_snap);

    // With no window errors, the global counter must still equal the snapshot.
    always @(*)
        if (win && (win_errs == 64'd0))
            assert (err_cnt == err_snap);
endmodule

module conv_interleaver (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_resync,
    input  wire [7:0] i_sym,
    output reg  [7:0] o_sym,
    output wire       o_fin
);
    // commutator branch counter and revolution counter
    reg [7:0] br  = 8'd0;
    reg [7:0] rev = 8'd0;
    // chain FSM: 0 IDLE, 1 ARMED (first symbol), 2 STARTED (first wrap), 3 FINISHED (second wrap)
    reg [1:0] phase = 2'd0;
    // scope latch: high until the first resync event
    reg before_r = 1'b1;
    reg pv = 1'b0;
    // per-branch delay memories: branch k delays by k symbols
    reg [7:0] d1_0 = 8'd0;
    reg [7:0] d2_0 = 8'd0, d2_1 = 8'd0;
    reg [7:0] d3_0 = 8'd0, d3_1 = 8'd0, d3_2 = 8'd0;
    initial o_sym = 8'd0;

    wire wrap = (br == 8'd3);
    wire fin  = (phase == 2'd3);
    assign o_fin = fin;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_resync) begin
            br       <= 8'd0;
            rev      <= 8'd0;
            phase    <= 2'd0;
            before_r <= 1'b0;
        end else if (i_ce) begin
            br <= wrap ? 8'd0 : br + 8'd1;
            if (wrap && rev != 8'd3) rev <= rev + 8'd1;
            case (phase)
                2'd0:    phase <= 2'd1;
                2'd1:    if (wrap) phase <= 2'd2;
                2'd2:    if (wrap) phase <= 2'd3;
                default: phase <= 2'd3;
            endcase
            case (br)
                8'd0: o_sym <= i_sym;
                8'd1: begin o_sym <= d1_0; d1_0 <= i_sym; end
                8'd2: begin o_sym <= d2_1; d2_1 <= d2_0; d2_0 <= i_sym; end
                default: begin o_sym <= d3_2; d3_2 <= d3_1; d3_1 <= d3_0; d3_0 <= i_sym; end
            endcase
        end
    end

    // finish may only be observed after arm and start: exactly two revolutions done
    always @(posedge clk)
        if (pv && before_r && $rose(fin))
            assert (rev == 8'd2);
endmodule

module GF8MulCore (
    input wire clk,
    input wire rst,
    input wire en,
    input wire req,
    input wire [7:0] a_in,
    input wire [7:0] b_in,
    input wire [7:0] poly_in,
    input wire poly_we,
    output reg done,
    output wire [7:0] result
);
    reg [7:0] acc;
    reg [7:0] a_reg;
    reg [7:0] b_reg;
    reg [7:0] poly;
    reg [7:0] bitcnt;
    reg [7:0] deadline;
    reg busy;
    reg armed;

    initial begin
        acc = 8'd0;
        a_reg = 8'd0;
        b_reg = 8'd0;
        poly = 8'd0;
        bitcnt = 8'd0;
        deadline = 8'd0;
        busy = 1'b0;
        armed = 1'b0;
        done = 1'b0;
    end

    assign result = acc;

    wire [7:0] a_shl = {a_reg[6:0], 1'b0};
    wire [7:0] xtime = a_reg[7] ? (a_shl ^ poly) : a_shl;

    always @(posedge clk) begin
        if (rst) begin
            acc <= 8'd0;
            a_reg <= 8'd0;
            b_reg <= 8'd0;
            poly <= 8'd0;
            bitcnt <= 8'd0;
            deadline <= 8'd0;
            busy <= 1'b0;
            armed <= 1'b0;
            done <= 1'b0;
        end else if (en) begin
            done <= 1'b0;
            if (poly_we && !busy)
                poly <= poly_in;
            if (!busy) begin
                if (req) begin
                    busy <= 1'b1;
                    armed <= 1'b1;
                    acc <= 8'd0;
                    a_reg <= a_in;
                    b_reg <= b_in;
                    bitcnt <= 8'd8;
                    deadline <= 8'd9;
                end
            end else if (bitcnt != 8'd0) begin
                if (b_reg[0])
                    acc <= acc ^ a_reg;
                a_reg <= xtime;
                b_reg <= {1'b0, b_reg[7:1]};
                bitcnt <= bitcnt - 8'd1;
                deadline <= deadline - 8'd1;
            end else begin
                busy <= 1'b0;
                deadline <= 8'd0;
                done <= 1'b1;
            end
        end
    end

    assert property (!(armed && busy) || (deadline != 8'd0));
endmodule

module mcycle_epoch (
    input  wire        clk,
    input  wire        i_ce,
    output wire [63:0] o_cycle,
    output wire [63:0] o_epoch
);
    // 64-bit synchronous binary up counter (cycle CSR style) with a
    // pipelined lookahead carry out of the low 32-bit half that drives
    // an epoch counter tracking high-half advances.
    reg [63:0] cnt;
    reg        carry_q;
    reg [63:0] epoch;
    reg        armed;
    reg        pv;
    initial cnt     = 64'd0;
    initial carry_q = 1'b0;
    initial epoch   = 64'd0;
    initial armed   = 1'b0;
    initial pv      = 1'b0;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (i_ce) begin
            cnt     <= cnt + 64'd1;
            carry_q <= (cnt[31:0] == 32'hFFFFFFFE);
            if (carry_q)
                epoch <= epoch + 64'd1;
            armed   <= 1'b1;
        end
    end

    assign o_cycle = cnt;
    assign o_epoch = epoch;

    // after the first enabled cycle: if the high half of the counter did
    // not change, the epoch counter must not have changed either
    always @(posedge clk)
        if (pv && armed && $stable(cnt[63:32]))
            assert ($stable(epoch));
endmodule

module bitslip_align (
    input  wire        clk,
    input  wire        i_ce,
    input  wire        i_slip,
    input  wire        i_lock,
    input  wire [31:0] i_word,
    output wire [31:0] o_word,
    output wire        o_armed
);
    // two-word window of the incoming serial stream
    reg [63:0] window  = 64'd0;
    // slip offset (up counter) and its redundant remaining-slips counter (down counter)
    reg [31:0] slip    = 32'd0;
    reg [31:0] slip_dn = 32'd31;
    // sticky: set the first time word lock is reported
    reg        armed   = 1'b0;

    always @(posedge clk) begin
        if (i_ce) begin
            window <= {window[31:0], i_word};
            if (i_lock)
                armed <= 1'b1;
            if (i_slip) begin
                // up counter wraps when the down counter is exhausted
                slip    <= (slip_dn == 32'd0)  ? 32'd0  : slip + 32'd1;
                // down counter reloads when the up counter hits the last offset
                slip_dn <= (slip == 32'd31)    ? 32'd31 : slip_dn - 32'd1;
            end
        end
    end

    wire [63:0] shifted = window << slip[4:0];
    assign o_word  = shifted[63:32];
    assign o_armed = armed;

    // after lock: the slip offset never exceeds one word width minus one
    always @(posedge clk)
        if (armed)
            assert (slip <= 32'd31);

    // after lock: the remaining-slip counter never exceeds one word width minus one
    always @(posedge clk)
        if (armed)
            assert (slip_dn <= 32'd31);
endmodule

module eink_cic_decim (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire [127:0] din,
    output wire [127:0] o_pix,
    output wire         o_valid
);
    // 2-stage CIC decimator (R=4) smoothing grayscale waveform drive levels
    reg [127:0] integ1, integ2;
    reg [127:0] comb1_dly, comb2_dly;
    reg [127:0] dout;
    reg [1:0]   phase;
    reg         seen_nz;   // shadow: a nonzero sample has been accepted
    reg         vld;
    initial integ1 = 128'd0;
    initial integ2 = 128'd0;
    initial comb1_dly = 128'd0;
    initial comb2_dly = 128'd0;
    initial dout = 128'd0;
    initial phase = 2'd0;
    initial seen_nz = 1'b0;
    initial vld = 1'b0;

    wire [127:0] c1 = integ2 - comb1_dly;
    wire [127:0] c2 = c1 - comb2_dly;

    always @(posedge clk) begin
        if (rst) begin
            integ1 <= 128'd0;
            integ2 <= 128'd0;
            comb1_dly <= 128'd0;
            comb2_dly <= 128'd0;
            dout <= 128'd0;
            phase <= 2'd0;
            seen_nz <= 1'b0;
            vld <= 1'b0;
        end else if (i_ce) begin
            integ1 <= integ1 + din;
            integ2 <= integ2 + integ1;
            phase <= phase + 2'd1;
            if (din != 128'd0)
                seen_nz <= 1'b1;
            if (phase == 2'd3) begin
                comb1_dly <= integ2;
                comb2_dly <= c1;
                dout <= c2;
                vld <= 1'b1;
            end else begin
                vld <= 1'b0;
            end
        end
    end

    assign o_pix = dout;
    assign o_valid = vld;

    // Precedence: a nonzero output requires a nonzero input accepted earlier
    always @(posedge clk)
        if (dout != 128'd0) assert (seen_nz);
endmodule

module meta_sync_burst (
    input  wire        clk,
    input  wire        ce,
    input  wire [31:0] async_main,
    input  wire [31:0] async_shadow,
    input  wire        win_open,
    input  wire        win_close,
    output wire [31:0] sync_q,
    output wire        meta_err
);
    reg [31:0] main_q   = 32'd0;
    reg [31:0] shadow_q = 32'd0;
    reg        err_flag = 1'b0;
    reg        win      = 1'b0;
    reg [31:0] burst    = 32'd0;
    reg [31:0] budget   = 32'd16;

    assign sync_q   = main_q;
    assign meta_err = err_flag;

    always @(posedge clk) begin
        if (ce) begin
            main_q   <= async_main;
            shadow_q <= async_shadow;
            err_flag <= (main_q != shadow_q);
        end
    end

    always @(posedge clk) begin
        if (ce) begin
            if (win_open) begin
                win    <= 1'b1;
                burst  <= 32'd0;
                budget <= 32'd16;
            end else if (win_close) begin
                win <= 1'b0;
            end else if (win && err_flag && (budget != 32'd0)) begin
                burst  <= burst + 32'd1;
                budget <= budget - 32'd1;
            end
        end
    end

    always @(posedge clk)
        assert (!win || burst <= 32'd16);
endmodule

module welch_spectral_avg (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [7:0]  mag,
    input  wire        dump,
    input  wire [6:0]  rd_addr,
    output wire [23:0] rd_data,
    output wire        avg_done
);
    // per-bin accumulation RAM for squared magnitudes
    reg [23:0] acc [0:127];
    reg [7:0]  bin_idx      = 8'd0;
    reg [7:0]  frame_cnt    = 8'd0;
    reg [10:0] samples_left = 11'd1024;
    reg        armed        = 1'b1;   // high until the first dump event

    integer i;
    initial begin
        for (i = 0; i < 128; i = i + 1)
            acc[i] = 24'd0;
    end

    wire [15:0] sq     = mag * mag;
    wire        accept = in_valid && (!armed || samples_left != 11'd0);

    always @(posedge clk) begin
        if (dump) begin
            armed        <= 1'b0;
            bin_idx      <= 8'd0;
            frame_cnt    <= 8'd0;
            samples_left <= 11'd0;
        end else if (accept) begin
            acc[bin_idx[6:0]] <= ((frame_cnt == 8'd0) ? 24'd0 : acc[bin_idx[6:0]]) + {8'd0, sq};
            if (bin_idx == 8'd127) begin
                bin_idx   <= 8'd0;
                frame_cnt <= frame_cnt + 8'd1;
            end else begin
                bin_idx <= bin_idx + 8'd1;
            end
            if (armed)
                samples_left <= samples_left - 11'd1;
        end
    end

    // 8-frame Welch average: divide accumulated power by 8
    assign rd_data  = acc[rd_addr] >> 3;
    assign avg_done = armed && (samples_left == 11'd0);

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    // Before the first dump, the frame count never exceeded 8
    always @(posedge clk)
        if (pv && armed)
            assert ($past(frame_cnt) <= 8'd8);
endmodule

module ppu_clkfail_ctl (
    input  wire clk,
    input  wire rst_n,
    input  wire en,
    input  wire prim_fail,
    output wire use_backup,
    output wire busy,
    output wire fail_flag
);
    localparam [7:0] SETTLE = 8'd200;

    reg       sel_src     = 1'b0;
    reg       switching   = 1'b0;
    reg [7:0] settle_cnt  = 8'd0;
    reg       sticky_fail = 1'b0;
    reg [7:0] fail_cnt    = 8'd0;
    reg       fail_seen   = 1'b0;

    always @(posedge clk) begin
        if (!rst_n) begin
            sel_src     <= 1'b0;
            switching   <= 1'b0;
            settle_cnt  <= 8'd0;
            sticky_fail <= 1'b0;
            fail_cnt    <= 8'd0;
            fail_seen   <= 1'b0;
        end else if (en) begin
            if (prim_fail) begin
                fail_seen   <= 1'b1;
                sticky_fail <= 1'b1;
                if (fail_cnt != 8'd255)
                    fail_cnt <= fail_cnt + 8'd1;
            end
            if (prim_fail && !sel_src && !switching) begin
                switching  <= 1'b1;
                settle_cnt <= SETTLE;
            end else if (switching) begin
                settle_cnt <= settle_cnt - 8'd1;
                if (settle_cnt == 8'd1) begin
                    sel_src   <= 1'b1;
                    switching <= 1'b0;
                end
            end
        end
    end

    assign use_backup = sel_src;
    assign busy       = switching;
    assign fail_flag  = sticky_fail;

    always @(posedge clk)
        if (sel_src)
            assert (fail_seen);
endmodule

module cam_key_scan (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire [7:0]  col_in,
    output reg  [31:0] row_n,
    output wire [7:0]  key_map_out
);
    localparam [7:0] DWELL = 8'd200;

    reg [7:0] row_idx;
    reg [7:0] scan_tmr;
    reg [7:0] key_map [0:31];
    integer i;

    initial begin
        row_idx  = 8'd0;
        scan_tmr = 8'd0;
        row_n    = 32'hFFFF_FFFE;
        for (i = 0; i < 32; i = i + 1) key_map[i] = 8'd0;
    end

    wire [7:0] nxt = (row_idx == 8'd31) ? 8'd0 : (row_idx + 8'd1);

    always @(posedge clk) begin
        if (rst) begin
            row_idx  <= 8'd0;
            scan_tmr <= 8'd0;
            row_n    <= 32'hFFFF_FFFE;
        end else if (en) begin
            if (scan_tmr == DWELL - 8'd1) begin
                scan_tmr <= 8'd0;
                key_map[row_idx[4:0]] <= ~col_in;
                row_idx  <= nxt;
                row_n    <= ~(32'b1 << nxt);
            end else begin
                scan_tmr <= scan_tmr + 8'd1;
            end
        end
    end

    assign key_map_out = key_map[row_idx[4:0]];

    reg pv = 1'b0;
    reg rst_q = 1'b1;
    always @(posedge clk) begin
        pv    <= 1'b1;
        rst_q <= rst;
    end

    always @(posedge clk)
        if (pv && !rst_q)
            assert (row_n == $past(row_n) || row_n == {$past(row_n[30:0]), $past(row_n[31])});
endmodule

module nan_canon_log (
    input wire clk,
    input wire i_ce,
    input wire [15:0] i_a,
    input wire [15:0] i_b,
    input wire i_canon,
    input wire i_pop,
    output wire [15:0] o_result,
    output wire o_invalid,
    output wire [15:0] o_log_head,
    output wire [15:0] o_occ
);
    localparam [15:0] QNAN_CANON = 16'h7E00;
    localparam [15:0] QUIET_BIT  = 16'h0200;

    // half-precision NaN classification
    wire a_nan  = (i_a[14:10] == 5'h1f) && (i_a[9:0] != 10'd0);
    wire b_nan  = (i_b[14:10] == 5'h1f) && (i_b[9:0] != 10'd0);
    wire a_snan = a_nan && !i_a[9];
    wire b_snan = b_nan && !i_b[9];
    wire any_nan = a_nan | b_nan;

    // NaN selection / quieting / canonicalization
    reg [15:0] sel;
    always @(*) begin
        if (i_canon)     sel = QNAN_CANON;
        else if (a_snan) sel = i_a | QUIET_BIT;
        else if (b_snan) sel = i_b | QUIET_BIT;
        else if (a_nan)  sel = i_a;
        else             sel = i_b;
    end
    wire [15:0] nxt = any_nan ? sel : i_a;

    reg [15:0] r_result = 16'd0;
    reg        r_invalid = 1'b0;
    reg [3:0]  wptr = 4'd0;
    reg [3:0]  rptr = 4'd0;
    reg [15:0] occ  = 16'd0;
    reg [15:0] log_mem [0:7];
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1) log_mem[i] = 16'd0;
    end

    wire [3:0] fill  = wptr - rptr;
    wire full  = (fill == 4'd8);
    wire empty = (fill == 4'd0);
    wire push_ok = i_ce && any_nan && !full;
    wire pop_ok  = i_pop && !empty;

    always @(posedge clk) begin
        if (i_ce) begin
            r_result  <= nxt;
            r_invalid <= a_snan | b_snan;
        end
        if (push_ok) begin
            log_mem[wptr[2:0]] <= sel;
            wptr <= wptr + 4'd1;
        end
        if (pop_ok)
            rptr <= rptr + 4'd1;
        case ({push_ok, pop_ok})
            2'b10: occ <= occ + 16'd1;
            2'b01: occ <= occ - 16'd1;
            default: ;
        endcase
    end

    assign o_result   = r_result;
    assign o_invalid  = r_invalid;
    assign o_log_head = log_mem[rptr[2:0]];
    assign o_occ      = occ;

    always @(posedge clk) assert (occ <= 16'd8);
endmodule

module lin_master_tx (
    input wire clk,
    input wire rst,
    input wire i_tick,
    input wire i_start,
    input wire i_abort,
    input wire i_enhanced,
    input wire [5:0] i_id,
    input wire [3:0] i_len,
    input wire i_wr_en,
    input wire [3:0] i_wr_addr,
    input wire [31:0] i_wr_data,
    output wire o_busy,
    output wire o_bus_low,
    output wire [31:0] o_tx_byte
);
    // one-hot frame phase: 0 IDLE, 1 BREAK, 2 SYNC, 3 PID, 4 DATA, 5 CSUM
    reg [5:0] phase;
    initial phase = 6'b000001;
    reg [31:0] brk_cnt = 32'd0;
    reg [31:0] byte_idx = 32'd0;
    reg [31:0] bytes_left = 32'd0;
    reg [31:0] frame_len = 32'd1;
    reg [31:0] csum = 32'd0;
    reg [31:0] tx_byte = 32'd0;
    reg [7:0] pid_reg = 8'd0;
    reg [31:0] data_buf [0:15];
    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) data_buf[i] = 32'd0;
    end
    reg armed = 1'b1;
    reg pv = 1'b0;

    wire [7:0] cur_byte = data_buf[byte_idx[3:0]][7:0];
    wire [8:0] csum_sum = {1'b0, csum[7:0]} + {1'b0, cur_byte};
    wire [7:0] csum_next = csum_sum[8] ? (csum_sum[7:0] + 8'd1) : csum_sum[7:0];
    wire p0 = i_id[0] ^ i_id[1] ^ i_id[2] ^ i_id[4];
    wire p1 = ~(i_id[1] ^ i_id[3] ^ i_id[4] ^ i_id[5]);
    wire [7:0] pid_calc = {p1, p0, i_id};

    always @(posedge clk) begin
        pv <= 1'b1;
        if (i_abort) armed <= 1'b0;
    end

    always @(posedge clk) begin
        if (i_wr_en) data_buf[i_wr_addr] <= i_wr_data;
    end

    always @(posedge clk) begin
        if (rst || i_abort) begin
            phase <= 6'b000001;
            brk_cnt <= 32'd0;
            byte_idx <= 32'd0;
            bytes_left <= 32'd0;
        end else if (i_tick) begin
            if (phase[0] && i_start) begin
                phase[0] <= 1'b0;
                phase[1] <= 1'b1;
                brk_cnt <= 32'd0;
                frame_len <= {28'd0, i_len} + 32'd1;
                pid_reg <= pid_calc;
                csum <= i_enhanced ? {24'd0, pid_calc} : 32'd0;
            end
            if (phase[1]) begin
                if (brk_cnt == 32'd12) begin
                    phase[1] <= 1'b0;
                    phase[2] <= 1'b1;
                end
                brk_cnt <= brk_cnt + 32'd1;
            end
            if (phase[2]) begin
                tx_byte <= 32'h00000055;
                phase[2] <= 1'b0;
                phase[3] <= 1'b1;
            end
            if (phase[3]) begin
                tx_byte <= {24'd0, pid_reg};
                byte_idx <= 32'd0;
                bytes_left <= frame_len;
                phase[3] <= 1'b0;
                phase[4] <= 1'b1;
            end
            if (phase[4]) begin
                tx_byte <= {24'd0, cur_byte};
                csum <= {24'd0, csum_next};
                byte_idx <= byte_idx + 32'd1;
                bytes_left <= bytes_left - 32'd1;
                if (byte_idx == frame_len - 32'd1) phase[4] <= 1'b0;
                if (bytes_left == 32'd1) phase[5] <= 1'b1;
            end
            if (phase[5]) begin
                tx_byte <= {24'd0, ~csum[7:0]};
                phase[5] <= 1'b0;
                phase[0] <= 1'b1;
            end
        end
    end

    assign o_busy = !phase[0];
    assign o_bus_low = phase[1];
    assign o_tx_byte = tx_byte;

    // Absence, before first abort: checksum phase never begins while data phase is still active
    always @(posedge clk)
        if (pv && armed && $rose(phase[5]))
            assert (!phase[4]);
endmodule

module femto_trace_ser (
    input wire clk,
    input wire rst,
    input wire en,
    input wire arm,
    input wire start,
    input wire ack,
    input wire flush,
    input wire [31:0] data_in,
    output wire sout
);
    localparam [1:0] IDLE = 2'd0, ARMED = 2'd1, SHIFT = 2'd2, DONE = 2'd3;

    reg [1:0]  phase;
    reg [31:0] load_reg;
    reg [31:0] shift_reg;
    reg [31:0] bit_cnt;
    reg armed_f, started_f, finished_f;
    reg win;

    initial begin
        phase = IDLE;
        load_reg = 32'd0;
        shift_reg = 32'd0;
        bit_cnt = 32'd0;
        armed_f = 1'b0;
        started_f = 1'b0;
        finished_f = 1'b0;
        win = 1'b0;
    end

    always @(posedge clk) begin
        if (rst) begin
            phase <= IDLE;
            load_reg <= 32'd0;
            shift_reg <= 32'd0;
            bit_cnt <= 32'd0;
            armed_f <= 1'b0;
            started_f <= 1'b0;
            finished_f <= 1'b0;
            win <= 1'b0;
        end else if (en) begin
            if (flush) begin
                win <= 1'b0;
                armed_f <= 1'b0;
                started_f <= 1'b0;
                finished_f <= 1'b0;
                phase <= IDLE;
            end else begin
                case (phase)
                    IDLE: begin
                        if (arm) begin
                            load_reg <= data_in;
                            armed_f <= 1'b1;
                            phase <= ARMED;
                            win <= 1'b1;
                        end
                    end
                    ARMED: begin
                        if (start) begin
                            shift_reg <= load_reg;
                            bit_cnt <= 32'd0;
                            started_f <= 1'b1;
                            phase <= SHIFT;
                        end
                    end
                    SHIFT: begin
                        shift_reg <= {shift_reg[30:0], 1'b0};
                        bit_cnt <= bit_cnt + 32'd1;
                        if (bit_cnt == 32'd31) begin
                            finished_f <= 1'b1;
                            phase <= DONE;
                        end
                    end
                    DONE: begin
                        if (ack) begin
                            armed_f <= 1'b0;
                            started_f <= 1'b0;
                            finished_f <= 1'b0;
                            phase <= IDLE;
                        end
                    end
                endcase
            end
        end
    end

    assign sout = shift_reg[31];

    always @(posedge clk)
        if (win && finished_f)
            assert (started_f);

    always @(posedge clk)
        if (win && started_f)
            assert (armed_f);
endmodule

module ec_jdbl_seq (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        arm,
    input  wire        start,
    input  wire        clr,
    input  wire        sel_add,
    input  wire        wr_en,
    input  wire [3:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire        o_done,
    output wire [31:0] o_acc,
    output wire [31:0] o_x3
);
    localparam [31:0] PRIME = 32'hFFFFFFFB;
    localparam [31:0] LAST  = 32'd11;
    localparam [1:0]  OP_MUL = 2'd0;
    localparam [1:0]  OP_ADD = 2'd1;
    localparam [1:0]  OP_SUB = 2'd2;

    reg        armed;
    reg        started;
    reg        done;
    reg        pre_clr;
    reg        mode;
    reg [31:0] step;
    reg [31:0] acc;
    reg [31:0] rf [0:15];

    integer i;
    initial begin
        armed   = 1'b0;
        started = 1'b0;
        done    = 1'b0;
        pre_clr = 1'b1;
        mode    = 1'b0;
        step    = 32'd0;
        acc     = 32'd0;
        for (i = 0; i < 16; i = i + 1)
            rf[i] = 32'd0;
    end

    function [31:0] fadd;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            s = {1'b0, a} + {1'b0, b};
            if (s >= {1'b0, PRIME})
                s = s - {1'b0, PRIME};
            fadd = s[31:0];
        end
    endfunction

    function [31:0] fsub;
        input [31:0] a;
        input [31:0] b;
        reg [32:0] s;
        begin
            if (a >= b)
                s = {1'b0, a} - {1'b0, b};
            else
                s = {1'b0, a} + {1'b0, PRIME} - {1'b0, b};
            fsub = s[31:0];
        end
    endfunction

    function [31:0] fmul;
        input [31:0] a;
        input [31:0] b;
        reg [63:0] p;
        reg [35:0] t;
        reg [35:0] u;
        begin
            p = {32'd0, a} * {32'd0, b};
            t = {4'd0, p[31:0]} + {4'd0, p[63:32]} * 36'd5;
            u = {4'd0, t[31:0]} + {32'd0, t[35:32]} * 36'd5;
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            if (u >= {4'd0, PRIME})
                u = u - {4'd0, PRIME};
            fmul = u[31:0];
        end
    endfunction

    reg [3:0] ra, rb, rd;
    reg [1:0] opc;
    always @(*) begin
        ra  = 4'd0;
        rb  = 4'd0;
        rd  = 4'd6;
        opc = OP_MUL;
        case (step)
            32'd1:  begin ra = 4'd1;  rb = mode ? 4'd4 : 4'd1; rd = 4'd6;  opc = OP_MUL; end
            32'd2:  begin ra = 4'd0;  rb = 4'd6;  rd = 4'd7;  opc = OP_MUL; end
            32'd3:  begin ra = 4'd0;  rb = mode ? 4'd3 : 4'd0; rd = 4'd8;  opc = OP_MUL; end
            32'd4:  begin ra = 4'd8;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd5:  begin ra = 4'd9;  rb = 4'd8;  rd = 4'd9;  opc = OP_ADD; end
            32'd6:  begin ra = 4'd9;  rb = 4'd9;  rd = 4'd10; opc = OP_MUL; end
            32'd7:  begin ra = 4'd7;  rb = 4'd7;  rd = 4'd11; opc = OP_ADD; end
            32'd8:  begin ra = 4'd10; rb = 4'd11; rd = 4'd12; opc = OP_SUB; end
            32'd9:  begin ra = mode ? 4'd2 : 4'd1; rb = mode ? 4'd5 : 4'd2; rd = 4'd13; opc = OP_MUL; end
            32'd10: begin ra = 4'd6;  rb = 4'd6;  rd = 4'd15; opc = OP_MUL; end
            default: begin ra = 4'd0; rb = 4'd0; rd = 4'd6; opc = OP_MUL; end
        endcase
    end

    wire [31:0] opa = rf[ra];
    wire [31:0] opb = rf[rb];
    reg  [31:0] res;
    always @(*) begin
        case (opc)
            OP_MUL:  res = fmul(opa, opb);
            OP_ADD:  res = fadd(opa, opb);
            OP_SUB:  res = fsub(opa, opb);
            default: res = opa;
        endcase
    end

    wire [31:0] y3 = fsub(fmul(rf[9], fsub(rf[7], rf[12])), rf[15]);
    wire [31:0] z3 = fadd(rf[13], rf[13]);

    always @(posedge clk) begin
        if (rst) begin
            armed   <= 1'b0;
            started <= 1'b0;
            done    <= 1'b0;
            pre_clr <= 1'b1;
            mode    <= 1'b0;
            step    <= 32'd0;
            acc     <= 32'd0;
        end else if (en) begin
            if (clr) begin
                armed   <= 1'b0;
                started <= 1'b0;
                done    <= 1'b0;
                pre_clr <= 1'b0;
            end else begin
                if (arm)
                    armed <= 1'b1;
                if (start && armed && step == 32'd0)
                    started <= 1'b1;
                if (step == LAST)
                    done <= 1'b1;
            end
            if (step == 32'd0) begin
                if (start && armed && !clr) begin
                    step <= 32'd1;
                    mode <= sel_add;
                end
            end else if (step == LAST) begin
                step <= 32'd0;
                acc  <= y3;
            end else begin
                step <= step + 32'd1;
                acc  <= res;
            end
        end
    end

    always @(posedge clk) begin
        if (!rst && en) begin
            if (step == 32'd0) begin
                if (wr_en)
                    rf[wr_addr] <= wr_data;
            end else if (step == LAST) begin
                rf[0] <= rf[12];
                rf[1] <= y3;
                rf[2] <= z3;
            end else begin
                rf[rd] <= res;
            end
        end
    end

    assign o_done = done;
    assign o_acc  = acc;
    assign o_x3   = rf[0];

    always @(*)
        if (pre_clr && done)
            assert (started && armed);
endmodule

module friscv_hart_rst_sync (
    input wire clk,
    input wire arst_n,
    input wire en,
    input wire soft_req,
    output wire hart_rst_n
);
    reg [3:0]  sync = 4'b0000;
    reg [63:0] cnt  = 64'd0;
    reg        pend = 1'b0;
    reg        win  = 1'b0;

    always @(posedge clk or negedge arst_n) begin
        if (!arst_n) begin
            sync <= 4'b0000;
            cnt  <= 64'd0;
            pend <= 1'b0;
            win  <= 1'b0;
        end else if (en) begin
            if (soft_req && !pend) begin
                sync <= 4'b0000;
                cnt  <= 64'd6;
                pend <= 1'b1;
                win  <= 1'b1;
            end else if (pend && sync != 4'b1111) begin
                sync <= {sync[2:0], 1'b1};
                cnt  <= cnt - 64'd1;
            end else if (pend) begin
                pend <= 1'b0;
                win  <= 1'b0;
            end
        end
    end

    assign hart_rst_n = sync[3];

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win && $rose(sync[3]))
            assert (cnt != 64'd0);
endmodule

module tta_loop_fu (
    input wire clk,
    input wire rst,
    input wire en,
    input wire load,
    input wire [31:0] bus,
    input wire tick,
    output reg [31:0] cnt,
    output reg [31:0] rem
);
    localparam [31:0] LIMIT = 32'd1000;

    initial cnt = 32'd0;
    initial rem = LIMIT;

    wire [31:0] v = (bus > LIMIT) ? LIMIT : bus;

    always @(posedge clk) begin
        if (en) begin
            if (rst) begin
                cnt <= 32'd0;
                rem <= LIMIT;
            end else if (load) begin
                cnt <= v;
                rem <= LIMIT - v;
            end else if (tick && rem != 32'd0) begin
                cnt <= cnt + 32'd1;
                rem <= rem - 32'd1;
            end
        end
    end

    always @(*) assert (cnt <= 32'd1000);
endmodule

module hadesv_mie_jk (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire j,
    input wire k,
    input wire trap_enter,
    input wire mret,
    output reg q,
    output reg [31:0] tcnt,
    output reg in_trap
);
    initial q = 1'b0;
    initial tcnt = 32'h00000000;
    initial in_trap = 1'b0;

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    wire q_next = (j & ~k) ? 1'b1 :
                  (~j & k) ? 1'b0 :
                  (j & k)  ? ~q   : q;

    always @(posedge clk) begin
        if (!rst_n) begin
            q <= 1'b0;
            tcnt <= 32'h00000000;
            in_trap <= 1'b0;
        end else if (en) begin
            q <= q_next;
            if (q_next != q)
                tcnt <= tcnt + 32'h00000001;
            if (mret)
                in_trap <= 1'b0;
            else if (trap_enter)
                in_trap <= 1'b1;
        end
    end

    always @(posedge clk) begin
        if (pv && rst_n && in_trap && $rose(q))
            assert (tcnt[0] == 1'b1);
    end
endmodule

module fft_tdm_bus (
    input  wire        clk,
    input  wire        step,
    input  wire        wr_en,
    input  wire [2:0]  wr_addr,
    input  wire [31:0] wr_data,
    output wire [31:0] bus
);
    // 8-entry butterfly result store, time-shared onto one tri-state bus
    reg [31:0] mem [0:7];
    reg [31:0] phase = 32'd0;   // time-share slot counter
    reg [7:0]  oe    = 8'h01;   // one-hot slot output enable
    reg        armed = 1'b0;    // sticky: first bus drive by slot 0 has happened
    integer i;
    initial begin
        for (i = 0; i < 8; i = i + 1)
            mem[i] = 32'd0;
    end

    always @(posedge clk) begin
        if (wr_en)
            mem[wr_addr] <= wr_data;
        if (step) begin
            oe <= {oe[6:0], oe[7]};
            if (oe[7])
                phase <= 32'd0;
            else
                phase <= phase + 32'd1;
            if (oe[0])
                armed <= 1'b1;
        end
    end

    // tri-state buffer: drive the selected butterfly word only while stepping
    assign bus = step ? mem[phase[2:0]] : 32'bz;

    always @(posedge clk)
        if (armed) assert (phase <= 32'd7);
endmodule

module wrapped_quad_dec (
    input  wire        clk,
    input  wire        rst,
    input  wire        proj_en,
    input  wire        enc_a,
    input  wire        enc_b,
    input  wire        wbs_stb_i,
    input  wire        wbs_cyc_i,
    input  wire        wbs_we_i,
    input  wire [3:0]  wbs_adr_i,
    output wire [31:0] wbs_dat_o,
    output wire        wbs_ack_o
);
    reg        a_q = 1'b0;
    reg        b_q = 1'b0;
    reg [15:0] pos = 16'd0;
    reg [15:0] err_cnt = 16'd0;
    reg        seen_step = 1'b0;
    reg        armed = 1'b0;
    reg        ack_q = 1'b0;

    wire da   = enc_a ^ a_q;
    wire db   = enc_b ^ b_q;
    wire step = da ^ db;
    wire dbl  = da & db;
    wire up   = a_q ^ enc_b;
    wire rd0  = proj_en && wbs_stb_i && wbs_cyc_i && !wbs_we_i && (wbs_adr_i == 4'd0);

    always @(posedge clk) begin
        if (rst) begin
            a_q       <= 1'b0;
            b_q       <= 1'b0;
            pos       <= 16'd0;
            err_cnt   <= 16'd0;
            seen_step <= 1'b0;
            armed     <= 1'b0;
            ack_q     <= 1'b0;
        end else if (proj_en) begin
            a_q <= enc_a;
            b_q <= enc_b;
            if (step) begin
                seen_step <= 1'b1;
                if (up)
                    pos <= pos + 16'd1;
                else
                    pos <= pos - 16'd1;
            end else if (dbl) begin
                err_cnt <= err_cnt + 16'd1;
            end
            if (rd0)
                armed <= 1'b1;
            ack_q <= wbs_stb_i && wbs_cyc_i && !ack_q;
        end
    end

    assign wbs_ack_o = ack_q;
    assign wbs_dat_o = (wbs_adr_i == 4'd0) ? {{16{pos[15]}}, pos} : {16'd0, err_cnt};

    assert property (!(armed && (pos != 16'd0)) || seen_step);
endmodule

module camsi_line_energy_acc (
    input wire clk,
    input wire rst_n,
    input wire en,
    input wire sol,
    input wire [31:0] px,
    output wire [31:0] o_energy,
    output wire o_sat
);
    localparam [31:0] LIMIT = 32'h00FF_FFFF;

    reg [31:0] acc;
    reg [31:0] headroom;
    reg        sat_flag;
    initial acc = 32'd0;
    initial headroom = LIMIT;
    initial sat_flag = 1'b0;

    always @(posedge clk) begin
        if (!rst_n) begin
            acc      <= 32'd0;
            headroom <= LIMIT;
            sat_flag <= 1'b0;
        end else if (en) begin
            if (sol) begin
                acc      <= 32'd0;
                headroom <= LIMIT;
                sat_flag <= 1'b0;
            end else if (px > headroom) begin
                acc      <= LIMIT;
                headroom <= 32'd0;
                sat_flag <= 1'b1;
            end else begin
                acc      <= acc + px;
                headroom <= headroom - px;
            end
        end
    end

    assign o_energy = acc;
    assign o_sat = sat_flag;

    always @(posedge clk)
        if (!sat_flag) assert (acc <= LIMIT);
endmodule

module gray_tally (
    input  wire        clk,
    input  wire        start,
    input  wire        stop,
    input  wire        step,
    output reg  [63:0] bin,
    output reg  [63:0] gray,
    output reg         armed
);
    initial bin   = 64'd0;
    initial gray  = 64'd0;
    initial armed = 1'b0;

    // next binary count and the bits that change on increment
    wire [63:0] bin_nx = bin + 64'd1;
    wire [63:0] diff   = bin ^ bin_nx;
    // binary-to-Gray conversion of the change mask: XOR each bit with its upper neighbour
    wire [63:0] flip   = diff ^ (diff >> 1);

    // tally counters: binary count plus an incrementally maintained Gray image
    always @(posedge clk) begin
        if (start) begin
            bin  <= 64'd0;
            gray <= 64'd0;
        end else if (step) begin
            bin  <= bin_nx;
            gray <= gray ^ flip;
        end
    end

    // observation window: opened by start, closed by stop (stop may never come)
    always @(posedge clk) begin
        if (start)
            armed <= 1'b1;
        else if (stop)
            armed <= 1'b0;
    end

    // inside the window the Gray image is zero exactly when the binary count is zero
    assert property (!armed || ((gray == 64'd0) == (bin == 64'd0)));
endmodule

module fb_scanout (
    input  wire        clk,
    input  wire        start,
    input  wire        ce,
    input  wire [31:0] base_in,
    output wire [31:0] o_addr,
    output wire        o_rd,
    output wire        o_eol,
    output wire        o_eof
);
    // 32 pixels per line, 32 lines per frame, raster-order scanout
    reg        armed    = 1'b0;
    reg [31:0] base     = 32'd0;
    reg [31:0] cur_addr = 32'd0;
    reg [31:0] line     = 32'd0;
    reg [31:0] px       = 32'd0;

    wire adv = armed && ce;
    wire eol = (px == 32'd31);
    wire eof = eol && (line == 32'd31);

    assign o_addr = cur_addr;
    assign o_rd   = adv;
    assign o_eol  = adv && eol;
    assign o_eof  = adv && eof;

    always @(posedge clk) begin
        if (start)
            armed <= 1'b1;
        if (adv) begin
            if (eof) begin
                base     <= base_in;
                cur_addr <= base_in;
                line     <= 32'd0;
                px       <= 32'd0;
            end else if (eol) begin
                px       <= 32'd0;
                line     <= line + 32'd1;
                cur_addr <= cur_addr + 32'd1;
            end else begin
                px       <= px + 32'd1;
                cur_addr <= cur_addr + 32'd1;
            end
        end
    end

    // after scanout has been started, the fetch address stays inside the frame
    always @(posedge clk)
        if (armed)
            assert (cur_addr - base <= 32'd1023);
endmodule

module csa_token_checksum (
    input  wire       clk,
    input  wire       i_ce,
    input  wire       i_close,
    input  wire [7:0] i_byte,
    output wire       o_csa_zero,
    output wire       o_ref_busy
);
    // carry-save accumulator of a token byte stream
    reg [7:0] sum_r   = 8'd0;
    reg [7:0] carry_r = 8'd0;
    // binary reference accumulator (shadow checksum)
    reg [7:0] acc     = 8'd0;
    // scope register: high until the first record-close event
    reg       armed   = 1'b1;

    // 3:2 reduction of (sum, carry<<1, incoming byte)
    wire [7:0] csa_a = sum_r;
    wire [7:0] csa_b = {carry_r[6:0], 1'b0};
    wire [7:0] csa_c = i_byte;
    wire [7:0] sum_n   = csa_a ^ csa_b ^ csa_c;
    wire [7:0] carry_n = (csa_a & csa_b) | (csa_a & csa_c) | (csa_b & csa_c);

    wire [7:0] csa_val = sum_r + {carry_r[6:0], 1'b0};

    assign o_csa_zero = (csa_val == 8'd0);
    assign o_ref_busy = (acc != 8'd0);

    always @(posedge clk) begin
        if (i_ce) begin
            sum_r   <= sum_n;
            carry_r <= carry_n;
            acc     <= acc + i_byte;
            if (i_close)
                armed <= 1'b0;
        end
    end

    // Absence, before first close: CSA-zero and reference-busy never together
    assert property (!armed || !(o_csa_zero && o_ref_busy));
endmodule

module atalanta_ca_retry (
    input wire clk,
    input wire rst,
    input wire en,
    input wire cmd_valid,
    input wire [63:0] cmd_addr,
    input wire alert_n,
    output reg [63:0] ca_out,
    output reg ca_par
);
    reg [63:0] hist [0:31];
    reg hist_par [0:31];
    reg [4:0] wr_ptr;
    reg [4:0] replay_ptr;
    reg replaying;
    reg [63:0] issue_cnt;
    reg [63:0] log_cnt;
    reg [63:0] err_status;
    reg no_alert_yet;

    integer i;
    initial begin
        for (i = 0; i < 32; i = i + 1) begin
            hist[i] = 64'd0;
            hist_par[i] = 1'b0;
        end
        wr_ptr = 5'd0;
        replay_ptr = 5'd0;
        replaying = 1'b0;
        issue_cnt = 64'd0;
        log_cnt = 64'd0;
        err_status = 64'd0;
        no_alert_yet = 1'b1;
        ca_out = 64'd0;
        ca_par = 1'b0;
    end

    wire alert = !alert_n;
    wire do_issue = cmd_valid && !replaying;
    wire [4:0] replay_next = replay_ptr + 5'd1;

    wire [63:0] err_next;
    assign err_next[0] = err_status[0] | (issue_cnt != log_cnt);
    assign err_next[1] = err_status[1] | alert;
    assign err_next[31:2] = err_status[31:2];
    assign err_next[63:32] = replaying ? (err_status[63:32] + 32'd1) : err_status[63:32];

    always @(posedge clk) begin
        if (rst) begin
            wr_ptr <= 5'd0;
            replay_ptr <= 5'd0;
            replaying <= 1'b0;
            issue_cnt <= 64'd0;
            log_cnt <= 64'd0;
            err_status <= 64'd0;
            no_alert_yet <= 1'b1;
            ca_out <= 64'd0;
            ca_par <= 1'b0;
        end else if (en) begin
            err_status <= err_next;
            if (do_issue) begin
                ca_out <= cmd_addr;
                ca_par <= ^cmd_addr;
                hist[wr_ptr] <= cmd_addr;
                hist_par[wr_ptr] <= ^cmd_addr;
                wr_ptr <= wr_ptr + 5'd1;
                issue_cnt <= issue_cnt + 64'd1;
                log_cnt <= log_cnt + 64'd1;
            end
            if (replaying) begin
                ca_out <= hist[replay_ptr];
                ca_par <= hist_par[replay_ptr];
                replay_ptr <= replay_next;
                if (replay_next == wr_ptr)
                    replaying <= 1'b0;
            end
            if (alert) begin
                replaying <= 1'b1;
                replay_ptr <= wr_ptr - 5'd1;
                no_alert_yet <= 1'b0;
            end
        end
    end

    always @(*) assert (!no_alert_yet || err_status == 64'd0);
endmodule

module gardner_ted_lxp (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [7:0] sample_in,
    output wire [15:0] o_err,
    output wire o_strobe
);
    reg phase;
    reg [7:0] prev_sym, mid, cur_sym;
    reg [7:0] sym_cnt;
    reg [7:0] half_cnt;
    reg [15:0] err_out;
    reg [15:0] err_mem [0:31];
    integer i;

    initial begin
        phase = 1'b0;
        prev_sym = 8'd0;
        mid = 8'd0;
        cur_sym = 8'd0;
        sym_cnt = 8'd0;
        half_cnt = 8'd0;
        err_out = 16'd0;
        for (i = 0; i < 32; i = i + 1) err_mem[i] = 16'd0;
    end

    wire signed [8:0] diff = $signed({sample_in[7], sample_in}) - $signed({cur_sym[7], cur_sym});
    wire signed [16:0] prod = diff * $signed({mid[7], mid});
    wire [15:0] err = prod[15:0];

    always @(posedge clk) begin
        if (rst) begin
            phase <= 1'b0;
            prev_sym <= 8'd0;
            mid <= 8'd0;
            cur_sym <= 8'd0;
            sym_cnt <= 8'd0;
            half_cnt <= 8'd0;
            err_out <= 16'd0;
            for (i = 0; i < 32; i = i + 1) err_mem[i] <= 16'd0;
        end else if (en) begin
            phase <= ~phase;
            if (!phase) begin
                mid <= sample_in;
            end else begin
                prev_sym <= cur_sym;
                cur_sym <= sample_in;
                err_out <= err;
                err_mem[sym_cnt[4:0]] <= err;
            end
            if (half_cnt == 8'd63) begin
                half_cnt <= 8'd0;
                sym_cnt <= 8'd0;
            end else begin
                half_cnt <= half_cnt + 8'd1;
                if (phase)
                    sym_cnt <= sym_cnt + 8'd1;
            end
        end
    end

    assign o_err = err_out;
    assign o_strobe = phase;

    always @(*) assert (sym_cnt <= 8'd31);
endmodule

module pico_wakeup (
    input wire        clk,
    input wire        rst_n,
    input wire        en,
    input wire        alloc,
    input wire [31:0] alloc_deps,
    input wire        issue,
    input wire [4:0]  issue_idx
);
    reg [31:0]   valid    = 32'd0;
    reg [1023:0] dep_flat = 1024'd0;
    reg [31:0]   pend     = 32'd0;
    reg [63:0]   occ      = 64'd0;
    reg [63:0]   wake_cnt = 64'd0;

    initial valid    = 32'd0;
    initial dep_flat = 1024'd0;
    initial pend     = 32'd0;
    initial occ      = 64'd0;
    initial wake_cnt = 64'd0;

    wire full = &valid;

    // lowest free index
    reg [4:0] free_idx;
    integer a;
    always @(*) begin
        free_idx = 5'd0;
        for (a = 31; a >= 0; a = a - 1)
            if (!valid[a]) free_idx = a[4:0];
    end

    // popcount of valid (status helper)
    reg [63:0] valid_cnt;
    integer b;
    always @(*) begin
        valid_cnt = 64'd0;
        for (b = 0; b < 32; b = b + 1)
            valid_cnt = valid_cnt + {63'd0, valid[b]};
    end

    // per-row OR of dependency matrix (status helper)
    reg [31:0] dep_or;
    integer c;
    always @(*) begin
        for (c = 0; c < 32; c = c + 1)
            dep_or[c] = |dep_flat[c*32 +: 32];
    end

    wire alloc_fire = alloc && !full;
    wire issue_fire = issue && valid[issue_idx] && !pend[issue_idx];
    wire [31:0] clr_mask   = issue_fire ? (32'd1 << issue_idx) : 32'd0;
    wire [31:0] alloc_mask = alloc_fire ? (32'd1 << free_idx)  : 32'd0;
    wire [31:0] new_deps   = alloc_deps & valid & ~clr_mask;

    reg [1023:0] dep_nxt;
    reg [31:0]   pend_nxt;
    reg [63:0]   woke;
    integer k;
    always @(*) begin
        woke = 64'd0;
        dep_nxt = dep_flat;
        pend_nxt = pend;
        for (k = 0; k < 32; k = k + 1) begin
            if (alloc_mask[k]) begin
                dep_nxt[k*32 +: 32] = new_deps;
                pend_nxt[k] = |new_deps;
            end else if (clr_mask[k]) begin
                dep_nxt[k*32 +: 32] = 32'd0;
                pend_nxt[k] = 1'b0;
            end else begin
                dep_nxt[k*32 +: 32] = dep_flat[k*32 +: 32] & ~clr_mask;
                pend_nxt[k] = pend[k] && (|(dep_flat[k*32 +: 32] & ~clr_mask));
                if (pend[k] && !pend_nxt[k])
                    woke = woke + 64'd1;
            end
        end
    end

    wire [31:0] valid_nxt = (valid | alloc_mask) & ~clr_mask;

    always @(posedge clk) begin
        if (!rst_n) begin
            valid    <= 32'd0;
            dep_flat <= 1024'd0;
            pend     <= 32'd0;
            occ      <= 64'd0;
            wake_cnt <= 64'd0;
        end else if (en) begin
            valid    <= valid_nxt;
            dep_flat <= dep_nxt;
            pend     <= pend_nxt;
            wake_cnt <= wake_cnt + woke;
            if (alloc_fire && !issue_fire)
                occ <= occ + 64'd1;
            else if (issue_fire && !alloc_fire)
                occ <= occ - 64'd1;
        end
    end

    always @(posedge clk)
        if (|valid) assert (occ <= 64'd32);
endmodule

module perfect_id_rom (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    output wire [31:0] rdata,
    output wire        last
);
    localparam [31:0] ROM_VENDOR    = 32'h49424D00;
    localparam [31:0] ROM_PART      = 32'h50455246;
    localparam [31:0] ROM_REVISION  = 32'h00000003;
    localparam [31:0] ROM_FEAT0     = 32'h0000C3A5;
    localparam [31:0] ROM_FEAT1     = 32'h00000011;
    localparam [31:0] ROM_SIGNATURE = 32'h43484933;
    localparam [31:0] LAST_IDX      = 32'd5;

    reg [31:0] ptr;
    reg [31:0] remaining;
    reg [31:0] rdata_q;
    initial begin
        ptr       = 32'd0;
        remaining = LAST_IDX;
        rdata_q   = 32'd0;
    end

    reg [31:0] rom_word;
    always @(*) begin
        case (ptr)
            32'd0:   rom_word = ROM_VENDOR;
            32'd1:   rom_word = ROM_PART;
            32'd2:   rom_word = ROM_REVISION;
            32'd3:   rom_word = ROM_FEAT0;
            32'd4:   rom_word = ROM_FEAT1;
            32'd5:   rom_word = ROM_SIGNATURE;
            default: rom_word = 32'd0;
        endcase
    end

    always @(posedge clk) begin
        if (rst) begin
            ptr       <= 32'd0;
            remaining <= LAST_IDX;
            rdata_q   <= 32'd0;
        end else if (en) begin
            rdata_q   <= rom_word;
            ptr       <= (remaining == 32'd0) ? 32'd0 : ptr + 32'd1;
            remaining <= (ptr == LAST_IDX) ? LAST_IDX : remaining - 32'd1;
        end
    end

    assign rdata = rdata_q;
    assign last  = (remaining == 32'd0);

    assert property (ptr <= 32'd5);
    assert property (remaining <= 32'd5);
endmodule

module hdmi_line_window (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        line_start,
    input  wire        line_stop,
    input  wire [31:0] sample_in,
    output reg  [31:0] y
);
    reg [31:0] win_rom [0:255];
    reg [31:0] idx;
    reg [31:0] dn;
    reg        win;

    integer i;
    initial begin
        for (i = 0; i < 256; i = i + 1) begin
            if (i < 128)
                win_rom[i] = i * i * 4;
            else
                win_rom[i] = (255 - i) * (255 - i) * 4;
        end
    end

    initial begin
        idx = 32'd0;
        dn  = 32'd255;
        win = 1'b0;
        y   = 32'd0;
    end

    wire [32:0] coef_sum = {1'b0, win_rom[idx[7:0]]} + {1'b0, win_rom[dn[7:0]]};
    wire [31:0] coef     = coef_sum[32:1];
    wire [63:0] prod     = sample_in * coef;

    always @(posedge clk) begin
        if (rst) begin
            idx <= 32'd0;
            dn  <= 32'd255;
            win <= 1'b0;
            y   <= 32'd0;
        end else if (en) begin
            if (dn == 32'd0) begin
                idx <= 32'd0;
                dn  <= 32'd255;
            end else begin
                idx <= idx + 32'd1;
                dn  <= dn - 32'd1;
            end
            win <= line_start ? 1'b1 : (line_stop ? 1'b0 : win);
            y   <= prod[31:0];
        end
    end

    assert property (!win || idx <= 32'd255);
endmodule

module qspi_xip_ctrl (
    input  wire        clk,
    input  wire        ce,
    input  wire        req,
    input  wire [23:0] addr,
    input  wire        cfg_we,
    input  wire [7:0]  cfg_wdata,
    input  wire [3:0]  io_in,
    output wire [3:0]  io_out,
    output wire        cs_n,
    output reg         busy,
    output reg         pf_valid,
    output reg  [31:0] pf_data
);
    reg        cs_active  = 1'b0;
    reg [31:0] cnt        = 32'd0;
    reg [31:0] nib        = 32'd0;
    reg [31:0] sh_out     = 32'd0;
    reg [7:0]  cfg_opcode = 8'hEB;
    reg        armed      = 1'b0;

    initial busy     = 1'b0;
    initial pf_valid = 1'b0;
    initial pf_data  = 32'd0;

    assign cs_n   = !cs_active;
    assign io_out = sh_out[31:28];

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (cfg_we)
                    cfg_opcode <= cfg_wdata;
                if (req) begin
                    armed     <= 1'b1;
                    busy      <= 1'b1;
                    cs_active <= 1'b1;
                    cnt       <= 32'd20;
                    nib       <= 32'd0;
                    pf_valid  <= 1'b0;
                    sh_out    <= {cfg_opcode, addr};
                end
            end else begin
                cnt    <= cnt - 32'd1;
                sh_out <= {sh_out[27:0], 4'h0};
                if (cnt <= 32'd8) begin
                    pf_data <= {pf_data[27:0], io_in};
                    if (nib == 32'd7) begin
                        pf_valid  <= 1'b1;
                        cs_active <= 1'b0;
                        nib       <= 32'd0;
                    end else begin
                        nib <= nib + 32'd1;
                    end
                end
                if (cnt == 32'd1)
                    busy <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (armed) assert (!(busy && pf_valid));

    always @(posedge clk)
        if (armed) assert (!(cs_active && !busy));
endmodule

module palette_lut (
    input wire clk,
    input wire rst,
    input wire wr_en,
    input wire [1:0] wr_idx,
    input wire [31:0] wr_data,
    input wire pix_valid,
    input wire [1:0] pix_idx,
    input wire lock_cmd,
    input wire unlock_cmd,
    output reg [31:0] color_q,
    output reg [1:0] idx_q,
    output reg locked,
    output reg [31:0] lookups
);
    reg [31:0] pal0, pal1, pal2, pal3;
    initial begin
        pal0 = 32'd0; pal1 = 32'd0; pal2 = 32'd0; pal3 = 32'd0;
        color_q = 32'd0; idx_q = 2'd0; locked = 1'b0; lookups = 32'd0;
    end

    wire do_wr = wr_en && !locked;
    wire [31:0] pal_rd = (pix_idx == 2'd0) ? pal0 : (pix_idx == 2'd1) ? pal1 : (pix_idx == 2'd2) ? pal2 : pal3;
    wire [31:0] new_rd = (do_wr && (wr_idx == pix_idx)) ? wr_data : pal_rd;
    wire [31:0] cur_entry = (idx_q == 2'd0) ? pal0 : (idx_q == 2'd1) ? pal1 : (idx_q == 2'd2) ? pal2 : pal3;

    always @(posedge clk) begin
        if (rst) begin
            pal0 <= 32'd0; pal1 <= 32'd0; pal2 <= 32'd0; pal3 <= 32'd0;
            color_q <= 32'd0; idx_q <= 2'd0; locked <= 1'b0; lookups <= 32'd0;
        end else begin
            if (do_wr) begin
                case (wr_idx)
                    2'd0: pal0 <= wr_data;
                    2'd1: pal1 <= wr_data;
                    2'd2: pal2 <= wr_data;
                    default: pal3 <= wr_data;
                endcase
            end
            if (pix_valid) begin
                idx_q <= pix_idx;
                color_q <= new_rd;
                lookups <= lookups + 32'd1;
            end else if (do_wr && (wr_idx == idx_q)) begin
                color_q <= wr_data;
            end
            if (lock_cmd) locked <= 1'b1;
            else if (unlock_cmd) locked <= 1'b0;
        end
    end

    always @(posedge clk)
        if (locked)
            assert (color_q == cur_entry);
endmodule

module act_gate_counter (
    input wire clk,
    input wire ce,
    input wire gate,
    input wire evt,
    output reg [7:0] result
);
    reg       gate_q = 1'b0;
    reg       evt_q  = 1'b0;
    reg [7:0] cnt    = 8'd0;
    reg       win    = 1'b0;
    reg       seen   = 1'b0;
    initial result = 8'd0;

    wire edge_det = evt && !evt_q;

    always @(posedge clk) begin
        if (ce) begin
            gate_q <= gate;
            evt_q  <= evt;
            if (gate && !gate_q) begin
                win  <= 1'b1;
                seen <= 1'b0;
            end else if (gate && gate_q) begin
                if (edge_det) begin
                    seen <= 1'b1;
                    if (cnt != 8'hFF)
                        cnt <= cnt + 8'd1;
                end
            end else if (!gate && gate_q) begin
                result <= cnt;
                cnt    <= 8'd0;
                win    <= 1'b0;
            end
        end
    end

    assert property (!win || seen || cnt == 8'd0);
endmodule

module wormhole_route_unit #(
    parameter [63:0] MY_X = 64'd4,
    parameter [63:0] MY_Y = 64'd2
) (
    input  wire        clk,
    input  wire        in_valid,
    input  wire [1:0]  flit_type,
    input  wire [3:0]  in_ch,
    input  wire [63:0] dest_x,
    input  wire [63:0] dest_y,
    output reg  [2:0]  out_port,
    output wire        out_fire
);
    localparam [1:0] FT_BODY = 2'b00;
    localparam [1:0] FT_HEAD = 2'b01;
    localparam [1:0] FT_TAIL = 2'b10;

    localparam [2:0] P_LOCAL = 3'd0;
    localparam [2:0] P_EAST  = 3'd1;
    localparam [2:0] P_WEST  = 3'd2;
    localparam [2:0] P_NORTH = 3'd3;
    localparam [2:0] P_SOUTH = 3'd4;

    reg [15:0] route_valid;
    reg [47:0] route_port;
    reg [63:0] head_cnt;
    reg [63:0] body_cnt;
    reg        head_seen;
    reg        armed;

    initial begin
        route_valid = 16'd0;
        route_port  = 48'd0;
        head_cnt    = 64'd0;
        body_cnt    = 64'd0;
        head_seen   = 1'b0;
        armed       = 1'b1;
        out_port    = 3'd0;
    end

    wire ch_busy = route_valid[in_ch];
    wire do_head = in_valid && (flit_type == FT_HEAD) && !ch_busy;
    wire do_body = in_valid && (flit_type == FT_BODY) && ch_busy;
    wire do_tail = in_valid && (flit_type == FT_TAIL) && ch_busy;

    assign out_fire = do_head || do_body || do_tail;

    reg [2:0] calc_port;
    always @(*) begin
        if (dest_x > MY_X)      calc_port = P_EAST;
        else if (dest_x < MY_X) calc_port = P_WEST;
        else if (dest_y > MY_Y) calc_port = P_NORTH;
        else if (dest_y < MY_Y) calc_port = P_SOUTH;
        else                    calc_port = P_LOCAL;
    end

    wire [2:0] stored_port = route_port[in_ch*3 +: 3];

    always @(posedge clk) begin
        if (do_head) begin
            route_valid[in_ch]         <= 1'b1;
            route_port[in_ch*3 +: 3]   <= calc_port;
            head_cnt                   <= head_cnt + 64'd1;
            head_seen                  <= 1'b1;
            out_port                   <= calc_port;
        end
        if (do_body) begin
            body_cnt <= body_cnt + 64'd1;
            out_port <= stored_port;
        end
        if (do_tail) begin
            route_valid[in_ch] <= 1'b0;
            armed              <= 1'b0;
            out_port           <= stored_port;
        end
    end

    always @(*) assert (!armed || (body_cnt == 64'd0) || head_seen);
endmodule

module lza_normalizer (
    input  wire        clk,
    input  wire        rst,
    input  wire        i_ce,
    input  wire        i_ld,
    input  wire [31:0] i_a,
    input  wire [31:0] i_b,
    output reg  [31:0] o_sum,
    output wire        o_done
);
    function [31:0] clz32;
        input [31:0] v;
        integer i;
        reg found;
        begin
            clz32 = 32'd32;
            found = 1'b0;
            for (i = 31; i >= 0; i = i - 1) begin
                if (!found && v[i]) begin
                    clz32 = 31 - i;
                    found = 1'b1;
                end
            end
        end
    endfunction

    reg [31:0] ind = 32'd0;
    reg [31:0] rem = 32'd32;
    initial o_sum = 32'd0;

    wire [31:0] t_str = i_a ^ i_b;
    wire [31:0] g_str = i_a & i_b;
    wire [31:0] f_new = t_str | g_str;

    wire [31:0] lz_of_ind = clz32(ind);
    wire busy = (rem != 32'd0) && (rem != 32'd32);

    assign o_done = (rem == 32'd0);

    always @(posedge clk) begin
        if (rst) begin
            ind   <= 32'd0;
            rem   <= 32'd32;
            o_sum <= 32'd0;
        end else if (i_ce) begin
            if (i_ld) begin
                ind   <= f_new;
                rem   <= clz32(f_new);
                o_sum <= i_a + i_b;
            end else if (busy) begin
                ind   <= ind << 1;
                rem   <= rem - 32'd1;
                o_sum <= o_sum << 1;
            end
        end
    end

    always @(posedge clk)
        if (o_done) assert (ind[31]);
endmodule

module misr_lockstep (
    input  wire        clk,
    input  wire        rst,
    input  wire        ce,
    input  wire        start,
    input  wire        stop,
    input  wire [63:0] din,
    output wire [63:0] signature,
    output wire        armed_o
);
    localparam [63:0] POLY = 64'h000000000000001B;
    localparam [63:0] SEED = 64'h0123456789ABCDEF;

    // Lane A holds the signature in true form, lane B in complemented form
    reg [63:0] sig_a;
    reg [63:0] sig_b;
    reg        armed;

    initial sig_a = SEED;
    initial sig_b = ~SEED;
    initial armed = 1'b0;

    function [63:0] misr_step;
        input [63:0] s;
        input [63:0] d;
        begin
            misr_step = {s[62:0], 1'b0} ^ (s[63] ? POLY : 64'd0) ^ d;
        end
    endfunction

    always @(posedge clk) begin
        if (rst) begin
            sig_a <= SEED;
            sig_b <= ~SEED;
            armed <= 1'b0;
        end else if (start) begin
            sig_a <= SEED;
            sig_b <= ~SEED;
            armed <= 1'b1;
        end else begin
            if (stop)
                armed <= 1'b0;
            if (ce) begin
                sig_a <= misr_step(sig_a, din);
                sig_b <= ~misr_step(~sig_b, din);
            end
        end
    end

    assign signature = sig_a;
    assign armed_o   = armed;

    // After a capture starts, until it is stopped, the lockstep lanes agree on the low byte
    always @(*) assert (!armed || (sig_a[7:0] == ~sig_b[7:0]));
endmodule

module hbpf_breathe (
    input  wire clk,
    input  wire en,
    output wire led
);
    localparam [63:0] STEP      = 64'h0000000100000000;
    localparam [63:0] NSTEPS    = 64'h0000000080000000;
    localparam [63:0] MAX       = 64'h8000000000000000;
    localparam [63:0] PRESC_MAX = 64'd999;

    reg [63:0] pwm_cnt  = 64'd0;
    reg [63:0] presc    = 64'd0;
    reg [63:0] pos      = 64'd0;
    reg [63:0] duty     = 64'd0;
    reg [63:0] headroom = 64'h8000000000000000;
    reg        dir        = 1'b1;
    reg        first_rise = 1'b1;

    assign led = (pwm_cnt < duty);

    wire tick = en && (presc == PRESC_MAX);

    always @(posedge clk) begin
        if (en) begin
            pwm_cnt <= pwm_cnt + 64'd1;
            if (presc == PRESC_MAX)
                presc <= 64'd0;
            else
                presc <= presc + 64'd1;
        end
        if (tick) begin
            if (dir) begin
                if (pos < NSTEPS) begin
                    pos      <= pos + 64'd1;
                    duty     <= duty + STEP;
                    headroom <= headroom - STEP;
                end else begin
                    dir        <= 1'b0;
                    first_rise <= 1'b0;
                end
            end else begin
                if (pos > 64'd0) begin
                    pos      <= pos - 64'd1;
                    duty     <= duty - STEP;
                    headroom <= headroom + STEP;
                end else begin
                    dir <= 1'b1;
                end
            end
        end
    end

    always @(posedge clk)
        if (first_rise)
            assert (duty <= MAX);

    always @(posedge clk)
        if (first_rise)
            assert (headroom <= MAX);
endmodule

module sv2v_hdr_parser (
    input wire clk,
    input wire rst,
    input wire en,
    input wire sop,
    input wire eop,
    input wire [15:0] din,
    output reg [15:0] kind,
    output reg [15:0] len,
    output reg [15:0] csum
);
    reg [15:0] off;
    reg [15:0] hdr_mem [0:31];
    reg hdr_done;
    reg win;
    integer i;

    initial begin
        off = 16'd0;
        kind = 16'd0;
        len = 16'd0;
        csum = 16'd0;
        hdr_done = 1'b0;
        win = 1'b0;
        for (i = 0; i < 32; i = i + 1) hdr_mem[i] = 16'd0;
    end

    always @(posedge clk) begin
        if (rst) begin
            off <= 16'd0;
            kind <= 16'd0;
            len <= 16'd0;
            csum <= 16'd0;
            hdr_done <= 1'b0;
            win <= 1'b0;
            for (i = 0; i < 32; i = i + 1) hdr_mem[i] <= 16'd0;
        end else if (en) begin
            if (sop) begin
                off <= 16'd1;
                kind <= din;
                hdr_mem[0] <= din;
                hdr_done <= 1'b0;
                win <= 1'b1;
            end else if (win) begin
                if (off < 16'd32) hdr_mem[off[4:0]] <= din;
                if (off == 16'd1) len <= din;
                if (off == 16'd2) begin
                    csum <= din;
                    hdr_done <= 1'b1;
                end
                if (off != 16'hFFFF) off <= off + 16'd1;
                if (eop) win <= 1'b0;
            end
        end
    end

    assert property (!(win && (off > 16'd3)) || hdr_done);
endmodule

module hfrisc_ctx_save_mux (
    input  wire          clk,
    input  wire          rst,
    input  wire          en,
    input  wire [1023:0] rf_flat,
    output reg  [31:0]   dout
);
    reg [31:0] sel;
    reg [4:0]  idx;
    initial begin
        sel = 32'h00000001;
        idx = 5'd0;
    end

    wire [4:0] idx_n = idx + 5'd1;

    always @(posedge clk) begin
        if (rst) begin
            sel <= 32'h00000001;
            idx <= 5'd0;
        end else if (en) begin
            sel <= sel ^ (32'h00000001 << idx) ^ (32'h00000001 << idx_n);
            idx <= idx_n;
        end
    end

    integer i;
    always @(*) begin
        dout = 32'h00000000;
        for (i = 0; i < 32; i = i + 1)
            dout = dout | (rf_flat[i*32 +: 32] & {32{sel[i]}});
    end

    always @(*) assert ((sel != 32'h00000000) && ((sel & (sel - 32'h00000001)) == 32'h00000000));
endmodule

module neo_ringstop (
    input  wire        clk,
    input  wire        rst,
    input  wire        en,
    input  wire        ring_in_vld,
    input  wire [63:0] ring_in_data,
    input  wire [3:0]  ring_in_dst,
    input  wire        push,
    input  wire [63:0] push_data,
    input  wire [3:0]  my_id,
    output wire        ring_hold,
    output wire        eject_vld,
    output wire [63:0] eject_data,
    output wire        out_vld,
    output wire [63:0] out_data,
    output wire [3:0]  out_dst
);
    reg        slot_vld = 1'b0;
    reg [63:0] slot_data = 64'd0;
    reg [3:0]  slot_dst = 4'd0;
    reg [63:0] fifo [0:15];
    reg [4:0]  q_head = 5'd0;
    reg [4:0]  q_tail = 5'd0;
    reg [4:0]  q_count = 5'd0;
    reg [63:0] starve_cnt = 64'd0;
    reg        rsv = 1'b0;
    reg [63:0] inj_total = 64'd0;
    reg        pre_rsv = 1'b1;
    reg        pv = 1'b0;

    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) fifo[i] = 64'd0;
    end

    wire through   = ring_in_vld && (ring_in_dst != my_id);
    wire nonempty  = (q_head != q_tail);
    wire free_slot = (!through) || rsv;
    wire pop       = nonempty && free_slot;
    wire push_ok   = push && (q_count < 5'd16);
    wire dec       = pop && (q_count != 5'd0);

    assign ring_hold  = rsv && through;
    assign eject_vld  = ring_in_vld && (ring_in_dst == my_id);
    assign eject_data = ring_in_data;
    assign out_vld    = slot_vld;
    assign out_data   = slot_data;
    assign out_dst    = slot_dst;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            slot_vld   <= 1'b0;
            slot_data  <= 64'd0;
            slot_dst   <= 4'd0;
            q_head     <= 5'd0;
            q_tail     <= 5'd0;
            q_count    <= 5'd0;
            starve_cnt <= 64'd0;
            rsv        <= 1'b0;
            inj_total  <= 64'd0;
            pre_rsv    <= 1'b1;
        end else if (en) begin
            if (pop) begin
                slot_vld  <= 1'b1;
                slot_data <= fifo[q_head[3:0]];
                slot_dst  <= fifo[q_head[3:0]][3:0];
                q_head    <= q_head + 5'd1;
                inj_total <= inj_total + 64'd1;
            end else if (through) begin
                slot_vld  <= 1'b1;
                slot_data <= ring_in_data;
                slot_dst  <= ring_in_dst;
            end else begin
                slot_vld  <= 1'b0;
            end

            if (push_ok) begin
                fifo[q_tail[3:0]] <= push_data;
                q_tail <= q_tail + 5'd1;
            end

            q_count <= q_count + {4'd0, push_ok} - {4'd0, dec};

            if (pop)
                starve_cnt <= 64'd0;
            else if (nonempty)
                starve_cnt <= starve_cnt + 64'd1;

            if (pop)
                rsv <= 1'b0;
            else if (starve_cnt == 64'd1000) begin
                rsv     <= 1'b1;
                pre_rsv <= 1'b0;
            end
        end
    end

    always @(posedge clk)
        if (pv && !$past(rst) && pre_rsv && $stable(q_tail) && $stable(q_count))
            assert ($stable(q_head));
endmodule

module therm_dac_seg (
    input wire clk,
    input wire i_ce,
    input wire i_mute,
    input wire i_load,
    input wire [3:0] i_val,
    input wire i_up,
    input wire i_down,
    output wire [15:0] o_seg
);
    reg [3:0]  val;
    reg [15:0] therm;
    reg        pre_mute;
    initial val = 4'd0;
    initial therm = 16'h0001;
    initial pre_mute = 1'b1;

    // binary-to-thermometer decoder: lines 0..i_val asserted
    wire [15:0] dec_in = (16'd2 << i_val) - 16'd1;

    always @(posedge clk) begin
        if (i_ce) begin
            if (!pre_mute) begin
                // muted: segments frozen off
            end else if (i_mute) begin
                pre_mute <= 1'b0;
                val      <= 4'd0;
                therm    <= 16'd0;
            end else if (i_load) begin
                val   <= i_val;
                therm <= dec_in;
            end else if (i_up && !i_down) begin
                if (val != 4'd15) begin
                    val   <= val + 4'd1;
                    therm <= {therm[14:0], 1'b1};
                end
            end else if (i_down && !i_up) begin
                if (val != 4'd0) begin
                    val   <= val - 4'd1;
                    therm <= {1'b0, therm[15:1]};
                end
            end
        end
    end

    // registered thermometer output driving unary DAC segments
    assign o_seg = therm;

    // before mute: output is always a valid, non-empty thermometer code
    always @(*)
        assert (!pre_mute || (therm[0] && ((therm & (therm + 16'd1)) == 16'd0)));
endmodule

module uart_nco (
    input wire i_clk,
    input wire i_rst,
    input wire i_en,
    input wire [7:0] i_fword,
    input wire i_start,
    input wire i_stop,
    output wire [7:0] o_sin,
    output wire [7:0] o_ticks,
    output wire o_win
);
    localparam [63:0] SIN_TAB = {8'd37, 8'd1, 8'd37, 8'd128, 8'd218, 8'd255, 8'd218, 8'd128};

    reg [7:0] phase = 8'd0;
    reg [7:0] tick_cnt = 8'd0;
    reg [2:0] last_idx = 3'd0;
    reg [7:0] sin_q = 8'd128;
    reg       win = 1'b0;

    wire [8:0] sum = {1'b0, phase} + {1'b0, i_fword};
    wire [7:0] nphase = sum[7:0];
    wire       carry = sum[8];
    wire [2:0] nidx = nphase[7:5];
    wire [5:0] nbase = {nidx, 3'b000};
    wire [7:0] n_sin = SIN_TAB[nbase +: 8];
    wire [5:0] lbase = {last_idx, 3'b000};
    wire [7:0] sin_of_last = SIN_TAB[lbase +: 8];

    always @(posedge i_clk) begin
        if (i_rst) begin
            phase <= 8'd0;
            tick_cnt <= 8'd0;
            last_idx <= 3'd0;
            sin_q <= 8'd128;
            win <= 1'b0;
        end else if (i_en) begin
            phase <= nphase;
            if (carry)
                tick_cnt <= tick_cnt + 8'd1;
            last_idx <= nidx;
            sin_q <= n_sin;
            if (i_start)
                win <= 1'b1;
            else if (i_stop)
                win <= 1'b0;
        end
    end

    assign o_sin = sin_q;
    assign o_ticks = tick_cnt;
    assign o_win = win;

    reg pv = 1'b0;
    always @(posedge i_clk) pv <= 1'b1;

    always @(posedge i_clk)
        if (pv && !$past(i_rst) && win && $stable(phase))
            assert ($stable(sin_q));
endmodule

module rdf_lockstep_wl (
    input wire clk,
    input wire rst,
    input wire en,
    input wire [63:0] wl_in,
    input wire close_in,
    input wire eco_in
);
    reg [63:0] acc_a = 64'd0;
    reg [63:0] acc_b = 64'd0;
    reg [63:0] step_cnt = 64'd0;
    reg mism_q = 1'b0;
    reg err_q = 1'b0;
    reg ok_q = 1'b0;
    reg pre_eco = 1'b1;

    wire [63:0] nxt_a = acc_a + wl_in;
    wire [63:0] nxt_b = acc_b + wl_in;

    always @(posedge clk) begin
        if (rst) begin
            acc_a <= 64'd0;
            acc_b <= 64'd0;
            step_cnt <= 64'd0;
            mism_q <= 1'b0;
            err_q <= 1'b0;
            ok_q <= 1'b0;
            pre_eco <= 1'b1;
        end else if (en) begin
            acc_a <= nxt_a;
            acc_b <= nxt_b;
            step_cnt <= step_cnt + 64'd1;
            mism_q <= (nxt_a != nxt_b);
            err_q <= err_q | mism_q;
            ok_q <= ok_q | close_in;
            pre_eco <= pre_eco & ~eco_in;
        end
    end

    always @(posedge clk) assert (!pre_eco || !(mism_q && ok_q));
endmodule

module fll_cmp #(
    parameter [31:0] WINDOW      = 32'd32,
    parameter [31:0] TARGET_INIT = 32'd20
) (
    input  wire        clk,
    input  wire        i_reset,
    input  wire        i_ce,
    input  wire        i_osc_tick,
    input  wire        i_set_target,
    input  wire [31:0] i_target,
    output wire [31:0] o_code,
    output wire        o_searching
);
    reg [31:0] cyc_cnt  = 32'd0;
    reg [31:0] win_tmr  = 32'd0;
    reg [31:0] target   = TARGET_INIT;
    reg [31:0] osc_code = 32'h80000000;
    reg        searching = 1'b1;

    wire        win_end   = (win_tmr == WINDOW - 32'd1);
    wire [31:0] final_cnt = cyc_cnt + {31'd0, i_osc_tick};

    always @(posedge clk) begin
        if (i_reset) begin
            cyc_cnt  <= 32'd0;
            win_tmr  <= 32'd0;
            target   <= TARGET_INIT;
            osc_code <= 32'h80000000;
        end else if (i_ce) begin
            if (i_set_target)
                target <= i_target;
            if (win_end) begin
                cyc_cnt <= 32'd0;
                win_tmr <= 32'd0;
                if (final_cnt < target) begin
                    if (osc_code != 32'hFFFFFFFF)
                        osc_code <= osc_code + 32'd1;
                end else if (final_cnt > target) begin
                    if (osc_code != 32'd0)
                        osc_code <= osc_code - 32'd1;
                end else begin
                    searching <= 1'b0;
                end
            end else begin
                win_tmr <= win_tmr + 32'd1;
                cyc_cnt <= final_cnt;
            end
        end
    end

    assign o_code      = osc_code;
    assign o_searching = searching;

    assert property (!searching || (cyc_cnt < WINDOW));
endmodule

module uart_break_detect #(
    parameter [31:0] FRAME = 32'd10
) (
    input  wire clk,
    input  wire rst,
    input  wire s_valid,
    input  wire s_line,
    output wire s_ready,
    output reg  m_valid,
    input  wire m_ready,
    output reg  brk_sticky
);
    reg [31:0] low_cnt = 32'd0;
    reg        in_brk  = 1'b0;
    reg        win     = 1'b0;
    initial m_valid    = 1'b0;
    initial brk_sticky = 1'b0;

    assign s_ready = !m_valid;
    wire acc = s_valid && s_ready;

    always @(posedge clk) begin
        if (rst) begin
            low_cnt    <= 32'd0;
            in_brk     <= 1'b0;
            win        <= 1'b0;
            m_valid    <= 1'b0;
            brk_sticky <= 1'b0;
        end else begin
            if (m_valid && m_ready)
                m_valid <= 1'b0;
            if (acc) begin
                if (!s_line) begin
                    win <= 1'b1;
                    if (!in_brk) begin
                        if (low_cnt == FRAME - 32'd1) begin
                            low_cnt    <= FRAME;
                            in_brk     <= 1'b1;
                            brk_sticky <= 1'b1;
                            m_valid    <= 1'b1;
                        end else begin
                            low_cnt <= low_cnt + 32'd1;
                        end
                    end
                end else begin
                    low_cnt <= 32'd0;
                    in_brk  <= 1'b0;
                    win     <= 1'b0;
                end
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && win)
            assert (low_cnt <= FRAME && $past(low_cnt) <= FRAME);
endmodule

module dualrail_asr #(
    parameter WIDTH = 32,
    parameter [WIDTH-1:0] INIT = 32'h8000_0000
) (
    input  wire             clk,
    input  wire             rst,
    input  wire             en,
    input  wire             dir,
    input  wire             load,
    input  wire [WIDTH-1:0] din,
    output reg  [WIDTH-1:0] data,
    output reg  [WIDTH-1:0] nd,
    output reg              armed
);
    initial data  = INIT;
    initial nd    = ~INIT;
    initial armed = 1'b1;

    always @(posedge clk) begin
        if (rst) begin
            data  <= INIT;
            nd    <= ~INIT;
            armed <= 1'b1;
        end else if (en) begin
            if (load) begin
                data <= din;
                nd   <= ~din;
            end else if (dir) begin
                data  <= {data[WIDTH-2:0], 1'b0};
                nd    <= {nd[WIDTH-2:0], 1'b0};
                armed <= 1'b0;
            end else begin
                data <= {data[WIDTH-1], data[WIDTH-1:1]};
                nd   <= {nd[WIDTH-1], nd[WIDTH-1:1]};
            end
        end
    end

    always @(posedge clk)
        assert (!armed || (data[0] != nd[0]));
endmodule

module dds_tmr_minority #(
    parameter W = 8
) (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         i_ce,
    input  wire [W-1:0] i_tw,
    input  wire         i_sweep_start,
    input  wire         i_sweep_stop,
    output wire         o_sq,
    output wire         o_min
);
    // Triple-redundant phase accumulators of a DDS core
    reg [W-1:0] acc_a;
    reg [W-1:0] acc_b;
    reg [W-1:0] acc_c;
    reg         sweep_win;
    initial acc_a = {W{1'b0}};
    initial acc_b = {W{1'b0}};
    initial acc_c = {W{1'b0}};
    initial sweep_win = 1'b0;

    always @(posedge clk) begin
        if (i_reset) begin
            acc_a     <= {W{1'b0}};
            acc_b     <= {W{1'b0}};
            acc_c     <= {W{1'b0}};
            sweep_win <= 1'b0;
        end else if (i_ce) begin
            acc_a <= acc_a + i_tw;
            acc_b <= acc_b + i_tw;
            acc_c <= acc_c + i_tw;
            if (i_sweep_start)
                sweep_win <= 1'b1;
            else if (i_sweep_stop)
                sweep_win <= 1'b0;
        end
    end

    // Square-wave output taken from replica A's MSB
    assign o_sq = acc_a[W-1];

    // Minority gate over the three replica MSBs: complement of the majority
    wire ma = acc_a[W-1];
    wire mb = acc_b[W-1];
    wire mc = acc_c[W-1];
    assign o_min = ~((ma & mb) | (mb & mc) | (ma & mc));

    // Absence, after sweep start until sweep stop:
    // square output and minority output are never high together
    assert property (!sweep_win || !(o_sq && o_min));
endmodule

module uart_break_det #(
    parameter FRAME_BITS = 10,
    parameter BREAK_LEN  = FRAME_BITS + 1
) (
    input  wire        clk,
    input  wire        rst,
    input  wire        tick,
    input  wire        rx,
    input  wire        clr_status,
    output reg  [31:0] low_cnt,
    output reg         in_break,
    output reg         break_rcvd
);
    localparam [31:0] BRK = BREAK_LEN;

    initial low_cnt    = 32'd0;
    initial in_break   = 1'b0;
    initial break_rcvd = 1'b0;

    always @(posedge clk) begin
        if (rst) begin
            low_cnt    <= 32'd0;
            in_break   <= 1'b0;
            break_rcvd <= 1'b0;
        end else begin
            if (clr_status)
                break_rcvd <= 1'b0;
            if (tick) begin
                if (rx) begin
                    low_cnt  <= 32'd0;
                    in_break <= 1'b0;
                end else if (!in_break) begin
                    low_cnt <= low_cnt + 32'd1;
                    if (low_cnt == BRK - 32'd1) begin
                        in_break   <= 1'b1;
                        break_rcvd <= 1'b1;
                    end
                end
            end
        end
    end

    always @(posedge clk)
        assert (low_cnt <= BRK);
endmodule

module xdom_pulse_demux #(
    parameter N = 64,
    parameter SELW = 6
) (
    input  wire            clk,
    input  wire            rst,
    input  wire            in_valid,
    output wire            in_ready,
    input  wire [SELW-1:0] in_sel,
    input  wire            dst_ce,
    output wire [N-1:0]    out_pulse,
    output wire            busy_o
);
    localparam [63:0] LAT = 64'd3;

    reg [N-1:0] src_tog = {N{1'b0}};
    reg [N-1:0] s1 = {N{1'b0}};
    reg [N-1:0] s2 = {N{1'b0}};
    reg [N-1:0] s3 = {N{1'b0}};
    reg         busy = 1'b0;
    reg [63:0]  countdown = 64'd0;

    assign in_ready  = !busy;
    wire   accept    = in_valid && in_ready;
    assign out_pulse = s2 ^ s3;
    assign busy_o    = busy;

    always @(posedge clk) begin
        if (rst) begin
            src_tog   <= {N{1'b0}};
            s1        <= {N{1'b0}};
            s2        <= {N{1'b0}};
            s3        <= {N{1'b0}};
            busy      <= 1'b0;
            countdown <= 64'd0;
        end else begin
            if (accept)
                src_tog <= src_tog ^ ({{(N-1){1'b0}}, 1'b1} << in_sel);
            if (dst_ce) begin
                s1 <= src_tog;
                s2 <= s1;
                s3 <= s2;
            end
            if (accept) begin
                busy      <= 1'b1;
                countdown <= LAT;
            end else if (busy && dst_ce) begin
                if (|out_pulse) begin
                    busy      <= 1'b0;
                    countdown <= 64'd0;
                end else begin
                    countdown <= countdown - 64'd1;
                end
            end
        end
    end

    always @(posedge clk)
        if (busy) assert (countdown != 64'd0);
endmodule

module ps2_frame_rx #(
    parameter W = 128
) (
    input  wire         clk,
    input  wire         rst,
    input  wire         in_valid,
    input  wire         in_bit,
    output wire         in_ready,
    output reg          out_valid,
    input  wire         out_ready,
    output reg  [W-1:0] code
);
    localparam CW = $clog2(W);

    reg [W-1:0]  shreg;
    reg [CW-1:0] bitcnt;
    reg          armed;

    initial shreg     = {W{1'b0}};
    initial bitcnt    = {CW{1'b0}};
    initial code      = {W{1'b0}};
    initial out_valid = 1'b0;
    initial armed     = 1'b1;

    assign in_ready = !out_valid;

    wire take = in_valid && in_ready;

    always @(posedge clk) begin
        if (rst) begin
            shreg     <= {W{1'b0}};
            bitcnt    <= {CW{1'b0}};
            code      <= {W{1'b0}};
            out_valid <= 1'b0;
        end else begin
            if (out_valid && out_ready)
                out_valid <= 1'b0;
            if (take) begin
                if (bitcnt == W-1) begin
                    code      <= {in_bit, shreg[W-1:1]};
                    out_valid <= 1'b1;
                    shreg     <= {W{1'b0}};
                    bitcnt    <= {CW{1'b0}};
                end else begin
                    shreg  <= {in_bit, shreg[W-1:1]};
                    bitcnt <= bitcnt + 1'b1;
                end
            end
            if (take && in_bit)
                armed <= 1'b0;
        end
    end

    always @(posedge clk)
        if (armed) assert (code == {W{1'b0}});
endmodule

module spi_sclk_tff #(
    parameter W = 8
) (
    input  wire         clk,
    input  wire         rst_n,
    input  wire         step,
    input  wire         miso,
    output wire         spi_clk_o,
    output wire [W-1:0] o_edges,
    output wire [W-1:0] o_rx
);
    localparam [W-1:0] MAXC = {W{1'b1}};

    // T flip-flop generating the SPI serial clock (mode 0)
    reg         sclk      = 1'b0;
    // number of rising SPI clock edges (saturating)
    reg [W-1:0] edges     = {W{1'b0}};
    // shadow register: a falling SPI clock edge has happened earlier
    reg         fell_seen = 1'b0;
    // MISO capture shift register, sampled on rising edges
    reg [W-1:0] rx        = {W{1'b0}};

    wire t    = step;
    wire rise = t && !sclk;
    wire fall = t &&  sclk;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            sclk      <= 1'b0;
            edges     <= {W{1'b0}};
            fell_seen <= 1'b0;
            rx        <= {W{1'b0}};
        end else begin
            if (t)
                sclk <= ~sclk;
            if (rise && edges != MAXC)
                edges <= edges + 1'b1;
            if (rise)
                rx <= {rx[W-2:0], miso};
            if (fall)
                fell_seen <= 1'b1;
        end
    end

    assign spi_clk_o = sclk;
    assign o_edges   = edges;
    assign o_rx      = rx;

    // Precedence: a second rising SPI clock edge requires an earlier falling edge
    always @(*) assert ((edges <= 8'd1) || fell_seen);
endmodule

module oc_csum_acc #(
    parameter W = 32
) (
    input  wire         clk,
    input  wire         i_reset,
    input  wire         in_valid,
    output wire         in_ready,
    input  wire [W-1:0] in_data,
    input  wire         i_ce,
    output wire [W-1:0] o_csum
);
    reg [W-1:0] acc;
    reg [W-1:0] hold_data;
    reg         hold_valid;
    reg         seen_nz;
    reg         armed;
    initial acc = {W{1'b0}};
    initial hold_data = {W{1'b0}};
    initial hold_valid = 1'b0;
    initial seen_nz = 1'b0;
    initial armed = 1'b1;

    wire drain = i_ce && hold_valid;
    assign in_ready = !hold_valid || drain;
    wire accept = in_valid && in_ready;

    // end-around-carry (one's-complement) adder, purely combinational
    wire [W:0]   raw     = {1'b0, acc} + {1'b0, hold_data};
    wire         eac     = raw[W];
    wire [W-1:0] eac_sum = raw[W-1:0] + {{(W-1){1'b0}}, eac};

    always @(posedge clk) begin
        if (i_reset) begin
            acc        <= {W{1'b0}};
            hold_data  <= {W{1'b0}};
            hold_valid <= 1'b0;
            seen_nz    <= 1'b0;
            armed      <= 1'b1;
        end else begin
            if (drain) begin
                acc <= eac_sum;
                if (eac)
                    armed <= 1'b0;
            end
            if (accept) begin
                hold_data  <= in_data;
                hold_valid <= 1'b1;
                if (in_data != {W{1'b0}})
                    seen_nz <= 1'b1;
            end else if (drain) begin
                hold_valid <= 1'b0;
            end
        end
    end

    assign o_csum = ~acc;

    always @(*)
        assert (!armed || seen_nz || acc == {W{1'b0}});
endmodule

module first_ready_latch #(
    parameter NCH  = 4,
    parameter IDXW = 2,
    parameter CW   = 64
) (
    input  wire            clk,
    input  wire            rst,
    input  wire            ce,
    input  wire            arm,
    input  wire            clr,
    input  wire [NCH-1:0]  ch_rdy,
    output reg  [IDXW-1:0] winner,
    output reg             captured,
    output reg             armed,
    output reg  [CW-1:0]   cap_cnt
);
    initial begin
        winner   = {IDXW{1'b0}};
        captured = 1'b0;
        armed    = 1'b0;
        cap_cnt  = {CW{1'b0}};
    end

    reg [IDXW-1:0] first_idx;
    integer i;
    always @(*) begin
        first_idx = {IDXW{1'b0}};
        for (i = NCH-1; i >= 0; i = i - 1)
            if (ch_rdy[i]) first_idx = i[IDXW-1:0];
    end

    wire any_rdy = |ch_rdy;

    always @(posedge clk) begin
        if (rst) begin
            winner   <= {IDXW{1'b0}};
            captured <= 1'b0;
            armed    <= 1'b0;
            cap_cnt  <= {CW{1'b0}};
        end else if (ce) begin
            if (clr) begin
                armed    <= 1'b0;
                captured <= 1'b0;
                cap_cnt  <= {CW{1'b0}};
            end else if (arm) begin
                armed    <= 1'b1;
                captured <= 1'b0;
                cap_cnt  <= {CW{1'b0}};
            end else if (armed && !captured && any_rdy) begin
                captured <= 1'b1;
                winner   <= first_idx;
                cap_cnt  <= cap_cnt + {{(CW-1){1'b0}}, 1'b1};
            end
        end
    end

    always @(*) assert (!armed || cap_cnt <= 64'd1);
endmodule

module uart_tx_word #(
    parameter DATA_W = 32
) (
    input  wire              clk,
    input  wire              rst_n,
    input  wire              baud_tick,
    input  wire              s_valid,
    output wire              s_ready,
    input  wire [DATA_W-1:0] s_data,
    output wire              txd,
    output wire              o_busy
);
    localparam integer FRAME_W = DATA_W + 3;
    localparam [31:0] LAST = FRAME_W - 1;
    localparam [FRAME_W-1:0] ONE = 1;

    reg [FRAME_W-1:0] shreg = {FRAME_W{1'b0}};
    reg [31:0] bitcnt = 32'd0;
    reg busy = 1'b0;
    reg in_frame = 1'b0;

    assign s_ready = !busy;
    assign txd = busy ? shreg[0] : 1'b1;
    assign o_busy = busy;

    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            shreg <= {FRAME_W{1'b0}};
            bitcnt <= 32'd0;
            busy <= 1'b0;
            in_frame <= 1'b0;
        end else if (s_valid && s_ready) begin
            shreg <= {1'b1, ^s_data, s_data, 1'b0};
            bitcnt <= 32'd0;
            busy <= 1'b1;
            in_frame <= 1'b1;
        end else if (baud_tick && busy) begin
            bitcnt <= bitcnt + 32'd1;
            if (shreg == ONE) begin
                shreg <= {FRAME_W{1'b0}};
                busy <= 1'b0;
                in_frame <= 1'b0;
            end else begin
                shreg <= shreg >> 1;
            end
        end
    end

    reg pv = 1'b0;
    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk)
        if (pv && in_frame && $rose(txd))
            assert (bitcnt <= LAST);
endmodule

module horner_eval (
    input wire i_clk,
    input wire i_reset,
    input wire i_ce,
    input wire [15:0] coeff,
    input wire [15:0] x,
    output wire [15:0] result
);
    reg [15:0] acc1, acc2;
    reg [15:0] deg;
    initial acc1 = 0;
    initial acc2 = 0;
    initial deg = 0;

    always @(posedge i_clk)
        if (i_reset) begin
            acc1 <= 0;
            acc2 <= 0;
            deg <= 0;
        end else if (i_ce) begin
            acc1 <= acc1 * x + coeff;
            acc2 <= acc2 * x + coeff;
            if (deg > 0)
                deg <= deg - 1;
        end

    assign result = acc1;

    reg pv = 0;
    always @(posedge i_clk) pv <= 1;
    always @(posedge i_clk) if (pv && i_ce) assert (acc1 ^ acc2 == 0);
endmodule

module feistel_round_unit (
    input  wire       clk,
    input  wire       ce,
    input  wire       load,
    input  wire [7:0] pt,
    output reg  [7:0] lhalf,
    output reg  [7:0] rhalf,
    output reg  [7:0] rc
);
    reg [7:0] cd;
    reg [7:0] sk;
    reg       armed;
    reg       pv;

    initial begin
        lhalf = 8'h00; rhalf = 8'h00; rc = 8'd0;
        cd = 8'h01; sk = 8'h01; armed = 1'b0; pv = 1'b0;
    end

    // rotating C/D key halves, combined into one byte for simplicity
    wire [7:0] cd_next = {cd[6:0], cd[7]};
    wire [7:0] sk_next = {sk[6:0], sk[7]};

    // DES expansion of the right half: 32->48 bits, truncated to 8 here
    wire [7:0] exp = rhalf[7:1];

    // 8-bit minisbox: 4 groups of 2 bits -> 1 bit each
    wire [7:0] sb  = {exp[7:6] ^ exp[5:4], exp[3:2] ^ exp[1:0],
                     exp[7:6] ^ exp[3:2], exp[5:4] ^ exp[1:0]};

    // P-permutation (truncated 32->8): swap nibbles and XOR columns
    wire [7:0] pperm = {sb[3:0] ^ sb[7:4], sb[7:4] ^ sb[3:0]};

    wire [7:0] rk = cd ^ sk;

    always @(posedge clk) pv <= 1'b1;

    always @(posedge clk) begin
        if (load) begin
            lhalf <= pt[7:4];
            rhalf <= pt[3:0];
            rc    <= 8'd0;
            cd    <= 8'h01;
            sk    <= 8'h01;
            armed <= 1'b1;
        end else if (ce) begin
            lhalf <= rhalf;
            rhalf <= lhalf ^ pperm ^ rk;
            rc    <= rc - 8'd1;
            cd    <= cd_next;
            sk    <= sk_next;
        end
    end

    always @(posedge clk)
        if (pv && armed && $fell(rc))
            assert (cd == sk);
endmodule

module keypad_scan64 (
    input  wire        clk,
    input  wire        ce,
    input  wire [3:0]  col_n,
    output wire [3:0]  row_n,
    output wire [63:0] o_key_code,
    output wire        o_key_pressed,
    output wire        o_busy
);
    localparam [63:0] ROWS     = 64'd15;
    localparam [63:0] COL_MASK = 64'hFFFF_FFFF_0000_0000;
    localparam [63:0] LAST   = 64'd15;
    localparam [63:0] DL_BASE  = 64'd16;

    reg [63:0] scan_idx  = 64'd0;
    reg [63:0] deadline  = 64'd0;
    reg [63:0] key_code  = 64'd0;
    reg        key_pressed = 1'b0;
    reg        busy      = 1'b0;

    wire [3:0] row_drv = ~scan_idx[3:0];
    assign row_n = row_drv;

    wire       any_press = ~(&col_n);
    wire [3:0] col_hit   = ~col_n;

    always @(posedge clk) begin
        if (ce) begin
            if (!busy) begin
                if (any_press) begin
                    busy      <= 1'b1;
                    scan_idx  <= 64'd0;
                    deadline  <= DL_BASE;
                    key_pressed <= 1'b0;
                end
            end else begin
                deadline <= deadline - 64'd1;
                if (scan_idx == LAST) begin
                    busy      <= 1'b0;
                    scan_idx  <= 64'd0;
                    key_pressed <= |(row_drv & col_hit);
                    if (key_pressed)
                        key_code <= {row_drv, col_hit};
                end else begin
                    scan_idx <= scan_idx + 64'd1;
                end
            end
        end
    end

    assign o_key_code      = key_code;
    assign o_key_pressed   = key_pressed;
    assign o_busy          = busy;

    always @(posedge clk)
        if (busy)
            assert (deadline != 64'd0);

    always @(posedge clk)
        if (busy)
            assert (scan_idx <= LAST);
endmodule

module field_prio_grant (
    input  wire         clk,
    input  wire         rst,
    input  wire         i_ce,
    input  wire [12*32-1:0] i_fields,
    input  wire         req_valid,
    output reg          rsp_valid,
    output reg  [31:0]  rsp_field,
    output reg  [31:0]  rsp_idx
);
    localparam [31:0] K = 32'd12;

    reg [31:0] timer;
    reg [31:0] idx;
    reg        busy;
    reg        armed;
    initial begin
        timer     = 32'd0;
        idx       = 32'd0;
        busy      = 1'b0;
        rsp_valid = 1'b0;
        armed     = 1'b0;
    end

    wire accept = !busy && req_valid;
    wire ack    = busy && (timer == 32'd2);
    wire [31:0] cur_base = idx * 32'd32;
    wire [31:0] cur_val  = i_fields[cur_base +: 32];

    always @(posedge clk) begin
        if (rst) begin
            timer     <= 32'd0;
            idx       <= 32'd0;
            busy      <= 1'b0;
            rsp_valid <= 1'b0;
        end else if (i_ce) begin
            if (accept) begin
                timer     <= K;
                rsp_valid <= 1'b0;
                busy      <= 1'b1;
                armed     <= 1'b1;
                idx       <= 32'd0;
            end else if (ack) begin
                timer     <= 32'd0;
                busy      <= 1'b0;
                rsp_valid <= 1'b1;
                rsp_idx   <= idx;
                rsp_field <= cur_val;
            end else if (busy) begin
                timer <= timer - 32'd1;
                if (cur_val == 32'd0) begin
                    if (idx == 32'd11) idx <= 32'd0;
                    else               idx <= idx + 32'd1;
                end
            end
        end
    end

    always @(*) assert (!armed || !busy || timer != 32'd0);
endmodule

module dl_bounded_resp (
    input  wire       clk,
    input  wire       rst,
    input  wire       ce,
    input  wire       req,
    input  wire [7:0] din,
    output wire [7:0] dout,
    output wire       busy_o,
    output wire       resp_o
);
    // 16-entry RAM delay line: write port at wr_addr, read port 12 entries behind
    reg [7:0] mem [0:15];
    integer i;
    initial begin
        for (i = 0; i < 16; i = i + 1) mem[i] = 8'd0;
    end

    reg [3:0] wr_addr  = 4'd0;
    reg [3:0] fill     = 4'd0;   // tokens consumed since the request opened
    reg [7:0] deadline = 8'd0;   // response countdown
    reg       busy     = 1'b0;   // window register: set by accept, cleared by response

    wire [3:0] rd_idx = wr_addr - 4'd12;
    assign dout   = mem[rd_idx];
    assign busy_o = busy;
    assign resp_o = busy && (deadline == 8'd0);

    always @(posedge clk) begin
        if (rst) begin
            wr_addr  <= 4'd0;
            fill     <= 4'd0;
            deadline <= 8'd0;
            busy     <= 1'b0;
        end else if (ce) begin
            mem[wr_addr] <= din;
            wr_addr <= wr_addr + 4'd1;
            if (!busy) begin
                if (req) begin
                    busy     <= 1'b1;
                    fill     <= 4'd0;
                    deadline <= 8'd16;
                end
            end else begin
                fill     <= fill + 4'd1;
                deadline <= deadline - 8'd1;
                if (fill == 4'd15) busy <= 1'b0;
            end
        end
    end

    // Bounded response: the countdown must never expire while the request
    // is still outstanding.
    always @(posedge clk)
        if (busy)
            assert (deadline != 8'd0);
endmodule

module bfx_load_unit (
    input  wire         clk,
    input  wire         i_ce,
    input  wire         i_load,
    input  wire         i_unlock,
    input  wire [127:0] i_src,
    input  wire [5:0]   i_offs,
    input  wire [5:0]   i_len,
    output reg  [127:0] field,
    output reg  [2:0]   n_loaded
);
    localparam [2:0] CAP = 3'd4;

    reg [127:0] src;
    reg [5:0]   offs;
    reg [5:0]   len;
    reg [2:0]   idx;
    reg         armed;

    initial begin
        src      = 128'd0;
        offs     = 6'd0;
        len      = 6'd0;
        field    = 128'd0;
        idx      = 3'd0;
        n_loaded = 3'd0;
        armed    = 1'b0;
    end

    wire [7:0] sh = offs + 64'd128 - len;
    wire [127:0] ext = (len >= 6'd128) ? src : ((src >> offs) << sh);
    wire [127:0] fill = (len >= 6'd128) ? src[127] : ext;

    always @(posedge clk) begin
        if (i_ce) begin
            if (i_load) begin
                src      <= i_src;
                offs     <= i_offs;
                len      <= i_len;
                field    <= fill;
                armed    <= 1'b1;
                if (idx < CAP) begin
                    idx      <= idx + 3'd1;
                    n_loaded <= n_loaded + 3'd1;
                end
            end else if (i_unlock) begin
                idx      <= 3'd0;
                n_loaded <= 3'd0;
            end
        end
    end

    always @(posedge clk)
        if (armed)
            assert (n_loaded <= 3'd4);
endmodule

module hilbert_xform (
    input  wire         clk,
    input  wire         ce,
    input  wire [127:0] x,
    output wire [127:0] i_out,
    output wire [127:0] q_out
);
    // 4-entry input delay line for the antisymmetric FIR
    reg [127:0] d0, d1, d2, d3;
    // matched delay aligning the in-phase path with the FIR centre tap (d1)
    reg [127:0] m0, m1;
    // shadow: sample that was newest at the previous strobe
    reg [127:0] prev_samp;
    // sticky scope register: set at first accepted sample, never cleared
    reg armed;

    initial begin
        d0 = 128'd0; d1 = 128'd0; d2 = 128'd0; d3 = 128'd0;
        m0 = 128'd0; m1 = 128'd0;
        prev_samp = 128'd0;
        armed = 1'b0;
    end

    always @(posedge clk) begin
        if (ce) begin
            d0 <= x;
            d1 <= d0;
            d2 <= d1;
            d3 <= d2;
            m0 <= x;
            m1 <= m0;
            prev_samp <= d0;
            armed <= 1'b1;
        end
    end

    // antisymmetric taps around centre position d1: h = {+1, +3, 0, -3, -1}
    wire [127:0] diff_inner = d0 - d2;
    wire [127:0] diff_outer = x - d3;
    assign q_out = (diff_inner + (diff_inner << 1)) + diff_outer;
    assign i_out = m1;

    // Precedence, after first sample: the in-phase output seen now must be
    // the sample recorded as newest at the previous strobe.
    assert property (!armed || (i_out == prev_samp));
endmodule
